insert into public.languages (id, code, name, native_name, writing_direction, tts_locale, is_available) values ('ar', 'ar', 'Arabe', 'العربية', 'rtl', 'ar-SA', true) on conflict (id) do update set name = excluded.name, native_name = excluded.native_name, writing_direction = excluded.writing_direction, tts_locale = excluded.tts_locale, is_available = excluded.is_available;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g01.alif_ba_ta_tha', 'ar', 'grammar', 'reading', 'Alif et les dents ب ت ث : les points font la différence', 1, '{}'::text[], 1, '{"rule": {"summary": "ب ت ث ont exactement le même corps : seuls les points changent (ب un point dessous, ت deux dessus, ث trois dessus). Alif ا s''attache à la lettre d''avant, jamais à celle d''après.", "explanation": "En arabe, une lettre change de forme selon sa place : isolée (ب), au début (بـ, attachée à gauche), au milieu (ـبـ, attachée des deux côtés) ou à la fin (ـب, attachée à droite). Pour ب ت ث, le corps est une cuvette quand la lettre est isolée ou finale, et une simple petite « dent » au début ou au milieu. Pour savoir laquelle tu lis, ne regarde que les points : un dessous = b, deux dessus = t, trois dessus = th (le th anglais de « think »). Alif ا est un trait vertical : il s''accroche à la lettre d''avant (ـا) mais jamais à la suivante, qui repart donc en forme de début ou isolée.", "pattern": "Isolée ب · début بـ · milieu ـبـ · fin ـب — ب : 1 point dessous, ت : 2 dessus, ث : 3 dessus ; ا ne s''attache jamais à gauche", "examples": [{"text": "بَاب", "translation": "la porte", "transliteration": "bâb"}, {"text": "كِتَاب", "translation": "le livre", "transliteration": "kitâb"}, {"text": "ثَوْب", "translation": "le vêtement", "transliteration": "thawb"}, {"text": "أَثَاث", "translation": "les meubles", "transliteration": "athâth"}], "commonErrors": [{"wrong": "كِتَاب lu « kibâb »", "right": "كِتَاب = kitâb", "why": "La dent du milieu porte deux points au-dessus : c''est ت (t). ب n''a qu''un point, et il est en dessous."}, {"wrong": "ثَوْب lu « tawb »", "right": "ثَوْب = thawb", "why": "Trois points au-dessus, c''est ث : le th anglais de « think ». ت n''en a que deux."}, {"wrong": "Chercher un ب attaché (ـب) à la fin de بَاب", "right": "بَاب finit par un ب isolé (ب)", "why": "ا ne s''attache jamais à la lettre qui le suit : après lui, la lettre repart seule."}], "tip": "Ne regarde pas le corps de la lettre, compte les points : 1 dessous (ب), 2 dessus (ت), 3 dessus (ث)."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g02.nun_ya_five_teeth', 'ar', 'grammar', 'reading', 'ن et ي : les cinq dents, des points à compter', 1, array['ar.g01.alif_ba_ta_tha']::text[], 1, '{"rule": {"summary": "ب ت ث ن ي forment la famille des « dents » : au début et au milieu, elles ont exactement le même corps. Seuls les points changent : ب 1 dessous, ت 2 dessus, ث 3 dessus, ن 1 dessus, ي 2 dessous.", "explanation": "Au début (بـ تـ ثـ نـ يـ) et au milieu (ـبـ ـتـ ـثـ ـنـ ـيـ), ces cinq lettres sont une petite dent identique : impossible de les reconnaître autrement que par leurs points. Pose-toi toujours deux questions dans cet ordre : combien de points ? au-dessus ou en dessous ? À la fin et isolées, ب ت ث ن sont une cuvette (ـب ـت ـث ـن) et ي se termine par une longue queue qui revient vers la gauche (ـي, ي). ن se prononce n comme dans « nuit » ; ي est le y de « yaourt » ou un î long, comme dans تِين.", "pattern": "ب : 1 point dessous · ت : 2 dessus · ث : 3 dessus · ن : 1 dessus · ي : 2 dessous", "examples": [{"text": "تِين", "translation": "les figues", "transliteration": "tîn"}, {"text": "بَنَات", "translation": "les filles", "transliteration": "banât"}, {"text": "نَبَات", "translation": "la plante", "transliteration": "nabât"}, {"text": "بَيْنَ", "translation": "entre", "transliteration": "bayna"}], "commonErrors": [{"wrong": "نَبَات lu « babât »", "right": "نَبَات = nabât", "why": "Le point de la première lettre est au-dessus de la dent : c''est ن (n). ب a son point en dessous."}, {"wrong": "بَيْنَ lu « batna »", "right": "بَيْنَ = bayna", "why": "La deuxième lettre a deux points en dessous : c''est ي (y). ت aussi a deux points, mais au-dessus."}, {"wrong": "تِين lu « yîn »", "right": "تِين = tîn", "why": "Les deux points de la première lettre sont au-dessus : c''est ت (t). Pour ي, ils seraient en dessous."}], "tip": "Deux questions, toujours dans cet ordre : combien de points ? au-dessus ou en dessous ?"}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g03.djim_ha_kha', 'ar', 'grammar', 'reading', 'ج ح خ : un crochet, trois lettres, un point à repérer', 2, array['ar.g02.nun_ya_five_teeth']::text[], 1, '{"rule": {"summary": "ج ح خ ont la même silhouette en crochet. Seul le point change : ج a un point dans la courbe (dessous), ح n''en a aucun, خ a un point au-dessus.", "explanation": "Ces trois lettres se ressemblent comme des sœurs. Au début et au milieu (جـ حـ خـ, ـجـ ـحـ ـخـ), elles se réduisent à une petite tête ; isolées ou à la fin (ج ح خ, ـج ـح ـخ), le crochet est complet, avec une courbe qui s''enroule sous la ligne. Dans tous les cas, regarde le point : sous la tête = ج (dj, comme dans « jazz » ; en Égypte on dit g), aucun point = ح (un h soufflé du fond de la gorge, noté 7), point au-dessus = خ (kh, comme le j espagnol de « jota » ou le ch allemand de « Bach »). Rappelle-toi aussi que ces lettres s''attachent des deux côtés, mais qu''après un ا la lettre repart seule : dans تَاج, le ج est isolé.", "pattern": "ج : 1 point dans la courbe · ح : aucun point · خ : 1 point au-dessus", "examples": [{"text": "حَبِيب", "translation": "le chéri", "transliteration": "7abîb"}, {"text": "تَاج", "translation": "la couronne", "transliteration": "tâdj"}, {"text": "خَاتَم", "translation": "la bague", "transliteration": "khâtam"}, {"text": "جَزَر", "translation": "les carottes", "transliteration": "djazar"}], "commonErrors": [{"wrong": "تَحْتَ lu « takhta »", "right": "تَحْتَ = ta7ta", "why": "La lettre du milieu n''a aucun point : c''est ح (h soufflé, noté 7). Avec un point dessus, ce serait خ."}, {"wrong": "جَزَر lu « 7azar »", "right": "جَزَر = djazar", "why": "Il y a un point à l''intérieur de la courbe, sous la tête : c''est ج. Sans point, ce serait ح."}, {"wrong": "خَاتَم lu « djâtam »", "right": "خَاتَم = khâtam", "why": "Le point est au-dessus : c''est خ (kh). ج a son point en dessous, dans la courbe."}], "tip": "Même crochet, trois cas : point dedans = dj, rien = 7, point dessus = kh."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g04.non_connecting_letters', 'ar', 'grammar', 'reading', 'ا د ذ ر ز و : les six lettres qui coupent le mot', 2, array['ar.g01.alif_ba_ta_tha']::text[], 1, '{"rule": {"summary": "ا د ذ ر ز و s''attachent à la lettre d''avant mais jamais à celle d''après. Après elles, le mot est « coupé » : la lettre suivante repart avec sa forme de début (ou isolée).", "explanation": "Ces six lettres n''ont que deux formes : isolée (د ذ ر ز و ا) et finale (ـد ـذ ـر ـز ـو ـا), qui ne diffère de l''isolée que par le trait qui les relie à la lettre d''avant. Elles n''ont ni forme de début attachée, ni forme du milieu. Conséquence : un mot qui en contient est découpé en blocs de lettres attachées, séparés par de petits espaces. Dans دَجَاج, il y a trois blocs : د | جا | ج. Dans لَذِيذ, deux : لذ | يذ. Attention à la lettre qui suit une coupure : elle prend sa forme de début, pas sa forme du milieu. Les couples د / ذ et ر / ز ne se distinguent que par un point au-dessus (ذ et ز en portent un).", "pattern": "ا د ذ ر ز و : attachées à gauche → jamais · la lettre d''après repart en forme de début · د ≠ ذ et ر ≠ ز : un point dessus", "examples": [{"text": "دَار", "translation": "la demeure", "transliteration": "dâr"}, {"text": "زَيْت", "translation": "l''huile", "transliteration": "zayt"}, {"text": "دَجَاج", "translation": "le poulet", "transliteration": "dadjâdj"}, {"text": "لَذِيذ", "translation": "délicieux", "transliteration": "ladhîdh"}], "commonErrors": [{"wrong": "دَار écrit avec les trois lettres reliées", "right": "دَار = د ا ر, trois lettres séparées", "why": "د ne s''attache pas à ا, et ا ne s''attache pas à ر : aucune liaison dans ce mot."}, {"wrong": "Le ي de زَيْت lu comme une forme finale ou isolée", "right": "Le ي de زَيْت est en forme de début (يـ)", "why": "ز coupe le mot : ي repart donc avec sa forme de début, puis s''attache à ت."}, {"wrong": "ر lu z, ou د lu dh", "right": "ر = r (sans point), ز = z (un point) ; د = d (sans point), ذ = dh (un point)", "why": "Le point dessus est le seul indice : sans point, c''est ر ou د ; avec un point, c''est ز ou ذ."}], "tip": "Six lettres coupeuses : ا د ذ ر ز و. Après elles, repars à zéro avec la forme de début."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g05.sin_chin_sad_dad', 'ar', 'grammar', 'reading', 'س ش ص ض : la scie et la boucle', 2, array['ar.g02.nun_ya_five_teeth']::text[], 1, '{"rule": {"summary": "س ش ont une « scie » de trois petites dents ; ص ض ont une boucle ronde. Dans chaque paire, seuls les points changent : ش = س + 3 points dessus, ض = ص + 1 point dessus.", "explanation": "Au début et au milieu, س et ش dessinent une petite scie à trois pointes (سـ ـسـ, شـ ـشـ) et ص et ض une boucle fermée (صـ ـصـ, ضـ ـضـ). Isolées ou à la fin, elles se terminent par une grande courbe avec une queue (س ش ص ض, ـس ـش ـص ـض). Les sons : س = s comme dans « sac » (toujours dur) ; ش = ch comme dans « chat » ; ص = un s « lourd » (la langue plaquée contre le palais, la bouche plus ronde), noté S ; ض = un d « lourd », noté D. Attention à ne pas confondre ث (trois points sur une seule dent) et ش (trois points sur trois dents).", "pattern": "س : scie, 0 point · ش : scie + 3 points · ص : boucle · ض : boucle + 1 point dessus", "examples": [{"text": "سَرِير", "translation": "le lit", "transliteration": "sarîr"}, {"text": "شَوْكَة", "translation": "la fourchette", "transliteration": "chawka"}, {"text": "صَحْن", "translation": "l''assiette", "transliteration": "Sa7n"}, {"text": "ضَيْف", "translation": "l''invité", "transliteration": "Dayf"}], "commonErrors": [{"wrong": "شَوْكَة lu « thawka »", "right": "شَوْكَة = chawka", "why": "Les trois points sont posés sur une scie à trois dents : c''est ش (ch). ث aurait ses trois points sur une seule dent."}, {"wrong": "صَحْن lu comme avec un س léger", "right": "صَحْن = Sa7n, avec un s « lourd »", "why": "Une boucle ronde, c''est ص : un s plus profond et plus appuyé que س, qui est une scie."}, {"wrong": "ضَيْف lu « Sayf »", "right": "ضَيْف = Dayf", "why": "Il y a un point au-dessus de la boucle : c''est ض (D). Sans point, صَيْف (Sayf) veut dire « l''été »."}], "tip": "Scie ou boucle ? Puis compte les points : zéro ou trois pour la scie, zéro ou un pour la boucle."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g06.ta_za_ayn_ghayn', 'ar', 'grammar', 'reading', 'ط ظ ع غ : la boucle à bâton et la tête d''œil', 3, array['ar.g05.sin_chin_sad_dad']::text[], 1, '{"rule": {"summary": "ط ظ : une boucle fermée surmontée d''un bâton vertical ; ظ = ط + un point dessus. ع غ : une tête en forme d''œil ; غ = ع + un point dessus. Forme d''abord, point ensuite.", "explanation": "ط et ظ ressemblent à ص et ض, avec un détail qui change tout : un bâton vertical qui monte au-dessus de la boucle (طـ ـطـ, ظـ ـظـ). Sans bâton, c''est ص ou ض ; avec le bâton, c''est ط ou ظ. Ce sont des sons « lourds » : ط = T (un t plus profond que ت) et ظ = Z (un dh lourd ; en Égypte, on entend plutôt un z lourd). ع et غ sont deux lettres de la gorge : au début et au milieu, une petite tête triangulaire (عـ ـعـ, غـ ـغـ), à la fin ou isolées, une tête avec une queue (ع ـع, غ ـغ). ع (3) n''existe pas en français : c''est un son créé en serrant la gorge, comme un « a » qu''on pousse du fond du larynx. غ (gh) ressemble au r grasseyé français, celui de « rue ».", "pattern": "ط : boucle + bâton · ظ : boucle + bâton + 1 point dessus · ع : tête, 0 point · غ : tête + 1 point dessus", "examples": [{"text": "طَعَام", "translation": "la nourriture", "transliteration": "Ta3âm"}, {"text": "عَسَل", "translation": "le miel", "transliteration": "3asal"}, {"text": "غُرْفَة", "translation": "la chambre", "transliteration": "ghurfa"}, {"text": "نَظِيف", "translation": "propre", "transliteration": "naZîf"}], "commonErrors": [{"wrong": "طَعَام lu « Sa3âm »", "right": "طَعَام = Ta3âm", "why": "Le bâton vertical distingue ط de ص : sans bâton, la boucle est un ص. Ici, il y a un bâton : c''est ط (T)."}, {"wrong": "غُرْفَة lu « 3urfa »", "right": "غُرْفَة = ghurfa", "why": "La tête porte un point au-dessus : c''est غ (gh). Sans point, ce serait ع (3)."}, {"wrong": "نَظِيف lu « naTîf »", "right": "نَظِيف = naZîf", "why": "Il y a un point au-dessus du bâton : c''est ظ (Z). ط n''a aucun point."}], "tip": "Bâton ? Alors ط ou ظ. Tête d''œil ? Alors ع ou غ. Un point dessus : ظ ou غ."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g07.fa_qaf_kaf_lam_mim_ha', 'ar', 'grammar', 'reading', 'ف ق ك ل م ه : six lettres fréquentes, ه aux quatre visages', 3, array['ar.g05.sin_chin_sad_dad']::text[], 1, '{"rule": {"summary": "ف et ق ont la même tête ronde : un point pour ف, deux pour ق. ك porte un petit zigzag, ل est un trait vertical simple, م une petite boule. ه a quatre formes presque sans rapport entre elles : il faut les apprendre toutes.", "explanation": "ف et ق partagent la même petite tête (فـ ـفـ, قـ ـقـ) : compte les points au-dessus, un seul pour ف (f), deux pour ق (q). À la fin ou isolée, la tête est suivie d''une courte queue pour ف, d''une longue queue qui plonge sous la ligne pour ق. ق est un k prononcé tout au fond de la gorge ; en Égypte, on l''entend souvent comme une petite coupure de gorge. ك (k) et ل (l) se confondent facilement : ك contient un petit zigzag, ل est un trait vertical tout simple (qui s''attache à la lettre suivante, contrairement à ا). م (m) est une boule qui descend en queue à la fin. Enfin ه (h léger, un souffle comme dans l''anglais « hello ») change complètement d''allure : isolée ه, début هـ, milieu ـهـ, fin ـه.", "pattern": "ف : tête + 1 point · ق : tête + 2 points · ك : zigzag · ل : trait simple · م : boule · ه / هـ / ـهـ / ـه", "examples": [{"text": "قَلَم", "translation": "le stylo", "transliteration": "qalam"}, {"text": "كُوب", "translation": "le verre", "transliteration": "kûb"}, {"text": "هَاتِف", "translation": "le téléphone", "transliteration": "hâtif"}, {"text": "مِفْتَاح", "translation": "la clé", "transliteration": "miftâ7"}], "commonErrors": [{"wrong": "قَلَم lu « falam »", "right": "قَلَم = qalam", "why": "La tête porte deux points au-dessus : c''est ق (q), pas ف qui n''en a qu''un."}, {"wrong": "كُوب lu « lûb »", "right": "كُوب = kûb", "why": "ك contient un petit zigzag ; ل est un trait vertical tout simple, sans rien à l''intérieur."}, {"wrong": "Chercher dans هَاتِف le dessin de ه qu''on a vu à la fin d''un mot", "right": "ه change de forme : هـ au début, ـه à la fin", "why": "ه est la lettre qui change le plus selon sa place : il faut apprendre ه, هـ, ـهـ et ـه comme quatre dessins différents."}], "tip": "Tête ronde : compte les points (1 = f, 2 = q). Trait haut : zigzag = k, trait nu = l."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g08.ta_marbuta_maqsura_hamza_lam_alif', 'ar', 'grammar', 'reading', 'ة ى ء لا : les derniers signes de l''alphabet', 3, array['ar.g07.fa_qaf_kaf_lam_mim_ha']::text[], 1, '{"rule": {"summary": "Quatre signes complètent l''alphabet : ة (fin de mot, se lit a), ى (fin de mot, se lit â), ء (la hamza, coupure de gorge) et la ligature لا, obligatoire quand ل est suivi de ا.", "explanation": "ة est un ه surmonté de deux points : on la trouve uniquement à la fin d''un mot, le plus souvent un féminin, et elle se lit a (مَكْتَبَة, maktaba). ى ressemble à un ي sans aucun point : à la fin de certains mots, elle se lit â (مَقْهَى, maqhâ). ء, la hamza, est une brève coupure de la gorge, comme dans « sama'' » ; elle peut se tenir seule sur la ligne (سَمَاء) ou sur un support (أ إ ؤ ئ), détaillé au module 2. Enfin ل suivi de ا ne s''écrit jamais en deux signes : on les fond en une ligature لا (سَلَام). Avec ces quatre signes, tu as fait le tour de l''alphabet : 28 lettres et leurs quatre formes.", "pattern": "ـة : fin de mot, a · ى : fin de mot, â · ء : coupure de gorge · لا : ligature obligatoire", "examples": [{"text": "مَكْتَبَة", "translation": "la bibliothèque", "transliteration": "maktaba"}, {"text": "مَقْهَى", "translation": "le café", "transliteration": "maqhâ"}, {"text": "سَمَاء", "translation": "le ciel", "transliteration": "samâ''"}, {"text": "سَلَام", "translation": "la paix", "transliteration": "salâm"}], "commonErrors": [{"wrong": "مَكْتَبَة lu « maktab »", "right": "مَكْتَبَة = maktaba", "why": "Le ة final se lit a : ne l''oublie pas. مَكْتَب (maktab) sans ة est le bureau, مَكْتَبَة (maktaba) la bibliothèque."}, {"wrong": "مَقْهَى lu « maqhî »", "right": "مَقْهَى = maqhâ", "why": "ى n''a aucun point : c''est alif maqSûra, qui se lit â. ي, avec ses deux points dessous, se lirait î."}, {"wrong": "سَلَام écrit avec ل et ا séparés", "right": "سَلَام = سـ + لا + م", "why": "ل suivi de ا s''écrit toujours en ligature لا : deux traits croisés."}], "tip": "Fin de mot : deux points sur la boucle = a (ة) ; queue sans point = â (ى)."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g09.short_vowels', 'ar', 'grammar', 'reading', 'Les voyelles brèves : fatha, kasra, damma', 1, '{}'::text[], 2, '{"rule": {"summary": "Trois petits signes donnent la voyelle brève d''une lettre : la fatha (ـَ) au-dessus = a, la kasra (ـِ) en dessous = i, la damma (ـُ) au-dessus = u.", "explanation": "En arabe, on écrit surtout les consonnes ; les voyelles brèves sont de petits signes (les harakat) posés sur ou sous la lettre. La fatha est un petit trait oblique au-dessus : بَ = ba. La kasra est le même trait, mais en dessous : بِ = bi. La damma ressemble à un petit و au-dessus : بُ = bu, qui se prononce « bou » (on l''écrit u). On lit toujours la consonne puis sa voyelle, syllabe par syllabe : كَتَبَ = ka-ta-ba. Dans les fiches de mots, la dernière lettre reste souvent sans signe : on la lit sans voyelle (وَلَد = walad).", "pattern": "consonne + signe = syllabe : بَ ba · بِ bi · بُ bu", "examples": [{"text": "كَتَبَ", "translation": "il a écrit", "transliteration": "kataba"}, {"text": "وَلَد", "translation": "garçon", "transliteration": "walad"}, {"text": "رَجُل", "translation": "homme", "transliteration": "radjul"}, {"text": "كُتِبَ", "translation": "il a été écrit", "transliteration": "kutiba"}], "commonErrors": [{"wrong": "بِ lu « ba »", "right": "بِ = bi", "why": "Le trait est sous la lettre : c''est une kasra, donc i. La fatha, elle, est au-dessus."}, {"wrong": "بُ lu « bo »", "right": "بُ = bu (« bou »)", "why": "La damma donne toujours le son « ou », jamais « o » : رَجُل se lit radjul."}, {"wrong": "كَتَبَ lu « katab »", "right": "كَتَبَ = kataba", "why": "Chaque lettre qui porte une voyelle se prononce avec elle, la dernière aussi : ka-ta-ba."}], "tip": "Trait au-dessus = a, trait en dessous = i, petit و au-dessus = u."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g10.sukun', 'ar', 'grammar', 'reading', 'Le sukun et les syllabes fermées', 1, array['ar.g09.short_vowels']::text[], 2, '{"rule": {"summary": "Le sukun (ـْ), petit rond au-dessus d''une lettre, indique que cette consonne n''a pas de voyelle : elle ferme la syllabe.", "explanation": "Une lettre avec sukun se prononce seule, sans voyelle, et s''accroche à la syllabe d''avant : بِنْت = bin-t, قَلْب = qal-b. On lit donc par syllabes fermées (consonne + voyelle + consonne) : كَتَبْتُ = ka-tab-tu. Le sukun est un petit rond fermé ; la damma a une petite queue, comme un mini و : ne les confonds pas. Un mot ne commence jamais par une lettre avec sukun. En fin de mot isolé (à la pause), on ne prononce pas la dernière voyelle : c''est pour cela que les fiches écrivent la dernière lettre sans signe.", "pattern": "consonne + voyelle + consonne avec ـْ = syllabe fermée : قَلْ = qal", "examples": [{"text": "بِنْت", "translation": "fille", "transliteration": "bint"}, {"text": "قَلْب", "translation": "cœur", "transliteration": "qalb"}, {"text": "كَتَبْتُ", "translation": "j''ai écrit", "transliteration": "katabtu"}, {"text": "طِفْل", "translation": "enfant", "transliteration": "Tifl"}], "commonErrors": [{"wrong": "قَلْب lu « qalab »", "right": "قَلْب = qalb", "why": "Le ل porte un sukun : on n''ajoute aucune voyelle après lui."}, {"wrong": "كَتَبْتُ lu « katabutu »", "right": "كَتَبْتُ = katabtu", "why": "Le ب porte un sukun : il se colle à la syllabe d''avant (ka-tab-tu), sans voyelle."}, {"wrong": "Confondre ـْ (sukun) et ـُ (damma)", "right": "ـْ = pas de voyelle ; ـُ = u", "why": "Le sukun est un petit rond fermé ; la damma a une queue comme un petit و."}], "tip": "Petit rond = rien : la consonne s''arrête net."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g11.long_vowels', 'ar', 'grammar', 'reading', 'Les voyelles longues (madd) et les diphtongues', 2, array['ar.g09.short_vowels','ar.g10.sukun']::text[], 2, '{"rule": {"summary": "Une voyelle brève suivie de sa lettre de prolongement devient longue : ـَا = â, ـِي = î, ـُو = û (c''est le madd).", "explanation": "Les lettres ا, و et ي servent aussi à allonger la voyelle qui précède : بَا = bâ, بِي = bî, بُو = bû. On tient le son deux fois plus longtemps ; en translittération, on le marque d''un accent circonflexe (kitâb). Les couples vont toujours ensemble : fatha + ا, kasra + ي, damma + و. Piège : si و ou ي porte un sukun après une fatha, ce n''est pas une voyelle longue mais une diphtongue : عَيْن = 3ayn, زَوْج = zawdj. Et si و ou ي porte une voyelle, c''est une consonne : وَلَد = walad. Dans quelques mots très courants, le â s''écrit avec un petit alif posé au-dessus de la lettre : هٰذَا = hâdhâ.", "pattern": "ـَا = â · ـِي = î · ـُو = û   mais   ـَيْ = ay · ـَوْ = aw", "examples": [{"text": "كِتَاب", "translation": "livre", "transliteration": "kitâb"}, {"text": "صَدِيق", "translation": "ami", "transliteration": "Sadîq"}, {"text": "عَجُوز", "translation": "personne âgée", "transliteration": "3adjûz"}, {"text": "عَيْن", "translation": "œil", "transliteration": "3ayn"}], "commonErrors": [{"wrong": "عَيْن lu « 3în »", "right": "عَيْن = 3ayn", "why": "Le ي porte un sukun après une fatha : c''est la diphtongue ay. Un î long s''écrirait kasra + ي (ـِي)."}, {"wrong": "كَتَبَ lu « kâtaba »", "right": "كَتَبَ = kataba", "why": "Il n''y a pas de ا après le ك : la voyelle reste brève. Seule une lettre de prolongement allonge le son."}, {"wrong": "صَدِيق lu « Sadiq », i bref", "right": "صَدِيق = Sadîq", "why": "Kasra + ي = î long : on tient le son. La longueur distingue beaucoup de mots."}], "tip": "Fatha + ا, kasra + ي, damma + و : la voyelle s''étire."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g12.shadda', 'ar', 'grammar', 'reading', 'La shadda : la lettre doublée', 2, array['ar.g10.sukun']::text[], 2, '{"rule": {"summary": "La shadda (ـّ), petit « w » posé sur une lettre, double la consonne : on la prononce deux fois.", "explanation": "Une lettre avec shadda vaut deux lettres : la première sans voyelle (elle ferme la syllabe), la seconde avec la voyelle (elle ouvre la suivante) : جَدَّة = djad-da, مُعَلِّم = mu-3al-lim. On appuie sur la consonne, comme dans l''italien « nonno ». La voyelle accompagne la shadda : fatha et damma au-dessus de la shadda (ـَّ ـُّ), kasra sous la lettre ou juste sous la shadda (ـِّ). La shadda change le sens : دَرَسَ (darasa, il a étudié) n''est pas دَرَّسَ (darrasa, il a enseigné).", "pattern": "ـّ = consonne doublée : جَدّ = djadd · مُعَلِّم = mu3allim", "examples": [{"text": "جَدّ", "translation": "grand-père", "transliteration": "djadd"}, {"text": "جَدَّة", "translation": "grand-mère", "transliteration": "djadda"}, {"text": "مُعَلِّم", "translation": "enseignant", "transliteration": "mu3allim"}, {"text": "دَرَّسَ", "translation": "il a enseigné", "transliteration": "darrasa"}], "commonErrors": [{"wrong": "جَدَّة lu « djada »", "right": "جَدَّة = djadda", "why": "La shadda double le د : djad-da. Sans elle, le mot est trop court."}, {"wrong": "مُعَلِّم lu « mu3allam »", "right": "مُعَلِّم = mu3allim", "why": "Le petit trait sous la shadda est une kasra : on lit lli, avec le ل doublé."}, {"wrong": "Lire la shadda comme un son « w »", "right": "ـّ = consonne doublée", "why": "La shadda ressemble à un petit w mais ne se prononce pas : elle double seulement la lettre."}], "tip": "Shadda = on dit la lettre deux fois : djad-da."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g13.tanwin', 'ar', 'grammar', 'reading', 'Le tanwin : -an, -in, -un', 2, array['ar.g09.short_vowels']::text[], 2, '{"rule": {"summary": "Le tanwin, c''est la voyelle finale écrite en double (ـٌ ـٍ ـً) : elle ajoute un son n à la fin du mot : -un, -in, -an.", "explanation": "On le trouve à la fin des noms et adjectifs indéfinis (« un livre ») : كِتَابٌ = kitâbun, كِتَابٍ = kitâbin, كِتَابًا = kitâban. Ce n s''entend mais ne s''écrit pas avec un ن. Le tanwin -an s''accompagne d''un alif muet (كِتَابًا), sauf après ة ou ـَاء (طَالِبَةً = Tâlibatan). Avec ة, le tanwin fait entendre le t : طَالِبَةٌ = Tâlibatun. Le tanwin disparaît dès que le mot prend l''article ال : الطَّالِبُ = aT-Tâlibu.", "pattern": "ـٌ = -un · ـٍ = -in · ـً (+ ا muet) = -an", "examples": [{"text": "طَالِبٌ", "translation": "un étudiant", "transliteration": "Tâlibun"}, {"text": "هِيَ طَالِبَةٌ", "translation": "Elle est étudiante.", "transliteration": "hiya Tâlibatun"}, {"text": "رَأَيْتُ طَبِيبًا", "translation": "J''ai vu un médecin.", "transliteration": "ra''aytu Tabîban"}, {"text": "مَعَ طَبِيبٍ", "translation": "avec un médecin", "transliteration": "ma3a Tabîbin"}], "commonErrors": [{"wrong": "كِتَابًا lu « kitâbanâ »", "right": "كِتَابًا = kitâban", "why": "L''alif après le tanwin -an est muet : il sert seulement de support."}, {"wrong": "طَالِبٌ lu « Tâlibu »", "right": "طَالِبٌ = Tâlibun", "why": "Deux dammas (ou une damma avec une queue) = tanwin : on ajoute le son n."}, {"wrong": "الْكِتَابٌ", "right": "الْكِتَابُ", "why": "L''article et le tanwin ne vont jamais ensemble : avec ال, la voyelle finale est simple."}], "tip": "Signe doublé = voyelle + n."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g14.hamza_madda', 'ar', 'grammar', 'reading', 'La hamza, ses supports et le alif madda', 3, array['ar.g11.long_vowels']::text[], 2, '{"rule": {"summary": "La hamza (ء) est un petit coup de glotte, comme la coupure dans « oh ! oh ! ». Elle s''écrit seule ou sur un support (أ إ ؤ ئ) ; le alif madda آ se lit ''â.", "explanation": "La hamza est une vraie consonne : on la note '' en translittération (سُؤَال = su''âl). Son support (ا, و, ou ي sans points) ne se prononce pas : lis seulement la hamza et sa voyelle. En début de mot, elle est sur l''alif : أَ = a, أُ = u, et إِ = i (hamza et kasra sous l''alif) ; on entend surtout la voyelle : أَب = ab, أُمّ = umm. Au milieu, le support suit la voyelle la plus forte : ؤ près d''un u, ئ près d''un i, أ près d''un a. Après un â long ou en fin de mot, elle reste souvent seule : نِسَاء = nisâ''. Le alif madda آ remplace « أَا » : آبَاء = âbâ''.", "pattern": "أَ a · أُ u · إِ i · ؤ ئ ء = '' · آ = ''â", "examples": [{"text": "أَب", "translation": "père", "transliteration": "ab"}, {"text": "سُؤَال", "translation": "question", "transliteration": "su''âl"}, {"text": "عَائِلَة", "translation": "famille", "transliteration": "3â''ila"}, {"text": "آبَاء", "translation": "pères, parents", "transliteration": "âbâ''"}], "commonErrors": [{"wrong": "سُؤَال lu « suwâl »", "right": "سُؤَال = su''âl", "why": "Le و ne sert que de support à la hamza : on ne prononce pas w mais un petit coup de glotte."}, {"wrong": "عَائِلَة lu « 3âyila »", "right": "عَائِلَة = 3â''ila", "why": "ئ (sans points) est une hamza sur un support, pas un ي : on lit 3â''ila."}, {"wrong": "آ lu comme un a bref", "right": "آ = ''â (long)", "why": "La madda indique une hamza suivie d''un â long : آبَاء = âbâ''."}], "tip": "Le support se tait : lis seulement la hamza et sa voyelle."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g15.article_sun_moon', 'ar', 'grammar', 'reading', 'L''article ال : lettres solaires et lunaires', 3, array['ar.g12.shadda','ar.g10.sukun']::text[], 2, '{"rule": {"summary": "L''article ال (al-, « le, la, les ») se colle au nom. Devant une lettre lunaire, on prononce le l ; devant une lettre solaire, le l disparaît et la lettre suivante est doublée.", "explanation": "Les 14 lettres solaires sont ت ث د ذ ر ز س ش ص ض ط ظ ل ن (on les prononce avec le bout de la langue). Devant elles, le ل s''écrit mais ne se prononce pas, et la lettre suivante porte une shadda : الشَّمْس = ach-chams. Les 14 autres lettres sont lunaires : le ل porte un sukun et se prononce : الْقَمَر = al-qamar. Dans un texte vocalisé, c''est donc facile : ل avec sukun → on dit l ; ل sans signe + shadda sur la lettre suivante → on ne dit pas l. Au milieu d''une phrase, le a de al- tombe après une voyelle : فِي الْبَيْتِ = fî l-bayti.", "pattern": "lunaire : الْ + lettre = al- · solaire : ال + lettre avec ـّ = a + lettre doublée", "examples": [{"text": "الشَّمْس", "translation": "le soleil", "transliteration": "ach-chams"}, {"text": "الْقَمَر", "translation": "la lune", "transliteration": "al-qamar"}, {"text": "الدَّم", "translation": "le sang", "transliteration": "ad-dam"}, {"text": "الْأُسْرَة", "translation": "la famille", "transliteration": "al-usra"}], "commonErrors": [{"wrong": "الشَّمْس lu « al-chams »", "right": "الشَّمْس = ach-chams", "why": "ش est une lettre solaire : le l ne se prononce pas et on double le ch."}, {"wrong": "الْقَمَر lu « aq-qamar »", "right": "الْقَمَر = al-qamar", "why": "ق est une lettre lunaire : le ل porte un sukun et se prononce."}, {"wrong": "الْوَلَد lu « aw-walad »", "right": "الْوَلَد = al-walad", "why": "و est lunaire : on garde le l. Repère : s''il y a un sukun sur le ل, on dit l."}], "tip": "Le soleil cache le l, la lune le laisse voir."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g16.reading_unvowelled', 'ar', 'grammar', 'reading', 'Lire sans voyelles', 4, array['ar.g11.long_vowels','ar.g15.article_sun_moon']::text[], 2, '{"rule": {"summary": "Les textes courants (journaux, panneaux, livres, messages) n''écrivent pas les voyelles brèves : on les devine grâce aux mots connus, aux lettres longues ا و ي et au sens.", "explanation": "Seules les lettres sont écrites : كتب peut se lire kataba (il a écrit), kutiba (il a été écrit) ou kutub (des livres). Les voyelles longues restent visibles, ce sont tes points d''appui : كتاب = kitâb. Le ة final signale souvent un nom féminin (طالبة = Tâliba) et ال au début, l''article (البيت = al-bayt). Les mots très courants se reconnaissent d''un coup d''œil, comme une image : ولد = walad, بنت = bint, هذا = hâdhâ. Quand plusieurs lectures sont possibles, c''est la phrase qui choisit.", "pattern": "Repères : ا و ي = voyelles longues · ال = article · ة = féminin · le sens choisit", "examples": [{"text": "ولد", "translation": "garçon", "transliteration": "walad"}, {"text": "بنت", "translation": "fille", "transliteration": "bint"}, {"text": "كتاب", "translation": "livre", "transliteration": "kitâb"}, {"text": "هذا", "translation": "ceci, c''est", "transliteration": "hâdhâ"}], "commonErrors": [{"wrong": "كتاب lu « kataba »", "right": "كتاب = kitâb", "why": "Le ا entre ت et ب est une voyelle longue : le verbe kataba s''écrit sans ا (كتب)."}, {"wrong": "بيت lu « bît »", "right": "بيت = bayt", "why": "Dans ce mot courant, le ي est une diphtongue (ay). Mémorise les mots fréquents comme des images."}, {"wrong": "هذا lu « hadhâ »", "right": "هذا = hâdhâ", "why": "Mot très courant : un â s''entend après le ه sans être écrit (petit alif dans le texte vocalisé هٰذَا)."}], "tip": "Repère d''abord les ا و ي et l''article, puis laisse le sens choisir."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g17.open_closed_syllables', 'ar', 'grammar', 'reading', 'Syllabes ouvertes et fermées', 2, '{}'::text[], 3, '{"rule": {"summary": "Un mot arabe se lit syllabe par syllabe : une syllabe ouverte finit par une voyelle (ka, kâ), une syllabe fermée finit par une consonne avec soukoun (kat, min).", "explanation": "Chaque syllabe commence par une consonne suivie d''une voyelle. Si elle s''arrête sur cette voyelle, brève ou longue, elle est ouverte : قَ (qa), فِي (fî). Si une consonne avec soukoun (ـْ) suit la voyelle, elle est fermée : مِنْ (min), مَدْ (mad). Pour lire vite, coupe le mot juste avant chaque consonne qui porte une voyelle : مَدْرَسَة = mad-ra-sa. Un mot lu seul s''arrête sur une consonne : on ne prononce pas la voyelle de la dernière lettre, donc la dernière syllabe est souvent fermée (قَمَر = qa-mar). Une lettre avec chadda (ـّ) compte double : elle ferme une syllabe et ouvre la suivante.", "pattern": "Ouverte = consonne + voyelle (ka, kâ) · Fermée = consonne + voyelle + consonne avec soukoun (kat)", "examples": [{"text": "قَمَر", "translation": "la lune : qa (ouverte) + mar (fermée)", "transliteration": "qa-mar"}, {"text": "مَدْرَسَة", "translation": "l''école : mad (fermée) + ra + sa (ouvertes)", "transliteration": "mad-ra-sa"}, {"text": "شَجَرَة", "translation": "l''arbre : 3 syllabes ouvertes, cha + dja + ra", "transliteration": "cha-dja-ra"}, {"text": "مِنْ", "translation": "de : une seule syllabe fermée", "transliteration": "min"}], "commonErrors": [{"wrong": "مَدْرَسَة = ma-dra-sa", "right": "mad-ra-sa", "why": "Le soukoun sur د ferme la syllabe : le d reste avec ma. Une syllabe arabe ne commence jamais par deux consonnes."}, {"wrong": "فِي = fi (i bref)", "right": "fî (i long)", "why": "Le ي après une kasra allonge la voyelle : c''est une syllabe ouverte longue."}, {"wrong": "قَمَر = qa-ma-ra", "right": "qa-mar", "why": "Un mot lu seul s''arrête sur une consonne : on ne prononce pas de voyelle sur la dernière lettre."}], "tip": "Cherche les soukouns (ـْ) : chacun ferme une syllabe. Partout ailleurs, coupe juste avant la consonne."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g18.three_letter_roots', 'ar', 'grammar', 'reading', 'Les mots de 3 lettres : la racine', 2, array['ar.g17.open_closed_syllables']::text[], 3, '{"rule": {"summary": "La plupart des mots arabes sont bâtis sur une racine de 3 consonnes : k-t-b = l''idée d''écrire. Repérer ces 3 lettres permet de lire et de deviner un mot très vite.", "explanation": "Le verbe de base au passé (« il a… ») n''a que 3 lettres, chacune avec sa voyelle : كَتَبَ (kataba), ذَهَبَ (dhahaba), فَتَحَ (fata7a). Le rythme le plus courant est CaCaCa, parfois CaCiCa (شَرِبَ chariba). C''est cette forme que l''on cherche dans le dictionnaire, et on la traduit par l''infinitif (écrire). Les mots de la même famille gardent les 3 lettres de la racine dans le même ordre, avec d''autres voyelles ou des lettres en plus : كِتَاب (kitâb, livre), مَكْتَب (maktab, bureau). Devant un mot long, cherche d''abord ces 3 lettres : le reste (مَـ au début, ا au milieu) précise le sens.", "pattern": "Racine k-t-b → كَتَبَ (il a écrit) · كِتَاب (livre) · مَكْتَب (bureau)", "examples": [{"text": "كَتَبَ", "translation": "il a écrit (racine k-t-b)", "transliteration": "kataba"}, {"text": "كِتَاب", "translation": "le livre (même racine k-t-b)", "transliteration": "kitâb"}, {"text": "مَكْتَب", "translation": "le bureau, le lieu où l''on écrit (مَـ + k-t-b)", "transliteration": "maktab"}, {"text": "شَرِبَ", "translation": "il a bu (rythme CaCiCa)", "transliteration": "chariba"}], "commonErrors": [{"wrong": "كَتَبَ = katab", "right": "kataba", "why": "Dans un verbe vocalisé, chaque lettre porte une voyelle : la fatha finale se lit, ka-ta-ba."}, {"wrong": "شَرِبَ = charaba", "right": "chariba", "why": "Regarde la voyelle du milieu : sous ر il y a une kasra (i). Tous les verbes ne suivent pas le rythme kataba."}, {"wrong": "مَكْتَب : racine m-k-t", "right": "racine k-t-b", "why": "Le مَـ du début est un ajout qui veut dire « lieu de ». La racine, ce sont les 3 lettres qui portent le sens : k-t-b."}], "tip": "Trois lettres, une idée : cherche le squelette (k-t-b) avant de lire le reste."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g19.non_connecting_letters', 'ar', 'grammar', 'reading', 'Les 6 lettres qui ne s''attachent pas à gauche', 2, array['ar.g17.open_closed_syllables']::text[], 3, '{"rule": {"summary": "Six lettres ne s''attachent jamais à la lettre qui les suit : ا د ذ ر ز و. Après elles, le mot se coupe mais continue : ce n''est pas un espace.", "explanation": "Ces 6 lettres s''attachent à la lettre d''avant, jamais à celle d''après. Un même mot peut donc être fait de plusieurs blocs : وَرْدَة (warda) s''écrit en 4 morceaux, و | ر | د | ة, et c''est pourtant un seul mot. La lettre qui suit une de ces 6 lettres prend sa forme de début, même au milieu du mot. Pour savoir où finit vraiment un mot, regarde l''espace : il est plus large que les petites coupures. Le ة et le ى de fin ne s''attachent pas non plus à gauche, mais ils sont toujours en fin de mot. Pour lire vite, avale un bloc d''un coup, puis passe au suivant.", "pattern": "ا د ذ ر ز و + lettre suivante = coupure dans le même mot", "examples": [{"text": "وَرْدَة", "translation": "la rose : 4 blocs (و | ر | د | ة)", "transliteration": "warda"}, {"text": "بَارِد", "translation": "froid : 3 blocs (با | ر | د)", "transliteration": "bârid"}, {"text": "مَدِينَة", "translation": "la ville : 2 blocs (مد | ينة)", "transliteration": "madîna"}, {"text": "أَرُزّ", "translation": "le riz : 3 blocs (أ | ر | ز)", "transliteration": "''aruzz"}], "commonErrors": [{"wrong": "وَرْدَة = 4 mots", "right": "1 seul mot en 4 blocs", "why": "Les coupures après و, ر et د sont obligatoires : elles sont plus petites qu''un espace entre deux mots."}, {"wrong": "بَارِد : le ر s''attache au د", "right": "le ر ne s''attache jamais à gauche", "why": "ر fait partie des 6 lettres qui ne donnent jamais la main à gauche : le د qui suit est détaché."}, {"wrong": "مَدِينَة : le mot s''arrête après د", "right": "le mot continue avec ينة", "why": "Après د le mot se coupe mais continue : la lettre suivante (ي) prend sa forme de début."}], "tip": "Retiens la phrase-clé : « ا د ذ ر ز و ne donnent jamais la main à gauche »."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g20.long_words_blocks', 'ar', 'grammar', 'reading', 'Lire les mots longs par blocs', 3, array['ar.g17.open_closed_syllables','ar.g19.non_connecting_letters']::text[], 3, '{"rule": {"summary": "Un mot long se lit par blocs : découpe-le aux coupures (après ا د ذ ر ز و), puis repère les morceaux qui reviennent souvent (مَـ، مُسْتَـ، ـة، ـات).", "explanation": "Ne lis pas lettre par lettre : ton œil doit attraper un bloc entier, puis le suivant. Étape 1 : repère les coupures (سَيَّارَة = سيا | ر | ة). Étape 2 : dans un long bloc attaché, cherche les morceaux familiers : مَـ ou مُـ au début (souvent un lieu : مَطْعَم, مُسْتَشْفَى), ـَة à la fin (souvent féminin), ـَات (pluriel). Étape 3 : appuie-toi sur les voyelles longues (ا و ي), qui marquent souvent la syllabe forte. Une voyelle longue de plus ou de moins change le mot : مَطَر (pluie) ≠ مَطَار (aéroport).", "pattern": "Coupures → blocs → morceaux connus (مَـ، مُسْتَـ، ـة، ـات) → voyelles longues", "examples": [{"text": "سَيَّارَة", "translation": "la voiture : سيا | ر | ة → say-yâ-ra", "transliteration": "sayyâra"}, {"text": "مُسْتَشْفَى", "translation": "l''hôpital : un seul bloc, mus-tach-fâ", "transliteration": "mustachfâ"}, {"text": "بُرْتُقَال", "translation": "l''orange : بر | تقا | ل → bur-tu-qâl", "transliteration": "burtuqâl"}, {"text": "مَطْعَم", "translation": "le restaurant : مَـ (lieu) + ط ع م (manger)", "transliteration": "maT3am"}], "commonErrors": [{"wrong": "مَطَار = maTar", "right": "maTâr", "why": "Le ا du milieu allonge la voyelle : مطار (aéroport) a 4 lettres, مطر (pluie) seulement 3."}, {"wrong": "مُسْتَشْفَى = mus-ta-chi-fâ", "right": "mus-tach-fâ", "why": "Le soukoun sur ش ferme la syllabe : on n''ajoute pas de voyelle entre ش et ف."}, {"wrong": "سَيَّارَة = sa-yâ-ra", "right": "say-yâ-ra", "why": "La chadda sur ي double la lettre : say + yâ."}], "tip": "Blocs d''abord, voyelles longues ensuite : un mot de 6 lettres, c''est 2 ou 3 bouchées."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g21.lookalike_letters', 'ar', 'grammar', 'reading', 'Les lettres jumelles : ne plus les confondre', 3, array['ar.g20.long_words_blocks']::text[], 3, '{"rule": {"summary": "Beaucoup de lettres ont le même dessin et ne diffèrent que par le nombre ou la place de leurs points : vérifie toujours les points.", "explanation": "Groupes à surveiller : ب (1 point dessous), ت (2 dessus), ث (3 dessus), ن (1 dessus), ي (2 dessous) ; ج (point dedans), ح (aucun point), خ (point dessus) ; puis les paires د / ذ, ر / ز, س / ش, ص / ض, ط / ظ, ع / غ, où la deuxième lettre a des points en plus. ف (1 point) et ق (2 points) ont presque la même tête. Une erreur de point change le mot : صَيْف (été) / ضَيْف (invité), خُبْز (pain) / جُبْن (fromage). Pour lire vite, regarde d''abord la silhouette du mot, puis vérifie les points en un coup d''œil.", "pattern": "Même dessin, points différents : ب ت ث ن ي · ج ح خ · د ذ · ر ز · س ش · ص ض · ط ظ · ع غ · ف ق", "examples": [{"text": "صَيْف", "translation": "l''été (ص : aucun point)", "transliteration": "Sayf"}, {"text": "ضَيْف", "translation": "l''invité (ض : un point)", "transliteration": "Dayf"}, {"text": "ثَلْج", "translation": "la neige (ث : 3 points)", "transliteration": "thaldj"}, {"text": "خُبْز", "translation": "le pain (خ : point dessus)", "transliteration": "khubz"}], "commonErrors": [{"wrong": "حَلِيب = khalîb", "right": "7alîb", "why": "ح n''a aucun point. Avec un point au-dessus, ce serait خ (kh)."}, {"wrong": "ثَلْج = taldj", "right": "thaldj", "why": "3 points au-dessus = ث (th) ; 2 points = ت (t)."}, {"wrong": "بَيْض = bayt", "right": "bayD", "why": "La dernière lettre est ض (D), pas ت : regarde la forme de la lettre, pas seulement ses points."}], "tip": "Silhouette d''abord, points ensuite : combien, et dessus ou dessous ?"}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g22.frequent_words', 'ar', 'grammar', 'reading', 'Les mots les plus fréquents', 2, array['ar.g17.open_closed_syllables']::text[], 3, '{"rule": {"summary": "Une vingtaine de petits mots (هٰذَا، فِي، مِنْ، عَلَى، هُوَ، لَا…) reviennent dans presque toutes les phrases : reconnais-les comme des images, sans les déchiffrer.", "explanation": "Ces mots sont courts et certains s''écrivent de façon particulière. هٰذَا (hâdhâ) et هٰذِهِ (hâdhihi) portent un petit alif vertical (ـٰ) sur le ه : on lit hâ, même si le grand ا n''est pas écrit. Le ى final de عَلَى et إِلَى se lit â, comme un alif. وَ (et) s''attache toujours au mot qui suit : وَالْخُبْزُ = wa + al-khubzu. Attention aux paires : هُوَ (il) / هِيَ (elle), هٰذَا (masculin) / هٰذِهِ (féminin), أَنَا (je) / أَنْتَ (tu). Ce sont eux qui donnent la structure de la phrase.", "pattern": "هٰذَا / هٰذِهِ (ceci) · هُوَ / هِيَ (il / elle) · أَنَا / أَنْتَ (je / tu) · فِي، مِنْ، عَلَى، إِلَى، مَعَ · لَا / نَعَمْ", "examples": [{"text": "هٰذَا كِتَابٌ", "translation": "C''est un livre.", "transliteration": "hâdhâ kitâb"}, {"text": "هٰذِهِ مَدْرَسَةٌ", "translation": "C''est une école.", "transliteration": "hâdhihi madrasa"}, {"text": "هُوَ هُنَا", "translation": "Il est ici.", "transliteration": "huwa hunâ"}, {"text": "نَعَمْ، أَنَا هُنَا", "translation": "Oui, je suis ici.", "transliteration": "na3am, ''anâ hunâ"}], "commonErrors": [{"wrong": "هٰذَا = hadha (a bref)", "right": "hâdhâ", "why": "Le petit alif vertical sur le ه allonge le a (hâ), et le ا final allonge aussi (dhâ)."}, {"wrong": "هٰذَا مَدْرَسَةٌ", "right": "هٰذِهِ مَدْرَسَةٌ", "why": "مَدْرَسَة est féminin (finale ـة) : on utilise هٰذِهِ."}, {"wrong": "عَلَى = 3alî", "right": "3alâ", "why": "Le ى sans points en fin de mot se lit â, comme un alif."}], "tip": "Ces mots sont des visages connus : reconnais-les d''un regard et garde ton énergie pour les mots nouveaux."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g23.short_sentences', 'ar', 'grammar', 'reading', 'Lire une phrase courte vocalisée', 3, array['ar.g22.frequent_words','ar.g20.long_words_blocks']::text[], 3, '{"rule": {"summary": "Pour lire une phrase vite, avance par mots entiers : repère les petits mots et l''article الـ, puis le mot principal ; la voyelle de la fin ne se prononce pas à la pause.", "explanation": "Au présent, le verbe « être » ne s''écrit pas : هٰذَا بَيْتٌ = « ceci (est) une maison ». L''article الـ (le, la) s''attache au nom ; devant certaines lettres (ت د ر س ش ص ط ل ن…), le ل ne se prononce pas et la lettre suivante porte une chadda : الشَّايُ = ach-châyu. Les voyelles de fin (ـُ ـَ ـِ, ـٌ) montrent le rôle du mot ; en fin de phrase, on ne les prononce pas : الْبَيْتُ جَمِيلٌ se lit al-baytu djamîl. Après فِي, مِنْ, عَلَى, إِلَى, le nom finit par une kasra : فِي الْبَيْتِ. Lis chaque phrase deux fois : une fois pour reconnaître les mots, une fois d''un trait.", "pattern": "هٰذَا + nom + adjectif · pronom + فِي / عَلَى + الـ nom + ـِ · verbe + الـ nom + ـَ", "examples": [{"text": "هٰذَا بَيْتٌ جَمِيلٌ", "translation": "C''est une belle maison.", "transliteration": "hâdhâ baytun djamîl"}, {"text": "أَنَا فِي الْمَدْرَسَةِ", "translation": "Je suis à l''école.", "transliteration": "''anâ fî l-madrasa"}, {"text": "الشَّايُ حَارٌّ", "translation": "Le thé est chaud.", "transliteration": "ach-châyu 7ârr"}, {"text": "ذَهَبَ إِلَى السُّوقِ", "translation": "Il est allé au marché.", "transliteration": "dhahaba ''ilâ s-sûq"}], "commonErrors": [{"wrong": "الشَّايُ = al-châyu", "right": "ach-châyu", "why": "Devant ش, le ل de l''article ne se prononce pas : la chadda sur ش montre que la lettre est doublée."}, {"wrong": "فِي الْبَيْتُ", "right": "فِي الْبَيْتِ", "why": "Après فِي, le nom prend une kasra (ـِ) à la fin."}, {"wrong": "هٰذَا بَيْتٌ جَمِيلٌ = « Ceci une maison belle »", "right": "C''est une belle maison.", "why": "Le verbe « être » n''est pas écrit au présent, et l''adjectif se place après le nom."}], "tip": "Petits mots d''abord, nom ensuite, terminaison en dernier."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g24.speed_reading', 'ar', 'grammar', 'reading', 'Lecture rapide : tout le module', 4, array['ar.g23.short_sentences','ar.g21.lookalike_letters']::text[], 3, '{"rule": {"summary": "Lire vite, c''est enchaîner tous les réflexes du module : blocs, racine, points, syllabes, puis les petits mots fréquents dans la phrase.", "explanation": "Devant un mot inconnu, fais 4 vérifications en une seconde : 1) compte les blocs (coupures après ا د ذ ر ز و) ; 2) cherche les 3 lettres de la racine ; 3) vérifie les points des lettres jumelles ; 4) lis syllabe par syllabe en t''appuyant sur les soukouns et les voyelles longues. Devant une phrase, repère d''abord les petits mots fréquents : ils donnent la structure (هٰذَا…, فِي…, هُوَ…). Relis ensuite la phrase d''un trait, plus vite : c''est la répétition qui transforme le déchiffrage en lecture.", "pattern": "Mot : blocs → racine → points → syllabes · Phrase : petits mots → noms → terminaisons", "examples": [{"text": "شِتَاء", "translation": "l''hiver : شتا | ء → chi-tâ''", "transliteration": "chitâ''"}, {"text": "اللَّيْلُ بَارِدٌ", "translation": "La nuit est froide.", "transliteration": "al-laylu bârid"}, {"text": "الشَّمْسُ حَارَّةٌ", "translation": "Le soleil est chaud.", "transliteration": "ach-chamsu 7ârra"}, {"text": "الْمَاءُ بَارِدٌ", "translation": "L''eau est froide.", "transliteration": "al-mâ''u bârid"}], "commonErrors": [{"wrong": "نَهَار = nahr", "right": "nahâr", "why": "Il y a un ا après ه : voyelle longue, na-hâr. Ne saute pas les voyelles longues en lisant vite."}, {"wrong": "غَيْمَة = 3ayma", "right": "ghayma", "why": "Le point au-dessus fait de ع un غ (gh). Aller vite ne veut pas dire oublier les points."}, {"wrong": "شَمْس = samas", "right": "chams", "why": "ش a 3 points (ch), et le soukoun sur م ferme la syllabe : chams se lit en une seule syllabe."}], "tip": "Vite, mais deux fois : un passage pour la forme, un passage pour le sens."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g25.al_solaire_lunaire', 'ar', 'grammar', 'reading', 'Lire ال (solaire ou lunaire) avec les mots de la foi', 2, array['ar.g15.article_sun_moon']::text[], 4, '{"rule": {"summary": "Devant un mot, l''article ال se lit de deux façons : le l se prononce (lettre lunaire : الْمَسِيح = al-masî7) ou il disparaît en doublant la lettre suivante (lettre solaire : الرَّبّ = ar-rabb).", "explanation": "Tu connais la règle de la leçon 15 ; ici tu l''appliques aux mots de la foi. Un seul signe suffit : si la lettre après ال porte une chadda (ـّ), le ل ne se dit pas et cette lettre est doublée : الرَّبّ = ar-rabb, الثَّالُوث = ath-thâlûth, الرُّوح = ar-rû7. Même اللّٰه suit la règle : le ل est solaire, d''où Allâh avec un l doublé, et non « al-lâh ». Si le ل porte un soukoun (ـْ), il se prononce : الْمَسِيح = al-masî7, الْآب = al-âb, الْقُدُس = al-qudus. Au milieu d''une phrase, le a de al- tombe après une voyelle : بِاسْمِ الْآبِ = bismi l-âbi. Dans بِاسْمِ aussi, le ا de اسْم ne se prononce pas.", "pattern": "ال + chadda sur la lettre suivante = solaire (ar-rabb) · ال + soukoun sur le ل = lunaire (al-masî7)", "examples": [{"text": "الرَّبّ", "translation": "le Seigneur : ر solaire, donc ar-rabb", "transliteration": "ar-rabb"}, {"text": "الْمَسِيح", "translation": "le Christ : م lunaire, donc al-masî7", "transliteration": "al-masî7"}, {"text": "الرُّوح الْقُدُس", "translation": "le Saint-Esprit : un mot solaire, un mot lunaire", "transliteration": "ar-rû7 al-qudus"}, {"text": "بِاسْمِ الْآبِ وَالاِبْنِ", "translation": "au nom du Père et du Fils : le a de al- tombe", "transliteration": "bismi l-âbi wa-l-ibn"}], "commonErrors": [{"wrong": "الثَّالُوث lu « al-thâlûth »", "right": "ath-thâlûth", "why": "ث est une lettre solaire : le l ne se dit pas et le th est doublé."}, {"wrong": "الْمَسِيح lu « am-masî7 »", "right": "al-masî7", "why": "م est lunaire : le ل porte un soukoun et se prononce."}, {"wrong": "اللّٰه lu « al-lâh »", "right": "Allâh", "why": "Le ل d''Allah est solaire : la chadda double le second l. Le petit trait vertical est un alif qui se lit â."}], "tip": "Cherche la chadda juste après ال : si elle est là, ne dis pas le l."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g26.ta_marbuta_diphtongues', 'ar', 'grammar', 'reading', 'Lire ة et les diphtongues ay / aw : les objets de l''église', 2, array['ar.g25.al_solaire_lunaire','ar.g11.long_vowels']::text[], 4, '{"rule": {"summary": "Le ة (deux points sur un rond) termine surtout des noms féminins : il se lit a à la fin d''un mot (كَنِيسَة = kanîsa) et at quand un autre mot suit. Après une fatha, ي ou و avec soukoun donnent les diphtongues ay et aw (هَيْكَل = haykal).", "explanation": "Le ة (tâ'' marbûta) n''existe qu''en fin de mot, jamais au début ni au milieu. Tu le reconnais aux deux points posés sur le rond, alors que le ه final n''en a pas. Mot seul, on lit un simple a : كَنِيسَة = kanîsa, أَيْقُونَة = ayqûna. Quand un autre mot le suit dans un groupe (كَنِيسَةُ الرَّبِّ), le t apparaît : kanîsatu r-rabb. Deuxième piège : ي ou و avec un soukoun juste après une fatha ne sont pas des voyelles longues mais des diphtongues. ـَيْ se lit ay (a-i enchaînés, comme dans « paye ») et ـَوْ se lit aw (a-ou enchaînés, comme dans « miaou »). Comparaison : هَيْكَل = haykal (ay), mais صَلِيب = Salîb (kasra + ي = î long) ; مَوْعِظَة = maw3iZa (aw), mais بَخُور = bakhûr (damma + و = û long).", "pattern": "ة final = a (at devant un mot) · ـَيْ = ay · ـَوْ = aw · ـِي = î · ـُو = û", "examples": [{"text": "كَنِيسَة", "translation": "l''église : le ة final se lit a", "transliteration": "kanîsa"}, {"text": "هَيْكَل", "translation": "le sanctuaire : ـَيْ = ay", "transliteration": "haykal"}, {"text": "مَوْعِظَة", "translation": "le sermon : ـَوْ = aw et ة final = a", "transliteration": "maw3iZa"}, {"text": "كَنِيسَةُ الرَّبِّ", "translation": "l''église du Seigneur : devant un mot, ة se lit at", "transliteration": "kanîsatu r-rabb"}], "commonErrors": [{"wrong": "هَيْكَل lu « hîkal »", "right": "haykal", "why": "Le ي porte un soukoun après une fatha : c''est la diphtongue ay, pas un î long (qui demanderait une kasra)."}, {"wrong": "كَنِيسَة lu « kanîsat » en fin de phrase", "right": "kanîsa", "why": "Seul ou en fin de phrase, ة se lit a. Le t n''apparaît que si un autre mot suit."}, {"wrong": "مَوْعِظَة lu « mû3iZa »", "right": "maw3iZa", "why": "و avec soukoun après une fatha = diphtongue aw. Le û long suppose une damma avant le و (comme dans بَخُور)."}], "tip": "Regarde la voyelle avant ي / و : fatha + soukoun = ay / aw ; kasra ou damma sans soukoun = î / û."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g27.voyelles_longues_mots_grecs', 'ar', 'grammar', 'reading', 'Lire les voyelles longues des mots venus du grec : les lectures de la messe', 2, array['ar.g25.al_solaire_lunaire','ar.g11.long_vowels']::text[], 4, '{"rule": {"summary": "Les noms des lectures du qoddâs viennent du grec et se lisent comme n''importe quel mot arabe vocalisé : chaque ا, و, ي après sa voyelle est long (â, û, î), et on lit le mot bloc par bloc.", "explanation": "Le Paulus, le Catholicon, l''Ibraksis ou le Synaxaire ont des noms grecs écrits en lettres arabes. Ils font peur parce qu''ils sont longs, mais la méthode ne change pas : repère d''abord les voyelles longues (ـَا = â, ـُو = û, ـِي = î) puis coupe en blocs. الْكَاثُولِيكُون = al-kâ-thû-lî-kûn : quatre voyelles longues, donc quatre temps forts. Les lettres ث et ج gardent leur son (th, dj). L''article suit la règle de la leçon 25 : lunaire devant ب, ك, إ (al-bûlus, al-kâthûlîkûn, al-ibraksîs), solaire devant س (as-sinaksâr). Pense à marquer la longueur : بُولُس se lit bûlus, avec un û long, et non bulus.", "pattern": "ـَا = â · ـُو = û · ـِي = î : on tient la voyelle deux fois plus longtemps", "examples": [{"text": "الْبُولُس", "translation": "la lecture de saint Paul : û long", "transliteration": "al-bûlus"}, {"text": "الْكَاثُولِيكُون", "translation": "les épîtres catholiques : â, û, î, û longs", "transliteration": "al-kâthûlîkûn"}, {"text": "الْإِبْرَكْسِيس", "translation": "les Actes des Apôtres : un seul î long, à la fin", "transliteration": "al-ibraksîs"}, {"text": "السِّنَكْسَار", "translation": "le Synaxaire : س solaire, â long", "transliteration": "as-sinaksâr"}], "commonErrors": [{"wrong": "الْبُولُس lu « al-bulus »", "right": "al-bûlus", "why": "Le و après la damma du ب allonge la voyelle : bû, pas bu."}, {"wrong": "السِّنَكْسَار lu « al-sinaksar »", "right": "as-sinaksâr", "why": "س est solaire (chadda) et le dernier ا est long : â."}, {"wrong": "الْكَاثُولِيكُون lu « al-katolikon »", "right": "al-kâthûlîkûn", "why": "ث se lit th, pas t, et chaque ا, و, ي marque une voyelle longue."}], "tip": "Souligne mentalement chaque ا, و, ي long : ce sont les temps forts du mot."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g28.nom_adjectif', 'ar', 'grammar', 'reading', 'Lire nom + adjectif (الْكِتَاب الْمُقَدَّس) et le pluriel en ـَات', 3, array['ar.g25.al_solaire_lunaire','ar.g26.ta_marbuta_diphtongues']::text[], 4, '{"rule": {"summary": "En arabe, l''adjectif suit le nom et s''accorde avec lui : il reprend ال si le nom est défini (الْعَهْد الْجَدِيد), et prend un ة s''il est féminin (الْكَنِيسَة الْقِبْطِيَّة). Les noms féminins font souvent leur pluriel en ـَات (نُبُوَّة → نُبُوَّات).", "explanation": "Dans un groupe nom + adjectif, l''adjectif vient toujours en deuxième. Si le nom a ال, l''adjectif l''a aussi : الْكِتَاب الْمُقَدَّس, mot à mot « le livre le saint » = la Bible. Sans ال des deux côtés, on obtient un groupe indéfini : كِتَابٌ مُقَدَّسٌ (un livre saint). Si seul le nom a ال, c''est une phrase : الْكِتَابُ مُقَدَّسٌ = le livre est saint. Un nom féminin demande un adjectif féminin : الْكَنِيسَة الْقِبْطِيَّة = l''Église copte. Le pluriel en ـَات se fait en retirant le ة et en ajoutant ـَات : نُبُوَّة → نُبُوَّات (prophéties), آيَة → آيَات (versets), أَيْقُونَة → أَيْقُونَات. Pour lire, applique ال à chaque mot : an-nubuwwât (ن solaire), al-qadîm (ق lunaire).", "pattern": "ال + nom + ال + adjectif (même genre) · pluriel : ـَة → ـَات", "examples": [{"text": "الْكِتَاب الْمُقَدَّس", "translation": "la Bible : nom et adjectif ont tous deux ال", "transliteration": "al-kitâb al-muqaddas"}, {"text": "الْعَهْد الْجَدِيد", "translation": "le Nouveau Testament", "transliteration": "al-3ahd al-djadîd"}, {"text": "الْكَنِيسَة الْقِبْطِيَّة", "translation": "l''Église copte : nom et adjectif féminins", "transliteration": "al-kanîsa al-qibTiyya"}, {"text": "النُّبُوَّات", "translation": "les prophéties : pluriel en ـَات de نُبُوَّة", "transliteration": "an-nubuwwât"}], "commonErrors": [{"wrong": "الْعَهْد جَدِيد pour « le Nouveau Testament »", "right": "الْعَهْد الْجَدِيد", "why": "Quand le nom a ال, l''adjectif doit l''avoir aussi. Sans lui, c''est une phrase : « le testament est nouveau »."}, {"wrong": "الْكَنِيسَة الْقِبْطِيّ", "right": "الْكَنِيسَة الْقِبْطِيَّة", "why": "كَنِيسَة est féminin : l''adjectif prend aussi le ة (ـِيَّة)."}, {"wrong": "النُّبُوَّات lu « an-nubuwat »", "right": "an-nubuwwât", "why": "Le و porte une chadda (deux w) et le ـَات final se lit â + t."}], "tip": "Nom d''abord, adjectif ensuite ; si le nom a ال, l''adjectif aussi ; si le nom est féminin, l''adjectif aussi."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g29.idafa', 'ar', 'grammar', 'reading', 'Lire l''annexion (iDâfa) : les noms des fêtes et des jeûnes', 3, array['ar.g28.nom_adjectif','ar.g26.ta_marbuta_diphtongues']::text[], 4, '{"rule": {"summary": "L''annexion (iDâfa) met deux noms côte à côte pour dire « X de Y » : le premier n''a ni ال ni tanwîn, le second est défini (ال) et se termine par une kasra. Le ة du premier nom se lit t.", "explanation": "Pour dire « la fête de la Nativité », l''arabe n''utilise pas de petit mot « de » : il pose deux noms l''un après l''autre, عِيد (fête) puis الْمِيلَاد (la Nativité). C''est l''annexion. Trois règles de lecture : (1) le premier nom n''a jamais ال ni tanwîn, même s''il est précis en français (عِيد الْقِيَامَة, pas الْعِيد الْقِيَامَة) ; (2) le second nom a ال (ou est un nom propre) et prend une kasra quand on lit les terminaisons : عِيدُ الْمِيلَادِ = 3îdu l-mîlâdi, avec le a de al- qui tombe ; (3) si le premier nom se termine par ة, on dit t : أَيْقُونَةُ الْعَذْرَاءِ = ayqûnatu l-3adhrâ''. Attention à ne pas confondre avec nom + adjectif (leçon 28) : الصَّوْم الْكَبِير, « le Grand Carême », a ال sur les deux mots, alors qu''une annexion n''a ال que sur le second.", "pattern": "1er nom sans ال + 2e nom avec ال = « X de Y » (3îd al-mîlâd) · nom + adjectif = ال sur les deux", "examples": [{"text": "عِيد الْمِيلَاد", "translation": "la fête de la Nativité (Noël) : 1er nom sans ال", "transliteration": "3îd al-mîlâd"}, {"text": "عِيد الْقِيَامَة", "translation": "la fête de la Résurrection (Pâques)", "transliteration": "3îd al-qiyâma"}, {"text": "أُسْبُوع الْآلَام", "translation": "la semaine de la Passion (Semaine sainte)", "transliteration": "usbû3 al-âlâm"}, {"text": "أَحَد الشَّعَانِين", "translation": "le dimanche des Rameaux : ش solaire dans le second nom", "transliteration": "a7ad ach-cha3ânîn"}], "commonErrors": [{"wrong": "الْعِيد الْقِيَامَة pour « la fête de la Résurrection »", "right": "عِيد الْقِيَامَة", "why": "Le premier nom d''une annexion n''a jamais ال : c''est le second nom qui le rend précis."}, {"wrong": "عِيدُ الْمِيلَادِ lu « 3îdu al-mîlâdi »", "right": "3îdu l-mîlâdi", "why": "Après la damma de 3îdu, le a de al- tombe : on enchaîne 3îdu l-mîlâdi."}, {"wrong": "الصَّوْم الْكَبِير lu comme une annexion « le jeûne du grand »", "right": "le Grand Carême", "why": "ال est sur les deux mots : c''est un nom + un adjectif, pas une annexion."}], "tip": "Annexion : le premier nom reste « nu » (sans ال), le second porte ال."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g30.chadda_hamza', 'ar', 'grammar', 'reading', 'Lire la chadda et la hamza finale : les saints et le clergé', 3, array['ar.g12.shadda','ar.g14.hamza_madda']::text[], 4, '{"rule": {"summary": "La chadda (ـّ) double la consonne : قِدِّيس = qid-dîs, شَمَّاس = cham-mâs. Une hamza écrite seule à la fin d''un mot, après un ا long, se lit comme un petit arrêt de la gorge : الْعَذْرَاء = al-3adhrâ''.", "explanation": "Tu connais déjà la chadda (leçon 12) et la hamza (leçon 14) ; ici, elles servent à lire les saints et le clergé. (1) Une lettre avec chadda vaut deux lettres : la première ferme la syllabe, la seconde ouvre la suivante. قِدِّيس = qid-dîs (le d est dit deux fois), شَمَّاس = cham-mâs. Avec ال solaire, le mot peut avoir deux chaddas : الشَّمَّاس = ach-cham-mâs. (2) Une hamza qui s''écrit seule (ء) à la fin d''un mot, après un ا long, est un léger coup de glotte, noté '' : الْعَذْرَاء = al-3adhrâ''. Elle n''ajoute pas de voyelle. Tu la retrouves dans de nombreux pluriels : شَهِيد → شُهَدَاء (chuhadâ'', les martyrs), نَبِيّ → أَنْبِيَاء (anbiyâ'', les prophètes).", "pattern": "ـّ = lettre doublée (qid-dîs, cham-mâs) · ء final après ا long = petit coup de glotte (3adhrâ'')", "examples": [{"text": "قِدِّيس", "translation": "saint : le د est doublé", "transliteration": "qid-dîs"}, {"text": "شَمَّاس", "translation": "diacre : le م est doublé", "transliteration": "cham-mâs"}, {"text": "الْعَذْرَاء", "translation": "la Vierge : hamza finale après â long", "transliteration": "al-3adhrâ''"}, {"text": "الشُّهَدَاء", "translation": "les martyrs : ش solaire, hamza finale", "transliteration": "ach-chuhadâ''"}], "commonErrors": [{"wrong": "قِدِّيس lu « qidis »", "right": "qid-dîs", "why": "La chadda double le د (deux d) et le ي après la kasra est long."}, {"wrong": "شَمَّاس lu « chamas »", "right": "cham-mâs", "why": "La chadda double le م : cham-mâs. Sans elle, le mot serait plus court."}, {"wrong": "الْعَذْرَاء lu « al-3adhrâ » sans la hamza finale", "right": "al-3adhrâ''", "why": "Le ء final se prononce : un petit coup de glotte après le â long."}], "tip": "Chadda = j''appuie sur la consonne ; ء final = je ferme la gorge d''un coup sec."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g31.ya_pronoms_attaches', 'ar', 'grammar', 'reading', 'Lire les formules de la liturgie : يَا, les pronoms attachés et le ا muet', 3, array['ar.g25.al_solaire_lunaire','ar.g26.ta_marbuta_diphtongues']::text[], 4, '{"rule": {"summary": "Pour lire les réponses de la liturgie : يَا appelle quelqu''un (« ô »), les petits suffixes ـكَ, ـنَا, ـهُ se collent au mot (« ton, notre, son ») et certains ا s''écrivent sans se prononcer.", "explanation": "Les réponses du peuple sont courtes et reviennent à chaque messe : lis-les par blocs. (1) يَا + nom = on appelle quelqu''un : يَا رَبُّ, « ô Seigneur ». Le ا de يَا est long (yâ) et le nom qui suit se termine par une damma, sans tanwîn. (2) Des pronoms se collent à la fin d''un mot : ـكَ = « ton / à toi » (رُوحِكَ, لَكَ), ـنَا = « notre / nous » (أَبَانَا, رَبُّنَا), ـهُ = « son / à lui » (لَهُ). Leur écriture ne change pas : repère-les d''abord, lis le mot ensuite. (3) Certains ا s''écrivent mais ne se disent pas. Le ا de ارْحَمْ tombe quand le mot qui précède se termine par une voyelle : يَا رَبُّ ارْحَمْ = yâ rabbu r-7am, comme dans بِاسْمِ (bismi, leçon 25) ; et le ا qui suit و à la fin d''un verbe au pluriel est muet : صَلُّوا = Sallû, et non « Sallûâ ». Dans l''église, tu entends aussi les deux mots séparés par un petit silence (« yâ rabb… irham ») : c''est la même formule, dite en deux temps.", "pattern": "يَا + nom en ـُ = « ô… » · mot + ـكَ / ـنَا / ـهُ = ton / notre / son · ا muet : ارْحَمْ, بِاسْمِ, صَلُّوا", "examples": [{"text": "يَا رَبُّ", "translation": "ô Seigneur : يَا appelle, le nom prend une damma", "transliteration": "yâ rabb"}, {"text": "لَكَ", "translation": "à toi : لِ (à) + ـكَ (toi)", "transliteration": "laka"}, {"text": "أَبَانَا", "translation": "notre père : أَب + ـنَا (notre)", "transliteration": "abâna"}, {"text": "يَا رَبُّ ارْحَمْ", "translation": "Seigneur, aie pitié : le ا de ارْحَمْ ne se dit pas", "transliteration": "yâ rabbu r-7am"}], "commonErrors": [{"wrong": "يَا رَبُّ ارْحَمْ lu « yâ rabbu ârham »", "right": "yâ rabbu r-7am", "why": "Le ا de ارْحَمْ n''est pas un â long : après رَبُّ il tombe et on enchaîne r-7am. En s''arrêtant entre les deux mots, on dit simplement « irham »."}, {"wrong": "صَلُّوا lu « Sallûâ »", "right": "Sallû", "why": "Le ا écrit après و à la fin d''un verbe pluriel est muet : il se voit, il ne se dit pas."}, {"wrong": "لَكَ lu « laki »", "right": "laka", "why": "Sous le ك, il y a une fatha : on s''adresse à Dieu au masculin, laka."}], "tip": "Pronom collé, ا muet : lis le mot, pas la lettre."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g32.tanwin_pause', 'ar', 'grammar', 'reading', 'Lire un verset : tanwîn et pause en fin de phrase', 3, array['ar.g13.tanwin','ar.g31.ya_pronoms_attaches']::text[], 4, '{"rule": {"summary": "Dans un verset, on lit les voyelles de fin et le tanwîn au milieu d''une phrase, mais on les laisse tomber à la fin : مَحَبَّةٌ se lit ma7abbatun au milieu et ma7abba à la fin.", "explanation": "Un verset court est souvent une phrase sans verbe : un sujet (اللّٰهُ, avec une damma) puis un attribut. (1) L''attribut sans ال porte un tanwîn : اللّٰهُ مَحَبَّةٌ, « Dieu est amour » (en français, on ne dit pas « un amour »). Avec ال, il garde une simple damma : الطَّرِيقُ, « le chemin ». أَنَا هُوَ… se traduit « Je suis… » et insiste sur « c''est moi qui suis ». (2) La règle de la pause. Au milieu d''une phrase, on lit tout : مَحَبَّةٌ وَنُورٌ = ma7abbatun wa-nûr. À la toute fin, on s''arrête sans voyelle : le tanwîn -un ou -in tombe (نُورٌ = nûr), la damma tombe (الْحَقُّ = al-7aqq) et le ة se lit a (مَحَبَّةٌ = ma7abba) ou ne s''entend plus après un â long (الْحَيَاةُ = al-7ayâ). (3) À la fin d''une phrase, le tanwîn -an (ـً) se prononce souvent â : أَيْضًا = ayDâ ; en Égypte, on garde parfois -an. Lis le verset d''un seul souffle, puis reprends-le en marquant la pause sur le dernier mot.", "pattern": "milieu de phrase : ـٌ = -un, ـُ = -u · fin de phrase : tout tombe (nûr, al-7aqq) · ـَةٌ → -a (ma7abba)", "examples": [{"text": "اللّٰهُ مَحَبَّةٌ", "translation": "Dieu est amour (1 Jean 4:8) : à la fin, le tanwîn et le t tombent", "transliteration": "Allâhu ma7abba"}, {"text": "مَحَبَّةٌ وَنُورٌ", "translation": "amour et lumière : au milieu, on lit -un ; à la fin, il tombe", "transliteration": "ma7abbatun wa-nûr"}, {"text": "أَنَا هُوَ نُورُ الْعَالَمِ", "translation": "Je suis la lumière du monde (Jean 8:12)", "transliteration": "ana huwa nûru l-3âlam"}, {"text": "أَنَا هُوَ الطَّرِيقُ وَالْحَقُّ وَالْحَيَاةُ", "translation": "Je suis le chemin, la vérité et la vie (Jean 14:6) : damma au milieu, rien à la fin", "transliteration": "ana huwa T-Tarîqu wa-l-7aqqu wa-l-7ayâ"}], "commonErrors": [{"wrong": "اللّٰهُ مَحَبَّةٌ lu « Allâhu ma7abbatun » en fin de verset", "right": "Allâhu ma7abba", "why": "À la fin d''une phrase, le tanwîn et le t du ة tombent : on s''arrête sur ma7abba."}, {"wrong": "الْحَيَاةُ lu « al-7ayâtu » en fin de phrase", "right": "al-7ayâ", "why": "À la pause, la damma et le t ne se lisent pas. On les dit seulement si un autre mot suit : al-7ayâtu l-abadiyya."}, {"wrong": "الطَّرِيقُ وَالْحَقُّ lu « aT-Tarîq wa-l-7aqq » au milieu du verset", "right": "aT-Tarîqu wa-l-7aqqu", "why": "Au milieu d''une phrase, on lit les voyelles de fin. Seul le dernier mot s''arrête sans voyelle."}], "tip": "Au milieu, lis la fin du mot ; à la fin, tais-la."}, "functionWords": []}'::jsonb, '2026.10.22', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
