insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l01', 'ar', 1, 'Alif et les dents ب ت ث', 'Reconnaître ا ب ت ث sous leurs quatre formes : ب ت ث ont le même corps, seuls les points changent, et ا ne s''attache jamais à la lettre suivante.', 1, 1, 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.v.alif','ar.v.ba','ar.v.ta','ar.v.tha','ar.v.bab','ar.v.kitab','ar.v.thawb','ar.v.athath']::text[], '{}'::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l02', 'ar', 1, 'Les cinq dents : ن et ي rejoignent ب ت ث', 'ن et ي ont le même corps que ب ت ث : au début et au milieu, seuls le nombre et la place des points les distinguent. Entraînement au comptage des points sur de vrais mots.', 1, 2, 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.nun','ar.v.ya','ar.v.tin','ar.v.banat','ar.v.nabat','ar.v.bayna']::text[], array['ar.g01.alif_ba_ta_tha','ar.v.kitab']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l03', 'ar', 1, 'Le crochet ج ح خ', 'ج ح خ ont la même silhouette en crochet : seul le point les distingue (dans la courbe, aucun, au-dessus). Lecture de mots fréquents où elles prennent leurs quatre formes.', 2, 3, 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.djim','ar.v.hha','ar.v.kha','ar.v.habib','ar.v.tahta','ar.v.nahnu','ar.v.taj','ar.v.khatam','ar.v.djazar']::text[], array['ar.g02.nun_ya_five_teeth','ar.v.tin','ar.v.ya']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l04', 'ar', 1, 'Les six lettres qui ne s''attachent pas : ا د ذ ر ز و', 'د ذ ر ز و (comme ا) s''attachent à la lettre d''avant mais jamais à la suivante : elles coupent le mot en blocs. Comprendre ce que cela change à la forme des lettres qui les suivent.', 2, 4, 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.dal','ar.v.dhal','ar.v.ra','ar.v.zay','ar.v.waw','ar.v.dar','ar.v.zayt','ar.v.dadjadj','ar.v.ladhidh']::text[], array['ar.g01.alif_ba_ta_tha','ar.g03.djim_ha_kha','ar.v.kitab','ar.v.taj']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l05', 'ar', 1, 'La scie et la boucle : س ش ص ض', 'س ش (trois dents en scie) et ص ض (une boucle ronde) : deux paires où seuls les points changent, avec le s et le d « lourds » de l''arabe. Lecture de mots de la maison et de la table.', 2, 5, 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.sin','ar.v.chin','ar.v.sad','ar.v.dad','ar.v.sarir','ar.v.chawka','ar.v.sahn','ar.v.misbah','ar.v.dayf','ar.v.qamis']::text[], array['ar.g04.non_connecting_letters','ar.g02.nun_ya_five_teeth','ar.v.zayt','ar.v.dar','ar.v.khatam','ar.v.djazar']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l06', 'ar', 1, 'Le bâton et l''œil : ط ظ ع غ', 'ط ظ (une boucle à bâton vertical) et ع غ (une tête en forme d''œil) : deux paires où le point fait toute la différence, avec les sons « lourds » et gutturaux de l''arabe.', 3, 6, 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.tah','ar.v.zah','ar.v.ayn','ar.v.ghayn','ar.v.taam','ar.v.tawila','ar.v.asal','ar.v.asir','ar.v.ghurfa','ar.v.nazif']::text[], array['ar.g05.sin_chin_sad_dad','ar.g04.non_connecting_letters','ar.v.sad','ar.v.sarir','ar.v.dayf','ar.v.qamis','ar.v.dadjadj']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l07', 'ar', 1, 'Six lettres de tous les jours : ف ق ك ل م ه', 'ف et ق (même tête, un ou deux points), ك et ل (un zigzag ou un simple trait), م, et ه dont les quatre formes n''ont presque rien de commun. Lecture d''objets du quotidien.', 3, 7, 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.fa','ar.v.qaf','ar.v.kaf','ar.v.lam','ar.v.mim','ar.v.ha','ar.v.qalam','ar.v.kub','ar.v.hatif','ar.v.miftah']::text[], array['ar.g06.ta_za_ayn_ghayn','ar.g05.sin_chin_sad_dad','ar.g04.non_connecting_letters','ar.v.asal','ar.v.qamis']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l08', 'ar', 1, 'Les derniers signes : ة ى ء لا, et tour de l''alphabet', 'ة (le a final des mots féminins), ى (un â final sans points), ء (la coupure de gorge) et la ligature obligatoire لا. Puis révision éclair de tout l''alphabet.', 3, 8, 'ar.g08.ta_marbuta_maqsura_hamza_lam_alif', array['ar.g08.ta_marbuta_maqsura_hamza_lam_alif','ar.v.ta_marbuta','ar.v.alif_maqsura','ar.v.hamza','ar.v.lam_alif','ar.v.maktaba','ar.v.fakiha','ar.v.maqha','ar.v.sama','ar.v.salam']::text[], array['ar.g01.alif_ba_ta_tha','ar.g03.djim_ha_kha','ar.g04.non_connecting_letters','ar.g05.sin_chin_sad_dad','ar.g06.ta_za_ayn_ghayn','ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.bab','ar.v.mim']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l09', 'ar', 2, 'Les voyelles brèves : fatha, kasra, damma', 'Lire une lettre avec a, i ou u, puis des mots entiers syllabe par syllabe.', 1, 9, 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.fatha','ar.v.kasra','ar.v.damma','ar.v.walad','ar.v.radjul','ar.v.yad','ar.v.fam','ar.v.katif','ar.v.unuq']::text[], '{}'::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l10', 'ar', 2, 'Le sukun et les syllabes fermées', 'Repérer le petit rond qui coupe la voyelle et lire bint, qalb, katabtu d''un seul trait.', 1, 10, 'ar.g10.sukun', array['ar.g10.sukun','ar.v.sukun','ar.v.bint','ar.v.ibn','ar.v.tifl','ar.v.qalb','ar.v.wadjh','ar.v.ridjl','ar.v.chakhs','ar.v.batn']::text[], array['ar.g09.short_vowels']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l11', 'ar', 2, 'Les voyelles longues : court ou long ?', 'Allonger la voyelle avec ا, و, ي et ne pas confondre î avec ay, û avec aw.', 2, 11, 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.madd','ar.v.khal','ar.v.sadiq','ar.v.djar','ar.v.lisan','ar.v.ayn_oeil','ar.v.zawdj','ar.v.adjuz','ar.v.dhira']::text[], array['ar.g09.short_vowels','ar.g10.sukun']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l12', 'ar', 2, 'La shadda : la lettre doublée', 'Lire la consonne doublée (djadd, mu3allim) et placer la voyelle qui l''accompagne.', 2, 12, 'ar.g12.shadda', array['ar.g12.shadda','ar.v.shadda','ar.v.djadd','ar.v.djadda','ar.v.amm','ar.v.amma','ar.v.muallim','ar.v.sinn','ar.v.khadd']::text[], array['ar.g10.sukun','ar.g11.long_vowels']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l13', 'ar', 2, 'Le tanwin : -an, -in, -un', 'Lire la voyelle finale doublée qui ajoute un n, et son alif muet.', 2, 13, 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.tanwin','ar.v.talib','ar.v.taliba','ar.v.tabib','ar.v.zawdja','ar.v.sadr','ar.v.zahr','ar.v.djabin']::text[], array['ar.g09.short_vowels','ar.g12.shadda']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l14', 'ar', 2, 'La hamza et le alif madda', 'Lire la hamza sur ses supports أ إ ؤ ئ ou seule (ء), et le alif madda آ.', 3, 14, 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.madda','ar.v.ab','ar.v.umm','ar.v.akh','ar.v.ukht','ar.v.ras','ar.v.udhun','ar.v.aila','ar.v.nisa','ar.v.imraa']::text[], array['ar.g11.long_vowels','ar.g10.sukun']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l15', 'ar', 2, 'L''article ال : lettres solaires et lunaires', 'Lire al-qamar mais ach-chams : savoir quand le l de l''article disparaît.', 3, 15, 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.v.lihya','ar.v.hadjib','ar.v.usra','ar.v.saq','ar.v.dam','ar.v.kaff','ar.v.dhaqn','ar.v.chaar']::text[], array['ar.g12.shadda','ar.g14.hamza_madda']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l16', 'ar', 2, 'Lire sans voyelles', 'Deviner les voyelles des mots courants quand le texte n''a pas de harakat.', 4, 16, 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.v.insan','ar.v.hafid','ar.v.zamil','ar.v.fatat','ar.v.chabb','ar.v.rukba','ar.v.azm','ar.v.ism']::text[], array['ar.g11.long_vowels','ar.g13.tanwin','ar.g15.article_sun_moon']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l17', 'ar', 3, 'Découper un mot en syllabes', 'Reconnaître les syllabes ouvertes (ba, bâ) et fermées (bal) pour lire un mot morceau par morceau.', 1, 17, 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.qamar','ar.v.djabal','ar.v.matar','ar.v.chadjara','ar.v.samak','ar.v.madrasa','ar.v.min','ar.v.fi']::text[], '{}'::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l18', 'ar', 3, 'La racine : trois lettres, une idée', 'Lire d''un coup les verbes de 3 lettres (كَتَبَ، دَرَسَ…) et retrouver la racine dans les mots de la même famille.', 2, 18, 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.kataba','ar.v.darasa','ar.v.dhahaba','ar.v.akala','ar.v.chariba','ar.v.fataha','ar.v.djalasa','ar.v.maktab']::text[], array['ar.g17.open_closed_syllables']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l19', 'ar', 3, 'Les coupures dans un mot', 'Repérer les 6 lettres qui ne s''attachent jamais à la lettre suivante (ا د ذ ر ز و) et ne plus prendre une coupure pour la fin du mot.', 2, 19, 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.warda','ar.v.aruzz','ar.v.barid','ar.v.harr','ar.v.madina','ar.v.chari','ar.v.ila','ar.v.wa']::text[], array['ar.g17.open_closed_syllables','ar.g18.three_letter_roots']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l20', 'ar', 3, 'Les mots longs, bloc par bloc', 'Lire les mots de 4 à 6 lettres en les découpant en blocs attachés, sans épeler lettre par lettre.', 3, 20, 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.mustachfa','ar.v.matam','ar.v.sayyara','ar.v.matar_aeroport','ar.v.burtuqal','ar.v.tuffaha','ar.v.sabah','ar.v.masa','ar.v.ala','ar.v.kabir']::text[], array['ar.g17.open_closed_syllables','ar.g19.non_connecting_letters']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l21', 'ar', 3, 'Les lettres jumelles', 'Distinguer au premier coup d''œil les lettres qui ne diffèrent que par leurs points : ب ت ث ن ي, ج ح خ, د ذ, ر ز, س ش, ص ض, ط ظ, ع غ, ف ق.', 3, 21, 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.khubz','ar.v.djubn','ar.v.halib','ar.v.sayf','ar.v.thaldj','ar.v.chay','ar.v.bayd','ar.v.suq','ar.v.saghir']::text[], array['ar.g19.non_connecting_letters','ar.g20.long_words_blocks']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l22', 'ar', 3, 'Les mots qu''on voit partout', 'Reconnaître d''un seul coup d''œil les petits mots les plus fréquents de l''arabe : هٰذَا، هِيَ، أَنَا، لَا، نَعَمْ, etc.', 2, 22, 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.hadha','ar.v.hadhihi','ar.v.huwa','ar.v.hiya','ar.v.ana','ar.v.anta','ar.v.la','ar.v.naam','ar.v.maa_avec','ar.v.huna']::text[], array['ar.g17.open_closed_syllables','ar.g19.non_connecting_letters']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l23', 'ar', 3, 'Lire une phrase d''un trait', 'Lire des phrases courtes entièrement vocalisées en reconnaissant les mots d''un coup, avec l''article الـ et les terminaisons.', 3, 23, 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.kana','ar.v.alladhi','ar.v.al_yawm','ar.v.djamil','ar.v.bayt','ar.v.bahr','ar.v.djadid','ar.v.qahwa']::text[], array['ar.g22.frequent_words','ar.g20.long_words_blocks']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l24', 'ar', 3, 'Lecture rapide', 'Tout mélanger : syllabes, racines, coupures, mots longs, lettres jumelles, petits mots et phrases, en lisant le plus vite possible.', 4, 24, 'ar.g24.speed_reading', array['ar.g24.speed_reading','ar.v.layl','ar.v.nahar','ar.v.chita','ar.v.nadjm','ar.v.maa_eau','ar.v.chams','ar.v.rih','ar.v.ghayma']::text[], array['ar.g23.short_sentences','ar.g21.lookalike_letters','ar.g20.long_words_blocks','ar.g19.non_connecting_letters']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l25', 'ar', 4, 'La foi : Dieu, le Christ, la Trinité', 'Lire les mots du Credo (الرَّبّ، الْمَسِيح، الْآب، الرُّوح الْقُدُس) en appliquant la règle de ال solaire et lunaire.', 2, 25, 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.allah','ar.v.rabb','ar.v.yasu','ar.v.masih','ar.v.al_ab','ar.v.ruh_al_qudus','ar.v.thaluth','ar.v.bismi']::text[], array['ar.g15.article_sun_moon','ar.g12.shadda','ar.v.ibn','ar.v.ism']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l26', 'ar', 4, 'Dans l''église : l''autel, les icônes, l''encens', 'Lire les objets de l''église (كَنِيسَة، هَيْكَل، أَيْقُونَة، بَخُور) : la fin en ة et les diphtongues ay / aw.', 2, 26, 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.kanisa','ar.v.haykal','ar.v.madhbah','ar.v.ayquna','ar.v.bakhur','ar.v.chamaa','ar.v.qurban','ar.v.abouna','ar.v.salib','ar.v.mawiza']::text[], array['ar.g25.al_solaire_lunaire','ar.v.rabb','ar.v.masih']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l27', 'ar', 4, 'La messe (الْقُدَّاس) et ses lectures', 'Lire le nom des lectures du qoddâs (الْبُولُس، الْكَاثُولِيكُون، الْإِبْرَكْسِيس، السِّنَكْسَار، الْإِنْجِيل) et de la tasbiha, et repérer leurs voyelles longues.', 2, 27, 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.quddas','ar.v.indjil','ar.v.bulus','ar.v.katholikon','ar.v.ibraksis','ar.v.sinaksar','ar.v.mazmur','ar.v.rasul','ar.v.tasbiha']::text[], array['ar.g25.al_solaire_lunaire','ar.g26.ta_marbuta_diphtongues','ar.v.abouna']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l28', 'ar', 4, 'La Bible et les prophéties', 'Lire الْكِتَاب الْمُقَدَّس, l''Ancien et le Nouveau Testament, les prophéties : nom + adjectif avec ال et pluriel en ـَات.', 3, 28, 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.kitab_muqaddas','ar.v.ahd_qadim','ar.v.ahd_djadid','ar.v.nebowat','ar.v.nabi','ar.v.sifr','ar.v.bichara','ar.v.aya','ar.v.ashah']::text[], array['ar.g27.voyelles_longues_mots_grecs','ar.g26.ta_marbuta_diphtongues','ar.v.indjil','ar.v.djadid']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l29', 'ar', 4, 'Fêtes et jeûnes coptes', 'Lire le nom des fêtes et des jeûnes (عِيد الْمِيلَاد، الصَّوْم الْكَبِير، أُسْبُوع الْآلَام) : l''annexion (iDâfa).', 3, 29, 'ar.g29.idafa', array['ar.g29.idafa','ar.v.eid','ar.v.eid_al_milad','ar.v.eid_al_qiyama','ar.v.ghitas','ar.v.ahad_al_chaanin','ar.v.sawm_kabir','ar.v.usbu_al_alam','ar.v.khamasin','ar.v.sawm']::text[], array['ar.g28.nom_adjectif','ar.g26.ta_marbuta_diphtongues','ar.v.masih']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l30', 'ar', 4, 'Les saints et le clergé', 'Lire les noms des saints et du clergé (قِدِّيس، شَهِيد، الْعَذْرَاء مَرْيَم، شَمَّاس) : la chadda et la hamza finale.', 3, 30, 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.qiddis','ar.v.chahid','ar.v.adhra_maryam','ar.v.mar_marqus','ar.v.mar_girgis','ar.v.baba','ar.v.usquf','ar.v.rahib','ar.v.chammas','ar.v.kahin']::text[], array['ar.g29.idafa','ar.g25.al_solaire_lunaire','ar.v.abouna']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l31', 'ar', 4, 'Prières et réponses de la liturgie', 'Lire et comprendre les réponses du qoddâs (يَا رَبُّ ارْحَمْ، آمِين، وَلِرُوحِكَ أَيْضًا) : يَا, les pronoms attachés et le ا qu''on ne prononce pas.', 3, 31, 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.ya_rabb_irham','ar.v.amin','ar.v.al_madjd_lak','ar.v.as_salam_lil_kull','ar.v.wa_li_ruhika','ar.v.abana','ar.v.quddus','ar.v.sallu','ar.v.halleluia','ar.v.ajbiyya']::text[], array['ar.g25.al_solaire_lunaire','ar.g30.chadda_hamza','ar.v.bismi','ar.v.alladhi']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l32', 'ar', 4, 'Lire des versets courts', 'Lire d''un trait des versets très courts de la Bible Van Dyck (« اللّٰهُ مَحَبَّةٌ », « أَنَا هُوَ الرَّاعِي الصَّالِحُ ») : tanwîn et pause en fin de phrase.', 3, 32, 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.mahabba','ar.v.rai','ar.v.salih','ar.v.nur','ar.v.tariq','ar.v.haqq','ar.v.hayat','ar.v.kalima','ar.v.alam']::text[], array['ar.g31.ya_pronoms_attaches','ar.g28.nom_adjectif','ar.g13.tanwin','ar.v.ana','ar.v.huwa']::text[], '2026.10.22', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e01', 'ar', 'ar.l01', 'ar.v.ba', array['ar.v.ba','ar.g01.alif_ba_ta_tha']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : ـبـ ?', array['bâ'' (b)']::text[], 'Une dent avec un seul point en dessous : c''est ب. Elle est attachée des deux côtés, c''est donc sa forme du milieu (ـبـ).', 1, '{"id": "ar.l01.e01", "unitIds": ["ar.v.ba", "ar.g01.alif_ba_ta_tha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : ـبـ ?", "promptLanguage": "fr", "options": ["bâ'' (b)", "tâ'' (t)", "thâ'' (th)", "alif (â)"], "answer": "bâ'' (b)", "acceptedAnswers": ["bâ'' (b)"], "hint": "Regarde où est le point.", "explanation": "Une dent avec un seul point en dessous : c''est ب. Elle est attachée des deux côtés, c''est donc sa forme du milieu (ـبـ).", "tip": "Un point dessous = b.", "extraExample": {"text": "شُبَّاك", "translation": "la fenêtre (ب au milieu)", "transliteration": "chubbâk"}, "errorPatterns": [{"equals": "tâ'' (t)", "category": "spelling", "feedback": "ت a deux points, au-dessus. Ici il n''y a qu''un point, en dessous : c''est ب."}, {"equals": "thâ'' (th)", "category": "spelling", "feedback": "ث a trois points au-dessus. Un seul point dessous, c''est ب."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e02', 'ar', 'ar.l01', 'ar.v.ta', array['ar.v.ta','ar.g01.alif_ba_ta_tha']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : تـ ?', array['tâ'' (t)']::text[], 'Une dent avec deux points au-dessus : c''est ت. Elle n''est attachée qu''à gauche : c''est sa forme du début (تـ).', 1, '{"id": "ar.l01.e02", "unitIds": ["ar.v.ta", "ar.g01.alif_ba_ta_tha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : تـ ?", "promptLanguage": "fr", "options": ["bâ'' (b)", "tâ'' (t)", "thâ'' (th)", "alif (â)"], "answer": "tâ'' (t)", "acceptedAnswers": ["tâ'' (t)"], "hint": "Compte les points.", "explanation": "Une dent avec deux points au-dessus : c''est ت. Elle n''est attachée qu''à gauche : c''est sa forme du début (تـ).", "tip": "Deux points dessus = t.", "extraExample": {"text": "تِين", "translation": "les figues (ت au début)", "transliteration": "tîn"}, "errorPatterns": [{"equals": "bâ'' (b)", "category": "spelling", "feedback": "ب a un seul point, en dessous. Ici il y a deux points au-dessus : c''est ت."}, {"equals": "thâ'' (th)", "category": "spelling", "feedback": "ث a trois points. Ici il n''y en a que deux : c''est ت."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e03', 'ar', 'ar.l01', 'ar.v.tha', array['ar.v.tha','ar.g01.alif_ba_ta_tha']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : ـث ?', array['thâ'' (th)']::text[], 'Une cuvette avec trois points au-dessus : c''est ث. Elle est attachée seulement à droite : c''est sa forme de fin (ـث).', 1, '{"id": "ar.l01.e03", "unitIds": ["ar.v.tha", "ar.g01.alif_ba_ta_tha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : ـث ?", "promptLanguage": "fr", "options": ["bâ'' (b)", "tâ'' (t)", "thâ'' (th)", "alif (â)"], "answer": "thâ'' (th)", "acceptedAnswers": ["thâ'' (th)"], "explanation": "Une cuvette avec trois points au-dessus : c''est ث. Elle est attachée seulement à droite : c''est sa forme de fin (ـث).", "tip": "Trois points dessus = th (comme dans « think »).", "extraExample": {"text": "ثَوْب", "translation": "le vêtement (ث au début)", "transliteration": "thawb"}, "errorPatterns": [{"equals": "tâ'' (t)", "category": "spelling", "feedback": "Compte bien : trois points, pas deux. Deux points, ce serait ت."}, {"equals": "bâ'' (b)", "category": "spelling", "feedback": "ب a un seul point, en dessous. Ici il y a trois points au-dessus : c''est ث."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e04', 'ar', 'ar.l01', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.v.ba','ar.v.ta','ar.v.tha','ar.v.alif']::text[], 'match', 'lesson', 'Quatre lettres, quatre formes', '{}'::text[], 'بـ (un point dessous) = b, ـتـ (deux points dessus) = t, ـث (trois points dessus) = th, ـا (trait vertical attaché à droite) = alif.', 1, '{"id": "ar.l01.e04", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.v.ba", "ar.v.ta", "ar.v.tha", "ar.v.alif"], "type": "match", "difficulty": 1, "instruction": "Associe chaque forme au nom de sa lettre.", "prompt": "Quatre lettres, quatre formes", "promptLanguage": "fr", "pairs": [{"left": "بـ", "right": "bâ'' (b)"}, {"left": "ـتـ", "right": "tâ'' (t)"}, {"left": "ـث", "right": "thâ'' (th)"}, {"left": "ـا", "right": "alif (â)"}], "answer": "بـ = bâ'' (b) ; ـتـ = tâ'' (t) ; ـث = thâ'' (th) ; ـا = alif (â)", "acceptedAnswers": [], "explanation": "بـ (un point dessous) = b, ـتـ (deux points dessus) = t, ـث (trois points dessus) = th, ـا (trait vertical attaché à droite) = alif.", "tip": "Pour ب ت ث, seul le nombre et la place des points comptent.", "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e05', 'ar', 'ar.l01', 'ar.v.alif', array['ar.v.alif','ar.g01.alif_ba_ta_tha']::text[], 'mcq', 'lesson', 'Quelle lettre ne s''attache jamais à la lettre qui la suit ?', array['ا']::text[], 'Alif s''accroche à la lettre d''avant (ـا) mais jamais à celle d''après. ب ت ث, elles, s''attachent des deux côtés.', 1, '{"id": "ar.l01.e05", "unitIds": ["ar.v.alif", "ar.g01.alif_ba_ta_tha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre ne s''attache jamais à la lettre qui la suit ?", "promptLanguage": "fr", "options": ["ا", "ب", "ت", "ث"], "answer": "ا", "acceptedAnswers": ["ا"], "explanation": "Alif s''accroche à la lettre d''avant (ـا) mais jamais à celle d''après. ب ت ث, elles, s''attachent des deux côtés.", "tip": "Après un ا, la lettre suivante recommence comme au début d''un mot.", "extraExample": {"text": "كِتَاب", "translation": "le livre : كِتَا puis ب isolé", "transliteration": "kitâb"}, "errorPatterns": [{"equals": "ب", "category": "grammar", "feedback": "ب s''attache des deux côtés : بـ au début, ـبـ au milieu. C''est ا qui ne s''attache jamais à la suivante."}, {"equals": "ت", "category": "grammar", "feedback": "ت s''attache des deux côtés (تـ, ـتـ). C''est ا qui coupe le mot."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e06', 'ar', 'ar.l01', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.v.ta']::text[], 'mcq', 'lesson', 'Quelle est la forme de ت au milieu d''un mot ?', array['ـتـ']::text[], 'Au milieu d''un mot, la lettre est attachée des deux côtés : un trait de liaison à droite et à gauche, ـتـ.', 2, '{"id": "ar.l01.e06", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.v.ta"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme.", "prompt": "Quelle est la forme de ت au milieu d''un mot ?", "promptLanguage": "fr", "options": ["ـتـ", "تـ", "ـت", "ت"], "answer": "ـتـ", "acceptedAnswers": ["ـتـ"], "explanation": "Au milieu d''un mot, la lettre est attachée des deux côtés : un trait de liaison à droite et à gauche, ـتـ.", "tip": "Milieu = attachée des deux côtés : ـتـ.", "extraExample": {"text": "كِتَاب", "translation": "le livre (ت au milieu)", "transliteration": "kitâb"}, "errorPatterns": [{"equals": "تـ", "category": "spelling", "feedback": "تـ est la forme du début : attachée seulement à gauche, vers la lettre suivante."}, {"equals": "ـت", "category": "spelling", "feedback": "ـت est la forme de fin : attachée seulement à droite, à la lettre d''avant."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e07', 'ar', 'ar.l01', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.v.ba','ar.v.ta','ar.v.tha','ar.v.alif']::text[], 'match', 'lesson', 'Du milieu du mot à la lettre seule', '{}'::text[], 'Au milieu, ب ت ث perdent leur cuvette et deviennent une petite dent, mais gardent leurs points. Alif reste un trait vertical.', 2, '{"id": "ar.l01.e07", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.v.ba", "ar.v.ta", "ar.v.tha", "ar.v.alif"], "type": "match", "difficulty": 2, "instruction": "Associe chaque forme du milieu à la lettre isolée.", "prompt": "Du milieu du mot à la lettre seule", "promptLanguage": "fr", "pairs": [{"left": "ـبـ", "right": "ب"}, {"left": "ـتـ", "right": "ت"}, {"left": "ـثـ", "right": "ث"}, {"left": "ـا", "right": "ا"}], "answer": "ـبـ = ب ; ـتـ = ت ; ـثـ = ث ; ـا = ا", "acceptedAnswers": [], "explanation": "Au milieu, ب ت ث perdent leur cuvette et deviennent une petite dent, mais gardent leurs points. Alif reste un trait vertical.", "tip": "Les points ne bougent jamais : ils suivent la lettre dans toutes ses formes.", "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e08', 'ar', 'ar.l01', 'ar.v.bab', array['ar.v.bab','ar.g01.alif_ba_ta_tha']::text[], 'mcq', 'lesson', 'Comment se lit بَاب ?', array['bâb']::text[], 'Deux ب (un point dessous chacun) autour d''un ا qui allonge le a : bâb, « la porte ».', 2, '{"id": "ar.l01.e08", "unitIds": ["ar.v.bab", "ar.g01.alif_ba_ta_tha"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit بَاب ?", "promptLanguage": "fr", "options": ["bâb", "tâb", "bât", "thâb"], "answer": "bâb", "acceptedAnswers": ["bâb"], "hint": "Regarde les points des deux lettres qui entourent ا.", "explanation": "Deux ب (un point dessous chacun) autour d''un ا qui allonge le a : bâb, « la porte ».", "tip": "ا après un a = son â long.", "extraExample": {"text": "أَبْوَاب", "translation": "des portes", "transliteration": "abwâb"}, "errorPatterns": [{"equals": "tâb", "category": "spelling", "feedback": "La première lettre a un point dessous : c''est ب (b), pas ت."}, {"equals": "bât", "category": "spelling", "feedback": "La dernière lettre a un point dessous : c''est encore ب (b), pas ت (deux points dessus)."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e09', 'ar', 'ar.l01', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.v.alif','ar.v.bab']::text[], 'mcq', 'lesson', 'Dans بَاب, pourquoi le second ب n''est-il pas attaché ?', array['Parce que ا ne s''attache jamais à la lettre suivante']::text[], 'ا coupe toujours le mot : la lettre qui le suit commence un nouveau morceau. À la fin du mot, elle prend donc sa forme isolée (ب) et non sa forme de fin attachée (ـب).', 2, '{"id": "ar.l01.e09", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.v.alif", "ar.v.bab"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne explication.", "prompt": "Dans بَاب, pourquoi le second ب n''est-il pas attaché ?", "promptLanguage": "fr", "options": ["Parce que ا ne s''attache jamais à la lettre suivante", "Parce que ب ne s''attache jamais à gauche", "Parce que c''est la dernière lettre du mot", "Parce qu''il porte un a long"], "answer": "Parce que ا ne s''attache jamais à la lettre suivante", "acceptedAnswers": ["Parce que ا ne s''attache jamais à la lettre suivante"], "explanation": "ا coupe toujours le mot : la lettre qui le suit commence un nouveau morceau. À la fin du mot, elle prend donc sa forme isolée (ب) et non sa forme de fin attachée (ـب).", "tip": "Après ا, la lettre repart seule.", "extraExample": {"text": "كِتَاب", "translation": "le livre : le ب final est isolé lui aussi", "transliteration": "kitâb"}, "errorPatterns": [{"equals": "Parce que c''est la dernière lettre du mot", "category": "grammar", "feedback": "Une lettre finale peut être attachée (ـب, comme dans كُتُب). Ici, c''est ا qui empêche la liaison."}, {"equals": "Parce que ب ne s''attache jamais à gauche", "category": "grammar", "feedback": "ب s''attache des deux côtés (بـ, ـبـ). C''est ا qui ne s''attache pas à gauche."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e10', 'ar', 'ar.l01', 'ar.v.kitab', array['ar.v.kitab','ar.g01.alif_ba_ta_tha']::text[], 'mcq', 'lesson', 'Dans كِتَاب (le livre), quelle lettre vient juste après ك ?', array['tâ'' (t)']::text[], 'Après ك vient une dent avec deux points au-dessus, au milieu du mot : ـتـ, c''est ت. Le mot se lit kitâb.', 2, '{"id": "ar.l01.e10", "unitIds": ["ar.v.kitab", "ar.g01.alif_ba_ta_tha"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Dans كِتَاب (le livre), quelle lettre vient juste après ك ?", "promptLanguage": "fr", "options": ["tâ'' (t)", "bâ'' (b)", "thâ'' (th)", "alif (â)"], "answer": "tâ'' (t)", "acceptedAnswers": ["tâ'' (t)"], "explanation": "Après ك vient une dent avec deux points au-dessus, au milieu du mot : ـتـ, c''est ت. Le mot se lit kitâb.", "tip": "Au milieu, regarde les points de la dent.", "extraExample": {"text": "كُتُب", "translation": "des livres (ت au milieu)", "transliteration": "kutub"}, "errorPatterns": [{"equals": "bâ'' (b)", "category": "spelling", "feedback": "ب a son point en dessous. Ici les deux points sont au-dessus : c''est ت (kitâb)."}, {"equals": "thâ'' (th)", "category": "spelling", "feedback": "Deux points, pas trois : c''est ت. Avec ث on lirait « kithâb »."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e11', 'ar', 'ar.l01', 'ar.v.thawb', array['ar.v.thawb','ar.g01.alif_ba_ta_tha']::text[], 'mcq', 'lesson', 'Comment se lit ثَوْب ?', array['thawb']::text[], 'Trois points au-dessus de la première lettre : ث (th). Puis و (w) et un ب isolé, un point dessous. On lit thawb, « le vêtement ».', 2, '{"id": "ar.l01.e11", "unitIds": ["ar.v.thawb", "ar.g01.alif_ba_ta_tha"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit ثَوْب ?", "promptLanguage": "fr", "options": ["thawb", "tawb", "bawth", "thawt"], "answer": "thawb", "acceptedAnswers": ["thawb"], "explanation": "Trois points au-dessus de la première lettre : ث (th). Puis و (w) et un ب isolé, un point dessous. On lit thawb, « le vêtement ».", "tip": "ث se prononce avec la langue entre les dents, comme « think ».", "extraExample": {"text": "ثِيَاب", "translation": "des vêtements", "transliteration": "thiyâb"}, "errorPatterns": [{"equals": "tawb", "category": "spelling", "feedback": "La première lettre a trois points : c''est ث (th), pas ت (t)."}, {"equals": "thawt", "category": "spelling", "feedback": "La dernière lettre a un seul point dessous : c''est ب (b)."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e12', 'ar', 'ar.l01', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.v.athath']::text[], 'mcq', 'lesson', 'Dans أَثَاث (les meubles), sous quelle forme est le dernier ث ?', array['isolée']::text[], 'Le dernier ث vient juste après ا. Comme ا ne s''attache jamais à la suivante, ce ث n''est relié à rien : il prend sa forme isolée (ث).', 3, '{"id": "ar.l01.e12", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.v.athath"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne forme.", "prompt": "Dans أَثَاث (les meubles), sous quelle forme est le dernier ث ?", "promptLanguage": "fr", "options": ["isolée", "finale", "médiane", "initiale"], "answer": "isolée", "acceptedAnswers": ["isolée"], "explanation": "Le dernier ث vient juste après ا. Comme ا ne s''attache jamais à la suivante, ce ث n''est relié à rien : il prend sa forme isolée (ث).", "tip": "Après ا, une lettre finale est isolée, pas « finale attachée ».", "extraExample": {"text": "بَاب", "translation": "la porte : le dernier ب est isolé", "transliteration": "bâb"}, "errorPatterns": [{"equals": "finale", "category": "grammar", "feedback": "La forme finale (ـث) est attachée à la lettre d''avant. Ici, la lettre d''avant est ا, qui ne s''attache pas : ث est isolé."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e13', 'ar', 'ar.l01', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.v.bab','ar.v.kitab','ar.v.thawb','ar.v.athath']::text[], 'match', 'lesson', 'Des mots de la maison', '{}'::text[], 'بَاب (bâb) = la porte, كِتَاب (kitâb) = le livre, ثَوْب (thawb) = le vêtement, أَثَاث (athâth) = les meubles.', 2, '{"id": "ar.l01.e13", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.v.bab", "ar.v.kitab", "ar.v.thawb", "ar.v.athath"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Des mots de la maison", "promptLanguage": "fr", "pairs": [{"left": "بَاب", "right": "la porte"}, {"left": "كِتَاب", "right": "le livre"}, {"left": "ثَوْب", "right": "le vêtement"}, {"left": "أَثَاث", "right": "les meubles"}], "answer": "بَاب = la porte ; كِتَاب = le livre ; ثَوْب = le vêtement ; أَثَاث = les meubles", "acceptedAnswers": [], "explanation": "بَاب (bâb) = la porte, كِتَاب (kitâb) = le livre, ثَوْب (thawb) = le vêtement, أَثَاث (athâth) = les meubles.", "tip": "Lis d''abord les points : ils te donnent la lecture, donc le mot.", "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e14', 'ar', 'ar.l01', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.v.kitab']::text[], 'fill_blank', 'lesson', 'Le livre (kitâb) : كِـ___ـاب', array['ـتـ','ت']::text[], 'Kitâb a un t au milieu : ت, avec deux points au-dessus. Au milieu du mot, il prend la forme ـتـ : كِتَاب.', 2, '{"id": "ar.l01.e14", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.v.kitab"], "type": "fill_blank", "difficulty": 2, "instruction": "Choisis la lettre qui manque.", "prompt": "Le livre (kitâb) : كِـ___ـاب", "promptLanguage": "fr", "options": ["ـتـ", "ـبـ", "ـثـ"], "answer": "ـتـ", "acceptedAnswers": ["ـتـ", "ت"], "explanation": "Kitâb a un t au milieu : ت, avec deux points au-dessus. Au milieu du mot, il prend la forme ـتـ : كِتَاب.", "tip": "Le son t = deux points au-dessus.", "extraExample": {"text": "كُتُب", "translation": "des livres", "transliteration": "kutub"}, "errorPatterns": [{"equals": "ـبـ", "category": "spelling", "feedback": "ـبـ (un point dessous) donnerait « kibâb ». Pour le son t, il faut ـتـ."}, {"equals": "ـثـ", "category": "spelling", "feedback": "ـثـ (trois points) donnerait « kithâb ». Pour le son t, il faut deux points : ـتـ."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e15', 'ar', 'ar.l01', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.v.ba']::text[], 'fill_blank', 'lesson', 'Dans كُتُب (des livres), le ب est en forme ___.', array['finale','final','de fin','fin','forme finale']::text[], 'Dans كُتُب, le ب est la dernière lettre et il est attaché au ت d''avant : c''est sa forme finale, ـب.', 3, '{"id": "ar.l01.e15", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.v.ba"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le nom de la forme : initiale, médiane, finale ou isolée.", "prompt": "Dans كُتُب (des livres), le ب est en forme ___.", "promptLanguage": "fr", "options": ["initiale", "médiane", "finale", "isolée"], "answer": "finale", "acceptedAnswers": ["finale", "final", "de fin", "fin", "forme finale"], "explanation": "Dans كُتُب, le ب est la dernière lettre et il est attaché au ت d''avant : c''est sa forme finale, ـب.", "tip": "Dernière lettre + attachée à droite = forme finale.", "extraExample": {"text": "مَكْتَب", "translation": "le bureau (ب final attaché)", "transliteration": "maktab"}, "errorPatterns": [{"equals": "isolée", "category": "grammar", "feedback": "Le ب est relié au ت qui le précède : il n''est pas isolé, il est en forme finale (ـب)."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e16', 'ar', 'ar.l01', 'ar.v.tha', array['ar.v.tha','ar.g01.alif_ba_ta_tha','ar.v.thawb']::text[], 'fill_blank', 'lesson', 'Le vêtement (thawb) : ___ـوْب', array['ثـ','ث']::text[], 'Thawb commence par le son th : ث, trois points au-dessus. Au début du mot, il prend la forme ثـ : ثَوْب.', 3, '{"id": "ar.l01.e16", "unitIds": ["ar.v.tha", "ar.g01.alif_ba_ta_tha", "ar.v.thawb"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la lettre qui manque.", "prompt": "Le vêtement (thawb) : ___ـوْب", "promptLanguage": "fr", "options": ["ثـ", "تـ", "بـ"], "answer": "ثـ", "acceptedAnswers": ["ثـ", "ث"], "explanation": "Thawb commence par le son th : ث, trois points au-dessus. Au début du mot, il prend la forme ثـ : ثَوْب.", "tip": "Th = trois points.", "extraExample": {"text": "ثِيَاب", "translation": "des vêtements", "transliteration": "thiyâb"}, "errorPatterns": [{"equals": "تـ", "category": "spelling", "feedback": "تـ (deux points) se lit t : on lirait « tawb ». Il faut ثـ, trois points."}, {"equals": "بـ", "category": "spelling", "feedback": "بـ (un point dessous) se lit b. Pour th, il faut ثـ."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e17', 'ar', 'ar.l01', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.v.bab']::text[], 'reorder', 'lesson', 'Écris « bâb » (la porte) avec ces lettres.', array['ب ا ب']::text[], 'Bâb : ب (b), ا (â long), ب (b). Attachées, ces lettres donnent بَاب, avec un ب final isolé après ا.', 2, '{"id": "ar.l01.e17", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.v.bab"], "type": "reorder", "difficulty": 2, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « bâb » (la porte) avec ces lettres.", "promptLanguage": "fr", "tokens": ["ا", "ب", "ب"], "answer": "ب ا ب", "acceptedAnswers": ["ب ا ب"], "explanation": "Bâb : ب (b), ا (â long), ب (b). Attachées, ces lettres donnent بَاب, avec un ب final isolé après ا.", "tip": "On lit et on écrit l''arabe de droite à gauche : la première lettre est à droite.", "extraExample": {"text": "بَابِي", "translation": "ma porte", "transliteration": "bâbî"}, "pool": "lesson", "lessonId": "ar.l01", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e18', 'ar', 'ar.l01', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.v.athath']::text[], 'reorder', 'lesson', 'Écris « athâth » (les meubles) avec ces lettres.', array['أ ث ا ث']::text[], 'Athâth : أ (a, alif avec hamza), ث (th), ا (â long), ث (th). Écrit : أَثَاث.', 3, '{"id": "ar.l01.e18", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.v.athath"], "type": "reorder", "difficulty": 3, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « athâth » (les meubles) avec ces lettres.", "promptLanguage": "fr", "tokens": ["ث", "ا", "ث", "أ"], "answer": "أ ث ا ث", "acceptedAnswers": ["أ ث ا ث"], "explanation": "Athâth : أ (a, alif avec hamza), ث (th), ا (â long), ث (th). Écrit : أَثَاث.", "tip": "Le son a au début d''un mot s''écrit avec un alif portant une hamza : أ.", "extraExample": {"text": "أَثَاثِي", "translation": "mes meubles", "transliteration": "athâthî"}, "pool": "lesson", "lessonId": "ar.l01", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e19', 'ar', 'ar.l01', 'ar.v.bab', array['ar.v.bab','ar.g01.alif_ba_ta_tha']::text[], 'translation', 'lesson', 'بَاب', array['la porte','porte','une porte']::text[], 'بَاب se lit bâb et veut dire « la porte ». Deux ب entourent un ا qui allonge le a.', 2, '{"id": "ar.l01.e19", "unitIds": ["ar.v.bab", "ar.g01.alif_ba_ta_tha"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "بَاب", "promptLanguage": "ar", "answer": "la porte", "acceptedAnswers": ["la porte", "porte", "une porte"], "explanation": "بَاب se lit bâb et veut dire « la porte ». Deux ب entourent un ا qui allonge le a.", "tip": "Bâb, la porte : un mot à reconnaître d''un coup d''œil.", "extraExample": {"text": "أَبْوَاب", "translation": "des portes", "transliteration": "abwâb"}, "errorPatterns": [{"equals": "la maison", "category": "vocabulary", "feedback": "La maison se dit بَيْت (bayt). بَاب (bâb), c''est la porte."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e20', 'ar', 'ar.l01', 'ar.v.kitab', array['ar.v.kitab','ar.g01.alif_ba_ta_tha']::text[], 'translation', 'lesson', 'كِتَاب', array['le livre','livre','un livre']::text[], 'كِتَاب se lit kitâb et veut dire « le livre ».', 2, '{"id": "ar.l01.e20", "unitIds": ["ar.v.kitab", "ar.g01.alif_ba_ta_tha"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "كِتَاب", "promptLanguage": "ar", "answer": "le livre", "acceptedAnswers": ["le livre", "livre", "un livre"], "explanation": "كِتَاب se lit kitâb et veut dire « le livre ».", "tip": "Kitâb, le livre : le ت du milieu a deux points au-dessus.", "extraExample": {"text": "كِتَابِي", "translation": "mon livre", "transliteration": "kitâbî"}, "errorPatterns": [{"equals": "les livres", "category": "vocabulary", "feedback": "Ici, c''est le singulier : kitâb, le livre. Des livres se dit كُتُب (kutub)."}, {"equals": "des livres", "category": "vocabulary", "feedback": "Ici, c''est le singulier : kitâb, le livre. Des livres se dit كُتُب (kutub)."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e21', 'ar', 'ar.l01', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.v.ta']::text[], 'free_answer', 'lesson', 'Comment se lit كُتُب (des livres) ?', array['kutub','koutoub']::text[], 'ك (k) avec u, ت (t, deux points dessus) avec u, puis ب final (b) : kutub, « des livres ».', 3, '{"id": "ar.l01.e21", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.v.ta"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture en lettres latines (u pour le son « ou »).", "prompt": "Comment se lit كُتُب (des livres) ?", "promptLanguage": "fr", "answer": "kutub", "acceptedAnswers": ["kutub", "koutoub"], "explanation": "ك (k) avec u, ت (t, deux points dessus) avec u, puis ب final (b) : kutub, « des livres ».", "tip": "Le petit signe ُ au-dessus d''une lettre se lit u (« ou »).", "extraExample": {"text": "كِتَاب", "translation": "le livre", "transliteration": "kitâb"}, "errorPatterns": [{"equals": "kubut", "category": "spelling", "feedback": "Regarde les points : la lettre du milieu a deux points au-dessus (t), la dernière un point dessous (b) : kutub."}, {"equals": "kuthub", "category": "spelling", "feedback": "La lettre du milieu n''a que deux points : c''est ت (t), pas ث (th)."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e22', 'ar', 'ar.l01', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.v.athath','ar.v.tha']::text[], 'free_answer', 'lesson', 'Comment se lit أَثَاث (les meubles) ?', array['athâth','athath','athaath','''athâth','''athath','''athaath']::text[], 'أ (a), ث (th), ا (â long), ث (th) : athâth, « les meubles ». Les deux ث ont trois points au-dessus.', 4, '{"id": "ar.l01.e22", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.v.athath", "ar.v.tha"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines (â pour un a long).", "prompt": "Comment se lit أَثَاث (les meubles) ?", "promptLanguage": "fr", "answer": "athâth", "acceptedAnswers": ["athâth", "athath", "athaath", "''athâth", "''athath", "''athaath"], "explanation": "أ (a), ث (th), ا (â long), ث (th) : athâth, « les meubles ». Les deux ث ont trois points au-dessus.", "tip": "Trois points = th, jamais t.", "extraExample": {"text": "ثَوْب", "translation": "le vêtement", "transliteration": "thawb"}, "errorPatterns": [{"equals": "atât", "category": "spelling", "feedback": "Trois points au-dessus, c''est ث : th (comme « think »), pas t."}, {"equals": "atat", "category": "spelling", "feedback": "Trois points au-dessus, c''est ث : th (comme « think »), pas t."}, {"equals": "abâb", "category": "spelling", "feedback": "ث a trois points au-dessus (th) ; ب n''en a qu''un, en dessous."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e01', 'ar', 'ar.l02', 'ar.v.nun', array['ar.v.nun','ar.g02.nun_ya_five_teeth']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : نـ ?', array['nûn (n)']::text[], 'Une dent attachée à gauche, avec un seul point au-dessus : c''est ن, sous sa forme du début (نـ).', 1, '{"id": "ar.l02.e01", "unitIds": ["ar.v.nun", "ar.g02.nun_ya_five_teeth"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : نـ ?", "promptLanguage": "fr", "options": ["bâ'' (b)", "nûn (n)", "tâ'' (t)", "yâ'' (y, î)"], "answer": "nûn (n)", "acceptedAnswers": ["nûn (n)"], "hint": "Un seul point : où est-il ?", "explanation": "Une dent attachée à gauche, avec un seul point au-dessus : c''est ن, sous sa forme du début (نـ).", "tip": "Un point dessus = n.", "extraExample": {"text": "نَبَات", "translation": "la plante (ن au début)", "transliteration": "nabât"}, "errorPatterns": [{"equals": "bâ'' (b)", "category": "spelling", "feedback": "ب a son point en dessous. Ici il est au-dessus : c''est ن."}, {"equals": "tâ'' (t)", "category": "spelling", "feedback": "ت a deux points. Ici il n''y en a qu''un : c''est ن."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e02', 'ar', 'ar.l02', 'ar.v.ya', array['ar.v.ya','ar.g02.nun_ya_five_teeth']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : ـيـ ?', array['yâ'' (y, î)']::text[], 'Une dent attachée des deux côtés, avec deux points en dessous : c''est ي, sous sa forme du milieu (ـيـ).', 1, '{"id": "ar.l02.e02", "unitIds": ["ar.v.ya", "ar.g02.nun_ya_five_teeth"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : ـيـ ?", "promptLanguage": "fr", "options": ["bâ'' (b)", "tâ'' (t)", "nûn (n)", "yâ'' (y, î)"], "answer": "yâ'' (y, î)", "acceptedAnswers": ["yâ'' (y, î)"], "hint": "Compte les points, puis regarde où ils sont.", "explanation": "Une dent attachée des deux côtés, avec deux points en dessous : c''est ي, sous sa forme du milieu (ـيـ).", "tip": "Deux points dessous = y.", "extraExample": {"text": "بَيْنَ", "translation": "entre (ي au milieu)", "transliteration": "bayna"}, "errorPatterns": [{"equals": "tâ'' (t)", "category": "spelling", "feedback": "ت a aussi deux points, mais au-dessus. Ici ils sont en dessous : c''est ي."}, {"equals": "bâ'' (b)", "category": "spelling", "feedback": "ب n''a qu''un point. Ici il y en a deux, en dessous : c''est ي."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e03', 'ar', 'ar.l02', 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.nun']::text[], 'mcq', 'lesson', 'Quelle lettre a un seul point au-dessus de sa dent ?', array['ن']::text[], 'ن a un point au-dessus. ب a aussi un seul point, mais en dessous ; ت a deux points dessus ; ي a deux points dessous.', 1, '{"id": "ar.l02.e03", "unitIds": ["ar.g02.nun_ya_five_teeth", "ar.v.nun"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre a un seul point au-dessus de sa dent ?", "promptLanguage": "fr", "options": ["ب", "ت", "ن", "ي"], "answer": "ن", "acceptedAnswers": ["ن"], "hint": "Pense au n de « nuit ».", "explanation": "ن a un point au-dessus. ب a aussi un seul point, mais en dessous ; ت a deux points dessus ; ي a deux points dessous.", "tip": "Un seul point : dessous = ب, dessus = ن.", "extraExample": {"text": "تِين", "translation": "les figues (ن à la fin)", "transliteration": "tîn"}, "errorPatterns": [{"equals": "ب", "category": "spelling", "feedback": "ب n''a qu''un point, mais il est en dessous."}, {"equals": "ت", "category": "spelling", "feedback": "ت a deux points. Ici on cherche un seul point."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e04', 'ar', 'ar.l02', 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.nun','ar.v.ya','ar.v.tha','ar.v.ba']::text[], 'match', 'lesson', 'Des formes de ن ي ث ب à reconnaître', '{}'::text[], 'نـ (un point dessus) = n, ـيـ (deux points dessous) = y, ـث (trois points dessus) = th, ـبـ (un point dessous) = b.', 1, '{"id": "ar.l02.e04", "unitIds": ["ar.g02.nun_ya_five_teeth", "ar.v.nun", "ar.v.ya", "ar.v.tha", "ar.v.ba"], "type": "match", "difficulty": 1, "instruction": "Associe chaque forme au nom de sa lettre.", "prompt": "Des formes de ن ي ث ب à reconnaître", "promptLanguage": "fr", "pairs": [{"left": "نـ", "right": "nûn (n)"}, {"left": "ـيـ", "right": "yâ'' (y, î)"}, {"left": "ـث", "right": "thâ'' (th)"}, {"left": "ـبـ", "right": "bâ'' (b)"}], "answer": "نـ = nûn (n) ; ـيـ = yâ'' (y, î) ; ـث = thâ'' (th) ; ـبـ = bâ'' (b)", "acceptedAnswers": [], "explanation": "نـ (un point dessus) = n, ـيـ (deux points dessous) = y, ـث (trois points dessus) = th, ـبـ (un point dessous) = b.", "tip": "Compte les points, puis regarde où ils sont : c''est tout ce qui compte.", "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e05', 'ar', 'ar.l02', 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.tin']::text[], 'mcq', 'lesson', 'Comment se lit تِين ?', array['tîn']::text[], 'Deux points au-dessus de la première lettre : ت (t). Puis ي (î long) et ن (n). On lit tîn, « les figues ».', 2, '{"id": "ar.l02.e05", "unitIds": ["ar.g02.nun_ya_five_teeth", "ar.v.tin"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit تِين ?", "promptLanguage": "fr", "options": ["tîn", "nîn", "bîn", "yîn"], "answer": "tîn", "acceptedAnswers": ["tîn"], "hint": "Regarde les points de la première lettre.", "explanation": "Deux points au-dessus de la première lettre : ت (t). Puis ي (î long) et ن (n). On lit tîn, « les figues ».", "tip": "Première lettre : deux points dessus = t.", "extraExample": {"text": "شَجَرَةُ تِين", "translation": "un figuier", "transliteration": "chadjaratu tîn"}, "errorPatterns": [{"equals": "nîn", "category": "spelling", "feedback": "La première lettre a deux points au-dessus : c''est ت (t). Le ن est la dernière lettre."}, {"equals": "bîn", "category": "spelling", "feedback": "ب a un point en dessous. Ici les deux points sont au-dessus : c''est ت."}, {"equals": "yîn", "category": "spelling", "feedback": "Deux points au-dessus de la première lettre, c''est ت. Pour ي, ils seraient en dessous."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e06', 'ar', 'ar.l02', 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.ba','ar.v.ta','ar.v.tha','ar.v.nun','ar.v.ya']::text[], 'match', 'lesson', 'Compter les points', '{}'::text[], 'Cinq lettres, un seul corps : ب (1 dessous), ت (2 dessus), ث (3 dessus), ن (1 dessus), ي (2 dessous).', 2, '{"id": "ar.l02.e06", "unitIds": ["ar.g02.nun_ya_five_teeth", "ar.v.ba", "ar.v.ta", "ar.v.tha", "ar.v.nun", "ar.v.ya"], "type": "match", "difficulty": 2, "instruction": "Associe chaque description à sa lettre.", "prompt": "Compter les points", "promptLanguage": "fr", "pairs": [{"left": "1 point dessous", "right": "ب"}, {"left": "2 points dessus", "right": "ت"}, {"left": "3 points dessus", "right": "ث"}, {"left": "1 point dessus", "right": "ن"}, {"left": "2 points dessous", "right": "ي"}], "answer": "1 point dessous = ب ; 2 points dessus = ت ; 3 points dessus = ث ; 1 point dessus = ن ; 2 points dessous = ي", "acceptedAnswers": [], "explanation": "Cinq lettres, un seul corps : ب (1 dessous), ت (2 dessus), ث (3 dessus), ن (1 dessus), ي (2 dessous).", "tip": "Nombre de points, puis place des points : jamais le corps de la lettre.", "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e07', 'ar', 'ar.l02', 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.ba','ar.v.ya']::text[], 'mcq', 'lesson', 'Parmi ب ت ث ن ي, lesquelles ont leurs points en dessous ?', array['ب et ي']::text[], 'ب (1 point) et ي (2 points) ont leurs points sous la dent. ت, ث et ن les ont au-dessus.', 2, '{"id": "ar.l02.e07", "unitIds": ["ar.g02.nun_ya_five_teeth", "ar.v.ba", "ar.v.ya"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Parmi ب ت ث ن ي, lesquelles ont leurs points en dessous ?", "promptLanguage": "fr", "options": ["ب et ي", "ت et ن", "ث et ن", "ب et ت"], "answer": "ب et ي", "acceptedAnswers": ["ب et ي"], "explanation": "ب (1 point) et ي (2 points) ont leurs points sous la dent. ت, ث et ن les ont au-dessus.", "tip": "Dessous : seulement ب et ي. Tout le reste est dessus.", "extraExample": {"text": "بَيْنَ", "translation": "entre (ب et ي : points dessous)", "transliteration": "bayna"}, "errorPatterns": [{"equals": "ت et ن", "category": "spelling", "feedback": "Ce sont justement deux lettres dont les points sont au-dessus."}, {"equals": "ب et ت", "category": "spelling", "feedback": "ب a son point dessous, mais ت a ses deux points dessus."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e08', 'ar', 'ar.l02', 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.nun']::text[], 'mcq', 'lesson', 'Dans بَنَات (les filles), sous quelle forme est le ن ?', array['médiane']::text[], 'Le ن est entre ب, qui s''attache à lui, et ا, qui s''attache à lui aussi : il est relié des deux côtés, donc en forme du milieu (ـنـ).', 3, '{"id": "ar.l02.e08", "unitIds": ["ar.g02.nun_ya_five_teeth", "ar.v.nun"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne forme.", "prompt": "Dans بَنَات (les filles), sous quelle forme est le ن ?", "promptLanguage": "fr", "options": ["initiale", "médiane", "finale", "isolée"], "answer": "médiane", "acceptedAnswers": ["médiane"], "explanation": "Le ن est entre ب, qui s''attache à lui, et ا, qui s''attache à lui aussi : il est relié des deux côtés, donc en forme du milieu (ـنـ).", "tip": "Relié des deux côtés = forme du milieu.", "extraExample": {"text": "نَبَات", "translation": "la plante (ن au début)", "transliteration": "nabât"}, "errorPatterns": [{"equals": "isolée", "category": "grammar", "feedback": "Le ن est relié à ب et à ا : seule la lettre qui suit ا (le ت final) est isolée."}, {"equals": "initiale", "category": "grammar", "feedback": "La forme initiale est la première lettre du mot. Ici, ن vient après ب."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e09', 'ar', 'ar.l02', 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.banat']::text[], 'mcq', 'lesson', 'Comment se lit بَنَات ?', array['banât']::text[], 'ب (point dessous), ن (point dessus), ا (â long), ت (deux points dessus) : banât, « les filles ».', 3, '{"id": "ar.l02.e09", "unitIds": ["ar.g02.nun_ya_five_teeth", "ar.v.banat"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit بَنَات ?", "promptLanguage": "fr", "options": ["banât", "batât", "bayât", "nabât"], "answer": "banât", "acceptedAnswers": ["banât"], "hint": "Regarde où est le point de la deuxième lettre.", "explanation": "ب (point dessous), ن (point dessus), ا (â long), ت (deux points dessus) : banât, « les filles ».", "tip": "Un point dessous d''abord (b), puis un point dessus (n).", "extraExample": {"text": "بِنْت", "translation": "une fille", "transliteration": "bint"}, "errorPatterns": [{"equals": "nabât", "category": "spelling", "feedback": "C''est l''ordre inverse : la première lettre a son point dessous (ب), le ن ne vient qu''en deuxième."}, {"equals": "bayât", "category": "spelling", "feedback": "La deuxième lettre n''a qu''un point : c''est ن (n). ي en aurait deux, dessous."}, {"equals": "batât", "category": "spelling", "feedback": "La deuxième lettre a un seul point au-dessus : c''est ن. ت en aurait deux."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e10', 'ar', 'ar.l02', 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.bayna','ar.v.ya']::text[], 'fill_blank', 'lesson', 'Entre (bayna) : بَـ___ـنَ', array['ـيـ','ي']::text[], 'Bayna a un y au milieu : ي, deux points en dessous. À l''intérieur du mot, il prend la forme ـيـ : بَيْنَ.', 3, '{"id": "ar.l02.e10", "unitIds": ["ar.g02.nun_ya_five_teeth", "ar.v.bayna", "ar.v.ya"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la lettre qui manque.", "prompt": "Entre (bayna) : بَـ___ـنَ", "promptLanguage": "fr", "options": ["ـيـ", "ـتـ", "ـنـ"], "answer": "ـيـ", "acceptedAnswers": ["ـيـ", "ي"], "explanation": "Bayna a un y au milieu : ي, deux points en dessous. À l''intérieur du mot, il prend la forme ـيـ : بَيْنَ.", "tip": "Le son y = deux points dessous.", "extraExample": {"text": "بَيْت", "translation": "la maison (ي au milieu)", "transliteration": "bayt"}, "errorPatterns": [{"equals": "ـتـ", "category": "spelling", "feedback": "ـتـ (deux points dessus) donnerait « batna ». Pour le son y, les deux points sont dessous."}, {"equals": "ـنـ", "category": "spelling", "feedback": "ـنـ (un point dessus) donnerait « banna ». Il faut deux points dessous : ـيـ."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e11', 'ar', 'ar.l02', 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.nun','ar.v.tin']::text[], 'fill_blank', 'lesson', 'Dans تِين (les figues), le ن est en forme ___.', array['finale','final','de fin','fin','forme finale']::text[], 'Le ن est la dernière lettre du mot et il est relié au ي qui le précède : c''est sa forme finale, ـن.', 3, '{"id": "ar.l02.e11", "unitIds": ["ar.g02.nun_ya_five_teeth", "ar.v.nun", "ar.v.tin"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le nom de la forme : initiale, médiane, finale ou isolée.", "prompt": "Dans تِين (les figues), le ن est en forme ___.", "promptLanguage": "fr", "options": ["initiale", "médiane", "finale", "isolée"], "answer": "finale", "acceptedAnswers": ["finale", "final", "de fin", "fin", "forme finale"], "explanation": "Le ن est la dernière lettre du mot et il est relié au ي qui le précède : c''est sa forme finale, ـن.", "tip": "Dernière lettre + attachée à droite = forme finale.", "extraExample": {"text": "حَبِيب", "translation": "chéri (ب final attaché)", "transliteration": "7abîb"}, "errorPatterns": [{"equals": "isolée", "category": "grammar", "feedback": "Le ن est relié au ي : il n''est pas isolé, il est en forme finale (ـن)."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e12', 'ar', 'ar.l02', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.v.alif','ar.v.nabat']::text[], 'mcq', 'lesson', 'Dans نَبَات (la plante), à quelle lettre le ا est-il attaché ?', array['ب']::text[], 'ا s''accroche toujours à la lettre qui est avant lui : ici ب (ـبا). Il ne s''attache pas au ت qui le suit : ce ت est isolé.', 3, '{"id": "ar.l02.e12", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.v.alif", "ar.v.nabat"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lettre.", "prompt": "Dans نَبَات (la plante), à quelle lettre le ا est-il attaché ?", "promptLanguage": "fr", "options": ["ب", "ن", "ت", "ي"], "answer": "ب", "acceptedAnswers": ["ب"], "explanation": "ا s''accroche toujours à la lettre qui est avant lui : ici ب (ـبا). Il ne s''attache pas au ت qui le suit : ce ت est isolé.", "tip": "ا se colle à la lettre d''avant, jamais à celle d''après.", "extraExample": {"text": "بَنَات", "translation": "les filles", "transliteration": "banât"}, "errorPatterns": [{"equals": "ت", "category": "grammar", "feedback": "ت vient après ا, et ا ne s''attache jamais à la lettre suivante."}, {"equals": "ن", "category": "grammar", "feedback": "Le ن est la première lettre du mot ; ا est collé au ب qui le précède directement."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e13', 'ar', 'ar.l02', 'ar.v.kitab', array['ar.v.kitab','ar.g01.alif_ba_ta_tha']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit kitâb (le livre) ?', array['كِتَاب']::text[], 'Il faut deux points au-dessus de la dent du milieu : ت (t). كِنَاب aurait un point dessus (n), كِيَاب deux points dessous (y), كِبَاب un point dessous (b).', 3, '{"id": "ar.l02.e13", "unitIds": ["ar.v.kitab", "ar.g01.alif_ba_ta_tha"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se lit kitâb (le livre) ?", "promptLanguage": "fr", "options": ["كِتَاب", "كِنَاب", "كِيَاب", "كِبَاب"], "answer": "كِتَاب", "acceptedAnswers": ["كِتَاب"], "explanation": "Il faut deux points au-dessus de la dent du milieu : ت (t). كِنَاب aurait un point dessus (n), كِيَاب deux points dessous (y), كِبَاب un point dessous (b).", "tip": "Pour retrouver t : deux points, et au-dessus.", "extraExample": {"text": "كُتُب", "translation": "des livres", "transliteration": "kutub"}, "errorPatterns": [{"equals": "كِنَاب", "category": "spelling", "feedback": "Un seul point au-dessus, c''est ن : on lirait « kinâb »."}, {"equals": "كِيَاب", "category": "spelling", "feedback": "Deux points dessous, c''est ي : on lirait « kiyâb »."}, {"equals": "كِبَاب", "category": "spelling", "feedback": "Un point dessous, c''est ب : on lirait « kibâb »."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e14', 'ar', 'ar.l02', 'ar.v.thawb', array['ar.v.thawb','ar.g01.alif_ba_ta_tha']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit thawb (le vêtement) ?', array['ثَوْب']::text[], 'Il faut trois points au-dessus de la première lettre : ث (th). تَوْب aurait deux points (t), نَوْب un point (n), يَوْب deux points dessous (y).', 3, '{"id": "ar.l02.e14", "unitIds": ["ar.v.thawb", "ar.g01.alif_ba_ta_tha"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se lit thawb (le vêtement) ?", "promptLanguage": "fr", "options": ["ثَوْب", "تَوْب", "نَوْب", "يَوْب"], "answer": "ثَوْب", "acceptedAnswers": ["ثَوْب"], "explanation": "Il faut trois points au-dessus de la première lettre : ث (th). تَوْب aurait deux points (t), نَوْب un point (n), يَوْب deux points dessous (y).", "tip": "Trois points dessus = th.", "extraExample": {"text": "ثِيَاب", "translation": "des vêtements", "transliteration": "thiyâb"}, "errorPatterns": [{"equals": "تَوْب", "category": "spelling", "feedback": "Deux points seulement : on lirait « tawb ». Pour th, il en faut trois."}, {"equals": "نَوْب", "category": "spelling", "feedback": "Un seul point : on lirait « nawb ». Pour th, il en faut trois."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e15', 'ar', 'ar.l02', 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.tin','ar.v.banat','ar.v.nabat','ar.v.bayna']::text[], 'match', 'lesson', 'Quatre mots à lire d''un coup d''œil', '{}'::text[], 'تِين (tîn) = les figues, بَنَات (banât) = les filles, نَبَات (nabât) = la plante, بَيْنَ (bayna) = entre.', 2, '{"id": "ar.l02.e15", "unitIds": ["ar.g02.nun_ya_five_teeth", "ar.v.tin", "ar.v.banat", "ar.v.nabat", "ar.v.bayna"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Quatre mots à lire d''un coup d''œil", "promptLanguage": "fr", "pairs": [{"left": "تِين", "right": "les figues"}, {"left": "بَنَات", "right": "les filles"}, {"left": "نَبَات", "right": "la plante"}, {"left": "بَيْنَ", "right": "entre"}], "answer": "تِين = les figues ; بَنَات = les filles ; نَبَات = la plante ; بَيْنَ = entre", "acceptedAnswers": [], "explanation": "تِين (tîn) = les figues, بَنَات (banât) = les filles, نَبَات (nabât) = la plante, بَيْنَ (bayna) = entre.", "tip": "Lis les points avant de deviner : ils te donnent la lecture, donc le mot.", "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e16', 'ar', 'ar.l02', 'ar.v.tin', array['ar.v.tin','ar.g02.nun_ya_five_teeth']::text[], 'reorder', 'lesson', 'Écris « tîn » (les figues) avec ces lettres.', array['ت ي ن']::text[], 'Tîn : ت (t), ي (î long), ن (n). Attachées, ces lettres donnent تِين.', 2, '{"id": "ar.l02.e16", "unitIds": ["ar.v.tin", "ar.g02.nun_ya_five_teeth"], "type": "reorder", "difficulty": 2, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « tîn » (les figues) avec ces lettres.", "promptLanguage": "fr", "tokens": ["ن", "ت", "ي"], "answer": "ت ي ن", "acceptedAnswers": ["ت ي ن"], "explanation": "Tîn : ت (t), ي (î long), ن (n). Attachées, ces lettres donnent تِين.", "tip": "On lit de droite à gauche : la première lettre est à droite.", "extraExample": {"text": "تِينَة", "translation": "une figue", "transliteration": "tîna"}, "pool": "lesson", "lessonId": "ar.l02", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e17', 'ar', 'ar.l02', 'ar.v.bayna', array['ar.v.bayna','ar.g02.nun_ya_five_teeth']::text[], 'reorder', 'lesson', 'Écris « bayna » (entre) avec ces lettres.', array['ب ي ن']::text[], 'Bayna : ب (b), ي (y), ن (n). Écrit avec les voyelles : بَيْنَ.', 3, '{"id": "ar.l02.e17", "unitIds": ["ar.v.bayna", "ar.g02.nun_ya_five_teeth"], "type": "reorder", "difficulty": 3, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « bayna » (entre) avec ces lettres.", "promptLanguage": "fr", "tokens": ["ن", "ب", "ي"], "answer": "ب ي ن", "acceptedAnswers": ["ب ي ن"], "explanation": "Bayna : ب (b), ي (y), ن (n). Écrit avec les voyelles : بَيْنَ.", "tip": "Les points te disent l''ordre : un dessous, deux dessous, un dessus.", "extraExample": {"text": "بَيْنِي وَبَيْنَكَ", "translation": "entre moi et toi", "transliteration": "baynî wa-baynaka"}, "pool": "lesson", "lessonId": "ar.l02", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e18', 'ar', 'ar.l02', 'ar.v.tin', array['ar.v.tin','ar.g02.nun_ya_five_teeth']::text[], 'translation', 'lesson', 'تِين', array['les figues','figues','des figues','la figue']::text[], 'تِين se lit tîn et veut dire « les figues » : ت, ي, ن.', 2, '{"id": "ar.l02.e18", "unitIds": ["ar.v.tin", "ar.g02.nun_ya_five_teeth"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "تِين", "promptLanguage": "ar", "answer": "les figues", "acceptedAnswers": ["les figues", "figues", "des figues", "la figue"], "explanation": "تِين se lit tîn et veut dire « les figues » : ت, ي, ن.", "tip": "Tîn : deux points dessus au début, un point dessus à la fin.", "extraExample": {"text": "تِينَة", "translation": "une figue", "transliteration": "tîna"}, "errorPatterns": [{"equals": "les filles", "category": "vocabulary", "feedback": "Les filles se dit بَنَات (banât). تِين commence par ت (deux points dessus) : tîn, les figues."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e19', 'ar', 'ar.l02', 'ar.v.nabat', array['ar.v.nabat','ar.g02.nun_ya_five_teeth']::text[], 'translation', 'lesson', 'نَبَات', array['la plante','plante','une plante','les plantes','la végétation','végétation']::text[], 'نَبَات se lit nabât et veut dire « la plante », la végétation en général : ن, ب, ا, ت.', 3, '{"id": "ar.l02.e19", "unitIds": ["ar.v.nabat", "ar.g02.nun_ya_five_teeth"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "نَبَات", "promptLanguage": "ar", "answer": "la plante", "acceptedAnswers": ["la plante", "plante", "une plante", "les plantes", "la végétation", "végétation"], "explanation": "نَبَات se lit nabât et veut dire « la plante », la végétation en général : ن, ب, ا, ت.", "tip": "Nabât commence par un point dessus (n), pas dessous.", "extraExample": {"text": "نَبَاتَات", "translation": "des plantes", "transliteration": "nabâtât"}, "errorPatterns": [{"equals": "les filles", "category": "vocabulary", "feedback": "Les filles se dit بَنَات (banât), qui commence par ب (point dessous). نَبَات commence par ن : nabât, la plante."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e20', 'ar', 'ar.l02', 'ar.v.bayna', array['ar.v.bayna','ar.g02.nun_ya_five_teeth']::text[], 'free_answer', 'lesson', 'Comment se lit بَيْنَ (entre) ?', array['bayna','bayn','baina']::text[], 'ب (b), ي (y, deux points dessous), ن (n) : bayna, « entre ».', 3, '{"id": "ar.l02.e20", "unitIds": ["ar.v.bayna", "ar.g02.nun_ya_five_teeth"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture en lettres latines (â pour un a long).", "prompt": "Comment se lit بَيْنَ (entre) ?", "promptLanguage": "fr", "answer": "bayna", "acceptedAnswers": ["bayna", "bayn", "baina"], "explanation": "ب (b), ي (y, deux points dessous), ن (n) : bayna, « entre ».", "tip": "Un point dessous, deux points dessous, un point dessus : b - y - n.", "extraExample": {"text": "بَيْنِي", "translation": "entre moi", "transliteration": "baynî"}, "errorPatterns": [{"equals": "batna", "category": "spelling", "feedback": "La deuxième lettre a ses deux points dessous : c''est ي (y), pas ت."}, {"equals": "banna", "category": "spelling", "feedback": "La deuxième lettre a deux points dessous : c''est ي (y), pas ن."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e21', 'ar', 'ar.l02', 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.ya','ar.v.ba']::text[], 'free_answer', 'lesson', 'Comment se lit بَيْت (la maison) ?', array['bayt','bait']::text[], 'ب (b), ي (y, deux points dessous), ت (t, deux points dessus) : bayt, « la maison ». Le dernier ت a ses points au-dessus, pas au-dessous.', 4, '{"id": "ar.l02.e21", "unitIds": ["ar.g02.nun_ya_five_teeth", "ar.v.ya", "ar.v.ba"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit بَيْت (la maison) ?", "promptLanguage": "fr", "answer": "bayt", "acceptedAnswers": ["bayt", "bait"], "explanation": "ب (b), ي (y, deux points dessous), ت (t, deux points dessus) : bayt, « la maison ». Le dernier ت a ses points au-dessus, pas au-dessous.", "tip": "Même début que بَيْنَ, mais la dernière lettre est ت (deux points dessus).", "extraExample": {"text": "بَيْتِي", "translation": "ma maison", "transliteration": "baytî"}, "errorPatterns": [{"equals": "bayn", "category": "spelling", "feedback": "La dernière lettre a deux points au-dessus : c''est ت (t), pas ن."}, {"equals": "bayb", "category": "spelling", "feedback": "La dernière lettre a deux points au-dessus : c''est ت (t), pas ب."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e01', 'ar', 'ar.l03', 'ar.v.djim', array['ar.v.djim','ar.g03.djim_ha_kha']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : جـ ?', array['djîm (dj)']::text[], 'Une petite tête avec un point en dessous, à l''intérieur de la courbe : c''est ج, sous sa forme du début (جـ).', 1, '{"id": "ar.l03.e01", "unitIds": ["ar.v.djim", "ar.g03.djim_ha_kha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : جـ ?", "promptLanguage": "fr", "options": ["djîm (dj)", "7â'' (7)", "khâ'' (kh)", "tâ'' (t)"], "answer": "djîm (dj)", "acceptedAnswers": ["djîm (dj)"], "hint": "Cherche le point : dedans, dessus ou rien ?", "explanation": "Une petite tête avec un point en dessous, à l''intérieur de la courbe : c''est ج, sous sa forme du début (جـ).", "tip": "Point dedans = dj.", "extraExample": {"text": "جَزَر", "translation": "les carottes (ج au début)", "transliteration": "djazar"}, "errorPatterns": [{"equals": "7â'' (7)", "category": "spelling", "feedback": "ح n''a aucun point. Ici il y en a un, en dessous : c''est ج."}, {"equals": "khâ'' (kh)", "category": "spelling", "feedback": "خ a son point au-dessus. Ici il est en dessous, dans la courbe : c''est ج."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e02', 'ar', 'ar.l03', 'ar.v.hha', array['ar.v.hha','ar.g03.djim_ha_kha']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : ـحـ ?', array['7â'' (7)']::text[], 'Une petite tête sans aucun point, attachée des deux côtés : c''est ح, sous sa forme du milieu (ـحـ).', 1, '{"id": "ar.l03.e02", "unitIds": ["ar.v.hha", "ar.g03.djim_ha_kha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : ـحـ ?", "promptLanguage": "fr", "options": ["djîm (dj)", "7â'' (7)", "khâ'' (kh)", "nûn (n)"], "answer": "7â'' (7)", "acceptedAnswers": ["7â'' (7)"], "hint": "Regarde bien : y a-t-il un point ?", "explanation": "Une petite tête sans aucun point, attachée des deux côtés : c''est ح, sous sa forme du milieu (ـحـ).", "tip": "Aucun point = 7.", "extraExample": {"text": "تَحْتَ", "translation": "sous (ح au milieu)", "transliteration": "ta7ta"}, "errorPatterns": [{"equals": "djîm (dj)", "category": "spelling", "feedback": "ج porte un point sous la tête. Ici il n''y en a aucun : c''est ح."}, {"equals": "khâ'' (kh)", "category": "spelling", "feedback": "خ porte un point au-dessus. Ici il n''y en a aucun : c''est ح."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e03', 'ar', 'ar.l03', 'ar.v.kha', array['ar.v.kha','ar.g03.djim_ha_kha']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : ـخ ?', array['khâ'' (kh)']::text[], 'Un crochet avec un point au-dessus : c''est خ. Il est attaché seulement à droite : c''est sa forme de fin (ـخ).', 1, '{"id": "ar.l03.e03", "unitIds": ["ar.v.kha", "ar.g03.djim_ha_kha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : ـخ ?", "promptLanguage": "fr", "options": ["djîm (dj)", "7â'' (7)", "khâ'' (kh)", "thâ'' (th)"], "answer": "khâ'' (kh)", "acceptedAnswers": ["khâ'' (kh)"], "explanation": "Un crochet avec un point au-dessus : c''est خ. Il est attaché seulement à droite : c''est sa forme de fin (ـخ).", "tip": "Point dessus = kh.", "extraExample": {"text": "مَطْبَخ", "translation": "la cuisine (خ à la fin)", "transliteration": "maTbakh"}, "errorPatterns": [{"equals": "djîm (dj)", "category": "spelling", "feedback": "ج a son point en dessous. Ici il est au-dessus : c''est خ."}, {"equals": "7â'' (7)", "category": "spelling", "feedback": "ح n''a aucun point. Ici il y en a un, au-dessus : c''est خ."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e04', 'ar', 'ar.l03', 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.djim','ar.v.hha','ar.v.kha','ar.v.nun']::text[], 'match', 'lesson', 'Le crochet sous toutes ses formes', '{}'::text[], 'جـ (point dedans) = dj, ـحـ (aucun point) = 7, ـخ (point dessus) = kh, ـنـ (dent avec un point dessus) = n.', 1, '{"id": "ar.l03.e04", "unitIds": ["ar.g03.djim_ha_kha", "ar.v.djim", "ar.v.hha", "ar.v.kha", "ar.v.nun"], "type": "match", "difficulty": 1, "instruction": "Associe chaque forme au nom de sa lettre.", "prompt": "Le crochet sous toutes ses formes", "promptLanguage": "fr", "pairs": [{"left": "جـ", "right": "djîm (dj)"}, {"left": "ـحـ", "right": "7â'' (7)"}, {"left": "ـخ", "right": "khâ'' (kh)"}, {"left": "ـنـ", "right": "nûn (n)"}], "answer": "جـ = djîm (dj) ; ـحـ = 7â'' (7) ; ـخ = khâ'' (kh) ; ـنـ = nûn (n)", "acceptedAnswers": [], "explanation": "جـ (point dedans) = dj, ـحـ (aucun point) = 7, ـخ (point dessus) = kh, ـنـ (dent avec un point dessus) = n.", "tip": "Pour le crochet, le point fait tout : dedans, rien, dessus.", "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e05', 'ar', 'ar.l03', 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.hha']::text[], 'mcq', 'lesson', 'Laquelle de ces lettres n''a aucun point ?', array['ح']::text[], 'ح est la seule du crochet à être « nue ». ج a un point dedans, خ un point dessus, ن un point dessus aussi (sur une dent).', 1, '{"id": "ar.l03.e05", "unitIds": ["ar.g03.djim_ha_kha", "ar.v.hha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Laquelle de ces lettres n''a aucun point ?", "promptLanguage": "fr", "options": ["ج", "ح", "خ", "ن"], "answer": "ح", "acceptedAnswers": ["ح"], "explanation": "ح est la seule du crochet à être « nue ». ج a un point dedans, خ un point dessus, ن un point dessus aussi (sur une dent).", "tip": "Rien du tout = ح, le h soufflé.", "extraExample": {"text": "حَبِيب", "translation": "le chéri (ح au début)", "transliteration": "7abîb"}, "errorPatterns": [{"equals": "ج", "category": "spelling", "feedback": "ج a un point sous sa tête, dans la courbe."}, {"equals": "خ", "category": "spelling", "feedback": "خ a un point au-dessus de sa tête."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e06', 'ar', 'ar.l03', 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.kha']::text[], 'mcq', 'lesson', 'Quelle lettre se prononce comme le j de l''espagnol « jota » ?', array['خ']::text[], 'خ (kh) est un souffle frotté au fond de la gorge, comme le j espagnol ou le ch allemand de « Bach ».', 2, '{"id": "ar.l03.e06", "unitIds": ["ar.g03.djim_ha_kha", "ar.v.kha"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre se prononce comme le j de l''espagnol « jota » ?", "promptLanguage": "fr", "options": ["ج", "ح", "خ", "ث"], "answer": "خ", "acceptedAnswers": ["خ"], "explanation": "خ (kh) est un souffle frotté au fond de la gorge, comme le j espagnol ou le ch allemand de « Bach ».", "tip": "kh = « jota ». Son signe : un point au-dessus.", "extraExample": {"text": "خَاتَم", "translation": "la bague (kh au début)", "transliteration": "khâtam"}, "errorPatterns": [{"equals": "ح", "category": "spelling", "feedback": "ح (7) est un h soufflé, plus doux que kh et sans frottement."}, {"equals": "ج", "category": "spelling", "feedback": "ج se prononce dj, comme dans « jazz », pas comme une jota."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e07', 'ar', 'ar.l03', 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.djim','ar.v.hha','ar.v.kha','ar.v.ta']::text[], 'match', 'lesson', 'Où est le point ?', '{}'::text[], 'ج : un point dedans. ح : aucun point. خ : un point dessus. ت : une dent (pas un crochet) avec deux points dessus.', 2, '{"id": "ar.l03.e07", "unitIds": ["ar.g03.djim_ha_kha", "ar.v.djim", "ar.v.hha", "ar.v.kha", "ar.v.ta"], "type": "match", "difficulty": 2, "instruction": "Associe chaque description à sa lettre.", "prompt": "Où est le point ?", "promptLanguage": "fr", "pairs": [{"left": "un point dessous, dans la courbe", "right": "ج"}, {"left": "aucun point", "right": "ح"}, {"left": "un point au-dessus du crochet", "right": "خ"}, {"left": "deux points au-dessus d''une dent", "right": "ت"}], "answer": "un point dessous, dans la courbe = ج ; aucun point = ح ; un point au-dessus du crochet = خ ; deux points au-dessus d''une dent = ت", "acceptedAnswers": [], "explanation": "ج : un point dedans. ح : aucun point. خ : un point dessus. ت : une dent (pas un crochet) avec deux points dessus.", "tip": "D''abord la silhouette (crochet ou dent), ensuite les points.", "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e08', 'ar', 'ar.l03', 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.habib','ar.v.hha']::text[], 'mcq', 'lesson', 'Comment se lit حَبِيب ?', array['7abîb']::text[], 'Aucun point sur la première lettre : ح (7). Puis ب (point dessous), ي (î long) et ب final : 7abîb, « le chéri ».', 2, '{"id": "ar.l03.e08", "unitIds": ["ar.g03.djim_ha_kha", "ar.v.habib", "ar.v.hha"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit حَبِيب ?", "promptLanguage": "fr", "options": ["7abîb", "djabîb", "khabîb", "7anîb"], "answer": "7abîb", "acceptedAnswers": ["7abîb"], "hint": "Regarde le point de la première lettre.", "explanation": "Aucun point sur la première lettre : ح (7). Puis ب (point dessous), ي (î long) et ب final : 7abîb, « le chéri ».", "tip": "Première lettre sans point = 7.", "extraExample": {"text": "حَبِيبِي", "translation": "mon chéri", "transliteration": "7abîbî"}, "errorPatterns": [{"equals": "djabîb", "category": "spelling", "feedback": "ج porte un point sous la tête. La première lettre n''en a aucun : c''est ح."}, {"equals": "khabîb", "category": "spelling", "feedback": "خ porte un point au-dessus. La première lettre n''en a aucun : c''est ح."}, {"equals": "7anîb", "category": "spelling", "feedback": "La deuxième lettre a son point dessous : c''est ب (b), pas ن."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e09', 'ar', 'ar.l03', 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.tahta']::text[], 'mcq', 'lesson', 'Comment se lit تَحْتَ ?', array['ta7ta']::text[], 'ت (deux points dessus), puis ح sans aucun point, puis ت : ta7ta, « sous ». Aucun point sur la lettre du milieu, donc ni ج ni خ.', 2, '{"id": "ar.l03.e09", "unitIds": ["ar.g03.djim_ha_kha", "ar.v.tahta"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit تَحْتَ ?", "promptLanguage": "fr", "options": ["ta7ta", "takhta", "tadjta", "tabta"], "answer": "ta7ta", "acceptedAnswers": ["ta7ta"], "explanation": "ت (deux points dessus), puis ح sans aucun point, puis ت : ta7ta, « sous ». Aucun point sur la lettre du milieu, donc ni ج ni خ.", "tip": "Lettre du milieu sans point = 7.", "extraExample": {"text": "تَحْتَ الْبَابِ", "translation": "sous la porte", "transliteration": "ta7ta l-bâbi"}, "errorPatterns": [{"equals": "takhta", "category": "spelling", "feedback": "خ aurait un point au-dessus de sa tête. Ici la lettre du milieu n''en a aucun : c''est ح."}, {"equals": "tadjta", "category": "spelling", "feedback": "ج aurait un point dedans. Ici la lettre du milieu n''en a aucun : c''est ح."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e10', 'ar', 'ar.l03', 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.taj','ar.v.djim']::text[], 'mcq', 'lesson', 'Dans تَاج (la couronne), sous quelle forme est le ج ?', array['isolée']::text[], 'Le ج vient juste après ا. Comme ا ne s''attache jamais à la lettre suivante, ce ج n''est relié à rien : il prend sa forme isolée (ج).', 3, '{"id": "ar.l03.e10", "unitIds": ["ar.g03.djim_ha_kha", "ar.v.taj", "ar.v.djim"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne forme.", "prompt": "Dans تَاج (la couronne), sous quelle forme est le ج ?", "promptLanguage": "fr", "options": ["isolée", "finale", "médiane", "initiale"], "answer": "isolée", "acceptedAnswers": ["isolée"], "explanation": "Le ج vient juste après ا. Comme ا ne s''attache jamais à la lettre suivante, ce ج n''est relié à rien : il prend sa forme isolée (ج).", "tip": "Après ا, une lettre finale est isolée, pas « finale attachée ».", "extraExample": {"text": "بَاب", "translation": "la porte : le dernier ب est isolé", "transliteration": "bâb"}, "errorPatterns": [{"equals": "finale", "category": "grammar", "feedback": "La forme finale (ـج) serait attachée à la lettre d''avant. Ici c''est ا, qui ne s''attache pas : ج est isolé."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e11', 'ar', 'ar.l03', 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.khatam','ar.v.kha']::text[], 'mcq', 'lesson', 'Comment se lit خَاتَم ?', array['khâtam']::text[], 'Un point au-dessus du crochet : خ (kh). Puis ا (â long), ت (deux points dessus) et م : khâtam, « la bague ».', 3, '{"id": "ar.l03.e11", "unitIds": ["ar.g03.djim_ha_kha", "ar.v.khatam", "ar.v.kha"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit خَاتَم ?", "promptLanguage": "fr", "options": ["khâtam", "djâtam", "7âtam", "khânam"], "answer": "khâtam", "acceptedAnswers": ["khâtam"], "explanation": "Un point au-dessus du crochet : خ (kh). Puis ا (â long), ت (deux points dessus) et م : khâtam, « la bague ».", "tip": "Point dessus au début = kh.", "extraExample": {"text": "خَاتَمِي", "translation": "ma bague", "transliteration": "khâtamî"}, "errorPatterns": [{"equals": "djâtam", "category": "spelling", "feedback": "ج a son point en dessous. Ici le point est au-dessus : c''est خ."}, {"equals": "7âtam", "category": "spelling", "feedback": "ح n''a aucun point. Ici il y en a un, au-dessus : c''est خ."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e12', 'ar', 'ar.l03', 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.djazar','ar.v.djim']::text[], 'fill_blank', 'lesson', 'Les carottes (djazar) : ___زَر', array['جـ','ج']::text[], 'Djazar commence par dj : ج, avec un point dans la courbe. Au début du mot, il prend la forme جـ : جَزَر.', 2, '{"id": "ar.l03.e12", "unitIds": ["ar.g03.djim_ha_kha", "ar.v.djazar", "ar.v.djim"], "type": "fill_blank", "difficulty": 2, "instruction": "Choisis la lettre qui manque.", "prompt": "Les carottes (djazar) : ___زَر", "promptLanguage": "fr", "options": ["جـ", "حـ", "خـ"], "answer": "جـ", "acceptedAnswers": ["جـ", "ج"], "explanation": "Djazar commence par dj : ج, avec un point dans la courbe. Au début du mot, il prend la forme جـ : جَزَر.", "tip": "Le son dj = un point dans la courbe.", "extraExample": {"text": "جَزَرَة", "translation": "une carotte", "transliteration": "djazara"}, "errorPatterns": [{"equals": "حـ", "category": "spelling", "feedback": "حـ (aucun point) donnerait « 7azar ». Pour dj, il faut un point dans la courbe."}, {"equals": "خـ", "category": "spelling", "feedback": "خـ (point dessus) donnerait « khazar ». Pour dj, le point est dedans."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e13', 'ar', 'ar.l03', 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.nahnu','ar.v.hha']::text[], 'fill_blank', 'lesson', 'Dans نَحْنُ (nous), le ح est en forme ___.', array['médiane','médian','du milieu','milieu','forme médiane']::text[], 'Le ح est entre deux ن : il est relié des deux côtés, donc en forme du milieu (ـحـ).', 3, '{"id": "ar.l03.e13", "unitIds": ["ar.g03.djim_ha_kha", "ar.v.nahnu", "ar.v.hha"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le nom de la forme : initiale, médiane, finale ou isolée.", "prompt": "Dans نَحْنُ (nous), le ح est en forme ___.", "promptLanguage": "fr", "options": ["initiale", "médiane", "finale", "isolée"], "answer": "médiane", "acceptedAnswers": ["médiane", "médian", "du milieu", "milieu", "forme médiane"], "explanation": "Le ح est entre deux ن : il est relié des deux côtés, donc en forme du milieu (ـحـ).", "tip": "Relié des deux côtés = forme du milieu.", "extraExample": {"text": "تَحْتَ", "translation": "sous (ح au milieu)", "transliteration": "ta7ta"}, "errorPatterns": [{"equals": "initiale", "category": "grammar", "feedback": "La forme initiale est celle de la première lettre du mot. Ici, ح est entouré de deux ن."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e14', 'ar', 'ar.l03', 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.tin','ar.v.nun']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit tîn (les figues) ?', array['تِين']::text[], 'tîn finit par ن (un seul point au-dessus, sur une cuvette). تِيح et تِيج finissent par un crochet, et نِين commence par ن.', 3, '{"id": "ar.l03.e14", "unitIds": ["ar.g02.nun_ya_five_teeth", "ar.v.tin", "ar.v.nun"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se lit tîn (les figues) ?", "promptLanguage": "fr", "options": ["تِين", "تِيح", "تِيج", "نِين"], "answer": "تِين", "acceptedAnswers": ["تِين"], "explanation": "tîn finit par ن (un seul point au-dessus, sur une cuvette). تِيح et تِيج finissent par un crochet, et نِين commence par ن.", "tip": "Cuvette ou crochet ? Dent ou crochet ? Ensuite seulement, les points.", "extraExample": {"text": "تِينَة", "translation": "une figue", "transliteration": "tîna"}, "errorPatterns": [{"equals": "نِين", "category": "spelling", "feedback": "La première lettre a deux points au-dessus : c''est ت (t), pas ن."}, {"equals": "تِيج", "category": "spelling", "feedback": "La dernière lettre est une simple cuvette avec un point dessus : c''est ن, pas un crochet."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e15', 'ar', 'ar.l03', 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.ya','ar.v.habib']::text[], 'fill_blank', 'lesson', 'Dans حَبِيب (le chéri), le ي est en forme ___.', array['médiane','médian','du milieu','milieu','forme médiane']::text[], 'Le ي est entre ب et ب : relié des deux côtés, il prend sa forme du milieu (ـيـ), avec ses deux points dessous.', 3, '{"id": "ar.l03.e15", "unitIds": ["ar.g02.nun_ya_five_teeth", "ar.v.ya", "ar.v.habib"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le nom de la forme : initiale, médiane, finale ou isolée.", "prompt": "Dans حَبِيب (le chéri), le ي est en forme ___.", "promptLanguage": "fr", "options": ["initiale", "médiane", "finale", "isolée"], "answer": "médiane", "acceptedAnswers": ["médiane", "médian", "du milieu", "milieu", "forme médiane"], "explanation": "Le ي est entre ب et ب : relié des deux côtés, il prend sa forme du milieu (ـيـ), avec ses deux points dessous.", "tip": "Deux points dessous au milieu d''un mot : ـيـ.", "extraExample": {"text": "بَيْنَ", "translation": "entre (ي au milieu)", "transliteration": "bayna"}, "errorPatterns": [{"equals": "finale", "category": "grammar", "feedback": "Le ي n''est pas la dernière lettre : après lui vient encore un ب."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e16', 'ar', 'ar.l03', 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.habib','ar.v.taj','ar.v.khatam','ar.v.djazar']::text[], 'match', 'lesson', 'Des mots à crochet', '{}'::text[], 'حَبِيب (7abîb) = le chéri, تَاج (tâdj) = la couronne, خَاتَم (khâtam) = la bague, جَزَر (djazar) = les carottes.', 2, '{"id": "ar.l03.e16", "unitIds": ["ar.g03.djim_ha_kha", "ar.v.habib", "ar.v.taj", "ar.v.khatam", "ar.v.djazar"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Des mots à crochet", "promptLanguage": "fr", "pairs": [{"left": "حَبِيب", "right": "le chéri"}, {"left": "تَاج", "right": "la couronne"}, {"left": "خَاتَم", "right": "la bague"}, {"left": "جَزَر", "right": "les carottes"}], "answer": "حَبِيب = le chéri ; تَاج = la couronne ; خَاتَم = la bague ; جَزَر = les carottes", "acceptedAnswers": [], "explanation": "حَبِيب (7abîb) = le chéri, تَاج (tâdj) = la couronne, خَاتَم (khâtam) = la bague, جَزَر (djazar) = les carottes.", "tip": "Repère d''abord le crochet, puis son point : il te donne le début du mot.", "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e17', 'ar', 'ar.l03', 'ar.v.taj', array['ar.v.taj','ar.g03.djim_ha_kha']::text[], 'reorder', 'lesson', 'Écris « tâdj » (la couronne) avec ces lettres.', array['ت ا ج']::text[], 'Tâdj : ت (t), ا (â long), ج (dj). Écrit : تَاج, avec un ج isolé après ا.', 3, '{"id": "ar.l03.e17", "unitIds": ["ar.v.taj", "ar.g03.djim_ha_kha"], "type": "reorder", "difficulty": 3, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « tâdj » (la couronne) avec ces lettres.", "promptLanguage": "fr", "tokens": ["ج", "ا", "ت"], "answer": "ت ا ج", "acceptedAnswers": ["ت ا ج"], "explanation": "Tâdj : ت (t), ا (â long), ج (dj). Écrit : تَاج, avec un ج isolé après ا.", "tip": "Le crochet ج ne s''attache pas à ا : il finit le mot tout seul.", "extraExample": {"text": "تَاجُ الْمَلِكِ", "translation": "la couronne du roi", "transliteration": "tâdju l-maliki"}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e18', 'ar', 'ar.l03', 'ar.v.habib', array['ar.v.habib','ar.g03.djim_ha_kha']::text[], 'reorder', 'lesson', 'Écris « 7abîb » (le chéri) avec ces lettres.', array['ح ب ي ب']::text[], '7abîb : ح (7), ب (b), ي (î long), ب (b). Écrit : حَبِيب.', 3, '{"id": "ar.l03.e18", "unitIds": ["ar.v.habib", "ar.g03.djim_ha_kha"], "type": "reorder", "difficulty": 3, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « 7abîb » (le chéri) avec ces lettres.", "promptLanguage": "fr", "tokens": ["ب", "ح", "ي", "ب"], "answer": "ح ب ي ب", "acceptedAnswers": ["ح ب ي ب"], "explanation": "7abîb : ح (7), ب (b), ي (î long), ب (b). Écrit : حَبِيب.", "tip": "Commence par le crochet sans point : c''est ح.", "extraExample": {"text": "حَبِيبَتِي", "translation": "ma chérie", "transliteration": "7abîbatî"}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e19', 'ar', 'ar.l03', 'ar.v.tahta', array['ar.v.tahta','ar.g03.djim_ha_kha']::text[], 'translation', 'lesson', 'تَحْتَ', array['sous','en dessous de','dessous','au-dessous de','en dessous']::text[], 'تَحْتَ se lit ta7ta et veut dire « sous, en dessous de » : ت, ح, ت.', 3, '{"id": "ar.l03.e19", "unitIds": ["ar.v.tahta", "ar.g03.djim_ha_kha"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "تَحْتَ", "promptLanguage": "ar", "answer": "sous", "acceptedAnswers": ["sous", "en dessous de", "dessous", "au-dessous de", "en dessous"], "explanation": "تَحْتَ se lit ta7ta et veut dire « sous, en dessous de » : ت, ح, ت.", "tip": "Ta7ta : le h soufflé (7) au milieu, sans point.", "extraExample": {"text": "تَحْتَ الْكِتَابِ", "translation": "sous le livre", "transliteration": "ta7ta l-kitâbi"}, "errorPatterns": [{"equals": "entre", "category": "vocabulary", "feedback": "Entre se dit بَيْنَ (bayna). تَحْتَ (ta7ta) veut dire « sous »."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e20', 'ar', 'ar.l03', 'ar.v.nahnu', array['ar.v.nahnu','ar.g03.djim_ha_kha']::text[], 'translation', 'lesson', 'نَحْنُ', array['nous']::text[], 'نَحْنُ se lit na7nu : c''est le pronom « nous ». Deux ن autour d''un ح sans point.', 3, '{"id": "ar.l03.e20", "unitIds": ["ar.v.nahnu", "ar.g03.djim_ha_kha"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "نَحْنُ", "promptLanguage": "ar", "answer": "nous", "acceptedAnswers": ["nous"], "explanation": "نَحْنُ se lit na7nu : c''est le pronom « nous ». Deux ن autour d''un ح sans point.", "tip": "Na7nu : n - 7 - n, avec le ح au milieu.", "extraExample": {"text": "نَحْنُ هُنَا", "translation": "nous sommes ici", "transliteration": "na7nu hunâ"}, "errorPatterns": [{"equals": "je", "category": "vocabulary", "feedback": "« Je » se dit أَنَا (ana). نَحْنُ est le pronom « nous »."}, {"equals": "sous", "category": "vocabulary", "feedback": "« Sous » se dit تَحْتَ (ta7ta). نَحْنُ (na7nu) commence par ن et veut dire « nous »."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e21', 'ar', 'ar.l03', 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.djazar','ar.v.djim']::text[], 'free_answer', 'lesson', 'Comment se lit جَزَر (les carottes) ?', array['djazar','jazar','gazar']::text[], 'ج (dj, point dans la courbe), ز (z) et ر (r) : djazar, « les carottes ».', 3, '{"id": "ar.l03.e21", "unitIds": ["ar.g03.djim_ha_kha", "ar.v.djazar", "ar.v.djim"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture en lettres latines (dj pour ج).", "prompt": "Comment se lit جَزَر (les carottes) ?", "promptLanguage": "fr", "answer": "djazar", "acceptedAnswers": ["djazar", "jazar", "gazar"], "explanation": "ج (dj, point dans la courbe), ز (z) et ر (r) : djazar, « les carottes ».", "tip": "Le point est dedans : dj. Rien : 7. Dessus : kh.", "extraExample": {"text": "جَزَرَة", "translation": "une carotte", "transliteration": "djazara"}, "errorPatterns": [{"equals": "7azar", "category": "spelling", "feedback": "La première lettre a un point dans la courbe : c''est ج (dj), pas ح."}, {"equals": "khazar", "category": "spelling", "feedback": "La première lettre a son point en dessous : c''est ج (dj), pas خ."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e22', 'ar', 'ar.l03', 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.taj']::text[], 'free_answer', 'lesson', 'Comment se lit تَاج (la couronne) ?', array['tâdj','tadj','taadj','tâj','taj','tâg','tag']::text[], 'ت (t), ا (â long), ج (dj) : tâdj, « la couronne ». En Égypte on entend « tâg », mais en arabe standard c''est tâdj.', 4, '{"id": "ar.l03.e22", "unitIds": ["ar.g03.djim_ha_kha", "ar.v.taj"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines (â pour un a long).", "prompt": "Comment se lit تَاج (la couronne) ?", "promptLanguage": "fr", "answer": "tâdj", "acceptedAnswers": ["tâdj", "tadj", "taadj", "tâj", "taj", "tâg", "tag"], "explanation": "ت (t), ا (â long), ج (dj) : tâdj, « la couronne ». En Égypte on entend « tâg », mais en arabe standard c''est tâdj.", "tip": "Après ا, le crochet reste isolé.", "extraExample": {"text": "تِيجَان", "translation": "des couronnes", "transliteration": "tîdjân"}, "errorPatterns": [{"equals": "tâkh", "category": "spelling", "feedback": "Le crochet final a son point en dessous, dans la courbe : c''est ج (dj), pas خ."}, {"equals": "tâ7", "category": "spelling", "feedback": "Le crochet final porte un point : c''est ج (dj), pas ح."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e01', 'ar', 'ar.l04', 'ar.v.dhal', array['ar.v.dhal','ar.g04.non_connecting_letters']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : ذ ?', array['dhâl (dh)']::text[], 'Un petit angle avec un point au-dessus : c''est ذ. Sans le point, ce serait د (d).', 1, '{"id": "ar.l04.e01", "unitIds": ["ar.v.dhal", "ar.g04.non_connecting_letters"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : ذ ?", "promptLanguage": "fr", "options": ["dâl (d)", "dhâl (dh)", "râ'' (r)", "zây (z)"], "answer": "dhâl (dh)", "acceptedAnswers": ["dhâl (dh)"], "hint": "Y a-t-il un point ?", "explanation": "Un petit angle avec un point au-dessus : c''est ذ. Sans le point, ce serait د (d).", "tip": "Le point dessus fait passer de d à dh.", "extraExample": {"text": "لَذِيذ", "translation": "délicieux (deux ذ)", "transliteration": "ladhîdh"}, "errorPatterns": [{"equals": "dâl (d)", "category": "spelling", "feedback": "د n''a aucun point. Ici il y en a un, au-dessus : c''est ذ."}, {"equals": "zây (z)", "category": "spelling", "feedback": "ز est une petite virgule qui descend sous la ligne. ذ est un angle, posé sur la ligne."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e02', 'ar', 'ar.l04', 'ar.v.zay', array['ar.v.zay','ar.g04.non_connecting_letters']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : ز ?', array['zây (z)']::text[], 'Une petite virgule qui descend sous la ligne, avec un point au-dessus : c''est ز. Sans le point, ce serait ر (r).', 1, '{"id": "ar.l04.e02", "unitIds": ["ar.v.zay", "ar.g04.non_connecting_letters"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : ز ?", "promptLanguage": "fr", "options": ["dâl (d)", "dhâl (dh)", "râ'' (r)", "zây (z)"], "answer": "zây (z)", "acceptedAnswers": ["zây (z)"], "hint": "Virgule ou angle ? Point ou pas ?", "explanation": "Une petite virgule qui descend sous la ligne, avec un point au-dessus : c''est ز. Sans le point, ce serait ر (r).", "tip": "Le point dessus fait passer de r à z.", "extraExample": {"text": "زَيْت", "translation": "l''huile (ز au début)", "transliteration": "zayt"}, "errorPatterns": [{"equals": "râ'' (r)", "category": "spelling", "feedback": "ر a la même forme, mais aucun point. Ici il y en a un, au-dessus : c''est ز."}, {"equals": "dhâl (dh)", "category": "spelling", "feedback": "ذ est un angle posé sur la ligne ; ز est une virgule qui descend. Les deux ont un point."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e03', 'ar', 'ar.l04', 'ar.v.waw', array['ar.v.waw','ar.g04.non_connecting_letters']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : و ?', array['wâw (w, û)']::text[], 'Une boucle fermée prolongée par une queue qui descend, sans aucun point : c''est و. Elle se lit w ou û, selon le mot.', 1, '{"id": "ar.l04.e03", "unitIds": ["ar.v.waw", "ar.g04.non_connecting_letters"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : و ?", "promptLanguage": "fr", "options": ["dâl (d)", "râ'' (r)", "zây (z)", "wâw (w, û)"], "answer": "wâw (w, û)", "acceptedAnswers": ["wâw (w, û)"], "explanation": "Une boucle fermée prolongée par une queue qui descend, sans aucun point : c''est و. Elle se lit w ou û, selon le mot.", "tip": "Boucle fermée + queue = و.", "extraExample": {"text": "وَرَق", "translation": "du papier (و au début)", "transliteration": "waraq"}, "errorPatterns": [{"equals": "râ'' (r)", "category": "spelling", "feedback": "ر est une simple virgule, sans boucle. و a une boucle fermée en haut."}, {"equals": "zây (z)", "category": "spelling", "feedback": "ز est une virgule avec un point. و a une boucle fermée et aucun point."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e04', 'ar', 'ar.l04', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.dal','ar.v.dhal','ar.v.ra','ar.v.zay','ar.v.waw']::text[], 'match', 'lesson', 'Cinq lettres qui coupent', '{}'::text[], 'د (angle, sans point) = d, ذ (angle + point) = dh, ر (virgule, sans point) = r, ز (virgule + point) = z, و (boucle) = w ou û.', 1, '{"id": "ar.l04.e04", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.dal", "ar.v.dhal", "ar.v.ra", "ar.v.zay", "ar.v.waw"], "type": "match", "difficulty": 1, "instruction": "Associe chaque lettre à son nom.", "prompt": "Cinq lettres qui coupent", "promptLanguage": "fr", "pairs": [{"left": "د", "right": "dâl (d)"}, {"left": "ذ", "right": "dhâl (dh)"}, {"left": "ر", "right": "râ'' (r)"}, {"left": "ز", "right": "zây (z)"}, {"left": "و", "right": "wâw (w, û)"}], "answer": "د = dâl (d) ; ذ = dhâl (dh) ; ر = râ'' (r) ; ز = zây (z) ; و = wâw (w, û)", "acceptedAnswers": [], "explanation": "د (angle, sans point) = d, ذ (angle + point) = dh, ر (virgule, sans point) = r, ز (virgule + point) = z, و (boucle) = w ou û.", "tip": "Deux formes (angle, virgule), un point en plus ou en moins : ça donne quatre lettres.", "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e05', 'ar', 'ar.l04', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.g04.non_connecting_letters','ar.v.ba']::text[], 'mcq', 'lesson', 'Laquelle de ces lettres s''attache à la lettre qui la suit ?', array['ب']::text[], 'ب s''attache des deux côtés (بـ, ـبـ). ز, د et و, comme ا et ر, s''attachent à la lettre d''avant mais jamais à la suivante.', 2, '{"id": "ar.l04.e05", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.g04.non_connecting_letters", "ar.v.ba"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Laquelle de ces lettres s''attache à la lettre qui la suit ?", "promptLanguage": "fr", "options": ["ز", "ب", "د", "و"], "answer": "ب", "acceptedAnswers": ["ب"], "explanation": "ب s''attache des deux côtés (بـ, ـبـ). ز, د et و, comme ا et ر, s''attachent à la lettre d''avant mais jamais à la suivante.", "tip": "Les coupeuses : ا د ذ ر ز و. Toutes les autres s''attachent.", "extraExample": {"text": "بَيْت", "translation": "la maison : ب s''attache au ي", "transliteration": "bayt"}, "errorPatterns": [{"equals": "ز", "category": "grammar", "feedback": "ز fait partie des six lettres qui ne s''attachent jamais à la suivante."}, {"equals": "د", "category": "grammar", "feedback": "د fait partie des six lettres qui ne s''attachent jamais à la suivante."}, {"equals": "و", "category": "grammar", "feedback": "و fait partie des six lettres qui ne s''attachent jamais à la suivante."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e06', 'ar', 'ar.l04', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.dal','ar.v.dhal','ar.v.ra','ar.v.zay']::text[], 'match', 'lesson', 'Angle ou virgule, point ou pas', '{}'::text[], 'د et ذ sont des angles, ر et ز des virgules. Les lettres avec point (ذ, ز) sont les jumelles des lettres sans point (د, ر).', 2, '{"id": "ar.l04.e06", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.dal", "ar.v.dhal", "ar.v.ra", "ar.v.zay"], "type": "match", "difficulty": 2, "instruction": "Associe chaque description à sa lettre.", "prompt": "Angle ou virgule, point ou pas", "promptLanguage": "fr", "pairs": [{"left": "un angle sans point", "right": "د"}, {"left": "le même angle avec un point dessus", "right": "ذ"}, {"left": "une virgule sans point", "right": "ر"}, {"left": "la même virgule avec un point dessus", "right": "ز"}], "answer": "un angle sans point = د ; le même angle avec un point dessus = ذ ; une virgule sans point = ر ; la même virgule avec un point dessus = ز", "acceptedAnswers": [], "explanation": "د et ذ sont des angles, ر et ز des virgules. Les lettres avec point (ذ, ز) sont les jumelles des lettres sans point (د, ر).", "tip": "D''abord la forme, ensuite le point.", "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e07', 'ar', 'ar.l04', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.dar']::text[], 'mcq', 'lesson', 'Dans دَار (la demeure), combien de lettres sont reliées entre elles ?', array['aucune']::text[], 'د ne s''attache pas à ا, et ا ne s''attache pas à ر : les trois lettres restent séparées.', 2, '{"id": "ar.l04.e07", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.dar"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans دَار (la demeure), combien de lettres sont reliées entre elles ?", "promptLanguage": "fr", "options": ["aucune", "deux", "trois", "toutes"], "answer": "aucune", "acceptedAnswers": ["aucune"], "explanation": "د ne s''attache pas à ا, et ا ne s''attache pas à ر : les trois lettres restent séparées.", "tip": "Trois coupeuses de suite : rien n''est relié.", "extraExample": {"text": "وَرَق", "translation": "du papier : trois lettres séparées", "transliteration": "waraq"}, "errorPatterns": [{"equals": "toutes", "category": "grammar", "feedback": "Aucune de ces trois lettres ne s''attache à la suivante : il n''y a donc aucune liaison."}, {"equals": "deux", "category": "grammar", "feedback": "د et ا ne s''attachent pas à la suivante : aucune liaison, pas même entre ا et ر."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e08', 'ar', 'ar.l04', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.dar']::text[], 'mcq', 'lesson', 'Comment se lit دَار ?', array['dâr']::text[], 'د (d, sans point), ا (â long), ر (r, sans point) : dâr. Aucune des deux lettres à angle ou à virgule ne porte de point.', 2, '{"id": "ar.l04.e08", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.dar"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit دَار ?", "promptLanguage": "fr", "options": ["dâr", "dhâr", "zâr", "dâz"], "answer": "dâr", "acceptedAnswers": ["dâr"], "explanation": "د (d, sans point), ا (â long), ر (r, sans point) : dâr. Aucune des deux lettres à angle ou à virgule ne porte de point.", "tip": "Pas de point = d et r.", "extraExample": {"text": "دَارِي", "translation": "ma demeure", "transliteration": "dârî"}, "errorPatterns": [{"equals": "dhâr", "category": "spelling", "feedback": "ذ aurait un point au-dessus. Ici la première lettre n''en a pas : c''est د (d)."}, {"equals": "zâr", "category": "spelling", "feedback": "ز aurait un point, et la première lettre est un angle (د), pas une virgule."}, {"equals": "dâz", "category": "spelling", "feedback": "La dernière lettre n''a pas de point : c''est ر (r), pas ز."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e09', 'ar', 'ar.l04', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.zayt','ar.v.ya']::text[], 'mcq', 'lesson', 'Dans زَيْت (l''huile), sous quelle forme est le ي ?', array['initiale']::text[], 'ز ne s''attache jamais à la lettre suivante. Le ي repart donc avec sa forme de début (يـ) et s''attache seulement au ت qui le suit.', 3, '{"id": "ar.l04.e09", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.zayt", "ar.v.ya"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne forme.", "prompt": "Dans زَيْت (l''huile), sous quelle forme est le ي ?", "promptLanguage": "fr", "options": ["initiale", "médiane", "finale", "isolée"], "answer": "initiale", "acceptedAnswers": ["initiale"], "explanation": "ز ne s''attache jamais à la lettre suivante. Le ي repart donc avec sa forme de début (يـ) et s''attache seulement au ت qui le suit.", "tip": "Après une coupeuse, on repart en forme de début.", "extraExample": {"text": "زَيْتُون", "translation": "des olives : même découpage", "transliteration": "zaytûn"}, "errorPatterns": [{"equals": "médiane", "category": "grammar", "feedback": "La forme du milieu suppose d''être attaché à droite aussi. Mais ز ne s''attache pas à ي : c''est une forme de début."}, {"equals": "isolée", "category": "grammar", "feedback": "ي est attaché au ت qui le suit : il n''est pas isolé."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e10', 'ar', 'ar.l04', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.dadjadj','ar.v.djim']::text[], 'fill_blank', 'lesson', 'Dans دَجَاج (le poulet), le premier ج est en forme ___.', array['initiale','initial','de début','début','forme initiale']::text[], 'د ne s''attache pas au ج qui le suit : ce ج repart avec sa forme de début (جـ) et s''attache au ا.', 3, '{"id": "ar.l04.e10", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.dadjadj", "ar.v.djim"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le nom de la forme : initiale, médiane, finale ou isolée.", "prompt": "Dans دَجَاج (le poulet), le premier ج est en forme ___.", "promptLanguage": "fr", "options": ["initiale", "médiane", "finale", "isolée"], "answer": "initiale", "acceptedAnswers": ["initiale", "initial", "de début", "début", "forme initiale"], "explanation": "د ne s''attache pas au ج qui le suit : ce ج repart avec sa forme de début (جـ) et s''attache au ا.", "tip": "Après د, la lettre suivante recommence comme au début d''un mot.", "extraExample": {"text": "جَزَر", "translation": "les carottes : ج au début", "transliteration": "djazar"}, "errorPatterns": [{"equals": "médiane", "category": "grammar", "feedback": "Pour être en forme du milieu, ج devrait être attaché à la lettre d''avant. Mais د ne s''attache pas."}, {"equals": "finale", "category": "grammar", "feedback": "Le premier ج n''est pas la dernière lettre : il est suivi de ا."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e11', 'ar', 'ar.l04', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.dadjadj']::text[], 'mcq', 'lesson', 'Comment se lit دَجَاج ?', array['dadjâdj']::text[], 'د (d), ج (dj, point dans la courbe), ا (â long), ج (dj) : dadjâdj, « le poulet ». Les deux crochets portent un point dedans.', 3, '{"id": "ar.l04.e11", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.dadjadj"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit دَجَاج ?", "promptLanguage": "fr", "options": ["dadjâdj", "dad7â7", "dakhâkh", "radjâdj"], "answer": "dadjâdj", "acceptedAnswers": ["dadjâdj"], "explanation": "د (d), ج (dj, point dans la courbe), ا (â long), ج (dj) : dadjâdj, « le poulet ». Les deux crochets portent un point dedans.", "tip": "Crochet avec un point dedans = dj.", "extraExample": {"text": "دَجَاجَة", "translation": "une poule", "transliteration": "dadjâdja"}, "errorPatterns": [{"equals": "dad7â7", "category": "spelling", "feedback": "ح n''a aucun point. Ici les crochets ont un point dans la courbe : c''est ج."}, {"equals": "dakhâkh", "category": "spelling", "feedback": "خ a son point au-dessus. Ici il est dedans, sous la tête : c''est ج."}, {"equals": "radjâdj", "category": "spelling", "feedback": "La première lettre est un angle (د), pas une virgule (ر)."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e12', 'ar', 'ar.l04', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.ladhidh','ar.v.dhal']::text[], 'mcq', 'lesson', 'Dans لَذِيذ (délicieux), combien de blocs de lettres attachées vois-tu ?', array['deux blocs']::text[], 'ل s''attache à ذ (premier bloc : لذ). Mais ذ coupe : ي repart en forme de début et s''attache au dernier ذ (deuxième bloc : يذ).', 3, '{"id": "ar.l04.e12", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.ladhidh", "ar.v.dhal"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans لَذِيذ (délicieux), combien de blocs de lettres attachées vois-tu ?", "promptLanguage": "fr", "options": ["un seul bloc", "deux blocs", "trois blocs", "quatre blocs"], "answer": "deux blocs", "acceptedAnswers": ["deux blocs"], "explanation": "ل s''attache à ذ (premier bloc : لذ). Mais ذ coupe : ي repart en forme de début et s''attache au dernier ذ (deuxième bloc : يذ).", "tip": "Chaque coupeuse (ا د ذ ر ز و) ferme un bloc.", "extraExample": {"text": "دَجَاج", "translation": "trois blocs : د | جا | ج", "transliteration": "dadjâdj"}, "errorPatterns": [{"equals": "un seul bloc", "category": "grammar", "feedback": "ذ ne s''attache pas à la lettre suivante : le mot est donc coupé en deux."}, {"equals": "quatre blocs", "category": "grammar", "feedback": "ل s''attache à ذ, et ي s''attache à ذ : il y a deux blocs, pas quatre lettres séparées."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e13', 'ar', 'ar.l04', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.zayt','ar.v.zay']::text[], 'fill_blank', 'lesson', 'L''huile (zayt) : ___َيْت', array['ز']::text[], 'Zayt commence par z : ز, une virgule avec un point au-dessus. ر (sans point) donnerait « rayt ».', 3, '{"id": "ar.l04.e13", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.zayt", "ar.v.zay"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la lettre qui manque.", "prompt": "L''huile (zayt) : ___َيْت", "promptLanguage": "fr", "options": ["ز", "ر", "ذ"], "answer": "ز", "acceptedAnswers": ["ز"], "explanation": "Zayt commence par z : ز, une virgule avec un point au-dessus. ر (sans point) donnerait « rayt ».", "tip": "z = virgule + point.", "extraExample": {"text": "زَيْتُونَة", "translation": "une olive", "transliteration": "zaytûna"}, "errorPatterns": [{"equals": "ر", "category": "spelling", "feedback": "ر n''a pas de point : on lirait « rayt ». Pour le son z, il faut le point au-dessus."}, {"equals": "ذ", "category": "spelling", "feedback": "ذ est un angle, pas une virgule : on lirait « dhayt »."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e14', 'ar', 'ar.l04', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.ladhidh','ar.v.dhal']::text[], 'fill_blank', 'lesson', 'Délicieux (ladhîdh) : لَ___ِيذ', array['ذ']::text[], 'Ladhîdh a un dh au milieu : ذ, un angle avec un point au-dessus. د (sans point) donnerait « ladîd ».', 3, '{"id": "ar.l04.e14", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.ladhidh", "ar.v.dhal"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la lettre qui manque.", "prompt": "Délicieux (ladhîdh) : لَ___ِيذ", "promptLanguage": "fr", "options": ["ذ", "د", "ز"], "answer": "ذ", "acceptedAnswers": ["ذ"], "explanation": "Ladhîdh a un dh au milieu : ذ, un angle avec un point au-dessus. د (sans point) donnerait « ladîd ».", "tip": "dh = angle + point.", "extraExample": {"text": "ذِرَاع", "translation": "le bras", "transliteration": "dhirâ3"}, "errorPatterns": [{"equals": "د", "category": "spelling", "feedback": "د n''a pas de point : on lirait « ladîd ». Pour dh, il faut le point au-dessus."}, {"equals": "ز", "category": "spelling", "feedback": "ز est une virgule qui descend sous la ligne ; ici il faut un angle avec un point : ذ."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e15', 'ar', 'ar.l04', 'ar.v.taj', array['ar.v.taj','ar.g03.djim_ha_kha','ar.v.djim']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit tâdj (la couronne) ?', array['تَاج']::text[], 'Le dernier signe est un crochet avec un point dedans : ج (dj). تَاح n''a aucun point (7), تَاخ un point dessus (kh), et ثَاج commence par trois points (th).', 3, '{"id": "ar.l04.e15", "unitIds": ["ar.v.taj", "ar.g03.djim_ha_kha", "ar.v.djim"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se lit tâdj (la couronne) ?", "promptLanguage": "fr", "options": ["تَاج", "تَاح", "تَاخ", "ثَاج"], "answer": "تَاج", "acceptedAnswers": ["تَاج"], "explanation": "Le dernier signe est un crochet avec un point dedans : ج (dj). تَاح n''a aucun point (7), تَاخ un point dessus (kh), et ثَاج commence par trois points (th).", "tip": "Dernier crochet : un point dedans = dj.", "extraExample": {"text": "تِيجَان", "translation": "des couronnes", "transliteration": "tîdjân"}, "errorPatterns": [{"equals": "تَاح", "category": "spelling", "feedback": "ح n''a aucun point : on lirait « tâ7 »."}, {"equals": "تَاخ", "category": "spelling", "feedback": "خ a son point au-dessus : on lirait « tâkh »."}, {"equals": "ثَاج", "category": "spelling", "feedback": "La première lettre aurait trois points : on lirait « thâdj »."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e16', 'ar', 'ar.l04', 'ar.v.kitab', array['ar.v.kitab','ar.g01.alif_ba_ta_tha','ar.g04.non_connecting_letters']::text[], 'fill_blank', 'lesson', 'Dans كِتَاب (le livre), il y a ___ blocs de lettres attachées.', array['2','deux']::text[], 'كِتَا forme un premier bloc, puis ا coupe le mot et ب repart seul : deux blocs, كِتَا et ب.', 3, '{"id": "ar.l04.e16", "unitIds": ["ar.v.kitab", "ar.g01.alif_ba_ta_tha", "ar.g04.non_connecting_letters"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Dans كِتَاب (le livre), il y a ___ blocs de lettres attachées.", "promptLanguage": "fr", "options": ["1", "2", "3"], "answer": "2", "acceptedAnswers": ["2", "deux"], "explanation": "كِتَا forme un premier bloc, puis ا coupe le mot et ب repart seul : deux blocs, كِتَا et ب.", "tip": "Même ا peut couper un mot : compte les blocs.", "extraExample": {"text": "بَاب", "translation": "la porte : deux blocs, با et ب", "transliteration": "bâb"}, "errorPatterns": [{"equals": "1", "category": "grammar", "feedback": "ا ne s''attache pas à la lettre suivante : le ب final est donc séparé du reste."}, {"equals": "3", "category": "grammar", "feedback": "ك, ت et ا sont attachés ensemble ; seul ب est séparé : deux blocs."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e17', 'ar', 'ar.l04', 'ar.v.habib', array['ar.v.habib','ar.v.taj','ar.g04.non_connecting_letters','ar.v.dar','ar.v.zayt']::text[], 'match', 'lesson', 'Des mots de la maison et de la table', '{}'::text[], 'حَبِيب (7abîb) = le chéri, تَاج (tâdj) = la couronne, دَار (dâr) = la demeure, زَيْت (zayt) = l''huile.', 2, '{"id": "ar.l04.e17", "unitIds": ["ar.v.habib", "ar.v.taj", "ar.g04.non_connecting_letters", "ar.v.dar", "ar.v.zayt"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Des mots de la maison et de la table", "promptLanguage": "fr", "pairs": [{"left": "حَبِيب", "right": "le chéri"}, {"left": "تَاج", "right": "la couronne"}, {"left": "دَار", "right": "la demeure"}, {"left": "زَيْت", "right": "l''huile"}], "answer": "حَبِيب = le chéri ; تَاج = la couronne ; دَار = la demeure ; زَيْت = l''huile", "acceptedAnswers": [], "explanation": "حَبِيب (7abîb) = le chéri, تَاج (tâdj) = la couronne, دَار (dâr) = la demeure, زَيْت (zayt) = l''huile.", "tip": "Repère les coupures : elles te donnent la silhouette du mot.", "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e18', 'ar', 'ar.l04', 'ar.v.dar', array['ar.v.dar','ar.g04.non_connecting_letters']::text[], 'reorder', 'lesson', 'Écris « dâr » (la demeure) avec ces lettres.', array['د ا ر']::text[], 'Dâr : د (d), ا (â long), ر (r). Aucune des trois lettres ne s''attache à la suivante : دَار.', 3, '{"id": "ar.l04.e18", "unitIds": ["ar.v.dar", "ar.g04.non_connecting_letters"], "type": "reorder", "difficulty": 3, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « dâr » (la demeure) avec ces lettres.", "promptLanguage": "fr", "tokens": ["ر", "ا", "د"], "answer": "د ا ر", "acceptedAnswers": ["د ا ر"], "explanation": "Dâr : د (d), ا (â long), ر (r). Aucune des trois lettres ne s''attache à la suivante : دَار.", "tip": "On commence par la lettre de droite.", "extraExample": {"text": "دَارِي", "translation": "ma demeure", "transliteration": "dârî"}, "pool": "lesson", "lessonId": "ar.l04", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e19', 'ar', 'ar.l04', 'ar.v.zayt', array['ar.v.zayt','ar.g04.non_connecting_letters']::text[], 'reorder', 'lesson', 'Écris « zayt » (l''huile) avec ces lettres.', array['ز ي ت']::text[], 'Zayt : ز (z), ي (y), ت (t). Écrit : زَيْت. ز coupe le mot, puis ي et ت s''attachent.', 3, '{"id": "ar.l04.e19", "unitIds": ["ar.v.zayt", "ar.g04.non_connecting_letters"], "type": "reorder", "difficulty": 3, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « zayt » (l''huile) avec ces lettres.", "promptLanguage": "fr", "tokens": ["ت", "ز", "ي"], "answer": "ز ي ت", "acceptedAnswers": ["ز ي ت"], "explanation": "Zayt : ز (z), ي (y), ت (t). Écrit : زَيْت. ز coupe le mot, puis ي et ت s''attachent.", "tip": "Z d''abord : la virgule avec un point.", "extraExample": {"text": "زَيْتُون", "translation": "des olives", "transliteration": "zaytûn"}, "pool": "lesson", "lessonId": "ar.l04", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e20', 'ar', 'ar.l04', 'ar.v.dadjadj', array['ar.v.dadjadj','ar.g04.non_connecting_letters']::text[], 'translation', 'lesson', 'دَجَاج', array['le poulet','poulet','du poulet','les poulets','la volaille','volaille']::text[], 'دَجَاج se lit dadjâdj et veut dire « le poulet », la volaille en général : د, ج, ا, ج.', 3, '{"id": "ar.l04.e20", "unitIds": ["ar.v.dadjadj", "ar.g04.non_connecting_letters"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "دَجَاج", "promptLanguage": "ar", "answer": "le poulet", "acceptedAnswers": ["le poulet", "poulet", "du poulet", "les poulets", "la volaille", "volaille"], "explanation": "دَجَاج se lit dadjâdj et veut dire « le poulet », la volaille en général : د, ج, ا, ج.", "tip": "Dadjâdj : un angle, puis un crochet avec un point dedans, deux fois.", "extraExample": {"text": "دَجَاجَة", "translation": "une poule", "transliteration": "dadjâdja"}, "errorPatterns": [{"equals": "l''huile", "category": "vocabulary", "feedback": "L''huile se dit زَيْت (zayt). دَجَاج commence par د : dadjâdj, le poulet."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e21', 'ar', 'ar.l04', 'ar.v.ladhidh', array['ar.v.ladhidh','ar.g04.non_connecting_letters']::text[], 'translation', 'lesson', 'لَذِيذ', array['délicieux','délicieuse','très bon','bon','savoureux','succulent']::text[], 'لَذِيذ se lit ladhîdh et veut dire « délicieux ». Deux ذ (angle avec un point) y coupent le mot en deux blocs.', 3, '{"id": "ar.l04.e21", "unitIds": ["ar.v.ladhidh", "ar.g04.non_connecting_letters"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "لَذِيذ", "promptLanguage": "ar", "answer": "délicieux", "acceptedAnswers": ["délicieux", "délicieuse", "très bon", "bon", "savoureux", "succulent"], "explanation": "لَذِيذ se lit ladhîdh et veut dire « délicieux ». Deux ذ (angle avec un point) y coupent le mot en deux blocs.", "tip": "Ladhîdh : l - dh - î - dh. Deux angles avec un point.", "extraExample": {"text": "طَعَام لَذِيذ", "translation": "un repas délicieux", "transliteration": "Ta3âm ladhîdh"}, "errorPatterns": [{"equals": "beau", "category": "vocabulary", "feedback": "« Beau » se dit جَمِيل (djamîl). لَذِيذ (ladhîdh) parle de goût : « délicieux »."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e22', 'ar', 'ar.l04', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.ladhidh','ar.v.dhal']::text[], 'free_answer', 'lesson', 'Comment se lit لَذِيذ (délicieux) ?', array['ladhîdh','ladhidh','ladhiidh','ladhîz','ladhiz']::text[], 'ل (l), ذ (dh), ي (î long), ذ (dh) : ladhîdh, « délicieux ». Les deux ذ ont un point au-dessus.', 4, '{"id": "ar.l04.e22", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.ladhidh", "ar.v.dhal"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines (dh pour ذ, î pour un i long).", "prompt": "Comment se lit لَذِيذ (délicieux) ?", "promptLanguage": "fr", "answer": "ladhîdh", "acceptedAnswers": ["ladhîdh", "ladhidh", "ladhiidh", "ladhîz", "ladhiz"], "explanation": "ل (l), ذ (dh), ي (î long), ذ (dh) : ladhîdh, « délicieux ». Les deux ذ ont un point au-dessus.", "tip": "Deux angles avec un point : dh, dh.", "extraExample": {"text": "لَذِيذَة", "translation": "délicieuse", "transliteration": "ladhîdha"}, "errorPatterns": [{"equals": "ladîd", "category": "spelling", "feedback": "Les deux angles portent un point au-dessus : ce sont des ذ (dh), pas des د (d)."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e23', 'ar', 'ar.l04', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.waw','ar.v.dal']::text[], 'free_answer', 'lesson', 'Comment se lit وَلَد (un garçon) ?', array['walad','waled','welad']::text[], 'و (w), ل (l), د (d) : walad, « un garçon ». و ne s''attache pas à ل, mais ل s''attache à د final.', 4, '{"id": "ar.l04.e23", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.waw", "ar.v.dal"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit وَلَد (un garçon) ?", "promptLanguage": "fr", "answer": "walad", "acceptedAnswers": ["walad", "waled", "welad"], "explanation": "و (w), ل (l), د (d) : walad, « un garçon ». و ne s''attache pas à ل, mais ل s''attache à د final.", "tip": "Boucle fermée = w ; angle sans point = d.", "extraExample": {"text": "أَوْلَاد", "translation": "des garçons, des enfants", "transliteration": "awlâd"}, "errorPatterns": [{"equals": "walaz", "category": "spelling", "feedback": "La dernière lettre est un angle sans point : c''est د (d)."}, {"equals": "warad", "category": "spelling", "feedback": "La deuxième lettre est ل (un trait vertical), pas ر."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e01', 'ar', 'ar.l05', 'ar.v.chin', array['ar.v.chin','ar.g05.sin_chin_sad_dad']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : ـشـ ?', array['chîn (ch)']::text[], 'Une petite scie de trois dents avec trois points au-dessus : c''est ش, sous sa forme du milieu (ـشـ).', 1, '{"id": "ar.l05.e01", "unitIds": ["ar.v.chin", "ar.g05.sin_chin_sad_dad"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : ـشـ ?", "promptLanguage": "fr", "options": ["sîn (s)", "chîn (ch)", "Sâd (S)", "thâ'' (th)"], "answer": "chîn (ch)", "acceptedAnswers": ["chîn (ch)"], "hint": "Scie ou boucle ? Combien de points ?", "explanation": "Une petite scie de trois dents avec trois points au-dessus : c''est ش, sous sa forme du milieu (ـشـ).", "tip": "Scie + trois points = ch.", "extraExample": {"text": "عَشَاء", "translation": "le dîner (ش au milieu)", "transliteration": "3achâ''"}, "errorPatterns": [{"equals": "sîn (s)", "category": "spelling", "feedback": "س a la même scie, mais aucun point. Ici il y en a trois : c''est ش."}, {"equals": "thâ'' (th)", "category": "spelling", "feedback": "ث porte ses trois points sur une seule dent. Ici ils sont posés sur une scie de trois dents : c''est ش."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e02', 'ar', 'ar.l05', 'ar.v.dad', array['ar.v.dad','ar.g05.sin_chin_sad_dad']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : ضـ ?', array['Dâd (D)']::text[], 'Une boucle ronde avec un point au-dessus : c''est ض, sous sa forme du début (ضـ). Sans le point, ce serait ص (S).', 1, '{"id": "ar.l05.e02", "unitIds": ["ar.v.dad", "ar.g05.sin_chin_sad_dad"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : ضـ ?", "promptLanguage": "fr", "options": ["sîn (s)", "chîn (ch)", "Sâd (S)", "Dâd (D)"], "answer": "Dâd (D)", "acceptedAnswers": ["Dâd (D)"], "hint": "Regarde le point au-dessus de la boucle.", "explanation": "Une boucle ronde avec un point au-dessus : c''est ض, sous sa forme du début (ضـ). Sans le point, ce serait ص (S).", "tip": "Boucle + un point dessus = D.", "extraExample": {"text": "ضَيْف", "translation": "l''invité (ض au début)", "transliteration": "Dayf"}, "errorPatterns": [{"equals": "Sâd (S)", "category": "spelling", "feedback": "ص a la même boucle, mais aucun point. Ici il y en a un, au-dessus : c''est ض."}, {"equals": "sîn (s)", "category": "spelling", "feedback": "س est une scie à trois dents. Ici c''est une boucle ronde : c''est ض ou ص."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e03', 'ar', 'ar.l05', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.sin','ar.v.chin','ar.v.sad','ar.v.dad']::text[], 'match', 'lesson', 'Scie ou boucle, avec ou sans points', '{}'::text[], 'Deux formes (scie, boucle), deux versions chacune : س et ص sont « nues », ش (trois points) et ض (un point) sont ornées.', 1, '{"id": "ar.l05.e03", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.sin", "ar.v.chin", "ar.v.sad", "ar.v.dad"], "type": "match", "difficulty": 1, "instruction": "Associe chaque description à sa lettre.", "prompt": "Scie ou boucle, avec ou sans points", "promptLanguage": "fr", "pairs": [{"left": "une scie à trois dents, aucun point", "right": "س"}, {"left": "une scie à trois dents, trois points dessus", "right": "ش"}, {"left": "une boucle ronde, aucun point", "right": "ص"}, {"left": "une boucle ronde, un point dessus", "right": "ض"}], "answer": "une scie à trois dents, aucun point = س ; une scie à trois dents, trois points dessus = ش ; une boucle ronde, aucun point = ص ; une boucle ronde, un point dessus = ض", "acceptedAnswers": [], "explanation": "Deux formes (scie, boucle), deux versions chacune : س et ص sont « nues », ش (trois points) et ض (un point) sont ornées.", "tip": "D''abord la forme, ensuite les points.", "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e04', 'ar', 'ar.l05', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.sad']::text[], 'mcq', 'lesson', 'Quelle lettre est un s « lourd », prononcé avec la langue plaquée contre le palais ?', array['ص']::text[], 'ص (S) est le s « emphatique » : plus profond que س, la bouche plus ronde. On le reconnaît à sa boucle.', 2, '{"id": "ar.l05.e04", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.sad"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un s « lourd », prononcé avec la langue plaquée contre le palais ?", "promptLanguage": "fr", "options": ["س", "ش", "ص", "ث"], "answer": "ص", "acceptedAnswers": ["ص"], "explanation": "ص (S) est le s « emphatique » : plus profond que س, la bouche plus ronde. On le reconnaît à sa boucle.", "tip": "Boucle = son lourd (ص, ض). Scie = son léger (س, ش).", "extraExample": {"text": "صَحْن", "translation": "l''assiette", "transliteration": "Sa7n"}, "errorPatterns": [{"equals": "س", "category": "spelling", "feedback": "س est le s léger, comme dans « sac ». Le s lourd, c''est ص."}, {"equals": "ش", "category": "spelling", "feedback": "ش se prononce ch, comme dans « chat »."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e05', 'ar', 'ar.l05', 'ar.g01.alif_ba_ta_tha', array['ar.g01.alif_ba_ta_tha','ar.g05.sin_chin_sad_dad','ar.v.chin']::text[], 'mcq', 'lesson', 'Quelle lettre a trois points posés sur trois petites dents ?', array['ش']::text[], 'ش a trois points au-dessus d''une scie de trois dents. ث a aussi trois points, mais ils sont sur une seule dent.', 2, '{"id": "ar.l05.e05", "unitIds": ["ar.g01.alif_ba_ta_tha", "ar.g05.sin_chin_sad_dad", "ar.v.chin"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre a trois points posés sur trois petites dents ?", "promptLanguage": "fr", "options": ["ث", "ش", "ت", "س"], "answer": "ش", "acceptedAnswers": ["ش"], "explanation": "ش a trois points au-dessus d''une scie de trois dents. ث a aussi trois points, mais ils sont sur une seule dent.", "tip": "Trois dents + trois points = ch. Une dent + trois points = th.", "extraExample": {"text": "شَوْكَة", "translation": "la fourchette (ش au début)", "transliteration": "chawka"}, "errorPatterns": [{"equals": "ث", "category": "spelling", "feedback": "ث a trois points, mais sur une seule dent : th. Ici il y a trois dents."}, {"equals": "س", "category": "spelling", "feedback": "س a trois dents, mais aucun point."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e06', 'ar', 'ar.l05', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.sarir','ar.v.sin']::text[], 'mcq', 'lesson', 'Comment se lit سَرِير ?', array['sarîr']::text[], 'Une scie sans point : س (s). Puis ر (r), ي (î long) et ر : sarîr, « le lit ».', 2, '{"id": "ar.l05.e06", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.sarir", "ar.v.sin"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit سَرِير ?", "promptLanguage": "fr", "options": ["sarîr", "charîr", "Darîr", "zarîr"], "answer": "sarîr", "acceptedAnswers": ["sarîr"], "hint": "Combien de points sur la première lettre ?", "explanation": "Une scie sans point : س (s). Puis ر (r), ي (î long) et ر : sarîr, « le lit ».", "tip": "Scie sans point = s.", "extraExample": {"text": "سَرِيرِي", "translation": "mon lit", "transliteration": "sarîrî"}, "errorPatterns": [{"equals": "charîr", "category": "spelling", "feedback": "ش aurait trois points au-dessus de sa scie. Ici il n''y en a aucun : c''est س."}, {"equals": "Darîr", "category": "spelling", "feedback": "ض est une boucle ronde avec un point. La première lettre est une scie sans point : c''est س."}, {"equals": "zarîr", "category": "spelling", "feedback": "La première lettre est une scie, pas une virgule avec un point : c''est س (s)."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e07', 'ar', 'ar.l05', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.sahn','ar.v.sad']::text[], 'mcq', 'lesson', 'Comment se lit صَحْن ?', array['Sa7n']::text[], 'Une boucle sans point : ص (S, s lourd). Puis ح (aucun point, noté 7) et ن : Sa7n, « l''assiette ».', 3, '{"id": "ar.l05.e07", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.sahn", "ar.v.sad"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit صَحْن ?", "promptLanguage": "fr", "options": ["Sa7n", "Da7n", "Sadjn", "Sakhn"], "answer": "Sa7n", "acceptedAnswers": ["Sa7n"], "explanation": "Une boucle sans point : ص (S, s lourd). Puis ح (aucun point, noté 7) et ن : Sa7n, « l''assiette ».", "tip": "Boucle sans point = S ; la lettre du milieu n''a pas de point : 7.", "extraExample": {"text": "صُحُون", "translation": "des assiettes", "transliteration": "Su7ûn"}, "errorPatterns": [{"equals": "Sakhn", "category": "spelling", "feedback": "La lettre du milieu n''a aucun point : c''est ح (7), pas خ (kh)."}, {"equals": "Da7n", "category": "spelling", "feedback": "ض aurait un point au-dessus de sa boucle. Ici il n''y en a pas : c''est ص."}, {"equals": "Sadjn", "category": "spelling", "feedback": "La lettre du milieu n''a aucun point : c''est ح (7), pas ج."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e08', 'ar', 'ar.l05', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.dayf','ar.v.dad']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit Dayf (l''invité) ?', array['ضَيْف']::text[], 'Il faut une boucle avec un point au-dessus : ض (D). صَيْف (sans point) se lit Sayf, « l''été » ; سَيْف (une scie) se lit sayf, « l''épée ».', 3, '{"id": "ar.l05.e08", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.dayf", "ar.v.dad"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se lit Dayf (l''invité) ?", "promptLanguage": "fr", "options": ["ضَيْف", "صَيْف", "سَيْف", "شَيْف"], "answer": "ضَيْف", "acceptedAnswers": ["ضَيْف"], "explanation": "Il faut une boucle avec un point au-dessus : ض (D). صَيْف (sans point) se lit Sayf, « l''été » ; سَيْف (une scie) se lit sayf, « l''épée ».", "tip": "Boucle + point dessus = D.", "extraExample": {"text": "ضُيُوف", "translation": "des invités", "transliteration": "Duyûf"}, "errorPatterns": [{"equals": "صَيْف", "category": "spelling", "feedback": "ص n''a aucun point : on lirait « Sayf » (l''été). Pour D, il faut un point au-dessus de la boucle."}, {"equals": "سَيْف", "category": "spelling", "feedback": "س est une scie, pas une boucle : on lirait « sayf » (l''épée)."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e09', 'ar', 'ar.l05', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.misbah','ar.v.sad']::text[], 'mcq', 'lesson', 'Dans مِصْبَاح (la lampe), sous quelle forme est le ص ?', array['médiane']::text[], 'Le ص est entre م, qui s''attache à lui, et ب, auquel il s''attache à son tour : relié des deux côtés, il est en forme du milieu (ـصـ).', 3, '{"id": "ar.l05.e09", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.misbah", "ar.v.sad"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne forme.", "prompt": "Dans مِصْبَاح (la lampe), sous quelle forme est le ص ?", "promptLanguage": "fr", "options": ["initiale", "médiane", "finale", "isolée"], "answer": "médiane", "acceptedAnswers": ["médiane"], "explanation": "Le ص est entre م, qui s''attache à lui, et ب, auquel il s''attache à son tour : relié des deux côtés, il est en forme du milieu (ـصـ).", "tip": "Relié des deux côtés = forme du milieu.", "extraExample": {"text": "مَصَابِيح", "translation": "des lampes (ص au milieu)", "transliteration": "maSâbî7"}, "errorPatterns": [{"equals": "isolée", "category": "grammar", "feedback": "Le ص est relié à م et à ب : il n''est pas isolé."}, {"equals": "initiale", "category": "grammar", "feedback": "La forme initiale est celle de la première lettre du mot. Ici, م vient avant ص."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e10', 'ar', 'ar.l05', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.qamis','ar.v.sad']::text[], 'fill_blank', 'lesson', 'Dans قَمِيص (la chemise), le ص est en forme ___.', array['finale','final','de fin','fin','forme finale']::text[], 'Le ص est la dernière lettre et il est relié au ي qui le précède : c''est sa forme finale, ـص, avec une boucle et une queue.', 3, '{"id": "ar.l05.e10", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.qamis", "ar.v.sad"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le nom de la forme : initiale, médiane, finale ou isolée.", "prompt": "Dans قَمِيص (la chemise), le ص est en forme ___.", "promptLanguage": "fr", "options": ["initiale", "médiane", "finale", "isolée"], "answer": "finale", "acceptedAnswers": ["finale", "final", "de fin", "fin", "forme finale"], "explanation": "Le ص est la dernière lettre et il est relié au ي qui le précède : c''est sa forme finale, ـص, avec une boucle et une queue.", "tip": "Dernière lettre + attachée à droite = forme finale.", "extraExample": {"text": "مَرِيض", "translation": "malade (ض final)", "transliteration": "marîD"}, "errorPatterns": [{"equals": "isolée", "category": "grammar", "feedback": "Le ص est relié au ي d''avant : il n''est pas isolé, il est en forme finale (ـص)."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e11', 'ar', 'ar.l05', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.sarir','ar.v.sin']::text[], 'fill_blank', 'lesson', 'Le lit (sarîr) : ___َرِير', array['سـ','س']::text[], 'Sarîr commence par s : س, une scie sans point. Au début du mot, il prend la forme سـ.', 2, '{"id": "ar.l05.e11", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.sarir", "ar.v.sin"], "type": "fill_blank", "difficulty": 2, "instruction": "Choisis la lettre qui manque.", "prompt": "Le lit (sarîr) : ___َرِير", "promptLanguage": "fr", "options": ["سـ", "شـ", "صـ"], "answer": "سـ", "acceptedAnswers": ["سـ", "س"], "explanation": "Sarîr commence par s : س, une scie sans point. Au début du mot, il prend la forme سـ.", "tip": "Scie sans point = s.", "extraExample": {"text": "مَسَاء", "translation": "le soir", "transliteration": "masâ''"}, "errorPatterns": [{"equals": "شـ", "category": "spelling", "feedback": "شـ (trois points) donnerait « charîr ». Pour le son s, il n''y a aucun point."}, {"equals": "صـ", "category": "spelling", "feedback": "صـ est une boucle (s lourd) : on lirait « Sarîr ». Ici il faut la scie."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e12', 'ar', 'ar.l05', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.dayf','ar.v.dad']::text[], 'fill_blank', 'lesson', 'L''invité (Dayf) : ___َيْف', array['ضـ','ض']::text[], 'Dayf commence par D, le d lourd : ض, une boucle avec un point au-dessus. صـ (sans point) donnerait « Sayf ».', 3, '{"id": "ar.l05.e12", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.dayf", "ar.v.dad"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la lettre qui manque.", "prompt": "L''invité (Dayf) : ___َيْف", "promptLanguage": "fr", "options": ["ضـ", "صـ", "شـ"], "answer": "ضـ", "acceptedAnswers": ["ضـ", "ض"], "explanation": "Dayf commence par D, le d lourd : ض, une boucle avec un point au-dessus. صـ (sans point) donnerait « Sayf ».", "tip": "D lourd = boucle + un point dessus.", "extraExample": {"text": "ضَيْفِي", "translation": "mon invité", "transliteration": "Dayfî"}, "errorPatterns": [{"equals": "صـ", "category": "spelling", "feedback": "صـ n''a pas de point : on lirait « Sayf », l''été. Pour D, il faut un point au-dessus."}, {"equals": "شـ", "category": "spelling", "feedback": "شـ est une scie à trois points : on lirait « chayf »."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e13', 'ar', 'ar.l05', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.chawka','ar.v.chin']::text[], 'fill_blank', 'lesson', 'La fourchette (chawka) : ___َوْكَة', array['شـ','ش']::text[], 'Chawka commence par ch : ش, une scie de trois dents surmontée de trois points. ثـ (trois points sur une seule dent) donnerait « thawka ».', 3, '{"id": "ar.l05.e13", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.chawka", "ar.v.chin"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la lettre qui manque.", "prompt": "La fourchette (chawka) : ___َوْكَة", "promptLanguage": "fr", "options": ["شـ", "سـ", "ثـ"], "answer": "شـ", "acceptedAnswers": ["شـ", "ش"], "explanation": "Chawka commence par ch : ش, une scie de trois dents surmontée de trois points. ثـ (trois points sur une seule dent) donnerait « thawka ».", "tip": "ch = trois dents, trois points.", "extraExample": {"text": "شَوْكَتِي", "translation": "ma fourchette", "transliteration": "chawkatî"}, "errorPatterns": [{"equals": "ثـ", "category": "spelling", "feedback": "ثـ n''a qu''une dent avec trois points : on lirait « thawka ». Ici, la scie est à trois dents."}, {"equals": "سـ", "category": "spelling", "feedback": "سـ n''a aucun point : on lirait « sawka ». Pour ch, il faut les trois points."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e14', 'ar', 'ar.l05', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.g05.sin_chin_sad_dad','ar.v.sarir']::text[], 'mcq', 'lesson', 'Dans سَرِير (le lit), combien de blocs de lettres attachées vois-tu ?', array['deux blocs']::text[], 'س s''attache à ر, mais ر coupe le mot. Le ي repart alors en forme de début, attaché au dernier ر : deux blocs, سر et ير.', 3, '{"id": "ar.l05.e14", "unitIds": ["ar.g04.non_connecting_letters", "ar.g05.sin_chin_sad_dad", "ar.v.sarir"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans سَرِير (le lit), combien de blocs de lettres attachées vois-tu ?", "promptLanguage": "fr", "options": ["un seul bloc", "deux blocs", "trois blocs", "quatre blocs"], "answer": "deux blocs", "acceptedAnswers": ["deux blocs"], "explanation": "س s''attache à ر, mais ر coupe le mot. Le ي repart alors en forme de début, attaché au dernier ر : deux blocs, سر et ير.", "tip": "Chaque coupeuse (ا د ذ ر ز و) ferme un bloc.", "extraExample": {"text": "لَذِيذ", "translation": "délicieux : deux blocs", "transliteration": "ladhîdh"}, "errorPatterns": [{"equals": "un seul bloc", "category": "grammar", "feedback": "ر ne s''attache pas à la lettre suivante : le mot est coupé en deux."}, {"equals": "trois blocs", "category": "grammar", "feedback": "Il n''y a qu''une seule coupure (après le premier ر) qui sépare le mot en deux blocs."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e15', 'ar', 'ar.l05', 'ar.g02.nun_ya_five_teeth', array['ar.g02.nun_ya_five_teeth','ar.v.ya','ar.v.ta']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit bayt (la maison) ?', array['بَيْت']::text[], 'La dernière lettre doit être une dent avec deux points au-dessus : ت (t). Les trois autres finissent par une scie ou une boucle : ش, ص, ض.', 3, '{"id": "ar.l05.e15", "unitIds": ["ar.g02.nun_ya_five_teeth", "ar.v.ya", "ar.v.ta"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se lit bayt (la maison) ?", "promptLanguage": "fr", "options": ["بَيْت", "بَيْش", "بَيْص", "بَيْض"], "answer": "بَيْت", "acceptedAnswers": ["بَيْت"], "explanation": "La dernière lettre doit être une dent avec deux points au-dessus : ت (t). Les trois autres finissent par une scie ou une boucle : ش, ص, ض.", "tip": "Dent ou scie ou boucle ? La silhouette d''abord.", "extraExample": {"text": "بَيْتِي", "translation": "ma maison", "transliteration": "baytî"}, "errorPatterns": [{"equals": "بَيْض", "category": "spelling", "feedback": "ض est une boucle avec un point : on lirait « bayD » (les œufs)."}, {"equals": "بَيْش", "category": "spelling", "feedback": "ش est une scie avec trois points : on lirait « baych »."}, {"equals": "بَيْص", "category": "spelling", "feedback": "ص est une boucle sans point : on lirait « bayS »."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e16', 'ar', 'ar.l05', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.sarir','ar.v.chawka','ar.v.sahn','ar.v.misbah']::text[], 'match', 'lesson', 'La maison et la table', '{}'::text[], 'سَرِير (sarîr) = le lit, شَوْكَة (chawka) = la fourchette, صَحْن (Sa7n) = l''assiette, مِصْبَاح (miSbâ7) = la lampe.', 2, '{"id": "ar.l05.e16", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.sarir", "ar.v.chawka", "ar.v.sahn", "ar.v.misbah"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "La maison et la table", "promptLanguage": "fr", "pairs": [{"left": "سَرِير", "right": "le lit"}, {"left": "شَوْكَة", "right": "la fourchette"}, {"left": "صَحْن", "right": "l''assiette"}, {"left": "مِصْبَاح", "right": "la lampe"}], "answer": "سَرِير = le lit ; شَوْكَة = la fourchette ; صَحْن = l''assiette ; مِصْبَاح = la lampe", "acceptedAnswers": [], "explanation": "سَرِير (sarîr) = le lit, شَوْكَة (chawka) = la fourchette, صَحْن (Sa7n) = l''assiette, مِصْبَاح (miSbâ7) = la lampe.", "tip": "Scie ou boucle te donne déjà le début du mot.", "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e17', 'ar', 'ar.l05', 'ar.v.zayt', array['ar.v.zayt','ar.g04.non_connecting_letters','ar.v.dar','ar.v.khatam','ar.v.djazar']::text[], 'match', 'lesson', 'Des mots des leçons précédentes', '{}'::text[], 'زَيْت (zayt) = l''huile, دَار (dâr) = la demeure, خَاتَم (khâtam) = la bague, جَزَر (djazar) = les carottes.', 2, '{"id": "ar.l05.e17", "unitIds": ["ar.v.zayt", "ar.g04.non_connecting_letters", "ar.v.dar", "ar.v.khatam", "ar.v.djazar"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Des mots des leçons précédentes", "promptLanguage": "fr", "pairs": [{"left": "زَيْت", "right": "l''huile"}, {"left": "دَار", "right": "la demeure"}, {"left": "خَاتَم", "right": "la bague"}, {"left": "جَزَر", "right": "les carottes"}], "answer": "زَيْت = l''huile ; دَار = la demeure ; خَاتَم = la bague ; جَزَر = les carottes", "acceptedAnswers": [], "explanation": "زَيْت (zayt) = l''huile, دَار (dâr) = la demeure, خَاتَم (khâtam) = la bague, جَزَر (djazar) = les carottes.", "tip": "Pour chaque mot, repère les lettres coupeuses et le point du crochet.", "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e18', 'ar', 'ar.l05', 'ar.v.dayf', array['ar.v.dayf','ar.g05.sin_chin_sad_dad']::text[], 'reorder', 'lesson', 'Écris « Dayf » (l''invité) avec ces lettres.', array['ض ي ف']::text[], 'Dayf : ض (D), ي (y), ف (f). Les trois lettres s''attachent : ضَيْف.', 3, '{"id": "ar.l05.e18", "unitIds": ["ar.v.dayf", "ar.g05.sin_chin_sad_dad"], "type": "reorder", "difficulty": 3, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « Dayf » (l''invité) avec ces lettres.", "promptLanguage": "fr", "tokens": ["ف", "ض", "ي"], "answer": "ض ي ف", "acceptedAnswers": ["ض ي ف"], "explanation": "Dayf : ض (D), ي (y), ف (f). Les trois lettres s''attachent : ضَيْف.", "tip": "Commence par la boucle avec un point.", "extraExample": {"text": "ضُيُوف", "translation": "des invités", "transliteration": "Duyûf"}, "pool": "lesson", "lessonId": "ar.l05", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e19', 'ar', 'ar.l05', 'ar.v.sarir', array['ar.v.sarir','ar.g05.sin_chin_sad_dad']::text[], 'reorder', 'lesson', 'Écris « sarîr » (le lit) avec ces lettres.', array['س ر ي ر']::text[], 'Sarîr : س (s), ر (r), ي (î long), ر (r). Écrit : سَرِير.', 3, '{"id": "ar.l05.e19", "unitIds": ["ar.v.sarir", "ar.g05.sin_chin_sad_dad"], "type": "reorder", "difficulty": 3, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « sarîr » (le lit) avec ces lettres.", "promptLanguage": "fr", "tokens": ["ر", "ر", "ي", "س"], "answer": "س ر ي ر", "acceptedAnswers": ["س ر ي ر"], "explanation": "Sarîr : س (s), ر (r), ي (î long), ر (r). Écrit : سَرِير.", "tip": "On commence par la scie, à droite.", "extraExample": {"text": "سَرِيرِي", "translation": "mon lit", "transliteration": "sarîrî"}, "pool": "lesson", "lessonId": "ar.l05", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e20', 'ar', 'ar.l05', 'ar.v.chawka', array['ar.v.chawka','ar.g05.sin_chin_sad_dad']::text[], 'translation', 'lesson', 'شَوْكَة', array['la fourchette','fourchette','une fourchette','l''épine','épine','une épine']::text[], 'شَوْكَة se lit chawka et veut dire « la fourchette » (et aussi « l''épine ») : ش, و, ك, ة.', 3, '{"id": "ar.l05.e20", "unitIds": ["ar.v.chawka", "ar.g05.sin_chin_sad_dad"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "شَوْكَة", "promptLanguage": "ar", "answer": "la fourchette", "acceptedAnswers": ["la fourchette", "fourchette", "une fourchette", "l''épine", "épine", "une épine"], "explanation": "شَوْكَة se lit chawka et veut dire « la fourchette » (et aussi « l''épine ») : ش, و, ك, ة.", "tip": "Chawka : la scie à trois points au début.", "extraExample": {"text": "شَوْكَتِي", "translation": "ma fourchette", "transliteration": "chawkatî"}, "errorPatterns": [{"equals": "la cuillère", "category": "vocabulary", "feedback": "La cuillère se dit مِلْعَقَة (mil3aqa). شَوْكَة (chawka) est la fourchette."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e21', 'ar', 'ar.l05', 'ar.v.qamis', array['ar.v.qamis','ar.g05.sin_chin_sad_dad']::text[], 'translation', 'lesson', 'قَمِيص', array['la chemise','chemise','une chemise']::text[], 'قَمِيص se lit qamîS et veut dire « la chemise ». Il finit par ص, une boucle avec sa queue.', 3, '{"id": "ar.l05.e21", "unitIds": ["ar.v.qamis", "ar.g05.sin_chin_sad_dad"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "قَمِيص", "promptLanguage": "ar", "answer": "la chemise", "acceptedAnswers": ["la chemise", "chemise", "une chemise"], "explanation": "قَمِيص se lit qamîS et veut dire « la chemise ». Il finit par ص, une boucle avec sa queue.", "tip": "QamîS : finit par la boucle sans point.", "extraExample": {"text": "قُمْصَان", "translation": "des chemises", "transliteration": "qumSân"}, "errorPatterns": [{"equals": "le lit", "category": "vocabulary", "feedback": "Le lit se dit سَرِير (sarîr). قَمِيص (qamîS) est un vêtement : la chemise."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e22', 'ar', 'ar.l05', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.misbah','ar.v.sad']::text[], 'free_answer', 'lesson', 'Comment se lit مِصْبَاح (la lampe) ?', array['miSbâ7','miSba7','misbah','misbâh','misbaah','mesbah']::text[], 'م (m), ص (S), ب (b), ا (â long), ح (7) : miSbâ7, « la lampe ». Le ح final est isolé après ا.', 4, '{"id": "ar.l05.e22", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.misbah", "ar.v.sad"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines (S pour ص, 7 pour ح).", "prompt": "Comment se lit مِصْبَاح (la lampe) ?", "promptLanguage": "fr", "answer": "miSbâ7", "acceptedAnswers": ["miSbâ7", "miSba7", "misbah", "misbâh", "misbaah", "mesbah"], "explanation": "م (m), ص (S), ب (b), ا (â long), ح (7) : miSbâ7, « la lampe ». Le ح final est isolé après ا.", "tip": "Boucle sans point au milieu : S. Le dernier crochet n''a aucun point : 7.", "extraExample": {"text": "مِصْبَاحِي", "translation": "ma lampe", "transliteration": "miSbâ7î"}, "errorPatterns": [{"equals": "midbâ7", "category": "spelling", "feedback": "La boucle n''a pas de point : c''est ص (S), pas ض (D)."}, {"equals": "miSbâkh", "category": "spelling", "feedback": "Le dernier crochet n''a aucun point : c''est ح (7), pas خ (kh)."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e23', 'ar', 'ar.l05', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.qamis','ar.v.sad']::text[], 'free_answer', 'lesson', 'Comment se lit قَمِيص (la chemise) ?', array['qamîS','qamis','qamiis','qamiss']::text[], 'ق (q), م (m), ي (î long), ص (S) : qamîS, « la chemise ». La boucle finale n''a pas de point.', 4, '{"id": "ar.l05.e23", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.qamis", "ar.v.sad"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines (S pour ص, î pour un i long).", "prompt": "Comment se lit قَمِيص (la chemise) ?", "promptLanguage": "fr", "answer": "qamîS", "acceptedAnswers": ["qamîS", "qamis", "qamiis", "qamiss"], "explanation": "ق (q), م (m), ي (î long), ص (S) : qamîS, « la chemise ». La boucle finale n''a pas de point.", "tip": "Pas de point sur la boucle : S, et non D.", "extraExample": {"text": "قَمِيصِي", "translation": "ma chemise", "transliteration": "qamîSî"}, "errorPatterns": [{"equals": "qamîD", "category": "spelling", "feedback": "ض aurait un point au-dessus de sa boucle. Ici il n''y en a pas : c''est ص (S)."}, {"equals": "qamîch", "category": "spelling", "feedback": "ش est une scie à trois points. Ici la lettre finale est une boucle : c''est ص (S)."}], "pool": "lesson", "lessonId": "ar.l05", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e01', 'ar', 'ar.l06', 'ar.v.tah', array['ar.v.tah','ar.g06.ta_za_ayn_ghayn']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : طـ ?', array['Tâ'' (T, t lourd)']::text[], 'Une boucle fermée surmontée d''un bâton vertical, sans aucun point : c''est ط, sous sa forme du début (طـ).', 1, '{"id": "ar.l06.e01", "unitIds": ["ar.v.tah", "ar.g06.ta_za_ayn_ghayn"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : طـ ?", "promptLanguage": "fr", "options": ["Tâ'' (T, t lourd)", "tâ'' (t)", "Sâd (S)", "Zâ'' (Z, dh lourd)"], "answer": "Tâ'' (T, t lourd)", "acceptedAnswers": ["Tâ'' (T, t lourd)"], "hint": "Y a-t-il un bâton vertical ?", "explanation": "Une boucle fermée surmontée d''un bâton vertical, sans aucun point : c''est ط, sous sa forme du début (طـ).", "tip": "Boucle + bâton = ط ou ظ ; sans point = ط.", "extraExample": {"text": "طَعَام", "translation": "la nourriture (ط au début)", "transliteration": "Ta3âm"}, "errorPatterns": [{"equals": "Sâd (S)", "category": "spelling", "feedback": "ص est une boucle sans bâton. Ici, un bâton monte au-dessus : c''est ط."}, {"equals": "Zâ'' (Z, dh lourd)", "category": "spelling", "feedback": "ظ porte un point au-dessus du bâton. Ici il n''y en a pas : c''est ط."}, {"equals": "tâ'' (t)", "category": "spelling", "feedback": "ت est une dent avec deux points, sans bâton. Ici c''est une boucle à bâton : ط."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e02', 'ar', 'ar.l06', 'ar.v.zah', array['ar.v.zah','ar.g06.ta_za_ayn_ghayn']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : ـظـ ?', array['Zâ'' (Z, dh lourd)']::text[], 'Une boucle à bâton avec un point au-dessus : c''est ظ, sous sa forme du milieu (ـظـ). Sans le point, ce serait ط.', 1, '{"id": "ar.l06.e02", "unitIds": ["ar.v.zah", "ar.g06.ta_za_ayn_ghayn"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : ـظـ ?", "promptLanguage": "fr", "options": ["Tâ'' (T, t lourd)", "Zâ'' (Z, dh lourd)", "Dâd (D)", "dhâl (dh)"], "answer": "Zâ'' (Z, dh lourd)", "acceptedAnswers": ["Zâ'' (Z, dh lourd)"], "hint": "Regarde bien : bâton ou pas ? point ou pas ?", "explanation": "Une boucle à bâton avec un point au-dessus : c''est ظ, sous sa forme du milieu (ـظـ). Sans le point, ce serait ط.", "tip": "Boucle + bâton + un point dessus = ظ.", "extraExample": {"text": "نَظِيف", "translation": "propre (ظ au milieu)", "transliteration": "naZîf"}, "errorPatterns": [{"equals": "Tâ'' (T, t lourd)", "category": "spelling", "feedback": "ط a la même forme, mais aucun point. Ici il y en a un, au-dessus : c''est ظ."}, {"equals": "Dâd (D)", "category": "spelling", "feedback": "ض est une boucle sans bâton. Ici, un bâton monte au-dessus : c''est ظ."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e03', 'ar', 'ar.l06', 'ar.v.ayn', array['ar.v.ayn','ar.g06.ta_za_ayn_ghayn']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : عـ ?', array['3ayn (3)']::text[], 'Une petite tête triangulaire, sans aucun point : c''est ع, sous sa forme du début (عـ).', 1, '{"id": "ar.l06.e03", "unitIds": ["ar.v.ayn", "ar.g06.ta_za_ayn_ghayn"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : عـ ?", "promptLanguage": "fr", "options": ["3ayn (3)", "ghayn (gh)", "7â'' (7)", "djîm (dj)"], "answer": "3ayn (3)", "acceptedAnswers": ["3ayn (3)"], "hint": "Combien de points ?", "explanation": "Une petite tête triangulaire, sans aucun point : c''est ع, sous sa forme du début (عـ).", "tip": "Tête d''œil sans point = 3.", "extraExample": {"text": "عَسَل", "translation": "le miel (ع au début)", "transliteration": "3asal"}, "errorPatterns": [{"equals": "ghayn (gh)", "category": "spelling", "feedback": "غ a un point au-dessus de sa tête. Ici il n''y en a aucun : c''est ع."}, {"equals": "7â'' (7)", "category": "spelling", "feedback": "ح est un crochet sans point mais sa forme est différente : une tête de crochet, pas une tête triangulaire."}, {"equals": "djîm (dj)", "category": "spelling", "feedback": "ج porte un point dans sa courbe. Ici il n''y a aucun point : c''est ع."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e04', 'ar', 'ar.l06', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.tah','ar.v.zah','ar.v.ayn','ar.v.ghayn']::text[], 'match', 'lesson', 'Bâton ou œil, avec ou sans point', '{}'::text[], 'Deux formes (boucle à bâton, tête d''œil), deux versions chacune : ط et ع sont « nues », ظ et غ portent un point au-dessus.', 1, '{"id": "ar.l06.e04", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.tah", "ar.v.zah", "ar.v.ayn", "ar.v.ghayn"], "type": "match", "difficulty": 1, "instruction": "Associe chaque description à sa lettre.", "prompt": "Bâton ou œil, avec ou sans point", "promptLanguage": "fr", "pairs": [{"left": "une boucle à bâton, aucun point", "right": "ط"}, {"left": "une boucle à bâton, un point dessus", "right": "ظ"}, {"left": "une tête d''œil, aucun point", "right": "ع"}, {"left": "une tête d''œil, un point dessus", "right": "غ"}], "answer": "une boucle à bâton, aucun point = ط ; une boucle à bâton, un point dessus = ظ ; une tête d''œil, aucun point = ع ; une tête d''œil, un point dessus = غ", "acceptedAnswers": [], "explanation": "Deux formes (boucle à bâton, tête d''œil), deux versions chacune : ط et ع sont « nues », ظ et غ portent un point au-dessus.", "tip": "D''abord la forme, ensuite le point.", "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e05', 'ar', 'ar.l06', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.tah','ar.v.sad']::text[], 'mcq', 'lesson', 'Qu''est-ce qui distingue ط de ص ?', array['Un bâton vertical qui monte au-dessus de la boucle']::text[], 'ط et ص ont tous deux une boucle et aucun point. Le bâton vertical est le seul signe qui permet de dire que c''est un ط.', 2, '{"id": "ar.l06.e05", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.tah", "ar.v.sad"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce qui distingue ط de ص ?", "promptLanguage": "fr", "options": ["Un bâton vertical qui monte au-dessus de la boucle", "Trois points au-dessus", "L''absence de boucle", "Une queue plus longue"], "answer": "Un bâton vertical qui monte au-dessus de la boucle", "acceptedAnswers": ["Un bâton vertical qui monte au-dessus de la boucle"], "explanation": "ط et ص ont tous deux une boucle et aucun point. Le bâton vertical est le seul signe qui permet de dire que c''est un ط.", "tip": "Bâton = ط ou ظ. Pas de bâton = ص ou ض.", "extraExample": {"text": "طَعَام", "translation": "la nourriture (ط avec bâton)", "transliteration": "Ta3âm"}, "errorPatterns": [{"equals": "Trois points au-dessus", "category": "grammar", "feedback": "ط n''a aucun point. Trois points, c''est la signature de ش ou ث."}, {"equals": "L''absence de boucle", "category": "grammar", "feedback": "ط a bien une boucle fermée, comme ص."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e06', 'ar', 'ar.l06', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.ghayn','ar.v.ayn']::text[], 'mcq', 'lesson', 'Quelle lettre ressemble au r grasseyé français de « rue » ?', array['غ']::text[], 'غ (gh) se prononce au fond de la gorge, comme le r français de « rue ». ع (3), elle, n''a pas d''équivalent en français ; ر est un r roulé.', 2, '{"id": "ar.l06.e06", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.ghayn", "ar.v.ayn"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre ressemble au r grasseyé français de « rue » ?", "promptLanguage": "fr", "options": ["ع", "غ", "ر", "خ"], "answer": "غ", "acceptedAnswers": ["غ"], "explanation": "غ (gh) se prononce au fond de la gorge, comme le r français de « rue ». ع (3), elle, n''a pas d''équivalent en français ; ر est un r roulé.", "tip": "gh = le r français. 3 = un son de gorge serrée.", "extraExample": {"text": "غُرْفَة", "translation": "la chambre (gh au début)", "transliteration": "ghurfa"}, "errorPatterns": [{"equals": "ر", "category": "spelling", "feedback": "ر est le r roulé de l''arabe (comme en espagnol). Le r grasseyé français correspond plutôt à غ."}, {"equals": "ع", "category": "spelling", "feedback": "ع (3) est un son de gorge serrée sans équivalent en français ; c''est غ (gh) qui ressemble au r de « rue »."}, {"equals": "خ", "category": "spelling", "feedback": "خ (kh) est un souffle rauque, comme la jota espagnole, plus sec que gh."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e07', 'ar', 'ar.l06', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.taam','ar.v.tah']::text[], 'mcq', 'lesson', 'Comment se lit طَعَام ?', array['Ta3âm']::text[], 'ط (T, boucle à bâton), ع (3, tête sans point), ا (â long) et م : Ta3âm, « la nourriture ».', 2, '{"id": "ar.l06.e07", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.taam", "ar.v.tah"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit طَعَام ?", "promptLanguage": "fr", "options": ["Ta3âm", "Sa3âm", "Ta7âm", "Taghâm"], "answer": "Ta3âm", "acceptedAnswers": ["Ta3âm"], "hint": "Regarde le début, puis le point de la deuxième lettre.", "explanation": "ط (T, boucle à bâton), ع (3, tête sans point), ا (â long) et م : Ta3âm, « la nourriture ».", "tip": "Bâton au début : T lourd.", "extraExample": {"text": "أَطْعِمَة", "translation": "des aliments", "transliteration": "aT3ima"}, "errorPatterns": [{"equals": "Sa3âm", "category": "spelling", "feedback": "ص n''a pas de bâton. Ici un bâton monte au-dessus de la boucle : c''est ط (T)."}, {"equals": "Ta7âm", "category": "spelling", "feedback": "ح est un crochet, pas une tête triangulaire : la deuxième lettre est ع (3)."}, {"equals": "Taghâm", "category": "spelling", "feedback": "غ aurait un point au-dessus. Ici la tête n''en a pas : c''est ع (3)."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e08', 'ar', 'ar.l06', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.asal','ar.v.ayn']::text[], 'mcq', 'lesson', 'Comment se lit عَسَل ?', array['3asal']::text[], 'ع (3, sans point), س (s, une scie sans point), ل (l) : 3asal, « le miel ».', 2, '{"id": "ar.l06.e08", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.asal", "ar.v.ayn"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit عَسَل ?", "promptLanguage": "fr", "options": ["3asal", "ghasal", "7asal", "3azal"], "answer": "3asal", "acceptedAnswers": ["3asal"], "explanation": "ع (3, sans point), س (s, une scie sans point), ل (l) : 3asal, « le miel ».", "tip": "Tête sans point en début de mot : 3.", "extraExample": {"text": "عَسَلِي", "translation": "mon miel", "transliteration": "3asalî"}, "errorPatterns": [{"equals": "ghasal", "category": "spelling", "feedback": "غ aurait un point au-dessus de la tête. Ici il n''y en a pas : c''est ع."}, {"equals": "7asal", "category": "spelling", "feedback": "ح est un crochet. La première lettre est une tête triangulaire : ع."}, {"equals": "3azal", "category": "spelling", "feedback": "La deuxième lettre est une scie à trois dents (س), pas une virgule avec un point (ز)."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e09', 'ar', 'ar.l06', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.nazif','ar.v.zah']::text[], 'mcq', 'lesson', 'Comment se lit نَظِيف ?', array['naZîf']::text[], 'ن (n), puis une boucle à bâton avec un point au-dessus : ظ (Z). Puis ي et ف : naZîf, « propre ».', 3, '{"id": "ar.l06.e09", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.nazif", "ar.v.zah"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit نَظِيف ?", "promptLanguage": "fr", "options": ["naZîf", "naTîf", "naDîf", "nadhîf"], "answer": "naZîf", "acceptedAnswers": ["naZîf"], "hint": "Y a-t-il un point au-dessus du bâton ?", "explanation": "ن (n), puis une boucle à bâton avec un point au-dessus : ظ (Z). Puis ي et ف : naZîf, « propre ».", "tip": "Bâton + point dessus = Z.", "extraExample": {"text": "قَمِيص نَظِيف", "translation": "une chemise propre", "transliteration": "qamîS naZîf"}, "errorPatterns": [{"equals": "naTîf", "category": "spelling", "feedback": "ط n''a aucun point. Ici il y en a un, au-dessus du bâton : c''est ظ (Z)."}, {"equals": "naDîf", "category": "spelling", "feedback": "ض n''a pas de bâton. Ici un bâton monte au-dessus de la boucle : c''est ظ."}, {"equals": "nadhîf", "category": "spelling", "feedback": "ذ est un petit angle qui ne s''attache pas à la suite. Ici c''est une boucle à bâton reliée au ي : ظ."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e10', 'ar', 'ar.l06', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.asal','ar.v.ayn']::text[], 'fill_blank', 'lesson', 'Dans طَعَام (la nourriture), le ع est en forme ___.', array['médiane','médian','du milieu','milieu','forme médiane']::text[], 'Le ع est relié à ط qui le précède et à ا qui le suit : relié des deux côtés, il est en forme du milieu (ـعـ).', 3, '{"id": "ar.l06.e10", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.asal", "ar.v.ayn"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le nom de la forme : initiale, médiane, finale ou isolée.", "prompt": "Dans طَعَام (la nourriture), le ع est en forme ___.", "promptLanguage": "fr", "options": ["initiale", "médiane", "finale", "isolée"], "answer": "médiane", "acceptedAnswers": ["médiane", "médian", "du milieu", "milieu", "forme médiane"], "explanation": "Le ع est relié à ط qui le précède et à ا qui le suit : relié des deux côtés, il est en forme du milieu (ـعـ).", "tip": "Relié des deux côtés = forme du milieu.", "extraExample": {"text": "مَعَ", "translation": "avec : ع final attaché", "transliteration": "ma3a"}, "errorPatterns": [{"equals": "finale", "category": "grammar", "feedback": "Le ع n''est pas la dernière lettre : il est suivi de ا puis de م."}, {"equals": "initiale", "category": "grammar", "feedback": "La forme initiale est celle de la première lettre du mot. Ici, ط vient avant ع."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e11', 'ar', 'ar.l06', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.ghurfa','ar.v.ghayn']::text[], 'fill_blank', 'lesson', 'La chambre (ghurfa) : ___ُرْفَة', array['غـ','غ']::text[], 'Ghurfa commence par gh : غ, une tête d''œil avec un point au-dessus. عـ (sans point) donnerait « 3urfa ».', 3, '{"id": "ar.l06.e11", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.ghurfa", "ar.v.ghayn"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la lettre qui manque.", "prompt": "La chambre (ghurfa) : ___ُرْفَة", "promptLanguage": "fr", "options": ["غـ", "عـ", "خـ"], "answer": "غـ", "acceptedAnswers": ["غـ", "غ"], "explanation": "Ghurfa commence par gh : غ, une tête d''œil avec un point au-dessus. عـ (sans point) donnerait « 3urfa ».", "tip": "gh = tête d''œil + un point dessus.", "extraExample": {"text": "غُرَف", "translation": "des chambres", "transliteration": "ghuraf"}, "errorPatterns": [{"equals": "عـ", "category": "spelling", "feedback": "عـ n''a pas de point : on lirait « 3urfa ». Pour gh, il faut le point au-dessus."}, {"equals": "خـ", "category": "spelling", "feedback": "خـ est un crochet. Ici c''est une tête d''œil : غـ."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e12', 'ar', 'ar.l06', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.asal','ar.v.ayn']::text[], 'fill_blank', 'lesson', 'Le miel (3asal) : ___َسَل', array['عـ','ع']::text[], '3asal commence par 3 : ع, une tête d''œil sans point. غـ (avec un point) donnerait « ghasal ».', 3, '{"id": "ar.l06.e12", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.asal", "ar.v.ayn"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la lettre qui manque.", "prompt": "Le miel (3asal) : ___َسَل", "promptLanguage": "fr", "options": ["عـ", "غـ", "حـ"], "answer": "عـ", "acceptedAnswers": ["عـ", "ع"], "explanation": "3asal commence par 3 : ع, une tête d''œil sans point. غـ (avec un point) donnerait « ghasal ».", "tip": "3 = tête d''œil sans point.", "extraExample": {"text": "عَسَلِي", "translation": "mon miel", "transliteration": "3asalî"}, "errorPatterns": [{"equals": "غـ", "category": "spelling", "feedback": "غـ a un point au-dessus : on lirait « ghasal ». Pour 3, il n''y en a aucun."}, {"equals": "حـ", "category": "spelling", "feedback": "حـ est un crochet, pas une tête d''œil : on lirait « 7asal »."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e13', 'ar', 'ar.l06', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.asir','ar.v.sad']::text[], 'fill_blank', 'lesson', 'Le jus (3aSîr) : عَ___ِير', array['ـصـ','ص']::text[], '3aSîr a un S lourd au milieu : ص, une boucle sans point ni bâton, sous sa forme du milieu (ـصـ).', 3, '{"id": "ar.l06.e13", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.asir", "ar.v.sad"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la lettre qui manque.", "prompt": "Le jus (3aSîr) : عَ___ِير", "promptLanguage": "fr", "options": ["ـصـ", "ـضـ", "ـطـ"], "answer": "ـصـ", "acceptedAnswers": ["ـصـ", "ص"], "explanation": "3aSîr a un S lourd au milieu : ص, une boucle sans point ni bâton, sous sa forme du milieu (ـصـ).", "tip": "Boucle seule, sans point : S.", "extraExample": {"text": "مِصْبَاح", "translation": "la lampe", "transliteration": "miSbâ7"}, "errorPatterns": [{"equals": "ـضـ", "category": "spelling", "feedback": "ـضـ a un point au-dessus : on lirait « 3aDîr ». Pour S, aucun point."}, {"equals": "ـطـ", "category": "spelling", "feedback": "ـطـ a un bâton : on lirait « 3aTîr ». Pour S, la boucle est seule."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e14', 'ar', 'ar.l06', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.sahn','ar.v.sad']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit Sa7n (l''assiette) ?', array['صَحْن']::text[], 'Il faut une boucle sans point ni bâton : ص (S). ضَحْن a un point (D), طَحْن un bâton (T, « moudre »), سَحْن une scie (s).', 3, '{"id": "ar.l06.e14", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.sahn", "ar.v.sad"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se lit Sa7n (l''assiette) ?", "promptLanguage": "fr", "options": ["صَحْن", "ضَحْن", "طَحْن", "سَحْن"], "answer": "صَحْن", "acceptedAnswers": ["صَحْن"], "explanation": "Il faut une boucle sans point ni bâton : ص (S). ضَحْن a un point (D), طَحْن un bâton (T, « moudre »), سَحْن une scie (s).", "tip": "Boucle nue = S. Point = D. Bâton = T. Scie = s.", "extraExample": {"text": "صُحُون", "translation": "des assiettes", "transliteration": "Su7ûn"}, "errorPatterns": [{"equals": "ضَحْن", "category": "spelling", "feedback": "ض a un point au-dessus de sa boucle : on lirait « Da7n »."}, {"equals": "طَحْن", "category": "spelling", "feedback": "ط a un bâton vertical : on lirait « Ta7n » (c''est un autre mot : moudre)."}, {"equals": "سَحْن", "category": "spelling", "feedback": "س est une scie à trois dents, pas une boucle : on lirait « sa7n »."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e15', 'ar', 'ar.l06', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.tawila','ar.v.waw']::text[], 'mcq', 'lesson', 'Dans طَاوِلَة (la table), combien de blocs de lettres attachées vois-tu ?', array['trois blocs']::text[], 'ط s''attache à ا (bloc 1 : طا). Mais ا coupe, puis و coupe aussi : il reste seul (bloc 2). Enfin ل s''attache à ة (bloc 3 : لة).', 3, '{"id": "ar.l06.e15", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.tawila", "ar.v.waw"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans طَاوِلَة (la table), combien de blocs de lettres attachées vois-tu ?", "promptLanguage": "fr", "options": ["un seul bloc", "deux blocs", "trois blocs", "quatre blocs"], "answer": "trois blocs", "acceptedAnswers": ["trois blocs"], "explanation": "ط s''attache à ا (bloc 1 : طا). Mais ا coupe, puis و coupe aussi : il reste seul (bloc 2). Enfin ل s''attache à ة (bloc 3 : لة).", "tip": "Les coupeuses ا et و ferment chacune un bloc.", "extraExample": {"text": "دَجَاج", "translation": "trois blocs aussi : د | جا | ج", "transliteration": "dadjâdj"}, "errorPatterns": [{"equals": "deux blocs", "category": "grammar", "feedback": "و est une coupeuse : il reste seul entre les blocs طا et لة, ce qui fait trois blocs."}, {"equals": "quatre blocs", "category": "grammar", "feedback": "Une seule lettre (و) est isolée au milieu ; ط et ا sont attachés, ainsi que ل et ة."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e16', 'ar', 'ar.l06', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.taam','ar.v.tawila','ar.v.asal','ar.v.asir']::text[], 'match', 'lesson', 'À table', '{}'::text[], 'طَعَام (Ta3âm) = la nourriture, طَاوِلَة (Tâwila) = la table, عَسَل (3asal) = le miel, عَصِير (3aSîr) = le jus.', 2, '{"id": "ar.l06.e16", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.taam", "ar.v.tawila", "ar.v.asal", "ar.v.asir"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "À table", "promptLanguage": "fr", "pairs": [{"left": "طَعَام", "right": "la nourriture"}, {"left": "طَاوِلَة", "right": "la table"}, {"left": "عَسَل", "right": "le miel"}, {"left": "عَصِير", "right": "le jus"}], "answer": "طَعَام = la nourriture ; طَاوِلَة = la table ; عَسَل = le miel ; عَصِير = le jus", "acceptedAnswers": [], "explanation": "طَعَام (Ta3âm) = la nourriture, طَاوِلَة (Tâwila) = la table, عَسَل (3asal) = le miel, عَصِير (3aSîr) = le jus.", "tip": "Bâton au début : ط ; tête d''œil au début : ع.", "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e17', 'ar', 'ar.l06', 'ar.v.sarir', array['ar.v.sarir','ar.g05.sin_chin_sad_dad','ar.v.dayf','ar.v.qamis','ar.v.dadjadj']::text[], 'match', 'lesson', 'Révision des leçons 4 et 5', '{}'::text[], 'سَرِير (sarîr) = le lit, ضَيْف (Dayf) = l''invité, قَمِيص (qamîS) = la chemise, دَجَاج (dadjâdj) = le poulet.', 2, '{"id": "ar.l06.e17", "unitIds": ["ar.v.sarir", "ar.g05.sin_chin_sad_dad", "ar.v.dayf", "ar.v.qamis", "ar.v.dadjadj"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Révision des leçons 4 et 5", "promptLanguage": "fr", "pairs": [{"left": "سَرِير", "right": "le lit"}, {"left": "ضَيْف", "right": "l''invité"}, {"left": "قَمِيص", "right": "la chemise"}, {"left": "دَجَاج", "right": "le poulet"}], "answer": "سَرِير = le lit ; ضَيْف = l''invité ; قَمِيص = la chemise ; دَجَاج = le poulet", "acceptedAnswers": [], "explanation": "سَرِير (sarîr) = le lit, ضَيْف (Dayf) = l''invité, قَمِيص (qamîS) = la chemise, دَجَاج (dadjâdj) = le poulet.", "tip": "Scie, boucle, angle : la silhouette d''abord.", "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e18', 'ar', 'ar.l06', 'ar.v.asal', array['ar.v.asal','ar.g06.ta_za_ayn_ghayn']::text[], 'reorder', 'lesson', 'Écris « 3asal » (le miel) avec ces lettres.', array['ع س ل']::text[], '3asal : ع (3), س (s), ل (l). Écrit : عَسَل.', 3, '{"id": "ar.l06.e18", "unitIds": ["ar.v.asal", "ar.g06.ta_za_ayn_ghayn"], "type": "reorder", "difficulty": 3, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « 3asal » (le miel) avec ces lettres.", "promptLanguage": "fr", "tokens": ["ل", "ع", "س"], "answer": "ع س ل", "acceptedAnswers": ["ع س ل"], "explanation": "3asal : ع (3), س (s), ل (l). Écrit : عَسَل.", "tip": "Commence par la tête d''œil sans point.", "extraExample": {"text": "عَسَلِي", "translation": "mon miel", "transliteration": "3asalî"}, "pool": "lesson", "lessonId": "ar.l06", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e19', 'ar', 'ar.l06', 'ar.v.taam', array['ar.v.taam','ar.g06.ta_za_ayn_ghayn']::text[], 'reorder', 'lesson', 'Écris « Ta3âm » (la nourriture) avec ces lettres.', array['ط ع ا م']::text[], 'Ta3âm : ط (T), ع (3), ا (â long), م (m). Écrit : طَعَام, avec un م isolé après ا.', 3, '{"id": "ar.l06.e19", "unitIds": ["ar.v.taam", "ar.g06.ta_za_ayn_ghayn"], "type": "reorder", "difficulty": 3, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « Ta3âm » (la nourriture) avec ces lettres.", "promptLanguage": "fr", "tokens": ["م", "ا", "ط", "ع"], "answer": "ط ع ا م", "acceptedAnswers": ["ط ع ا م"], "explanation": "Ta3âm : ط (T), ع (3), ا (â long), م (m). Écrit : طَعَام, avec un م isolé après ا.", "tip": "Boucle à bâton d''abord, puis tête d''œil.", "extraExample": {"text": "طَعَام لَذِيذ", "translation": "un repas délicieux", "transliteration": "Ta3âm ladhîdh"}, "pool": "lesson", "lessonId": "ar.l06", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e20', 'ar', 'ar.l06', 'ar.v.ghurfa', array['ar.v.ghurfa','ar.g06.ta_za_ayn_ghayn']::text[], 'translation', 'lesson', 'غُرْفَة', array['la chambre','chambre','une chambre','la pièce','pièce','une pièce']::text[], 'غُرْفَة se lit ghurfa et veut dire « la chambre », ou plus largement une pièce de la maison.', 3, '{"id": "ar.l06.e20", "unitIds": ["ar.v.ghurfa", "ar.g06.ta_za_ayn_ghayn"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "غُرْفَة", "promptLanguage": "ar", "answer": "la chambre", "acceptedAnswers": ["la chambre", "chambre", "une chambre", "la pièce", "pièce", "une pièce"], "explanation": "غُرْفَة se lit ghurfa et veut dire « la chambre », ou plus largement une pièce de la maison.", "tip": "Ghurfa : tête d''œil avec un point au début.", "extraExample": {"text": "غُرْفَتِي", "translation": "ma chambre", "transliteration": "ghurfatî"}, "errorPatterns": [{"equals": "la maison", "category": "vocabulary", "feedback": "La maison se dit بَيْت (bayt). غُرْفَة (ghurfa), c''est la chambre, une pièce à l''intérieur."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e21', 'ar', 'ar.l06', 'ar.v.nazif', array['ar.v.nazif','ar.g06.ta_za_ayn_ghayn']::text[], 'translation', 'lesson', 'نَظِيف', array['propre','nette','net','propres']::text[], 'نَظِيف se lit naZîf et veut dire « propre ». On l''emploie pour un lieu, un vêtement, une personne.', 3, '{"id": "ar.l06.e21", "unitIds": ["ar.v.nazif", "ar.g06.ta_za_ayn_ghayn"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "نَظِيف", "promptLanguage": "ar", "answer": "propre", "acceptedAnswers": ["propre", "nette", "net", "propres"], "explanation": "نَظِيف se lit naZîf et veut dire « propre ». On l''emploie pour un lieu, un vêtement, une personne.", "tip": "NaZîf : ن puis ظ, la boucle à bâton avec un point.", "extraExample": {"text": "بَيْت نَظِيف", "translation": "une maison propre", "transliteration": "bayt naZîf"}, "errorPatterns": [{"equals": "sale", "category": "vocabulary", "feedback": "Le contraire ! « Sale » se dit وَسِخ (wasikh). نَظِيف veut dire « propre »."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e22', 'ar', 'ar.l06', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.tawila','ar.v.tah']::text[], 'free_answer', 'lesson', 'Comment se lit طَاوِلَة (la table) ?', array['Tâwila','Tawila','Taawila','Tâwla']::text[], 'ط (T), ا (â long), و (w), ل (l), ة (a) : Tâwila, « la table ». ط a un bâton et aucun point.', 4, '{"id": "ar.l06.e22", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.tawila", "ar.v.tah"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines (T pour ط, â pour un a long).", "prompt": "Comment se lit طَاوِلَة (la table) ?", "promptLanguage": "fr", "answer": "Tâwila", "acceptedAnswers": ["Tâwila", "Tawila", "Taawila", "Tâwla"], "explanation": "ط (T), ا (â long), و (w), ل (l), ة (a) : Tâwila, « la table ». ط a un bâton et aucun point.", "tip": "Bâton sans point : T lourd.", "extraExample": {"text": "طَاوِلَات", "translation": "des tables", "transliteration": "Tâwilât"}, "errorPatterns": [{"equals": "Dâwila", "category": "spelling", "feedback": "ض n''a pas de bâton : ici la boucle a un bâton vertical, c''est ط (T)."}, {"equals": "Zâwila", "category": "spelling", "feedback": "ظ aurait un point au-dessus du bâton. Ici il n''y en a pas : c''est ط."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e23', 'ar', 'ar.l06', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.asir','ar.v.ayn']::text[], 'free_answer', 'lesson', 'Comment se lit عَصِير (le jus) ?', array['3aSîr','3asir','3asiir']::text[], 'ع (3), ص (S), ي (î long), ر (r) : 3aSîr, « le jus ». La tête d''œil n''a pas de point, la boucle non plus.', 4, '{"id": "ar.l06.e23", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.asir", "ar.v.ayn"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines (3 pour ع, S pour ص).", "prompt": "Comment se lit عَصِير (le jus) ?", "promptLanguage": "fr", "answer": "3aSîr", "acceptedAnswers": ["3aSîr", "3asir", "3asiir"], "explanation": "ع (3), ص (S), ي (î long), ر (r) : 3aSîr, « le jus ». La tête d''œil n''a pas de point, la boucle non plus.", "tip": "Tête d''œil sans point : 3. Boucle nue : S.", "extraExample": {"text": "عَصِيرُ جَزَر", "translation": "du jus de carotte", "transliteration": "3aSîru djazar"}, "errorPatterns": [{"equals": "ghaSîr", "category": "spelling", "feedback": "غ aurait un point au-dessus de sa tête. Ici il n''y en a pas : c''est ع (3)."}, {"equals": "3aDîr", "category": "spelling", "feedback": "ض aurait un point au-dessus de sa boucle. Ici il n''y en a pas : c''est ص (S)."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e01', 'ar', 'ar.l07', 'ar.v.fa', array['ar.v.fa','ar.g07.fa_qaf_kaf_lam_mim_ha']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : ـفـ ?', array['fâ'' (f)']::text[], 'Une petite tête ronde avec un seul point au-dessus, attachée des deux côtés : c''est ف, sous sa forme du milieu (ـفـ).', 1, '{"id": "ar.l07.e01", "unitIds": ["ar.v.fa", "ar.g07.fa_qaf_kaf_lam_mim_ha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : ـفـ ?", "promptLanguage": "fr", "options": ["fâ'' (f)", "qâf (q)", "bâ'' (b)", "wâw (w, û)"], "answer": "fâ'' (f)", "acceptedAnswers": ["fâ'' (f)"], "hint": "Combien de points ?", "explanation": "Une petite tête ronde avec un seul point au-dessus, attachée des deux côtés : c''est ف, sous sa forme du milieu (ـفـ).", "tip": "Tête ronde + 1 point dessus = f.", "extraExample": {"text": "مِفْتَاح", "translation": "la clé (ف au milieu)", "transliteration": "miftâ7"}, "errorPatterns": [{"equals": "qâf (q)", "category": "spelling", "feedback": "ق a deux points au-dessus de sa tête. Ici il n''y en a qu''un : c''est ف."}, {"equals": "bâ'' (b)", "category": "spelling", "feedback": "ب est une dent avec un point en dessous. Ici c''est une tête ronde avec un point dessus : ف."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e02', 'ar', 'ar.l07', 'ar.v.qaf', array['ar.v.qaf','ar.g07.fa_qaf_kaf_lam_mim_ha']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : ـق ?', array['qâf (q)']::text[], 'Une tête ronde avec deux points au-dessus, suivie d''une longue queue qui plonge sous la ligne : c''est ق, sous sa forme de fin (ـق).', 1, '{"id": "ar.l07.e02", "unitIds": ["ar.v.qaf", "ar.g07.fa_qaf_kaf_lam_mim_ha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : ـق ?", "promptLanguage": "fr", "options": ["fâ'' (f)", "qâf (q)", "nûn (n)", "Sâd (S)"], "answer": "qâf (q)", "acceptedAnswers": ["qâf (q)"], "hint": "Compte les points au-dessus.", "explanation": "Une tête ronde avec deux points au-dessus, suivie d''une longue queue qui plonge sous la ligne : c''est ق, sous sa forme de fin (ـق).", "tip": "Tête ronde + 2 points dessus = q.", "extraExample": {"text": "بَقَرَة", "translation": "la vache (ق au milieu)", "transliteration": "baqara"}, "errorPatterns": [{"equals": "fâ'' (f)", "category": "spelling", "feedback": "ف n''a qu''un seul point. Ici il y en a deux : c''est ق."}, {"equals": "nûn (n)", "category": "spelling", "feedback": "ن est une cuvette avec un seul point. Ici c''est une tête ronde avec deux points : ق."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e03', 'ar', 'ar.l07', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.qaf']::text[], 'mcq', 'lesson', 'Quelle lettre se prononce comme un k, mais tout au fond de la gorge ?', array['ق']::text[], 'ق (q) est le k « profond ». ك est le k ordinaire ; خ (kh) et غ (gh) sont des souffles rauques, pas des k.', 2, '{"id": "ar.l07.e03", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.qaf"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre se prononce comme un k, mais tout au fond de la gorge ?", "promptLanguage": "fr", "options": ["ق", "ك", "خ", "غ"], "answer": "ق", "acceptedAnswers": ["ق"], "explanation": "ق (q) est le k « profond ». ك est le k ordinaire ; خ (kh) et غ (gh) sont des souffles rauques, pas des k.", "tip": "q = k du fond de la gorge. En Égypte, souvent une petite coupure de gorge.", "extraExample": {"text": "قَلَم", "translation": "le stylo", "transliteration": "qalam"}, "errorPatterns": [{"equals": "ك", "category": "spelling", "feedback": "ك est le k ordinaire, comme dans « kilo ». Le k profond, c''est ق."}, {"equals": "خ", "category": "spelling", "feedback": "خ (kh) est un souffle rauque comme la jota espagnole, pas un k."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e04', 'ar', 'ar.l07', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.kaf','ar.v.lam','ar.v.mim','ar.v.ha']::text[], 'match', 'lesson', 'Quatre lettres à reconnaître sous leur forme attachée', '{}'::text[], 'كـ (zigzag) = k, ـلـ (trait vertical) = l, ـمـ (petite bosse sur la ligne) = m, ـه (forme de fin) = h.', 1, '{"id": "ar.l07.e04", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.kaf", "ar.v.lam", "ar.v.mim", "ar.v.ha"], "type": "match", "difficulty": 1, "instruction": "Associe chaque forme au nom de sa lettre.", "prompt": "Quatre lettres à reconnaître sous leur forme attachée", "promptLanguage": "fr", "pairs": [{"left": "كـ", "right": "kâf (k)"}, {"left": "ـلـ", "right": "lâm (l)"}, {"left": "ـمـ", "right": "mîm (m)"}, {"left": "ـه", "right": "hâ'' (h)"}], "answer": "كـ = kâf (k) ; ـلـ = lâm (l) ; ـمـ = mîm (m) ; ـه = hâ'' (h)", "acceptedAnswers": [], "explanation": "كـ (zigzag) = k, ـلـ (trait vertical) = l, ـمـ (petite bosse sur la ligne) = m, ـه (forme de fin) = h.", "tip": "ك : zigzag. ل : trait nu. م : boule. ه : quatre visages à connaître.", "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e05', 'ar', 'ar.l07', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.kaf','ar.v.lam']::text[], 'mcq', 'lesson', 'Quelle lettre contient un petit zigzag dans son trait haut ?', array['ك']::text[], 'Le zigzag est la signature de ك. ل et ا sont des traits verticaux tout simples, sans rien dedans.', 2, '{"id": "ar.l07.e05", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.kaf", "ar.v.lam"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre contient un petit zigzag dans son trait haut ?", "promptLanguage": "fr", "options": ["ك", "ل", "ا", "م"], "answer": "ك", "acceptedAnswers": ["ك"], "hint": "Pense au « k » de kilo.", "explanation": "Le zigzag est la signature de ك. ل et ا sont des traits verticaux tout simples, sans rien dedans.", "tip": "Zigzag = k. Trait nu = l (ou alif).", "extraExample": {"text": "كُوب", "translation": "le verre (ك au début)", "transliteration": "kûb"}, "errorPatterns": [{"equals": "ل", "category": "spelling", "feedback": "ل est un trait vertical tout simple. Le zigzag, c''est ك."}, {"equals": "ا", "category": "spelling", "feedback": "ا est un trait vertical sans rien dedans, qui ne s''attache pas à la suite."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e06', 'ar', 'ar.l07', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.lam','ar.v.alif']::text[], 'mcq', 'lesson', 'Quelle lettre ressemble à ا mais s''attache à la lettre suivante ?', array['ل']::text[], 'ل est un grand trait vertical comme ا, mais il s''attache à la lettre suivante (لـ), ce que ا ne fait jamais. Il se termine, isolé ou final, par une base arrondie.', 2, '{"id": "ar.l07.e06", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.lam", "ar.v.alif"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre ressemble à ا mais s''attache à la lettre suivante ?", "promptLanguage": "fr", "options": ["ل", "ك", "د", "ط"], "answer": "ل", "acceptedAnswers": ["ل"], "explanation": "ل est un grand trait vertical comme ا, mais il s''attache à la lettre suivante (لـ), ce que ا ne fait jamais. Il se termine, isolé ou final, par une base arrondie.", "tip": "Trait nu qui s''attache = ل. Trait nu qui coupe = ا.", "extraExample": {"text": "قَلَم", "translation": "le stylo (ل attaché des deux côtés)", "transliteration": "qalam"}, "errorPatterns": [{"equals": "ك", "category": "spelling", "feedback": "ك contient un zigzag : ce n''est pas un trait nu."}, {"equals": "د", "category": "grammar", "feedback": "د est un petit angle qui ne s''attache pas à la suite."}, {"equals": "ط", "category": "spelling", "feedback": "ط a une boucle à sa base, pas un simple trait."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e07', 'ar', 'ar.l07', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.ha']::text[], 'match', 'lesson', 'Les quatre visages de ه', '{}'::text[], 'ه est la lettre dont les formes se ressemblent le moins : ه (isolée), هـ (début), ـهـ (milieu), ـه (fin). Il faut les apprendre toutes les quatre.', 2, '{"id": "ar.l07.e07", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.ha"], "type": "match", "difficulty": 2, "instruction": "Associe chaque forme de ه à sa place dans le mot.", "prompt": "Les quatre visages de ه", "promptLanguage": "fr", "pairs": [{"left": "ه", "right": "isolée"}, {"left": "هـ", "right": "début de mot"}, {"left": "ـهـ", "right": "milieu de mot"}, {"left": "ـه", "right": "fin de mot"}], "answer": "ه = isolée ; هـ = début de mot ; ـهـ = milieu de mot ; ـه = fin de mot", "acceptedAnswers": [], "explanation": "ه est la lettre dont les formes se ressemblent le moins : ه (isolée), هـ (début), ـهـ (milieu), ـه (fin). Il faut les apprendre toutes les quatre.", "tip": "Ne cherche pas de ressemblance : mémorise quatre dessins.", "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e08', 'ar', 'ar.l07', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.ha']::text[], 'mcq', 'lesson', 'Laquelle de ces formes est celle de ه au milieu d''un mot ?', array['ـهـ']::text[], 'Au milieu d''un mot, ه est attaché des deux côtés : ـهـ. هـ est la forme du début, ـه celle de la fin, ه la forme isolée.', 3, '{"id": "ar.l07.e08", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.ha"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne forme.", "prompt": "Laquelle de ces formes est celle de ه au milieu d''un mot ?", "promptLanguage": "fr", "options": ["ه", "هـ", "ـهـ", "ـه"], "answer": "ـهـ", "acceptedAnswers": ["ـهـ"], "explanation": "Au milieu d''un mot, ه est attaché des deux côtés : ـهـ. هـ est la forme du début, ـه celle de la fin, ه la forme isolée.", "tip": "Milieu = trait de liaison des deux côtés.", "extraExample": {"text": "جِهَاز", "translation": "l''appareil (ه au milieu)", "transliteration": "djihâz"}, "errorPatterns": [{"equals": "هـ", "category": "spelling", "feedback": "هـ n''est attaché qu''à gauche : c''est la forme du début."}, {"equals": "ـه", "category": "spelling", "feedback": "ـه n''est attaché qu''à droite : c''est la forme de fin."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e09', 'ar', 'ar.l07', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.qalam','ar.v.qaf']::text[], 'mcq', 'lesson', 'Comment se lit قَلَم ?', array['qalam']::text[], 'ق (deux points dessus) puis ل (trait vertical) et م : qalam, « le stylo ».', 2, '{"id": "ar.l07.e09", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.qalam", "ar.v.qaf"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit قَلَم ?", "promptLanguage": "fr", "options": ["qalam", "falam", "kalam", "qaram"], "answer": "qalam", "acceptedAnswers": ["qalam"], "hint": "Combien de points sur la première lettre ?", "explanation": "ق (deux points dessus) puis ل (trait vertical) et م : qalam, « le stylo ».", "tip": "Deux points sur une tête ronde au début : q.", "extraExample": {"text": "قَلَمِي", "translation": "mon stylo", "transliteration": "qalamî"}, "errorPatterns": [{"equals": "falam", "category": "spelling", "feedback": "ف n''a qu''un point. La première lettre en a deux : c''est ق."}, {"equals": "kalam", "category": "spelling", "feedback": "ك est un trait haut avec un zigzag. La première lettre est une tête ronde à deux points : ق."}, {"equals": "qaram", "category": "spelling", "feedback": "La deuxième lettre est un trait vertical : c''est ل, pas ر (qui est une virgule sous la ligne)."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e10', 'ar', 'ar.l07', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.hatif','ar.v.ha']::text[], 'mcq', 'lesson', 'Comment se lit هَاتِف ?', array['hâtif']::text[], 'ه (h léger), ا (â long), ت (t) et ف (une tête ronde, un point dessus) : hâtif, « le téléphone ».', 3, '{"id": "ar.l07.e10", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.hatif", "ar.v.ha"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit هَاتِف ?", "promptLanguage": "fr", "options": ["hâtif", "7âtif", "hâtik", "hâtiq"], "answer": "hâtif", "acceptedAnswers": ["hâtif"], "explanation": "ه (h léger), ا (â long), ت (t) et ف (une tête ronde, un point dessus) : hâtif, « le téléphone ».", "tip": "La dernière lettre est une tête avec un seul point : f.", "extraExample": {"text": "هَوَاتِف", "translation": "des téléphones", "transliteration": "hawâtif"}, "errorPatterns": [{"equals": "7âtif", "category": "spelling", "feedback": "ح est un crochet sans point. La première lettre est un ه (h léger), pas un h rauque."}, {"equals": "hâtik", "category": "spelling", "feedback": "ك contient un zigzag. La dernière lettre est une tête ronde avec un point : ف."}, {"equals": "hâtiq", "category": "spelling", "feedback": "ق a deux points. Ici il n''y en a qu''un seul : ف."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e11', 'ar', 'ar.l07', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.miftah','ar.v.fa']::text[], 'fill_blank', 'lesson', 'Dans مِفْتَاح (la clé), le ف est en forme ___.', array['médiane','médian','du milieu','milieu','forme médiane']::text[], 'Le ف est relié à م qui le précède et à ت qui le suit : relié des deux côtés, il est en forme du milieu (ـفـ).', 3, '{"id": "ar.l07.e11", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.miftah", "ar.v.fa"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le nom de la forme : initiale, médiane, finale ou isolée.", "prompt": "Dans مِفْتَاح (la clé), le ف est en forme ___.", "promptLanguage": "fr", "options": ["initiale", "médiane", "finale", "isolée"], "answer": "médiane", "acceptedAnswers": ["médiane", "médian", "du milieu", "milieu", "forme médiane"], "explanation": "Le ف est relié à م qui le précède et à ت qui le suit : relié des deux côtés, il est en forme du milieu (ـفـ).", "tip": "Relié des deux côtés = forme du milieu.", "extraExample": {"text": "هَاتِف", "translation": "le téléphone : ف final", "transliteration": "hâtif"}, "errorPatterns": [{"equals": "finale", "category": "grammar", "feedback": "Le ف n''est pas la dernière lettre : il est suivi de ت."}, {"equals": "initiale", "category": "grammar", "feedback": "La forme initiale est celle de la première lettre du mot. Ici, م vient avant ف."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e12', 'ar', 'ar.l07', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.kub','ar.v.kaf']::text[], 'fill_blank', 'lesson', 'Le verre (kûb) : ___ُوب', array['كـ','ك']::text[], 'Kûb commence par k : ك, un trait haut avec un zigzag. لـ (trait nu) donnerait « lûb » ; قـ (tête à deux points) « qûb ».', 3, '{"id": "ar.l07.e12", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.kub", "ar.v.kaf"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la lettre qui manque.", "prompt": "Le verre (kûb) : ___ُوب", "promptLanguage": "fr", "options": ["كـ", "لـ", "قـ"], "answer": "كـ", "acceptedAnswers": ["كـ", "ك"], "explanation": "Kûb commence par k : ك, un trait haut avec un zigzag. لـ (trait nu) donnerait « lûb » ; قـ (tête à deux points) « qûb ».", "tip": "k = trait haut + zigzag.", "extraExample": {"text": "أَكْوَاب", "translation": "des verres", "transliteration": "akwâb"}, "errorPatterns": [{"equals": "لـ", "category": "spelling", "feedback": "لـ est un trait nu, sans zigzag : on lirait « lûb »."}, {"equals": "قـ", "category": "spelling", "feedback": "قـ est une tête ronde à deux points : on lirait « qûb »."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e13', 'ar', 'ar.l07', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.hatif','ar.v.ha']::text[], 'fill_blank', 'lesson', 'Le téléphone (hâtif) : ___َاتِف', array['هـ','ه']::text[], 'Hâtif commence par un h léger : ه, sous sa forme du début (هـ). حـ (crochet) se lirait « 7âtif », خـ « khâtif ».', 3, '{"id": "ar.l07.e13", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.hatif", "ar.v.ha"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la lettre qui manque.", "prompt": "Le téléphone (hâtif) : ___َاتِف", "promptLanguage": "fr", "options": ["هـ", "حـ", "خـ"], "answer": "هـ", "acceptedAnswers": ["هـ", "ه"], "explanation": "Hâtif commence par un h léger : ه, sous sa forme du début (هـ). حـ (crochet) se lirait « 7âtif », خـ « khâtif ».", "tip": "h léger = le dessin de début هـ, sans point.", "extraExample": {"text": "هَاتِفِي", "translation": "mon téléphone", "transliteration": "hâtifî"}, "errorPatterns": [{"equals": "حـ", "category": "spelling", "feedback": "حـ est un crochet, plus rauque : on lirait « 7âtif »."}, {"equals": "خـ", "category": "spelling", "feedback": "خـ est un crochet avec un point dessus : on lirait « khâtif »."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e14', 'ar', 'ar.l07', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.asal','ar.v.ayn']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit 3asal (le miel) ?', array['عَسَل']::text[], 'Il faut une tête sans point au début (ع), puis س, et enfin un trait vertical (ل). Avec un point au-dessus de la tête, ce serait غ ; avec une boule à la fin, م ; avec un zigzag, ك.', 3, '{"id": "ar.l07.e14", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.asal", "ar.v.ayn"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se lit 3asal (le miel) ?", "promptLanguage": "fr", "options": ["عَسَل", "غَسَل", "عَسَم", "عَسَك"], "answer": "عَسَل", "acceptedAnswers": ["عَسَل"], "explanation": "Il faut une tête sans point au début (ع), puis س, et enfin un trait vertical (ل). Avec un point au-dessus de la tête, ce serait غ ; avec une boule à la fin, م ; avec un zigzag, ك.", "tip": "Début : tête sans point = 3. Fin : trait nu = l.", "extraExample": {"text": "عَسَلِي", "translation": "mon miel", "transliteration": "3asalî"}, "errorPatterns": [{"equals": "غَسَل", "category": "spelling", "feedback": "غ a un point au-dessus de sa tête : on lirait « ghasal »."}, {"equals": "عَسَم", "category": "spelling", "feedback": "La dernière lettre est une boule (م) : on lirait « 3asam »."}, {"equals": "عَسَك", "category": "spelling", "feedback": "La dernière lettre contient un zigzag (ك) : on lirait « 3asak »."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e15', 'ar', 'ar.l07', 'ar.g05.sin_chin_sad_dad', array['ar.g05.sin_chin_sad_dad','ar.v.qamis','ar.v.sad']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit qamîS (la chemise) ?', array['قَمِيص']::text[], 'Début : tête à deux points (ق). Fin : boucle sans point (ص, S lourd). فَمِيص n''a qu''un point au début, قَمِيض un point sur la boucle, قَمِيس une scie à la fin.', 3, '{"id": "ar.l07.e15", "unitIds": ["ar.g05.sin_chin_sad_dad", "ar.v.qamis", "ar.v.sad"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se lit qamîS (la chemise) ?", "promptLanguage": "fr", "options": ["قَمِيص", "فَمِيص", "قَمِيض", "قَمِيس"], "answer": "قَمِيص", "acceptedAnswers": ["قَمِيص"], "explanation": "Début : tête à deux points (ق). Fin : boucle sans point (ص, S lourd). فَمِيص n''a qu''un point au début, قَمِيض un point sur la boucle, قَمِيس une scie à la fin.", "tip": "Deux points au début, boucle nue à la fin.", "extraExample": {"text": "قَمِيصِي", "translation": "ma chemise", "transliteration": "qamîSî"}, "errorPatterns": [{"equals": "فَمِيص", "category": "spelling", "feedback": "ف n''a qu''un seul point : on lirait « famîS »."}, {"equals": "قَمِيض", "category": "spelling", "feedback": "ض a un point au-dessus de sa boucle : on lirait « qamîD »."}, {"equals": "قَمِيس", "category": "spelling", "feedback": "س est une scie à trois dents : on lirait « qamîs »."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e16', 'ar', 'ar.l07', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.miftah','ar.v.alif']::text[], 'fill_blank', 'lesson', 'Dans مِفْتَاح (la clé), il y a ___ blocs de lettres attachées.', array['2','deux']::text[], 'م, ف, ت et ا s''attachent en un seul bloc (مفتا). Mais ا coupe le mot : ح reste seul. Deux blocs.', 3, '{"id": "ar.l07.e16", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.miftah", "ar.v.alif"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Dans مِفْتَاح (la clé), il y a ___ blocs de lettres attachées.", "promptLanguage": "fr", "options": ["1", "2", "3"], "answer": "2", "acceptedAnswers": ["2", "deux"], "explanation": "م, ف, ت et ا s''attachent en un seul bloc (مفتا). Mais ا coupe le mot : ح reste seul. Deux blocs.", "tip": "ا coupe toujours : compte les blocs avant et après.", "extraExample": {"text": "طَاوِلَة", "translation": "trois blocs : طا, و, لة", "transliteration": "Tâwila"}, "errorPatterns": [{"equals": "1", "category": "grammar", "feedback": "ا ne s''attache pas à la lettre suivante : le ح final reste séparé."}, {"equals": "3", "category": "grammar", "feedback": "Il n''y a qu''une seule coupure, après ا : مفتا et ح."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e17', 'ar', 'ar.l07', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.qalam','ar.v.kub','ar.v.hatif','ar.v.miftah']::text[], 'match', 'lesson', 'Sur le bureau et à la maison', '{}'::text[], 'قَلَم (qalam) = le stylo, كُوب (kûb) = le verre, هَاتِف (hâtif) = le téléphone, مِفْتَاح (miftâ7) = la clé.', 2, '{"id": "ar.l07.e17", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.qalam", "ar.v.kub", "ar.v.hatif", "ar.v.miftah"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Sur le bureau et à la maison", "promptLanguage": "fr", "pairs": [{"left": "قَلَم", "right": "le stylo"}, {"left": "كُوب", "right": "le verre"}, {"left": "هَاتِف", "right": "le téléphone"}, {"left": "مِفْتَاح", "right": "la clé"}], "answer": "قَلَم = le stylo ; كُوب = le verre ; هَاتِف = le téléphone ; مِفْتَاح = la clé", "acceptedAnswers": [], "explanation": "قَلَم (qalam) = le stylo, كُوب (kûb) = le verre, هَاتِف (hâtif) = le téléphone, مِفْتَاح (miftâ7) = la clé.", "tip": "Regarde la première lettre : ق, ك, ه, م.", "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e18', 'ar', 'ar.l07', 'ar.v.qalam', array['ar.v.qalam','ar.g07.fa_qaf_kaf_lam_mim_ha']::text[], 'reorder', 'lesson', 'Écris « qalam » (le stylo) avec ces lettres.', array['ق ل م']::text[], 'Qalam : ق (q), ل (l), م (m). Les trois lettres s''attachent : قَلَم.', 3, '{"id": "ar.l07.e18", "unitIds": ["ar.v.qalam", "ar.g07.fa_qaf_kaf_lam_mim_ha"], "type": "reorder", "difficulty": 3, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « qalam » (le stylo) avec ces lettres.", "promptLanguage": "fr", "tokens": ["م", "ق", "ل"], "answer": "ق ل م", "acceptedAnswers": ["ق ل م"], "explanation": "Qalam : ق (q), ل (l), م (m). Les trois lettres s''attachent : قَلَم.", "tip": "Commence par la tête ronde à deux points.", "extraExample": {"text": "أَقْلَام", "translation": "des stylos", "transliteration": "aqlâm"}, "pool": "lesson", "lessonId": "ar.l07", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e19', 'ar', 'ar.l07', 'ar.v.miftah', array['ar.v.miftah','ar.g07.fa_qaf_kaf_lam_mim_ha']::text[], 'reorder', 'lesson', 'Écris « miftâ7 » (la clé) avec ces lettres.', array['م ف ت ا ح']::text[], 'Miftâ7 : م (m), ف (f), ت (t), ا (â long), ح (7). Écrit : مِفْتَاح, avec ح isolé après ا.', 4, '{"id": "ar.l07.e19", "unitIds": ["ar.v.miftah", "ar.g07.fa_qaf_kaf_lam_mim_ha"], "type": "reorder", "difficulty": 4, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « miftâ7 » (la clé) avec ces lettres.", "promptLanguage": "fr", "tokens": ["ت", "م", "ح", "ا", "ف"], "answer": "م ف ت ا ح", "acceptedAnswers": ["م ف ت ا ح"], "explanation": "Miftâ7 : م (m), ف (f), ت (t), ا (â long), ح (7). Écrit : مِفْتَاح, avec ح isolé après ا.", "tip": "On lit de droite à gauche : la boule م d''abord.", "extraExample": {"text": "مَفَاتِيح", "translation": "des clés", "transliteration": "mafâtî7"}, "pool": "lesson", "lessonId": "ar.l07", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e20', 'ar', 'ar.l07', 'ar.v.qalam', array['ar.v.qalam','ar.g07.fa_qaf_kaf_lam_mim_ha']::text[], 'translation', 'lesson', 'قَلَم', array['le stylo','stylo','un stylo','le crayon','crayon','un crayon','la plume','plume']::text[], 'قَلَم se lit qalam et veut dire « le stylo » (ou le crayon) : ق, ل, م.', 2, '{"id": "ar.l07.e20", "unitIds": ["ar.v.qalam", "ar.g07.fa_qaf_kaf_lam_mim_ha"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "قَلَم", "promptLanguage": "ar", "answer": "le stylo", "acceptedAnswers": ["le stylo", "stylo", "un stylo", "le crayon", "crayon", "un crayon", "la plume", "plume"], "explanation": "قَلَم se lit qalam et veut dire « le stylo » (ou le crayon) : ق, ل, م.", "tip": "Qalam : deux points au début, une boule à la fin.", "extraExample": {"text": "قَلَمِي", "translation": "mon stylo", "transliteration": "qalamî"}, "errorPatterns": [{"equals": "le livre", "category": "vocabulary", "feedback": "Le livre se dit كِتَاب (kitâb). قَلَم (qalam) est le stylo."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e21', 'ar', 'ar.l07', 'ar.v.hatif', array['ar.v.hatif','ar.g07.fa_qaf_kaf_lam_mim_ha']::text[], 'translation', 'lesson', 'هَاتِف', array['le téléphone','téléphone','un téléphone','le portable','portable']::text[], 'هَاتِف se lit hâtif et veut dire « le téléphone ».', 2, '{"id": "ar.l07.e21", "unitIds": ["ar.v.hatif", "ar.g07.fa_qaf_kaf_lam_mim_ha"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "هَاتِف", "promptLanguage": "ar", "answer": "le téléphone", "acceptedAnswers": ["le téléphone", "téléphone", "un téléphone", "le portable", "portable"], "explanation": "هَاتِف se lit hâtif et veut dire « le téléphone ».", "tip": "Hâtif : ه au début, ف à la fin.", "extraExample": {"text": "هَاتِفِي", "translation": "mon téléphone", "transliteration": "hâtifî"}, "errorPatterns": [{"equals": "la clé", "category": "vocabulary", "feedback": "La clé se dit مِفْتَاح (miftâ7). هَاتِف (hâtif) est le téléphone."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e22', 'ar', 'ar.l07', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.kub','ar.v.kaf']::text[], 'free_answer', 'lesson', 'Comment se lit كُوب (le verre) ?', array['kûb','kub','koub','kuub']::text[], 'ك (k), و (û long), ب (b) : kûb, « le verre ». Le و qui allonge le u coupe le mot : ب reste isolé.', 4, '{"id": "ar.l07.e22", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.kub", "ar.v.kaf"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines (û pour un u long).", "prompt": "Comment se lit كُوب (le verre) ?", "promptLanguage": "fr", "answer": "kûb", "acceptedAnswers": ["kûb", "kub", "koub", "kuub"], "explanation": "ك (k), و (û long), ب (b) : kûb, « le verre ». Le و qui allonge le u coupe le mot : ب reste isolé.", "tip": "Zigzag au début : k. و après u : û long.", "extraExample": {"text": "كُوبِي", "translation": "mon verre", "transliteration": "kûbî"}, "errorPatterns": [{"equals": "lûb", "category": "spelling", "feedback": "La première lettre contient un zigzag : c''est ك (k), pas ل."}, {"equals": "qûb", "category": "spelling", "feedback": "La première lettre est un trait haut avec un zigzag, pas une tête à deux points : c''est ك (k)."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e23', 'ar', 'ar.l07', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.miftah','ar.v.mim']::text[], 'free_answer', 'lesson', 'Comment se lit مِفْتَاح (la clé) ?', array['miftâ7','mifta7','miftaa7','miftah','miftâh','miftaah']::text[], 'م (m), ف (f, un point dessus), ت (t, deux points dessus), ا (â long), ح (7, sans point) : miftâ7, « la clé ».', 4, '{"id": "ar.l07.e23", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.miftah", "ar.v.mim"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines (7 pour ح, â pour un a long).", "prompt": "Comment se lit مِفْتَاح (la clé) ?", "promptLanguage": "fr", "answer": "miftâ7", "acceptedAnswers": ["miftâ7", "mifta7", "miftaa7", "miftah", "miftâh", "miftaah"], "explanation": "م (m), ف (f, un point dessus), ت (t, deux points dessus), ا (â long), ح (7, sans point) : miftâ7, « la clé ».", "tip": "Un point dessus : f ; deux points dessus : t ; le dernier crochet sans point : 7.", "extraExample": {"text": "مِفْتَاحِي", "translation": "ma clé", "transliteration": "miftâ7î"}, "errorPatterns": [{"equals": "miqtâ7", "category": "spelling", "feedback": "La deuxième lettre n''a qu''un point au-dessus : c''est ف (f), pas ق (q)."}, {"equals": "miftâkh", "category": "spelling", "feedback": "Le dernier crochet n''a aucun point : c''est ح (7), pas خ (kh)."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e01', 'ar', 'ar.l08', 'ar.v.ta_marbuta', array['ar.v.ta_marbuta','ar.g08.ta_marbuta_maqsura_hamza_lam_alif']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : ـة ?', array['tâ'' marbûTa (-a)']::text[], 'Une petite boucle surmontée de deux points, à la fin d''un mot : c''est ة (tâ'' marbûTa). Elle se lit a.', 1, '{"id": "ar.l08.e01", "unitIds": ["ar.v.ta_marbuta", "ar.g08.ta_marbuta_maqsura_hamza_lam_alif"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : ـة ?", "promptLanguage": "fr", "options": ["tâ'' marbûTa (-a)", "tâ'' (t)", "hâ'' (h)", "alif maqSûra (â)"], "answer": "tâ'' marbûTa (-a)", "acceptedAnswers": ["tâ'' marbûTa (-a)"], "hint": "Regarde la fin du mot : combien de points ?", "explanation": "Une petite boucle surmontée de deux points, à la fin d''un mot : c''est ة (tâ'' marbûTa). Elle se lit a.", "tip": "Boucle + deux points, en fin de mot = -a.", "extraExample": {"text": "فَاكِهَة", "translation": "le fruit (ـة à la fin)", "transliteration": "fâkiha"}, "errorPatterns": [{"equals": "hâ'' (h)", "category": "spelling", "feedback": "ه n''a aucun point. Ici il y a deux points au-dessus de la boucle : c''est ة."}, {"equals": "tâ'' (t)", "category": "spelling", "feedback": "ت est une dent ou une cuvette à deux points. ة est une petite boucle, toujours à la fin d''un mot."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e02', 'ar', 'ar.l08', 'ar.v.alif_maqsura', array['ar.v.alif_maqsura','ar.g08.ta_marbuta_maqsura_hamza_lam_alif']::text[], 'mcq', 'lesson', 'Quelle lettre vois-tu ici : ى ?', array['alif maqSûra (â)']::text[], 'Une queue qui descend sous la ligne, sans aucun point : c''est ى (alif maqSûra), qui se lit â en fin de mot.', 1, '{"id": "ar.l08.e02", "unitIds": ["ar.v.alif_maqsura", "ar.g08.ta_marbuta_maqsura_hamza_lam_alif"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le nom de la lettre.", "prompt": "Quelle lettre vois-tu ici : ى ?", "promptLanguage": "fr", "options": ["tâ'' marbûTa (-a)", "yâ'' (y, î)", "alif maqSûra (â)", "alif (â)"], "answer": "alif maqSûra (â)", "acceptedAnswers": ["alif maqSûra (â)"], "hint": "Y a-t-il des points ?", "explanation": "Une queue qui descend sous la ligne, sans aucun point : c''est ى (alif maqSûra), qui se lit â en fin de mot.", "tip": "Queue sans point à la fin d''un mot = â.", "extraExample": {"text": "مَقْهَى", "translation": "le café (ى à la fin)", "transliteration": "maqhâ"}, "errorPatterns": [{"equals": "yâ'' (y, î)", "category": "spelling", "feedback": "ي a deux points en dessous. Ici il n''y en a aucun : c''est ى."}, {"equals": "alif (â)", "category": "spelling", "feedback": "ا est un simple trait vertical. ى a une queue qui descend sous la ligne."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e03', 'ar', 'ar.l08', 'ar.v.hamza', array['ar.v.hamza','ar.g08.ta_marbuta_maqsura_hamza_lam_alif']::text[], 'mcq', 'lesson', 'Comment s''appelle le petit signe ء ?', array['hamza (coupure de gorge)']::text[], 'ء est la hamza : une brève coupure de la gorge, notée ''. Elle peut se tenir seule sur la ligne (comme dans سَمَاء) ou sur un support.', 2, '{"id": "ar.l08.e03", "unitIds": ["ar.v.hamza", "ar.g08.ta_marbuta_maqsura_hamza_lam_alif"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon nom.", "prompt": "Comment s''appelle le petit signe ء ?", "promptLanguage": "fr", "options": ["hamza (coupure de gorge)", "3ayn (3)", "alif (â)", "hâ'' (h)"], "answer": "hamza (coupure de gorge)", "acceptedAnswers": ["hamza (coupure de gorge)"], "explanation": "ء est la hamza : une brève coupure de la gorge, notée ''. Elle peut se tenir seule sur la ligne (comme dans سَمَاء) ou sur un support.", "tip": "Hamza = petite tête d''œil, sans queue, qui note une coupure.", "extraExample": {"text": "مَاء", "translation": "l''eau (ء seule, après ا)", "transliteration": "mâ''"}, "errorPatterns": [{"equals": "3ayn (3)", "category": "spelling", "feedback": "ع est une grande tête d''œil, un son de gorge serrée. La hamza est un tout petit signe, une simple coupure."}, {"equals": "alif (â)", "category": "spelling", "feedback": "ا est un trait vertical. La hamza, c''est le petit signe qui note la coupure de gorge."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e04', 'ar', 'ar.l08', 'ar.g08.ta_marbuta_maqsura_hamza_lam_alif', array['ar.g08.ta_marbuta_maqsura_hamza_lam_alif','ar.v.ta_marbuta','ar.v.alif_maqsura','ar.v.hamza','ar.v.lam_alif']::text[], 'match', 'lesson', 'Les quatre derniers signes', '{}'::text[], 'ـة (boucle + deux points) = tâ'' marbûTa, ى (queue sans point) = alif maqSûra, ء (petite coupure) = hamza, لا (deux traits croisés) = lâm-alif.', 1, '{"id": "ar.l08.e04", "unitIds": ["ar.g08.ta_marbuta_maqsura_hamza_lam_alif", "ar.v.ta_marbuta", "ar.v.alif_maqsura", "ar.v.hamza", "ar.v.lam_alif"], "type": "match", "difficulty": 1, "instruction": "Associe chaque signe à son nom.", "prompt": "Les quatre derniers signes", "promptLanguage": "fr", "pairs": [{"left": "ـة", "right": "tâ'' marbûTa (-a)"}, {"left": "ى", "right": "alif maqSûra (â)"}, {"left": "ء", "right": "hamza ('')"}, {"left": "لا", "right": "lâm-alif (lâ)"}], "answer": "ـة = tâ'' marbûTa (-a) ; ى = alif maqSûra (â) ; ء = hamza ('') ; لا = lâm-alif (lâ)", "acceptedAnswers": [], "explanation": "ـة (boucle + deux points) = tâ'' marbûTa, ى (queue sans point) = alif maqSûra, ء (petite coupure) = hamza, لا (deux traits croisés) = lâm-alif.", "tip": "Quatre signes : boucle à points, queue sans point, petit signe seul, croix.", "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e05', 'ar', 'ar.l08', 'ar.g08.ta_marbuta_maqsura_hamza_lam_alif', array['ar.g08.ta_marbuta_maqsura_hamza_lam_alif','ar.v.ta_marbuta']::text[], 'mcq', 'lesson', 'Quelle différence y a-t-il entre ـة et ـه à la fin d''un mot ?', array['ـة porte deux points au-dessus']::text[], 'ـة est un ـه surmonté de deux points. Les deux points changent tout : ة se lit a (mot féminin), ه se lit h.', 2, '{"id": "ar.l08.e05", "unitIds": ["ar.g08.ta_marbuta_maqsura_hamza_lam_alif", "ar.v.ta_marbuta"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle différence y a-t-il entre ـة et ـه à la fin d''un mot ?", "promptLanguage": "fr", "options": ["ـة porte deux points au-dessus", "ـة n''a aucun point", "ـه porte deux points au-dessus", "ـة s''attache des deux côtés"], "answer": "ـة porte deux points au-dessus", "acceptedAnswers": ["ـة porte deux points au-dessus"], "explanation": "ـة est un ـه surmonté de deux points. Les deux points changent tout : ة se lit a (mot féminin), ه se lit h.", "tip": "Deux points sur la boucle finale = a.", "extraExample": {"text": "مَكْتَبَة", "translation": "la bibliothèque (ة)", "transliteration": "maktaba"}, "errorPatterns": [{"equals": "ـة n''a aucun point", "category": "grammar", "feedback": "C''est ـه qui n''a aucun point. ـة en a deux, au-dessus."}, {"equals": "ـه porte deux points au-dessus", "category": "grammar", "feedback": "C''est l''inverse : ـة porte les deux points, ـه n''en a pas."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e06', 'ar', 'ar.l08', 'ar.g08.ta_marbuta_maqsura_hamza_lam_alif', array['ar.g08.ta_marbuta_maqsura_hamza_lam_alif','ar.v.alif_maqsura','ar.v.ya']::text[], 'mcq', 'lesson', 'Quelle différence y a-t-il entre ى et ي à la fin d''un mot ?', array['ى n''a aucun point, alors que ي en a deux en dessous']::text[], 'La queue est la même, mais ي porte deux points en dessous. Sans point, c''est ى (â) ; avec deux points dessous, c''est ي (î).', 2, '{"id": "ar.l08.e06", "unitIds": ["ar.g08.ta_marbuta_maqsura_hamza_lam_alif", "ar.v.alif_maqsura", "ar.v.ya"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle différence y a-t-il entre ى et ي à la fin d''un mot ?", "promptLanguage": "fr", "options": ["ى n''a aucun point, alors que ي en a deux en dessous", "ى a deux points au-dessus", "ى a un seul point en dessous", "ى s''attache toujours à la lettre suivante"], "answer": "ى n''a aucun point, alors que ي en a deux en dessous", "acceptedAnswers": ["ى n''a aucun point, alors que ي en a deux en dessous"], "explanation": "La queue est la même, mais ي porte deux points en dessous. Sans point, c''est ى (â) ; avec deux points dessous, c''est ي (î).", "tip": "Deux points dessous : î. Rien : â.", "extraExample": {"text": "مُسْتَشْفَى", "translation": "l''hôpital (ى sans point)", "transliteration": "mustachfâ"}, "errorPatterns": [{"equals": "ى a deux points au-dessus", "category": "grammar", "feedback": "ى n''a pas de points du tout : ce sont les deux points de ت ou de ق qui sont au-dessus."}, {"equals": "ى s''attache toujours à la lettre suivante", "category": "grammar", "feedback": "ى est toujours à la fin d''un mot : rien ne le suit."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e07', 'ar', 'ar.l08', 'ar.g08.ta_marbuta_maqsura_hamza_lam_alif', array['ar.g08.ta_marbuta_maqsura_hamza_lam_alif','ar.v.lam_alif','ar.v.salam']::text[], 'mcq', 'lesson', 'Dans سَلَام (la paix), comment s''écrivent ل et ا ensemble ?', array['en ligature لا, deux traits croisés']::text[], 'Quand ل est suivi de ا, on les écrit toujours en ligature : لا. Le mot سَلَام s''écrit donc سـ + لا + م.', 2, '{"id": "ar.l08.e07", "unitIds": ["ar.g08.ta_marbuta_maqsura_hamza_lam_alif", "ar.v.lam_alif", "ar.v.salam"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans سَلَام (la paix), comment s''écrivent ل et ا ensemble ?", "promptLanguage": "fr", "options": ["en ligature لا, deux traits croisés", "côte à côte, séparés par un petit espace", "ا d''abord, puis ل", "ل attaché à م, et ا isolé"], "answer": "en ligature لا, deux traits croisés", "acceptedAnswers": ["en ligature لا, deux traits croisés"], "explanation": "Quand ل est suivi de ا, on les écrit toujours en ligature : لا. Le mot سَلَام s''écrit donc سـ + لا + م.", "tip": "ل puis ا = لا, jamais deux signes séparés.", "extraExample": {"text": "صَلَاة", "translation": "la prière (ligature لا)", "transliteration": "Salâ"}, "errorPatterns": [{"equals": "côte à côte, séparés par un petit espace", "category": "grammar", "feedback": "L''arabe n''écrit jamais ل et ا côte à côte : ils fusionnent en la ligature لا."}, {"equals": "ا d''abord, puis ل", "category": "grammar", "feedback": "L''ordre est ل puis ا. ا puis ل (ال) est l''article « le », un autre mot."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e08', 'ar', 'ar.l08', 'ar.g08.ta_marbuta_maqsura_hamza_lam_alif', array['ar.g08.ta_marbuta_maqsura_hamza_lam_alif','ar.v.maktaba','ar.v.ta_marbuta']::text[], 'mcq', 'lesson', 'Comment se lit مَكْتَبَة ?', array['maktaba']::text[], 'م, ك (zigzag), ت (deux points), ب (un point dessous) puis ة final : maktaba, « la bibliothèque ». Le ة final se lit a.', 3, '{"id": "ar.l08.e08", "unitIds": ["ar.g08.ta_marbuta_maqsura_hamza_lam_alif", "ar.v.maktaba", "ar.v.ta_marbuta"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit مَكْتَبَة ?", "promptLanguage": "fr", "options": ["maktaba", "maktab", "maktana", "maqtaba"], "answer": "maktaba", "acceptedAnswers": ["maktaba"], "hint": "Regarde bien la fin du mot.", "explanation": "م, ك (zigzag), ت (deux points), ب (un point dessous) puis ة final : maktaba, « la bibliothèque ». Le ة final se lit a.", "tip": "N''oublie pas le a final : ة.", "extraExample": {"text": "مَكْتَب", "translation": "le bureau (sans ة)", "transliteration": "maktab"}, "errorPatterns": [{"equals": "maktab", "category": "spelling", "feedback": "Le mot finit par ة (boucle + deux points), qui se lit a. Sans lui, ce serait مَكْتَب (le bureau)."}, {"equals": "maktana", "category": "spelling", "feedback": "La quatrième lettre a un point en dessous : c''est ب (b), pas ن."}, {"equals": "maqtaba", "category": "spelling", "feedback": "La deuxième lettre contient un zigzag : c''est ك (k), pas ق."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e09', 'ar', 'ar.l08', 'ar.g08.ta_marbuta_maqsura_hamza_lam_alif', array['ar.g08.ta_marbuta_maqsura_hamza_lam_alif','ar.v.fakiha','ar.v.ta_marbuta']::text[], 'fill_blank', 'lesson', 'Le fruit (fâkiha) : فَاكِهَ___', array['ـة','ة']::text[], 'Le mot finit par le son a, écrit ة, la boucle à deux points. ـه se lirait « fâkih » et ـى « fâkihâ ».', 2, '{"id": "ar.l08.e09", "unitIds": ["ar.g08.ta_marbuta_maqsura_hamza_lam_alif", "ar.v.fakiha", "ar.v.ta_marbuta"], "type": "fill_blank", "difficulty": 2, "instruction": "Choisis la lettre qui manque.", "prompt": "Le fruit (fâkiha) : فَاكِهَ___", "promptLanguage": "fr", "options": ["ـة", "ـه", "ـى"], "answer": "ـة", "acceptedAnswers": ["ـة", "ة"], "explanation": "Le mot finit par le son a, écrit ة, la boucle à deux points. ـه se lirait « fâkih » et ـى « fâkihâ ».", "tip": "Fin de mot en -a : boucle + deux points.", "extraExample": {"text": "فَوَاكِه", "translation": "des fruits", "transliteration": "fawâkih"}, "errorPatterns": [{"equals": "ـه", "category": "spelling", "feedback": "ه n''a pas de points et se lit h : on lirait « fâkih »."}, {"equals": "ـى", "category": "spelling", "feedback": "ى se lit â : on lirait « fâkihâ »."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e10', 'ar', 'ar.l08', 'ar.g08.ta_marbuta_maqsura_hamza_lam_alif', array['ar.g08.ta_marbuta_maqsura_hamza_lam_alif','ar.v.maqha','ar.v.alif_maqsura']::text[], 'fill_blank', 'lesson', 'Le café (maqhâ) : مَقْه___', array['ـى','ى']::text[], 'Maqhâ finit par un â long écrit ى : une queue sans aucun point, attachée à ه. ـي (deux points dessous) se lirait « maqhî ».', 2, '{"id": "ar.l08.e10", "unitIds": ["ar.g08.ta_marbuta_maqsura_hamza_lam_alif", "ar.v.maqha", "ar.v.alif_maqsura"], "type": "fill_blank", "difficulty": 2, "instruction": "Choisis la lettre qui manque.", "prompt": "Le café (maqhâ) : مَقْه___", "promptLanguage": "fr", "options": ["ـى", "ـي", "ـا"], "answer": "ـى", "acceptedAnswers": ["ـى", "ى"], "explanation": "Maqhâ finit par un â long écrit ى : une queue sans aucun point, attachée à ه. ـي (deux points dessous) se lirait « maqhî ».", "tip": "Fin de mot en â : queue sans point.", "extraExample": {"text": "مُسْتَشْفَى", "translation": "l''hôpital", "transliteration": "mustachfâ"}, "errorPatterns": [{"equals": "ـي", "category": "spelling", "feedback": "ي porte deux points en dessous : on lirait « maqhî »."}, {"equals": "ـا", "category": "spelling", "feedback": "Ce mot s''écrit avec ى à la fin, pas avec ا."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e11', 'ar', 'ar.l08', 'ar.g08.ta_marbuta_maqsura_hamza_lam_alif', array['ar.g08.ta_marbuta_maqsura_hamza_lam_alif','ar.v.sama','ar.v.hamza']::text[], 'fill_blank', 'lesson', 'Le ciel (samâ'') : سَمَا___', array['ء']::text[], 'Samâ'' finit par une coupure de gorge : ء, la hamza, seule sur la ligne après ا. ع se lirait « samâ3 » et ة « samâ ».', 3, '{"id": "ar.l08.e11", "unitIds": ["ar.g08.ta_marbuta_maqsura_hamza_lam_alif", "ar.v.sama", "ar.v.hamza"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la lettre qui manque.", "prompt": "Le ciel (samâ'') : سَمَا___", "promptLanguage": "fr", "options": ["ء", "ع", "ة"], "answer": "ء", "acceptedAnswers": ["ء"], "explanation": "Samâ'' finit par une coupure de gorge : ء, la hamza, seule sur la ligne après ا. ع se lirait « samâ3 » et ة « samâ ».", "tip": "Coupure de gorge en fin de mot : ء.", "extraExample": {"text": "مَاء", "translation": "l''eau", "transliteration": "mâ''"}, "errorPatterns": [{"equals": "ع", "category": "spelling", "feedback": "ع (3) est une tête d''œil plus grande, un son de gorge serrée : on lirait « samâ3 »."}, {"equals": "ة", "category": "spelling", "feedback": "ة est une boucle à deux points qui se lit a, pas une coupure."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e12', 'ar', 'ar.l08', 'ar.v.bab', array['ar.v.bab','ar.g01.alif_ba_ta_tha']::text[], 'mcq', 'lesson', 'Lequel de ces mots veut dire « la porte » ?', array['بَاب']::text[], 'بَاب (bâb) est la porte : ب, ا, ب. تَاج est la couronne, دَار la demeure, كُوب le verre.', 2, '{"id": "ar.l08.e12", "unitIds": ["ar.v.bab", "ar.g01.alif_ba_ta_tha"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots veut dire « la porte » ?", "promptLanguage": "fr", "options": ["بَاب", "تَاج", "دَار", "كُوب"], "answer": "بَاب", "acceptedAnswers": ["بَاب"], "explanation": "بَاب (bâb) est la porte : ب, ا, ب. تَاج est la couronne, دَار la demeure, كُوب le verre.", "tip": "Mot connu = reconnu d''un seul coup d''œil.", "extraExample": {"text": "أَبْوَاب", "translation": "des portes", "transliteration": "abwâb"}, "errorPatterns": [{"equals": "دَار", "category": "vocabulary", "feedback": "دَار (dâr) est la demeure, la maison : trois lettres séparées, د ا ر."}, {"equals": "تَاج", "category": "vocabulary", "feedback": "تَاج (tâdj) est la couronne."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e13', 'ar', 'ar.l08', 'ar.v.asir', array['ar.v.asir','ar.g06.ta_za_ayn_ghayn']::text[], 'mcq', 'lesson', 'Lequel de ces mots veut dire « le jus » ?', array['عَصِير']::text[], 'عَصِير (3aSîr) est le jus : une tête d''œil, une boucle, ي, ر. عَسَل (3asal) est le miel, طَعَام la nourriture, نَظِيف propre.', 3, '{"id": "ar.l08.e13", "unitIds": ["ar.v.asir", "ar.g06.ta_za_ayn_ghayn"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots veut dire « le jus » ?", "promptLanguage": "fr", "options": ["عَصِير", "عَسَل", "طَعَام", "نَظِيف"], "answer": "عَصِير", "acceptedAnswers": ["عَصِير"], "explanation": "عَصِير (3aSîr) est le jus : une tête d''œil, une boucle, ي, ر. عَسَل (3asal) est le miel, طَعَام la nourriture, نَظِيف propre.", "tip": "3aSîr (boucle) et 3asal (scie) : même début, lettre suivante différente.", "extraExample": {"text": "عَصِيرُ جَزَر", "translation": "du jus de carotte", "transliteration": "3aSîru djazar"}, "errorPatterns": [{"equals": "عَسَل", "category": "vocabulary", "feedback": "عَسَل (3asal) est le miel : après la tête d''œil, c''est une scie (س), pas une boucle."}, {"equals": "طَعَام", "category": "vocabulary", "feedback": "طَعَام (Ta3âm) est la nourriture."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e14', 'ar', 'ar.l08', 'ar.g04.non_connecting_letters', array['ar.g04.non_connecting_letters','ar.v.dal','ar.v.zay']::text[], 'mcq', 'lesson', 'Quelles lettres ne s''attachent jamais à la lettre qui les suit ?', array['ا د ذ ر ز و']::text[], 'Les six coupeuses sont ا د ذ ر ز و. ل, ن et ب s''attachent des deux côtés.', 3, '{"id": "ar.l08.e14", "unitIds": ["ar.g04.non_connecting_letters", "ar.v.dal", "ar.v.zay"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne série.", "prompt": "Quelles lettres ne s''attachent jamais à la lettre qui les suit ?", "promptLanguage": "fr", "options": ["ا د ذ ر ز و", "ا د ذ ر ز ل", "ا د ر ز و ن", "ا ذ ر ز و ب"], "answer": "ا د ذ ر ز و", "acceptedAnswers": ["ا د ذ ر ز و"], "explanation": "Les six coupeuses sont ا د ذ ر ز و. ل, ن et ب s''attachent des deux côtés.", "tip": "ا د ذ ر ز و : six lettres, six coupures.", "extraExample": {"text": "دَجَاج", "translation": "trois blocs : د | جا | ج", "transliteration": "dadjâdj"}, "errorPatterns": [{"equals": "ا د ذ ر ز ل", "category": "grammar", "feedback": "ل s''attache à la lettre suivante (لـ) : ce n''est pas une coupeuse."}, {"equals": "ا د ر ز و ن", "category": "grammar", "feedback": "ن s''attache des deux côtés (نـ, ـنـ) : il manque ذ à cette série."}, {"equals": "ا ذ ر ز و ب", "category": "grammar", "feedback": "ب s''attache des deux côtés : il manque د à cette série."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e15', 'ar', 'ar.l08', 'ar.g06.ta_za_ayn_ghayn', array['ar.g06.ta_za_ayn_ghayn','ar.v.zah','ar.v.nazif']::text[], 'fill_blank', 'lesson', 'Dans نَظِيف (propre), le ظ est en forme ___.', array['médiane','médian','du milieu','milieu','forme médiane']::text[], 'Le ظ est relié à ن qui le précède et à ي qui le suit : relié des deux côtés, il est en forme du milieu (ـظـ).', 3, '{"id": "ar.l08.e15", "unitIds": ["ar.g06.ta_za_ayn_ghayn", "ar.v.zah", "ar.v.nazif"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le nom de la forme : initiale, médiane, finale ou isolée.", "prompt": "Dans نَظِيف (propre), le ظ est en forme ___.", "promptLanguage": "fr", "options": ["initiale", "médiane", "finale", "isolée"], "answer": "médiane", "acceptedAnswers": ["médiane", "médian", "du milieu", "milieu", "forme médiane"], "explanation": "Le ظ est relié à ن qui le précède et à ي qui le suit : relié des deux côtés, il est en forme du milieu (ـظـ).", "tip": "Relié des deux côtés = forme du milieu.", "extraExample": {"text": "مَنْظَر", "translation": "la vue (ظ au milieu)", "transliteration": "manZar"}, "errorPatterns": [{"equals": "finale", "category": "grammar", "feedback": "Le ظ n''est pas la dernière lettre : il est suivi de ي et de ف."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e16', 'ar', 'ar.l08', 'ar.g03.djim_ha_kha', array['ar.g03.djim_ha_kha','ar.v.tha','ar.v.djim','ar.v.kha','ar.v.chin','ar.v.ghayn']::text[], 'match', 'lesson', 'Tour de l''alphabet : les formes', '{}'::text[], 'ـثـ (trois points sur une dent) = th, جـ (point dans la courbe) = dj, ـخ (point dessus, crochet) = kh, ـشـ (scie, trois points) = ch, ـغ (tête d''œil, un point) = gh.', 3, '{"id": "ar.l08.e16", "unitIds": ["ar.g03.djim_ha_kha", "ar.v.tha", "ar.v.djim", "ar.v.kha", "ar.v.chin", "ar.v.ghayn"], "type": "match", "difficulty": 3, "instruction": "Associe chaque forme au nom de sa lettre.", "prompt": "Tour de l''alphabet : les formes", "promptLanguage": "fr", "pairs": [{"left": "ـثـ", "right": "thâ'' (th)"}, {"left": "جـ", "right": "djîm (dj)"}, {"left": "ـخ", "right": "khâ'' (kh)"}, {"left": "ـشـ", "right": "chîn (ch)"}, {"left": "ـغ", "right": "ghayn (gh)"}], "answer": "ـثـ = thâ'' (th) ; جـ = djîm (dj) ; ـخ = khâ'' (kh) ; ـشـ = chîn (ch) ; ـغ = ghayn (gh)", "acceptedAnswers": [], "explanation": "ـثـ (trois points sur une dent) = th, جـ (point dans la courbe) = dj, ـخ (point dessus, crochet) = kh, ـشـ (scie, trois points) = ch, ـغ (tête d''œil, un point) = gh.", "tip": "Forme d''abord, points ensuite : c''est la méthode qui marche partout.", "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e17', 'ar', 'ar.l08', 'ar.g07.fa_qaf_kaf_lam_mim_ha', array['ar.g07.fa_qaf_kaf_lam_mim_ha','ar.v.ta','ar.v.tah','ar.v.kaf','ar.v.qaf','ar.v.kha']::text[], 'match', 'lesson', 'Des sons proches à ne pas mélanger', '{}'::text[], 'ت = t, ط = T lourd, ك = k, ق = q (k du fond de la gorge), خ = kh (souffle rauque).', 3, '{"id": "ar.l08.e17", "unitIds": ["ar.g07.fa_qaf_kaf_lam_mim_ha", "ar.v.ta", "ar.v.tah", "ar.v.kaf", "ar.v.qaf", "ar.v.kha"], "type": "match", "difficulty": 3, "instruction": "Associe chaque lettre à son son.", "prompt": "Des sons proches à ne pas mélanger", "promptLanguage": "fr", "pairs": [{"left": "ت", "right": "t"}, {"left": "ط", "right": "T (t lourd)"}, {"left": "ك", "right": "k"}, {"left": "ق", "right": "q (k profond)"}, {"left": "خ", "right": "kh"}], "answer": "ت = t ; ط = T (t lourd) ; ك = k ; ق = q (k profond) ; خ = kh", "acceptedAnswers": [], "explanation": "ت = t, ط = T lourd, ك = k, ق = q (k du fond de la gorge), خ = kh (souffle rauque).", "tip": "Les lettres lourdes (ط ص ض ظ ق) viennent du fond de la bouche.", "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e18', 'ar', 'ar.l08', 'ar.v.bab', array['ar.v.bab','ar.g01.alif_ba_ta_tha','ar.v.djazar','ar.v.dayf','ar.v.ghurfa','ar.v.miftah']::text[], 'match', 'lesson', 'Révision : les mots du module', '{}'::text[], 'بَاب (bâb) = la porte, جَزَر (djazar) = les carottes, ضَيْف (Dayf) = l''invité, غُرْفَة (ghurfa) = la chambre, مِفْتَاح (miftâ7) = la clé.', 3, '{"id": "ar.l08.e18", "unitIds": ["ar.v.bab", "ar.g01.alif_ba_ta_tha", "ar.v.djazar", "ar.v.dayf", "ar.v.ghurfa", "ar.v.miftah"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à son sens.", "prompt": "Révision : les mots du module", "promptLanguage": "fr", "pairs": [{"left": "بَاب", "right": "la porte"}, {"left": "جَزَر", "right": "les carottes"}, {"left": "ضَيْف", "right": "l''invité"}, {"left": "غُرْفَة", "right": "la chambre"}, {"left": "مِفْتَاح", "right": "la clé"}], "answer": "بَاب = la porte ; جَزَر = les carottes ; ضَيْف = l''invité ; غُرْفَة = la chambre ; مِفْتَاح = la clé", "acceptedAnswers": [], "explanation": "بَاب (bâb) = la porte, جَزَر (djazar) = les carottes, ضَيْف (Dayf) = l''invité, غُرْفَة (ghurfa) = la chambre, مِفْتَاح (miftâ7) = la clé.", "tip": "Au bout de huit leçons, tu lis ces mots d''un seul coup d''œil.", "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e19', 'ar', 'ar.l08', 'ar.v.salam', array['ar.v.salam','ar.g08.ta_marbuta_maqsura_hamza_lam_alif']::text[], 'reorder', 'lesson', 'Écris « salâm » (la paix) avec ces lettres.', array['س ل ا م']::text[], 'Salâm : س (s), ل (l), ا (â long), م (m). ل et ا forment ensemble la ligature لا : سَلَام.', 3, '{"id": "ar.l08.e19", "unitIds": ["ar.v.salam", "ar.g08.ta_marbuta_maqsura_hamza_lam_alif"], "type": "reorder", "difficulty": 3, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « salâm » (la paix) avec ces lettres.", "promptLanguage": "fr", "tokens": ["م", "ا", "ل", "س"], "answer": "س ل ا م", "acceptedAnswers": ["س ل ا م"], "explanation": "Salâm : س (s), ل (l), ا (â long), م (m). ل et ا forment ensemble la ligature لا : سَلَام.", "tip": "ل puis ا : jamais séparés.", "extraExample": {"text": "السَّلَامُ عَلَيْكُمْ", "translation": "que la paix soit sur vous", "transliteration": "as-salâmu 3alaykum"}, "pool": "lesson", "lessonId": "ar.l08", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e20', 'ar', 'ar.l08', 'ar.v.maqha', array['ar.v.maqha','ar.g08.ta_marbuta_maqsura_hamza_lam_alif']::text[], 'reorder', 'lesson', 'Écris « maqhâ » (le café) avec ces lettres.', array['م ق ه ى']::text[], 'Maqhâ : م (m), ق (q), ه (h), ى (â). Écrit : مَقْهَى. Le ى final n''a aucun point.', 4, '{"id": "ar.l08.e20", "unitIds": ["ar.v.maqha", "ar.g08.ta_marbuta_maqsura_hamza_lam_alif"], "type": "reorder", "difficulty": 4, "instruction": "Touche les lettres dans l''ordre de lecture : la première lettre (à droite dans le mot) d''abord.", "prompt": "Écris « maqhâ » (le café) avec ces lettres.", "promptLanguage": "fr", "tokens": ["ى", "ه", "ق", "م"], "answer": "م ق ه ى", "acceptedAnswers": ["م ق ه ى"], "explanation": "Maqhâ : م (m), ق (q), ه (h), ى (â). Écrit : مَقْهَى. Le ى final n''a aucun point.", "tip": "On finit par la queue sans point.", "extraExample": {"text": "مُسْتَشْفَى", "translation": "l''hôpital", "transliteration": "mustachfâ"}, "pool": "lesson", "lessonId": "ar.l08", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e21', 'ar', 'ar.l08', 'ar.v.maktaba', array['ar.v.maktaba','ar.g08.ta_marbuta_maqsura_hamza_lam_alif']::text[], 'translation', 'lesson', 'مَكْتَبَة', array['la bibliothèque','bibliothèque','une bibliothèque','la librairie','librairie','une librairie']::text[], 'مَكْتَبَة se lit maktaba et veut dire « la bibliothèque » ou « la librairie » : le lieu des livres.', 3, '{"id": "ar.l08.e21", "unitIds": ["ar.v.maktaba", "ar.g08.ta_marbuta_maqsura_hamza_lam_alif"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "مَكْتَبَة", "promptLanguage": "ar", "answer": "la bibliothèque", "acceptedAnswers": ["la bibliothèque", "bibliothèque", "une bibliothèque", "la librairie", "librairie", "une librairie"], "explanation": "مَكْتَبَة se lit maktaba et veut dire « la bibliothèque » ou « la librairie » : le lieu des livres.", "tip": "Même racine que كِتَاب : cherche le ك, le ت et le ب.", "extraExample": {"text": "مَكْتَبَتِي", "translation": "ma bibliothèque", "transliteration": "maktabatî"}, "errorPatterns": [{"equals": "le bureau", "category": "word_confusion", "feedback": "Le bureau se dit مَكْتَب (maktab), sans ة finale. مَكْتَبَة (maktaba) est la bibliothèque."}, {"equals": "le livre", "category": "word_confusion", "feedback": "Le livre se dit كِتَاب (kitâb). مَكْتَبَة (maktaba) est le lieu où l''on trouve des livres."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e22', 'ar', 'ar.l08', 'ar.v.fakiha', array['ar.v.fakiha','ar.g08.ta_marbuta_maqsura_hamza_lam_alif']::text[], 'translation', 'lesson', 'فَاكِهَة', array['le fruit','fruit','un fruit','les fruits','fruits','des fruits']::text[], 'فَاكِهَة se lit fâkiha et veut dire « le fruit ». Le ة final se lit a.', 3, '{"id": "ar.l08.e22", "unitIds": ["ar.v.fakiha", "ar.g08.ta_marbuta_maqsura_hamza_lam_alif"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "فَاكِهَة", "promptLanguage": "ar", "answer": "le fruit", "acceptedAnswers": ["le fruit", "fruit", "un fruit", "les fruits", "fruits", "des fruits"], "explanation": "فَاكِهَة se lit fâkiha et veut dire « le fruit ». Le ة final se lit a.", "tip": "Fâkiha : finit par la boucle à deux points.", "extraExample": {"text": "فَوَاكِه", "translation": "des fruits", "transliteration": "fawâkih"}, "errorPatterns": [{"equals": "le jus", "category": "vocabulary", "feedback": "Le jus se dit عَصِير (3aSîr). فَاكِهَة (fâkiha) est le fruit."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e23', 'ar', 'ar.l08', 'ar.g08.ta_marbuta_maqsura_hamza_lam_alif', array['ar.g08.ta_marbuta_maqsura_hamza_lam_alif','ar.v.salam','ar.v.lam_alif']::text[], 'free_answer', 'lesson', 'Comment se lit سَلَام (la paix) ?', array['salâm','salam','salaam']::text[], 'س (s), ل + ا en ligature لا (lâ), م (m) : salâm, « la paix ». Le م final reste isolé car la ligature ne s''attache pas à la suivante.', 4, '{"id": "ar.l08.e23", "unitIds": ["ar.g08.ta_marbuta_maqsura_hamza_lam_alif", "ar.v.salam", "ar.v.lam_alif"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines (â pour un a long).", "prompt": "Comment se lit سَلَام (la paix) ?", "promptLanguage": "fr", "answer": "salâm", "acceptedAnswers": ["salâm", "salam", "salaam"], "explanation": "س (s), ل + ا en ligature لا (lâ), م (m) : salâm, « la paix ». Le م final reste isolé car la ligature ne s''attache pas à la suivante.", "tip": "Scie sans point, ligature, boule.", "extraExample": {"text": "سَلَامٌ لَكَ", "translation": "paix à toi", "transliteration": "salâmun laka"}, "errorPatterns": [{"equals": "sham", "category": "spelling", "feedback": "La première lettre est une scie sans point : c''est س (s), pas ش (ch)."}, {"equals": "salim", "category": "spelling", "feedback": "Le ا de la ligature allonge le a : on lit â, pas i."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e24', 'ar', 'ar.l08', 'ar.g08.ta_marbuta_maqsura_hamza_lam_alif', array['ar.g08.ta_marbuta_maqsura_hamza_lam_alif','ar.v.sama','ar.v.hamza']::text[], 'free_answer', 'lesson', 'Comment se lit سَمَاء (le ciel) ?', array['samâ''','samâ','sama''','sama','samaa''','samaa']::text[], 'س (s), م (m), ا (â long) et ء (coupure de gorge) : samâ'', « le ciel ».', 4, '{"id": "ar.l08.e24", "unitIds": ["ar.g08.ta_marbuta_maqsura_hamza_lam_alif", "ar.v.sama", "ar.v.hamza"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines (â pour un a long, '' pour la hamza).", "prompt": "Comment se lit سَمَاء (le ciel) ?", "promptLanguage": "fr", "answer": "samâ''", "acceptedAnswers": ["samâ''", "samâ", "sama''", "sama", "samaa''", "samaa"], "explanation": "س (s), م (m), ا (â long) et ء (coupure de gorge) : samâ'', « le ciel ».", "tip": "La hamza ء note une brève coupure de la gorge à la fin du mot.", "extraExample": {"text": "فِي السَّمَاء", "translation": "dans le ciel", "transliteration": "fî s-samâ''"}, "errorPatterns": [{"equals": "samâ3", "category": "spelling", "feedback": "La dernière lettre est une hamza ء, un petit signe de coupure, pas un ع (3)."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e01', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.fatha']::text[], 'mcq', 'lesson', 'Comment se lit بَ ?', array['ba']::text[], 'Le petit trait est au-dessus du ب : c''est une fatha, qui donne le son a. On lit donc ba.', 1, '{"id": "ar.l09.e01", "unitIds": ["ar.g09.short_vowels", "ar.v.fatha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit بَ ?", "promptLanguage": "fr", "options": ["ba", "bi", "bu"], "answer": "ba", "acceptedAnswers": ["ba"], "hint": "Regarde où est placé le petit trait.", "explanation": "Le petit trait est au-dessus du ب : c''est une fatha, qui donne le son a. On lit donc ba.", "tip": "Trait au-dessus = a.", "extraExample": {"text": "بَدَن", "translation": "corps", "transliteration": "badan"}, "errorPatterns": [{"equals": "bi", "category": "word_confusion", "feedback": "bi s''écrirait بِ, avec le trait sous la lettre (kasra). Ici le trait est au-dessus : fatha = a."}, {"equals": "bu", "category": "word_confusion", "feedback": "bu s''écrirait بُ, avec un petit و au-dessus (damma). Ici, c''est un simple trait : a."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e02', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.kasra']::text[], 'mcq', 'lesson', 'Comment se lit بِ ?', array['bi']::text[], 'Le petit trait est sous le ب : c''est une kasra, qui donne le son i. On lit bi.', 1, '{"id": "ar.l09.e02", "unitIds": ["ar.g09.short_vowels", "ar.v.kasra"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit بِ ?", "promptLanguage": "fr", "options": ["ba", "bi", "bu"], "answer": "bi", "acceptedAnswers": ["bi"], "explanation": "Le petit trait est sous le ب : c''est une kasra, qui donne le son i. On lit bi.", "tip": "Trait en dessous = i.", "extraExample": {"text": "سِ", "translation": "si", "transliteration": "si"}, "errorPatterns": [{"equals": "ba", "category": "word_confusion", "feedback": "Pour ba, le trait serait au-dessus (fatha). Ici il est en dessous : kasra = i."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e03', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.damma']::text[], 'mcq', 'lesson', 'Comment se lit بُ ?', array['bu']::text[], 'Le petit signe en forme de و au-dessus du ب est une damma : elle donne le son u, prononcé « ou ». On lit bu (« bou »).', 1, '{"id": "ar.l09.e03", "unitIds": ["ar.g09.short_vowels", "ar.v.damma"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit بُ ?", "promptLanguage": "fr", "options": ["ba", "bi", "bu"], "answer": "bu", "acceptedAnswers": ["bu"], "explanation": "Le petit signe en forme de و au-dessus du ب est une damma : elle donne le son u, prononcé « ou ». On lit bu (« bou »).", "tip": "Petit و au-dessus = u (« ou »).", "extraExample": {"text": "دُ", "translation": "du (« dou »)", "transliteration": "du"}, "errorPatterns": [{"equals": "ba", "category": "word_confusion", "feedback": "La fatha est un trait droit. Ici, le signe a une petite boucle comme un و : c''est une damma, u."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e04', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.fatha','ar.v.kasra','ar.v.damma']::text[], 'match', 'lesson', 'Les trois voyelles brèves', '{}'::text[], 'La fatha (trait au-dessus) donne a, la kasra (trait en dessous) donne i, la damma (petit و au-dessus) donne u.', 1, '{"id": "ar.l09.e04", "unitIds": ["ar.g09.short_vowels", "ar.v.fatha", "ar.v.kasra", "ar.v.damma"], "type": "match", "difficulty": 1, "instruction": "Associe chaque signe à son nom et à son son.", "prompt": "Les trois voyelles brèves", "promptLanguage": "fr", "pairs": [{"left": "ـَ", "right": "fatha : a"}, {"left": "ـِ", "right": "kasra : i"}, {"left": "ـُ", "right": "damma : u"}], "answer": "ـَ = fatha : a ; ـِ = kasra : i ; ـُ = damma : u", "acceptedAnswers": [], "explanation": "La fatha (trait au-dessus) donne a, la kasra (trait en dessous) donne i, la damma (petit و au-dessus) donne u.", "tip": "Au-dessus : a ou u ; en dessous : i.", "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e05', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels']::text[], 'mcq', 'lesson', 'Quel mot est vocalisé correctement pour « kataba » (il a écrit) ?', array['كَتَبَ']::text[], 'Kataba = ka-ta-ba : trois syllabes avec a, donc une fatha sur chacune des trois lettres.', 2, '{"id": "ar.l09.e05", "unitIds": ["ar.g09.short_vowels"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le mot bien vocalisé.", "prompt": "Quel mot est vocalisé correctement pour « kataba » (il a écrit) ?", "promptLanguage": "fr", "options": ["كَتَبَ", "كِتَبَ", "كَتُبَ", "كُتِبَ"], "answer": "كَتَبَ", "acceptedAnswers": ["كَتَبَ"], "explanation": "Kataba = ka-ta-ba : trois syllabes avec a, donc une fatha sur chacune des trois lettres.", "tip": "Un son a = un trait au-dessus de la lettre.", "extraExample": {"text": "ذَهَبَ", "translation": "il est allé", "transliteration": "dhahaba"}, "errorPatterns": [{"equals": "كُتِبَ", "category": "word_confusion", "feedback": "Celui-ci se lit kutiba (« il a été écrit ») : damma puis kasra."}, {"equals": "كِتَبَ", "category": "word_confusion", "feedback": "Celui-ci commence par ki : la kasra est sous le ك."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e06', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.walad','ar.v.radjul','ar.v.katif','ar.v.unuq']::text[], 'match', 'lesson', 'Lis chaque mot syllabe par syllabe.', '{}'::text[], 'Chaque lettre se lit avec sa voyelle : wa-lad, ra-djul, ka-tif, 3u-nuq. La dernière lettre, sans signe, se lit sans voyelle.', 2, '{"id": "ar.l09.e06", "unitIds": ["ar.g09.short_vowels", "ar.v.walad", "ar.v.radjul", "ar.v.katif", "ar.v.unuq"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lis chaque mot syllabe par syllabe.", "promptLanguage": "fr", "pairs": [{"left": "وَلَد", "right": "walad"}, {"left": "رَجُل", "right": "radjul"}, {"left": "كَتِف", "right": "katif"}, {"left": "عُنُق", "right": "3unuq"}], "answer": "وَلَد = walad ; رَجُل = radjul ; كَتِف = katif ; عُنُق = 3unuq", "acceptedAnswers": [], "explanation": "Chaque lettre se lit avec sa voyelle : wa-lad, ra-djul, ka-tif, 3u-nuq. La dernière lettre, sans signe, se lit sans voyelle.", "tip": "Lis de droite à gauche, une lettre et son signe à la fois.", "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e07', 'ar', 'ar.l09', 'ar.v.yad', array['ar.v.yad','ar.v.fam','ar.v.katif','ar.v.unuq','ar.v.radjul']::text[], 'match', 'lesson', 'Le corps et les personnes', '{}'::text[], 'يَد (yad) = la main, فَم (fam) = la bouche, كَتِف (katif) = l''épaule, عُنُق (3unuq) = le cou, رَجُل (radjul) = l''homme.', 2, '{"id": "ar.l09.e07", "unitIds": ["ar.v.yad", "ar.v.fam", "ar.v.katif", "ar.v.unuq", "ar.v.radjul"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Le corps et les personnes", "promptLanguage": "fr", "pairs": [{"left": "يَد", "right": "la main"}, {"left": "فَم", "right": "la bouche"}, {"left": "كَتِف", "right": "l''épaule"}, {"left": "عُنُق", "right": "le cou"}, {"left": "رَجُل", "right": "l''homme"}], "answer": "يَد = la main ; فَم = la bouche ; كَتِف = l''épaule ; عُنُق = le cou ; رَجُل = l''homme", "acceptedAnswers": [], "explanation": "يَد (yad) = la main, فَم (fam) = la bouche, كَتِف (katif) = l''épaule, عُنُق (3unuq) = le cou, رَجُل (radjul) = l''homme.", "tip": "Lis d''abord le mot à voix haute : le son aide à retrouver le sens.", "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e08', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels']::text[], 'mcq', 'lesson', 'Dans كَتَبَ, quelle forme a le ت ?', array['la forme du milieu (ـتـ)']::text[], 'Le ت est attaché au ك avant lui et au ب après lui : il prend sa forme du milieu, ـتـ.', 2, '{"id": "ar.l09.e08", "unitIds": ["ar.g09.short_vowels"], "type": "mcq", "difficulty": 2, "instruction": "Révision des formes de lettres. Choisis la bonne réponse.", "prompt": "Dans كَتَبَ, quelle forme a le ت ?", "promptLanguage": "fr", "options": ["la forme du milieu (ـتـ)", "la forme du début (تـ)", "la forme de la fin (ـت)", "la forme isolée (ت)"], "answer": "la forme du milieu (ـتـ)", "acceptedAnswers": ["la forme du milieu (ـتـ)"], "explanation": "Le ت est attaché au ك avant lui et au ب après lui : il prend sa forme du milieu, ـتـ.", "tip": "Lettre attachée des deux côtés = forme du milieu.", "extraExample": {"text": "فَهِمَ", "translation": "il a compris", "transliteration": "fahima"}, "errorPatterns": [{"equals": "la forme de la fin (ـت)", "category": "spelling", "feedback": "La forme de la fin n''est attachée qu''à droite. Ici le ت est aussi relié au ب qui suit."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e09', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels']::text[], 'mcq', 'lesson', 'Comment se lit فَهِمَ (il a compris) ?', array['fahima']::text[], 'Fatha sur le ف (fa), kasra sous le ه (hi), fatha sur le م (ma) : fa-hi-ma.', 2, '{"id": "ar.l09.e09", "unitIds": ["ar.g09.short_vowels"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit فَهِمَ (il a compris) ?", "promptLanguage": "fr", "options": ["fahima", "fahama", "fuhima", "fahimu"], "answer": "fahima", "acceptedAnswers": ["fahima"], "explanation": "Fatha sur le ف (fa), kasra sous le ه (hi), fatha sur le م (ma) : fa-hi-ma.", "tip": "Une lettre, un signe, une syllabe.", "extraExample": {"text": "شَرِبَ", "translation": "il a bu", "transliteration": "chariba"}, "errorPatterns": [{"equals": "fahama", "category": "word_confusion", "feedback": "Regarde sous le ه : le trait est en dessous, c''est une kasra (hi)."}, {"equals": "fuhima", "category": "word_confusion", "feedback": "Sur le ف, c''est un simple trait (fatha) : fa, pas fu."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e10', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.unuq']::text[], 'mcq', 'lesson', 'Comment se lit عُنُق (le cou) ?', array['3unuq']::text[], 'Le ع et le ن portent chacun une damma (u) ; le ق final n''a pas de signe : 3u-nuq.', 2, '{"id": "ar.l09.e10", "unitIds": ["ar.g09.short_vowels", "ar.v.unuq"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit عُنُق (le cou) ?", "promptLanguage": "fr", "options": ["3unuq", "3anaq", "3iniq", "3unaq"], "answer": "3unuq", "acceptedAnswers": ["3unuq"], "explanation": "Le ع et le ن portent chacun une damma (u) ; le ق final n''a pas de signe : 3u-nuq.", "tip": "Deux petits و au-dessus = deux u.", "extraExample": {"text": "رُطَب", "translation": "dattes fraîches", "transliteration": "ruTab"}, "errorPatterns": [{"equals": "3unaq", "category": "word_confusion", "feedback": "Le ن porte aussi une damma, pas une fatha : nu."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e11', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.yad']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit « yad » (la main) ?', array['يَد']::text[], 'Pour yad, il faut le son a sur le ي : une fatha, donc un trait au-dessus.', 2, '{"id": "ar.l09.e11", "unitIds": ["ar.g09.short_vowels", "ar.v.yad"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le mot qui correspond.", "prompt": "Lequel de ces mots se lit « yad » (la main) ?", "promptLanguage": "fr", "options": ["يَد", "يُد", "يِد"], "answer": "يَد", "acceptedAnswers": ["يَد"], "explanation": "Pour yad, il faut le son a sur le ي : une fatha, donc un trait au-dessus.", "tip": "Son a = trait au-dessus.", "extraExample": {"text": "يَدُ الْوَلَدِ", "translation": "la main du garçon", "transliteration": "yadu l-waladi"}, "errorPatterns": [{"equals": "يُد", "category": "word_confusion", "feedback": "Le petit و au-dessus est une damma : on lirait yud."}, {"equals": "يِد", "category": "word_confusion", "feedback": "Le trait sous la lettre est une kasra : on lirait yid."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e12', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels']::text[], 'mcq', 'lesson', 'Comment s''écrit le ع au début d''un mot, comme dans عُنُق ?', array['عـ']::text[], 'Au début d''un mot, le ع est attaché seulement à la lettre suivante : on écrit عـ, la tête ouverte.', 2, '{"id": "ar.l09.e12", "unitIds": ["ar.g09.short_vowels"], "type": "mcq", "difficulty": 2, "instruction": "Révision des formes de lettres. Choisis la bonne réponse.", "prompt": "Comment s''écrit le ع au début d''un mot, comme dans عُنُق ?", "promptLanguage": "fr", "options": ["عـ", "ـعـ", "ـع", "ع"], "answer": "عـ", "acceptedAnswers": ["عـ"], "explanation": "Au début d''un mot, le ع est attaché seulement à la lettre suivante : on écrit عـ, la tête ouverte.", "tip": "Début de mot = attaché seulement à gauche.", "extraExample": {"text": "عَمَل", "translation": "travail", "transliteration": "3amal"}, "errorPatterns": [{"equals": "ـعـ", "category": "spelling", "feedback": "ـعـ est la forme du milieu, attachée des deux côtés. Au début, rien n''est attaché à droite."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e13', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.kasra']::text[], 'fill_blank', 'lesson', 'Pour écrire « bi », on met une ___ sous le ب.', array['kasra']::text[], 'Le son i s''écrit avec une kasra, un petit trait placé sous la lettre : بِ.', 2, '{"id": "ar.l09.e13", "unitIds": ["ar.g09.short_vowels", "ar.v.kasra"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le nom du signe.", "prompt": "Pour écrire « bi », on met une ___ sous le ب.", "promptLanguage": "fr", "options": ["kasra", "fatha", "damma"], "answer": "kasra", "acceptedAnswers": ["kasra"], "explanation": "Le son i s''écrit avec une kasra, un petit trait placé sous la lettre : بِ.", "tip": "Kasra = sous la lettre = i.", "extraExample": {"text": "سِ", "translation": "si", "transliteration": "si"}, "errorPatterns": [{"equals": "fatha", "category": "word_confusion", "feedback": "La fatha se met au-dessus et donne a. Pour i, le trait va sous la lettre : kasra."}, {"equals": "damma", "category": "word_confusion", "feedback": "La damma donne u et se met au-dessus."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e14', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.radjul']::text[], 'fill_blank', 'lesson', 'Dans رَجُل (radjul, homme), le ج porte une ___.', array['damma','dhamma']::text[], 'On lit ra-djul : le ج a le son u, donc une damma (le petit و au-dessus).', 2, '{"id": "ar.l09.e14", "unitIds": ["ar.g09.short_vowels", "ar.v.radjul"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le nom du signe.", "prompt": "Dans رَجُل (radjul, homme), le ج porte une ___.", "promptLanguage": "fr", "options": ["damma", "fatha", "kasra"], "answer": "damma", "acceptedAnswers": ["damma", "dhamma"], "explanation": "On lit ra-djul : le ج a le son u, donc une damma (le petit و au-dessus).", "tip": "Son u (« ou ») = damma.", "extraExample": {"text": "كُتِبَ", "translation": "il a été écrit", "transliteration": "kutiba"}, "errorPatterns": [{"equals": "fatha", "category": "word_confusion", "feedback": "La fatha est sur le ر (ra). Sur le ج, on entend u : c''est une damma."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e15', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels']::text[], 'reorder', 'lesson', 'Écris « kataba » (il a écrit).', array['كَ تَ بَ']::text[], 'Ka-ta-ba : trois syllabes, chacune avec une fatha. On commence par la droite en arabe, mais on touche d''abord la première syllabe.', 2, '{"id": "ar.l09.e15", "unitIds": ["ar.g09.short_vowels"], "type": "reorder", "difficulty": 2, "instruction": "Touche les syllabes dans l''ordre de lecture (la première d''abord).", "prompt": "Écris « kataba » (il a écrit).", "promptLanguage": "fr", "tokens": ["بَ", "كَ", "تَ"], "answer": "كَ تَ بَ", "acceptedAnswers": ["كَ تَ بَ"], "explanation": "Ka-ta-ba : trois syllabes, chacune avec une fatha. On commence par la droite en arabe, mais on touche d''abord la première syllabe.", "tip": "Dis le mot à voix haute et suis les syllabes.", "extraExample": {"text": "جَلَسَ", "translation": "il s''est assis", "transliteration": "djalasa"}, "pool": "lesson", "lessonId": "ar.l09", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e16', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.radjul']::text[], 'reorder', 'lesson', 'Écris « radjul » (homme).', array['رَ جُ ل']::text[], 'Ra-djul : ر avec fatha, ج avec damma, puis ل sans voyelle qui termine le mot.', 3, '{"id": "ar.l09.e16", "unitIds": ["ar.g09.short_vowels", "ar.v.radjul"], "type": "reorder", "difficulty": 3, "instruction": "Touche les syllabes dans l''ordre de lecture (la première d''abord).", "prompt": "Écris « radjul » (homme).", "promptLanguage": "fr", "tokens": ["جُ", "ل", "رَ"], "answer": "رَ جُ ل", "acceptedAnswers": ["رَ جُ ل"], "explanation": "Ra-djul : ر avec fatha, ج avec damma, puis ل sans voyelle qui termine le mot.", "tip": "La dernière lettre d''un mot isolé se lit souvent sans voyelle.", "extraExample": {"text": "وَلَد", "translation": "garçon", "transliteration": "walad"}, "pool": "lesson", "lessonId": "ar.l09", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e17', 'ar', 'ar.l09', 'ar.v.fam', array['ar.v.fam','ar.g09.short_vowels']::text[], 'translation', 'lesson', 'فَم', array['la bouche','bouche','une bouche']::text[], 'فَم se lit fam (fatha sur le ف) et veut dire « la bouche ».', 2, '{"id": "ar.l09.e17", "unitIds": ["ar.v.fam", "ar.g09.short_vowels"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "فَم", "promptLanguage": "ar", "answer": "la bouche", "acceptedAnswers": ["la bouche", "bouche", "une bouche"], "explanation": "فَم se lit fam (fatha sur le ف) et veut dire « la bouche ».", "tip": "Fam, la bouche : un mot d''une seule syllabe.", "extraExample": {"text": "فَمُ الطِّفْلِ", "translation": "la bouche de l''enfant", "transliteration": "famu T-Tifli"}, "errorPatterns": [{"equals": "la main", "category": "vocabulary", "feedback": "La main, c''est يَد (yad). فَم (fam), c''est la bouche."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e18', 'ar', 'ar.l09', 'ar.v.walad', array['ar.v.walad','ar.g09.short_vowels']::text[], 'translation', 'lesson', 'وَلَد', array['garçon','un garçon','le garçon','enfant','un enfant','l''enfant','fils','un fils','le fils']::text[], 'وَلَد se lit walad : un garçon, ou plus largement un enfant.', 2, '{"id": "ar.l09.e18", "unitIds": ["ar.v.walad", "ar.g09.short_vowels"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "وَلَد", "promptLanguage": "ar", "answer": "garçon", "acceptedAnswers": ["garçon", "un garçon", "le garçon", "enfant", "un enfant", "l''enfant", "fils", "un fils", "le fils"], "explanation": "وَلَد se lit walad : un garçon, ou plus largement un enfant.", "tip": "Walad : le garçon, l''enfant.", "extraExample": {"text": "وَلَدٌ صَغِيرٌ", "translation": "un petit garçon", "transliteration": "waladun Saghîrun"}, "errorPatterns": [{"equals": "homme", "category": "vocabulary", "feedback": "L''homme, c''est رَجُل (radjul). وَلَد (walad) est un garçon, un enfant."}, {"equals": "fille", "category": "vocabulary", "feedback": "La fille, c''est بِنْت (bint). وَلَد (walad) est un garçon."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e19', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.katif']::text[], 'free_answer', 'lesson', 'Comment se lit كَتِف (l''épaule) ?', array['katif']::text[], 'Fatha sur le ك (ka), kasra sous le ت (ti), ف final sans voyelle : ka-tif.', 3, '{"id": "ar.l09.e19", "unitIds": ["ar.g09.short_vowels", "ar.v.katif"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit كَتِف (l''épaule) ?", "promptLanguage": "fr", "answer": "katif", "acceptedAnswers": ["katif"], "hint": "Le signe du ت est sous la lettre.", "explanation": "Fatha sur le ك (ka), kasra sous le ت (ti), ف final sans voyelle : ka-tif.", "tip": "Regarde au-dessus ET en dessous de chaque lettre.", "extraExample": {"text": "كَتِفِي", "translation": "mon épaule", "transliteration": "katifî"}, "errorPatterns": [{"equals": "kataf", "category": "spelling", "feedback": "Le ت porte une kasra (trait sous la lettre) : ti, pas ta."}, {"equals": "kitaf", "category": "spelling", "feedback": "Le ك porte une fatha (trait au-dessus) : ka. La kasra est sous le ت."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e20', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels']::text[], 'free_answer', 'lesson', 'Comment se lit كُتِبَ (il a été écrit) ?', array['kutiba','koutiba']::text[], 'Damma sur le ك (ku), kasra sous le ت (ti), fatha sur le ب (ba) : ku-ti-ba. Mêmes lettres que kataba, mais d''autres voyelles et un autre sens.', 4, '{"id": "ar.l09.e20", "unitIds": ["ar.g09.short_vowels"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit كُتِبَ (il a été écrit) ?", "promptLanguage": "fr", "answer": "kutiba", "acceptedAnswers": ["kutiba", "koutiba"], "explanation": "Damma sur le ك (ku), kasra sous le ت (ti), fatha sur le ب (ba) : ku-ti-ba. Mêmes lettres que kataba, mais d''autres voyelles et un autre sens.", "tip": "Mêmes lettres, autres signes = autre mot : lis toujours les signes.", "extraExample": {"text": "كَتَبَ", "translation": "il a écrit", "transliteration": "kataba"}, "errorPatterns": [{"equals": "kataba", "category": "spelling", "feedback": "Regarde bien : damma sur le ك (ku), kasra sous le ت (ti). kataba s''écrirait كَتَبَ."}, {"equals": "kutib", "category": "spelling", "feedback": "Le ب final porte une fatha : il se prononce ba. On lit kutiba."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e21', 'ar', 'ar.l09', 'ar.g09.short_vowels', array['ar.g09.short_vowels']::text[], 'mcq', 'lesson', 'Dans وَلَد, quelle lettre ne s''attache pas à la lettre qui la suit ?', array['و']::text[], 'و fait partie des lettres qui ne s''attachent jamais à gauche (ا د ذ ر ز و). C''est pour cela que وَلَد commence par un و détaché.', 3, '{"id": "ar.l09.e21", "unitIds": ["ar.g09.short_vowels"], "type": "mcq", "difficulty": 3, "instruction": "Révision des lettres. Choisis la bonne réponse.", "prompt": "Dans وَلَد, quelle lettre ne s''attache pas à la lettre qui la suit ?", "promptLanguage": "fr", "options": ["و", "ل", "ب", "ي"], "answer": "و", "acceptedAnswers": ["و"], "explanation": "و fait partie des lettres qui ne s''attachent jamais à gauche (ا د ذ ر ز و). C''est pour cela que وَلَد commence par un و détaché.", "tip": "ا د ذ ر ز و : six lettres qui ne tendent jamais la main à gauche.", "extraExample": {"text": "دَرَسَ", "translation": "il a étudié", "transliteration": "darasa"}, "errorPatterns": [{"equals": "ل", "category": "spelling", "feedback": "Le ل s''attache des deux côtés. Celui qui reste seul à gauche, c''est le و."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e01', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun','ar.v.sukun']::text[], 'mcq', 'lesson', 'Que veut dire le petit rond (ـْ) posé sur une lettre ?', array['la lettre n''a pas de voyelle']::text[], 'Le petit rond est le sukun : la consonne se prononce seule, sans voyelle, et ferme la syllabe.', 1, '{"id": "ar.l10.e01", "unitIds": ["ar.g10.sukun", "ar.v.sukun"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le petit rond (ـْ) posé sur une lettre ?", "promptLanguage": "fr", "options": ["la lettre n''a pas de voyelle", "la voyelle u", "la lettre est doublée", "la voyelle est longue"], "answer": "la lettre n''a pas de voyelle", "acceptedAnswers": ["la lettre n''a pas de voyelle"], "explanation": "Le petit rond est le sukun : la consonne se prononce seule, sans voyelle, et ferme la syllabe.", "tip": "Petit rond = rien : la consonne s''arrête net.", "extraExample": {"text": "قَلْب", "translation": "cœur", "transliteration": "qalb"}, "errorPatterns": [{"equals": "la voyelle u", "category": "word_confusion", "feedback": "Le son u, c''est la damma, qui a une petite queue comme un و. Le sukun est un rond fermé : pas de voyelle."}, {"equals": "la lettre est doublée", "category": "word_confusion", "feedback": "La lettre doublée, c''est la shadda (petit w). Le petit rond, c''est le sukun : pas de voyelle."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e02', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun','ar.v.sukun','ar.v.fatha','ar.v.kasra','ar.v.damma']::text[], 'match', 'lesson', 'Les quatre signes de base', '{}'::text[], 'Fatha = a, kasra = i, damma = u, et le sukun = aucune voyelle : la consonne reste nue.', 1, '{"id": "ar.l10.e02", "unitIds": ["ar.g10.sukun", "ar.v.sukun", "ar.v.fatha", "ar.v.kasra", "ar.v.damma"], "type": "match", "difficulty": 1, "instruction": "Associe chaque signe à ce qu''il fait entendre.", "prompt": "Les quatre signes de base", "promptLanguage": "fr", "pairs": [{"left": "ـَ", "right": "a"}, {"left": "ـِ", "right": "i"}, {"left": "ـُ", "right": "u"}, {"left": "ـْ", "right": "pas de voyelle"}], "answer": "ـَ = a ; ـِ = i ; ـُ = u ; ـْ = pas de voyelle", "acceptedAnswers": [], "explanation": "Fatha = a, kasra = i, damma = u, et le sukun = aucune voyelle : la consonne reste nue.", "tip": "Le sukun est le seul signe qui enlève le son au lieu d''en ajouter un.", "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e03', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun','ar.v.bint','ar.v.ibn','ar.v.tifl','ar.v.qalb']::text[], 'match', 'lesson', 'Des mots avec un sukun', '{}'::text[], 'Dans chaque mot, la lettre avec sukun se colle à la syllabe d''avant : bin-t, ib-n, Tif-l, qal-b.', 1, '{"id": "ar.l10.e03", "unitIds": ["ar.g10.sukun", "ar.v.bint", "ar.v.ibn", "ar.v.tifl", "ar.v.qalb"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Des mots avec un sukun", "promptLanguage": "fr", "pairs": [{"left": "بِنْت", "right": "bint"}, {"left": "اِبْن", "right": "ibn"}, {"left": "طِفْل", "right": "Tifl"}, {"left": "قَلْب", "right": "qalb"}], "answer": "بِنْت = bint ; اِبْن = ibn ; طِفْل = Tifl ; قَلْب = qalb", "acceptedAnswers": [], "explanation": "Dans chaque mot, la lettre avec sukun se colle à la syllabe d''avant : bin-t, ib-n, Tif-l, qal-b.", "tip": "Une syllabe fermée se dit d''un seul coup : qal, pas qa-la.", "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e04', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun','ar.v.bint']::text[], 'mcq', 'lesson', 'Comment se lit بِنْت (fille) ?', array['bint']::text[], 'Kasra sous le ب (bi), sukun sur le ن (n sans voyelle), puis ت final : bint, une seule syllabe.', 1, '{"id": "ar.l10.e04", "unitIds": ["ar.g10.sukun", "ar.v.bint"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit بِنْت (fille) ?", "promptLanguage": "fr", "options": ["bint", "binat", "banit", "bunt"], "answer": "bint", "acceptedAnswers": ["bint"], "explanation": "Kasra sous le ب (bi), sukun sur le ن (n sans voyelle), puis ت final : bint, une seule syllabe.", "tip": "Le sukun colle la consonne à la voyelle d''avant.", "extraExample": {"text": "طِفْل", "translation": "enfant", "transliteration": "Tifl"}, "errorPatterns": [{"equals": "binat", "category": "word_confusion", "feedback": "Le ن porte un sukun : on n''ajoute pas de a après lui. On lit bint."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e05', 'ar', 'ar.l10', 'ar.v.wadjh', array['ar.v.wadjh','ar.v.ridjl','ar.v.chakhs','ar.v.batn','ar.v.qalb']::text[], 'match', 'lesson', 'Visage, jambe, personne, ventre et cœur', '{}'::text[], 'وَجْه (wadjh) = le visage, رِجْل (ridjl) = la jambe, شَخْص (chakhS) = la personne, بَطْن (baTn) = le ventre, قَلْب (qalb) = le cœur.', 2, '{"id": "ar.l10.e05", "unitIds": ["ar.v.wadjh", "ar.v.ridjl", "ar.v.chakhs", "ar.v.batn", "ar.v.qalb"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Visage, jambe, personne, ventre et cœur", "promptLanguage": "fr", "pairs": [{"left": "وَجْه", "right": "le visage"}, {"left": "رِجْل", "right": "la jambe"}, {"left": "شَخْص", "right": "la personne"}, {"left": "بَطْن", "right": "le ventre"}, {"left": "قَلْب", "right": "le cœur"}], "answer": "وَجْه = le visage ; رِجْل = la jambe ; شَخْص = la personne ; بَطْن = le ventre ; قَلْب = le cœur", "acceptedAnswers": [], "explanation": "وَجْه (wadjh) = le visage, رِجْل (ridjl) = la jambe, شَخْص (chakhS) = la personne, بَطْن (baTn) = le ventre, قَلْب (qalb) = le cœur.", "tip": "Lis chaque mot à voix haute avant de chercher son sens.", "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e06', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun']::text[], 'mcq', 'lesson', 'Dans كَتَبْتُ (j''ai écrit), quelle lettre porte un sukun ?', array['le ب']::text[], 'On lit ka-tab-tu : le ب porte le petit rond, il n''a pas de voyelle et ferme la syllabe tab.', 2, '{"id": "ar.l10.e06", "unitIds": ["ar.g10.sukun"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans كَتَبْتُ (j''ai écrit), quelle lettre porte un sukun ?", "promptLanguage": "fr", "options": ["le ب", "le ك", "le premier ت", "le dernier ت"], "answer": "le ب", "acceptedAnswers": ["le ب"], "explanation": "On lit ka-tab-tu : le ب porte le petit rond, il n''a pas de voyelle et ferme la syllabe tab.", "tip": "Cherche le petit rond, puis découpe : ka-tab-tu.", "extraExample": {"text": "دَرَسْتُ", "translation": "j''ai étudié", "transliteration": "darastu"}, "errorPatterns": [{"equals": "le dernier ت", "category": "word_confusion", "feedback": "Le dernier ت porte une damma (tu). Le sukun est sur le ب."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e07', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun']::text[], 'mcq', 'lesson', 'Comment se lit كَتَبْتُ (j''ai écrit) ?', array['katabtu']::text[], 'Ka-tab-tu : le ب a un sukun, il se colle à ta. On ne dit donc pas « katabatu ».', 2, '{"id": "ar.l10.e07", "unitIds": ["ar.g10.sukun"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit كَتَبْتُ (j''ai écrit) ?", "promptLanguage": "fr", "options": ["katabtu", "katabatu", "katibtu", "katbutu"], "answer": "katabtu", "acceptedAnswers": ["katabtu"], "explanation": "Ka-tab-tu : le ب a un sukun, il se colle à ta. On ne dit donc pas « katabatu ».", "tip": "Pas de voyelle sous le petit rond.", "extraExample": {"text": "جَلَسْتُ", "translation": "je me suis assis", "transliteration": "djalastu"}, "errorPatterns": [{"equals": "katabatu", "category": "word_confusion", "feedback": "Tu as ajouté un a après le ب, mais il porte un sukun : katabtu."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e08', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun','ar.v.chakhs']::text[], 'mcq', 'lesson', 'Quel mot est vocalisé correctement pour « chakhS » (personne) ?', array['شَخْص']::text[], 'Cha-khS : fatha sur le ش, sukun sur le خ (pas de voyelle), puis le ص final.', 2, '{"id": "ar.l10.e08", "unitIds": ["ar.g10.sukun", "ar.v.chakhs"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le mot bien vocalisé.", "prompt": "Quel mot est vocalisé correctement pour « chakhS » (personne) ?", "promptLanguage": "fr", "options": ["شَخْص", "شَخَص", "شُخْص", "شِخْص"], "answer": "شَخْص", "acceptedAnswers": ["شَخْص"], "explanation": "Cha-khS : fatha sur le ش, sukun sur le خ (pas de voyelle), puis le ص final.", "tip": "Une consonne collée à la suivante = sukun.", "extraExample": {"text": "بَطْن", "translation": "ventre", "transliteration": "baTn"}, "errorPatterns": [{"equals": "شَخَص", "category": "word_confusion", "feedback": "Avec une fatha sur le خ, on lirait chakhaS. Il faut un sukun : chakhS."}, {"equals": "شُخْص", "category": "word_confusion", "feedback": "La damma sur le ش donnerait chukhS. On dit chakhS, avec a."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e09', 'ar', 'ar.l10', 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.ridjl']::text[], 'mcq', 'lesson', 'Quel signe porte le ر dans رِجْل (ridjl) ?', array['une kasra']::text[], 'On entend ri : le ر porte une kasra, le petit trait sous la lettre. Le ج, lui, porte un sukun.', 2, '{"id": "ar.l10.e09", "unitIds": ["ar.g09.short_vowels", "ar.v.ridjl"], "type": "mcq", "difficulty": 2, "instruction": "Révision : choisis la bonne réponse.", "prompt": "Quel signe porte le ر dans رِجْل (ridjl) ?", "promptLanguage": "fr", "options": ["une kasra", "une fatha", "une damma", "un sukun"], "answer": "une kasra", "acceptedAnswers": ["une kasra"], "explanation": "On entend ri : le ر porte une kasra, le petit trait sous la lettre. Le ج, lui, porte un sukun.", "tip": "Son i = trait sous la lettre.", "extraExample": {"text": "سِنّ", "translation": "dent", "transliteration": "sinn"}, "errorPatterns": [{"equals": "un sukun", "category": "word_confusion", "feedback": "Le sukun est sur le ج, pas sur le ر : un mot ne commence jamais par une lettre sans voyelle."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e10', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun','ar.v.ridjl','ar.v.radjul']::text[], 'mcq', 'lesson', 'Lequel de ces mots veut dire « la jambe » ?', array['رِجْل']::text[], 'رِجْل (ridjl) = la jambe ; رَجُل (radjul) = l''homme. Mêmes lettres, mais ce sont les signes qui font la différence.', 3, '{"id": "ar.l10.e10", "unitIds": ["ar.g10.sukun", "ar.v.ridjl", "ar.v.radjul"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots veut dire « la jambe » ?", "promptLanguage": "fr", "options": ["رِجْل", "رَجُل", "رُجُل"], "answer": "رِجْل", "acceptedAnswers": ["رِجْل"], "explanation": "رِجْل (ridjl) = la jambe ; رَجُل (radjul) = l''homme. Mêmes lettres, mais ce sont les signes qui font la différence.", "tip": "Ridjl (sukun) pour la jambe, radjul pour l''homme.", "extraExample": {"text": "رَجُل", "translation": "homme", "transliteration": "radjul"}, "errorPatterns": [{"equals": "رَجُل", "category": "vocabulary", "feedback": "رَجُل se lit radjul : c''est l''homme. La jambe, c''est رِجْل (ridjl), avec un sukun sur le ج."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e11', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun','ar.v.qalb']::text[], 'mcq', 'lesson', 'Lequel de ces mots a une syllabe fermée par un sukun ?', array['قَلْب']::text[], 'Dans قَلْب, le ل porte un sukun : qal-b. Les trois autres mots n''ont que des voyelles brèves (ra-djul, ka-tif, 3u-nuq).', 2, '{"id": "ar.l10.e11", "unitIds": ["ar.g10.sukun", "ar.v.qalb"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Lequel de ces mots a une syllabe fermée par un sukun ?", "promptLanguage": "fr", "options": ["قَلْب", "رَجُل", "كَتِف", "عُنُق"], "answer": "قَلْب", "acceptedAnswers": ["قَلْب"], "explanation": "Dans قَلْب, le ل porte un sukun : qal-b. Les trois autres mots n''ont que des voyelles brèves (ra-djul, ka-tif, 3u-nuq).", "tip": "Le petit rond signale toujours une syllabe fermée.", "extraExample": {"text": "وَجْه", "translation": "visage", "transliteration": "wadjh"}, "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e12', 'ar', 'ar.l10', 'ar.g09.short_vowels', array['ar.g09.short_vowels']::text[], 'mcq', 'lesson', 'Dans بِنْت, quelle forme a le ن ?', array['la forme du milieu (ـنـ)']::text[], 'Le ن est relié au ب avant lui et au ت après lui : c''est sa forme du milieu, qui ressemble à une dent avec un point au-dessus.', 2, '{"id": "ar.l10.e12", "unitIds": ["ar.g09.short_vowels"], "type": "mcq", "difficulty": 2, "instruction": "Révision des formes de lettres. Choisis la bonne réponse.", "prompt": "Dans بِنْت, quelle forme a le ن ?", "promptLanguage": "fr", "options": ["la forme du milieu (ـنـ)", "la forme de la fin (ـن)", "la forme isolée (ن)", "la forme du début (نـ)"], "answer": "la forme du milieu (ـنـ)", "acceptedAnswers": ["la forme du milieu (ـنـ)"], "explanation": "Le ن est relié au ب avant lui et au ت après lui : c''est sa forme du milieu, qui ressemble à une dent avec un point au-dessus.", "tip": "Au milieu, ب ت ث ن ي se ressemblent : seuls les points changent.", "extraExample": {"text": "بَنَات", "translation": "filles", "transliteration": "banât"}, "errorPatterns": [{"equals": "la forme de la fin (ـن)", "category": "spelling", "feedback": "La forme de la fin a une grande courbe ; ici, le ن est suivi du ت, il est donc au milieu."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e13', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun','ar.v.sukun','ar.v.qalb']::text[], 'fill_blank', 'lesson', 'Dans قَلْب (qalb), le ل porte un ___.', array['sukun','soukoun','soukoune','sukûn']::text[], 'Le ل se prononce sans voyelle et ferme la syllabe qal : il porte un sukun.', 2, '{"id": "ar.l10.e13", "unitIds": ["ar.g10.sukun", "ar.v.sukun", "ar.v.qalb"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le nom du signe.", "prompt": "Dans قَلْب (qalb), le ل porte un ___.", "promptLanguage": "fr", "options": ["sukun", "fatha", "damma", "kasra"], "answer": "sukun", "acceptedAnswers": ["sukun", "soukoun", "soukoune", "sukûn"], "explanation": "Le ل se prononce sans voyelle et ferme la syllabe qal : il porte un sukun.", "tip": "Pas de voyelle = sukun.", "extraExample": {"text": "طِفْل", "translation": "enfant", "transliteration": "Tifl"}, "errorPatterns": [{"equals": "damma", "category": "word_confusion", "feedback": "La damma donnerait qalub. Ici le ل n''a pas de voyelle : sukun."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e14', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun','ar.v.wadjh']::text[], 'fill_blank', 'lesson', 'وَجْه (visage) se lit « ___ ».', array['wadjh','wajh']::text[], 'Fatha sur le و (wa), sukun sur le ج, puis le ه final : wadjh.', 2, '{"id": "ar.l10.e14", "unitIds": ["ar.g10.sukun", "ar.v.wadjh"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne lecture.", "prompt": "وَجْه (visage) se lit « ___ ».", "promptLanguage": "fr", "options": ["wadjh", "wadjah", "widjh", "wudjuh"], "answer": "wadjh", "acceptedAnswers": ["wadjh", "wajh"], "explanation": "Fatha sur le و (wa), sukun sur le ج, puis le ه final : wadjh.", "tip": "Sukun = la consonne se colle à la syllabe d''avant.", "extraExample": {"text": "وَجْهِي", "translation": "mon visage", "transliteration": "wadjhî"}, "errorPatterns": [{"equals": "wadjah", "category": "spelling", "feedback": "Le ج porte un sukun : pas de a après lui. On lit wadjh."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e15', 'ar', 'ar.l10', 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.fam']::text[], 'fill_blank', 'lesson', 'Dans فَم (fam), le ف porte une ___.', array['fatha','fat7a']::text[], 'On entend fa : le ف porte une fatha, le petit trait au-dessus.', 2, '{"id": "ar.l10.e15", "unitIds": ["ar.g09.short_vowels", "ar.v.fam"], "type": "fill_blank", "difficulty": 2, "instruction": "Révision : complète avec le nom du signe.", "prompt": "Dans فَم (fam), le ف porte une ___.", "promptLanguage": "fr", "options": ["fatha", "kasra", "damma", "sukun"], "answer": "fatha", "acceptedAnswers": ["fatha", "fat7a"], "explanation": "On entend fa : le ف porte une fatha, le petit trait au-dessus.", "tip": "Son a = fatha au-dessus.", "extraExample": {"text": "يَد", "translation": "main", "transliteration": "yad"}, "errorPatterns": [{"equals": "kasra", "category": "word_confusion", "feedback": "La kasra donnerait fi. Ici on entend fa : fatha."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e16', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun']::text[], 'reorder', 'lesson', 'Écris « katabtu » (j''ai écrit).', array['كَ تَبْ تُ']::text[], 'Ka-tab-tu : la syllabe du milieu est fermée par le ب avec sukun.', 2, '{"id": "ar.l10.e16", "unitIds": ["ar.g10.sukun"], "type": "reorder", "difficulty": 2, "instruction": "Touche les syllabes dans l''ordre de lecture (la première d''abord).", "prompt": "Écris « katabtu » (j''ai écrit).", "promptLanguage": "fr", "tokens": ["تُ", "كَ", "تَبْ"], "answer": "كَ تَبْ تُ", "acceptedAnswers": ["كَ تَبْ تُ"], "explanation": "Ka-tab-tu : la syllabe du milieu est fermée par le ب avec sukun.", "tip": "Découpe le mot à voix haute : ka / tab / tu.", "extraExample": {"text": "دَرَسْتُ", "translation": "j''ai étudié", "transliteration": "darastu"}, "pool": "lesson", "lessonId": "ar.l10", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e17', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun','ar.v.batn']::text[], 'reorder', 'lesson', 'Écris « baTn » (ventre).', array['بَ طْ ن']::text[], 'Ba, puis ط avec sukun, puis ن : baTn, une seule syllabe.', 2, '{"id": "ar.l10.e17", "unitIds": ["ar.g10.sukun", "ar.v.batn"], "type": "reorder", "difficulty": 2, "instruction": "Touche les morceaux dans l''ordre de lecture (le premier d''abord).", "prompt": "Écris « baTn » (ventre).", "promptLanguage": "fr", "tokens": ["طْ", "ن", "بَ"], "answer": "بَ طْ ن", "acceptedAnswers": ["بَ طْ ن"], "explanation": "Ba, puis ط avec sukun, puis ن : baTn, une seule syllabe.", "tip": "Une lettre avec sukun ne fait pas de syllabe toute seule.", "extraExample": {"text": "بَطْنِي", "translation": "mon ventre", "transliteration": "baTnî"}, "pool": "lesson", "lessonId": "ar.l10", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e18', 'ar', 'ar.l10', 'ar.v.qalb', array['ar.v.qalb','ar.g10.sukun']::text[], 'translation', 'lesson', 'قَلْب', array['le cœur','cœur','un cœur','le coeur','coeur','un coeur']::text[], 'قَلْب se lit qalb : le cœur.', 2, '{"id": "ar.l10.e18", "unitIds": ["ar.v.qalb", "ar.g10.sukun"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "قَلْب", "promptLanguage": "ar", "answer": "le cœur", "acceptedAnswers": ["le cœur", "cœur", "un cœur", "le coeur", "coeur", "un coeur"], "explanation": "قَلْب se lit qalb : le cœur.", "tip": "Qalb avec un ق : le cœur ; kalb avec un ك : le chien.", "extraExample": {"text": "قَلْبِي", "translation": "mon cœur", "transliteration": "qalbî"}, "errorPatterns": [{"equals": "le chien", "category": "word_confusion", "feedback": "Le chien, c''est كَلْب (kalb), avec un ك. Ici c''est un ق : qalb, le cœur."}, {"equals": "chien", "category": "word_confusion", "feedback": "Le chien, c''est كَلْب (kalb), avec un ك. Ici c''est un ق : qalb, le cœur."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e19', 'ar', 'ar.l10', 'ar.v.bint', array['ar.v.bint','ar.g10.sukun']::text[], 'translation', 'lesson', 'بِنْت', array['fille','une fille','la fille','jeune fille','une jeune fille','la jeune fille']::text[], 'بِنْت se lit bint : une fille, ou la fille de quelqu''un.', 2, '{"id": "ar.l10.e19", "unitIds": ["ar.v.bint", "ar.g10.sukun"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "بِنْت", "promptLanguage": "ar", "answer": "fille", "acceptedAnswers": ["fille", "une fille", "la fille", "jeune fille", "une jeune fille", "la jeune fille"], "explanation": "بِنْت se lit bint : une fille, ou la fille de quelqu''un.", "tip": "Bint, la fille ; ibn, le fils.", "extraExample": {"text": "بِنْتِي", "translation": "ma fille", "transliteration": "bintî"}, "errorPatterns": [{"equals": "fils", "category": "vocabulary", "feedback": "Le fils, c''est اِبْن (ibn). بِنْت (bint), c''est la fille."}, {"equals": "le fils", "category": "vocabulary", "feedback": "Le fils, c''est اِبْن (ibn). بِنْت (bint), c''est la fille."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e20', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun','ar.v.batn']::text[], 'free_answer', 'lesson', 'Comment se lit بَطْن (le ventre) ?', array['baTn']::text[], 'Fatha sur le ب (ba), sukun sur le ط, puis ن : baTn. En lettres latines, le T majuscule note le ط.', 3, '{"id": "ar.l10.e20", "unitIds": ["ar.g10.sukun", "ar.v.batn"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit بَطْن (le ventre) ?", "promptLanguage": "fr", "answer": "baTn", "acceptedAnswers": ["baTn"], "explanation": "Fatha sur le ب (ba), sukun sur le ط, puis ن : baTn. En lettres latines, le T majuscule note le ط.", "tip": "Pas de voyelle après une lettre avec sukun.", "extraExample": {"text": "بُطُون", "translation": "ventres", "transliteration": "buTûn"}, "errorPatterns": [{"equals": "batan", "category": "spelling", "feedback": "Le ط porte un sukun : pas de voyelle après lui. On lit baTn."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e21', 'ar', 'ar.l10', 'ar.g10.sukun', array['ar.g10.sukun']::text[], 'free_answer', 'lesson', 'Comment se lit قُلْتُ (j''ai dit) ?', array['qultu','qoultou']::text[], 'Damma sur le ق (qu), sukun sur le ل, damma sur le ت : qul-tu.', 4, '{"id": "ar.l10.e21", "unitIds": ["ar.g10.sukun"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit قُلْتُ (j''ai dit) ?", "promptLanguage": "fr", "answer": "qultu", "acceptedAnswers": ["qultu", "qoultou"], "explanation": "Damma sur le ق (qu), sukun sur le ل, damma sur le ت : qul-tu.", "tip": "Repère d''abord le sukun, puis coupe la syllabe juste après.", "extraExample": {"text": "كَتَبْتُ", "translation": "j''ai écrit", "transliteration": "katabtu"}, "errorPatterns": [{"equals": "qulutu", "category": "spelling", "feedback": "Le ل porte un sukun : on ne met pas de voyelle après lui. qul-tu."}, {"equals": "qult", "category": "spelling", "feedback": "Le ت final porte une damma : il se prononce tu. On lit qultu."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e22', 'ar', 'ar.l10', 'ar.g09.short_vowels', array['ar.g09.short_vowels']::text[], 'mcq', 'lesson', 'Comment se lit سَمِعَ (il a entendu) ?', array['sami3a']::text[], 'Fatha sur le س (sa), kasra sous le م (mi), fatha sur le ع (3a) : sa-mi-3a.', 3, '{"id": "ar.l10.e22", "unitIds": ["ar.g09.short_vowels"], "type": "mcq", "difficulty": 3, "instruction": "Révision : choisis la bonne lecture.", "prompt": "Comment se lit سَمِعَ (il a entendu) ?", "promptLanguage": "fr", "options": ["sami3a", "sama3a", "sumi3a", "sami3"], "answer": "sami3a", "acceptedAnswers": ["sami3a"], "explanation": "Fatha sur le س (sa), kasra sous le م (mi), fatha sur le ع (3a) : sa-mi-3a.", "tip": "Une lettre, un signe : lis-les dans l''ordre.", "extraExample": {"text": "فَهِمَ", "translation": "il a compris", "transliteration": "fahima"}, "errorPatterns": [{"equals": "sami3", "category": "word_confusion", "feedback": "Le ع final porte une fatha : on le prononce 3a. sami3a."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e01', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.madd']::text[], 'mcq', 'lesson', 'Comment se lit بَا ?', array['bâ']::text[], 'La fatha sur le ب donne a, et le ا qui la suit allonge ce son : c''est le madd (مَدّ). On tient le a deux fois plus longtemps : bâ.', 1, '{"id": "ar.l11.e01", "unitIds": ["ar.g11.long_vowels", "ar.v.madd"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit بَا ?", "promptLanguage": "fr", "options": ["bâ", "ba", "bi", "bû"], "answer": "bâ", "acceptedAnswers": ["bâ"], "hint": "Regarde la lettre qui suit la fatha.", "explanation": "La fatha sur le ب donne a, et le ا qui la suit allonge ce son : c''est le madd (مَدّ). On tient le a deux fois plus longtemps : bâ.", "tip": "Fatha + ا = â : le a s''étire.", "extraExample": {"text": "بَاب", "translation": "porte", "transliteration": "bâb"}, "errorPatterns": [{"equals": "ba", "category": "word_confusion", "feedback": "Sans le ا, la voyelle resterait brève : بَ = ba. Ici le ا allonge le son : bâ."}, {"equals": "bi", "category": "word_confusion", "feedback": "bi demande une kasra (trait sous la lettre). Ici c''est une fatha suivie de ا : bâ."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e02', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels']::text[], 'mcq', 'lesson', 'Comment se lit بِي ?', array['bî']::text[], 'La kasra est suivie d''un ي sans signe : le i s''allonge, on lit bî. Ici le ي n''est pas une consonne, c''est le prolongement de la kasra.', 1, '{"id": "ar.l11.e02", "unitIds": ["ar.g11.long_vowels"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit بِي ?", "promptLanguage": "fr", "options": ["bî", "bi", "bay", "bû"], "answer": "bî", "acceptedAnswers": ["bî"], "explanation": "La kasra est suivie d''un ي sans signe : le i s''allonge, on lit bî. Ici le ي n''est pas une consonne, c''est le prolongement de la kasra.", "tip": "Kasra + ي = î.", "extraExample": {"text": "فِي", "translation": "dans, en", "transliteration": "fî"}, "errorPatterns": [{"equals": "bi", "category": "word_confusion", "feedback": "Sans le ي, la voyelle serait brève : بِ = bi. Avec le ي, elle est longue : bî."}, {"equals": "bay", "category": "word_confusion", "feedback": "Pour la diphtongue ay, le ي porterait un sukun après une fatha (بَيْ). Ici : kasra + ي sans signe = î."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e03', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels']::text[], 'match', 'lesson', 'Voyelles longues et diphtongues', '{}'::text[], 'Fatha + ا = â, kasra + ي = î, damma + و = û : ce sont les voyelles longues. Quand le ي ou le و porte un sukun après une fatha, on entend une diphtongue : ay, aw.', 2, '{"id": "ar.l11.e03", "unitIds": ["ar.g11.long_vowels"], "type": "match", "difficulty": 2, "instruction": "Associe chaque groupe de signes à sa lecture.", "prompt": "Voyelles longues et diphtongues", "promptLanguage": "fr", "pairs": [{"left": "ـَا", "right": "â"}, {"left": "ـِي", "right": "î"}, {"left": "ـُو", "right": "û"}, {"left": "ـَيْ", "right": "ay"}, {"left": "ـَوْ", "right": "aw"}], "answer": "ـَا = â ; ـِي = î ; ـُو = û ; ـَيْ = ay ; ـَوْ = aw", "acceptedAnswers": [], "explanation": "Fatha + ا = â, kasra + ي = î, damma + و = û : ce sont les voyelles longues. Quand le ي ou le و porte un sukun après une fatha, on entend une diphtongue : ay, aw.", "tip": "Lettre nue après sa voyelle = voyelle longue ; lettre avec sukun = ay ou aw.", "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e04', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.sadiq']::text[], 'mcq', 'lesson', 'Comment se lit صَدِيق (ami) ?', array['Sadîq']::text[], 'Fatha sur le ص (Sa), kasra sous le د suivie d''un ي : le i est long, dîq. Le ق final n''a pas de signe : Sa-dîq.', 2, '{"id": "ar.l11.e04", "unitIds": ["ar.g11.long_vowels", "ar.v.sadiq"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit صَدِيق (ami) ?", "promptLanguage": "fr", "options": ["Sadîq", "Sadiq", "Sadâq", "Sadûq"], "answer": "Sadîq", "acceptedAnswers": ["Sadîq"], "explanation": "Fatha sur le ص (Sa), kasra sous le د suivie d''un ي : le i est long, dîq. Le ق final n''a pas de signe : Sa-dîq.", "tip": "Kasra + ي : on tient le i.", "extraExample": {"text": "جَمِيل", "translation": "beau", "transliteration": "djamîl"}, "errorPatterns": [{"equals": "Sadiq", "category": "word_confusion", "feedback": "Le ي après la kasra allonge le i : Sadîq, pas Sadiq."}, {"equals": "Sadâq", "category": "word_confusion", "feedback": "Sous le د, c''est une kasra (trait sous la lettre) : di, pas da."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e05', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.djar']::text[], 'mcq', 'lesson', 'Comment se lit جَار (voisin) ?', array['djâr']::text[], 'La fatha sur le ج est suivie d''un ا : le a est long. Le ر final n''a pas de signe : on lit djâr, avec un â tenu.', 2, '{"id": "ar.l11.e05", "unitIds": ["ar.g11.long_vowels", "ar.v.djar"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit جَار (voisin) ?", "promptLanguage": "fr", "options": ["djâr", "djar", "djîr", "djûr"], "answer": "djâr", "acceptedAnswers": ["djâr"], "explanation": "La fatha sur le ج est suivie d''un ا : le a est long. Le ر final n''a pas de signe : on lit djâr, avec un â tenu.", "tip": "Un ا juste après une fatha = a long.", "extraExample": {"text": "دَار", "translation": "maison", "transliteration": "dâr"}, "errorPatterns": [{"equals": "djar", "category": "word_confusion", "feedback": "Le ا allonge la fatha : djâr. Sans lui, on lirait djar."}, {"equals": "djîr", "category": "word_confusion", "feedback": "Un î long s''écrit avec une kasra et un ي. Ici c''est une fatha et un ا : â."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e06', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.ayn_oeil']::text[], 'mcq', 'lesson', 'Comment se lit عَيْن (œil) ?', array['3ayn']::text[], 'Le ي porte un sukun après une fatha : ce n''est pas un î long mais une diphtongue, ay. On lit 3ayn (comme dans « ail »).', 2, '{"id": "ar.l11.e06", "unitIds": ["ar.g11.long_vowels", "ar.v.ayn_oeil"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit عَيْن (œil) ?", "promptLanguage": "fr", "options": ["3ayn", "3în", "3ân", "3awn"], "answer": "3ayn", "acceptedAnswers": ["3ayn"], "explanation": "Le ي porte un sukun après une fatha : ce n''est pas un î long mais une diphtongue, ay. On lit 3ayn (comme dans « ail »).", "tip": "Fatha + ي avec sukun = ay.", "extraExample": {"text": "بَيْت", "translation": "maison", "transliteration": "bayt"}, "errorPatterns": [{"equals": "3în", "category": "word_confusion", "feedback": "Un î long s''écrirait kasra + ي sans signe (ـِي). Ici le ي porte un sukun après une fatha : ay."}, {"equals": "3awn", "category": "spelling", "feedback": "La lettre est un ي, pas un و : on entend ay et non aw."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e07', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.zawdj']::text[], 'mcq', 'lesson', 'Comment se lit زَوْج (mari) ?', array['zawdj']::text[], 'Le و porte un sukun après une fatha : c''est la diphtongue aw. Puis le ج : zawdj. Un û long s''écrirait damma + و sans signe.', 2, '{"id": "ar.l11.e07", "unitIds": ["ar.g11.long_vowels", "ar.v.zawdj"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit زَوْج (mari) ?", "promptLanguage": "fr", "options": ["zawdj", "zûdj", "zâdj", "zawadj"], "answer": "zawdj", "acceptedAnswers": ["zawdj"], "explanation": "Le و porte un sukun après une fatha : c''est la diphtongue aw. Puis le ج : zawdj. Un û long s''écrirait damma + و sans signe.", "tip": "Fatha + و avec sukun = aw.", "extraExample": {"text": "يَوْم", "translation": "jour", "transliteration": "yawm"}, "errorPatterns": [{"equals": "zûdj", "category": "word_confusion", "feedback": "Pour un û long, il faudrait une damma sur le ز. Ici c''est une fatha et un sukun sur le و : aw."}, {"equals": "zawadj", "category": "spelling", "feedback": "Le و porte un sukun : on n''ajoute aucune voyelle après lui."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e08', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.adjuz']::text[], 'mcq', 'lesson', 'Comment se lit عَجُوز (personne âgée) ?', array['3adjûz']::text[], 'Damma sur le ج, suivie d''un و sans signe : le u est long, û. Le ز final n''a pas de signe : 3a-djûz.', 3, '{"id": "ar.l11.e08", "unitIds": ["ar.g11.long_vowels", "ar.v.adjuz"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit عَجُوز (personne âgée) ?", "promptLanguage": "fr", "options": ["3adjûz", "3adjuz", "3adjîz", "3adjâz"], "answer": "3adjûz", "acceptedAnswers": ["3adjûz"], "explanation": "Damma sur le ج, suivie d''un و sans signe : le u est long, û. Le ز final n''a pas de signe : 3a-djûz.", "tip": "Damma + و : le « ou » s''étire.", "extraExample": {"text": "نُور", "translation": "lumière", "transliteration": "nûr"}, "errorPatterns": [{"equals": "3adjuz", "category": "word_confusion", "feedback": "Le و après la damma allonge le son : 3adjûz."}, {"equals": "3adjîz", "category": "word_confusion", "feedback": "Après la damma, c''est un و (û) et non un ي (î)."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e09', 'ar', 'ar.l11', 'ar.v.yad', array['ar.v.yad','ar.g11.long_vowels']::text[], 'mcq', 'lesson', 'Dans quel mot le ي est-il une voyelle longue î ?', array['صَدِيق']::text[], 'Dans صَدِيق, le ي suit une kasra : c''est un î long. Dans عَيْن, il porte un sukun après une fatha : diphtongue ay. Dans يَد, il porte une fatha : c''est la consonne y.', 3, '{"id": "ar.l11.e09", "unitIds": ["ar.v.yad", "ar.g11.long_vowels"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans quel mot le ي est-il une voyelle longue î ?", "promptLanguage": "fr", "options": ["صَدِيق", "عَيْن", "يَد"], "answer": "صَدِيق", "acceptedAnswers": ["صَدِيق"], "explanation": "Dans صَدِيق, le ي suit une kasra : c''est un î long. Dans عَيْن, il porte un sukun après une fatha : diphtongue ay. Dans يَد, il porte une fatha : c''est la consonne y.", "tip": "Le ي peut être une voyelle (î), une diphtongue (ay) ou une consonne (y).", "extraExample": {"text": "يَمِين", "translation": "droite", "transliteration": "yamîn"}, "errorPatterns": [{"equals": "عَيْن", "category": "word_confusion", "feedback": "Dans عَيْن, le ي porte un sukun : diphtongue ay, pas î."}, {"equals": "يَد", "category": "word_confusion", "feedback": "Dans يَد, le ي porte une fatha : c''est la consonne y, il ne prolonge aucune voyelle."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e10', 'ar', 'ar.l11', 'ar.g09.short_vowels', array['ar.g09.short_vowels','ar.v.radjul','ar.v.katif','ar.v.unuq','ar.v.dhira']::text[], 'mcq', 'lesson', 'Lequel de ces mots contient une voyelle longue ?', array['ذِرَاع']::text[], 'Dans ذِرَاع, la fatha du ر est suivie d''un ا : â long. رَجُل (ra-djul), كَتِف (ka-tif) et عُنُق (3u-nuq) n''ont que des voyelles brèves.', 3, '{"id": "ar.l11.e10", "unitIds": ["ar.g09.short_vowels", "ar.v.radjul", "ar.v.katif", "ar.v.unuq", "ar.v.dhira"], "type": "mcq", "difficulty": 3, "instruction": "Révision : choisis la bonne réponse.", "prompt": "Lequel de ces mots contient une voyelle longue ?", "promptLanguage": "fr", "options": ["رَجُل", "كَتِف", "عُنُق", "ذِرَاع"], "answer": "ذِرَاع", "acceptedAnswers": ["ذِرَاع"], "explanation": "Dans ذِرَاع, la fatha du ر est suivie d''un ا : â long. رَجُل (ra-djul), كَتِف (ka-tif) et عُنُق (3u-nuq) n''ont que des voyelles brèves.", "tip": "Cherche un ا, un و ou un ي sans signe juste après une voyelle.", "extraExample": {"text": "كِتَاب", "translation": "livre", "transliteration": "kitâb"}, "errorPatterns": [{"equals": "رَجُل", "category": "word_confusion", "feedback": "رَجُل n''a que des voyelles brèves : fatha sur le ر, damma sur le ج. Aucun ا, و ou ي ne les prolonge."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e11', 'ar', 'ar.l11', 'ar.v.kitab', array['ar.v.kitab','ar.g11.long_vowels']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit « kitâb » (livre) ?', array['كِتَاب']::text[], 'كِتَاب = ki-tâb : kasra sous le ك, puis un ا après la fatha du ت. كُتُب se lit kutub (des livres), كَتَبَ kataba (il a écrit) et كَاتِب kâtib (écrivain).', 2, '{"id": "ar.l11.e11", "unitIds": ["ar.v.kitab", "ar.g11.long_vowels"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se lit « kitâb » (livre) ?", "promptLanguage": "fr", "options": ["كِتَاب", "كُتُب", "كَتَبَ", "كَاتِب"], "answer": "كِتَاب", "acceptedAnswers": ["كِتَاب"], "explanation": "كِتَاب = ki-tâb : kasra sous le ك, puis un ا après la fatha du ت. كُتُب se lit kutub (des livres), كَتَبَ kataba (il a écrit) et كَاتِب kâtib (écrivain).", "tip": "Mêmes consonnes ك ت ب, mais les voyelles et le ا changent tout.", "extraExample": {"text": "مَكْتَب", "translation": "bureau", "transliteration": "maktab"}, "errorPatterns": [{"equals": "كُتُب", "category": "word_confusion", "feedback": "كُتُب se lit kutub (« des livres ») : deux dammas et aucun ا."}, {"equals": "كَتَبَ", "category": "word_confusion", "feedback": "كَتَبَ se lit kataba (« il a écrit ») : trois fathas et pas de ا."}, {"equals": "كَاتِب", "category": "word_confusion", "feedback": "كَاتِب se lit kâtib (« écrivain ») : le ا est juste après le ك, pas après le ت."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e12', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.khal','ar.v.lisan','ar.v.dhira','ar.v.adjuz','ar.v.sadiq']::text[], 'match', 'lesson', 'Lis chaque mot en tenant les voyelles longues.', '{}'::text[], 'Dans chaque mot, un ا, un و ou un ي prolonge la voyelle d''avant : khâl, lisân, dhirâ3, 3adjûz, Sadîq.', 2, '{"id": "ar.l11.e12", "unitIds": ["ar.g11.long_vowels", "ar.v.khal", "ar.v.lisan", "ar.v.dhira", "ar.v.adjuz", "ar.v.sadiq"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lis chaque mot en tenant les voyelles longues.", "promptLanguage": "fr", "pairs": [{"left": "خَال", "right": "khâl"}, {"left": "لِسَان", "right": "lisân"}, {"left": "ذِرَاع", "right": "dhirâ3"}, {"left": "عَجُوز", "right": "3adjûz"}, {"left": "صَدِيق", "right": "Sadîq"}], "answer": "خَال = khâl ; لِسَان = lisân ; ذِرَاع = dhirâ3 ; عَجُوز = 3adjûz ; صَدِيق = Sadîq", "acceptedAnswers": [], "explanation": "Dans chaque mot, un ا, un و ou un ي prolonge la voyelle d''avant : khâl, lisân, dhirâ3, 3adjûz, Sadîq.", "tip": "Marque un temps d''arrêt sur la voyelle longue : elle dure le double d''une brève.", "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e13', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.sadiq','ar.v.djar','ar.v.zawdj','ar.v.lisan','ar.v.dhira']::text[], 'match', 'lesson', 'Amis, voisins, langue et bras', '{}'::text[], 'صَدِيق (Sadîq) = l''ami, جَار (djâr) = le voisin, زَوْج (zawdj) = le mari, لِسَان (lisân) = la langue, ذِرَاع (dhirâ3) = le bras.', 2, '{"id": "ar.l11.e13", "unitIds": ["ar.g11.long_vowels", "ar.v.sadiq", "ar.v.djar", "ar.v.zawdj", "ar.v.lisan", "ar.v.dhira"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Amis, voisins, langue et bras", "promptLanguage": "fr", "pairs": [{"left": "صَدِيق", "right": "l''ami"}, {"left": "جَار", "right": "le voisin"}, {"left": "زَوْج", "right": "le mari"}, {"left": "لِسَان", "right": "la langue"}, {"left": "ذِرَاع", "right": "le bras"}], "answer": "صَدِيق = l''ami ; جَار = le voisin ; زَوْج = le mari ; لِسَان = la langue ; ذِرَاع = le bras", "acceptedAnswers": [], "explanation": "صَدِيق (Sadîq) = l''ami, جَار (djâr) = le voisin, زَوْج (zawdj) = le mari, لِسَان (lisân) = la langue, ذِرَاع (dhirâ3) = le bras.", "tip": "Lis le mot à voix haute avant de chercher son sens.", "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e14', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.lisan']::text[], 'fill_blank', 'lesson', 'Dans لِسَان (lisân), le â long s''écrit avec la lettre ___.', array['ا']::text[], 'Le س porte une fatha, suivie d''un ا : sâ. Le و prolonge une damma et le ي une kasra.', 2, '{"id": "ar.l11.e14", "unitIds": ["ar.g11.long_vowels", "ar.v.lisan"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne lettre.", "prompt": "Dans لِسَان (lisân), le â long s''écrit avec la lettre ___.", "promptLanguage": "fr", "options": ["ا", "و", "ي"], "answer": "ا", "acceptedAnswers": ["ا"], "explanation": "Le س porte une fatha, suivie d''un ا : sâ. Le و prolonge une damma et le ي une kasra.", "tip": "Fatha → ا, damma → و, kasra → ي.", "extraExample": {"text": "سَلَام", "translation": "paix", "transliteration": "salâm"}, "errorPatterns": [{"equals": "و", "category": "word_confusion", "feedback": "Le و prolonge une damma (û). Ici la voyelle du س est une fatha."}, {"equals": "ي", "category": "word_confusion", "feedback": "Le ي prolonge une kasra (î). Ici la voyelle du س est une fatha."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e15', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.ayn_oeil']::text[], 'fill_blank', 'lesson', 'Dans عَيْن, le ي porte un sukun : on lit la diphtongue « ___ ».', array['ay']::text[], 'Fatha + ي avec sukun donne ay (comme dans « ail »). Le î long, lui, s''écrit avec une kasra et un ي sans signe.', 2, '{"id": "ar.l11.e15", "unitIds": ["ar.g11.long_vowels", "ar.v.ayn_oeil"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne lecture.", "prompt": "Dans عَيْن, le ي porte un sukun : on lit la diphtongue « ___ ».", "promptLanguage": "fr", "options": ["ay", "î", "aw", "ây"], "answer": "ay", "acceptedAnswers": ["ay"], "explanation": "Fatha + ي avec sukun donne ay (comme dans « ail »). Le î long, lui, s''écrit avec une kasra et un ي sans signe.", "tip": "Sukun sur le ي ou le و : on entend y ou w, pas une voyelle longue.", "extraExample": {"text": "لَيْل", "translation": "nuit", "transliteration": "layl"}, "errorPatterns": [{"equals": "î", "category": "word_confusion", "feedback": "Le î long s''écrit kasra + ي sans signe. Ici le ي porte un sukun après une fatha : ay."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e16', 'ar', 'ar.l11', 'ar.g10.sukun', array['ar.g10.sukun','ar.v.zawdj']::text[], 'fill_blank', 'lesson', 'Dans زَوْج, le و porte un ___ : c''est pour cela qu''on lit aw et non û.', array['sukun']::text[], 'Un sukun sur le و (ou le ي) après une fatha forme une diphtongue. Sans sukun et après une damma, on aurait un û long.', 2, '{"id": "ar.l11.e16", "unitIds": ["ar.g10.sukun", "ar.v.zawdj"], "type": "fill_blank", "difficulty": 2, "instruction": "Révision : complète avec le nom du signe.", "prompt": "Dans زَوْج, le و porte un ___ : c''est pour cela qu''on lit aw et non û.", "promptLanguage": "fr", "options": ["sukun", "damma", "fatha", "shadda"], "answer": "sukun", "acceptedAnswers": ["sukun"], "explanation": "Un sukun sur le و (ou le ي) après une fatha forme une diphtongue. Sans sukun et après une damma, on aurait un û long.", "tip": "Voyelle longue = lettre nue ; diphtongue = lettre avec sukun.", "extraExample": {"text": "يَوْم", "translation": "jour", "transliteration": "yawm"}, "errorPatterns": [{"equals": "damma", "category": "word_confusion", "feedback": "Une damma sur le و ferait lire wu. Ici, le petit rond est un sukun : il n''y a pas de voyelle après le w."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e17', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.dhira']::text[], 'reorder', 'lesson', 'Écris « dhirâ3 » (bras).', array['ذِ رَا ع']::text[], 'Dhi-râ3 : ذ avec kasra, puis ر avec fatha et ا (â long), puis le ع final sans signe.', 2, '{"id": "ar.l11.e17", "unitIds": ["ar.g11.long_vowels", "ar.v.dhira"], "type": "reorder", "difficulty": 2, "instruction": "Touche les syllabes dans l''ordre de lecture (la première d''abord).", "prompt": "Écris « dhirâ3 » (bras).", "promptLanguage": "fr", "tokens": ["ع", "رَا", "ذِ"], "answer": "ذِ رَا ع", "acceptedAnswers": ["ذِ رَا ع"], "explanation": "Dhi-râ3 : ذ avec kasra, puis ر avec fatha et ا (â long), puis le ع final sans signe.", "tip": "Le ا ne se lit pas seul : il allonge la syllabe رَا.", "extraExample": {"text": "ذِرَاعِي", "translation": "mon bras", "transliteration": "dhirâ3î"}, "pool": "lesson", "lessonId": "ar.l11", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e18', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.sadiq']::text[], 'reorder', 'lesson', 'Écris « Sadîq » (ami).', array['صَ دِي ق']::text[], 'Sa-dîq : ص avec fatha, puis د avec kasra et ي (î long), puis le ق final.', 3, '{"id": "ar.l11.e18", "unitIds": ["ar.g11.long_vowels", "ar.v.sadiq"], "type": "reorder", "difficulty": 3, "instruction": "Touche les syllabes dans l''ordre de lecture (la première d''abord).", "prompt": "Écris « Sadîq » (ami).", "promptLanguage": "fr", "tokens": ["ق", "دِي", "صَ"], "answer": "صَ دِي ق", "acceptedAnswers": ["صَ دِي ق"], "explanation": "Sa-dîq : ص avec fatha, puis د avec kasra et ي (î long), puis le ق final.", "tip": "Kasra + ي forment ensemble la syllabe longue دِي.", "extraExample": {"text": "صَدِيقِي", "translation": "mon ami", "transliteration": "Sadîqî"}, "pool": "lesson", "lessonId": "ar.l11", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e19', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.khal']::text[], 'translation', 'lesson', 'خَال', array['oncle','l''oncle','un oncle','oncle maternel','l''oncle maternel','un oncle maternel','oncle (frère de la mère)']::text[], 'خَال (khâl) est le frère de la mère, l''oncle maternel. Le frère du père a un autre mot.', 2, '{"id": "ar.l11.e19", "unitIds": ["ar.g11.long_vowels", "ar.v.khal"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "خَال", "promptLanguage": "ar", "answer": "oncle", "acceptedAnswers": ["oncle", "l''oncle", "un oncle", "oncle maternel", "l''oncle maternel", "un oncle maternel", "oncle (frère de la mère)"], "explanation": "خَال (khâl) est le frère de la mère, l''oncle maternel. Le frère du père a un autre mot.", "tip": "Khâl : l''oncle maternel, avec un â long.", "extraExample": {"text": "خَالِي", "translation": "mon oncle", "transliteration": "khâlî"}, "errorPatterns": [{"equals": "oncle paternel", "category": "vocabulary", "feedback": "L''oncle paternel n''est pas خَال : khâl est le frère de ta mère."}, {"equals": "tante", "category": "vocabulary", "feedback": "Une tante maternelle s''écrit خَالَة (khâla). خَال est un homme : l''oncle."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e20', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.djar']::text[], 'translation', 'lesson', 'جَار', array['voisin','le voisin','un voisin']::text[], 'جَار (djâr) veut dire « le voisin ».', 2, '{"id": "ar.l11.e20", "unitIds": ["ar.g11.long_vowels", "ar.v.djar"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "جَار", "promptLanguage": "ar", "answer": "voisin", "acceptedAnswers": ["voisin", "le voisin", "un voisin"], "explanation": "جَار (djâr) veut dire « le voisin ».", "tip": "Djâr, le voisin : le â long est au milieu.", "extraExample": {"text": "جَارُنَا", "translation": "notre voisin", "transliteration": "djârunâ"}, "errorPatterns": [{"equals": "ami", "category": "vocabulary", "feedback": "L''ami, c''est صَدِيق (Sadîq). جَار (djâr), c''est le voisin."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e21', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.lisan']::text[], 'free_answer', 'lesson', 'Comment se lit لِسَان (langue) ?', array['lisân','lisan','lisaan']::text[], 'Kasra sous le ل (li), fatha sur le س suivie de ا (sâ, long), puis ن final : li-sân.', 3, '{"id": "ar.l11.e21", "unitIds": ["ar.g11.long_vowels", "ar.v.lisan"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit لِسَان (langue) ?", "promptLanguage": "fr", "answer": "lisân", "acceptedAnswers": ["lisân", "lisan", "lisaan"], "hint": "Deux syllabes : li-sân.", "explanation": "Kasra sous le ل (li), fatha sur le س suivie de ا (sâ, long), puis ن final : li-sân.", "tip": "Fatha + ا = â : le a de la dernière syllabe est long.", "extraExample": {"text": "لِسَانِي", "translation": "ma langue", "transliteration": "lisânî"}, "errorPatterns": [{"equals": "lisin", "category": "word_confusion", "feedback": "Il n''y a pas de ي : la voyelle longue est â (ا après la fatha), pas î."}, {"equals": "lasan", "category": "word_confusion", "feedback": "Sous le ل, c''est une kasra (trait sous la lettre) : li, pas la."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e22', 'ar', 'ar.l11', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.dhira']::text[], 'free_answer', 'lesson', 'Comment se lit ذِرَاع (bras) ?', array['dhirâ3','dhira3','dhiraa3']::text[], 'Kasra sous le ذ (dhi), fatha sur le ر suivie de ا (râ, long), puis ع final : dhi-râ3.', 4, '{"id": "ar.l11.e22", "unitIds": ["ar.g11.long_vowels", "ar.v.dhira"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit ذِرَاع (bras) ?", "promptLanguage": "fr", "answer": "dhirâ3", "acceptedAnswers": ["dhirâ3", "dhira3", "dhiraa3"], "hint": "Le ذ se note dh.", "explanation": "Kasra sous le ذ (dhi), fatha sur le ر suivie de ا (râ, long), puis ع final : dhi-râ3.", "tip": "Le ذ se note dh, le ع se note 3 : dhirâ3.", "extraExample": {"text": "ذِرَاعَانِ", "translation": "deux bras", "transliteration": "dhirâ3âni"}, "errorPatterns": [{"equals": "dharâ3", "category": "word_confusion", "feedback": "Sous le ذ, c''est une kasra (trait sous la lettre) : dhi, pas dha."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e01', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.shadda']::text[], 'mcq', 'lesson', 'Quel signe indique qu''une lettre est doublée ?', array['la shadda (ـّ)']::text[], 'La shadda (شَدَّة), petit « w » posé au-dessus de la lettre, double la consonne : on la prononce deux fois. Le sukun, petit rond, supprime au contraire la voyelle.', 1, '{"id": "ar.l12.e01", "unitIds": ["ar.g12.shadda", "ar.v.shadda"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel signe indique qu''une lettre est doublée ?", "promptLanguage": "fr", "options": ["la shadda (ـّ)", "le sukun (ـْ)", "la fatha (ـَ)", "la kasra (ـِ)"], "answer": "la shadda (ـّ)", "acceptedAnswers": ["la shadda (ـّ)"], "explanation": "La shadda (شَدَّة), petit « w » posé au-dessus de la lettre, double la consonne : on la prononce deux fois. Le sukun, petit rond, supprime au contraire la voyelle.", "tip": "Shadda = petit w = lettre en double.", "extraExample": {"text": "جَدّ", "translation": "grand-père", "transliteration": "djadd"}, "errorPatterns": [{"equals": "le sukun (ـْ)", "category": "word_confusion", "feedback": "Le sukun (petit rond) enlève la voyelle, il ne double rien. La lettre doublée, c''est la shadda, petit w."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e02', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.g10.sukun']::text[], 'mcq', 'lesson', 'Lequel de ces mots contient une lettre doublée ?', array['جَدَّة']::text[], 'Dans جَدَّة, le د porte une shadda : il est doublé (djad-da). بِنْت, قَلْب et وَجْه n''ont qu''un sukun, un petit rond : leur lettre n''est pas doublée.', 1, '{"id": "ar.l12.e02", "unitIds": ["ar.g12.shadda", "ar.g10.sukun"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots contient une lettre doublée ?", "promptLanguage": "fr", "options": ["جَدَّة", "بِنْت", "قَلْب", "وَجْه"], "answer": "جَدَّة", "acceptedAnswers": ["جَدَّة"], "explanation": "Dans جَدَّة, le د porte une shadda : il est doublé (djad-da). بِنْت, قَلْب et وَجْه n''ont qu''un sukun, un petit rond : leur lettre n''est pas doublée.", "tip": "Petit w = doublé ; petit rond = pas de voyelle.", "extraExample": {"text": "حُبّ", "translation": "amour", "transliteration": "7ubb"}, "errorPatterns": [{"equals": "بِنْت", "category": "word_confusion", "feedback": "Dans بِنْت, le petit rond sur le ن est un sukun : le ن n''est pas doublé."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e03', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.djadd']::text[], 'mcq', 'lesson', 'Comment se lit جَدّ (grand-père) ?', array['djadd']::text[], 'Fatha sur le ج (dja), puis le د porte une shadda : il est doublé et on l''entend deux fois. À la fin du mot, on lit djadd.', 1, '{"id": "ar.l12.e03", "unitIds": ["ar.g12.shadda", "ar.v.djadd"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit جَدّ (grand-père) ?", "promptLanguage": "fr", "options": ["djadd", "djad", "djâd", "djid"], "answer": "djadd", "acceptedAnswers": ["djadd"], "explanation": "Fatha sur le ج (dja), puis le د porte une shadda : il est doublé et on l''entend deux fois. À la fin du mot, on lit djadd.", "tip": "Shadda = on dit la lettre deux fois.", "extraExample": {"text": "كُلّ", "translation": "tout, chaque", "transliteration": "kull"}, "errorPatterns": [{"equals": "djad", "category": "word_confusion", "feedback": "Le د porte une shadda : il est doublé. Sans elle, on lirait djad."}, {"equals": "djâd", "category": "word_confusion", "feedback": "Il n''y a pas de ا dans ce mot : la voyelle reste brève. Le doublement vient de la shadda."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e04', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.djadda']::text[], 'mcq', 'lesson', 'Comment se lit جَدَّة (grand-mère) ?', array['djadda']::text[], 'Fatha sur le ج (dja), puis le د doublé par la shadda, avec une fatha : djad-da. Le ة final ne se prononce pas à la fin du mot isolé : on s''arrête sur le a.', 1, '{"id": "ar.l12.e04", "unitIds": ["ar.g12.shadda", "ar.v.djadda"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit جَدَّة (grand-mère) ?", "promptLanguage": "fr", "options": ["djadda", "djada", "djâda", "djidda"], "answer": "djadda", "acceptedAnswers": ["djadda"], "explanation": "Fatha sur le ج (dja), puis le د doublé par la shadda, avec une fatha : djad-da. Le ة final ne se prononce pas à la fin du mot isolé : on s''arrête sur le a.", "tip": "Djad-da : coupe entre les deux d.", "extraExample": {"text": "جَدَّتِي", "translation": "ma grand-mère", "transliteration": "djaddatî"}, "errorPatterns": [{"equals": "djada", "category": "word_confusion", "feedback": "La shadda double le د : djad-da. Sans elle, le mot serait trop court."}, {"equals": "djidda", "category": "word_confusion", "feedback": "Sous le د, il n''y a pas de kasra : c''est une fatha, donc da."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e05', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.djadd','ar.v.djadda','ar.v.amm','ar.v.amma','ar.v.khadd']::text[], 'match', 'lesson', 'Cinq mots avec une lettre doublée', '{}'::text[], 'Dans chaque mot, la lettre qui porte la shadda se prononce deux fois : djad-d, djad-da, 3am-m, 3am-ma, khad-d.', 2, '{"id": "ar.l12.e05", "unitIds": ["ar.g12.shadda", "ar.v.djadd", "ar.v.djadda", "ar.v.amm", "ar.v.amma", "ar.v.khadd"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Cinq mots avec une lettre doublée", "promptLanguage": "fr", "pairs": [{"left": "جَدّ", "right": "djadd"}, {"left": "جَدَّة", "right": "djadda"}, {"left": "عَمّ", "right": "3amm"}, {"left": "عَمَّة", "right": "3amma"}, {"left": "خَدّ", "right": "khadd"}], "answer": "جَدّ = djadd ; جَدَّة = djadda ; عَمّ = 3amm ; عَمَّة = 3amma ; خَدّ = khadd", "acceptedAnswers": [], "explanation": "Dans chaque mot, la lettre qui porte la shadda se prononce deux fois : djad-d, djad-da, 3am-m, 3am-ma, khad-d.", "tip": "Cherche le petit w : c''est lui qui double la lettre.", "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e06', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.sinn']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit « sinn » (dent) ?', array['سِنّ']::text[], 'Kasra sous le س (si), puis le ن avec shadda : sinn. سِنْ n''a qu''un sukun (sin), سُنّ se lit sunn et سَنّ se lit sann.', 2, '{"id": "ar.l12.e06", "unitIds": ["ar.g12.shadda", "ar.v.sinn"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se lit « sinn » (dent) ?", "promptLanguage": "fr", "options": ["سِنّ", "سِنْ", "سُنّ", "سَنّ"], "answer": "سِنّ", "acceptedAnswers": ["سِنّ"], "explanation": "Kasra sous le س (si), puis le ن avec shadda : sinn. سِنْ n''a qu''un sukun (sin), سُنّ se lit sunn et سَنّ se lit sann.", "tip": "Compte les n : deux n = une shadda.", "extraExample": {"text": "سِنُّهُ", "translation": "sa dent", "transliteration": "sinnuhu"}, "errorPatterns": [{"equals": "سِنْ", "category": "word_confusion", "feedback": "Le petit rond est un sukun, pas une shadda : le ن n''est pas doublé."}, {"equals": "سُنّ", "category": "word_confusion", "feedback": "Sous le س, il y a une kasra (trait sous la lettre) : si, pas su."}, {"equals": "سَنّ", "category": "word_confusion", "feedback": "Sous le س, il y a une kasra (trait sous la lettre) : si, pas sa."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e07', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.muallim']::text[], 'mcq', 'lesson', 'Dans مُعَلِّم (enseignant), quelle lettre porte la shadda ?', array['le ل']::text[], 'La shadda est sur le ل : on lit mu-3al-lim, avec le l doublé. Le ع porte seulement une fatha.', 2, '{"id": "ar.l12.e07", "unitIds": ["ar.g12.shadda", "ar.v.muallim"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans مُعَلِّم (enseignant), quelle lettre porte la shadda ?", "promptLanguage": "fr", "options": ["le ل", "le ع", "le premier م", "le dernier م"], "answer": "le ل", "acceptedAnswers": ["le ل"], "explanation": "La shadda est sur le ل : on lit mu-3al-lim, avec le l doublé. Le ع porte seulement une fatha.", "tip": "Cherche le petit w, juste au-dessus de la kasra.", "extraExample": {"text": "مُدَرِّس", "translation": "professeur", "transliteration": "mudarris"}, "errorPatterns": [{"equals": "le ع", "category": "word_confusion", "feedback": "Le ع porte une fatha (3a). La shadda est sur le ل : lli."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e08', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda']::text[], 'mcq', 'lesson', 'Quelle est la différence entre دَرَسَ (darasa) et دَرَّسَ (darrasa) ?', array['dans دَرَّسَ le ر est doublé : « il a enseigné »']::text[], 'La shadda double le ر : darrasa. Ce doublement change le sens : darasa = il a étudié, darrasa = il a enseigné.', 2, '{"id": "ar.l12.e08", "unitIds": ["ar.g12.shadda"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle est la différence entre دَرَسَ (darasa) et دَرَّسَ (darrasa) ?", "promptLanguage": "fr", "options": ["dans دَرَّسَ le ر est doublé : « il a enseigné »", "dans دَرَّسَ le د est doublé : « il a étudié »", "dans دَرَّسَ le ر a un sukun : « il a enseigné »", "il n''y a aucune différence de sens"], "answer": "dans دَرَّسَ le ر est doublé : « il a enseigné »", "acceptedAnswers": ["dans دَرَّسَ le ر est doublé : « il a enseigné »"], "explanation": "La shadda double le ر : darrasa. Ce doublement change le sens : darasa = il a étudié, darrasa = il a enseigné.", "tip": "Une shadda en plus peut changer le sens du mot.", "extraExample": {"text": "كَسَّرَ", "translation": "il a brisé en morceaux", "transliteration": "kassara"}, "errorPatterns": [{"equals": "il n''y a aucune différence de sens", "category": "word_confusion", "feedback": "La shadda change le sens : darasa = il a étudié, darrasa = il a enseigné."}, {"equals": "dans دَرَّسَ le د est doublé : « il a étudié »", "category": "word_confusion", "feedback": "Le د n''a pas de shadda : c''est le ر, au milieu, qui est doublé."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e09', 'ar', 'ar.l12', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.khal']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit « khâl » (oncle maternel) ?', array['خَال']::text[], 'خَال = khâl : fatha puis ا (â long), sans shadda. خَلّ se lit khall (le ل est doublé) et خَدّ se lit khadd (la joue).', 3, '{"id": "ar.l12.e09", "unitIds": ["ar.g11.long_vowels", "ar.v.khal"], "type": "mcq", "difficulty": 3, "instruction": "Révision : choisis le bon mot.", "prompt": "Lequel de ces mots se lit « khâl » (oncle maternel) ?", "promptLanguage": "fr", "options": ["خَال", "خَلّ", "خَدّ"], "answer": "خَال", "acceptedAnswers": ["خَال"], "explanation": "خَال = khâl : fatha puis ا (â long), sans shadda. خَلّ se lit khall (le ل est doublé) et خَدّ se lit khadd (la joue).", "tip": "Un ا allonge la voyelle, une shadda double la consonne : ne les confonds pas.", "extraExample": {"text": "خَالَة", "translation": "tante maternelle", "transliteration": "khâla"}, "errorPatterns": [{"equals": "خَلّ", "category": "word_confusion", "feedback": "خَلّ se lit khall (vinaigre) : le ل est doublé par la shadda et il n''y a pas de ا."}, {"equals": "خَدّ", "category": "word_confusion", "feedback": "خَدّ se lit khadd (joue) : le د est doublé et il n''y a pas de ا."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e10', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.muallim']::text[], 'mcq', 'lesson', 'Quel signe accompagne la shadda sur le ل de مُعَلِّم ?', array['une kasra']::text[], 'Le petit trait placé sous le ل est une kasra : la lettre doublée est suivie de i, on lit lli. D''où mu-3al-lim.', 3, '{"id": "ar.l12.e10", "unitIds": ["ar.g12.shadda", "ar.v.muallim"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel signe accompagne la shadda sur le ل de مُعَلِّم ?", "promptLanguage": "fr", "options": ["une kasra", "une fatha", "une damma", "un sukun"], "answer": "une kasra", "acceptedAnswers": ["une kasra"], "explanation": "Le petit trait placé sous le ل est une kasra : la lettre doublée est suivie de i, on lit lli. D''où mu-3al-lim.", "tip": "Lettre doublée + kasra : lis deux fois la consonne, puis le i.", "extraExample": {"text": "مُعَلِّمُونَ", "translation": "enseignants", "transliteration": "mu3allimûna"}, "errorPatterns": [{"equals": "une fatha", "category": "word_confusion", "feedback": "Avec une fatha, on lirait mu3allam. Ici le trait est sous le ل : kasra, donc lim."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e11', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.djadd','ar.v.djadda','ar.v.amm','ar.v.amma','ar.v.muallim']::text[], 'match', 'lesson', 'La famille et l''école', '{}'::text[], 'جَدّ (djadd) = grand-père, جَدَّة (djadda) = grand-mère, عَمّ (3amm) = oncle paternel, عَمَّة (3amma) = tante paternelle, مُعَلِّم (mu3allim) = enseignant.', 2, '{"id": "ar.l12.e11", "unitIds": ["ar.g12.shadda", "ar.v.djadd", "ar.v.djadda", "ar.v.amm", "ar.v.amma", "ar.v.muallim"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa traduction.", "prompt": "La famille et l''école", "promptLanguage": "fr", "pairs": [{"left": "جَدّ", "right": "le grand-père"}, {"left": "جَدَّة", "right": "la grand-mère"}, {"left": "عَمّ", "right": "l''oncle (frère du père)"}, {"left": "عَمَّة", "right": "la tante (sœur du père)"}, {"left": "مُعَلِّم", "right": "l''enseignant"}], "answer": "جَدّ = le grand-père ; جَدَّة = la grand-mère ; عَمّ = l''oncle (frère du père) ; عَمَّة = la tante (sœur du père) ; مُعَلِّم = l''enseignant", "acceptedAnswers": [], "explanation": "جَدّ (djadd) = grand-père, جَدَّة (djadda) = grand-mère, عَمّ (3amm) = oncle paternel, عَمَّة (3amma) = tante paternelle, مُعَلِّم (mu3allim) = enseignant.", "tip": "Le ة final marque souvent le féminin : djadd / djadda, 3amm / 3amma.", "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e12', 'ar', 'ar.l12', 'ar.v.qalb', array['ar.v.qalb','ar.g12.shadda','ar.v.sinn','ar.v.khadd','ar.v.wadjh','ar.v.ayn_oeil']::text[], 'match', 'lesson', 'Du visage au cœur', '{}'::text[], 'سِنّ (sinn) = la dent, خَدّ (khadd) = la joue, قَلْب (qalb) = le cœur, وَجْه (wadjh) = le visage, عَيْن (3ayn) = l''œil.', 3, '{"id": "ar.l12.e12", "unitIds": ["ar.v.qalb", "ar.g12.shadda", "ar.v.sinn", "ar.v.khadd", "ar.v.wadjh", "ar.v.ayn_oeil"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Du visage au cœur", "promptLanguage": "fr", "pairs": [{"left": "سِنّ", "right": "la dent"}, {"left": "خَدّ", "right": "la joue"}, {"left": "قَلْب", "right": "le cœur"}, {"left": "وَجْه", "right": "le visage"}, {"left": "عَيْن", "right": "l''œil"}], "answer": "سِنّ = la dent ; خَدّ = la joue ; قَلْب = le cœur ; وَجْه = le visage ; عَيْن = l''œil", "acceptedAnswers": [], "explanation": "سِنّ (sinn) = la dent, خَدّ (khadd) = la joue, قَلْب (qalb) = le cœur, وَجْه (wadjh) = le visage, عَيْن (3ayn) = l''œil.", "tip": "Une shadda se repère à son petit w : سِنّ et خَدّ en ont une, قَلْب et وَجْه n''en ont pas.", "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e13', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.djadda']::text[], 'fill_blank', 'lesson', 'Dans جَدَّة (djadda), la shadda est posée sur le ___.', array['د']::text[], 'La shadda est au-dessus du د : il est doublé, djad-da. Le ج ne porte qu''une fatha.', 1, '{"id": "ar.l12.e13", "unitIds": ["ar.g12.shadda", "ar.v.djadda"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète avec la bonne lettre.", "prompt": "Dans جَدَّة (djadda), la shadda est posée sur le ___.", "promptLanguage": "fr", "options": ["د", "ج", "ة"], "answer": "د", "acceptedAnswers": ["د"], "explanation": "La shadda est au-dessus du د : il est doublé, djad-da. Le ج ne porte qu''une fatha.", "tip": "Cherche le petit w.", "extraExample": {"text": "عَمَّة", "translation": "tante", "transliteration": "3amma"}, "errorPatterns": [{"equals": "ج", "category": "word_confusion", "feedback": "Le ج ne porte qu''une fatha (dja). La shadda est sur le د."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e14', 'ar', 'ar.l12', 'ar.g10.sukun', array['ar.g10.sukun','ar.v.bint']::text[], 'fill_blank', 'lesson', 'Dans بِنْت (bint), le ن porte un ___ et non une shadda : il n''est pas doublé.', array['sukun']::text[], 'Le petit rond est un sukun : la consonne se prononce une seule fois, sans voyelle. La shadda, elle, double la lettre.', 2, '{"id": "ar.l12.e14", "unitIds": ["ar.g10.sukun", "ar.v.bint"], "type": "fill_blank", "difficulty": 2, "instruction": "Révision : complète avec le nom du signe.", "prompt": "Dans بِنْت (bint), le ن porte un ___ et non une shadda : il n''est pas doublé.", "promptLanguage": "fr", "options": ["sukun", "damma", "fatha", "kasra"], "answer": "sukun", "acceptedAnswers": ["sukun"], "explanation": "Le petit rond est un sukun : la consonne se prononce une seule fois, sans voyelle. La shadda, elle, double la lettre.", "tip": "Petit rond = rien ; petit w = lettre doublée.", "extraExample": {"text": "بِنْتِي", "translation": "ma fille", "transliteration": "bintî"}, "errorPatterns": [{"equals": "damma", "category": "word_confusion", "feedback": "La damma donnerait binut. Sur le ن, il n''y a pas de voyelle : c''est un sukun."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e15', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.amma']::text[], 'fill_blank', 'lesson', 'Pour dire « tante » (sœur du père), on écrit عَمَّة, qui se lit « ___ ».', array['3amma']::text[], 'Fatha sur le ع (3a), puis le م doublé par la shadda, avec une fatha : 3am-ma.', 3, '{"id": "ar.l12.e15", "unitIds": ["ar.g12.shadda", "ar.v.amma"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la bonne lecture.", "prompt": "Pour dire « tante » (sœur du père), on écrit عَمَّة, qui se lit « ___ ».", "promptLanguage": "fr", "options": ["3amma", "3ama", "3amâ", "3umma"], "answer": "3amma", "acceptedAnswers": ["3amma"], "explanation": "Fatha sur le ع (3a), puis le م doublé par la shadda, avec une fatha : 3am-ma.", "tip": "Lettre doublée : tiens la consonne, puis dis la voyelle.", "extraExample": {"text": "عَمَّتِي", "translation": "ma tante", "transliteration": "3ammatî"}, "errorPatterns": [{"equals": "3ama", "category": "word_confusion", "feedback": "Le م est doublé par la shadda : 3amma. Sans elle, le mot serait 3ama."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e16', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.djadda']::text[], 'reorder', 'lesson', 'Écris « djadda » (grand-mère) en séparant la lettre doublée.', array['جَ دْ دَ ة']::text[], 'La shadda vaut deux lettres : un د avec sukun, qui ferme la syllabe djad, puis un د avec fatha (da). Le ة termine le mot.', 3, '{"id": "ar.l12.e16", "unitIds": ["ar.g12.shadda", "ar.v.djadda"], "type": "reorder", "difficulty": 3, "instruction": "Touche les morceaux dans l''ordre de lecture (le premier d''abord).", "prompt": "Écris « djadda » (grand-mère) en séparant la lettre doublée.", "promptLanguage": "fr", "tokens": ["دَ", "ة", "جَ", "دْ"], "answer": "جَ دْ دَ ة", "acceptedAnswers": ["جَ دْ دَ ة"], "explanation": "La shadda vaut deux lettres : un د avec sukun, qui ferme la syllabe djad, puis un د avec fatha (da). Le ة termine le mot.", "tip": "Shadda = lettre sans voyelle + même lettre avec voyelle.", "extraExample": {"text": "جَدَّات", "translation": "grands-mères", "transliteration": "djaddât"}, "pool": "lesson", "lessonId": "ar.l12", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e17', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.muallim']::text[], 'reorder', 'lesson', 'Écris « mu3allim » (enseignant).', array['مُ عَلْ لِ م']::text[], 'Mu-3al-lim : le ل doublé se coupe en deux, un ل sans voyelle qui ferme la syllabe 3al (عَلْ), puis un ل avec kasra (لِ).', 3, '{"id": "ar.l12.e17", "unitIds": ["ar.g12.shadda", "ar.v.muallim"], "type": "reorder", "difficulty": 3, "instruction": "Touche les syllabes dans l''ordre de lecture (la première d''abord).", "prompt": "Écris « mu3allim » (enseignant).", "promptLanguage": "fr", "tokens": ["لِ", "مُ", "م", "عَلْ"], "answer": "مُ عَلْ لِ م", "acceptedAnswers": ["مُ عَلْ لِ م"], "explanation": "Mu-3al-lim : le ل doublé se coupe en deux, un ل sans voyelle qui ferme la syllabe 3al (عَلْ), puis un ل avec kasra (لِ).", "tip": "Découpe à voix haute : mu / 3al / lim.", "extraExample": {"text": "مُعَلِّمُونَ", "translation": "enseignants", "transliteration": "mu3allimûna"}, "pool": "lesson", "lessonId": "ar.l12", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e18', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.djadd']::text[], 'translation', 'lesson', 'جَدّ', array['grand-père','le grand-père','un grand-père','grand père','le grand père','grand-papa','papy','papi']::text[], 'جَدّ (djadd) : le grand-père. Avec un ة à la fin (جَدَّة), il devient grand-mère.', 2, '{"id": "ar.l12.e18", "unitIds": ["ar.g12.shadda", "ar.v.djadd"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "جَدّ", "promptLanguage": "ar", "answer": "grand-père", "acceptedAnswers": ["grand-père", "le grand-père", "un grand-père", "grand père", "le grand père", "grand-papa", "papy", "papi"], "explanation": "جَدّ (djadd) : le grand-père. Avec un ة à la fin (جَدَّة), il devient grand-mère.", "tip": "Djadd, grand-père ; djadda, grand-mère.", "extraExample": {"text": "جَدِّي", "translation": "mon grand-père", "transliteration": "djaddî"}, "errorPatterns": [{"equals": "grand-mère", "category": "vocabulary", "feedback": "La grand-mère, c''est جَدَّة (djadda), avec le ة final. جَدّ (djadd) est le grand-père."}, {"equals": "la grand-mère", "category": "vocabulary", "feedback": "La grand-mère, c''est جَدَّة (djadda), avec le ة final. جَدّ (djadd) est le grand-père."}, {"equals": "grand mère", "category": "vocabulary", "feedback": "La grand-mère, c''est جَدَّة (djadda), avec le ة final. جَدّ (djadd) est le grand-père."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e19', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.amm']::text[], 'translation', 'lesson', 'عَمّ', array['oncle','l''oncle','un oncle','oncle paternel','l''oncle paternel','un oncle paternel','oncle (frère du père)']::text[], 'عَمّ (3amm) est le frère du père, l''oncle paternel.', 2, '{"id": "ar.l12.e19", "unitIds": ["ar.g12.shadda", "ar.v.amm"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "عَمّ", "promptLanguage": "ar", "answer": "oncle", "acceptedAnswers": ["oncle", "l''oncle", "un oncle", "oncle paternel", "l''oncle paternel", "un oncle paternel", "oncle (frère du père)"], "explanation": "عَمّ (3amm) est le frère du père, l''oncle paternel.", "tip": "3amm (shadda) : l''oncle du côté du père ; khâl : du côté de la mère.", "extraExample": {"text": "عَمِّي", "translation": "mon oncle", "transliteration": "3ammî"}, "errorPatterns": [{"equals": "oncle maternel", "category": "vocabulary", "feedback": "L''oncle maternel, c''est خَال (khâl), avec un ا. عَمّ (3amm), avec une shadda, est le frère du père."}, {"equals": "l''oncle maternel", "category": "vocabulary", "feedback": "L''oncle maternel, c''est خَال (khâl), avec un ا. عَمّ (3amm), avec une shadda, est le frère du père."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e20', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.khadd']::text[], 'free_answer', 'lesson', 'Comment se lit خَدّ (joue) ?', array['khadd']::text[], 'Fatha sur le خ (kha), puis le د doublé par la shadda : khadd.', 3, '{"id": "ar.l12.e20", "unitIds": ["ar.g12.shadda", "ar.v.khadd"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit خَدّ (joue) ?", "promptLanguage": "fr", "answer": "khadd", "acceptedAnswers": ["khadd"], "hint": "Le خ se note kh.", "explanation": "Fatha sur le خ (kha), puis le د doublé par la shadda : khadd.", "tip": "Deux d : la shadda double la lettre.", "extraExample": {"text": "خَدَّانِ", "translation": "deux joues", "transliteration": "khaddâni"}, "errorPatterns": [{"equals": "khad", "category": "spelling", "feedback": "La shadda double le د : il faut deux d, khadd."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e21', 'ar', 'ar.l12', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.muallim']::text[], 'free_answer', 'lesson', 'Comment se lit مُعَلِّم (enseignant) ?', array['mu3allim']::text[], 'Damma sur le م (mu), fatha sur le ع (3a), puis le ل doublé avec une kasra (llim) : mu-3al-lim.', 4, '{"id": "ar.l12.e21", "unitIds": ["ar.g12.shadda", "ar.v.muallim"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit مُعَلِّم (enseignant) ?", "promptLanguage": "fr", "answer": "mu3allim", "acceptedAnswers": ["mu3allim"], "hint": "Le ع se note 3.", "explanation": "Damma sur le م (mu), fatha sur le ع (3a), puis le ل doublé avec une kasra (llim) : mu-3al-lim.", "tip": "Dans mu3allim : un seul 3, deux l.", "extraExample": {"text": "مُعَلِّمَة", "translation": "enseignante", "transliteration": "mu3allima"}, "errorPatterns": [{"equals": "mu3alim", "category": "spelling", "feedback": "Le ل porte une shadda : il faut deux l, mu3allim."}, {"equals": "mu3allam", "category": "word_confusion", "feedback": "Sous le ل doublé, c''est une kasra : lim, pas lam."}], "pool": "lesson", "lessonId": "ar.l12", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e01', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.talib']::text[], 'mcq', 'lesson', 'Comment se lit طَالِبٌ (un étudiant) ?', array['Tâlibun']::text[], 'Le signe doublé ـٌ à la fin du mot est un tanwin : une damma écrite en double, qui ajoute un son n. On lit Tâlib-un.', 1, '{"id": "ar.l13.e01", "unitIds": ["ar.g13.tanwin", "ar.v.talib"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit طَالِبٌ (un étudiant) ?", "promptLanguage": "fr", "options": ["Tâlibun", "Tâlibu", "Tâlib", "Tâlibûn"], "answer": "Tâlibun", "acceptedAnswers": ["Tâlibun"], "hint": "Regarde le signe sur la dernière lettre : est-il simple ou doublé ?", "explanation": "Le signe doublé ـٌ à la fin du mot est un tanwin : une damma écrite en double, qui ajoute un son n. On lit Tâlib-un.", "tip": "Signe doublé = voyelle + n.", "extraExample": {"text": "رَجُلٌ", "translation": "un homme", "transliteration": "radjulun"}, "errorPatterns": [{"equals": "Tâlibu", "category": "word_confusion", "feedback": "Le signe est doublé (ـٌ) : c''est un tanwin, qui ajoute un n. Une simple damma donnerait Tâlibu."}, {"equals": "Tâlibûn", "category": "word_confusion", "feedback": "Un û long demanderait un و. Ici, le tanwin ajoute seulement un n : Tâlibun."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e02', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin']::text[], 'mcq', 'lesson', 'Comment se lit طَبِيبًا (un médecin, complément) ?', array['Tabîban']::text[], 'Le tanwin ـً (fatha doublée) se lit -an. Le ا qui le suit est un alif muet : il sert seulement de support et ne se prononce pas.', 1, '{"id": "ar.l13.e02", "unitIds": ["ar.g13.tanwin"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit طَبِيبًا (un médecin, complément) ?", "promptLanguage": "fr", "options": ["Tabîban", "Tabîbanâ", "Tabîbân", "Tabîbana"], "answer": "Tabîban", "acceptedAnswers": ["Tabîban"], "explanation": "Le tanwin ـً (fatha doublée) se lit -an. Le ا qui le suit est un alif muet : il sert seulement de support et ne se prononce pas.", "tip": "Tanwin -an : le ا final se tait.", "extraExample": {"text": "وَلَدًا", "translation": "un garçon", "transliteration": "waladan"}, "errorPatterns": [{"equals": "Tabîbân", "category": "word_confusion", "feedback": "L''alif après le tanwin est muet, il ne forme pas un â long : Tabîban."}, {"equals": "Tabîbanâ", "category": "word_confusion", "feedback": "Le ا final ne se prononce pas : on s''arrête sur le n, Tabîban."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e03', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.taliba']::text[], 'mcq', 'lesson', 'Comment se lit طَالِبَةٌ (une étudiante) ?', array['Tâlibatun']::text[], 'Avec le ة, le tanwin fait entendre un t : Tâliba-t-un. Le ة ne se lit t que lorsqu''une voyelle ou un tanwin le suit.', 2, '{"id": "ar.l13.e03", "unitIds": ["ar.g13.tanwin", "ar.v.taliba"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit طَالِبَةٌ (une étudiante) ?", "promptLanguage": "fr", "options": ["Tâlibatun", "Tâlibun", "Tâlibatân", "Tâlibatu"], "answer": "Tâlibatun", "acceptedAnswers": ["Tâlibatun"], "explanation": "Avec le ة, le tanwin fait entendre un t : Tâliba-t-un. Le ة ne se lit t que lorsqu''une voyelle ou un tanwin le suit.", "tip": "ة + tanwin = -atun.", "extraExample": {"text": "مُعَلِّمَةٌ", "translation": "une enseignante", "transliteration": "mu3allimatun"}, "errorPatterns": [{"equals": "Tâlibun", "category": "word_confusion", "feedback": "Il y a un ة avant le tanwin : on entend le t. Tâlibun serait طَالِبٌ (un étudiant)."}, {"equals": "Tâlibatu", "category": "word_confusion", "feedback": "Le signe est doublé (ـٌ) : le tanwin ajoute un n, Tâlibatun."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e04', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.tanwin']::text[], 'match', 'lesson', 'Les trois tanwins', '{}'::text[], 'Damma doublée = -un, kasra doublée = -in, fatha doublée = -an. Le son n s''ajoute toujours à la fin du mot.', 1, '{"id": "ar.l13.e04", "unitIds": ["ar.g13.tanwin", "ar.v.tanwin"], "type": "match", "difficulty": 1, "instruction": "Associe chaque signe à sa lecture.", "prompt": "Les trois tanwins", "promptLanguage": "fr", "pairs": [{"left": "ـٌ", "right": "-un"}, {"left": "ـٍ", "right": "-in"}, {"left": "ـً", "right": "-an"}], "answer": "ـٌ = -un ; ـٍ = -in ; ـً = -an", "acceptedAnswers": [], "explanation": "Damma doublée = -un, kasra doublée = -in, fatha doublée = -an. Le son n s''ajoute toujours à la fin du mot.", "tip": "Même voyelle qu''avant, en double, avec un n.", "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e05', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.zawdja']::text[], 'mcq', 'lesson', 'Comment se lit زَوْجَةً (une épouse, complément) ?', array['zawdjatan']::text[], 'Après un ة, le tanwin -an s''écrit sans alif : zawdja-t-an. Le t apparaît parce qu''un tanwin suit le ة.', 2, '{"id": "ar.l13.e05", "unitIds": ["ar.g13.tanwin", "ar.v.zawdja"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit زَوْجَةً (une épouse, complément) ?", "promptLanguage": "fr", "options": ["zawdjatan", "zawdjatân", "zawdjan", "zawdjatun"], "answer": "zawdjatan", "acceptedAnswers": ["zawdjatan"], "explanation": "Après un ة, le tanwin -an s''écrit sans alif : zawdja-t-an. Le t apparaît parce qu''un tanwin suit le ة.", "tip": "ة + ـً : pas d''alif, on lit -atan.", "extraExample": {"text": "طَالِبَةً", "translation": "une étudiante", "transliteration": "Tâlibatan"}, "errorPatterns": [{"equals": "zawdjatân", "category": "word_confusion", "feedback": "Il n''y a pas d''alif après un ة : le tanwin se lit simplement -an."}, {"equals": "zawdjatun", "category": "word_confusion", "feedback": "Le tanwin est ـً (fatha doublée) : -an, et non -un."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e06', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.taliba']::text[], 'mcq', 'lesson', 'Dans quel cas n''écrit-on pas d''alif avec le tanwin -an ?', array['après un ة (طَالِبَةً)']::text[], 'L''alif de soutien se met après presque toutes les lettres, mais pas après le ة : on écrit طَالِبَةً (Tâlibatan), sans alif.', 3, '{"id": "ar.l13.e06", "unitIds": ["ar.g13.tanwin", "ar.v.taliba"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans quel cas n''écrit-on pas d''alif avec le tanwin -an ?", "promptLanguage": "fr", "options": ["après un ة (طَالِبَةً)", "après un ب (طَبِيبًا)", "après un د (وَلَدًا)", "après un ر (رَجُلًا)"], "answer": "après un ة (طَالِبَةً)", "acceptedAnswers": ["après un ة (طَالِبَةً)"], "explanation": "L''alif de soutien se met après presque toutes les lettres, mais pas après le ة : on écrit طَالِبَةً (Tâlibatan), sans alif.", "tip": "ة et alif de soutien ne vont pas ensemble.", "extraExample": {"text": "زَوْجَةً", "translation": "une épouse", "transliteration": "zawdjatan"}, "errorPatterns": [{"equals": "après un ب (طَبِيبًا)", "category": "grammar", "feedback": "Après le ب, on écrit bien un alif de soutien : طَبِيبًا. L''exception, c''est le ة."}, {"equals": "après un د (وَلَدًا)", "category": "grammar", "feedback": "Après le د, on écrit bien un alif de soutien : وَلَدًا. L''exception, c''est le ة."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e07', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.sadr']::text[], 'mcq', 'lesson', 'Comment se lit صَدْرٌ (une poitrine) ?', array['Sadrun']::text[], 'Fatha sur le ص (Sa), sukun sur le د, puis le ر avec tanwin -un : Sadr-un.', 2, '{"id": "ar.l13.e07", "unitIds": ["ar.g13.tanwin", "ar.v.sadr"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit صَدْرٌ (une poitrine) ?", "promptLanguage": "fr", "options": ["Sadrun", "Sadru", "Sadarun", "Sadrûn"], "answer": "Sadrun", "acceptedAnswers": ["Sadrun"], "explanation": "Fatha sur le ص (Sa), sukun sur le د, puis le ر avec tanwin -un : Sadr-un.", "tip": "Sukun d''abord, tanwin à la fin : Sadr + un.", "extraExample": {"text": "ظَهْرٌ", "translation": "un dos", "transliteration": "Zahrun"}, "errorPatterns": [{"equals": "Sadarun", "category": "spelling", "feedback": "Le د porte un sukun : pas de voyelle après lui. On lit Sadr-un."}, {"equals": "Sadru", "category": "word_confusion", "feedback": "Le signe est doublé (ـٌ) : le tanwin ajoute un n, Sadrun."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e08', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit « Tabîbin » ?', array['طَبِيبٍ']::text[], 'La kasra doublée sous le ب donne -in : Tabîbin. طَبِيبٌ = Tabîbun, طَبِيبًا = Tabîban, et طَبِيبُ (simple damma) = Tabîbu, sans n.', 3, '{"id": "ar.l13.e08", "unitIds": ["ar.g13.tanwin"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se lit « Tabîbin » ?", "promptLanguage": "fr", "options": ["طَبِيبٍ", "طَبِيبٌ", "طَبِيبًا", "طَبِيبُ"], "answer": "طَبِيبٍ", "acceptedAnswers": ["طَبِيبٍ"], "explanation": "La kasra doublée sous le ب donne -in : Tabîbin. طَبِيبٌ = Tabîbun, طَبِيبًا = Tabîban, et طَبِيبُ (simple damma) = Tabîbu, sans n.", "tip": "Kasra doublée : le signe est sous la lettre.", "extraExample": {"text": "مَعَ طَبِيبٍ", "translation": "avec un médecin", "transliteration": "ma3a Tabîbin"}, "errorPatterns": [{"equals": "طَبِيبٌ", "category": "word_confusion", "feedback": "طَبِيبٌ (damma doublée au-dessus) se lit Tabîbun."}, {"equals": "طَبِيبًا", "category": "word_confusion", "feedback": "طَبِيبًا (fatha doublée + alif) se lit Tabîban."}, {"equals": "طَبِيبُ", "category": "word_confusion", "feedback": "طَبِيبُ (simple damma) se lit Tabîbu, sans n : ce n''est pas un tanwin."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e09', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin']::text[], 'mcq', 'lesson', 'Un nom précédé de ال (comme الطَّالِبُ, « l''étudiant ») garde-t-il le tanwin ?', array['non : avec ال, la voyelle finale est simple']::text[], 'ال rend le nom défini (« le, la »), alors que le tanwin marque un nom indéfini (« un, une ») : les deux ne vont jamais ensemble. On écrit الطَّالِبُ (aT-Tâlibu), avec une damma simple.', 3, '{"id": "ar.l13.e09", "unitIds": ["ar.g13.tanwin"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Un nom précédé de ال (comme الطَّالِبُ, « l''étudiant ») garde-t-il le tanwin ?", "promptLanguage": "fr", "options": ["non : avec ال, la voyelle finale est simple", "oui : le tanwin s''ajoute à ال", "oui, mais seulement le tanwin -an", "oui, mais seulement avec un ة"], "answer": "non : avec ال, la voyelle finale est simple", "acceptedAnswers": ["non : avec ال, la voyelle finale est simple"], "explanation": "ال rend le nom défini (« le, la »), alors que le tanwin marque un nom indéfini (« un, une ») : les deux ne vont jamais ensemble. On écrit الطَّالِبُ (aT-Tâlibu), avec une damma simple.", "tip": "ال ou tanwin, jamais les deux.", "extraExample": {"text": "الْكِتَابُ", "translation": "le livre", "transliteration": "al-kitâbu"}, "errorPatterns": [{"equals": "oui : le tanwin s''ajoute à ال", "category": "grammar", "feedback": "Le tanwin marque l''indéfini (« un »), ال le défini (« le ») : ils s''excluent."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e10', 'ar', 'ar.l13', 'ar.v.kitab', array['ar.v.kitab','ar.g13.tanwin']::text[], 'mcq', 'lesson', 'Comment se lit كِتَابٌ (un livre) ?', array['kitâbun']::text[], 'Kasra sous le ك (ki), fatha et ا sur le ت (tâ, long), puis le ب avec tanwin -un : ki-tâb-un.', 2, '{"id": "ar.l13.e10", "unitIds": ["ar.v.kitab", "ar.g13.tanwin"], "type": "mcq", "difficulty": 2, "instruction": "Révision : choisis la bonne lecture.", "prompt": "Comment se lit كِتَابٌ (un livre) ?", "promptLanguage": "fr", "options": ["kitâbun", "kitâbu", "kitabun", "kitâb"], "answer": "kitâbun", "acceptedAnswers": ["kitâbun"], "explanation": "Kasra sous le ك (ki), fatha et ا sur le ت (tâ, long), puis le ب avec tanwin -un : ki-tâb-un.", "tip": "Voyelle longue avant, tanwin après : kitâb + un.", "extraExample": {"text": "كِتَابًا", "translation": "un livre", "transliteration": "kitâban"}, "errorPatterns": [{"equals": "kitâbu", "category": "word_confusion", "feedback": "Le signe est doublé (ـٌ) : il faut ajouter le n, kitâbun."}, {"equals": "kitabun", "category": "word_confusion", "feedback": "Le ا après le ت allonge le a : tâ, et non ta."}, {"equals": "kitâb", "category": "word_confusion", "feedback": "Le tanwin ajoute un n final : kitâbun, et pas seulement kitâb."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e11', 'ar', 'ar.l13', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.djadda']::text[], 'mcq', 'lesson', 'Comment se lit جَدَّةٌ (une grand-mère) ?', array['djaddatun']::text[], 'La shadda double le د (djad-da), puis le ة et le tanwin -un font entendre -tun : djaddatun.', 3, '{"id": "ar.l13.e11", "unitIds": ["ar.g12.shadda", "ar.v.djadda"], "type": "mcq", "difficulty": 3, "instruction": "Révision : choisis la bonne lecture.", "prompt": "Comment se lit جَدَّةٌ (une grand-mère) ?", "promptLanguage": "fr", "options": ["djaddatun", "djadatun", "djaddatân", "djaddatu"], "answer": "djaddatun", "acceptedAnswers": ["djaddatun"], "explanation": "La shadda double le د (djad-da), puis le ة et le tanwin -un font entendre -tun : djaddatun.", "tip": "Shadda pour doubler, ة + tanwin pour -atun.", "extraExample": {"text": "عَمَّةٌ", "translation": "une tante", "transliteration": "3ammatun"}, "errorPatterns": [{"equals": "djadatun", "category": "word_confusion", "feedback": "Le د porte une shadda : djaddatun, avec deux d."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e12', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.talib','ar.v.taliba','ar.v.tabib','ar.v.zawdja','ar.v.zawdj']::text[], 'match', 'lesson', 'Étudiants, médecins et couples', '{}'::text[], 'طَالِب (Tâlib) = l''étudiant, طَالِبَة (Tâliba) = l''étudiante, طَبِيب (Tabîb) = le médecin, زَوْجَة (zawdja) = l''épouse, زَوْج (zawdj) = le mari.', 2, '{"id": "ar.l13.e12", "unitIds": ["ar.g13.tanwin", "ar.v.talib", "ar.v.taliba", "ar.v.tabib", "ar.v.zawdja", "ar.v.zawdj"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Étudiants, médecins et couples", "promptLanguage": "fr", "pairs": [{"left": "طَالِب", "right": "l''étudiant"}, {"left": "طَالِبَة", "right": "l''étudiante"}, {"left": "طَبِيب", "right": "le médecin"}, {"left": "زَوْجَة", "right": "l''épouse"}, {"left": "زَوْج", "right": "le mari"}], "answer": "طَالِب = l''étudiant ; طَالِبَة = l''étudiante ; طَبِيب = le médecin ; زَوْجَة = l''épouse ; زَوْج = le mari", "acceptedAnswers": [], "explanation": "طَالِب (Tâlib) = l''étudiant, طَالِبَة (Tâliba) = l''étudiante, طَبِيب (Tabîb) = le médecin, زَوْجَة (zawdja) = l''épouse, زَوْج (zawdj) = le mari.", "tip": "Le ة final fait souvent le féminin : طَالِب / طَالِبَة, زَوْج / زَوْجَة.", "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e13', 'ar', 'ar.l13', 'ar.v.dhira', array['ar.v.dhira','ar.g13.tanwin','ar.v.sadr','ar.v.zahr','ar.v.djabin','ar.v.qalb']::text[], 'match', 'lesson', 'Du front au dos', '{}'::text[], 'جَبِين (djabîn) = le front, صَدْر (Sadr) = la poitrine, ظَهْر (Zahr) = le dos, قَلْب (qalb) = le cœur, ذِرَاع (dhirâ3) = le bras.', 3, '{"id": "ar.l13.e13", "unitIds": ["ar.v.dhira", "ar.g13.tanwin", "ar.v.sadr", "ar.v.zahr", "ar.v.djabin", "ar.v.qalb"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Du front au dos", "promptLanguage": "fr", "pairs": [{"left": "جَبِين", "right": "le front"}, {"left": "صَدْر", "right": "la poitrine"}, {"left": "ظَهْر", "right": "le dos"}, {"left": "قَلْب", "right": "le cœur"}, {"left": "ذِرَاع", "right": "le bras"}], "answer": "جَبِين = le front ; صَدْر = la poitrine ; ظَهْر = le dos ; قَلْب = le cœur ; ذِرَاع = le bras", "acceptedAnswers": [], "explanation": "جَبِين (djabîn) = le front, صَدْر (Sadr) = la poitrine, ظَهْر (Zahr) = le dos, قَلْب (qalb) = le cœur, ذِرَاع (dhirâ3) = le bras.", "tip": "Du haut vers le bas : le front, la poitrine, le dos.", "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e14', 'ar', 'ar.l13', 'ar.v.kasra', array['ar.v.kasra','ar.g13.tanwin']::text[], 'fill_blank', 'lesson', 'Le tanwin ـٍ est une ___ doublée : il fait entendre -in.', array['kasra']::text[], 'Le tanwin ـٍ est une kasra écrite en double sous la lettre : il fait entendre -in. Même logique : damma doublée = -un, fatha doublée = -an.', 2, '{"id": "ar.l13.e14", "unitIds": ["ar.v.kasra", "ar.g13.tanwin"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le nom du signe.", "prompt": "Le tanwin ـٍ est une ___ doublée : il fait entendre -in.", "promptLanguage": "fr", "options": ["kasra", "fatha", "damma", "shadda"], "answer": "kasra", "acceptedAnswers": ["kasra"], "explanation": "Le tanwin ـٍ est une kasra écrite en double sous la lettre : il fait entendre -in. Même logique : damma doublée = -un, fatha doublée = -an.", "tip": "Le tanwin garde la voyelle du signe simple, mais en double.", "extraExample": {"text": "فِي بَيْتٍ", "translation": "dans une maison", "transliteration": "fî baytin"}, "errorPatterns": [{"equals": "damma", "category": "word_confusion", "feedback": "La damma doublée (ـٌ) fait entendre -un. Ici le signe est sous la lettre : c''est une kasra."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e15', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.taliba']::text[], 'fill_blank', 'lesson', 'طَالِبَةٌ se lit Tâlibatun : devant le tanwin, le ة fait entendre un ___.', array['t']::text[], 'Le ة se lit t quand une voyelle ou un tanwin le suit. À la fin d''un mot isolé, il se tait.', 2, '{"id": "ar.l13.e15", "unitIds": ["ar.g13.tanwin", "ar.v.taliba"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec la bonne lettre.", "prompt": "طَالِبَةٌ se lit Tâlibatun : devant le tanwin, le ة fait entendre un ___.", "promptLanguage": "fr", "options": ["t", "d", "h", "k"], "answer": "t", "acceptedAnswers": ["t"], "explanation": "Le ة se lit t quand une voyelle ou un tanwin le suit. À la fin d''un mot isolé, il se tait.", "tip": "ة + voyelle ou tanwin = t.", "extraExample": {"text": "زَوْجَةٌ", "translation": "une épouse", "transliteration": "zawdjatun"}, "pool": "lesson", "lessonId": "ar.l13", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e16', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.tabib']::text[], 'fill_blank', 'lesson', 'Pour écrire « Tabîbun » (un médecin), la dernière lettre porte une ___ doublée.', array['damma']::text[], 'Tabîbun se termine par -un : une damma écrite en double (ـٌ) sur le ب final, طَبِيبٌ.', 3, '{"id": "ar.l13.e16", "unitIds": ["ar.g13.tanwin", "ar.v.tabib"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le nom du signe.", "prompt": "Pour écrire « Tabîbun » (un médecin), la dernière lettre porte une ___ doublée.", "promptLanguage": "fr", "options": ["damma", "fatha", "kasra", "sukun"], "answer": "damma", "acceptedAnswers": ["damma"], "explanation": "Tabîbun se termine par -un : une damma écrite en double (ـٌ) sur le ب final, طَبِيبٌ.", "tip": "-un : damma doublée ; -in : kasra doublée ; -an : fatha doublée.", "extraExample": {"text": "طَبِيبٌ", "translation": "un médecin", "transliteration": "Tabîbun"}, "errorPatterns": [{"equals": "fatha", "category": "word_confusion", "feedback": "La fatha doublée (ـً) fait entendre -an : Tabîban."}, {"equals": "kasra", "category": "word_confusion", "feedback": "La kasra doublée (ـٍ) fait entendre -in : Tabîbin."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e17', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.talib']::text[], 'reorder', 'lesson', 'Écris « Tâlibun » (un étudiant).', array['طَا لِ بٌ']::text[], 'Tâ-li-bun : ط avec fatha et ا (tâ, long), ل avec kasra, puis ب avec le tanwin (-bun).', 2, '{"id": "ar.l13.e17", "unitIds": ["ar.g13.tanwin", "ar.v.talib"], "type": "reorder", "difficulty": 2, "instruction": "Touche les syllabes dans l''ordre de lecture (la première d''abord).", "prompt": "Écris « Tâlibun » (un étudiant).", "promptLanguage": "fr", "tokens": ["بٌ", "طَا", "لِ"], "answer": "طَا لِ بٌ", "acceptedAnswers": ["طَا لِ بٌ"], "explanation": "Tâ-li-bun : ط avec fatha et ا (tâ, long), ل avec kasra, puis ب avec le tanwin (-bun).", "tip": "Le tanwin se met sur la dernière lettre.", "extraExample": {"text": "طُلَّابٌ", "translation": "des étudiants", "transliteration": "Tullâbun"}, "pool": "lesson", "lessonId": "ar.l13", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e18', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.tabib']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : je suis allé / chez / un médecin', array['ذَهَبْتُ إِلَى طَبِيبٍ']::text[], 'Dhahabtu ilâ Tabîbin : après la préposition إِلَى, le nom indéfini prend le tanwin -in.', 3, '{"id": "ar.l13.e18", "unitIds": ["ar.g13.tanwin", "ar.v.tabib"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre de lecture (le premier d''abord).", "prompt": "Remets dans l''ordre : je suis allé / chez / un médecin", "promptLanguage": "fr", "tokens": ["طَبِيبٍ", "ذَهَبْتُ", "إِلَى"], "answer": "ذَهَبْتُ إِلَى طَبِيبٍ", "acceptedAnswers": ["ذَهَبْتُ إِلَى طَبِيبٍ"], "explanation": "Dhahabtu ilâ Tabîbin : après la préposition إِلَى, le nom indéfini prend le tanwin -in.", "tip": "Verbe, préposition, puis le nom avec son tanwin.", "extraExample": {"text": "جَلَسْتُ مَعَ طَالِبٍ", "translation": "je me suis assis avec un étudiant", "transliteration": "djalastu ma3a Tâlibin"}, "pool": "lesson", "lessonId": "ar.l13", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e19', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.tabib']::text[], 'translation', 'lesson', 'طَبِيب', array['médecin','le médecin','un médecin','docteur','le docteur','un docteur']::text[], 'طَبِيب (Tabîb) : le médecin. Le ي après la kasra est long : Ta-bîb.', 2, '{"id": "ar.l13.e19", "unitIds": ["ar.g13.tanwin", "ar.v.tabib"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "طَبِيب", "promptLanguage": "ar", "answer": "médecin", "acceptedAnswers": ["médecin", "le médecin", "un médecin", "docteur", "le docteur", "un docteur"], "explanation": "طَبِيب (Tabîb) : le médecin. Le ي après la kasra est long : Ta-bîb.", "tip": "Tabîb : le ي après la kasra allonge le i.", "extraExample": {"text": "طَبِيبَة", "translation": "femme médecin", "transliteration": "Tabîba"}, "errorPatterns": [{"equals": "étudiant", "category": "vocabulary", "feedback": "L''étudiant, c''est طَالِب (Tâlib). طَبِيب (Tabîb), c''est le médecin."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e20', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.zawdja']::text[], 'translation', 'lesson', 'زَوْجَة', array['épouse','l''épouse','une épouse','femme','la femme','ma femme','sa femme']::text[], 'زَوْجَة (zawdja) : l''épouse. Le ة final marque le féminin de زَوْج (le mari).', 2, '{"id": "ar.l13.e20", "unitIds": ["ar.g13.tanwin", "ar.v.zawdja"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "زَوْجَة", "promptLanguage": "ar", "answer": "épouse", "acceptedAnswers": ["épouse", "l''épouse", "une épouse", "femme", "la femme", "ma femme", "sa femme"], "explanation": "زَوْجَة (zawdja) : l''épouse. Le ة final marque le féminin de زَوْج (le mari).", "tip": "Zawdj, le mari ; zawdja, l''épouse.", "extraExample": {"text": "زَوْجَتِي", "translation": "ma femme", "transliteration": "zawdjatî"}, "errorPatterns": [{"equals": "mari", "category": "vocabulary", "feedback": "Le mari, c''est زَوْج (zawdj), sans ة. زَوْجَة (zawdja) est l''épouse."}, {"equals": "le mari", "category": "vocabulary", "feedback": "Le mari, c''est زَوْج (zawdj), sans ة. زَوْجَة (zawdja) est l''épouse."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e21', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.talib']::text[], 'free_answer', 'lesson', 'Comment se lit طَالِبًا (un étudiant, complément) ?', array['Tâliban','Taliban','Taaliban']::text[], 'Fatha et ا sur le ط (Tâ, long), kasra sous le ل, puis le ب avec tanwin -an : Tâli-ban. Le ا final est muet.', 3, '{"id": "ar.l13.e21", "unitIds": ["ar.g13.tanwin", "ar.v.talib"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit طَالِبًا (un étudiant, complément) ?", "promptLanguage": "fr", "answer": "Tâliban", "acceptedAnswers": ["Tâliban", "Taliban", "Taaliban"], "hint": "Le ط se note T majuscule.", "explanation": "Fatha et ا sur le ط (Tâ, long), kasra sous le ل, puis le ب avec tanwin -an : Tâli-ban. Le ا final est muet.", "tip": "Tanwin -an : on entend an, pas â.", "extraExample": {"text": "رَأَيْتُ طَالِبًا", "translation": "j''ai vu un étudiant", "transliteration": "ra''aytu Tâliban"}, "errorPatterns": [{"equals": "Tâlibân", "category": "word_confusion", "feedback": "L''alif final est muet : on entend -an, pas un â long."}, {"equals": "Tâlibanâ", "category": "word_confusion", "feedback": "Le ا final ne se prononce pas : Tâliban."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e22', 'ar', 'ar.l13', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.zahr']::text[], 'free_answer', 'lesson', 'Comment se lit ظَهْرٌ (un dos) ?', array['Zahrun']::text[], 'Fatha sur le ظ (Za), sukun sur le ه, puis le ر avec tanwin -un : Zahr-un.', 4, '{"id": "ar.l13.e22", "unitIds": ["ar.g13.tanwin", "ar.v.zahr"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit ظَهْرٌ (un dos) ?", "promptLanguage": "fr", "answer": "Zahrun", "acceptedAnswers": ["Zahrun"], "hint": "Le ظ se note Z majuscule.", "explanation": "Fatha sur le ظ (Za), sukun sur le ه, puis le ر avec tanwin -un : Zahr-un.", "tip": "Le ظ se note Z majuscule ; le tanwin ajoute un n.", "extraExample": {"text": "ظَهْرًا", "translation": "un dos", "transliteration": "Zahran"}, "errorPatterns": [{"equals": "Zahr", "category": "spelling", "feedback": "Le tanwin ajoute -un à la fin du mot : Zahrun."}, {"equals": "Zahru", "category": "word_confusion", "feedback": "Le signe est doublé (ـٌ) : le tanwin ajoute un n, Zahrun."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e01', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.ab']::text[], 'mcq', 'lesson', 'Comment se lit أَب (père) ?', array['ab']::text[], 'Le petit ء au-dessus du ا est la hamza : un léger coup de glotte, suivi de la voyelle (ici une fatha : a). En début de mot, on entend surtout la voyelle : ab.', 1, '{"id": "ar.l14.e01", "unitIds": ["ar.g14.hamza_madda", "ar.v.ab"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit أَب (père) ?", "promptLanguage": "fr", "options": ["ab", "ba", "âb", "3ab"], "answer": "ab", "acceptedAnswers": ["ab"], "explanation": "Le petit ء au-dessus du ا est la hamza : un léger coup de glotte, suivi de la voyelle (ici une fatha : a). En début de mot, on entend surtout la voyelle : ab.", "tip": "Hamza + fatha sur le ا = a.", "extraExample": {"text": "أَخ", "translation": "frère", "transliteration": "akh"}, "errorPatterns": [{"equals": "âb", "category": "word_confusion", "feedback": "Il n''y a ni madda ni deuxième ا : la voyelle est brève, ab."}, {"equals": "3ab", "category": "word_confusion", "feedback": "Le أ n''est pas un ع : son petit ء est une hamza (coup de glotte), pas la lettre ع."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e02', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.umm']::text[], 'mcq', 'lesson', 'Comment se lit أُمّ (mère) ?', array['umm']::text[], 'Hamza et damma sur le ا : u. Puis le م porte une shadda : il est doublé. On lit umm.', 1, '{"id": "ar.l14.e02", "unitIds": ["ar.g14.hamza_madda", "ar.v.umm"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit أُمّ (mère) ?", "promptLanguage": "fr", "options": ["umm", "um", "amm", "imm"], "answer": "umm", "acceptedAnswers": ["umm"], "explanation": "Hamza et damma sur le ا : u. Puis le م porte une shadda : il est doublé. On lit umm.", "tip": "Hamza + damma sur le ا = u.", "extraExample": {"text": "أُمِّي", "translation": "ma mère", "transliteration": "ummî"}, "errorPatterns": [{"equals": "um", "category": "word_confusion", "feedback": "Le م porte une shadda : il est doublé, umm."}, {"equals": "amm", "category": "word_confusion", "feedback": "Le signe sur le ا est une damma (u), pas une fatha."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e03', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.madda']::text[], 'mcq', 'lesson', 'Comment se lit آ ?', array['â (a long)']::text[], 'Le signe ondulé posé sur le ا s''appelle la madda (مَدَّة). آ remplace deux lettres : une hamza avec fatha suivie d''un ا, soit أَا. On entend donc un â long.', 2, '{"id": "ar.l14.e03", "unitIds": ["ar.g14.hamza_madda", "ar.v.madda"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit آ ?", "promptLanguage": "fr", "options": ["â (a long)", "a (a bref)", "i", "û"], "answer": "â (a long)", "acceptedAnswers": ["â (a long)"], "explanation": "Le signe ondulé posé sur le ا s''appelle la madda (مَدَّة). آ remplace deux lettres : une hamza avec fatha suivie d''un ا, soit أَا. On entend donc un â long.", "tip": "آ = â long, comme au début de آمِين (âmîn).", "extraExample": {"text": "آمِين", "translation": "amen", "transliteration": "âmîn"}, "errorPatterns": [{"equals": "a (a bref)", "category": "word_confusion", "feedback": "La madda allonge le son : آ = â, deux fois plus long qu''un a bref."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e04', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda']::text[], 'match', 'lesson', 'Le ا avec hamza ou madda', '{}'::text[], 'Hamza au-dessus du ا + fatha = a, hamza au-dessus + damma = u. Hamza sous le ا + kasra = i. La madda آ donne â long.', 2, '{"id": "ar.l14.e04", "unitIds": ["ar.g14.hamza_madda"], "type": "match", "difficulty": 2, "instruction": "Associe chaque signe à sa lecture.", "prompt": "Le ا avec hamza ou madda", "promptLanguage": "fr", "pairs": [{"left": "أَ", "right": "a"}, {"left": "أُ", "right": "u"}, {"left": "إِ", "right": "i"}, {"left": "آ", "right": "â"}], "answer": "أَ = a ; أُ = u ; إِ = i ; آ = â", "acceptedAnswers": [], "explanation": "Hamza au-dessus du ا + fatha = a, hamza au-dessus + damma = u. Hamza sous le ا + kasra = i. La madda آ donne â long.", "tip": "Hamza en haut : a ou u ; hamza en bas : i.", "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e05', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.ras']::text[], 'mcq', 'lesson', 'Comment se lit رَأْس (tête) ?', array['ra''s']::text[], 'Le أ porte un sukun : c''est une hamza sans voyelle, un coup de glotte qui ferme la syllabe ra''. Puis le س : ra''s.', 2, '{"id": "ar.l14.e05", "unitIds": ["ar.g14.hamza_madda", "ar.v.ras"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit رَأْس (tête) ?", "promptLanguage": "fr", "options": ["ra''s", "râs", "rass", "ra''as"], "answer": "ra''s", "acceptedAnswers": ["ra''s"], "explanation": "Le أ porte un sukun : c''est une hamza sans voyelle, un coup de glotte qui ferme la syllabe ra''. Puis le س : ra''s.", "tip": "Hamza + sukun = coup de glotte net, sans voyelle.", "extraExample": {"text": "بِئْر", "translation": "puits", "transliteration": "bi''r"}, "errorPatterns": [{"equals": "râs", "category": "word_confusion", "feedback": "Il n''y a pas de ا long : le أ est une hamza avec sukun, on marque un petit arrêt, ra''s."}, {"equals": "rass", "category": "spelling", "feedback": "La lettre أ est une hamza (coup de glotte), pas un س doublé."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e06', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.nisa']::text[], 'mcq', 'lesson', 'Comment se lit نِسَاء (femmes) ?', array['nisâ''']::text[], 'La fatha sur le س est suivie d''un ا : sâ long. Le ء final est une hamza seule, un petit coup de glotte : nisâ''.', 2, '{"id": "ar.l14.e06", "unitIds": ["ar.g14.hamza_madda", "ar.v.nisa"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit نِسَاء (femmes) ?", "promptLanguage": "fr", "options": ["nisâ''", "nisâ", "nisây", "nisâ''a"], "answer": "nisâ''", "acceptedAnswers": ["nisâ''"], "explanation": "La fatha sur le س est suivie d''un ا : sâ long. Le ء final est une hamza seule, un petit coup de glotte : nisâ''.", "tip": "Le ء final se marque par un petit arrêt.", "extraExample": {"text": "مَاء", "translation": "eau", "transliteration": "mâ''"}, "errorPatterns": [{"equals": "nisâ", "category": "word_confusion", "feedback": "Le ء final est une vraie consonne, une hamza : il faut marquer le petit coup de glotte, nisâ''."}, {"equals": "nisây", "category": "spelling", "feedback": "Le ء n''est pas un ي : c''est une hamza."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e07', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.imraa']::text[], 'mcq', 'lesson', 'Comment se lit اِمْرَأَة (femme) ?', array['imra''a']::text[], 'Le ا initial porte une kasra : i. Puis م (sukun), ر (fatha) et un أ avec fatha : hamza + a. Le ة final se tait : im-ra-''a.', 3, '{"id": "ar.l14.e07", "unitIds": ["ar.g14.hamza_madda", "ar.v.imraa"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit اِمْرَأَة (femme) ?", "promptLanguage": "fr", "options": ["imra''a", "imrâ''a", "imra''", "amra''a"], "answer": "imra''a", "acceptedAnswers": ["imra''a"], "explanation": "Le ا initial porte une kasra : i. Puis م (sukun), ر (fatha) et un أ avec fatha : hamza + a. Le ة final se tait : im-ra-''a.", "tip": "Hamza au milieu + fatha = ''a : coup de glotte, puis a.", "extraExample": {"text": "مَسْأَلَة", "translation": "question, problème", "transliteration": "mas''ala"}, "errorPatterns": [{"equals": "imrâ''a", "category": "word_confusion", "feedback": "Le أ porte une fatha brève : ''a. Il n''y a pas de ا long entre le ر et la hamza."}, {"equals": "imra''", "category": "spelling", "feedback": "Le أ porte une fatha : on prononce ''a, pas seulement un coup de glotte."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e08', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda']::text[], 'mcq', 'lesson', 'Quelle écriture est la bonne pour « su''âl » (question) ?', array['سُؤَال']::text[], 'Le س porte une damma et la hamza une fatha : la voyelle la plus forte est la damma, donc la hamza s''écrit sur un و (ؤ). On lit su''âl.', 3, '{"id": "ar.l14.e08", "unitIds": ["ar.g14.hamza_madda"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne écriture.", "prompt": "Quelle écriture est la bonne pour « su''âl » (question) ?", "promptLanguage": "fr", "options": ["سُؤَال", "سُأَال", "سُئَال", "سُوَال"], "answer": "سُؤَال", "acceptedAnswers": ["سُؤَال"], "explanation": "Le س porte une damma et la hamza une fatha : la voyelle la plus forte est la damma, donc la hamza s''écrit sur un و (ؤ). On lit su''âl.", "tip": "Support de la hamza : kasra (ي) avant damma (و) avant fatha (ا).", "extraExample": {"text": "مَسْؤُول", "translation": "responsable", "transliteration": "mas''ûl"}, "errorPatterns": [{"equals": "سُأَال", "category": "grammar", "feedback": "Avec une damma juste avant, le support est un و (ؤ), pas un ا."}, {"equals": "سُئَال", "category": "grammar", "feedback": "Le support ئ (ي) est réservé à la kasra, la voyelle la plus forte. Ici c''est la damma : ؤ."}, {"equals": "سُوَال", "category": "spelling", "feedback": "Un simple و se lirait suwâl. Il faut la hamza sur le و : ؤ."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e09', 'ar', 'ar.l14', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.nisa']::text[], 'mcq', 'lesson', 'Dans نِسَاء, quelle lettre allonge la voyelle du س ?', array['ا']::text[], 'Le ا qui suit la fatha du س la rend longue (â). Le ء final n''allonge rien : c''est une hamza, un coup de glotte.', 3, '{"id": "ar.l14.e09", "unitIds": ["ar.g11.long_vowels", "ar.v.nisa"], "type": "mcq", "difficulty": 3, "instruction": "Révision : choisis la bonne réponse.", "prompt": "Dans نِسَاء, quelle lettre allonge la voyelle du س ?", "promptLanguage": "fr", "options": ["ا", "ء", "ن", "و"], "answer": "ا", "acceptedAnswers": ["ا"], "explanation": "Le ا qui suit la fatha du س la rend longue (â). Le ء final n''allonge rien : c''est une hamza, un coup de glotte.", "tip": "Le ا allonge, le ء coupe.", "extraExample": {"text": "سَمَاء", "translation": "ciel", "transliteration": "samâ''"}, "errorPatterns": [{"equals": "ء", "category": "word_confusion", "feedback": "Le ء final est une hamza : une petite coupure, pas un allongement."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e10', 'ar', 'ar.l14', 'ar.v.amm', array['ar.v.amm','ar.v.khal','ar.v.djadd','ar.v.akh']::text[], 'mcq', 'lesson', 'Parmi ces mots de la famille, lequel désigne l''oncle paternel ?', array['عَمّ']::text[], 'عَمّ (3amm) est le frère du père. خَال (khâl) est le frère de la mère, جَدّ (djadd) le grand-père et أَخ (akh) le frère.', 3, '{"id": "ar.l14.e10", "unitIds": ["ar.v.amm", "ar.v.khal", "ar.v.djadd", "ar.v.akh"], "type": "mcq", "difficulty": 3, "instruction": "Révision : choisis le bon mot.", "prompt": "Parmi ces mots de la famille, lequel désigne l''oncle paternel ?", "promptLanguage": "fr", "options": ["عَمّ", "خَال", "جَدّ", "أَخ"], "answer": "عَمّ", "acceptedAnswers": ["عَمّ"], "explanation": "عَمّ (3amm) est le frère du père. خَال (khâl) est le frère de la mère, جَدّ (djadd) le grand-père et أَخ (akh) le frère.", "tip": "3amm : côté du père ; khâl : côté de la mère.", "extraExample": {"text": "عَمِّي", "translation": "mon oncle", "transliteration": "3ammî"}, "errorPatterns": [{"equals": "خَال", "category": "vocabulary", "feedback": "خَال (khâl) est l''oncle maternel, le frère de la mère."}, {"equals": "أَخ", "category": "vocabulary", "feedback": "أَخ (akh) est le frère, pas l''oncle."}, {"equals": "جَدّ", "category": "vocabulary", "feedback": "جَدّ (djadd) est le grand-père."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e11', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.ab','ar.v.umm','ar.v.akh','ar.v.ukht','ar.v.aila']::text[], 'match', 'lesson', 'Père, mère, frère, sœur et famille', '{}'::text[], 'أَب (ab) = le père, أُمّ (umm) = la mère, أَخ (akh) = le frère, أُخْت (ukht) = la sœur, عَائِلَة (3â''ila) = la famille.', 2, '{"id": "ar.l14.e11", "unitIds": ["ar.g14.hamza_madda", "ar.v.ab", "ar.v.umm", "ar.v.akh", "ar.v.ukht", "ar.v.aila"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Père, mère, frère, sœur et famille", "promptLanguage": "fr", "pairs": [{"left": "أَب", "right": "le père"}, {"left": "أُمّ", "right": "la mère"}, {"left": "أَخ", "right": "le frère"}, {"left": "أُخْت", "right": "la sœur"}, {"left": "عَائِلَة", "right": "la famille"}], "answer": "أَب = le père ; أُمّ = la mère ; أَخ = le frère ; أُخْت = la sœur ; عَائِلَة = la famille", "acceptedAnswers": [], "explanation": "أَب (ab) = le père, أُمّ (umm) = la mère, أَخ (akh) = le frère, أُخْت (ukht) = la sœur, عَائِلَة (3â''ila) = la famille.", "tip": "Ab et akh se ressemblent : regarde la deuxième lettre (ب ou خ).", "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e12', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.aila','ar.v.ras','ar.v.nisa']::text[], 'match', 'lesson', 'La hamza sur tous ses supports', '{}'::text[], 'ؤ (hamza sur و) dans su''âl, ئ (hamza sur ي) dans 3â''ila, أ (hamza sur ا) dans ra''s, ء (hamza seule) dans nisâ'', et la madda آ dans qur''ân.', 3, '{"id": "ar.l14.e12", "unitIds": ["ar.g14.hamza_madda", "ar.v.aila", "ar.v.ras", "ar.v.nisa"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à sa lecture.", "prompt": "La hamza sur tous ses supports", "promptLanguage": "fr", "pairs": [{"left": "سُؤَال", "right": "su''âl"}, {"left": "عَائِلَة", "right": "3â''ila"}, {"left": "رَأْس", "right": "ra''s"}, {"left": "نِسَاء", "right": "nisâ''"}, {"left": "قُرْآن", "right": "qur''ân"}], "answer": "سُؤَال = su''âl ; عَائِلَة = 3â''ila ; رَأْس = ra''s ; نِسَاء = nisâ'' ; قُرْآن = qur''ân", "acceptedAnswers": [], "explanation": "ؤ (hamza sur و) dans su''âl, ئ (hamza sur ي) dans 3â''ila, أ (hamza sur ا) dans ra''s, ء (hamza seule) dans nisâ'', et la madda آ dans qur''ân.", "tip": "Le support se tait : lis seulement la hamza et sa voyelle.", "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e13', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.madda']::text[], 'fill_blank', 'lesson', 'Le signe ondulé posé sur un ا (آ) s''appelle la ___.', array['madda']::text[], 'La madda (مَدَّة) est le signe ondulé posé sur le ا : آ = hamza + â long.', 2, '{"id": "ar.l14.e13", "unitIds": ["ar.g14.hamza_madda", "ar.v.madda"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le nom du signe.", "prompt": "Le signe ondulé posé sur un ا (آ) s''appelle la ___.", "promptLanguage": "fr", "options": ["madda", "shadda", "sukun", "hamza"], "answer": "madda", "acceptedAnswers": ["madda"], "explanation": "La madda (مَدَّة) est le signe ondulé posé sur le ا : آ = hamza + â long.", "tip": "Madda = allongement.", "extraExample": {"text": "آخِر", "translation": "dernier", "transliteration": "âkhir"}, "errorPatterns": [{"equals": "hamza", "category": "word_confusion", "feedback": "La hamza est le petit ء. Le signe ondulé sur le ا est la madda."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e14', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.ukht']::text[], 'fill_blank', 'lesson', 'Pour écrire « ukht » (sœur), on met sur le ا une hamza avec une ___.', array['damma']::text[], 'Ukht commence par u : hamza + damma sur le ا, أُخْت. Le خ porte un sukun.', 2, '{"id": "ar.l14.e14", "unitIds": ["ar.g14.hamza_madda", "ar.v.ukht"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le nom du signe.", "prompt": "Pour écrire « ukht » (sœur), on met sur le ا une hamza avec une ___.", "promptLanguage": "fr", "options": ["damma", "fatha", "kasra"], "answer": "damma", "acceptedAnswers": ["damma"], "explanation": "Ukht commence par u : hamza + damma sur le ا, أُخْت. Le خ porte un sukun.", "tip": "u = damma, a = fatha, i = kasra.", "extraExample": {"text": "أُسْرَة", "translation": "famille", "transliteration": "usra"}, "errorPatterns": [{"equals": "fatha", "category": "word_confusion", "feedback": "Avec une fatha, on lirait akht. Ukht commence par u : damma."}, {"equals": "kasra", "category": "word_confusion", "feedback": "Avec une kasra, la hamza passerait sous le ا (إِ) et on lirait ikht."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e15', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.aila']::text[], 'fill_blank', 'lesson', 'Dans عَائِلَة, la hamza est posée sur un support en forme de ___.', array['ي sans points (ئ)']::text[], 'La hamza porte une kasra, la voyelle la plus forte : son support est un ي sans points, ئ. On lit 3â''ila.', 3, '{"id": "ar.l14.e15", "unitIds": ["ar.g14.hamza_madda", "ar.v.aila"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le bon support.", "prompt": "Dans عَائِلَة, la hamza est posée sur un support en forme de ___.", "promptLanguage": "fr", "options": ["ي sans points (ئ)", "و (ؤ)", "ا (أ)"], "answer": "ي sans points (ئ)", "acceptedAnswers": ["ي sans points (ئ)"], "explanation": "La hamza porte une kasra, la voyelle la plus forte : son support est un ي sans points, ئ. On lit 3â''ila.", "tip": "Hamza + kasra = support ي, sans points.", "extraExample": {"text": "رَئِيس", "translation": "président", "transliteration": "ra''îs"}, "errorPatterns": [{"equals": "و (ؤ)", "category": "grammar", "feedback": "Le و sert de support à une hamza avec damma. Ici la hamza a une kasra : ئ."}, {"equals": "ا (أ)", "category": "grammar", "feedback": "Le ا sert de support à une hamza avec fatha. Ici la hamza a une kasra : ئ."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e16', 'ar', 'ar.l14', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.umm']::text[], 'fill_blank', 'lesson', 'Dans أُمّ (umm), le م porte une ___.', array['shadda']::text[], 'Le petit w au-dessus du م est une shadda : le م est doublé, umm.', 2, '{"id": "ar.l14.e16", "unitIds": ["ar.g12.shadda", "ar.v.umm"], "type": "fill_blank", "difficulty": 2, "instruction": "Révision : complète avec le nom du signe.", "prompt": "Dans أُمّ (umm), le م porte une ___.", "promptLanguage": "fr", "options": ["shadda", "sukun", "damma", "fatha"], "answer": "shadda", "acceptedAnswers": ["shadda"], "explanation": "Le petit w au-dessus du م est une shadda : le م est doublé, umm.", "tip": "Petit w = lettre doublée.", "extraExample": {"text": "أُمَّة", "translation": "nation", "transliteration": "umma"}, "errorPatterns": [{"equals": "sukun", "category": "word_confusion", "feedback": "Le sukun est un petit rond. Ici, c''est un petit w : une shadda."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e17', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.madda']::text[], 'reorder', 'lesson', 'Écris « âbâ'' » (pères) en le découpant.', array['آ بَا ء']::text[], 'Â-bâ'' : la madda آ (â long), puis بَا (bâ, long), puis la hamza finale ء.', 2, '{"id": "ar.l14.e17", "unitIds": ["ar.g14.hamza_madda", "ar.v.madda"], "type": "reorder", "difficulty": 2, "instruction": "Touche les morceaux dans l''ordre de lecture (le premier d''abord).", "prompt": "Écris « âbâ'' » (pères) en le découpant.", "promptLanguage": "fr", "tokens": ["ء", "بَا", "آ"], "answer": "آ بَا ء", "acceptedAnswers": ["آ بَا ء"], "explanation": "Â-bâ'' : la madda آ (â long), puis بَا (bâ, long), puis la hamza finale ء.", "tip": "La madda ouvre le mot et compte pour un â long.", "extraExample": {"text": "آخِر", "translation": "dernier", "transliteration": "âkhir"}, "pool": "lesson", "lessonId": "ar.l14", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e18', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.ukht']::text[], 'reorder', 'lesson', 'Écris « ukht » (sœur).', array['أُ خْ ت']::text[], 'U-kht : أُ (hamza + damma), خْ (le خ avec sukun), puis ت.', 3, '{"id": "ar.l14.e18", "unitIds": ["ar.g14.hamza_madda", "ar.v.ukht"], "type": "reorder", "difficulty": 3, "instruction": "Touche les morceaux dans l''ordre de lecture (le premier d''abord).", "prompt": "Écris « ukht » (sœur).", "promptLanguage": "fr", "tokens": ["ت", "خْ", "أُ"], "answer": "أُ خْ ت", "acceptedAnswers": ["أُ خْ ت"], "explanation": "U-kht : أُ (hamza + damma), خْ (le خ avec sukun), puis ت.", "tip": "Un mot ne commence jamais par un sukun : la hamza porte la voyelle d''attaque.", "extraExample": {"text": "أُخْتَانِ", "translation": "deux sœurs", "transliteration": "ukhtâni"}, "pool": "lesson", "lessonId": "ar.l14", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e19', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.ab']::text[], 'translation', 'lesson', 'أَب', array['père','le père','un père','papa']::text[], 'أَب (ab) : le père. Ne le confonds pas avec أَخ (akh), le frère.', 2, '{"id": "ar.l14.e19", "unitIds": ["ar.g14.hamza_madda", "ar.v.ab"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "أَب", "promptLanguage": "ar", "answer": "père", "acceptedAnswers": ["père", "le père", "un père", "papa"], "explanation": "أَب (ab) : le père. Ne le confonds pas avec أَخ (akh), le frère.", "tip": "Ab = père (comme « baba »), akh = frère.", "extraExample": {"text": "أَبِي", "translation": "mon père", "transliteration": "abî"}, "errorPatterns": [{"equals": "frère", "category": "vocabulary", "feedback": "Le frère, c''est أَخ (akh). أَب (ab), c''est le père."}, {"equals": "le frère", "category": "vocabulary", "feedback": "Le frère, c''est أَخ (akh). أَب (ab), c''est le père."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e20', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.ukht']::text[], 'translation', 'lesson', 'أُخْت', array['sœur','la sœur','une sœur','soeur','la soeur','une soeur']::text[], 'أُخْت (ukht) : la sœur, le féminin de أَخ (akh).', 2, '{"id": "ar.l14.e20", "unitIds": ["ar.g14.hamza_madda", "ar.v.ukht"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "أُخْت", "promptLanguage": "ar", "answer": "sœur", "acceptedAnswers": ["sœur", "la sœur", "une sœur", "soeur", "la soeur", "une soeur"], "explanation": "أُخْت (ukht) : la sœur, le féminin de أَخ (akh).", "tip": "Akh, frère ; ukht, sœur.", "extraExample": {"text": "أُخْتِي", "translation": "ma sœur", "transliteration": "ukhtî"}, "errorPatterns": [{"equals": "frère", "category": "vocabulary", "feedback": "Le frère, c''est أَخ (akh), sans ت. أُخْت (ukht) est la sœur."}, {"equals": "mère", "category": "vocabulary", "feedback": "La mère, c''est أُمّ (umm). أُخْت (ukht), c''est la sœur."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e21', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.udhun']::text[], 'free_answer', 'lesson', 'Comment se lit أُذُن (oreille) ?', array['udhun','oudhoun']::text[], 'Hamza et damma sur le ا : u. Puis ذ avec damma (dhu) et ن final : u-dhun.', 3, '{"id": "ar.l14.e21", "unitIds": ["ar.g14.hamza_madda", "ar.v.udhun"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit أُذُن (oreille) ?", "promptLanguage": "fr", "answer": "udhun", "acceptedAnswers": ["udhun", "oudhoun"], "hint": "Le ذ se note dh.", "explanation": "Hamza et damma sur le ا : u. Puis ذ avec damma (dhu) et ن final : u-dhun.", "tip": "Deux dammas, donc deux u : u-dhun.", "extraExample": {"text": "أُذُنَانِ", "translation": "deux oreilles", "transliteration": "udhunâni"}, "errorPatterns": [{"equals": "adhun", "category": "word_confusion", "feedback": "Le premier signe est une damma (u), pas une fatha."}, {"equals": "udhn", "category": "spelling", "feedback": "Le ذ porte une damma : il faut un u entre le dh et le n."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e22', 'ar', 'ar.l14', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.v.aila']::text[], 'free_answer', 'lesson', 'Comment se lit عَائِلَة (famille) ?', array['3â''ila','3a''ila','3aila','3aa''ila']::text[], 'Fatha et ا sur le ع (3â, long), puis la hamza sur ئ avec une kasra (''i), ل avec fatha, et ة final muet : 3â-''i-la.', 4, '{"id": "ar.l14.e22", "unitIds": ["ar.g14.hamza_madda", "ar.v.aila"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit عَائِلَة (famille) ?", "promptLanguage": "fr", "answer": "3â''ila", "acceptedAnswers": ["3â''ila", "3a''ila", "3aila", "3aa''ila"], "hint": "La hamza se note ''.", "explanation": "Fatha et ا sur le ع (3â, long), puis la hamza sur ئ avec une kasra (''i), ل avec fatha, et ة final muet : 3â-''i-la.", "tip": "Entre 3â et ila, marque la hamza par un léger arrêt.", "extraExample": {"text": "عَائِلَتِي", "translation": "ma famille", "transliteration": "3â''ilatî"}, "errorPatterns": [{"equals": "3ayila", "category": "spelling", "feedback": "Le ئ n''est pas un ي : c''est une hamza sur son support, un coup de glotte ('') et non un y."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e01', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon']::text[], 'mcq', 'lesson', 'Comment se lit الْقَمَر (la lune) ?', array['al-qamar']::text[], 'Le ل porte un sukun : il se prononce. Le ق est une lettre lunaire, donc on lit al-qamar.', 1, '{"id": "ar.l15.e01", "unitIds": ["ar.g15.article_sun_moon"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit الْقَمَر (la lune) ?", "promptLanguage": "fr", "options": ["al-qamar", "aq-qamar", "qamar", "al-kamar"], "answer": "al-qamar", "acceptedAnswers": ["al-qamar"], "explanation": "Le ل porte un sukun : il se prononce. Le ق est une lettre lunaire, donc on lit al-qamar.", "tip": "ل avec sukun = on dit le l.", "extraExample": {"text": "الْقَلْب", "translation": "le cœur", "transliteration": "al-qalb"}, "errorPatterns": [{"equals": "aq-qamar", "category": "word_confusion", "feedback": "ق est une lettre lunaire : le l ne disparaît pas. Repère le sukun sur le ل."}, {"equals": "al-kamar", "category": "spelling", "feedback": "La lettre est un ق (q), pas un ك (k)."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e02', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon']::text[], 'mcq', 'lesson', 'Comment se lit الشَّمْس (le soleil) ?', array['ach-chams']::text[], 'ش est une lettre solaire : le ل s''écrit mais ne se prononce pas, et le ش porte une shadda (il est doublé). On lit ach-chams.', 1, '{"id": "ar.l15.e02", "unitIds": ["ar.g15.article_sun_moon"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit الشَّمْس (le soleil) ?", "promptLanguage": "fr", "options": ["ach-chams", "al-chams", "ach-chamas", "al-shams"], "answer": "ach-chams", "acceptedAnswers": ["ach-chams"], "explanation": "ش est une lettre solaire : le ل s''écrit mais ne se prononce pas, et le ش porte une shadda (il est doublé). On lit ach-chams.", "tip": "Soleil : le l disparaît, la lettre se double.", "extraExample": {"text": "الشَّجَرَة", "translation": "l''arbre", "transliteration": "ach-chadjara"}, "errorPatterns": [{"equals": "al-chams", "category": "word_confusion", "feedback": "ش est une lettre solaire : le ل ne se prononce pas. La shadda sur le ش te le signale."}, {"equals": "ach-chamas", "category": "spelling", "feedback": "Le م porte un sukun : pas de voyelle après lui, chams."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e03', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.v.dam','ar.v.usra','ar.v.saq']::text[], 'match', 'lesson', 'Soleil ou lune : lis le bon son', '{}'::text[], 'ش, د et س sont solaires : le l disparaît et la lettre est doublée (ach-chams, ad-dam, as-sâq). ق et أ sont lunaires : on garde le l (al-qamar, al-usra).', 1, '{"id": "ar.l15.e03", "unitIds": ["ar.g15.article_sun_moon", "ar.v.dam", "ar.v.usra", "ar.v.saq"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Soleil ou lune : lis le bon son", "promptLanguage": "fr", "pairs": [{"left": "الشَّمْس", "right": "ach-chams"}, {"left": "الْقَمَر", "right": "al-qamar"}, {"left": "الدَّم", "right": "ad-dam"}, {"left": "الْأُسْرَة", "right": "al-usra"}, {"left": "السَّاق", "right": "as-sâq"}], "answer": "الشَّمْس = ach-chams ; الْقَمَر = al-qamar ; الدَّم = ad-dam ; الْأُسْرَة = al-usra ; السَّاق = as-sâq", "acceptedAnswers": [], "explanation": "ش, د et س sont solaires : le l disparaît et la lettre est doublée (ach-chams, ad-dam, as-sâq). ق et أ sont lunaires : on garde le l (al-qamar, al-usra).", "tip": "Shadda sur la lettre = le l est absent ; sukun sur le ل = il est là.", "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e04', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon']::text[], 'mcq', 'lesson', 'Dans un texte vocalisé, quel indice montre que le ل de ال ne se prononce pas ?', array['la lettre suivante porte une shadda']::text[], 'Devant une lettre solaire, le ل n''a pas de sukun et la lettre suivante porte une shadda : c''est le signe qu''on ne dit pas le l.', 2, '{"id": "ar.l15.e04", "unitIds": ["ar.g15.article_sun_moon"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans un texte vocalisé, quel indice montre que le ل de ال ne se prononce pas ?", "promptLanguage": "fr", "options": ["la lettre suivante porte une shadda", "le ل porte un sukun", "le mot est féminin", "le mot finit par ة"], "answer": "la lettre suivante porte une shadda", "acceptedAnswers": ["la lettre suivante porte une shadda"], "explanation": "Devant une lettre solaire, le ل n''a pas de sukun et la lettre suivante porte une shadda : c''est le signe qu''on ne dit pas le l.", "tip": "Shadda juste après ال = pas de l.", "extraExample": {"text": "الدَّرْس", "translation": "la leçon", "transliteration": "ad-dars"}, "errorPatterns": [{"equals": "le ل porte un sukun", "category": "word_confusion", "feedback": "C''est l''inverse : un sukun sur le ل signale qu''on le prononce (lettre lunaire)."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e05', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon']::text[], 'fill_blank', 'lesson', 'Devant une lettre ___, le ل de l''article ne se prononce pas.', array['solaire']::text[], 'Les 14 lettres solaires (ت ث د ذ ر ز س ش ص ض ط ظ ل ن) absorbent le ل de l''article. Les 14 autres, les lunaires, le laissent se prononcer.', 1, '{"id": "ar.l15.e05", "unitIds": ["ar.g15.article_sun_moon"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète avec le bon mot.", "prompt": "Devant une lettre ___, le ل de l''article ne se prononce pas.", "promptLanguage": "fr", "options": ["solaire", "lunaire", "longue"], "answer": "solaire", "acceptedAnswers": ["solaire"], "explanation": "Les 14 lettres solaires (ت ث د ذ ر ز س ش ص ض ط ظ ل ن) absorbent le ل de l''article. Les 14 autres, les lunaires, le laissent se prononcer.", "tip": "Le soleil cache le l, la lune le laisse voir.", "extraExample": {"text": "الشَّمْس", "translation": "le soleil", "transliteration": "ach-chams"}, "errorPatterns": [{"equals": "lunaire", "category": "word_confusion", "feedback": "Devant une lettre lunaire, au contraire, le l se prononce : al-qamar."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e06', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon']::text[], 'fill_blank', 'lesson', 'Devant une lettre lunaire comme le ق, le ل de l''article porte un ___ et se prononce.', array['sukun']::text[], 'Le ل porte un sukun et se prononce : الْقَمَر = al-qamar. La lettre suivante n''est pas doublée.', 2, '{"id": "ar.l15.e06", "unitIds": ["ar.g15.article_sun_moon"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le nom du signe.", "prompt": "Devant une lettre lunaire comme le ق, le ل de l''article porte un ___ et se prononce.", "promptLanguage": "fr", "options": ["sukun", "shadda", "fatha"], "answer": "sukun", "acceptedAnswers": ["sukun"], "explanation": "Le ل porte un sukun et se prononce : الْقَمَر = al-qamar. La lettre suivante n''est pas doublée.", "tip": "Sukun sur le ل = on dit le l.", "extraExample": {"text": "الْبَاب", "translation": "la porte", "transliteration": "al-bâb"}, "errorPatterns": [{"equals": "shadda", "category": "word_confusion", "feedback": "La shadda se met sur la lettre solaire qui suit le ل, pas sur le ل lui-même."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e07', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.v.hadjib']::text[], 'mcq', 'lesson', 'Comment se lit الْحَاجِب (le sourcil) ?', array['al-7âdjib']::text[], 'ح est une lettre lunaire : le ل porte un sukun et se prononce. La fatha et le ا donnent un â long : al-7âdjib.', 2, '{"id": "ar.l15.e07", "unitIds": ["ar.g15.article_sun_moon", "ar.v.hadjib"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit الْحَاجِب (le sourcil) ?", "promptLanguage": "fr", "options": ["al-7âdjib", "a7-7âdjib", "al-7adjib", "ah-hâdjib"], "answer": "al-7âdjib", "acceptedAnswers": ["al-7âdjib"], "explanation": "ح est une lettre lunaire : le ل porte un sukun et se prononce. La fatha et le ا donnent un â long : al-7âdjib.", "tip": "ح fait partie des lunaires : ا ب ج ح خ ع غ ف ق ك م ه و ي.", "extraExample": {"text": "الْحُبّ", "translation": "l''amour", "transliteration": "al-7ubb"}, "errorPatterns": [{"equals": "a7-7âdjib", "category": "word_confusion", "feedback": "ح est lunaire : le ل se prononce. Ici, il porte un sukun."}, {"equals": "al-7adjib", "category": "spelling", "feedback": "Le ا après la fatha allonge le a : 7âdjib."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e08', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.v.chaar','ar.v.kaff','ar.v.hadjib','ar.v.usra']::text[], 'mcq', 'lesson', 'Lequel de ces mots a un ل qui ne se prononce pas ?', array['الشَّعْر']::text[], 'Dans الشَّعْر, le ش est solaire : le ل se tait et le ش est doublé (ach-cha3r). Les trois autres ont un ل avec sukun, qui se prononce.', 2, '{"id": "ar.l15.e08", "unitIds": ["ar.g15.article_sun_moon", "ar.v.chaar", "ar.v.kaff", "ar.v.hadjib", "ar.v.usra"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots a un ل qui ne se prononce pas ?", "promptLanguage": "fr", "options": ["الشَّعْر", "الْكَفّ", "الْحَاجِب", "الْأُسْرَة"], "answer": "الشَّعْر", "acceptedAnswers": ["الشَّعْر"], "explanation": "Dans الشَّعْر, le ش est solaire : le ل se tait et le ش est doublé (ach-cha3r). Les trois autres ont un ل avec sukun, qui se prononce.", "tip": "Cherche la shadda juste après ال.", "extraExample": {"text": "الرَّأْس", "translation": "la tête", "transliteration": "ar-ra''s"}, "errorPatterns": [{"equals": "الْكَفّ", "category": "word_confusion", "feedback": "Dans الْكَفّ, le ل porte un sukun : on dit al-kaff."}, {"equals": "الْحَاجِب", "category": "word_confusion", "feedback": "Dans الْحَاجِب, le ل porte un sukun : on dit al-7âdjib."}, {"equals": "الْأُسْرَة", "category": "word_confusion", "feedback": "Dans الْأُسْرَة, le ل porte un sukun : on dit al-usra."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e09', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.v.kaff','ar.v.saq','ar.v.dam','ar.v.dhaqn']::text[], 'mcq', 'lesson', 'Lequel de ces mots a un ل qui se prononce ?', array['الْكَفّ']::text[], 'Le ك est lunaire : le ل porte un sukun et se prononce, al-kaff. Dans السَّاق, الدَّم et الذَّقْن, la shadda remplace le ل : as-sâq, ad-dam, adh-dhaqn.', 2, '{"id": "ar.l15.e09", "unitIds": ["ar.g15.article_sun_moon", "ar.v.kaff", "ar.v.saq", "ar.v.dam", "ar.v.dhaqn"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots a un ل qui se prononce ?", "promptLanguage": "fr", "options": ["الْكَفّ", "السَّاق", "الدَّم", "الذَّقْن"], "answer": "الْكَفّ", "acceptedAnswers": ["الْكَفّ"], "explanation": "Le ك est lunaire : le ل porte un sukun et se prononce, al-kaff. Dans السَّاق, الدَّم et الذَّقْن, la shadda remplace le ل : as-sâq, ad-dam, adh-dhaqn.", "tip": "Sukun = on dit le l ; shadda = on ne le dit pas.", "extraExample": {"text": "الْكِتَاب", "translation": "le livre", "transliteration": "al-kitâb"}, "errorPatterns": [{"equals": "الدَّم", "category": "word_confusion", "feedback": "Dans الدَّم, le د est solaire : on dit ad-dam, sans l."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e10', 'ar', 'ar.l15', 'ar.v.walad', array['ar.v.walad','ar.g15.article_sun_moon']::text[], 'mcq', 'lesson', 'Comment se lit الْوَلَد (le garçon) ?', array['al-walad']::text[], 'و est une lettre lunaire : le ل porte un sukun et se prononce. Le w n''est pas doublé : al-walad.', 3, '{"id": "ar.l15.e10", "unitIds": ["ar.v.walad", "ar.g15.article_sun_moon"], "type": "mcq", "difficulty": 3, "instruction": "Révision : choisis la bonne lecture.", "prompt": "Comment se lit الْوَلَد (le garçon) ?", "promptLanguage": "fr", "options": ["al-walad", "aw-walad", "ul-walad", "a-walad"], "answer": "al-walad", "acceptedAnswers": ["al-walad"], "explanation": "و est une lettre lunaire : le ل porte un sukun et se prononce. Le w n''est pas doublé : al-walad.", "tip": "Le و n''est pas solaire : le l reste.", "extraExample": {"text": "الْوَجْه", "translation": "le visage", "transliteration": "al-wadjh"}, "errorPatterns": [{"equals": "aw-walad", "category": "word_confusion", "feedback": "و est lunaire, pas solaire : le l ne disparaît pas."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e11', 'ar', 'ar.l15', 'ar.v.tabib', array['ar.v.tabib','ar.g15.article_sun_moon']::text[], 'mcq', 'lesson', 'Comment se lit الطَّبِيب (le médecin) ?', array['aT-Tabîb']::text[], 'ط est une lettre solaire : le ل ne se prononce pas et le ط est doublé, aT-Tabîb. Le ي après la kasra est long.', 3, '{"id": "ar.l15.e11", "unitIds": ["ar.v.tabib", "ar.g15.article_sun_moon"], "type": "mcq", "difficulty": 3, "instruction": "Révision : choisis la bonne lecture.", "prompt": "Comment se lit الطَّبِيب (le médecin) ?", "promptLanguage": "fr", "options": ["aT-Tabîb", "al-Tabîb", "a-Tabîb"], "answer": "aT-Tabîb", "acceptedAnswers": ["aT-Tabîb"], "explanation": "ط est une lettre solaire : le ل ne se prononce pas et le ط est doublé, aT-Tabîb. Le ي après la kasra est long.", "tip": "ط fait partie des solaires : ت ث د ذ ر ز س ش ص ض ط ظ ل ن.", "extraExample": {"text": "الطَّالِب", "translation": "l''étudiant", "transliteration": "aT-Tâlib"}, "errorPatterns": [{"equals": "al-Tabîb", "category": "word_confusion", "feedback": "ط est solaire : le l disparaît et le ط se double."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e12', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.v.imraa']::text[], 'mcq', 'lesson', 'Comment s''écrit « la femme » (al-mar''a) avec l''article ?', array['الْمَرْأَة']::text[], 'Avec l''article, اِمْرَأَة perd son ا initial : on écrit الْمَرْأَة (al-mar''a), et non « al-imra''a ».', 4, '{"id": "ar.l15.e12", "unitIds": ["ar.g15.article_sun_moon", "ar.v.imraa"], "type": "mcq", "difficulty": 4, "instruction": "Choisis la bonne écriture.", "prompt": "Comment s''écrit « la femme » (al-mar''a) avec l''article ?", "promptLanguage": "fr", "options": ["الْمَرْأَة", "الْاِمْرَأَة", "اِلْمَرْأَة", "الْإِمْرَأَة"], "answer": "الْمَرْأَة", "acceptedAnswers": ["الْمَرْأَة"], "explanation": "Avec l''article, اِمْرَأَة perd son ا initial : on écrit الْمَرْأَة (al-mar''a), et non « al-imra''a ».", "tip": "Le ا initial de اِمْرَأَة tombe après ال.", "extraExample": {"text": "الْمَرْأَةُ", "translation": "la femme", "transliteration": "al-mar''atu"}, "errorPatterns": [{"equals": "الْاِمْرَأَة", "category": "spelling", "feedback": "Le ا initial de اِمْرَأَة disparaît après ال : on n''écrit pas deux ا à la suite."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e13', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.v.lihya','ar.v.hadjib','ar.v.usra','ar.v.saq','ar.v.dhaqn']::text[], 'match', 'lesson', 'Barbe, sourcil, famille, jambe et menton', '{}'::text[], 'اللِّحْيَة (al-li7ya) = la barbe, الْحَاجِب (al-7âdjib) = le sourcil, الْأُسْرَة (al-usra) = la famille, السَّاق (as-sâq) = la jambe, الذَّقْن (adh-dhaqn) = le menton.', 2, '{"id": "ar.l15.e13", "unitIds": ["ar.g15.article_sun_moon", "ar.v.lihya", "ar.v.hadjib", "ar.v.usra", "ar.v.saq", "ar.v.dhaqn"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Barbe, sourcil, famille, jambe et menton", "promptLanguage": "fr", "pairs": [{"left": "اللِّحْيَة", "right": "la barbe"}, {"left": "الْحَاجِب", "right": "le sourcil"}, {"left": "الْأُسْرَة", "right": "la famille"}, {"left": "السَّاق", "right": "la jambe"}, {"left": "الذَّقْن", "right": "le menton"}], "answer": "اللِّحْيَة = la barbe ; الْحَاجِب = le sourcil ; الْأُسْرَة = la famille ; السَّاق = la jambe ; الذَّقْن = le menton", "acceptedAnswers": [], "explanation": "اللِّحْيَة (al-li7ya) = la barbe, الْحَاجِب (al-7âdjib) = le sourcil, الْأُسْرَة (al-usra) = la famille, السَّاق (as-sâq) = la jambe, الذَّقْن (adh-dhaqn) = le menton.", "tip": "Retire ال, il reste le mot : لِحْيَة, حَاجِب, أُسْرَة, سَاق, ذَقْن.", "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e14', 'ar', 'ar.l15', 'ar.v.qalb', array['ar.v.qalb','ar.g15.article_sun_moon','ar.v.wadjh','ar.v.nisa','ar.v.radjul']::text[], 'match', 'lesson', 'Lune ou soleil : le mot entier', '{}'::text[], 'ر, ن et ط sont solaires (ar-radjul, an-nisâ'', aT-Tifl) ; ق et و sont lunaires (al-qalb, al-wadjh).', 3, '{"id": "ar.l15.e14", "unitIds": ["ar.v.qalb", "ar.g15.article_sun_moon", "ar.v.wadjh", "ar.v.nisa", "ar.v.radjul"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lune ou soleil : le mot entier", "promptLanguage": "fr", "pairs": [{"left": "الْقَلْب", "right": "al-qalb"}, {"left": "الرَّجُل", "right": "ar-radjul"}, {"left": "الْوَجْه", "right": "al-wadjh"}, {"left": "النِّسَاء", "right": "an-nisâ''"}, {"left": "الطِّفْل", "right": "aT-Tifl"}], "answer": "الْقَلْب = al-qalb ; الرَّجُل = ar-radjul ; الْوَجْه = al-wadjh ; النِّسَاء = an-nisâ'' ; الطِّفْل = aT-Tifl", "acceptedAnswers": [], "explanation": "ر, ن et ط sont solaires (ar-radjul, an-nisâ'', aT-Tifl) ; ق et و sont lunaires (al-qalb, al-wadjh).", "tip": "Regarde la shadda : s''il y en a une, le l disparaît.", "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e15', 'ar', 'ar.l15', 'ar.g12.shadda', array['ar.g12.shadda','ar.v.dam']::text[], 'fill_blank', 'lesson', 'Dans الدَّم (ad-dam), c''est la ___ sur le د qui remplace le ل.', array['shadda']::text[], 'Le ل ne se prononce pas : à sa place, le د est doublé par la shadda. On lit ad-dam.', 3, '{"id": "ar.l15.e15", "unitIds": ["ar.g12.shadda", "ar.v.dam"], "type": "fill_blank", "difficulty": 3, "instruction": "Révision : complète avec le nom du signe.", "prompt": "Dans الدَّم (ad-dam), c''est la ___ sur le د qui remplace le ل.", "promptLanguage": "fr", "options": ["shadda", "sukun", "fatha"], "answer": "shadda", "acceptedAnswers": ["shadda"], "explanation": "Le ل ne se prononce pas : à sa place, le د est doublé par la shadda. On lit ad-dam.", "tip": "Shadda = lettre doublée = trace du ل absent.", "extraExample": {"text": "الذَّقْن", "translation": "le menton", "transliteration": "adh-dhaqn"}, "errorPatterns": [{"equals": "sukun", "category": "word_confusion", "feedback": "Le sukun indiquerait qu''on prononce le ل (lettre lunaire). Ici, c''est une shadda."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e16', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.v.usra']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : la famille / dans / la maison', array['الْأُسْرَةُ فِي الْبَيْتِ']::text[], 'Al-usratu fî l-bayti : le sujet avec ال vient d''abord, puis la préposition فِي et le lieu.', 2, '{"id": "ar.l15.e16", "unitIds": ["ar.g15.article_sun_moon", "ar.v.usra"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre de lecture (le premier d''abord).", "prompt": "Remets dans l''ordre : la famille / dans / la maison", "promptLanguage": "fr", "tokens": ["فِي", "الْبَيْتِ", "الْأُسْرَةُ"], "answer": "الْأُسْرَةُ فِي الْبَيْتِ", "acceptedAnswers": ["الْأُسْرَةُ فِي الْبَيْتِ"], "explanation": "Al-usratu fî l-bayti : le sujet avec ال vient d''abord, puis la préposition فِي et le lieu.", "tip": "Dans l''ordre : sujet, فِي, lieu.", "extraExample": {"text": "الْوَلَدُ فِي الْبَيْتِ", "translation": "le garçon est à la maison", "transliteration": "al-waladu fî l-bayti"}, "pool": "lesson", "lessonId": "ar.l15", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e17', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.v.sadr']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : une douleur / dans / la poitrine', array['أَلَمٌ فِي الصَّدْرِ']::text[], 'Alamun fî S-Sadri : أَلَمٌ a un tanwin (indéfini), الصَّدْرِ a l''article (défini). Le ص est solaire, d''où la shadda.', 3, '{"id": "ar.l15.e17", "unitIds": ["ar.g15.article_sun_moon", "ar.v.sadr"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre de lecture (le premier d''abord).", "prompt": "Remets dans l''ordre : une douleur / dans / la poitrine", "promptLanguage": "fr", "tokens": ["فِي", "الصَّدْرِ", "أَلَمٌ"], "answer": "أَلَمٌ فِي الصَّدْرِ", "acceptedAnswers": ["أَلَمٌ فِي الصَّدْرِ"], "explanation": "Alamun fî S-Sadri : أَلَمٌ a un tanwin (indéfini), الصَّدْرِ a l''article (défini). Le ص est solaire, d''où la shadda.", "tip": "Tanwin pour « un », ال pour « le ».", "extraExample": {"text": "أَلَمٌ فِي الظَّهْرِ", "translation": "une douleur dans le dos", "transliteration": "alamun fî Z-Zahri"}, "pool": "lesson", "lessonId": "ar.l15", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e18', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.v.dam']::text[], 'translation', 'lesson', 'الدَّم', array['le sang','sang','du sang']::text[], 'الدَّم (ad-dam) : le sang. Le د est solaire, donc le ل ne se prononce pas.', 2, '{"id": "ar.l15.e18", "unitIds": ["ar.g15.article_sun_moon", "ar.v.dam"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "الدَّم", "promptLanguage": "ar", "answer": "le sang", "acceptedAnswers": ["le sang", "sang", "du sang"], "explanation": "الدَّم (ad-dam) : le sang. Le د est solaire, donc le ل ne se prononce pas.", "tip": "Ad-dam : un seul mot, deux d.", "extraExample": {"text": "فَحْصُ الدَّمِ", "translation": "l''analyse de sang", "transliteration": "fa7Su d-dami"}, "errorPatterns": [{"equals": "le cœur", "category": "vocabulary", "feedback": "Le cœur, c''est الْقَلْب (al-qalb). الدَّم (ad-dam), c''est le sang."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e19', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.v.chaar']::text[], 'translation', 'lesson', 'الشَّعْر', array['les cheveux','cheveux','la chevelure']::text[], 'الشَّعْر (ach-cha3r) : les cheveux. En arabe, c''est un mot au singulier qui désigne l''ensemble. Le ش est solaire.', 3, '{"id": "ar.l15.e19", "unitIds": ["ar.g15.article_sun_moon", "ar.v.chaar"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "الشَّعْر", "promptLanguage": "ar", "answer": "les cheveux", "acceptedAnswers": ["les cheveux", "cheveux", "la chevelure"], "explanation": "الشَّعْر (ach-cha3r) : les cheveux. En arabe, c''est un mot au singulier qui désigne l''ensemble. Le ش est solaire.", "tip": "Ach-cha3r : le l disparaît, le ch se double.", "extraExample": {"text": "الشَّعْرُ الْأَسْوَدُ", "translation": "les cheveux noirs", "transliteration": "ach-cha3ru l-aswadu"}, "errorPatterns": [{"equals": "la barbe", "category": "vocabulary", "feedback": "La barbe, c''est اللِّحْيَة (al-li7ya). الشَّعْر (ach-cha3r), ce sont les cheveux."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e20', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.v.saq']::text[], 'free_answer', 'lesson', 'Comment se lit السَّاق (la jambe) ?', array['as-sâq','as-saq','as-saaq','assâq','assaq','as saq']::text[], 'Le س est solaire : le ل ne se prononce pas et le س est doublé, as-sâq. Le â long vient du ا après la fatha.', 3, '{"id": "ar.l15.e20", "unitIds": ["ar.g15.article_sun_moon", "ar.v.saq"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit السَّاق (la jambe) ?", "promptLanguage": "fr", "answer": "as-sâq", "acceptedAnswers": ["as-sâq", "as-saq", "as-saaq", "assâq", "assaq", "as saq"], "hint": "Le ل de l''article disparaît.", "explanation": "Le س est solaire : le ل ne se prononce pas et le س est doublé, as-sâq. Le â long vient du ا après la fatha.", "tip": "Deux s de suite : as-sâq.", "extraExample": {"text": "السَّاقُ الْيُمْنَى", "translation": "la jambe droite", "transliteration": "as-sâqu l-yumnâ"}, "errorPatterns": [{"equals": "al-sâq", "category": "word_confusion", "feedback": "س est solaire : le ل ne se prononce pas. On dit as-sâq."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e21', 'ar', 'ar.l15', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.v.dhaqn']::text[], 'free_answer', 'lesson', 'Comment se lit الذَّقْن (le menton) ?', array['adh-dhaqn','adhdhaqn','adh dhaqn']::text[], 'Le ذ est solaire : le ل ne se prononce pas et le ذ (dh) est doublé : adh-dhaqn.', 4, '{"id": "ar.l15.e21", "unitIds": ["ar.g15.article_sun_moon", "ar.v.dhaqn"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit الذَّقْن (le menton) ?", "promptLanguage": "fr", "answer": "adh-dhaqn", "acceptedAnswers": ["adh-dhaqn", "adhdhaqn", "adh dhaqn"], "hint": "Le ذ se note dh.", "explanation": "Le ذ est solaire : le ل ne se prononce pas et le ذ (dh) est doublé : adh-dhaqn.", "tip": "Dh doublé : adh-dhaqn.", "extraExample": {"text": "ذَقْنُ الرَّجُلِ", "translation": "le menton de l''homme", "transliteration": "dhaqnu r-radjuli"}, "errorPatterns": [{"equals": "al-dhaqn", "category": "word_confusion", "feedback": "ذ est solaire : le ل ne se prononce pas."}], "pool": "lesson", "lessonId": "ar.l15", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e01', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.g11.long_vowels']::text[], 'mcq', 'lesson', 'Quelles lettres t''aident le plus à lire un mot sans voyelles ?', array['ا و ي (les voyelles longues)']::text[], 'Les voyelles brèves ne sont pas écrites, mais les voyelles longues le sont : ا, و et ي restent visibles et servent de points d''appui. Dans كتاب, le ا te dit : voyelle longue au milieu, donc kitâb.', 1, '{"id": "ar.l16.e01", "unitIds": ["ar.g16.reading_unvowelled", "ar.g11.long_vowels"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelles lettres t''aident le plus à lire un mot sans voyelles ?", "promptLanguage": "fr", "options": ["ا و ي (les voyelles longues)", "les points des lettres", "les lettres finales", "la première lettre"], "answer": "ا و ي (les voyelles longues)", "acceptedAnswers": ["ا و ي (les voyelles longues)"], "explanation": "Les voyelles brèves ne sont pas écrites, mais les voyelles longues le sont : ا, و et ي restent visibles et servent de points d''appui. Dans كتاب, le ا te dit : voyelle longue au milieu, donc kitâb.", "tip": "Cherche d''abord les ا و ي.", "extraExample": {"text": "كتاب", "translation": "livre (vocalisé : كِتَاب)", "transliteration": "kitâb"}, "errorPatterns": [{"equals": "les points des lettres", "category": "word_confusion", "feedback": "Les points distinguent les lettres entre elles (ب ت ث), mais ils ne donnent aucune voyelle."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e02', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled']::text[], 'fill_blank', 'lesson', 'Dans un texte sans voyelles, les voyelles ___ ne sont pas écrites.', array['brèves']::text[], 'Les voyelles brèves (fatha, kasra, damma) disparaissent. Les voyelles longues, elles, restent écrites avec ا و ي.', 1, '{"id": "ar.l16.e02", "unitIds": ["ar.g16.reading_unvowelled"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète avec le bon mot.", "prompt": "Dans un texte sans voyelles, les voyelles ___ ne sont pas écrites.", "promptLanguage": "fr", "options": ["brèves", "longues", "doublées"], "answer": "brèves", "acceptedAnswers": ["brèves"], "explanation": "Les voyelles brèves (fatha, kasra, damma) disparaissent. Les voyelles longues, elles, restent écrites avec ا و ي.", "tip": "Brèves absentes, longues présentes.", "extraExample": {"text": "صديق", "translation": "ami (vocalisé : صَدِيق)", "transliteration": "Sadîq"}, "errorPatterns": [{"equals": "longues", "category": "word_confusion", "feedback": "Au contraire : ا و ي restent écrits, ce sont les voyelles brèves qui manquent."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e03', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.v.ism']::text[], 'mcq', 'lesson', 'Comment se lit اسم (nom, prénom) ?', array['ism']::text[], 'La forme vocalisée est اِسْم : kasra sur le ا, sukun sur le س. On lit ism. C''est un mot très courant, à reconnaître comme une image.', 1, '{"id": "ar.l16.e03", "unitIds": ["ar.g16.reading_unvowelled", "ar.v.ism"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit اسم (nom, prénom) ?", "promptLanguage": "fr", "options": ["ism", "asm", "isim", "âsm"], "answer": "ism", "acceptedAnswers": ["ism"], "explanation": "La forme vocalisée est اِسْم : kasra sur le ا, sukun sur le س. On lit ism. C''est un mot très courant, à reconnaître comme une image.", "tip": "Mot courant = image : اسم → ism.", "extraExample": {"text": "اسمي", "translation": "mon nom (vocalisé : اِسْمِي)", "transliteration": "ismî"}, "errorPatterns": [{"equals": "asm", "category": "word_confusion", "feedback": "Dans اِسْم, le ا porte une kasra : i. On lit ism."}, {"equals": "isim", "category": "spelling", "feedback": "Il n''y a pas de voyelle entre le س et le م : ism."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e04', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.v.zamil']::text[], 'mcq', 'lesson', 'Comment se lit زميل (collègue) ?', array['zamîl']::text[], 'Le ي au milieu du mot est une voyelle longue visible : zamîl. Les voyelles brèves (deux fathas) se devinent, comme dans صديق et طبيب.', 2, '{"id": "ar.l16.e04", "unitIds": ["ar.g16.reading_unvowelled", "ar.v.zamil"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit زميل (collègue) ?", "promptLanguage": "fr", "options": ["zamîl", "zamil", "zumîl", "zamâl"], "answer": "zamîl", "acceptedAnswers": ["zamîl"], "explanation": "Le ي au milieu du mot est une voyelle longue visible : zamîl. Les voyelles brèves (deux fathas) se devinent, comme dans صديق et طبيب.", "tip": "Un ي entre deux consonnes, après une kasra : î.", "extraExample": {"text": "زميلة", "translation": "collègue (femme) (vocalisé : زَمِيلَة)", "transliteration": "zamîla"}, "errorPatterns": [{"equals": "zamil", "category": "word_confusion", "feedback": "Le ي visible est une voyelle longue : zamîl, avec un î tenu."}, {"equals": "zamâl", "category": "word_confusion", "feedback": "La lettre longue est un ي, pas un ا : î et non â."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e05', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.v.fatat']::text[], 'mcq', 'lesson', 'Que signale le ة à la fin de فتاة (jeune fille) ?', array['un mot féminin']::text[], 'Le ة final est très souvent la marque du féminin : فتاة (la jeune fille), طالبة (l''étudiante), زوجة (l''épouse).', 2, '{"id": "ar.l16.e05", "unitIds": ["ar.g16.reading_unvowelled", "ar.v.fatat"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que signale le ة à la fin de فتاة (jeune fille) ?", "promptLanguage": "fr", "options": ["un mot féminin", "un mot pluriel", "un verbe", "un mot masculin"], "answer": "un mot féminin", "acceptedAnswers": ["un mot féminin"], "explanation": "Le ة final est très souvent la marque du féminin : فتاة (la jeune fille), طالبة (l''étudiante), زوجة (l''épouse).", "tip": "ة final = féminin (en général).", "extraExample": {"text": "طالبة", "translation": "étudiante (vocalisé : طَالِبَة)", "transliteration": "Tâliba"}, "errorPatterns": [{"equals": "un mot masculin", "category": "grammar", "feedback": "Au contraire : le ة final marque en général le féminin."}, {"equals": "un mot pluriel", "category": "grammar", "feedback": "Le pluriel s''écrit avec d''autres terminaisons, comme ـات ou ـون. Le ة final indique le féminin singulier."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e06', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.v.walad','ar.v.bint','ar.v.kitab','ar.v.ayn_oeil','ar.v.qalb']::text[], 'match', 'lesson', 'Du mot nu au mot vocalisé', '{}'::text[], 'Dans chaque paire, ce sont les mêmes lettres : on ajoute seulement les signes (harakat). Les ا و ي restent visibles dans les deux écritures.', 2, '{"id": "ar.l16.e06", "unitIds": ["ar.g16.reading_unvowelled", "ar.v.walad", "ar.v.bint", "ar.v.kitab", "ar.v.ayn_oeil", "ar.v.qalb"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot sans voyelles à sa forme vocalisée.", "prompt": "Du mot nu au mot vocalisé", "promptLanguage": "fr", "pairs": [{"left": "ولد", "right": "وَلَد"}, {"left": "بنت", "right": "بِنْت"}, {"left": "كتاب", "right": "كِتَاب"}, {"left": "عين", "right": "عَيْن"}, {"left": "قلب", "right": "قَلْب"}], "answer": "ولد = وَلَد ; بنت = بِنْت ; كتاب = كِتَاب ; عين = عَيْن ; قلب = قَلْب", "acceptedAnswers": [], "explanation": "Dans chaque paire, ce sont les mêmes lettres : on ajoute seulement les signes (harakat). Les ا و ي restent visibles dans les deux écritures.", "tip": "Compare les squelettes lettre par lettre.", "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e07', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.v.hafid','ar.v.zamil','ar.v.fatat','ar.v.insan','ar.v.azm']::text[], 'match', 'lesson', 'Cinq mots sans voyelles', '{}'::text[], 'Les ا و ي visibles te guident : حفيد (7afîd), زميل (zamîl), فتاة (fatâ), إنسان (insân). Pour عظم (3aZm), aucune lettre longue ne t''aide : il faut connaître le mot.', 2, '{"id": "ar.l16.e07", "unitIds": ["ar.g16.reading_unvowelled", "ar.v.hafid", "ar.v.zamil", "ar.v.fatat", "ar.v.insan", "ar.v.azm"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Cinq mots sans voyelles", "promptLanguage": "fr", "pairs": [{"left": "حفيد", "right": "7afîd"}, {"left": "زميل", "right": "zamîl"}, {"left": "فتاة", "right": "fatâ"}, {"left": "إنسان", "right": "insân"}, {"left": "عظم", "right": "3aZm"}], "answer": "حفيد = 7afîd ; زميل = zamîl ; فتاة = fatâ ; إنسان = insân ; عظم = 3aZm", "acceptedAnswers": [], "explanation": "Les ا و ي visibles te guident : حفيد (7afîd), زميل (zamîl), فتاة (fatâ), إنسان (insân). Pour عظم (3aZm), aucune lettre longue ne t''aide : il faut connaître le mot.", "tip": "Un mot connu se lit comme une image.", "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e08', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.v.chabb','ar.v.rukba','ar.v.ism','ar.v.azm','ar.v.fatat']::text[], 'match', 'lesson', 'Lire et comprendre sans voyelles', '{}'::text[], 'شاب (châbb) = le jeune homme, ركبة (rukba) = le genou, اسم (ism) = le nom, عظم (3aZm) = l''os, فتاة (fatâ) = la jeune fille.', 3, '{"id": "ar.l16.e08", "unitIds": ["ar.g16.reading_unvowelled", "ar.v.chabb", "ar.v.rukba", "ar.v.ism", "ar.v.azm", "ar.v.fatat"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Lire et comprendre sans voyelles", "promptLanguage": "fr", "pairs": [{"left": "شاب", "right": "le jeune homme"}, {"left": "ركبة", "right": "le genou"}, {"left": "اسم", "right": "le nom"}, {"left": "عظم", "right": "l''os"}, {"left": "فتاة", "right": "la jeune fille"}], "answer": "شاب = le jeune homme ; ركبة = le genou ; اسم = le nom ; عظم = l''os ; فتاة = la jeune fille", "acceptedAnswers": [], "explanation": "شاب (châbb) = le jeune homme, ركبة (rukba) = le genou, اسم (ism) = le nom, عظم (3aZm) = l''os, فتاة (fatâ) = la jeune fille.", "tip": "Le ة de ركبة et فتاة signale deux mots féminins.", "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e09', 'ar', 'ar.l16', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.g16.reading_unvowelled']::text[], 'mcq', 'lesson', 'Comment se lit الشمس (sans voyelles) ?', array['ach-chams']::text[], 'ش est une lettre solaire : même sans signes, on sait que le ل de ال se tait et que le ش est doublé. On lit ach-chams.', 3, '{"id": "ar.l16.e09", "unitIds": ["ar.g15.article_sun_moon", "ar.g16.reading_unvowelled"], "type": "mcq", "difficulty": 3, "instruction": "Révision : choisis la bonne lecture.", "prompt": "Comment se lit الشمس (sans voyelles) ?", "promptLanguage": "fr", "options": ["ach-chams", "al-chams", "ach-chimas"], "answer": "ach-chams", "acceptedAnswers": ["ach-chams"], "explanation": "ش est une lettre solaire : même sans signes, on sait que le ل de ال se tait et que le ش est doublé. On lit ach-chams.", "tip": "Repère ال, puis regarde si la lettre suivante est solaire.", "extraExample": {"text": "القمر", "translation": "la lune (vocalisé : الْقَمَر)", "transliteration": "al-qamar"}, "errorPatterns": [{"equals": "al-chams", "category": "word_confusion", "feedback": "ش est solaire : le ل ne se prononce pas, même quand les signes ne sont pas écrits."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e10', 'ar', 'ar.l16', 'ar.g11.long_vowels', array['ar.g11.long_vowels','ar.v.zawdj']::text[], 'mcq', 'lesson', 'Comment se lit زوج (mari) ?', array['zawdj']::text[], 'Le و peut être un û long ou la diphtongue aw : sans signes, il faut connaître le mot. زوج se lit zawdj, comme dans زوجة (zawdja).', 3, '{"id": "ar.l16.e10", "unitIds": ["ar.g11.long_vowels", "ar.v.zawdj"], "type": "mcq", "difficulty": 3, "instruction": "Révision : choisis la bonne lecture.", "prompt": "Comment se lit زوج (mari) ?", "promptLanguage": "fr", "options": ["zawdj", "zûdj", "zâdj", "zawadj"], "answer": "zawdj", "acceptedAnswers": ["zawdj"], "explanation": "Le و peut être un û long ou la diphtongue aw : sans signes, il faut connaître le mot. زوج se lit zawdj, comme dans زوجة (zawdja).", "tip": "و et ي entre deux consonnes : mémorise le mot.", "extraExample": {"text": "عين", "translation": "œil (vocalisé : عَيْن)", "transliteration": "3ayn"}, "errorPatterns": [{"equals": "zûdj", "category": "word_confusion", "feedback": "Le و n''est pas toujours un û : ici c''est la diphtongue aw, zawdj, comme dans زوجة."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e11', 'ar', 'ar.l16', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.tabib']::text[], 'mcq', 'lesson', 'Dans « رأيت طبيبا » (j''ai vu un médecin), à quoi sert le ا final ?', array['c''est l''alif muet du tanwin -an : Tabîban']::text[], 'Le signe du tanwin disparaît dans un texte sans voyelles, mais l''alif qui le porte reste écrit. On lit ra''aytu Tabîban : le ا final est muet.', 3, '{"id": "ar.l16.e11", "unitIds": ["ar.g13.tanwin", "ar.v.tabib"], "type": "mcq", "difficulty": 3, "instruction": "Révision : choisis la bonne réponse.", "prompt": "Dans « رأيت طبيبا » (j''ai vu un médecin), à quoi sert le ا final ?", "promptLanguage": "fr", "options": ["c''est l''alif muet du tanwin -an : Tabîban", "il allonge la voyelle : Tabîbâ", "il marque le féminin", "il marque l''article"], "answer": "c''est l''alif muet du tanwin -an : Tabîban", "acceptedAnswers": ["c''est l''alif muet du tanwin -an : Tabîban"], "explanation": "Le signe du tanwin disparaît dans un texte sans voyelles, mais l''alif qui le porte reste écrit. On lit ra''aytu Tabîban : le ا final est muet.", "tip": "Un ا final après un nom indéfini : souvent le tanwin -an.", "extraExample": {"text": "رأيت ولدا", "translation": "j''ai vu un garçon (vocalisé : رَأَيْتُ وَلَدًا)", "transliteration": "ra''aytu waladan"}, "errorPatterns": [{"equals": "il allonge la voyelle : Tabîbâ", "category": "word_confusion", "feedback": "Le ا après le tanwin -an est muet : on lit Tabîban, pas Tabîbâ."}, {"equals": "il marque le féminin", "category": "grammar", "feedback": "Le féminin se marque avec un ة. طبيب reste masculin."}, {"equals": "il marque l''article", "category": "grammar", "feedback": "L''article, c''est ال au début du mot. Ici le ا final est l''alif du tanwin -an."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e12', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled']::text[], 'mcq', 'lesson', 'Dans la phrase « كتب الولد الدرس » (le garçon a écrit la leçon), comment se lit كتب ?', array['kataba']::text[], 'Sans voyelles, كتب peut être kataba (il a écrit), kutiba (il a été écrit) ou kutub (des livres). Ici le verbe est suivi de « le garçon » et « la leçon » : c''est « il a écrit ».', 3, '{"id": "ar.l16.e12", "unitIds": ["ar.g16.reading_unvowelled"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lecture.", "prompt": "Dans la phrase « كتب الولد الدرس » (le garçon a écrit la leçon), comment se lit كتب ?", "promptLanguage": "fr", "options": ["kataba", "kutiba", "kutub"], "answer": "kataba", "acceptedAnswers": ["kataba"], "explanation": "Sans voyelles, كتب peut être kataba (il a écrit), kutiba (il a été écrit) ou kutub (des livres). Ici le verbe est suivi de « le garçon » et « la leçon » : c''est « il a écrit ».", "tip": "Quand plusieurs lectures sont possibles, la phrase choisit.", "extraExample": {"text": "كتب الدرس", "translation": "il a écrit la leçon (vocalisé : كَتَبَ الدَّرْسَ)", "transliteration": "kataba d-darsa"}, "errorPatterns": [{"equals": "kutiba", "category": "grammar", "feedback": "« Kutiba » (il a été écrit) ne peut pas avoir « le garçon » comme auteur de l''action : on dirait plutôt « la leçon a été écrite »."}, {"equals": "kutub", "category": "grammar", "feedback": "« Kutub » est un nom (des livres) : ici, c''est un verbe, le garçon écrit la leçon."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e13', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled']::text[], 'mcq', 'lesson', 'Dans « هذه كتب » (ce sont des livres), comment se lit كتب ?', array['kutub']::text[], 'Après « هذه » (ceci), on attend un nom : كتب est le pluriel de كتاب, kutub (des livres).', 4, '{"id": "ar.l16.e13", "unitIds": ["ar.g16.reading_unvowelled"], "type": "mcq", "difficulty": 4, "instruction": "Choisis la bonne lecture.", "prompt": "Dans « هذه كتب » (ce sont des livres), comment se lit كتب ?", "promptLanguage": "fr", "options": ["kutub", "kataba", "kutiba", "kitâb"], "answer": "kutub", "acceptedAnswers": ["kutub"], "explanation": "Après « هذه » (ceci), on attend un nom : كتب est le pluriel de كتاب, kutub (des livres).", "tip": "Un nom après « voici », un verbe après un sujet.", "extraExample": {"text": "كتب جديدة", "translation": "des livres neufs (vocalisé : كُتُبٌ جَدِيدَةٌ)", "transliteration": "kutubun djadîdatun"}, "errorPatterns": [{"equals": "kataba", "category": "grammar", "feedback": "Après « ceci », on attend un nom, pas un verbe : kutub, des livres."}, {"equals": "kitâb", "category": "word_confusion", "feedback": "Il n''y a pas de ا dans كتب : ce n''est pas kitâb (un livre) mais kutub (des livres)."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e14', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled']::text[], 'fill_blank', 'lesson', 'Quand un mot sans voyelles a plusieurs lectures possibles, c''est la ___ qui choisit.', array['phrase']::text[], 'Un même squelette peut se lire de plusieurs façons (كتب : kataba, kutiba, kutub). Le sens de la phrase décide.', 2, '{"id": "ar.l16.e14", "unitIds": ["ar.g16.reading_unvowelled"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "Quand un mot sans voyelles a plusieurs lectures possibles, c''est la ___ qui choisit.", "promptLanguage": "fr", "options": ["phrase", "dernière lettre", "première lettre"], "answer": "phrase", "acceptedAnswers": ["phrase"], "explanation": "Un même squelette peut se lire de plusieurs façons (كتب : kataba, kutiba, kutub). Le sens de la phrase décide.", "tip": "Le contexte est ton meilleur indice.", "extraExample": {"text": "علم", "translation": "science, savoir (vocalisé : عِلْم)", "transliteration": "3ilm"}, "errorPatterns": [{"equals": "dernière lettre", "category": "word_confusion", "feedback": "La dernière lettre ne suffit pas à choisir : c''est le sens de la phrase qui tranche."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e15', 'ar', 'ar.l16', 'ar.g15.article_sun_moon', array['ar.g15.article_sun_moon','ar.g16.reading_unvowelled']::text[], 'fill_blank', 'lesson', 'Au début d''un mot sans voyelles, ال signale l''___ défini (le, la, les).', array['article']::text[], 'ال est toujours l''article défini. Dans الولد on lit al-walad ; dans الشمس, le ل se tait et on lit ach-chams.', 2, '{"id": "ar.l16.e15", "unitIds": ["ar.g15.article_sun_moon", "ar.g16.reading_unvowelled"], "type": "fill_blank", "difficulty": 2, "instruction": "Révision : complète avec le bon mot.", "prompt": "Au début d''un mot sans voyelles, ال signale l''___ défini (le, la, les).", "promptLanguage": "fr", "options": ["article", "adjectif", "verbe"], "answer": "article", "acceptedAnswers": ["article"], "explanation": "ال est toujours l''article défini. Dans الولد on lit al-walad ; dans الشمس, le ل se tait et on lit ach-chams.", "tip": "ال au début = le, la, les.", "extraExample": {"text": "الولد", "translation": "le garçon (vocalisé : الْوَلَد)", "transliteration": "al-walad"}, "errorPatterns": [{"equals": "verbe", "category": "grammar", "feedback": "ال n''est pas un verbe : c''est l''article défini."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e16', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.v.chabb']::text[], 'fill_blank', 'lesson', 'Sans voyelles, شاب (jeune homme) s''écrit sans shadda : on le lit « ___ ».', array['châbb']::text[], 'La shadda n''est pas écrite non plus dans un texte sans signes : il faut connaître le mot. شاب se lit châbb (شَابّ), avec le b doublé.', 3, '{"id": "ar.l16.e16", "unitIds": ["ar.g16.reading_unvowelled", "ar.v.chabb"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec la bonne lecture.", "prompt": "Sans voyelles, شاب (jeune homme) s''écrit sans shadda : on le lit « ___ ».", "promptLanguage": "fr", "options": ["châbb", "châb", "chibb", "chabab"], "answer": "châbb", "acceptedAnswers": ["châbb"], "explanation": "La shadda n''est pas écrite non plus dans un texte sans signes : il faut connaître le mot. شاب se lit châbb (شَابّ), avec le b doublé.", "tip": "Les mots courants se mémorisent avec leur shadda.", "extraExample": {"text": "جد", "translation": "grand-père (vocalisé : جَدّ)", "transliteration": "djadd"}, "errorPatterns": [{"equals": "châb", "category": "spelling", "feedback": "La shadda manque à l''écrit, mais le b est bien doublé : châbb."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e17', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.v.walad']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : ceci (c''est) / un garçon / petit', array['هذا ولد صغير']::text[], 'Hâdhâ walad Saghîr : « c''est un petit garçon ». هذا ouvre la phrase, puis le nom, puis l''adjectif.', 3, '{"id": "ar.l16.e17", "unitIds": ["ar.g16.reading_unvowelled", "ar.v.walad"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre de lecture (le premier d''abord).", "prompt": "Remets dans l''ordre : ceci (c''est) / un garçon / petit", "promptLanguage": "fr", "tokens": ["صغير", "هذا", "ولد"], "answer": "هذا ولد صغير", "acceptedAnswers": ["هذا ولد صغير"], "explanation": "Hâdhâ walad Saghîr : « c''est un petit garçon ». هذا ouvre la phrase, puis le nom, puis l''adjectif.", "tip": "Repère le ا de هذا et le ي de صغير : ils te donnent des voyelles longues.", "extraExample": {"text": "هذا كتاب", "translation": "c''est un livre (vocalisé : هٰذَا كِتَابٌ)", "transliteration": "hâdhâ kitâbun"}, "pool": "lesson", "lessonId": "ar.l16", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e18', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.v.zamil']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : il (est) / mon collègue / au travail', array['هو زميلي في العمل']::text[], 'Huwa zamîlî fî l-3amali : « c''est mon collègue de travail ».', 3, '{"id": "ar.l16.e18", "unitIds": ["ar.g16.reading_unvowelled", "ar.v.zamil"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre de lecture (le premier d''abord).", "prompt": "Remets dans l''ordre : il (est) / mon collègue / au travail", "promptLanguage": "fr", "tokens": ["في", "زميلي", "العمل", "هو"], "answer": "هو زميلي في العمل", "acceptedAnswers": ["هو زميلي في العمل"], "explanation": "Huwa zamîlî fî l-3amali : « c''est mon collègue de travail ».", "tip": "Pronom, nom, préposition, lieu.", "extraExample": {"text": "هي زميلتي", "translation": "c''est ma collègue (vocalisé : هِيَ زَمِيلَتِي)", "transliteration": "hiya zamîlatî"}, "pool": "lesson", "lessonId": "ar.l16", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e19', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.v.rukba']::text[], 'translation', 'lesson', 'ركبة', array['genou','le genou','un genou']::text[], 'ركبة (rukba) : le genou. Le ة final est un indice : c''est un mot féminin. Vocalisé : رُكْبَة.', 3, '{"id": "ar.l16.e19", "unitIds": ["ar.g16.reading_unvowelled", "ar.v.rukba"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "ركبة", "promptLanguage": "ar", "answer": "genou", "acceptedAnswers": ["genou", "le genou", "un genou"], "explanation": "ركبة (rukba) : le genou. Le ة final est un indice : c''est un mot féminin. Vocalisé : رُكْبَة.", "tip": "Rukba : le genou.", "extraExample": {"text": "ركبتي", "translation": "mon genou (vocalisé : رُكْبَتِي)", "transliteration": "rukbatî"}, "errorPatterns": [{"equals": "jambe", "category": "vocabulary", "feedback": "La jambe, c''est رِجْل (ridjl) ou سَاق (sâq). ركبة (rukba), c''est le genou."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e20', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.v.azm']::text[], 'translation', 'lesson', 'عظم', array['os','l''os','un os']::text[], 'عظم (3aZm) : l''os. Sans voyelles, aucune lettre longue ne t''aide : ce mot se mémorise. Vocalisé : عَظْم.', 3, '{"id": "ar.l16.e20", "unitIds": ["ar.g16.reading_unvowelled", "ar.v.azm"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "عظم", "promptLanguage": "ar", "answer": "os", "acceptedAnswers": ["os", "l''os", "un os"], "explanation": "عظم (3aZm) : l''os. Sans voyelles, aucune lettre longue ne t''aide : ce mot se mémorise. Vocalisé : عَظْم.", "tip": "3aZm : l''os (avec un ظ).", "extraExample": {"text": "عظام", "translation": "os (pluriel) (vocalisé : عِظَام)", "transliteration": "3iZâm"}, "pool": "lesson", "lessonId": "ar.l16", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e21', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.v.insan']::text[], 'free_answer', 'lesson', 'Comment se lit إنسان (être humain) ?', array['insân','insan','insaan']::text[], 'Le ا avant le ن final est une voyelle longue : in-sân. Le premier ا porte une hamza avec kasra (إِ) : i. Vocalisé : إِنْسَان.', 3, '{"id": "ar.l16.e21", "unitIds": ["ar.g16.reading_unvowelled", "ar.v.insan"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit إنسان (être humain) ?", "promptLanguage": "fr", "answer": "insân", "acceptedAnswers": ["insân", "insan", "insaan"], "explanation": "Le ا avant le ن final est une voyelle longue : in-sân. Le premier ا porte une hamza avec kasra (إِ) : i. Vocalisé : إِنْسَان.", "tip": "Le ا visible = un â long : in-sân.", "extraExample": {"text": "الإنسان", "translation": "l''être humain (vocalisé : الْإِنْسَان)", "transliteration": "al-insân"}, "errorPatterns": [{"equals": "insin", "category": "word_confusion", "feedback": "Le ا avant le ن final est un â long (sân), pas un î."}, {"equals": "ansân", "category": "word_confusion", "feedback": "La hamza est sous le ا : c''est une kasra, i. Vocalisé : إِنْسَان."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e22', 'ar', 'ar.l16', 'ar.g16.reading_unvowelled', array['ar.g16.reading_unvowelled','ar.v.hafid']::text[], 'free_answer', 'lesson', 'Comment se lit حفيد (petit-fils) ?', array['7afîd','7afid','7afiid']::text[], 'Le ي visible est une voyelle longue : 7a-fîd. Le ح se note 7. Vocalisé : حَفِيد.', 4, '{"id": "ar.l16.e22", "unitIds": ["ar.g16.reading_unvowelled", "ar.v.hafid"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture en lettres latines.", "prompt": "Comment se lit حفيد (petit-fils) ?", "promptLanguage": "fr", "answer": "7afîd", "acceptedAnswers": ["7afîd", "7afid", "7afiid"], "hint": "Le ح se note 7.", "explanation": "Le ي visible est une voyelle longue : 7a-fîd. Le ح se note 7. Vocalisé : حَفِيد.", "tip": "Le ح se note 7, le ي visible = î.", "extraExample": {"text": "أحفاد", "translation": "petits-enfants (vocalisé : أَحْفَاد)", "transliteration": "a7fâd"}, "errorPatterns": [{"equals": "7afayd", "category": "word_confusion", "feedback": "Ici le ي est une voyelle longue (î), pas la diphtongue ay : 7afîd."}], "pool": "lesson", "lessonId": "ar.l16", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e01', 'ar', 'ar.l17', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.qamar']::text[], 'mcq', 'lesson', 'قَمَر', array['qamar']::text[], 'قَ = qa (fatha, syllabe ouverte), puis مَر = mar (syllabe fermée en fin de mot). Il n''y a pas de ا : les deux voyelles sont brèves.', 1, '{"id": "ar.l17.e01", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.qamar"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "قَمَر", "promptLanguage": "ar", "options": ["qamar", "qamâr", "kamar", "qumar"], "answer": "qamar", "acceptedAnswers": ["qamar"], "hint": "Petits traits au-dessus = a ; pas de ا dans le mot.", "explanation": "قَ = qa (fatha, syllabe ouverte), puis مَر = mar (syllabe fermée en fin de mot). Il n''y a pas de ا : les deux voyelles sont brèves.", "tip": "Pas de ا, و ou ي après la voyelle ? Alors elle est brève.", "extraExample": {"text": "قَمَرٌ جَمِيلٌ", "translation": "Une belle lune.", "transliteration": "qamarun djamîl"}, "errorPatterns": [{"equals": "qamâr", "category": "spelling", "feedback": "â s''écrit avec un ا ; ici il n''y en a pas : qa-mar, deux a brefs."}, {"equals": "kamar", "category": "spelling", "feedback": "La première lettre est ق (q, du fond de la gorge), pas ك (k) : ق a deux points et une queue ronde qui descend."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e02', 'ar', 'ar.l17', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.madrasa']::text[], 'mcq', 'lesson', 'مَدْرَسَة', array['mad-ra-sa']::text[], 'Le soukoun sur د ferme la première syllabe : mad. Ensuite رَ = ra et سَة = sa, deux syllabes ouvertes.', 1, '{"id": "ar.l17.e02", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.madrasa"], "type": "mcq", "difficulty": 1, "instruction": "Comment se découpe ce mot en syllabes ?", "prompt": "مَدْرَسَة", "promptLanguage": "ar", "options": ["mad-ra-sa", "ma-dra-sa", "ma-dar-sa", "madr-a-sa"], "answer": "mad-ra-sa", "acceptedAnswers": ["mad-ra-sa"], "hint": "Cherche le soukoun (petit rond) : il ferme une syllabe.", "explanation": "Le soukoun sur د ferme la première syllabe : mad. Ensuite رَ = ra et سَة = sa, deux syllabes ouvertes.", "tip": "Une syllabe arabe ne commence jamais par deux consonnes : coupe après la consonne au soukoun.", "extraExample": {"text": "مَكْتَب", "translation": "le bureau : mak-tab", "transliteration": "maktab"}, "errorPatterns": [{"equals": "ma-dra-sa", "category": "spelling", "feedback": "Une syllabe arabe ne commence pas par deux consonnes : le d au soukoun reste avec ma → mad."}, {"equals": "ma-dar-sa", "category": "spelling", "feedback": "Il n''y a pas de voyelle sur د : le soukoun (ـْ) montre qu''on passe directement au r."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e03', 'ar', 'ar.l17', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.min']::text[], 'mcq', 'lesson', 'مِنْ', array['fermée : min']::text[], 'مِ = mi, puis نْ porte un soukoun : la syllabe se ferme sur n. C''est une syllabe fermée, min.', 1, '{"id": "ar.l17.e03", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.min"], "type": "mcq", "difficulty": 1, "instruction": "Cette syllabe est-elle ouverte ou fermée ?", "prompt": "مِنْ", "promptLanguage": "ar", "options": ["fermée : min", "ouverte : mi", "ouverte : mî"], "answer": "fermée : min", "acceptedAnswers": ["fermée : min"], "explanation": "مِ = mi, puis نْ porte un soukoun : la syllabe se ferme sur n. C''est une syllabe fermée, min.", "tip": "Soukoun à la fin = syllabe fermée.", "extraExample": {"text": "مِنْ مِصْرَ", "translation": "d''Égypte", "transliteration": "min miSr"}, "errorPatterns": [{"equals": "ouverte : mi", "category": "spelling", "feedback": "Le ن au soukoun se prononce : la syllabe ne s''arrête pas sur i, elle se ferme sur n."}, {"equals": "ouverte : mî", "category": "spelling", "feedback": "Il n''y a pas de ي après la kasra : le i est bref et la syllabe finit par n."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e04', 'ar', 'ar.l17', 'ar.v.qamar', array['ar.v.qamar','ar.v.djabal','ar.v.matar','ar.v.chadjara','ar.v.samak']::text[], 'match', 'lesson', 'La nature en 5 mots', '{}'::text[], 'Ces 5 noms sont courts : lis-les syllabe par syllabe (qa-mar, dja-bal, ma-Tar, cha-dja-ra, sa-mak) avant de chercher le sens.', 1, '{"id": "ar.l17.e04", "unitIds": ["ar.v.qamar", "ar.v.djabal", "ar.v.matar", "ar.v.chadjara", "ar.v.samak"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à sa traduction.", "prompt": "La nature en 5 mots", "promptLanguage": "fr", "pairs": [{"left": "قَمَر", "right": "la lune"}, {"left": "جَبَل", "right": "la montagne"}, {"left": "مَطَر", "right": "la pluie"}, {"left": "شَجَرَة", "right": "l''arbre"}, {"left": "سَمَك", "right": "le poisson"}], "answer": "قَمَر = la lune ; جَبَل = la montagne ; مَطَر = la pluie ; شَجَرَة = l''arbre ; سَمَك = le poisson", "acceptedAnswers": [], "explanation": "Ces 5 noms sont courts : lis-les syllabe par syllabe (qa-mar, dja-bal, ma-Tar, cha-dja-ra, sa-mak) avant de chercher le sens.", "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e05', 'ar', 'ar.l17', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.fi']::text[], 'mcq', 'lesson', 'Lequel de ces mots se lit en une seule syllabe ouverte et longue ?', array['فِي']::text[], 'فِي = fî : la kasra suivie de ي donne un i long, et rien ne ferme la syllabe. مِنْ est fermé (min), قَمَر et سَمَك ont deux syllabes.', 1, '{"id": "ar.l17.e05", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.fi"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Lequel de ces mots se lit en une seule syllabe ouverte et longue ?", "promptLanguage": "fr", "options": ["فِي", "مِنْ", "قَمَر", "سَمَك"], "answer": "فِي", "acceptedAnswers": ["فِي"], "hint": "Ouverte = finit par une voyelle ; longue = voyelle suivie de ا, و ou ي.", "explanation": "فِي = fî : la kasra suivie de ي donne un i long, et rien ne ferme la syllabe. مِنْ est fermé (min), قَمَر et سَمَك ont deux syllabes.", "tip": "Kasra + ي = î long ; fatha + ا = â ; damma + و = û.", "extraExample": {"text": "فِي الْمَدْرَسَةِ", "translation": "à l''école", "transliteration": "fî l-madrasa"}, "errorPatterns": [{"equals": "مِنْ", "category": "spelling", "feedback": "مِنْ finit par un ن au soukoun : c''est une syllabe fermée, min."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e06', 'ar', 'ar.l17', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.chadjara']::text[], 'mcq', 'lesson', 'Combien de syllabes : شَجَرَة ?', array['3']::text[], 'Trois consonnes avec fatha, trois syllabes ouvertes : cha-dja-ra. Le ة final ne fait pas une syllabe de plus : à la pause, il se tait.', 2, '{"id": "ar.l17.e06", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.chadjara"], "type": "mcq", "difficulty": 2, "instruction": "Combien de syllabes dans ce mot ?", "prompt": "Combien de syllabes : شَجَرَة ?", "promptLanguage": "ar", "options": ["2", "3", "4"], "answer": "3", "acceptedAnswers": ["3"], "explanation": "Trois consonnes avec fatha, trois syllabes ouvertes : cha-dja-ra. Le ة final ne fait pas une syllabe de plus : à la pause, il se tait.", "tip": "Compte les consonnes qui portent une voyelle : chacune ouvre une syllabe.", "extraExample": {"text": "سَمَكَة", "translation": "un poisson : sa-ma-ka, 3 syllabes", "transliteration": "samaka"}, "errorPatterns": [{"equals": "4", "category": "spelling", "feedback": "Le ة final ne se prononce pas à la pause : il termine simplement la syllabe ra."}, {"equals": "2", "category": "spelling", "feedback": "ش, ج et ر portent chacune une fatha : cha, dja, ra, cela fait trois syllabes."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e07', 'ar', 'ar.l17', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.qamar','ar.v.djabal','ar.v.matar','ar.v.samak','ar.v.madrasa']::text[], 'match', 'lesson', 'Découpe chaque mot', '{}'::text[], 'Les mots de 3 lettres avec deux fathas se lisent ouverte + fermée (qa-mar). مَدْرَسَة commence par une syllabe fermée à cause du soukoun sur د.', 2, '{"id": "ar.l17.e07", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.qamar", "ar.v.djabal", "ar.v.matar", "ar.v.samak", "ar.v.madrasa"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son découpage en syllabes.", "prompt": "Découpe chaque mot", "promptLanguage": "fr", "pairs": [{"left": "قَمَر", "right": "qa-mar"}, {"left": "جَبَل", "right": "dja-bal"}, {"left": "مَطَر", "right": "ma-Tar"}, {"left": "سَمَك", "right": "sa-mak"}, {"left": "مَدْرَسَة", "right": "mad-ra-sa"}], "answer": "قَمَر = qa-mar ; جَبَل = dja-bal ; مَطَر = ma-Tar ; سَمَك = sa-mak ; مَدْرَسَة = mad-ra-sa", "acceptedAnswers": [], "explanation": "Les mots de 3 lettres avec deux fathas se lisent ouverte + fermée (qa-mar). مَدْرَسَة commence par une syllabe fermée à cause du soukoun sur د.", "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e08', 'ar', 'ar.l17', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.djabal']::text[], 'mcq', 'lesson', 'Dans جَبَل, quelle syllabe est fermée ?', array['bal']::text[], 'جَ = dja est ouverte (elle finit par a). Le mot lu seul s''arrête sur ل : la dernière syllabe, bal, est fermée.', 2, '{"id": "ar.l17.e08", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.djabal"], "type": "mcq", "difficulty": 2, "instruction": "Quelle est la syllabe fermée de ce mot ?", "prompt": "Dans جَبَل, quelle syllabe est fermée ?", "promptLanguage": "ar", "options": ["bal", "dja", "djab"], "answer": "bal", "acceptedAnswers": ["bal"], "explanation": "جَ = dja est ouverte (elle finit par a). Le mot lu seul s''arrête sur ل : la dernière syllabe, bal, est fermée.", "tip": "En fin de mot lu seul, la dernière syllabe se ferme sur la dernière consonne.", "extraExample": {"text": "مَطَر", "translation": "la pluie : ma (ouverte) + Tar (fermée)", "transliteration": "maTar"}, "errorPatterns": [{"equals": "dja", "category": "spelling", "feedback": "dja finit par une voyelle : c''est une syllabe ouverte."}, {"equals": "djab", "category": "spelling", "feedback": "Le ب porte une fatha : il ouvre une nouvelle syllabe (ba) au lieu de fermer dja."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e09', 'ar', 'ar.l17', 'ar.v.samak', array['ar.v.samak','ar.g17.open_closed_syllables']::text[], 'mcq', 'lesson', 'سَمَك', array['samak']::text[], 'س n''a pas de points (s), les deux petits traits au-dessus sont des fathas (a), et il n''y a pas de ا : sa-mak.', 2, '{"id": "ar.l17.e09", "unitIds": ["ar.v.samak", "ar.g17.open_closed_syllables"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "سَمَك", "promptLanguage": "ar", "options": ["samak", "chamak", "sumuk", "samâk"], "answer": "samak", "acceptedAnswers": ["samak"], "hint": "Regarde les points et les petits traits.", "explanation": "س n''a pas de points (s), les deux petits traits au-dessus sont des fathas (a), et il n''y a pas de ا : sa-mak.", "tip": "Avant de lire, vérifie : points de la lettre, puis voyelle.", "extraExample": {"text": "سَمَكٌ وَخُبْزٌ", "translation": "Du poisson et du pain.", "transliteration": "samakun wa-khubz"}, "errorPatterns": [{"equals": "chamak", "category": "spelling", "feedback": "س n''a pas de points ; c''est ش (3 points) qui se lit ch."}, {"equals": "sumuk", "category": "spelling", "feedback": "Le petit trait au-dessus est une fatha (a). La damma (u) ressemble à un petit و."}, {"equals": "samâk", "category": "spelling", "feedback": "Il n''y a pas de ا dans le mot : les voyelles sont brèves."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e10', 'ar', 'ar.l17', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.matar']::text[], 'mcq', 'lesson', 'Quel mot se lit ma-Tar ?', array['مَطَر']::text[], 'ma-Tar : fatha sur م, fatha sur ط, pas de ا. مَطَار (avec ا) se lit ma-Târ et veut dire « aéroport ».', 3, '{"id": "ar.l17.e10", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.matar"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Quel mot se lit ma-Tar ?", "promptLanguage": "fr", "options": ["مَطَر", "مَطَار", "مُطِر", "مِطْر"], "answer": "مَطَر", "acceptedAnswers": ["مَطَر"], "explanation": "ma-Tar : fatha sur م, fatha sur ط, pas de ا. مَطَار (avec ا) se lit ma-Târ et veut dire « aéroport ».", "tip": "Une voyelle longue s''écrit avec une lettre en plus (ا و ي).", "extraExample": {"text": "الْمَطَرُ بَارِدٌ", "translation": "La pluie est froide.", "transliteration": "al-maTaru bârid"}, "errorPatterns": [{"equals": "مَطَار", "category": "spelling", "feedback": "مَطَار contient un ا : la syllabe est longue, ma-Târ (l''aéroport)."}, {"equals": "مُطِر", "category": "spelling", "feedback": "Damma puis kasra : ce mot se lirait mu-Tir, pas ma-Tar."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e11', 'ar', 'ar.l17', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.madrasa']::text[], 'fill_blank', 'lesson', 'mad - ___ - sa', array['ra']::text[], 'Après la syllabe fermée mad, le ر porte une fatha : il ouvre la syllabe ra, puis sa.', 2, '{"id": "ar.l17.e11", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.madrasa"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le découpage en syllabes de مَدْرَسَة.", "prompt": "mad - ___ - sa", "promptLanguage": "fr", "options": ["ra", "dra", "dar"], "answer": "ra", "acceptedAnswers": ["ra"], "explanation": "Après la syllabe fermée mad, le ر porte une fatha : il ouvre la syllabe ra, puis sa.", "tip": "Chaque consonne qui porte une voyelle commence une nouvelle syllabe.", "extraExample": {"text": "مَكْتَبَة", "translation": "la bibliothèque : mak-ta-ba", "transliteration": "maktaba"}, "errorPatterns": [{"equals": "dra", "category": "spelling", "feedback": "Le d est déjà dans mad (il porte le soukoun) : la syllabe suivante commence au r."}, {"equals": "dar", "category": "spelling", "feedback": "د n''a pas de voyelle, et ر n''a pas de soukoun : on lit mad-ra, pas dar."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e12', 'ar', 'ar.l17', 'ar.v.fi', array['ar.v.fi','ar.g17.open_closed_syllables']::text[], 'fill_blank', 'lesson', 'السَّمَكُ ___ الْمَاءِ', array['فِي']::text[], '« Dans » se dit فِي (fî). Le nom qui suit prend une kasra : فِي الْمَاءِ.', 2, '{"id": "ar.l17.e12", "unitIds": ["ar.v.fi", "ar.g17.open_closed_syllables"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « Le poisson est dans l''eau. »", "prompt": "السَّمَكُ ___ الْمَاءِ", "promptLanguage": "ar", "options": ["فِي", "مِنْ", "عَلَى"], "answer": "فِي", "acceptedAnswers": ["فِي"], "explanation": "« Dans » se dit فِي (fî). Le nom qui suit prend une kasra : فِي الْمَاءِ.", "tip": "فِي = dans, à, en ; مِنْ = de (provenance).", "extraExample": {"text": "الْقَمَرُ فِي اللَّيْلِ", "translation": "La lune (est là) la nuit.", "transliteration": "al-qamaru fî l-layl"}, "errorPatterns": [{"equals": "مِنْ", "category": "word_confusion", "feedback": "مِنْ veut dire « de » (on vient de quelque part). Pour « dans », c''est فِي."}, {"equals": "عَلَى", "category": "word_confusion", "feedback": "عَلَى veut dire « sur ». Le poisson est dans l''eau : فِي."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e13', 'ar', 'ar.l17', 'ar.v.min', array['ar.v.min','ar.g17.open_closed_syllables']::text[], 'fill_blank', 'lesson', 'هُوَ ___ مِصْرَ', array['مِنْ']::text[], 'Pour dire d''où l''on vient, on utilise مِنْ (min), avec une kasra sous م et un soukoun sur ن.', 3, '{"id": "ar.l17.e13", "unitIds": ["ar.v.min", "ar.g17.open_closed_syllables"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Il est d''Égypte. »", "prompt": "هُوَ ___ مِصْرَ", "promptLanguage": "ar", "options": ["مِنْ", "مَنْ", "فِي"], "answer": "مِنْ", "acceptedAnswers": ["مِنْ"], "explanation": "Pour dire d''où l''on vient, on utilise مِنْ (min), avec une kasra sous م et un soukoun sur ن.", "tip": "مِنْ (kasra) = de ; مَنْ (fatha) = qui ?", "extraExample": {"text": "أَنَا مِنْ مِصْرَ", "translation": "Je suis d''Égypte.", "transliteration": "''anâ min miSr"}, "errorPatterns": [{"equals": "مَنْ", "category": "word_confusion", "feedback": "Avec une fatha, مَنْ (man) veut dire « qui ? ». « De » se dit مِنْ, avec une kasra."}, {"equals": "فِي", "category": "word_confusion", "feedback": "هُوَ فِي مِصْرَ voudrait dire « il est en Égypte ». Pour « de », c''est مِنْ."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e14', 'ar', 'ar.l17', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.chadjara']::text[], 'reorder', 'lesson', 'Les syllabes de شَجَرَة, dans l''ordre', array['cha dja ra']::text[], 'On lit de droite à gauche : شَ = cha, جَ = dja, رَة = ra.', 2, '{"id": "ar.l17.e14", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.chadjara"], "type": "reorder", "difficulty": 2, "instruction": "Remets les syllabes dans l''ordre pour lire ce mot.", "prompt": "Les syllabes de شَجَرَة, dans l''ordre", "promptLanguage": "ar", "tokens": ["ra", "cha", "dja"], "answer": "cha dja ra", "acceptedAnswers": ["cha dja ra"], "explanation": "On lit de droite à gauche : شَ = cha, جَ = dja, رَة = ra.", "tip": "En arabe, la première syllabe est à droite.", "extraExample": {"text": "شَجَرَةٌ كَبِيرَةٌ", "translation": "un grand arbre", "transliteration": "chadjaratun kabîra"}, "pool": "lesson", "lessonId": "ar.l17", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e15', 'ar', 'ar.l17', 'ar.v.matar', array['ar.v.matar','ar.v.djabal','ar.v.fi']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : الْمَطَرُ / فِي / الْجَبَلِ', array['الْمَطَرُ فِي الْجَبَلِ']::text[], 'On commence par le sujet (الْمَطَرُ, la pluie), puis فِي et le lieu, qui prend une kasra : الْجَبَلِ.', 3, '{"id": "ar.l17.e15", "unitIds": ["ar.v.matar", "ar.v.djabal", "ar.v.fi"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « La pluie est dans la montagne. »", "prompt": "Remets dans l''ordre : الْمَطَرُ / فِي / الْجَبَلِ", "promptLanguage": "ar", "tokens": ["فِي", "الْجَبَلِ", "الْمَطَرُ"], "answer": "الْمَطَرُ فِي الْجَبَلِ", "acceptedAnswers": ["الْمَطَرُ فِي الْجَبَلِ"], "explanation": "On commence par le sujet (الْمَطَرُ, la pluie), puis فِي et le lieu, qui prend une kasra : الْجَبَلِ.", "tip": "Sujet d''abord, puis فِي + lieu.", "extraExample": {"text": "السَّمَكُ فِي الْمَاءِ", "translation": "Le poisson est dans l''eau.", "transliteration": "as-samaku fî l-mâ''"}, "pool": "lesson", "lessonId": "ar.l17", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e16', 'ar', 'ar.l17', 'ar.v.samak', array['ar.v.samak','ar.g17.open_closed_syllables']::text[], 'translation', 'lesson', 'سَمَكٌ وَقَمَرٌ', array['poisson et lune','un poisson et une lune','du poisson et une lune','le poisson et la lune','des poissons et une lune']::text[], 'سَمَكٌ = poisson, وَ = et, قَمَرٌ = lune. Le double signe à la fin (tanwîn) marque un nom indéfini : « un, du ».', 3, '{"id": "ar.l17.e16", "unitIds": ["ar.v.samak", "ar.g17.open_closed_syllables"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "سَمَكٌ وَقَمَرٌ", "promptLanguage": "ar", "answer": "du poisson et une lune", "acceptedAnswers": ["poisson et lune", "un poisson et une lune", "du poisson et une lune", "le poisson et la lune", "des poissons et une lune"], "explanation": "سَمَكٌ = poisson, وَ = et, قَمَرٌ = lune. Le double signe à la fin (tanwîn) marque un nom indéfini : « un, du ».", "tip": "Le tanwîn (ـٌ) se lit -un et se traduit par « un » ou « du ».", "extraExample": {"text": "جَبَلٌ وَشَجَرَةٌ", "translation": "une montagne et un arbre", "transliteration": "djabalun wa-chadjara"}, "errorPatterns": [{"contains": "soleil", "category": "vocabulary", "feedback": "قَمَر est la lune ; le soleil se dit شَمْس."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e17', 'ar', 'ar.l17', 'ar.v.madrasa', array['ar.v.madrasa','ar.v.fi']::text[], 'translation', 'lesson', 'فِي الْمَدْرَسَةِ', array['à l''école','dans l''école','a l''ecole']::text[], 'فِي = à, dans ; الْمَدْرَسَةِ = l''école (avec l''article الـ et une kasra après فِي).', 3, '{"id": "ar.l17.e17", "unitIds": ["ar.v.madrasa", "ar.v.fi"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "فِي الْمَدْرَسَةِ", "promptLanguage": "ar", "answer": "à l''école", "acceptedAnswers": ["à l''école", "dans l''école", "a l''ecole"], "explanation": "فِي = à, dans ; الْمَدْرَسَةِ = l''école (avec l''article الـ et une kasra après فِي).", "tip": "الـ au début d''un nom = le, la.", "extraExample": {"text": "فِي الْجَبَلِ", "translation": "dans la montagne", "transliteration": "fî l-djabal"}, "errorPatterns": [{"contains": "de l''école", "category": "preposition", "feedback": "فِي veut dire « à, dans ». « De l''école » se dirait مِنَ الْمَدْرَسَةِ."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e18', 'ar', 'ar.l17', 'ar.v.djabal', array['ar.v.djabal','ar.g17.open_closed_syllables']::text[], 'free_answer', 'lesson', 'جَبَل', array['djabal','jabal','gabal']::text[], 'جَ = dja, بَل = bal : djabal (la montagne). Deux syllabes, ouverte puis fermée.', 3, '{"id": "ar.l17.e18", "unitIds": ["ar.v.djabal", "ar.g17.open_closed_syllables"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ce mot en lettres latines.", "prompt": "جَبَل", "promptLanguage": "ar", "answer": "djabal", "acceptedAnswers": ["djabal", "jabal", "gabal"], "hint": "ج se transcrit dj.", "explanation": "جَ = dja, بَل = bal : djabal (la montagne). Deux syllabes, ouverte puis fermée.", "tip": "Lis syllabe par syllabe, puis colle les morceaux.", "extraExample": {"text": "جِبَال", "translation": "des montagnes", "transliteration": "djibâl"}, "errorPatterns": [{"equals": "djabl", "category": "spelling", "feedback": "Le ب porte une fatha : on la prononce, dja-bal."}, {"equals": "habal", "category": "spelling", "feedback": "ج a un point à l''intérieur : c''est dj, pas h."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e19', 'ar', 'ar.l17', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.chadjara']::text[], 'free_answer', 'lesson', 'شَجَرَة', array['chadjara','chajara','shajara','shadjara','chadjarah','shajarah']::text[], 'شَ = cha, جَ = dja, رَة = ra : chadjara (l''arbre). Le ة final se lit a à la pause.', 4, '{"id": "ar.l17.e19", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.chadjara"], "type": "free_answer", "difficulty": 4, "instruction": "Écris ce mot en lettres latines.", "prompt": "شَجَرَة", "promptLanguage": "ar", "answer": "chadjara", "acceptedAnswers": ["chadjara", "chajara", "shajara", "shadjara", "chadjarah", "shajarah"], "hint": "ش = ch, ج = dj ; trois syllabes ouvertes.", "explanation": "شَ = cha, جَ = dja, رَة = ra : chadjara (l''arbre). Le ة final se lit a à la pause.", "tip": "Trois fathas = trois a : cha-dja-ra.", "extraExample": {"text": "أَشْجَار", "translation": "des arbres : ''ach-djâr", "transliteration": "''achdjâr"}, "errorPatterns": [{"equals": "sadjara", "category": "spelling", "feedback": "ش a trois points : c''est ch, pas s."}, {"equals": "chadjra", "category": "spelling", "feedback": "Le ج porte une fatha, pas un soukoun : cha-dja-ra."}], "pool": "lesson", "lessonId": "ar.l17", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l17.e20', 'ar', 'ar.l17', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.min','ar.v.fi','ar.v.qamar','ar.v.chadjara','ar.v.madrasa']::text[], 'match', 'lesson', 'Quelles syllabes dans chaque mot ?', '{}'::text[], 'Le soukoun ferme une syllabe (min, mad) ; une voyelle suivie de ي allonge la syllabe (fî) ; en fin de mot lu seul, la dernière syllabe se ferme (qa-mar).', 3, '{"id": "ar.l17.e20", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.min", "ar.v.fi", "ar.v.qamar", "ar.v.chadjara", "ar.v.madrasa"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à sa structure.", "prompt": "Quelles syllabes dans chaque mot ?", "promptLanguage": "fr", "pairs": [{"left": "مِنْ", "right": "1 syllabe fermée"}, {"left": "فِي", "right": "1 syllabe ouverte longue"}, {"left": "قَمَر", "right": "1 ouverte + 1 fermée"}, {"left": "شَجَرَة", "right": "3 syllabes ouvertes"}, {"left": "مَدْرَسَة", "right": "1 fermée + 2 ouvertes"}], "answer": "مِنْ = 1 syllabe fermée ; فِي = 1 syllabe ouverte longue ; قَمَر = 1 ouverte + 1 fermée ; شَجَرَة = 3 syllabes ouvertes ; مَدْرَسَة = 1 fermée + 2 ouvertes", "acceptedAnswers": [], "explanation": "Le soukoun ferme une syllabe (min, mad) ; une voyelle suivie de ي allonge la syllabe (fî) ; en fin de mot lu seul, la dernière syllabe se ferme (qa-mar).", "pool": "lesson", "lessonId": "ar.l17", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e01', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.kataba']::text[], 'mcq', 'lesson', 'كَتَبَ', array['kataba']::text[], 'كَتَبَ porte une fatha sur chacune de ses 3 lettres : ka-ta-ba, « il a écrit ». La fatha finale se prononce.', 1, '{"id": "ar.l18.e01", "unitIds": ["ar.g18.three_letter_roots", "ar.v.kataba"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "كَتَبَ", "promptLanguage": "ar", "options": ["kataba", "katab", "kutiba", "kitâb"], "answer": "kataba", "acceptedAnswers": ["kataba"], "hint": "Trois lettres, trois fathas.", "explanation": "كَتَبَ porte une fatha sur chacune de ses 3 lettres : ka-ta-ba, « il a écrit ». La fatha finale se prononce.", "tip": "Verbe de base = 3 lettres, 3 voyelles : CaCaCa.", "extraExample": {"text": "كَتَبَ كِتَابًا", "translation": "Il a écrit un livre.", "transliteration": "kataba kitâban"}, "errorPatterns": [{"equals": "katab", "category": "spelling", "feedback": "La dernière lettre porte une fatha : on la lit, ka-ta-ba."}, {"equals": "kitâb", "category": "spelling", "feedback": "كِتَاب (le livre) a une kasra sous ك et un ا. Ici, trois fathas et pas de ا : kataba."}, {"equals": "kutiba", "category": "spelling", "feedback": "Les petits traits sont au-dessus des lettres : ce sont des fathas (a), pas une damma et une kasra."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e02', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.kitab']::text[], 'mcq', 'lesson', 'Quelle est la racine de كِتَاب ?', array['ك ت ب']::text[], 'Le ا de كِتَاب sert à allonger la voyelle (tâ) ; il ne fait pas partie de la racine. Les 3 consonnes qui portent le sens « écrire » sont ك ت ب.', 1, '{"id": "ar.l18.e02", "unitIds": ["ar.g18.three_letter_roots", "ar.v.kitab"], "type": "mcq", "difficulty": 1, "instruction": "Choisis les 3 lettres de la racine.", "prompt": "Quelle est la racine de كِتَاب ?", "promptLanguage": "fr", "options": ["ك ت ب", "ك ت ا", "ت ا ب"], "answer": "ك ت ب", "acceptedAnswers": ["ك ت ب"], "explanation": "Le ا de كِتَاب sert à allonger la voyelle (tâ) ; il ne fait pas partie de la racine. Les 3 consonnes qui portent le sens « écrire » sont ك ت ب.", "tip": "La racine ne garde que les consonnes de base : on enlève les ا, و, ي qui allongent.", "extraExample": {"text": "كُتُب", "translation": "des livres (même racine ك ت ب)", "transliteration": "kutub"}, "errorPatterns": [{"equals": "ك ت ا", "category": "spelling", "feedback": "Le ا est une voyelle longue ajoutée, pas une lettre de la racine : ك ت ب."}, {"equals": "ت ا ب", "category": "spelling", "feedback": "Le ك du début fait partie de la racine (écrire) ; le ا, lui, n''en fait pas partie."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e03', 'ar', 'ar.l18', 'ar.v.kataba', array['ar.v.kataba','ar.v.darasa','ar.v.dhahaba','ar.v.akala','ar.v.chariba']::text[], 'match', 'lesson', 'Cinq verbes de 3 lettres', '{}'::text[], 'Tous ces verbes sont au passé, à la forme « il » : c''est la forme de base de 3 lettres que l''on cherche dans le dictionnaire.', 1, '{"id": "ar.l18.e03", "unitIds": ["ar.v.kataba", "ar.v.darasa", "ar.v.dhahaba", "ar.v.akala", "ar.v.chariba"], "type": "match", "difficulty": 1, "instruction": "Associe chaque verbe à sa traduction.", "prompt": "Cinq verbes de 3 lettres", "promptLanguage": "fr", "pairs": [{"left": "كَتَبَ", "right": "il a écrit"}, {"left": "دَرَسَ", "right": "il a étudié"}, {"left": "ذَهَبَ", "right": "il est allé"}, {"left": "أَكَلَ", "right": "il a mangé"}, {"left": "شَرِبَ", "right": "il a bu"}], "answer": "كَتَبَ = il a écrit ; دَرَسَ = il a étudié ; ذَهَبَ = il est allé ; أَكَلَ = il a mangé ; شَرِبَ = il a bu", "acceptedAnswers": [], "explanation": "Tous ces verbes sont au passé, à la forme « il » : c''est la forme de base de 3 lettres que l''on cherche dans le dictionnaire.", "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e04', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.chariba']::text[], 'mcq', 'lesson', 'شَرِبَ', array['chariba']::text[], 'شَ = cha, رِ = ri (kasra sous ر), بَ = ba : chariba, « il a bu ». Ce verbe suit le rythme CaCiCa.', 1, '{"id": "ar.l18.e04", "unitIds": ["ar.g18.three_letter_roots", "ar.v.chariba"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "شَرِبَ", "promptLanguage": "ar", "options": ["chariba", "charaba", "churiba", "sariba"], "answer": "chariba", "acceptedAnswers": ["chariba"], "hint": "Regarde bien la voyelle sous le ر.", "explanation": "شَ = cha, رِ = ri (kasra sous ر), بَ = ba : chariba, « il a bu ». Ce verbe suit le rythme CaCiCa.", "tip": "Tous les verbes ne font pas kataba : vérifie la voyelle du milieu.", "extraExample": {"text": "شَرِبَ الْمَاءَ", "translation": "Il a bu l''eau.", "transliteration": "chariba l-mâ''"}, "errorPatterns": [{"equals": "charaba", "category": "spelling", "feedback": "Sous le ر il y a une kasra (petit trait dessous) : ri, pas ra."}, {"equals": "sariba", "category": "spelling", "feedback": "ش a trois points : c''est ch, pas s."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e05', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.maktab']::text[], 'mcq', 'lesson', 'Quel mot appartient à la famille de كَتَبَ (écrire) ?', array['مَكْتَب']::text[], 'مَكْتَب contient ك ت ب dans le même ordre, avec مَـ devant (le lieu) : le bureau, « le lieu où l''on écrit ».', 2, '{"id": "ar.l18.e05", "unitIds": ["ar.g18.three_letter_roots", "ar.v.maktab"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot appartient à la famille de كَتَبَ (écrire) ?", "promptLanguage": "fr", "options": ["مَكْتَب", "مَطْعَم", "مَدْرَسَة", "جَلَسَ"], "answer": "مَكْتَب", "acceptedAnswers": ["مَكْتَب"], "explanation": "مَكْتَب contient ك ت ب dans le même ordre, avec مَـ devant (le lieu) : le bureau, « le lieu où l''on écrit ».", "tip": "Cherche les 3 lettres de la racine, dans le même ordre, au milieu du mot.", "extraExample": {"text": "مَكْتَبَة", "translation": "la bibliothèque (racine ك ت ب)", "transliteration": "maktaba"}, "errorPatterns": [{"equals": "مَطْعَم", "category": "word_confusion", "feedback": "مَطْعَم commence aussi par مَـ, mais sa racine est ط ع م (manger) : c''est le restaurant."}, {"equals": "مَدْرَسَة", "category": "word_confusion", "feedback": "مَدْرَسَة vient de la racine د ر س (étudier), pas de ك ت ب."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e06', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.fataha']::text[], 'mcq', 'lesson', 'فَتَحَ', array['fata7a']::text[], 'فَ = fa (un point : f), تَ = ta, حَ = 7a (aucun point) : fata7a, « il a ouvert ».', 2, '{"id": "ar.l18.e06", "unitIds": ["ar.g18.three_letter_roots", "ar.v.fataha"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "فَتَحَ", "promptLanguage": "ar", "options": ["fata7a", "qata7a", "fatakha", "fati7a"], "answer": "fata7a", "acceptedAnswers": ["fata7a"], "hint": "ف a un seul point ; ح n''en a aucun.", "explanation": "فَ = fa (un point : f), تَ = ta, حَ = 7a (aucun point) : fata7a, « il a ouvert ».", "tip": "Rythme CaCaCa : trois fathas, une seule lecture possible.", "extraExample": {"text": "فَتَحَ الْبَابَ", "translation": "Il a ouvert la porte.", "transliteration": "fata7a l-bâb"}, "errorPatterns": [{"equals": "qata7a", "category": "spelling", "feedback": "ف a un seul point au-dessus ; ق en a deux."}, {"equals": "fatakha", "category": "spelling", "feedback": "La dernière lettre n''a pas de point : c''est ح (7), pas خ (kh)."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e07', 'ar', 'ar.l18', 'ar.v.djalasa', array['ar.v.djalasa','ar.g18.three_letter_roots']::text[], 'mcq', 'lesson', 'جَلَسَ', array['il s''est assis']::text[], 'جَلَسَ (dja-la-sa) veut dire « il s''est assis ». Racine ج ل س.', 2, '{"id": "ar.l18.e07", "unitIds": ["ar.v.djalasa", "ar.g18.three_letter_roots"], "type": "mcq", "difficulty": 2, "instruction": "Que veut dire ce verbe ?", "prompt": "جَلَسَ", "promptLanguage": "ar", "options": ["il s''est assis", "il a étudié", "il a écrit", "il a ouvert"], "answer": "il s''est assis", "acceptedAnswers": ["il s''est assis"], "explanation": "جَلَسَ (dja-la-sa) veut dire « il s''est assis ». Racine ج ل س.", "tip": "Associe chaque racine à une image : ج ل س = une chaise.", "extraExample": {"text": "جَلَسَ فِي الْمَطْعَمِ", "translation": "Il s''est assis au restaurant.", "transliteration": "djalasa fî l-maT3am"}, "errorPatterns": [{"equals": "il a ouvert", "category": "vocabulary", "feedback": "« Il a ouvert » se dit فَتَحَ (fata7a)."}, {"equals": "il a étudié", "category": "vocabulary", "feedback": "« Il a étudié » se dit دَرَسَ ; il finit aussi par سَ, mais commence par د."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e08', 'ar', 'ar.l18', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.darasa']::text[], 'mcq', 'lesson', 'دَرَسَ', array['3']::text[], 'Révision des syllabes : trois lettres avec fatha = trois syllabes ouvertes, da-ra-sa.', 2, '{"id": "ar.l18.e08", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.darasa"], "type": "mcq", "difficulty": 2, "instruction": "Combien de syllabes dans ce verbe ?", "prompt": "دَرَسَ", "promptLanguage": "ar", "options": ["2", "3", "4"], "answer": "3", "acceptedAnswers": ["3"], "explanation": "Révision des syllabes : trois lettres avec fatha = trois syllabes ouvertes, da-ra-sa.", "tip": "Un verbe de base vocalisé CaCaCa = 3 syllabes ouvertes.", "extraExample": {"text": "ذَهَبَ", "translation": "il est allé : dha-ha-ba", "transliteration": "dhahaba"}, "errorPatterns": [{"equals": "2", "category": "spelling", "feedback": "La fatha finale se prononce dans un verbe : da-ra-sa, trois syllabes."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e09', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.kataba','ar.v.kitab','ar.v.maktab','ar.v.darasa','ar.v.madrasa']::text[], 'match', 'lesson', 'Deux familles : écrire et étudier', '{}'::text[], 'ك ت ب donne كَتَبَ, كِتَاب, مَكْتَب ; د ر س donne دَرَسَ et مَدْرَسَة. Le مَـ du début indique souvent un lieu.', 2, '{"id": "ar.l18.e09", "unitIds": ["ar.g18.three_letter_roots", "ar.v.kataba", "ar.v.kitab", "ar.v.maktab", "ar.v.darasa", "ar.v.madrasa"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Deux familles : écrire et étudier", "promptLanguage": "fr", "pairs": [{"left": "كَتَبَ", "right": "il a écrit"}, {"left": "كِتَاب", "right": "le livre"}, {"left": "مَكْتَب", "right": "le bureau"}, {"left": "دَرَسَ", "right": "il a étudié"}, {"left": "مَدْرَسَة", "right": "l''école"}], "answer": "كَتَبَ = il a écrit ; كِتَاب = le livre ; مَكْتَب = le bureau ; دَرَسَ = il a étudié ; مَدْرَسَة = l''école", "acceptedAnswers": [], "explanation": "ك ت ب donne كَتَبَ, كِتَاب, مَكْتَب ; د ر س donne دَرَسَ et مَدْرَسَة. Le مَـ du début indique souvent un lieu.", "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e10', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.akala','ar.v.fataha','ar.v.djalasa','ar.v.dhahaba','ar.v.chariba']::text[], 'match', 'lesson', 'Lis chaque verbe d''un coup', '{}'::text[], 'Quatre de ces verbes suivent le rythme CaCaCa ; شَرِبَ suit CaCiCa (kasra sous ر).', 2, '{"id": "ar.l18.e10", "unitIds": ["ar.g18.three_letter_roots", "ar.v.akala", "ar.v.fataha", "ar.v.djalasa", "ar.v.dhahaba", "ar.v.chariba"], "type": "match", "difficulty": 2, "instruction": "Associe chaque verbe à sa lecture.", "prompt": "Lis chaque verbe d''un coup", "promptLanguage": "fr", "pairs": [{"left": "أَكَلَ", "right": "''akala"}, {"left": "فَتَحَ", "right": "fata7a"}, {"left": "جَلَسَ", "right": "djalasa"}, {"left": "ذَهَبَ", "right": "dhahaba"}, {"left": "شَرِبَ", "right": "chariba"}], "answer": "أَكَلَ = ''akala ; فَتَحَ = fata7a ; جَلَسَ = djalasa ; ذَهَبَ = dhahaba ; شَرِبَ = chariba", "acceptedAnswers": [], "explanation": "Quatre de ces verbes suivent le rythme CaCaCa ; شَرِبَ suit CaCiCa (kasra sous ر).", "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e11', 'ar', 'ar.l18', 'ar.v.madrasa', array['ar.v.madrasa','ar.g18.three_letter_roots']::text[], 'mcq', 'lesson', 'Quelle est la racine de مَدْرَسَة ?', array['د ر س']::text[], 'Révision : مَدْرَسَة = مَـ (lieu) + د ر س (étudier) + ـة. C''est « le lieu où l''on étudie ».', 3, '{"id": "ar.l18.e11", "unitIds": ["ar.v.madrasa", "ar.g18.three_letter_roots"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la racine.", "prompt": "Quelle est la racine de مَدْرَسَة ?", "promptLanguage": "fr", "options": ["د ر س", "م د ر", "ر س ة"], "answer": "د ر س", "acceptedAnswers": ["د ر س"], "explanation": "Révision : مَدْرَسَة = مَـ (lieu) + د ر س (étudier) + ـة. C''est « le lieu où l''on étudie ».", "tip": "Enlève مَـ au début et ـة à la fin : il reste la racine.", "extraExample": {"text": "دَرَسَ فِي الْمَدْرَسَةِ", "translation": "Il a étudié à l''école.", "transliteration": "darasa fî l-madrasa"}, "errorPatterns": [{"equals": "م د ر", "category": "spelling", "feedback": "Le مَـ du début est un ajout qui indique le lieu ; il ne fait pas partie de la racine."}, {"equals": "ر س ة", "category": "spelling", "feedback": "Le ة final est une terminaison (féminin), pas une lettre de la racine."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e12', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.dhahaba']::text[], 'mcq', 'lesson', 'Quel mot veut dire « il est allé » ?', array['ذَهَبَ']::text[], 'ذَهَبَ commence par ذ (un point, dh) et porte une fatha sur chaque lettre : dha-ha-ba, « il est allé ».', 3, '{"id": "ar.l18.e12", "unitIds": ["ar.g18.three_letter_roots", "ar.v.dhahaba"], "type": "mcq", "difficulty": 3, "instruction": "Attention aux points et aux voyelles.", "prompt": "Quel mot veut dire « il est allé » ?", "promptLanguage": "fr", "options": ["ذَهَبَ", "ذَهَب", "دَهَبَ"], "answer": "ذَهَبَ", "acceptedAnswers": ["ذَهَبَ"], "explanation": "ذَهَبَ commence par ذ (un point, dh) et porte une fatha sur chaque lettre : dha-ha-ba, « il est allé ».", "tip": "Le verbe porte une voyelle sur sa dernière lettre ; le nom lu seul, non.", "extraExample": {"text": "ذَهَبَ إِلَى السُّوقِ", "translation": "Il est allé au marché.", "transliteration": "dhahaba ''ilâ s-sûq"}, "errorPatterns": [{"equals": "ذَهَب", "category": "word_confusion", "feedback": "Sans voyelle finale, ذَهَب est un nom : l''or. Le verbe porte une fatha sur chaque lettre."}, {"equals": "دَهَبَ", "category": "spelling", "feedback": "د n''a pas de point : le verbe « aller » commence par ذ (dh)."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e13', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.kitab','ar.v.fataha']::text[], 'fill_blank', 'lesson', 'فَتَحَ ___', array['الْكِتَابَ']::text[], '« Le livre » = الْكِتَابَ (ki-tâb, avec ا). الْمَكْتَب est le bureau et كَتَبَ est un verbe : même racine, autre sens.', 2, '{"id": "ar.l18.e13", "unitIds": ["ar.g18.three_letter_roots", "ar.v.kitab", "ar.v.fataha"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « Il a ouvert le livre. »", "prompt": "فَتَحَ ___", "promptLanguage": "ar", "options": ["الْكِتَابَ", "الْمَكْتَبَ", "كَتَبَ"], "answer": "الْكِتَابَ", "acceptedAnswers": ["الْكِتَابَ"], "explanation": "« Le livre » = الْكِتَابَ (ki-tâb, avec ا). الْمَكْتَب est le bureau et كَتَبَ est un verbe : même racine, autre sens.", "tip": "Même racine, sens différent : regarde les lettres ajoutées (ا, مَـ).", "extraExample": {"text": "فَتَحَ الْمَكْتَبَ", "translation": "Il a ouvert le bureau.", "transliteration": "fata7a l-maktab"}, "errorPatterns": [{"equals": "الْمَكْتَبَ", "category": "word_confusion", "feedback": "الْمَكْتَب (avec مَـ) est le bureau. Le livre, c''est الْكِتَاب, avec un ا."}, {"equals": "كَتَبَ", "category": "word_confusion", "feedback": "كَتَبَ est un verbe (il a écrit). Après فَتَحَ, il faut un nom : الْكِتَابَ."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e14', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.akala','ar.v.samak']::text[], 'fill_blank', 'lesson', '___ السَّمَكَ', array['أَكَلَ']::text[], '« Il a mangé » = أَكَلَ (''a-ka-la), racine أ ك ل. شَرِبَ veut dire « il a bu ».', 3, '{"id": "ar.l18.e14", "unitIds": ["ar.g18.three_letter_roots", "ar.v.akala", "ar.v.samak"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Il a mangé le poisson. »", "prompt": "___ السَّمَكَ", "promptLanguage": "ar", "options": ["أَكَلَ", "شَرِبَ", "كَتَبَ"], "answer": "أَكَلَ", "acceptedAnswers": ["أَكَلَ"], "explanation": "« Il a mangé » = أَكَلَ (''a-ka-la), racine أ ك ل. شَرِبَ veut dire « il a bu ».", "tip": "أ ك ل = manger ; ش ر ب = boire.", "extraExample": {"text": "أَكَلَ الْخُبْزَ", "translation": "Il a mangé le pain.", "transliteration": "''akala l-khubz"}, "errorPatterns": [{"equals": "شَرِبَ", "category": "vocabulary", "feedback": "شَرِبَ veut dire « il a bu ». On mange le poisson : أَكَلَ."}, {"equals": "كَتَبَ", "category": "vocabulary", "feedback": "كَتَبَ veut dire « il a écrit ». « Il a mangé » : أَكَلَ."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e15', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.dhahaba','ar.v.madrasa']::text[], 'fill_blank', 'lesson', '___ إِلَى الْمَدْرَسَةِ', array['ذَهَبَ']::text[], '« Il est allé » = ذَهَبَ. Avec إِلَى (vers), on attend un verbe de mouvement.', 3, '{"id": "ar.l18.e15", "unitIds": ["ar.g18.three_letter_roots", "ar.v.dhahaba", "ar.v.madrasa"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Il est allé à l''école. »", "prompt": "___ إِلَى الْمَدْرَسَةِ", "promptLanguage": "ar", "options": ["ذَهَبَ", "جَلَسَ", "دَرَسَ"], "answer": "ذَهَبَ", "acceptedAnswers": ["ذَهَبَ"], "explanation": "« Il est allé » = ذَهَبَ. Avec إِلَى (vers), on attend un verbe de mouvement.", "tip": "ذَهَبَ + إِلَى = aller à.", "extraExample": {"text": "ذَهَبَ إِلَى الْمَطْعَمِ", "translation": "Il est allé au restaurant.", "transliteration": "dhahaba ''ilâ l-maT3am"}, "errorPatterns": [{"equals": "دَرَسَ", "category": "word_confusion", "feedback": "دَرَسَ veut dire « il a étudié ». Avec إِلَى (vers), il faut le verbe « aller » : ذَهَبَ."}, {"equals": "جَلَسَ", "category": "word_confusion", "feedback": "جَلَسَ veut dire « il s''est assis ». Pour « il est allé », c''est ذَهَبَ."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e16', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.darasa','ar.v.kitab','ar.v.maktab']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : il a étudié / le livre / au bureau', array['دَرَسَ الْكِتَابَ فِي الْمَكْتَبِ']::text[], 'En arabe, la phrase commence souvent par le verbe : دَرَسَ, puis ce qu''il a étudié (الْكِتَابَ), puis le lieu (فِي الْمَكْتَبِ).', 3, '{"id": "ar.l18.e16", "unitIds": ["ar.g18.three_letter_roots", "ar.v.darasa", "ar.v.kitab", "ar.v.maktab"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Il a étudié le livre au bureau. »", "prompt": "Remets dans l''ordre : il a étudié / le livre / au bureau", "promptLanguage": "fr", "tokens": ["فِي", "الْمَكْتَبِ", "دَرَسَ", "الْكِتَابَ"], "answer": "دَرَسَ الْكِتَابَ فِي الْمَكْتَبِ", "acceptedAnswers": ["دَرَسَ الْكِتَابَ فِي الْمَكْتَبِ"], "explanation": "En arabe, la phrase commence souvent par le verbe : دَرَسَ, puis ce qu''il a étudié (الْكِتَابَ), puis le lieu (فِي الْمَكْتَبِ).", "tip": "Verbe d''abord, puis l''objet, puis le lieu.", "extraExample": {"text": "كَتَبَ الْكِتَابَ فِي الْمَدْرَسَةِ", "translation": "Il a écrit le livre à l''école.", "transliteration": "kataba l-kitâba fî l-madrasa"}, "pool": "lesson", "lessonId": "ar.l18", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e17', 'ar', 'ar.l18', 'ar.v.samak', array['ar.v.samak','ar.v.akala','ar.v.madrasa']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : il a mangé / le poisson / à l''école', array['أَكَلَ السَّمَكَ فِي الْمَدْرَسَةِ']::text[], 'Verbe (أَكَلَ), objet (السَّمَكَ), puis lieu (فِي الْمَدْرَسَةِ). Révision : سَمَك et مَدْرَسَة viennent de la leçon précédente.', 3, '{"id": "ar.l18.e17", "unitIds": ["ar.v.samak", "ar.v.akala", "ar.v.madrasa"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Il a mangé le poisson à l''école. »", "prompt": "Remets dans l''ordre : il a mangé / le poisson / à l''école", "promptLanguage": "fr", "tokens": ["السَّمَكَ", "فِي", "الْمَدْرَسَةِ", "أَكَلَ"], "answer": "أَكَلَ السَّمَكَ فِي الْمَدْرَسَةِ", "acceptedAnswers": ["أَكَلَ السَّمَكَ فِي الْمَدْرَسَةِ"], "explanation": "Verbe (أَكَلَ), objet (السَّمَكَ), puis lieu (فِي الْمَدْرَسَةِ). Révision : سَمَك et مَدْرَسَة viennent de la leçon précédente.", "tip": "Repère d''abord le verbe de 3 lettres : il ouvre la phrase.", "extraExample": {"text": "شَرِبَ الْمَاءَ فِي الْمَدْرَسَةِ", "translation": "Il a bu l''eau à l''école.", "transliteration": "chariba l-mâ''a fî l-madrasa"}, "pool": "lesson", "lessonId": "ar.l18", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e18', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.kataba','ar.v.maktab']::text[], 'translation', 'lesson', 'كَتَبَ فِي الْمَكْتَبِ', array['Il a écrit au bureau.','Il a écrit dans le bureau.','Il écrivait au bureau.','Il écrivit au bureau.']::text[], 'كَتَبَ = il a écrit ; فِي = à, dans ; الْمَكْتَبِ = le bureau (مَـ + ك ت ب : le lieu où l''on écrit).', 3, '{"id": "ar.l18.e18", "unitIds": ["ar.g18.three_letter_roots", "ar.v.kataba", "ar.v.maktab"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "كَتَبَ فِي الْمَكْتَبِ", "promptLanguage": "ar", "answer": "Il a écrit au bureau.", "acceptedAnswers": ["Il a écrit au bureau.", "Il a écrit dans le bureau.", "Il écrivait au bureau.", "Il écrivit au bureau."], "explanation": "كَتَبَ = il a écrit ; فِي = à, dans ; الْمَكْتَبِ = le bureau (مَـ + ك ت ب : le lieu où l''on écrit).", "tip": "مَـ + racine = un lieu : مَكْتَب, مَطْعَم, مَدْرَسَة.", "extraExample": {"text": "دَرَسَ فِي الْمَدْرَسَةِ", "translation": "Il a étudié à l''école.", "transliteration": "darasa fî l-madrasa"}, "errorPatterns": [{"contains": "livre", "category": "vocabulary", "feedback": "مَكْتَب (avec مَـ) est le bureau ; le livre, c''est كِتَاب."}, {"contains": "bibliothèque", "category": "vocabulary", "feedback": "La bibliothèque se dit مَكْتَبَة (avec ـة). مَكْتَب, c''est le bureau."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e19', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.djalasa','ar.v.kataba']::text[], 'translation', 'lesson', 'جَلَسَ وَكَتَبَ', array['Il s''est assis et il a écrit.','Il s''est assis et a écrit.','Il s''assit et écrivit.','Il s''est assis puis il a écrit.','Il s''est assis puis a écrit.']::text[], 'Deux verbes de 3 lettres reliés par وَ (et), collé au second : جَلَسَ = il s''est assis, وَ = et, كَتَبَ = il a écrit.', 4, '{"id": "ar.l18.e19", "unitIds": ["ar.g18.three_letter_roots", "ar.v.djalasa", "ar.v.kataba"], "type": "translation", "difficulty": 4, "instruction": "Traduis en français.", "prompt": "جَلَسَ وَكَتَبَ", "promptLanguage": "ar", "answer": "Il s''est assis et il a écrit.", "acceptedAnswers": ["Il s''est assis et il a écrit.", "Il s''est assis et a écrit.", "Il s''assit et écrivit.", "Il s''est assis puis il a écrit.", "Il s''est assis puis a écrit."], "explanation": "Deux verbes de 3 lettres reliés par وَ (et), collé au second : جَلَسَ = il s''est assis, وَ = et, كَتَبَ = il a écrit.", "tip": "وَ se colle au mot suivant : وَكَتَبَ = wa + kataba.", "extraExample": {"text": "أَكَلَ وَشَرِبَ", "translation": "Il a mangé et il a bu.", "transliteration": "''akala wa-chariba"}, "errorPatterns": [{"contains": "ouvert", "category": "vocabulary", "feedback": "فَتَحَ = il a ouvert ; ici le premier verbe est جَلَسَ, il s''est assis."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e20', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.kitab']::text[], 'free_answer', 'lesson', 'Comment se lit كِتَاب ?', array['kitâb','kitab','kitaab']::text[], 'كِ = ki, تَا = tâ (fatha + ا = a long), ب = b : kitâb, le livre.', 3, '{"id": "ar.l18.e20", "unitIds": ["ar.g18.three_letter_roots", "ar.v.kitab"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture de ce mot en lettres latines.", "prompt": "Comment se lit كِتَاب ?", "promptLanguage": "fr", "answer": "kitâb", "acceptedAnswers": ["kitâb", "kitab", "kitaab"], "hint": "Kasra sous ك, puis un ا qui allonge.", "explanation": "كِ = ki, تَا = tâ (fatha + ا = a long), ب = b : kitâb, le livre.", "tip": "Fatha + ا = â long : écris â, ou aa.", "extraExample": {"text": "هٰذَا كِتَابٌ جَدِيدٌ", "translation": "C''est un nouveau livre.", "transliteration": "hâdhâ kitâbun djadîd"}, "errorPatterns": [{"equals": "katab", "category": "spelling", "feedback": "Sous ك il y a une kasra (ki) et le ا allonge le a : ki-tâb."}, {"equals": "kataba", "category": "word_confusion", "feedback": "kataba, c''est le verbe كَتَبَ (il a écrit), sans ا. Ici : ki-tâb, le livre."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l18.e21', 'ar', 'ar.l18', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.maktab']::text[], 'free_answer', 'lesson', 'مَكْتَب', array['k-t-b','ktb']::text[], 'مَكْتَب = مَـ (lieu) + ك ت ب. La racine est k-t-b, l''idée d''écrire.', 4, '{"id": "ar.l18.e21", "unitIds": ["ar.g18.three_letter_roots", "ar.v.maktab"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la racine de ce mot en lettres latines, séparées par des tirets.", "prompt": "مَكْتَب", "promptLanguage": "ar", "answer": "k-t-b", "acceptedAnswers": ["k-t-b", "ktb"], "hint": "Enlève le مَـ du début.", "explanation": "مَكْتَب = مَـ (lieu) + ك ت ب. La racine est k-t-b, l''idée d''écrire.", "tip": "مَـ au début d''un mot est très souvent un ajout : la racine commence après.", "extraExample": {"text": "مَكْتَب، كِتَاب، كَتَبَ", "translation": "bureau, livre, il a écrit : une seule racine", "transliteration": "maktab, kitâb, kataba"}, "errorPatterns": [{"equals": "m-k-t", "category": "spelling", "feedback": "Le مَـ du début est un ajout (« lieu de ») ; la racine est k-t-b."}, {"equals": "m-k-t-b", "category": "spelling", "feedback": "Une racine a 3 lettres : on enlève le مَـ, il reste k-t-b."}], "pool": "lesson", "lessonId": "ar.l18", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e01', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters']::text[], 'mcq', 'lesson', 'Quelles lettres ne s''attachent jamais à la lettre suivante ?', array['ا د ذ ر ز و']::text[], 'Six lettres seulement refusent de s''attacher à la lettre suivante : ا د ذ ر ز و. Toutes les autres, comme ل, ط ou ب, donnent la main à gauche.', 1, '{"id": "ar.l19.e01", "unitIds": ["ar.g19.non_connecting_letters"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne série.", "prompt": "Quelles lettres ne s''attachent jamais à la lettre suivante ?", "promptLanguage": "fr", "options": ["ا د ذ ر ز و", "ا د ذ ر ز ل", "ا د ر ز ط و", "ب د ذ ر ز و"], "answer": "ا د ذ ر ز و", "acceptedAnswers": ["ا د ذ ر ز و"], "hint": "Il y en a exactement six, et le و en fait partie.", "explanation": "Six lettres seulement refusent de s''attacher à la lettre suivante : ا د ذ ر ز و. Toutes les autres, comme ل, ط ou ب, donnent la main à gauche.", "tip": "Retiens-les comme une phrase : « ا د ذ ر ز و ne donnent jamais la main à gauche ».", "extraExample": {"text": "وَرْدَة", "translation": "la rose : و, ر et د coupent le mot en blocs", "transliteration": "warda"}, "errorPatterns": [{"equals": "ا د ذ ر ز ل", "category": "spelling", "feedback": "ل s''attache à la lettre suivante (لـ) ; la sixième lettre qui coupe est و."}, {"equals": "ا د ر ز ط و", "category": "spelling", "feedback": "ط s''attache à la lettre suivante ; il manque ذ dans cette série."}, {"equals": "ب د ذ ر ز و", "category": "spelling", "feedback": "ب s''attache à la lettre suivante (بـ) ; la série commence par ا."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e02', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.warda']::text[], 'mcq', 'lesson', 'وَرْدَة', array['warda']::text[], 'وَ = wa, رْ = r (le soukoun supprime la voyelle), دَة = da : war-da. Quatre lettres détachées, mais un seul mot.', 1, '{"id": "ar.l19.e02", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.warda"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "وَرْدَة", "promptLanguage": "ar", "options": ["warda", "waruda", "wurda", "dawra"], "answer": "warda", "acceptedAnswers": ["warda"], "explanation": "وَ = wa, رْ = r (le soukoun supprime la voyelle), دَة = da : war-da. Quatre lettres détachées, mais un seul mot.", "tip": "Quand les lettres sont détachées, lis-les de droite à gauche sans t''arrêter : un seul mot, un seul souffle.", "extraExample": {"text": "هٰذِهِ وَرْدَةٌ جَمِيلَةٌ", "translation": "C''est une belle rose.", "transliteration": "hâdhihi wardatun djamîla"}, "errorPatterns": [{"equals": "waruda", "category": "spelling", "feedback": "Le soukoun (ـْ) sur ر supprime la voyelle : war-da, pas wa-ru-da."}, {"equals": "dawra", "category": "spelling", "feedback": "On lit de droite à gauche : le mot commence par و, pas par د."}, {"equals": "wurda", "category": "spelling", "feedback": "Le و porte une fatha (a), pas une damma : wa-, pas wu-."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e03', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.warda','ar.v.aruzz','ar.v.barid','ar.v.harr','ar.v.chari']::text[], 'match', 'lesson', 'Cinq mots faits de plusieurs blocs', '{}'::text[], 'Chacun de ces mots contient une des six lettres qui coupent : و ر د dans وَرْدَة, أ ر ز dans أَرُزّ, ا ر د dans بَارِد, ا ر dans حَارّ et شَارِع.', 1, '{"id": "ar.l19.e03", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.warda", "ar.v.aruzz", "ar.v.barid", "ar.v.harr", "ar.v.chari"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à son sens.", "prompt": "Cinq mots faits de plusieurs blocs", "promptLanguage": "fr", "pairs": [{"left": "وَرْدَة", "right": "la rose"}, {"left": "أَرُزّ", "right": "le riz"}, {"left": "بَارِد", "right": "froid"}, {"left": "حَارّ", "right": "chaud"}, {"left": "شَارِع", "right": "la rue"}], "answer": "وَرْدَة = la rose ; أَرُزّ = le riz ; بَارِد = froid ; حَارّ = chaud ; شَارِع = la rue", "acceptedAnswers": [], "explanation": "Chacun de ces mots contient une des six lettres qui coupent : و ر د dans وَرْدَة, أ ر ز dans أَرُزّ, ا ر د dans بَارِد, ا ر dans حَارّ et شَارِع.", "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e04', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.madina']::text[], 'mcq', 'lesson', 'Dans مَدِينَة, après quelle lettre le mot se coupe-t-il ?', array['après le د']::text[], 'م s''attache à د, mais د ne s''attache pas à la lettre suivante : le mot se coupe après lui, puis continue avec ينة. Deux blocs : مد | ينة.', 1, '{"id": "ar.l19.e04", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.madina"], "type": "mcq", "difficulty": 1, "instruction": "Trouve la coupure.", "prompt": "Dans مَدِينَة, après quelle lettre le mot se coupe-t-il ?", "promptLanguage": "fr", "options": ["après le د", "après le م", "après le ي", "après le ن"], "answer": "après le د", "acceptedAnswers": ["après le د"], "explanation": "م s''attache à د, mais د ne s''attache pas à la lettre suivante : le mot se coupe après lui, puis continue avec ينة. Deux blocs : مد | ينة.", "tip": "Cherche d''abord la première lettre parmi ا د ذ ر ز و : c''est là que ça coupe.", "extraExample": {"text": "أَنَا فِي الْمَدِينَةِ", "translation": "Je suis en ville.", "transliteration": "''anâ fî l-madîna"}, "errorPatterns": [{"equals": "après le م", "category": "spelling", "feedback": "م s''attache à la lettre suivante (مـ) : il n''y a pas de coupure ici."}, {"equals": "après le ي", "category": "spelling", "feedback": "ي s''attache à la lettre suivante (يـ) : la coupure est plus tôt, après د."}, {"equals": "après le ن", "category": "spelling", "feedback": "ن s''attache à la lettre suivante ; la seule coupure du mot est après د."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e05', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.harr']::text[], 'mcq', 'lesson', 'Quel mot se lit 7ârr (chaud) ?', array['حَارّ']::text[], 'حَارّ = حَا + رّ : le ا allonge le a (7â) et la chadda double le r. حَرّ n''a pas de ا (7arr, la chaleur), et جَار a un ج, avec un point dedans : djâr, le voisin.', 2, '{"id": "ar.l19.e05", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.harr"], "type": "mcq", "difficulty": 2, "instruction": "Retrouve le mot qui correspond à la lecture.", "prompt": "Quel mot se lit 7ârr (chaud) ?", "promptLanguage": "fr", "options": ["حَارّ", "حَرّ", "جَار", "بَارِد"], "answer": "حَارّ", "acceptedAnswers": ["حَارّ"], "explanation": "حَارّ = حَا + رّ : le ا allonge le a (7â) et la chadda double le r. حَرّ n''a pas de ا (7arr, la chaleur), et جَار a un ج, avec un point dedans : djâr, le voisin.", "tip": "Un ا au milieu = voyelle longue ; une chadda = lettre doublée.", "extraExample": {"text": "الشَّايُ حَارٌّ", "translation": "Le thé est chaud.", "transliteration": "ach-châyu 7ârr"}, "errorPatterns": [{"equals": "حَرّ", "category": "spelling", "feedback": "حَرّ s''écrit sans ا : 7arr, c''est le nom « la chaleur ». Ici il faut le ا long : 7ârr."}, {"equals": "جَار", "category": "spelling", "feedback": "جَار commence par ج (un point dedans) : djâr, le voisin."}, {"equals": "بَارِد", "category": "word_confusion", "feedback": "بَارِد (bârid) veut dire « froid » : ب a un point dessous."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e06', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.warda','ar.v.barid','ar.v.madina','ar.v.aruzz','ar.v.chari']::text[], 'match', 'lesson', 'Coupe chaque mot en blocs', '{}'::text[], 'Un bloc se termine après chaque lettre de ا د ذ ر ز و : c''est pour cela que وَرْدَة fait 4 blocs et مَدِينَة seulement 2.', 2, '{"id": "ar.l19.e06", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.warda", "ar.v.barid", "ar.v.madina", "ar.v.aruzz", "ar.v.chari"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son découpage en blocs.", "prompt": "Coupe chaque mot en blocs", "promptLanguage": "fr", "pairs": [{"left": "وَرْدَة", "right": "و | ر | د | ة"}, {"left": "بَارِد", "right": "با | ر | د"}, {"left": "مَدِينَة", "right": "مد | ينة"}, {"left": "أَرُزّ", "right": "أ | ر | ز"}, {"left": "شَارِع", "right": "شا | ر | ع"}], "answer": "وَرْدَة = و | ر | د | ة ; بَارِد = با | ر | د ; مَدِينَة = مد | ينة ; أَرُزّ = أ | ر | ز ; شَارِع = شا | ر | ع", "acceptedAnswers": [], "explanation": "Un bloc se termine après chaque lettre de ا د ذ ر ز و : c''est pour cela que وَرْدَة fait 4 blocs et مَدِينَة seulement 2.", "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e07', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.ila','ar.v.madina','ar.v.dhahaba']::text[], 'mcq', 'lesson', 'Combien de mots y a-t-il dans ذَهَبَ إِلَى الْمَدِينَةِ ?', array['3']::text[], 'Il y a 3 mots (ذَهَبَ, إِلَى, الْمَدِينَةِ) mais 7 blocs : 2 + 2 + 3. Une coupure dans un mot est petite ; seul l''espace entre deux mots est large.', 2, '{"id": "ar.l19.e07", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.ila", "ar.v.madina", "ar.v.dhahaba"], "type": "mcq", "difficulty": 2, "instruction": "Ne confonds pas blocs et mots.", "prompt": "Combien de mots y a-t-il dans ذَهَبَ إِلَى الْمَدِينَةِ ?", "promptLanguage": "fr", "options": ["2", "3", "5", "7"], "answer": "3", "acceptedAnswers": ["3"], "explanation": "Il y a 3 mots (ذَهَبَ, إِلَى, الْمَدِينَةِ) mais 7 blocs : 2 + 2 + 3. Une coupure dans un mot est petite ; seul l''espace entre deux mots est large.", "tip": "Une coupure n''est pas un espace : compte les grands espaces pour compter les mots.", "extraExample": {"text": "ذَهَبَ إِلَى الْمَدْرَسَةِ", "translation": "Il est allé à l''école.", "transliteration": "dhahaba ''ilâ l-madrasa"}, "errorPatterns": [{"equals": "7", "category": "spelling", "feedback": "7 est le nombre de blocs. Un mot peut en contenir plusieurs : ذَهَبَ en a déjà 2 (ذ | هب)."}, {"equals": "5", "category": "spelling", "feedback": "Compte les grands espaces : il y en a 2, donc 3 mots."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e08', 'ar', 'ar.l19', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.dhahaba','ar.g19.non_connecting_letters']::text[], 'mcq', 'lesson', 'Un seul de ces verbes de 3 lettres se coupe en deux blocs. Lequel ?', array['ذَهَبَ']::text[], 'Révision des verbes : ذَهَبَ commence par ذ, l''une des six lettres qui ne s''attachent pas : ذ | هب. كَتَبَ, جَلَسَ et فَتَحَ s''écrivent d''un seul bloc.', 2, '{"id": "ar.l19.e08", "unitIds": ["ar.g18.three_letter_roots", "ar.v.dhahaba", "ar.g19.non_connecting_letters"], "type": "mcq", "difficulty": 2, "instruction": "Trouve l''intrus.", "prompt": "Un seul de ces verbes de 3 lettres se coupe en deux blocs. Lequel ?", "promptLanguage": "fr", "options": ["كَتَبَ", "ذَهَبَ", "جَلَسَ", "فَتَحَ"], "answer": "ذَهَبَ", "acceptedAnswers": ["ذَهَبَ"], "explanation": "Révision des verbes : ذَهَبَ commence par ذ, l''une des six lettres qui ne s''attachent pas : ذ | هب. كَتَبَ, جَلَسَ et فَتَحَ s''écrivent d''un seul bloc.", "tip": "Dans un verbe de 3 lettres, regarde seulement si l''une des lettres est dans ا د ذ ر ز و.", "extraExample": {"text": "ذَهَبَ إِلَى السُّوقِ", "translation": "Il est allé au marché.", "transliteration": "dhahaba ''ilâ s-sûq"}, "errorPatterns": [{"equals": "كَتَبَ", "category": "spelling", "feedback": "ك, ت et ب s''attachent toutes à la suivante : كَتَبَ s''écrit d''un seul bloc."}, {"equals": "جَلَسَ", "category": "spelling", "feedback": "ج, ل et س s''attachent à la suivante : un seul bloc."}, {"equals": "فَتَحَ", "category": "spelling", "feedback": "ف, ت et ح s''attachent à la suivante : un seul bloc."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e09', 'ar', 'ar.l19', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.warda','ar.g19.non_connecting_letters']::text[], 'mcq', 'lesson', 'Combien de syllabes dans وَرْدَة ?', array['2']::text[], 'Révision des syllabes : le soukoun sur ر ferme la première syllabe (war), puis دَة = da. Le mot compte 4 blocs mais seulement 2 syllabes.', 3, '{"id": "ar.l19.e09", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.warda", "ar.g19.non_connecting_letters"], "type": "mcq", "difficulty": 3, "instruction": "Compte avec les voyelles, pas avec les blocs.", "prompt": "Combien de syllabes dans وَرْدَة ?", "promptLanguage": "fr", "options": ["2", "3", "4"], "answer": "2", "acceptedAnswers": ["2"], "explanation": "Révision des syllabes : le soukoun sur ر ferme la première syllabe (war), puis دَة = da. Le mot compte 4 blocs mais seulement 2 syllabes.", "tip": "Les blocs se voient avec les yeux, les syllabes se comptent avec les voyelles.", "extraExample": {"text": "مَدْرَسَة", "translation": "l''école : 3 syllabes, mad-ra-sa", "transliteration": "madrasa"}, "errorPatterns": [{"equals": "4", "category": "spelling", "feedback": "4 est le nombre de blocs (و ر د ة). Les syllabes se comptent avec les voyelles : war-da."}, {"equals": "3", "category": "spelling", "feedback": "Le soukoun sur ر empêche de dire wa-ra : la première syllabe est war."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e10', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.ila','ar.v.dhahaba','ar.v.madina']::text[], 'fill_blank', 'lesson', 'ذَهَبَ ___ الْمَدِينَةِ', array['إِلَى']::text[], '« Aller à » se dit ذَهَبَ إِلَى. إِلَى (vers) s''écrit en deux blocs, إ | لى, et son ى final se lit â.', 2, '{"id": "ar.l19.e10", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.ila", "ar.v.dhahaba", "ar.v.madina"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « Il est allé à la ville. »", "prompt": "ذَهَبَ ___ الْمَدِينَةِ", "promptLanguage": "ar", "options": ["إِلَى", "مِنْ", "فِي"], "answer": "إِلَى", "acceptedAnswers": ["إِلَى"], "explanation": "« Aller à » se dit ذَهَبَ إِلَى. إِلَى (vers) s''écrit en deux blocs, إ | لى, et son ى final se lit â.", "tip": "إِلَى = direction (vers) ; مِنْ = origine (de) ; فِي = lieu (dans).", "extraExample": {"text": "ذَهَبَ إِلَى الْمَطْعَمِ", "translation": "Il est allé au restaurant.", "transliteration": "dhahaba ''ilâ l-maT3am"}, "errorPatterns": [{"equals": "مِنْ", "category": "preposition", "feedback": "مِنْ indique l''origine (de) : « il est parti de la ville ». Pour aller vers un lieu, on emploie إِلَى."}, {"equals": "فِي", "category": "preposition", "feedback": "فِي indique le lieu où l''on est (dans), pas la direction."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e11', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.warda','ar.v.barid','ar.v.aruzz','ar.v.chari','ar.v.harr']::text[], 'match', 'lesson', 'Lis chaque mot d''un coup, bloc par bloc', '{}'::text[], 'Repère d''abord le ا ou le ر qui coupent le mot, lis le bloc, puis passe au suivant. Un ا au milieu allonge la voyelle (bâ, châ, 7â) ; la chadda double la lettre (zz, rr).', 2, '{"id": "ar.l19.e11", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.warda", "ar.v.barid", "ar.v.aruzz", "ar.v.chari", "ar.v.harr"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lis chaque mot d''un coup, bloc par bloc", "promptLanguage": "fr", "pairs": [{"left": "وَرْدَة", "right": "warda"}, {"left": "بَارِد", "right": "bârid"}, {"left": "أَرُزّ", "right": "''aruzz"}, {"left": "شَارِع", "right": "châri3"}, {"left": "حَارّ", "right": "7ârr"}], "answer": "وَرْدَة = warda ; بَارِد = bârid ; أَرُزّ = ''aruzz ; شَارِع = châri3 ; حَارّ = 7ârr", "acceptedAnswers": [], "explanation": "Repère d''abord le ا ou le ر qui coupent le mot, lis le bloc, puis passe au suivant. Un ا au milieu allonge la voyelle (bâ, châ, 7â) ; la chadda double la lettre (zz, rr).", "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e12', 'ar', 'ar.l19', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.barid','ar.g19.non_connecting_letters']::text[], 'mcq', 'lesson', 'Quelle est la racine de بَارِد (froid) ?', array['ب ر د']::text[], 'Révision : le ا de بَارِد allonge la voyelle (bâ), il ne fait pas partie de la racine. Les 3 consonnes du sens « froid » sont ب ر د, comme dans بَرْد (le froid).', 3, '{"id": "ar.l19.e12", "unitIds": ["ar.g18.three_letter_roots", "ar.v.barid", "ar.g19.non_connecting_letters"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la racine.", "prompt": "Quelle est la racine de بَارِد (froid) ?", "promptLanguage": "fr", "options": ["ب ر د", "ب ا ر", "ا ر د"], "answer": "ب ر د", "acceptedAnswers": ["ب ر د"], "explanation": "Révision : le ا de بَارِد allonge la voyelle (bâ), il ne fait pas partie de la racine. Les 3 consonnes du sens « froid » sont ب ر د, comme dans بَرْد (le froid).", "tip": "Pour trouver la racine, enlève les ا و ي qui allongent une voyelle.", "extraExample": {"text": "بَرْد", "translation": "le froid (même racine ب ر د)", "transliteration": "bard"}, "errorPatterns": [{"equals": "ب ا ر", "category": "spelling", "feedback": "Le ا n''est pas une consonne de la racine : il allonge le a. La racine est ب ر د."}, {"equals": "ا ر د", "category": "spelling", "feedback": "Le mot commence par ب, pas par ا : la racine est ب ر د."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e13', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.warda']::text[], 'fill_blank', 'lesson', 'وَ___دَة', array['رْ']::text[], 'La rose se lit war-da : après وَ, il faut ر avec un soukoun. ز et ذ portent un point au-dessus ; seul ر n''en a aucun.', 3, '{"id": "ar.l19.e13", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.warda"], "type": "fill_blank", "difficulty": 3, "instruction": "Quelle lettre manque dans « la rose » ?", "prompt": "وَ___دَة", "promptLanguage": "ar", "options": ["رْ", "زْ", "ذْ"], "answer": "رْ", "acceptedAnswers": ["رْ"], "hint": "Le mot se lit war-da.", "explanation": "La rose se lit war-da : après وَ, il faut ر avec un soukoun. ز et ذ portent un point au-dessus ; seul ر n''en a aucun.", "tip": "ر n''a jamais de point ; ز et ذ en ont un.", "extraExample": {"text": "وُرُود", "translation": "des roses (pluriel)", "transliteration": "wurûd"}, "errorPatterns": [{"equals": "زْ", "category": "spelling", "feedback": "ز a un point au-dessus : le mot se lirait wazda. Pour war-da il faut ر, sans point."}, {"equals": "ذْ", "category": "spelling", "feedback": "ذ a un point au-dessus et se lit dh : le mot se lirait wadhda. Il faut ر, sans point."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e14', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.aruzz','ar.v.harr']::text[], 'fill_blank', 'lesson', 'الْأَرُزُّ ___', array['حَارٌّ']::text[], '« Chaud » = حَارّ : ح (aucun point), un ا, puis ر avec chadda. بَارِد veut dire froid (ب a un point dessous) et جَار est un voisin (ج a un point dedans).', 3, '{"id": "ar.l19.e14", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.aruzz", "ar.v.harr"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Le riz est chaud. »", "prompt": "الْأَرُزُّ ___", "promptLanguage": "ar", "options": ["حَارٌّ", "بَارِدٌ", "جَارٌ"], "answer": "حَارٌّ", "acceptedAnswers": ["حَارٌّ"], "explanation": "« Chaud » = حَارّ : ح (aucun point), un ا, puis ر avec chadda. بَارِد veut dire froid (ب a un point dessous) et جَار est un voisin (ج a un point dedans).", "tip": "Compare la première lettre : ح (sans point), ب (point dessous), ج (point dedans).", "extraExample": {"text": "الْأَرُزُّ بَارِدٌ", "translation": "Le riz est froid.", "transliteration": "al-''aruzzu bârid"}, "errorPatterns": [{"equals": "بَارِدٌ", "category": "word_confusion", "feedback": "بَارِدٌ veut dire « froid ». « Chaud » se dit حَارٌّ."}, {"equals": "جَارٌ", "category": "word_confusion", "feedback": "جَارٌ veut dire « un voisin » : ce n''est pas une température."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e15', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.warda']::text[], 'reorder', 'lesson', 'Les 4 blocs de وَرْدَة, dans l''ordre', array['وَ رْ دَ ة']::text[], 'On lit de droite à gauche : وَ (wa), رْ (r), دَ (da), ة (a final). Chaque lettre est un bloc, car و ر د ne s''attachent pas à la suivante.', 2, '{"id": "ar.l19.e15", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.warda"], "type": "reorder", "difficulty": 2, "instruction": "Remets les blocs dans l''ordre pour lire « la rose ».", "prompt": "Les 4 blocs de وَرْدَة, dans l''ordre", "promptLanguage": "fr", "tokens": ["دَ", "وَ", "ة", "رْ"], "answer": "وَ رْ دَ ة", "acceptedAnswers": ["وَ رْ دَ ة"], "hint": "Le mot commence par و.", "explanation": "On lit de droite à gauche : وَ (wa), رْ (r), دَ (da), ة (a final). Chaque lettre est un bloc, car و ر د ne s''attachent pas à la suivante.", "tip": "Le premier bloc est celui de droite.", "extraExample": {"text": "وَرْدَةٌ", "translation": "une rose", "transliteration": "wardatun"}, "pool": "lesson", "lessonId": "ar.l19", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e16', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.dhahaba','ar.v.ila','ar.v.chari']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : il est allé / vers / la rue', array['ذَهَبَ إِلَى الشَّارِعِ']::text[], 'Le verbe ouvre la phrase (ذَهَبَ), puis la direction إِلَى, puis le lieu avec l''article (الشَّارِعِ, finale en kasra après إِلَى).', 3, '{"id": "ar.l19.e16", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.dhahaba", "ar.v.ila", "ar.v.chari"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Il est allé dans la rue. »", "prompt": "Remets dans l''ordre : il est allé / vers / la rue", "promptLanguage": "fr", "tokens": ["الشَّارِعِ", "ذَهَبَ", "إِلَى"], "answer": "ذَهَبَ إِلَى الشَّارِعِ", "acceptedAnswers": ["ذَهَبَ إِلَى الشَّارِعِ"], "explanation": "Le verbe ouvre la phrase (ذَهَبَ), puis la direction إِلَى, puis le lieu avec l''article (الشَّارِعِ, finale en kasra après إِلَى).", "tip": "Verbe, puis إِلَى, puis le lieu.", "extraExample": {"text": "ذَهَبَ إِلَى الْمَكْتَبِ", "translation": "Il est allé au bureau.", "transliteration": "dhahaba ''ilâ l-maktab"}, "pool": "lesson", "lessonId": "ar.l19", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e17', 'ar', 'ar.l19', 'ar.v.radjul', array['ar.v.radjul','ar.g19.non_connecting_letters','ar.v.dhahaba','ar.v.madina','ar.v.ila']::text[], 'translation', 'lesson', 'ذَهَبَ الرَّجُلُ إِلَى الْمَدِينَةِ', array['L''homme est allé à la ville.','L''homme est allé en ville.','L''homme est allé dans la ville.','L''homme alla à la ville.','L''homme s''est rendu en ville.']::text[], 'ذَهَبَ = il est allé ; الرَّجُلُ = l''homme (devant ر, le ل de l''article ne se prononce pas) ; إِلَى = à, vers ; الْمَدِينَةِ = la ville. Beaucoup de coupures, mais 4 mots seulement.', 3, '{"id": "ar.l19.e17", "unitIds": ["ar.v.radjul", "ar.g19.non_connecting_letters", "ar.v.dhahaba", "ar.v.madina", "ar.v.ila"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "ذَهَبَ الرَّجُلُ إِلَى الْمَدِينَةِ", "promptLanguage": "ar", "answer": "L''homme est allé à la ville.", "acceptedAnswers": ["L''homme est allé à la ville.", "L''homme est allé en ville.", "L''homme est allé dans la ville.", "L''homme alla à la ville.", "L''homme s''est rendu en ville."], "explanation": "ذَهَبَ = il est allé ; الرَّجُلُ = l''homme (devant ر, le ل de l''article ne se prononce pas) ; إِلَى = à, vers ; الْمَدِينَةِ = la ville. Beaucoup de coupures, mais 4 mots seulement.", "tip": "Traduis mot par mot : verbe, sujet, direction, lieu.", "extraExample": {"text": "ذَهَبَ الْوَلَدُ إِلَى الْمَدْرَسَةِ", "translation": "Le garçon est allé à l''école.", "transliteration": "dhahaba l-waladu ''ilâ l-madrasa"}, "errorPatterns": [{"contains": "garçon", "category": "vocabulary", "feedback": "الرَّجُل est l''homme ; le garçon se dit الْوَلَد."}, {"contains": "femme", "category": "vocabulary", "feedback": "الرَّجُل est l''homme, pas la femme."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e18', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.wa','ar.v.warda','ar.v.kitab']::text[], 'translation', 'lesson', 'كِتَابٌ وَوَرْدَةٌ', array['un livre et une rose','un livre et une fleur','le livre et la rose','livre et rose']::text[], 'كِتَابٌ = un livre ; وَ = et ; وَرْدَةٌ = une rose. وَ se colle au mot suivant et ne s''attache pas à gauche : on lit donc وَوَرْدَةٌ, wa + wardatun, avec deux و à la suite.', 4, '{"id": "ar.l19.e18", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.wa", "ar.v.warda", "ar.v.kitab"], "type": "translation", "difficulty": 4, "instruction": "Traduis en français.", "prompt": "كِتَابٌ وَوَرْدَةٌ", "promptLanguage": "ar", "answer": "un livre et une rose", "acceptedAnswers": ["un livre et une rose", "un livre et une fleur", "le livre et la rose", "livre et rose"], "explanation": "كِتَابٌ = un livre ; وَ = et ; وَرْدَةٌ = une rose. وَ se colle au mot suivant et ne s''attache pas à gauche : on lit donc وَوَرْدَةٌ, wa + wardatun, avec deux و à la suite.", "tip": "وَ (et) ne s''écrit jamais seul : il se colle au mot qui suit.", "extraExample": {"text": "وَرْدَةٌ وَشَجَرَةٌ", "translation": "une rose et un arbre", "transliteration": "wardatun wa-chadjara"}, "errorPatterns": [{"contains": "bureau", "category": "word_confusion", "feedback": "Le bureau se dit مَكْتَب. Ici كِتَابٌ est le livre."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e19', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.madina']::text[], 'free_answer', 'lesson', 'Comment se lit مَدِينَة ?', array['madîna','madiina','madina']::text[], 'مَ = ma, دِي = dî (kasra + ي = î long), نَة = na : ma-dî-na. Le د coupe le mot en deux blocs, mais la lecture se fait d''un trait.', 3, '{"id": "ar.l19.e19", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.madina"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture de ce mot en lettres latines.", "prompt": "Comment se lit مَدِينَة ?", "promptLanguage": "fr", "answer": "madîna", "acceptedAnswers": ["madîna", "madiina", "madina"], "hint": "Le ي après la kasra allonge le i.", "explanation": "مَ = ma, دِي = dî (kasra + ي = î long), نَة = na : ma-dî-na. Le د coupe le mot en deux blocs, mais la lecture se fait d''un trait.", "tip": "Kasra + ي = î : écris î, ou ii.", "extraExample": {"text": "هٰذِهِ مَدِينَةٌ كَبِيرَةٌ", "translation": "C''est une grande ville.", "transliteration": "hâdhihi madînatun kabîra"}, "errorPatterns": [{"equals": "madna", "category": "spelling", "feedback": "Le ي après la kasra est une voyelle longue : ma-dî-na, trois syllabes."}, {"equals": "madrasa", "category": "word_confusion", "feedback": "madrasa, c''est مَدْرَسَة (l''école), avec un ر. Ici : ma-dî-na."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l19.e20', 'ar', 'ar.l19', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.chari']::text[], 'free_answer', 'lesson', 'Comment se lit شَارِع ?', array['châri3','chaari3','chari3','shaari3','shari3','shâri3']::text[], 'شَا = châ (fatha + ا), رِ = ri, ع = 3 : châ-ri3. Trois blocs, شا | ر | ع, mais un seul mot.', 4, '{"id": "ar.l19.e20", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.chari"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture de ce mot en lettres latines.", "prompt": "Comment se lit شَارِع ?", "promptLanguage": "fr", "answer": "châri3", "acceptedAnswers": ["châri3", "chaari3", "chari3", "shaari3", "shari3", "shâri3"], "hint": "ع se transcrit 3.", "explanation": "شَا = châ (fatha + ا), رِ = ri, ع = 3 : châ-ri3. Trois blocs, شا | ر | ع, mais un seul mot.", "tip": "Pour écrire ع, utilise le chiffre 3.", "extraExample": {"text": "السُّوقُ فِي هٰذَا الشَّارِعِ", "translation": "Le marché est dans cette rue.", "transliteration": "as-sûqu fî hâdhâ ch-châri3"}, "errorPatterns": [{"equals": "chari", "category": "spelling", "feedback": "Il manque le ع final, qui se prononce du fond de la gorge : châri3."}, {"equals": "chara3", "category": "spelling", "feedback": "Sous le ر il y a une kasra : ri, pas ra."}], "pool": "lesson", "lessonId": "ar.l19", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e01', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.matam']::text[], 'mcq', 'lesson', 'مَطْعَم', array['maT3am']::text[], 'مَ = ma, طْ = T (le soukoun supprime la voyelle), عَ = 3a, م = m : maT-3am, « le restaurant ». Aucune lettre ne coupe : un seul bloc de 4 lettres.', 1, '{"id": "ar.l20.e01", "unitIds": ["ar.g20.long_words_blocks", "ar.v.matam"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "مَطْعَم", "promptLanguage": "ar", "options": ["maT3am", "maTa3am", "maT3im", "maT3um"], "answer": "maT3am", "acceptedAnswers": ["maT3am"], "explanation": "مَ = ma, طْ = T (le soukoun supprime la voyelle), عَ = 3a, م = m : maT-3am, « le restaurant ». Aucune lettre ne coupe : un seul bloc de 4 lettres.", "tip": "Cherche le soukoun d''abord : il te dit où la première syllabe se ferme (maT).", "extraExample": {"text": "هُوَ فِي الْمَطْعَمِ", "translation": "Il est au restaurant.", "transliteration": "huwa fî l-maT3am"}, "errorPatterns": [{"equals": "maTa3am", "category": "spelling", "feedback": "Le soukoun (ـْ) sur ط supprime la voyelle : maT-3am, pas ma-Ta-3am."}, {"equals": "maT3im", "category": "spelling", "feedback": "Sur ع il y a une fatha (a), pas une kasra : 3am."}, {"equals": "maT3um", "category": "spelling", "feedback": "Sur ع il y a une fatha (a), pas une damma : 3am."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e02', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.sayyara']::text[], 'mcq', 'lesson', 'En combien de blocs s''écrit سَيَّارَة ?', array['3']::text[], 'سَيَّارَة a 5 lettres mais seulement 3 blocs : سيا | ر | ة. Seuls le ا et le ر coupent le mot.', 1, '{"id": "ar.l20.e02", "unitIds": ["ar.g20.long_words_blocks", "ar.v.sayyara"], "type": "mcq", "difficulty": 1, "instruction": "Compte les blocs.", "prompt": "En combien de blocs s''écrit سَيَّارَة ?", "promptLanguage": "fr", "options": ["2", "3", "5"], "answer": "3", "acceptedAnswers": ["3"], "explanation": "سَيَّارَة a 5 lettres mais seulement 3 blocs : سيا | ر | ة. Seuls le ا et le ر coupent le mot.", "tip": "Compte les coupures, pas les lettres.", "extraExample": {"text": "هٰذِهِ سَيَّارَةٌ جَدِيدَةٌ", "translation": "C''est une voiture neuve.", "transliteration": "hâdhihi sayyâratun djadîda"}, "errorPatterns": [{"equals": "5", "category": "spelling", "feedback": "5 est le nombre de lettres. Les blocs se comptent aux coupures : après le ا et après le ر."}, {"equals": "2", "category": "spelling", "feedback": "Il y a deux coupures (après ا, après ر), donc trois blocs."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e03', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.mustachfa','ar.v.matam','ar.v.sayyara','ar.v.burtuqal','ar.v.tuffaha']::text[], 'match', 'lesson', 'Cinq mots longs, cinq lectures', '{}'::text[], 'Découpe en syllabes pour lire sans épeler : mus-tach-fâ, maT-3am, say-yâ-ra, bur-tu-qâl, tuf-fâ-7a. Les voyelles longues (ا, ى) et les chaddas guident ton œil.', 1, '{"id": "ar.l20.e03", "unitIds": ["ar.g20.long_words_blocks", "ar.v.mustachfa", "ar.v.matam", "ar.v.sayyara", "ar.v.burtuqal", "ar.v.tuffaha"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Cinq mots longs, cinq lectures", "promptLanguage": "fr", "pairs": [{"left": "مُسْتَشْفَى", "right": "mustachfâ"}, {"left": "مَطْعَم", "right": "maT3am"}, {"left": "سَيَّارَة", "right": "sayyâra"}, {"left": "بُرْتُقَال", "right": "burtuqâl"}, {"left": "تُفَّاحَة", "right": "tuffâ7a"}], "answer": "مُسْتَشْفَى = mustachfâ ; مَطْعَم = maT3am ; سَيَّارَة = sayyâra ; بُرْتُقَال = burtuqâl ; تُفَّاحَة = tuffâ7a", "acceptedAnswers": [], "explanation": "Découpe en syllabes pour lire sans épeler : mus-tach-fâ, maT-3am, say-yâ-ra, bur-tu-qâl, tuf-fâ-7a. Les voyelles longues (ا, ى) et les chaddas guident ton œil.", "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e04', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.tuffaha']::text[], 'mcq', 'lesson', 'تُفَّاحَة', array['tuffâ7a']::text[], 'تُ = tu, فَّا = ffâ (la chadda double le f, le ا allonge le a), حَة = 7a : tuf-fâ-7a, « la pomme ». Deux blocs : تفا | حة.', 2, '{"id": "ar.l20.e04", "unitIds": ["ar.g20.long_words_blocks", "ar.v.tuffaha"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "تُفَّاحَة", "promptLanguage": "ar", "options": ["tuffâ7a", "tufa7a", "tafâ7a", "tuffâkha"], "answer": "tuffâ7a", "acceptedAnswers": ["tuffâ7a"], "explanation": "تُ = tu, فَّا = ffâ (la chadda double le f, le ا allonge le a), حَة = 7a : tuf-fâ-7a, « la pomme ». Deux blocs : تفا | حة.", "tip": "Chadda = deux consonnes : tuf-fâ, jamais tu-fâ.", "extraExample": {"text": "أَكَلَ تُفَّاحَةً", "translation": "Il a mangé une pomme.", "transliteration": "''akala tuffâ7a"}, "errorPatterns": [{"equals": "tufa7a", "category": "spelling", "feedback": "La chadda sur ف double la lettre (ff) et le ا allonge le a : tuf-fâ-7a."}, {"equals": "tuffâkha", "category": "spelling", "feedback": "ح n''a aucun point : 7, pas kh."}, {"equals": "tafâ7a", "category": "spelling", "feedback": "La première lettre porte une damma (u), pas une fatha."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e05', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.matam','ar.v.madrasa','ar.v.maktab']::text[], 'mcq', 'lesson', 'Quel début est commun à مَطْعَم, مَدْرَسَة et مَكْتَب ?', array['مَـ']::text[], 'Ces trois mots commencent par مَـ, qui indique souvent un lieu : où l''on mange (مَطْعَم), où l''on étudie (مَدْرَسَة), où l''on écrit (مَكْتَب).', 2, '{"id": "ar.l20.e05", "unitIds": ["ar.g20.long_words_blocks", "ar.v.matam", "ar.v.madrasa", "ar.v.maktab"], "type": "mcq", "difficulty": 2, "instruction": "Repère le morceau qui revient.", "prompt": "Quel début est commun à مَطْعَم, مَدْرَسَة et مَكْتَب ?", "promptLanguage": "fr", "options": ["مَـ", "مُسْتَـ", "مِنْ", "وَ"], "answer": "مَـ", "acceptedAnswers": ["مَـ"], "explanation": "Ces trois mots commencent par مَـ, qui indique souvent un lieu : où l''on mange (مَطْعَم), où l''on étudie (مَدْرَسَة), où l''on écrit (مَكْتَب).", "tip": "مَـ au début d''un mot = souvent un lieu.", "extraExample": {"text": "مَطَار", "translation": "l''aéroport : مَـ + la racine « voler »", "transliteration": "maTâr"}, "errorPatterns": [{"equals": "مُسْتَـ", "category": "word_confusion", "feedback": "مُسْتَـ est le début de مُسْتَشْفَى (l''hôpital), pas de ces trois mots."}, {"equals": "وَ", "category": "word_confusion", "feedback": "وَ veut dire « et » : c''est un petit mot, pas le début de ces trois noms."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e06', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.sabah','ar.v.masa','ar.v.ala','ar.v.kabir','ar.v.burtuqal']::text[], 'match', 'lesson', 'Lis chaque mot et retrouve son sens', '{}'::text[], 'صَبَاح (Sa-bâ7) et مَسَاء (ma-sâ'') ont une voyelle longue au milieu ; عَلَى se lit 3alâ (le ى final = â) ; كَبِير : ka-bîr (kasra + ي = î).', 2, '{"id": "ar.l20.e06", "unitIds": ["ar.g20.long_words_blocks", "ar.v.sabah", "ar.v.masa", "ar.v.ala", "ar.v.kabir", "ar.v.burtuqal"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Lis chaque mot et retrouve son sens", "promptLanguage": "fr", "pairs": [{"left": "صَبَاح", "right": "le matin"}, {"left": "مَسَاء", "right": "le soir"}, {"left": "عَلَى", "right": "sur"}, {"left": "كَبِير", "right": "grand"}, {"left": "بُرْتُقَال", "right": "l''orange"}], "answer": "صَبَاح = le matin ; مَسَاء = le soir ; عَلَى = sur ; كَبِير = grand ; بُرْتُقَال = l''orange", "acceptedAnswers": [], "explanation": "صَبَاح (Sa-bâ7) et مَسَاء (ma-sâ'') ont une voyelle longue au milieu ; عَلَى se lit 3alâ (le ى final = â) ; كَبِير : ka-bîr (kasra + ي = î).", "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e07', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.sayyara']::text[], 'mcq', 'lesson', 'Que veut dire سَيَّارَات ?', array['des voitures']::text[], 'ـَات à la fin d''un mot marque le pluriel : سَيَّارَة (une voiture) devient سَيَّارَات (des voitures).', 2, '{"id": "ar.l20.e07", "unitIds": ["ar.g20.long_words_blocks", "ar.v.sayyara"], "type": "mcq", "difficulty": 2, "instruction": "Reconnais la finale.", "prompt": "Que veut dire سَيَّارَات ?", "promptLanguage": "fr", "options": ["des voitures", "la voiture", "des pommes", "des aéroports"], "answer": "des voitures", "acceptedAnswers": ["des voitures"], "explanation": "ـَات à la fin d''un mot marque le pluriel : سَيَّارَة (une voiture) devient سَيَّارَات (des voitures).", "tip": "ـَة = un seul ; ـَات = plusieurs.", "extraExample": {"text": "مُسْتَشْفَيَات", "translation": "des hôpitaux", "transliteration": "mustachfayât"}, "errorPatterns": [{"equals": "la voiture", "category": "grammar", "feedback": "Il y a ـَات à la fin, pas ـَة : c''est le pluriel."}, {"equals": "des aéroports", "category": "word_confusion", "feedback": "« Des aéroports » se dit مَطَارَات. Ici le mot commence par سَيَّ, comme سَيَّارَة."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e08', 'ar', 'ar.l20', 'ar.v.matar', array['ar.v.matar','ar.g20.long_words_blocks','ar.v.matar_aeroport','ar.v.matam','ar.v.madrasa']::text[], 'mcq', 'lesson', 'Trois de ces mots sont des lieux. Lequel n''en est pas un ?', array['مَطَر']::text[], 'مَطْعَم (restaurant), مَطَار (aéroport) et مَدْرَسَة (école) sont des lieux. مَطَر (la pluie) commence aussi par مَـ, mais ce م fait partie de sa racine (م ط ر) : ce n''est pas le préfixe « lieu ».', 3, '{"id": "ar.l20.e08", "unitIds": ["ar.v.matar", "ar.g20.long_words_blocks", "ar.v.matar_aeroport", "ar.v.matam", "ar.v.madrasa"], "type": "mcq", "difficulty": 3, "instruction": "Trouve l''intrus.", "prompt": "Trois de ces mots sont des lieux. Lequel n''en est pas un ?", "promptLanguage": "fr", "options": ["مَطْعَم", "مَطَار", "مَدْرَسَة", "مَطَر"], "answer": "مَطَر", "acceptedAnswers": ["مَطَر"], "explanation": "مَطْعَم (restaurant), مَطَار (aéroport) et مَدْرَسَة (école) sont des lieux. مَطَر (la pluie) commence aussi par مَـ, mais ce م fait partie de sa racine (م ط ر) : ce n''est pas le préfixe « lieu ».", "tip": "Un seul ا de différence change tout : مَطَر (pluie) ≠ مَطَار (aéroport).", "extraExample": {"text": "الْمَطَرُ بَارِدٌ", "translation": "La pluie est froide.", "transliteration": "al-maTaru bârid"}, "errorPatterns": [{"equals": "مَطَار", "category": "word_confusion", "feedback": "مَطَار est l''aéroport, un lieu (avec un ا long). L''intrus est la pluie."}, {"equals": "مَطْعَم", "category": "word_confusion", "feedback": "مَطْعَم est le restaurant, un lieu."}, {"equals": "مَدْرَسَة", "category": "word_confusion", "feedback": "مَدْرَسَة est l''école, un lieu."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e09', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.mustachfa']::text[], 'mcq', 'lesson', 'مُسْتَشْفَى', array['mustachfâ']::text[], 'مُسْ = mus, تَشْ = tach, فَى = fâ : mus-tach-fâ. Le soukoun sur س et sur ش empêche d''ajouter une voyelle ; le ى final se lit â.', 2, '{"id": "ar.l20.e09", "unitIds": ["ar.g20.long_words_blocks", "ar.v.mustachfa"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "مُسْتَشْفَى", "promptLanguage": "ar", "options": ["mustachfâ", "mustachifâ", "mustachfa", "mustakhfâ"], "answer": "mustachfâ", "acceptedAnswers": ["mustachfâ"], "explanation": "مُسْ = mus, تَشْ = tach, فَى = fâ : mus-tach-fâ. Le soukoun sur س et sur ش empêche d''ajouter une voyelle ; le ى final se lit â.", "tip": "Deux soukouns, trois syllabes : mus-tach-fâ.", "extraExample": {"text": "الْمُسْتَشْفَى فِي الْمَدِينَةِ", "translation": "L''hôpital est en ville.", "transliteration": "al-mustachfâ fî l-madîna"}, "errorPatterns": [{"equals": "mustachifâ", "category": "spelling", "feedback": "Le soukoun sur ش supprime la voyelle : tach-fâ, pas ta-chi-fâ."}, {"equals": "mustachfa", "category": "spelling", "feedback": "Le ى final sans points se lit â (long), comme un ا : fâ."}, {"equals": "mustakhfâ", "category": "spelling", "feedback": "ش a trois points : ch, pas kh."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e10', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.sayyara','ar.v.burtuqal','ar.v.mustachfa','ar.v.tuffaha','ar.v.matam']::text[], 'match', 'lesson', 'Découpe chaque mot long en blocs', '{}'::text[], 'Un seul bloc quand aucune lettre ne coupe (مستشفى, مطعم). Sinon on coupe après chaque ا, د, ذ, ر, ز, و : سيا | ر | ة, بر | تقا | ل, تفا | حة.', 2, '{"id": "ar.l20.e10", "unitIds": ["ar.g20.long_words_blocks", "ar.v.sayyara", "ar.v.burtuqal", "ar.v.mustachfa", "ar.v.tuffaha", "ar.v.matam"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à son découpage en blocs.", "prompt": "Découpe chaque mot long en blocs", "promptLanguage": "fr", "pairs": [{"left": "سَيَّارَة", "right": "سيا | ر | ة"}, {"left": "بُرْتُقَال", "right": "بر | تقا | ل"}, {"left": "مُسْتَشْفَى", "right": "مستشفى"}, {"left": "تُفَّاحَة", "right": "تفا | حة"}, {"left": "مَطْعَم", "right": "مطعم"}], "answer": "سَيَّارَة = سيا | ر | ة ; بُرْتُقَال = بر | تقا | ل ; مُسْتَشْفَى = مستشفى ; تُفَّاحَة = تفا | حة ; مَطْعَم = مطعم", "acceptedAnswers": [], "explanation": "Un seul bloc quand aucune lettre ne coupe (مستشفى, مطعم). Sinon on coupe après chaque ا, د, ذ, ر, ز, و : سيا | ر | ة, بر | تقا | ل, تفا | حة.", "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e11', 'ar', 'ar.l20', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.burtuqal','ar.g20.long_words_blocks']::text[], 'mcq', 'lesson', 'Combien de syllabes dans بُرْتُقَال ?', array['3']::text[], 'Révision : بُرْ (fermée, soukoun sur ر) + تُ (ouverte) + قَال (qâl, voyelle longue puis ل) = bur-tu-qâl. Une voyelle longue ne fait qu''une syllabe.', 3, '{"id": "ar.l20.e11", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.burtuqal", "ar.g20.long_words_blocks"], "type": "mcq", "difficulty": 3, "instruction": "Compte avec les voyelles.", "prompt": "Combien de syllabes dans بُرْتُقَال ?", "promptLanguage": "fr", "options": ["2", "3", "4"], "answer": "3", "acceptedAnswers": ["3"], "explanation": "Révision : بُرْ (fermée, soukoun sur ر) + تُ (ouverte) + قَال (qâl, voyelle longue puis ل) = bur-tu-qâl. Une voyelle longue ne fait qu''une syllabe.", "tip": "Une voyelle (brève ou longue) = une syllabe.", "extraExample": {"text": "مَدْرَسَة", "translation": "l''école : 3 syllabes, mad-ra-sa", "transliteration": "madrasa"}, "errorPatterns": [{"equals": "4", "category": "spelling", "feedback": "Une voyelle longue (ا) ne fait qu''une syllabe : qâl, pas qa-al."}, {"equals": "2", "category": "spelling", "feedback": "Il y a trois voyelles : u, u, â. Donc trois syllabes."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e12', 'ar', 'ar.l20', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.mustachfa','ar.g20.long_words_blocks']::text[], 'mcq', 'lesson', 'En combien de blocs s''écrit مُسْتَشْفَى ?', array['1']::text[], 'Révision des coupures : aucune des lettres م س ت ش ف ne coupe le mot. Le ى final s''arrête là : il reste un seul bloc de 6 lettres.', 3, '{"id": "ar.l20.e12", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.mustachfa", "ar.g20.long_words_blocks"], "type": "mcq", "difficulty": 3, "instruction": "Compte les blocs.", "prompt": "En combien de blocs s''écrit مُسْتَشْفَى ?", "promptLanguage": "fr", "options": ["1", "2", "3", "6"], "answer": "1", "acceptedAnswers": ["1"], "explanation": "Révision des coupures : aucune des lettres م س ت ش ف ne coupe le mot. Le ى final s''arrête là : il reste un seul bloc de 6 lettres.", "tip": "Pas de ا د ذ ر ز و au milieu du mot = un seul bloc.", "extraExample": {"text": "مَطْعَم", "translation": "le restaurant : un seul bloc aussi", "transliteration": "maT3am"}, "errorPatterns": [{"equals": "6", "category": "spelling", "feedback": "6 est le nombre de lettres. Les blocs se comptent aux coupures : ici il n''y en a aucune."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e13', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.burtuqal']::text[], 'fill_blank', 'lesson', 'bur - tu - ___', array['qâl']::text[], 'La dernière syllabe est قَال : qâl, avec un a long (fatha + ا). ق a deux points au-dessus (q), ك est une autre lettre (k).', 2, '{"id": "ar.l20.e13", "unitIds": ["ar.g20.long_words_blocks", "ar.v.burtuqal"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la lecture de بُرْتُقَال (l''orange).", "prompt": "bur - tu - ___", "promptLanguage": "fr", "options": ["qâl", "qal", "kâl"], "answer": "qâl", "acceptedAnswers": ["qâl"], "explanation": "La dernière syllabe est قَال : qâl, avec un a long (fatha + ا). ق a deux points au-dessus (q), ك est une autre lettre (k).", "tip": "Fatha + ا = a long : prolonge le son.", "extraExample": {"text": "بُرْتُقَالَةٌ", "translation": "une orange (une seule)", "transliteration": "burtuqâla"}, "errorPatterns": [{"equals": "qal", "category": "spelling", "feedback": "Le ا allonge le a : qâl, pas qal."}, {"equals": "kâl", "category": "spelling", "feedback": "La lettre est ق (deux points dessus) : q, pas k."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e14', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.ala']::text[], 'fill_blank', 'lesson', 'الْكِتَابُ ___ الْمَكْتَبِ', array['عَلَى']::text[], '« Sur » = عَلَى (3alâ). Il ressemble à إِلَى (vers) car les deux finissent par ى (qui se lit â), mais il commence par ع, pas par إ.', 2, '{"id": "ar.l20.e14", "unitIds": ["ar.g20.long_words_blocks", "ar.v.ala"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « Le livre est sur le bureau. »", "prompt": "الْكِتَابُ ___ الْمَكْتَبِ", "promptLanguage": "ar", "options": ["عَلَى", "إِلَى", "مِنْ"], "answer": "عَلَى", "acceptedAnswers": ["عَلَى"], "explanation": "« Sur » = عَلَى (3alâ). Il ressemble à إِلَى (vers) car les deux finissent par ى (qui se lit â), mais il commence par ع, pas par إ.", "tip": "عَلَى = sur (3alâ) ; إِلَى = vers (''ilâ).", "extraExample": {"text": "الشَّايُ عَلَى الْمَكْتَبِ", "translation": "Le thé est sur le bureau.", "transliteration": "ach-châyu 3alâ l-maktab"}, "errorPatterns": [{"equals": "إِلَى", "category": "word_confusion", "feedback": "إِلَى veut dire « vers » et commence par un alif. « Sur » commence par ع : عَلَى."}, {"equals": "مِنْ", "category": "word_confusion", "feedback": "مِنْ veut dire « de, depuis »."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e15', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.kabir','ar.v.sayyara']::text[], 'fill_blank', 'lesson', 'السَّيَّارَةُ ___', array['كَبِيرَةٌ']::text[], 'سَيَّارَة est féminin (finale ـة) : l''adjectif prend lui aussi ـة, كَبِيرَةٌ (ka-bîra). كَبِيرٌ est la forme masculine.', 3, '{"id": "ar.l20.e15", "unitIds": ["ar.g20.long_words_blocks", "ar.v.kabir", "ar.v.sayyara"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « La voiture est grande. »", "prompt": "السَّيَّارَةُ ___", "promptLanguage": "ar", "options": ["كَبِيرَةٌ", "كَبِيرٌ", "بَارِدَةٌ"], "answer": "كَبِيرَةٌ", "acceptedAnswers": ["كَبِيرَةٌ"], "explanation": "سَيَّارَة est féminin (finale ـة) : l''adjectif prend lui aussi ـة, كَبِيرَةٌ (ka-bîra). كَبِيرٌ est la forme masculine.", "tip": "Nom en ـة, adjectif en ـة.", "extraExample": {"text": "الْمَطَارُ كَبِيرٌ", "translation": "L''aéroport est grand.", "transliteration": "al-maTâru kabîr"}, "errorPatterns": [{"equals": "كَبِيرٌ", "category": "grammar", "feedback": "Le nom est féminin (ـة) : l''adjectif doit avoir ـة aussi."}, {"equals": "بَارِدَةٌ", "category": "word_confusion", "feedback": "بَارِدَةٌ veut dire « froide ». Ici on veut dire « grande »."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e16', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.mustachfa']::text[], 'reorder', 'lesson', 'Reconstitue le mot « l''hôpital » à partir de ses syllabes', array['مُسْ تَشْ فَى']::text[], 'On assemble de droite à gauche : مُسْ (mus) + تَشْ (tach) + فَى (fâ). Les deux premières syllabes sont fermées par un soukoun.', 3, '{"id": "ar.l20.e16", "unitIds": ["ar.g20.long_words_blocks", "ar.v.mustachfa"], "type": "reorder", "difficulty": 3, "instruction": "Remets les syllabes dans l''ordre pour lire « l''hôpital ».", "prompt": "Reconstitue le mot « l''hôpital » à partir de ses syllabes", "promptLanguage": "fr", "tokens": ["فَى", "مُسْ", "تَشْ"], "answer": "مُسْ تَشْ فَى", "acceptedAnswers": ["مُسْ تَشْ فَى"], "explanation": "On assemble de droite à gauche : مُسْ (mus) + تَشْ (tach) + فَى (fâ). Les deux premières syllabes sont fermées par un soukoun.", "tip": "Le soukoun ferme la syllabe : repère مُسْ et تَشْ.", "extraExample": {"text": "بُرْتُقَال", "translation": "l''orange : بُرْ + تُ + قَال", "transliteration": "burtuqâl"}, "pool": "lesson", "lessonId": "ar.l20", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e17', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.tuffaha','ar.v.sabah','ar.v.akala']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : il a mangé / une pomme / le matin', array['أَكَلَ تُفَّاحَةً فِي الصَّبَاحِ']::text[], 'Le verbe d''abord (أَكَلَ), puis ce qu''il a mangé (تُفَّاحَةً, avec tanwin -an), puis le moment avec فِي et l''article : الصَّبَاحِ.', 3, '{"id": "ar.l20.e17", "unitIds": ["ar.g20.long_words_blocks", "ar.v.tuffaha", "ar.v.sabah", "ar.v.akala"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Il a mangé une pomme le matin. »", "prompt": "Remets dans l''ordre : il a mangé / une pomme / le matin", "promptLanguage": "fr", "tokens": ["فِي", "تُفَّاحَةً", "الصَّبَاحِ", "أَكَلَ"], "answer": "أَكَلَ تُفَّاحَةً فِي الصَّبَاحِ", "acceptedAnswers": ["أَكَلَ تُفَّاحَةً فِي الصَّبَاحِ"], "explanation": "Le verbe d''abord (أَكَلَ), puis ce qu''il a mangé (تُفَّاحَةً, avec tanwin -an), puis le moment avec فِي et l''article : الصَّبَاحِ.", "tip": "Verbe, objet, moment.", "extraExample": {"text": "شَرِبَ الْقَهْوَةَ فِي الصَّبَاحِ", "translation": "Il a bu le café le matin.", "transliteration": "chariba l-qahwata fî S-Sabâ7"}, "pool": "lesson", "lessonId": "ar.l20", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e18', 'ar', 'ar.l20', 'ar.v.chari', array['ar.v.chari','ar.g20.long_words_blocks','ar.v.sayyara','ar.v.fi']::text[], 'translation', 'lesson', 'السَّيَّارَةُ فِي الشَّارِعِ', array['La voiture est dans la rue.','La voiture se trouve dans la rue.','La voiture est dans la rue']::text[], 'السَّيَّارَةُ = la voiture ; فِي = dans ; الشَّارِعِ = la rue. Au présent, le verbe « être » ne s''écrit pas.', 3, '{"id": "ar.l20.e18", "unitIds": ["ar.v.chari", "ar.g20.long_words_blocks", "ar.v.sayyara", "ar.v.fi"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "السَّيَّارَةُ فِي الشَّارِعِ", "promptLanguage": "ar", "answer": "La voiture est dans la rue.", "acceptedAnswers": ["La voiture est dans la rue.", "La voiture se trouve dans la rue.", "La voiture est dans la rue"], "explanation": "السَّيَّارَةُ = la voiture ; فِي = dans ; الشَّارِعِ = la rue. Au présent, le verbe « être » ne s''écrit pas.", "tip": "Au présent : nom + فِي + lieu, sans verbe « être ».", "extraExample": {"text": "الْمَطْعَمُ فِي الشَّارِعِ", "translation": "Le restaurant est dans la rue.", "transliteration": "al-maT3amu fî ch-châri3"}, "errorPatterns": [{"contains": "sur", "category": "preposition", "feedback": "فِي veut dire « dans » ; « sur » se dit عَلَى."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e19', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.mustachfa','ar.v.masa','ar.v.dhahaba']::text[], 'translation', 'lesson', 'ذَهَبَ إِلَى الْمُسْتَشْفَى فِي الْمَسَاءِ', array['Il est allé à l''hôpital le soir.','Il est allé à l''hôpital dans la soirée.','Il est allé à l''hôpital en soirée.','Il est allé à l''hôpital au soir.']::text[], 'ذَهَبَ إِلَى = il est allé à ; الْمُسْتَشْفَى = l''hôpital ; فِي الْمَسَاءِ = le soir (mot à mot : dans le soir).', 4, '{"id": "ar.l20.e19", "unitIds": ["ar.g20.long_words_blocks", "ar.v.mustachfa", "ar.v.masa", "ar.v.dhahaba"], "type": "translation", "difficulty": 4, "instruction": "Traduis en français.", "prompt": "ذَهَبَ إِلَى الْمُسْتَشْفَى فِي الْمَسَاءِ", "promptLanguage": "ar", "answer": "Il est allé à l''hôpital le soir.", "acceptedAnswers": ["Il est allé à l''hôpital le soir.", "Il est allé à l''hôpital dans la soirée.", "Il est allé à l''hôpital en soirée.", "Il est allé à l''hôpital au soir."], "explanation": "ذَهَبَ إِلَى = il est allé à ; الْمُسْتَشْفَى = l''hôpital ; فِي الْمَسَاءِ = le soir (mot à mot : dans le soir).", "tip": "Repère d''abord les petits mots (إِلَى, فِي) : ils découpent la phrase.", "extraExample": {"text": "جَلَسَ فِي الْمُسْتَشْفَى فِي الصَّبَاحِ", "translation": "Il s''est assis à l''hôpital le matin.", "transliteration": "djalasa fî l-mustachfâ fî S-Sabâ7"}, "errorPatterns": [{"contains": "matin", "category": "vocabulary", "feedback": "الصَّبَاح = le matin ; الْمَسَاء = le soir."}, {"contains": "restaurant", "category": "vocabulary", "feedback": "مَطْعَم = restaurant ; l''hôpital se dit مُسْتَشْفَى."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e20', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.matar_aeroport']::text[], 'free_answer', 'lesson', 'Comment se lit مَطَار ?', array['maTâr','maTaar']::text[], 'مَ = ma, طَا = Tâ (fatha + ا = a long), ر = r : ma-Târ, « l''aéroport ». Sans le ا, مَطَر se lit ma-Tar et veut dire « la pluie ».', 3, '{"id": "ar.l20.e20", "unitIds": ["ar.g20.long_words_blocks", "ar.v.matar_aeroport"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture de ce mot en lettres latines.", "prompt": "Comment se lit مَطَار ?", "promptLanguage": "fr", "answer": "maTâr", "acceptedAnswers": ["maTâr", "maTaar"], "hint": "Il y a un ا après ط.", "explanation": "مَ = ma, طَا = Tâ (fatha + ا = a long), ر = r : ma-Târ, « l''aéroport ». Sans le ا, مَطَر se lit ma-Tar et veut dire « la pluie ».", "tip": "Un ا de plus = une voyelle longue de plus : écris â, ou aa.", "extraExample": {"text": "هٰذَا مَطَارٌ كَبِيرٌ", "translation": "C''est un grand aéroport.", "transliteration": "hâdhâ maTârun kabîr"}, "errorPatterns": [{"equals": "matar", "category": "word_confusion", "feedback": "matar (sans voyelle longue), c''est مَطَر, la pluie. Ici il y a un ا : maTâr, l''aéroport."}, {"equals": "maTar", "category": "word_confusion", "feedback": "maTar (sans voyelle longue), c''est مَطَر, la pluie. Ici il y a un ا : maTâr, l''aéroport."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l20.e21', 'ar', 'ar.l20', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.sayyara']::text[], 'free_answer', 'lesson', 'Comment se lit سَيَّارَة ?', array['sayyâra','sayyaara','sayyara']::text[], 'سَ = sa, يَّا = yyâ (la chadda double le y, le ا allonge le a), رَة = ra : say-yâ-ra, « la voiture ».', 4, '{"id": "ar.l20.e21", "unitIds": ["ar.g20.long_words_blocks", "ar.v.sayyara"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture de ce mot en lettres latines.", "prompt": "Comment se lit سَيَّارَة ?", "promptLanguage": "fr", "answer": "sayyâra", "acceptedAnswers": ["sayyâra", "sayyaara", "sayyara"], "hint": "La chadda double le y.", "explanation": "سَ = sa, يَّا = yyâ (la chadda double le y, le ا allonge le a), رَة = ra : say-yâ-ra, « la voiture ».", "tip": "Chadda = lettre doublée : écris yy.", "extraExample": {"text": "سَيَّارَةٌ كَبِيرَةٌ", "translation": "une grande voiture", "transliteration": "sayyâratun kabîra"}, "errorPatterns": [{"equals": "sayara", "category": "spelling", "feedback": "La chadda double le y et le ا allonge le a : say-yâ-ra."}, {"equals": "sayyar", "category": "spelling", "feedback": "Le mot finit par ـَة : il y a un a final, say-yâ-ra."}], "pool": "lesson", "lessonId": "ar.l20", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e01', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters']::text[], 'mcq', 'lesson', 'Parmi ج ح خ, laquelle n''a aucun point ?', array['ح']::text[], 'Ces trois lettres ont le même dessin : seuls les points les distinguent. ج a un point à l''intérieur, خ un point au-dessus, et ح aucun.', 1, '{"id": "ar.l21.e01", "unitIds": ["ar.g21.lookalike_letters"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Parmi ج ح خ, laquelle n''a aucun point ?", "promptLanguage": "fr", "options": ["ح", "ج", "خ"], "answer": "ح", "acceptedAnswers": ["ح"], "hint": "C''est la lettre que l''on note 7.", "explanation": "Ces trois lettres ont le même dessin : seuls les points les distinguent. ج a un point à l''intérieur, خ un point au-dessus, et ح aucun.", "tip": "Même dessin, points différents : compte-les et regarde où ils sont.", "extraExample": {"text": "شَرِبَ الْحَلِيبَ", "translation": "Il a bu le lait.", "transliteration": "chariba l-7alîb"}, "errorPatterns": [{"equals": "ج", "category": "spelling", "feedback": "ج a un point à l''intérieur de la courbe."}, {"equals": "خ", "category": "spelling", "feedback": "خ a un point au-dessus."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e02', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.khubz']::text[], 'mcq', 'lesson', 'خُبْز', array['khubz']::text[], 'خُ = khu (خ a un point au-dessus), بْ = b (soukoun), ز = z (un point au-dessus) : khubz, « le pain ».', 1, '{"id": "ar.l21.e02", "unitIds": ["ar.g21.lookalike_letters", "ar.v.khubz"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "خُبْز", "promptLanguage": "ar", "options": ["khubz", "djubz", "7ubz", "khubr"], "answer": "khubz", "acceptedAnswers": ["khubz"], "explanation": "خُ = khu (خ a un point au-dessus), بْ = b (soukoun), ز = z (un point au-dessus) : khubz, « le pain ».", "tip": "Compte les points de la première et de la dernière lettre : ce sont elles qui piègent.", "extraExample": {"text": "أَكَلَ الْخُبْزَ", "translation": "Il a mangé le pain.", "transliteration": "''akala l-khubz"}, "errorPatterns": [{"equals": "djubz", "category": "spelling", "feedback": "ج a un point à l''intérieur ; ici le point est au-dessus : خ, kh."}, {"equals": "7ubz", "category": "spelling", "feedback": "ح n''a aucun point ; ici il y en a un au-dessus : خ, kh."}, {"equals": "khubr", "category": "spelling", "feedback": "ر n''a pas de point ; ici il y en a un au-dessus : ز, z."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e03', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.khubz','ar.v.djubn','ar.v.halib','ar.v.chay','ar.v.bayd']::text[], 'match', 'lesson', 'Cinq aliments, cinq jeux de points', '{}'::text[], 'خُبْز (خ), جُبْن (ج) et حَلِيب (ح) commencent par le trio ج ح خ ; شَاي commence par ش (trois points) ; بَيْض finit par ض (un point).', 1, '{"id": "ar.l21.e03", "unitIds": ["ar.g21.lookalike_letters", "ar.v.khubz", "ar.v.djubn", "ar.v.halib", "ar.v.chay", "ar.v.bayd"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à son sens.", "prompt": "Cinq aliments, cinq jeux de points", "promptLanguage": "fr", "pairs": [{"left": "خُبْز", "right": "le pain"}, {"left": "جُبْن", "right": "le fromage"}, {"left": "حَلِيب", "right": "le lait"}, {"left": "شَاي", "right": "le thé"}, {"left": "بَيْض", "right": "les œufs"}], "answer": "خُبْز = le pain ; جُبْن = le fromage ; حَلِيب = le lait ; شَاي = le thé ; بَيْض = les œufs", "acceptedAnswers": [], "explanation": "خُبْز (خ), جُبْن (ج) et حَلِيب (ح) commencent par le trio ج ح خ ; شَاي commence par ش (trois points) ; بَيْض finit par ض (un point).", "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e04', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.djubn','ar.v.khubz']::text[], 'mcq', 'lesson', 'Quel mot se lit djubn (le fromage) ?', array['جُبْن']::text[], 'Le fromage commence par ج (un point dedans) et finit par ن (un bol avec un point). خُبْز, le pain, commence par خ et finit par ز. Les deux autres combinaisons mélangent les lettres de ces deux mots.', 2, '{"id": "ar.l21.e04", "unitIds": ["ar.g21.lookalike_letters", "ar.v.djubn", "ar.v.khubz"], "type": "mcq", "difficulty": 2, "instruction": "Retrouve le mot qui correspond à la lecture.", "prompt": "Quel mot se lit djubn (le fromage) ?", "promptLanguage": "fr", "options": ["جُبْن", "خُبْن", "جُبْز", "خُبْز"], "answer": "جُبْن", "acceptedAnswers": ["جُبْن"], "explanation": "Le fromage commence par ج (un point dedans) et finit par ن (un bol avec un point). خُبْز, le pain, commence par خ et finit par ز. Les deux autres combinaisons mélangent les lettres de ces deux mots.", "tip": "Vérifie la première ET la dernière lettre.", "extraExample": {"text": "الْجُبْنُ مِنَ السُّوقِ", "translation": "Le fromage vient du marché.", "transliteration": "al-djubnu mina s-sûq"}, "errorPatterns": [{"equals": "خُبْن", "category": "spelling", "feedback": "Le début est خ (point au-dessus, kh). Pour dj, il faut le point à l''intérieur de ج."}, {"equals": "جُبْز", "category": "spelling", "feedback": "La fin est ز (un petit ر avec un point) ; le fromage finit par ن, un bol avec un point."}, {"equals": "خُبْز", "category": "word_confusion", "feedback": "خُبْز se lit khubz : c''est le pain, pas le fromage."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e05', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.sayf']::text[], 'mcq', 'lesson', 'صَيْف', array['Sayf']::text[], 'صَ = Sa (ص n''a aucun point), يْ = y avec soukoun (le son ay), ف = f (un point au-dessus) : Sayf, « l''été ».', 2, '{"id": "ar.l21.e05", "unitIds": ["ar.g21.lookalike_letters", "ar.v.sayf"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "صَيْف", "promptLanguage": "ar", "options": ["Sayf", "Dayf", "chayf", "Tayf"], "answer": "Sayf", "acceptedAnswers": ["Sayf"], "explanation": "صَ = Sa (ص n''a aucun point), يْ = y avec soukoun (le son ay), ف = f (un point au-dessus) : Sayf, « l''été ».", "tip": "Avec un point en plus, ص devient ض : صَيْف (l''été) ≠ ضَيْف (l''invité).", "extraExample": {"text": "الشَّمْسُ حَارَّةٌ فِي الصَّيْفِ", "translation": "Le soleil est chaud en été.", "transliteration": "ach-chamsu 7ârratun fî S-Sayf"}, "errorPatterns": [{"equals": "Dayf", "category": "spelling", "feedback": "ض a un point au-dessus ; ici ص n''en a pas : Sayf, l''été. Dayf (ضَيْف) est l''invité."}, {"equals": "chayf", "category": "spelling", "feedback": "ش a trois points et une autre forme ; ici la lettre est ص (S), sans point."}, {"equals": "Tayf", "category": "spelling", "feedback": "ط a une tige verticale ; ici la lettre est ص (S)."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e06', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters']::text[], 'match', 'lesson', 'Cinq lettres à points, cinq sons', '{}'::text[], 'ث : trois points au-dessus (th) ; خ : un point au-dessus de ح (kh) ; ش : trois points sur le dessin de س (ch) ; ض : un point sur ص (D) ; غ : un point sur ع (gh).', 2, '{"id": "ar.l21.e06", "unitIds": ["ar.g21.lookalike_letters"], "type": "match", "difficulty": 2, "instruction": "Associe chaque lettre à son son.", "prompt": "Cinq lettres à points, cinq sons", "promptLanguage": "fr", "pairs": [{"left": "ث", "right": "th"}, {"left": "خ", "right": "kh"}, {"left": "ش", "right": "ch"}, {"left": "ض", "right": "D"}, {"left": "غ", "right": "gh"}], "answer": "ث = th ; خ = kh ; ش = ch ; ض = D ; غ = gh", "acceptedAnswers": [], "explanation": "ث : trois points au-dessus (th) ; خ : un point au-dessus de ح (kh) ; ش : trois points sur le dessin de س (ch) ; ض : un point sur ص (D) ; غ : un point sur ع (gh).", "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e07', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.sayf']::text[], 'mcq', 'lesson', 'ضَيْف', array['l''invité']::text[], 'ضَيْف (Dayf) a un point de plus que صَيْف : c''est l''invité. Un seul point change tout le sens du mot.', 2, '{"id": "ar.l21.e07", "unitIds": ["ar.g21.lookalike_letters", "ar.v.sayf"], "type": "mcq", "difficulty": 2, "instruction": "Que veut dire ce mot ?", "prompt": "ضَيْف", "promptLanguage": "ar", "options": ["l''invité", "l''été", "le marché", "la neige"], "answer": "l''invité", "acceptedAnswers": ["l''invité"], "explanation": "ضَيْف (Dayf) a un point de plus que صَيْف : c''est l''invité. Un seul point change tout le sens du mot.", "tip": "ض = ص + un point.", "extraExample": {"text": "هٰذَا ضَيْفٌ جَدِيدٌ", "translation": "C''est un nouvel invité.", "transliteration": "hâdhâ Dayfun djadîd"}, "errorPatterns": [{"equals": "l''été", "category": "word_confusion", "feedback": "L''été se dit صَيْف, sans point. Ici ض a un point au-dessus : ضَيْف, l''invité."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e08', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.halib','ar.v.khubz','ar.v.djubn','ar.v.chay']::text[], 'mcq', 'lesson', 'Lequel de ces mots commence par une lettre SANS aucun point ?', array['حَلِيب']::text[], 'ح n''a aucun point. خ a un point au-dessus, ج un point à l''intérieur et ش trois points au-dessus.', 2, '{"id": "ar.l21.e08", "unitIds": ["ar.g21.lookalike_letters", "ar.v.halib", "ar.v.khubz", "ar.v.djubn", "ar.v.chay"], "type": "mcq", "difficulty": 2, "instruction": "Regarde la première lettre.", "prompt": "Lequel de ces mots commence par une lettre SANS aucun point ?", "promptLanguage": "fr", "options": ["حَلِيب", "خُبْز", "جُبْن", "شَاي"], "answer": "حَلِيب", "acceptedAnswers": ["حَلِيب"], "explanation": "ح n''a aucun point. خ a un point au-dessus, ج un point à l''intérieur et ش trois points au-dessus.", "tip": "Cherche les points de la première lettre : aucun, un, ou trois ?", "extraExample": {"text": "الْحَلِيبُ بَارِدٌ", "translation": "Le lait est froid.", "transliteration": "al-7alîbu bârid"}, "errorPatterns": [{"equals": "خُبْز", "category": "spelling", "feedback": "خ a un point au-dessus : ce n''est pas la lettre sans point."}, {"equals": "جُبْن", "category": "spelling", "feedback": "ج a un point à l''intérieur de la courbe."}, {"equals": "شَاي", "category": "spelling", "feedback": "ش a trois points au-dessus."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e09', 'ar', 'ar.l21', 'ar.v.kabir', array['ar.v.kabir','ar.v.saghir','ar.g21.lookalike_letters']::text[], 'mcq', 'lesson', 'Quel mot veut dire le contraire de صَغِير (petit) ?', array['كَبِير']::text[], 'صَغِير (Sa-ghîr) = petit, كَبِير (ka-bîr) = grand. Les deux finissent par ـِير ; regarde le début : صَغـ pour petit, كَبـ pour grand.', 2, '{"id": "ar.l21.e09", "unitIds": ["ar.v.kabir", "ar.v.saghir", "ar.g21.lookalike_letters"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le contraire.", "prompt": "Quel mot veut dire le contraire de صَغِير (petit) ?", "promptLanguage": "fr", "options": ["كَبِير", "حَارّ", "بَارِد", "جَدِيد"], "answer": "كَبِير", "acceptedAnswers": ["كَبِير"], "explanation": "صَغِير (Sa-ghîr) = petit, كَبِير (ka-bîr) = grand. Les deux finissent par ـِير ; regarde le début : صَغـ pour petit, كَبـ pour grand.", "tip": "Petit = ص + غ (un point) ; grand = ك + ب (un point dessous).", "extraExample": {"text": "الْمَطْعَمُ صَغِيرٌ", "translation": "Le restaurant est petit.", "transliteration": "al-maT3amu Saghîr"}, "errorPatterns": [{"equals": "بَارِد", "category": "word_confusion", "feedback": "بَارِد veut dire « froid » : une température, pas une taille."}, {"equals": "حَارّ", "category": "word_confusion", "feedback": "حَارّ veut dire « chaud » : une température, pas une taille."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e10', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.khubz','ar.v.djubn']::text[], 'fill_blank', 'lesson', 'الْخُبْزُ وَ___', array['الْجُبْنُ']::text[], '« Fromage » = جُبْن : ج avec un point à l''intérieur, puis ن. الْخُبْزُ est déjà dans la phrase et الْحَلِيبُ est le lait.', 2, '{"id": "ar.l21.e10", "unitIds": ["ar.g21.lookalike_letters", "ar.v.khubz", "ar.v.djubn"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « Le pain et le fromage. »", "prompt": "الْخُبْزُ وَ___", "promptLanguage": "ar", "options": ["الْجُبْنُ", "الْخُبْزُ", "الْحَلِيبُ"], "answer": "الْجُبْنُ", "acceptedAnswers": ["الْجُبْنُ"], "explanation": "« Fromage » = جُبْن : ج avec un point à l''intérieur, puis ن. الْخُبْزُ est déjà dans la phrase et الْحَلِيبُ est le lait.", "tip": "وَ (et) se colle au mot qui suit : وَالْجُبْنُ = wa + al-djubn.", "extraExample": {"text": "الْخُبْزُ وَالْحَلِيبُ", "translation": "Le pain et le lait.", "transliteration": "al-khubzu wa-l-7alîb"}, "errorPatterns": [{"equals": "الْحَلِيبُ", "category": "word_confusion", "feedback": "الْحَلِيبُ est le lait (ح, sans point). Le fromage commence par ج."}, {"equals": "الْخُبْزُ", "category": "word_confusion", "feedback": "الْخُبْزُ est le pain, déjà cité dans la phrase."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e11', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.bayd']::text[], 'fill_blank', 'lesson', 'بَيْ___', array['ض']::text[], 'Les œufs : بَيْض, avec ض (un point au-dessus, D). Avec ت (deux points) on lirait بَيْت, la maison ; ص n''a aucun point.', 2, '{"id": "ar.l21.e11", "unitIds": ["ar.g21.lookalike_letters", "ar.v.bayd"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le mot « les œufs ».", "prompt": "بَيْ___", "promptLanguage": "ar", "options": ["ض", "ت", "ص"], "answer": "ض", "acceptedAnswers": ["ض"], "explanation": "Les œufs : بَيْض, avec ض (un point au-dessus, D). Avec ت (deux points) on lirait بَيْت, la maison ; ص n''a aucun point.", "tip": "Dernière lettre : ض (1 point) ≠ ت (2 points) ≠ ص (aucun).", "extraExample": {"text": "أَكَلَ الْبَيْضَ", "translation": "Il a mangé les œufs.", "transliteration": "''akala l-bayD"}, "errorPatterns": [{"equals": "ت", "category": "word_confusion", "feedback": "بَيْت (bayt) est la maison. Les œufs finissent par ض."}, {"equals": "ص", "category": "spelling", "feedback": "ص n''a pas de point et se lit S. Les œufs finissent par ض, avec un point au-dessus."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e12', 'ar', 'ar.l21', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.suq','ar.g21.lookalike_letters']::text[], 'mcq', 'lesson', 'Un seul de ces mots se coupe en deux blocs. Lequel ?', array['سُوق']::text[], 'Révision des coupures : dans سُوق, le و ne s''attache pas à la lettre suivante : سو | ق. خُبْز, جُبْن et حَلِيب s''écrivent d''un seul bloc.', 2, '{"id": "ar.l21.e12", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.suq", "ar.g21.lookalike_letters"], "type": "mcq", "difficulty": 2, "instruction": "Compte les blocs.", "prompt": "Un seul de ces mots se coupe en deux blocs. Lequel ?", "promptLanguage": "fr", "options": ["سُوق", "خُبْز", "جُبْن", "حَلِيب"], "answer": "سُوق", "acceptedAnswers": ["سُوق"], "explanation": "Révision des coupures : dans سُوق, le و ne s''attache pas à la lettre suivante : سو | ق. خُبْز, جُبْن et حَلِيب s''écrivent d''un seul bloc.", "tip": "Cherche un ا د ذ ر ز و avant la dernière lettre.", "extraExample": {"text": "أَنَا فِي السُّوقِ", "translation": "Je suis au marché.", "transliteration": "''anâ fî s-sûq"}, "errorPatterns": [{"equals": "خُبْز", "category": "spelling", "feedback": "Le ز coupe, mais il est à la fin du mot : خُبْز reste un seul bloc."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e13', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.sayf','ar.v.thaldj','ar.v.suq','ar.v.saghir','ar.v.djubn']::text[], 'match', 'lesson', 'Lis chaque mot en vérifiant les points', '{}'::text[], 'Les points décident : صَيْف (ص sans point, ف un point) ; ثَلْج (ث, trois points) ; سُوق (س sans point, ق deux points) ; صَغِير (غ, un point) ; جُبْن (ج, point dedans).', 3, '{"id": "ar.l21.e13", "unitIds": ["ar.g21.lookalike_letters", "ar.v.sayf", "ar.v.thaldj", "ar.v.suq", "ar.v.saghir", "ar.v.djubn"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lis chaque mot en vérifiant les points", "promptLanguage": "fr", "pairs": [{"left": "صَيْف", "right": "Sayf"}, {"left": "ثَلْج", "right": "thaldj"}, {"left": "سُوق", "right": "sûq"}, {"left": "صَغِير", "right": "Saghîr"}, {"left": "جُبْن", "right": "djubn"}], "answer": "صَيْف = Sayf ; ثَلْج = thaldj ; سُوق = sûq ; صَغِير = Saghîr ; جُبْن = djubn", "acceptedAnswers": [], "explanation": "Les points décident : صَيْف (ص sans point, ف un point) ; ثَلْج (ث, trois points) ; سُوق (س sans point, ق deux points) ; صَغِير (غ, un point) ; جُبْن (ج, point dedans).", "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e14', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.khubz','ar.v.bayd','ar.v.saghir','ar.v.thaldj']::text[], 'mcq', 'lesson', 'Trois de ces mots contiennent une lettre avec UN point au-dessus. Lequel n''en a pas ?', array['ثَلْج']::text[], 'خُبْز a خ et ز, بَيْض a ض, صَغِير a غ : chacun a un point au-dessus. ثَلْج n''a que ث (trois points) et ج (un point dedans).', 3, '{"id": "ar.l21.e14", "unitIds": ["ar.g21.lookalike_letters", "ar.v.khubz", "ar.v.bayd", "ar.v.saghir", "ar.v.thaldj"], "type": "mcq", "difficulty": 3, "instruction": "Trouve l''intrus.", "prompt": "Trois de ces mots contiennent une lettre avec UN point au-dessus. Lequel n''en a pas ?", "promptLanguage": "fr", "options": ["خُبْز", "بَيْض", "صَغِير", "ثَلْج"], "answer": "ثَلْج", "acceptedAnswers": ["ثَلْج"], "explanation": "خُبْز a خ et ز, بَيْض a ض, صَغِير a غ : chacun a un point au-dessus. ثَلْج n''a que ث (trois points) et ج (un point dedans).", "tip": "Un point dedans ou dessous n''est pas un point au-dessus : regarde où il se trouve.", "extraExample": {"text": "لَا ثَلْجَ الْيَوْمَ", "translation": "Il n''y a pas de neige aujourd''hui.", "transliteration": "lâ thaldja l-yawm"}, "errorPatterns": [{"equals": "خُبْز", "category": "spelling", "feedback": "خُبْز contient خ et ز, qui ont chacune un point au-dessus."}, {"equals": "بَيْض", "category": "spelling", "feedback": "بَيْض contient ض, qui a un point au-dessus."}, {"equals": "صَغِير", "category": "spelling", "feedback": "صَغِير contient غ, qui a un point au-dessus."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e15', 'ar', 'ar.l21', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.halib','ar.g21.lookalike_letters']::text[], 'mcq', 'lesson', 'Quelle est la racine de حَلِيب (lait) ?', array['ح ل ب']::text[], 'Révision : le ي de حَلِيب allonge la voyelle (lîb), il ne fait pas partie de la racine. ح n''a aucun point : la racine est ح ل ب. Avec ج, ce serait une autre racine.', 3, '{"id": "ar.l21.e15", "unitIds": ["ar.g18.three_letter_roots", "ar.v.halib", "ar.g21.lookalike_letters"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la racine.", "prompt": "Quelle est la racine de حَلِيب (lait) ?", "promptLanguage": "fr", "options": ["ح ل ب", "ج ل ب", "ح ل ي"], "answer": "ح ل ب", "acceptedAnswers": ["ح ل ب"], "explanation": "Révision : le ي de حَلِيب allonge la voyelle (lîb), il ne fait pas partie de la racine. ح n''a aucun point : la racine est ح ل ب. Avec ج, ce serait une autre racine.", "tip": "Racine = 3 consonnes : retire le ي qui allonge, puis vérifie les points.", "extraExample": {"text": "حَلَبَ", "translation": "il a trait (le lait)", "transliteration": "7alaba"}, "errorPatterns": [{"equals": "ج ل ب", "category": "spelling", "feedback": "ج a un point dedans ; le lait commence par ح, sans point."}, {"equals": "ح ل ي", "category": "spelling", "feedback": "Le ي allonge la voyelle : ce n''est pas une consonne de la racine."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e16', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.thaldj']::text[], 'fill_blank', 'lesson', 'ثَلْ___', array['ج']::text[], 'La neige : ثَلْج. La dernière lettre a un point à l''intérieur de sa courbe : ج (dj). ح n''a aucun point et خ en a un au-dessus.', 3, '{"id": "ar.l21.e16", "unitIds": ["ar.g21.lookalike_letters", "ar.v.thaldj"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète le mot « la neige ».", "prompt": "ثَلْ___", "promptLanguage": "ar", "options": ["ج", "ح", "خ"], "answer": "ج", "acceptedAnswers": ["ج"], "explanation": "La neige : ثَلْج. La dernière lettre a un point à l''intérieur de sa courbe : ج (dj). ح n''a aucun point et خ en a un au-dessus.", "tip": "ج = point dedans, ح = aucun, خ = point dessus.", "extraExample": {"text": "الثَّلْجُ بَارِدٌ", "translation": "La neige est froide.", "transliteration": "ath-thaldju bârid"}, "errorPatterns": [{"equals": "ح", "category": "spelling", "feedback": "ح n''a aucun point : la neige finit par ج, avec un point à l''intérieur."}, {"equals": "خ", "category": "spelling", "feedback": "خ a un point au-dessus, pas à l''intérieur : la neige finit par ج."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e17', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.khubz','ar.v.djubn','ar.v.wa']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : il a mangé / le pain / et le fromage', array['أَكَلَ الْخُبْزَ وَالْجُبْنَ']::text[], 'Le verbe ouvre la phrase (أَكَلَ), puis le premier aliment (الْخُبْزَ), puis وَ collé au second : وَالْجُبْنَ. Après le verbe, les noms prennent une fatha finale.', 2, '{"id": "ar.l21.e17", "unitIds": ["ar.g21.lookalike_letters", "ar.v.khubz", "ar.v.djubn", "ar.v.wa"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre : « Il a mangé le pain et le fromage. »", "prompt": "Remets dans l''ordre : il a mangé / le pain / et le fromage", "promptLanguage": "fr", "tokens": ["وَالْجُبْنَ", "أَكَلَ", "الْخُبْزَ"], "answer": "أَكَلَ الْخُبْزَ وَالْجُبْنَ", "acceptedAnswers": ["أَكَلَ الْخُبْزَ وَالْجُبْنَ"], "explanation": "Le verbe ouvre la phrase (أَكَلَ), puis le premier aliment (الْخُبْزَ), puis وَ collé au second : وَالْجُبْنَ. Après le verbe, les noms prennent une fatha finale.", "tip": "Verbe, premier nom, وَ + deuxième nom.", "extraExample": {"text": "أَكَلَ الْبَيْضَ وَالْخُبْزَ", "translation": "Il a mangé les œufs et le pain.", "transliteration": "''akala l-bayDa wa-l-khubz"}, "pool": "lesson", "lessonId": "ar.l21", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e18', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.suq','ar.v.sayf','ar.v.ila']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : il est allé / au marché / en été', array['ذَهَبَ إِلَى السُّوقِ فِي الصَّيْفِ']::text[], 'Verbe (ذَهَبَ), direction (إِلَى السُّوقِ), puis le moment (فِي الصَّيْفِ). Dans السُّوق et الصَّيْف, le ل de l''article ne se prononce pas devant س et ص.', 3, '{"id": "ar.l21.e18", "unitIds": ["ar.g21.lookalike_letters", "ar.v.suq", "ar.v.sayf", "ar.v.ila"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Il est allé au marché en été. »", "prompt": "Remets dans l''ordre : il est allé / au marché / en été", "promptLanguage": "fr", "tokens": ["فِي", "السُّوقِ", "الصَّيْفِ", "إِلَى", "ذَهَبَ"], "answer": "ذَهَبَ إِلَى السُّوقِ فِي الصَّيْفِ", "acceptedAnswers": ["ذَهَبَ إِلَى السُّوقِ فِي الصَّيْفِ"], "explanation": "Verbe (ذَهَبَ), direction (إِلَى السُّوقِ), puis le moment (فِي الصَّيْفِ). Dans السُّوق et الصَّيْف, le ل de l''article ne se prononce pas devant س et ص.", "tip": "Verbe, lieu, moment.", "extraExample": {"text": "ذَهَبَ إِلَى الْبَحْرِ فِي الصَّيْفِ", "translation": "Il est allé à la mer en été.", "transliteration": "dhahaba ''ilâ l-ba7r fî S-Sayf"}, "pool": "lesson", "lessonId": "ar.l21", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e19', 'ar', 'ar.l21', 'ar.v.chariba', array['ar.v.chariba','ar.g21.lookalike_letters','ar.v.chay','ar.v.halib']::text[], 'translation', 'lesson', 'شَرِبَ الشَّايَ وَالْحَلِيبَ', array['Il a bu le thé et le lait.','Il a bu du thé et du lait.','Il but le thé et le lait.']::text[], 'شَرِبَ = il a bu ; الشَّايَ = le thé (ش : trois points) ; وَالْحَلِيبَ = et le lait (ح : aucun point).', 3, '{"id": "ar.l21.e19", "unitIds": ["ar.v.chariba", "ar.g21.lookalike_letters", "ar.v.chay", "ar.v.halib"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "شَرِبَ الشَّايَ وَالْحَلِيبَ", "promptLanguage": "ar", "answer": "Il a bu le thé et le lait.", "acceptedAnswers": ["Il a bu le thé et le lait.", "Il a bu du thé et du lait.", "Il but le thé et le lait."], "explanation": "شَرِبَ = il a bu ; الشَّايَ = le thé (ش : trois points) ; وَالْحَلِيبَ = et le lait (ح : aucun point).", "tip": "Thé = ش (trois points) ; lait = ح (aucun point).", "extraExample": {"text": "شَرِبَ الْقَهْوَةَ", "translation": "Il a bu le café.", "transliteration": "chariba l-qahwata"}, "errorPatterns": [{"contains": "eau", "category": "vocabulary", "feedback": "L''eau se dit مَاء. Ici : الشَّاي (le thé) et الْحَلِيب (le lait)."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e20', 'ar', 'ar.l21', 'ar.v.barid', array['ar.v.barid','ar.v.harr','ar.g21.lookalike_letters','ar.v.thaldj','ar.v.sayf']::text[], 'translation', 'lesson', 'الثَّلْجُ بَارِدٌ وَالصَّيْفُ حَارٌّ', array['La neige est froide et l''été est chaud.','La neige est froide et l''été chaud.','La neige est froide, et l''été est chaud.','La neige est froide mais l''été est chaud.']::text[], 'الثَّلْجُ = la neige ; بَارِدٌ = froide ; وَ = et ; الصَّيْفُ = l''été ; حَارٌّ = chaud. Surveille ث (trois points) dans الثَّلْج et ص (aucun point) dans الصَّيْف.', 4, '{"id": "ar.l21.e20", "unitIds": ["ar.v.barid", "ar.v.harr", "ar.g21.lookalike_letters", "ar.v.thaldj", "ar.v.sayf"], "type": "translation", "difficulty": 4, "instruction": "Traduis en français.", "prompt": "الثَّلْجُ بَارِدٌ وَالصَّيْفُ حَارٌّ", "promptLanguage": "ar", "answer": "La neige est froide et l''été est chaud.", "acceptedAnswers": ["La neige est froide et l''été est chaud.", "La neige est froide et l''été chaud.", "La neige est froide, et l''été est chaud.", "La neige est froide mais l''été est chaud."], "explanation": "الثَّلْجُ = la neige ; بَارِدٌ = froide ; وَ = et ; الصَّيْفُ = l''été ; حَارٌّ = chaud. Surveille ث (trois points) dans الثَّلْج et ص (aucun point) dans الصَّيْف.", "tip": "Neige = ث (trois points) ; été = ص (aucun point).", "extraExample": {"text": "الشِّتَاءُ بَارِدٌ", "translation": "L''hiver est froid.", "transliteration": "ach-chitâ''u bârid"}, "errorPatterns": [{"contains": "invité", "category": "word_confusion", "feedback": "ضَيْف (avec un point en plus) est l''invité. Ici ص : l''été."}, {"contains": "neige est chaude", "category": "word_confusion", "feedback": "بَارِد (froid) décrit la neige ; حَارّ (chaud) décrit l''été."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e21', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.chay']::text[], 'free_answer', 'lesson', 'Comment se lit شَاي ?', array['chây','chaay','chay','shaay','shay','shây']::text[], 'شَا = châ (fatha + ا), ي = y : chây, « le thé ». ش a trois points au-dessus : ch. س, sans point, se lirait s.', 3, '{"id": "ar.l21.e21", "unitIds": ["ar.g21.lookalike_letters", "ar.v.chay"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture de ce mot en lettres latines.", "prompt": "Comment se lit شَاي ?", "promptLanguage": "fr", "answer": "chây", "acceptedAnswers": ["chây", "chaay", "chay", "shaay", "shay", "shây"], "hint": "ش a trois points.", "explanation": "شَا = châ (fatha + ا), ي = y : chây, « le thé ». ش a trois points au-dessus : ch. س, sans point, se lirait s.", "tip": "ش = ch (trois points) ; س = s (aucun point).", "extraExample": {"text": "هٰذَا شَايٌ حَارٌّ", "translation": "C''est un thé chaud.", "transliteration": "hâdhâ châyun 7ârr"}, "errorPatterns": [{"equals": "say", "category": "spelling", "feedback": "س n''a aucun point ; ici il y a trois points : ش se lit ch."}, {"equals": "châ", "category": "spelling", "feedback": "N''oublie pas le ي final : il se prononce y, chây."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l21.e22', 'ar', 'ar.l21', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.thaldj']::text[], 'free_answer', 'lesson', 'Comment se lit ثَلْج ?', array['thaldj','thalj']::text[], 'ثَ = tha (ث : trois points, th), لْ = l (soukoun), ج = dj (point dedans) : thaldj, « la neige ».', 4, '{"id": "ar.l21.e22", "unitIds": ["ar.g21.lookalike_letters", "ar.v.thaldj"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture de ce mot en lettres latines.", "prompt": "Comment se lit ثَلْج ?", "promptLanguage": "fr", "answer": "thaldj", "acceptedAnswers": ["thaldj", "thalj"], "hint": "Trois points, c''est th.", "explanation": "ثَ = tha (ث : trois points, th), لْ = l (soukoun), ج = dj (point dedans) : thaldj, « la neige ».", "tip": "ث = trois points = th ; ت = deux points = t.", "extraExample": {"text": "لَا ثَلْجَ فِي الْمَدِينَةِ", "translation": "Il n''y a pas de neige en ville.", "transliteration": "lâ thaldja fî l-madîna"}, "errorPatterns": [{"equals": "taldj", "category": "spelling", "feedback": "ت n''a que deux points ; ici il y en a trois : ث se lit th."}, {"equals": "thalkh", "category": "spelling", "feedback": "Le point de ج est à l''intérieur, pas au-dessus : dj, pas kh."}], "pool": "lesson", "lessonId": "ar.l21", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e01', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.hadha']::text[], 'mcq', 'lesson', 'هٰذَا', array['hâdhâ']::text[], 'Le petit trait vertical sur ه est un alif : il allonge le a (hâ). Puis ذَا = dhâ (fatha + ا) : hâ-dhâ, « ceci ».', 1, '{"id": "ar.l22.e01", "unitIds": ["ar.g22.frequent_words", "ar.v.hadha"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "هٰذَا", "promptLanguage": "ar", "options": ["hâdhâ", "hadhâ", "hâdhî", "hudhâ"], "answer": "hâdhâ", "acceptedAnswers": ["hâdhâ"], "explanation": "Le petit trait vertical sur ه est un alif : il allonge le a (hâ). Puis ذَا = dhâ (fatha + ا) : hâ-dhâ, « ceci ».", "tip": "Petit alif vertical = a long, même si le grand ا n''est pas écrit.", "extraExample": {"text": "هٰذَا كِتَابٌ", "translation": "C''est un livre.", "transliteration": "hâdhâ kitâb"}, "errorPatterns": [{"equals": "hadhâ", "category": "spelling", "feedback": "Le petit alif sur le ه allonge aussi le premier a : hâ-dhâ."}, {"equals": "hâdhî", "category": "spelling", "feedback": "Le ا final suit une fatha : â, pas î."}, {"equals": "hudhâ", "category": "spelling", "feedback": "Sur le ه il n''y a pas de damma : le premier a est long, hâ."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e02', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.hiya']::text[], 'mcq', 'lesson', 'هِيَ', array['elle']::text[], 'هِيَ (hiya) = elle. Il s''oppose à هُوَ (huwa) = il : la kasra sous ه et le ي final disent « elle », la damma et le و disent « il ».', 1, '{"id": "ar.l22.e02", "unitIds": ["ar.g22.frequent_words", "ar.v.hiya"], "type": "mcq", "difficulty": 1, "instruction": "Que veut dire ce mot ?", "prompt": "هِيَ", "promptLanguage": "ar", "options": ["elle", "il", "je", "ici"], "answer": "elle", "acceptedAnswers": ["elle"], "explanation": "هِيَ (hiya) = elle. Il s''oppose à هُوَ (huwa) = il : la kasra sous ه et le ي final disent « elle », la damma et le و disent « il ».", "tip": "Kasra + ي = elle ; damma + و = il.", "extraExample": {"text": "هِيَ فِي الْمَدْرَسَةِ", "translation": "Elle est à l''école.", "transliteration": "hiya fî l-madrasa"}, "errorPatterns": [{"equals": "il", "category": "word_confusion", "feedback": "« Il » se dit هُوَ, avec une damma sur ه et un و."}, {"equals": "ici", "category": "word_confusion", "feedback": "« Ici » se dit هُنَا."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e03', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.ana','ar.v.anta','ar.v.huwa','ar.v.hiya','ar.v.huna']::text[], 'match', 'lesson', 'Cinq petits mots à connaître par cœur', '{}'::text[], 'أَنَا (je) et أَنْتَ (tu) commencent par أ ; هُوَ (il), هِيَ (elle) et هُنَا (ici) commencent par ه. Regarde la voyelle sur le ه et la fin du mot pour les distinguer.', 1, '{"id": "ar.l22.e03", "unitIds": ["ar.g22.frequent_words", "ar.v.ana", "ar.v.anta", "ar.v.huwa", "ar.v.hiya", "ar.v.huna"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à son sens.", "prompt": "Cinq petits mots à connaître par cœur", "promptLanguage": "fr", "pairs": [{"left": "أَنَا", "right": "je, moi"}, {"left": "أَنْتَ", "right": "tu, toi (masculin)"}, {"left": "هُوَ", "right": "il, lui"}, {"left": "هِيَ", "right": "elle"}, {"left": "هُنَا", "right": "ici"}], "answer": "أَنَا = je, moi ; أَنْتَ = tu, toi (masculin) ; هُوَ = il, lui ; هِيَ = elle ; هُنَا = ici", "acceptedAnswers": [], "explanation": "أَنَا (je) et أَنْتَ (tu) commencent par أ ; هُوَ (il), هِيَ (elle) et هُنَا (ici) commencent par ه. Regarde la voyelle sur le ه et la fin du mot pour les distinguer.", "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e04', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.la']::text[], 'mcq', 'lesson', 'لَا', array['non']::text[], 'لَا (lâ) = non, et aussi « ne… pas ». Le ل et le ا s''écrivent collés en un seul signe. « Oui » se dit نَعَمْ (na-3am).', 1, '{"id": "ar.l22.e04", "unitIds": ["ar.g22.frequent_words", "ar.v.la"], "type": "mcq", "difficulty": 1, "instruction": "Que veut dire ce mot ?", "prompt": "لَا", "promptLanguage": "ar", "options": ["non", "oui", "ici", "avec"], "answer": "non", "acceptedAnswers": ["non"], "explanation": "لَا (lâ) = non, et aussi « ne… pas ». Le ل et le ا s''écrivent collés en un seul signe. « Oui » se dit نَعَمْ (na-3am).", "tip": "لَا = non ; نَعَمْ = oui.", "extraExample": {"text": "لَا، أَنَا فِي الْبَيْتِ", "translation": "Non, je suis à la maison.", "transliteration": "lâ, ''anâ fî l-bayt"}, "errorPatterns": [{"equals": "oui", "category": "word_confusion", "feedback": "« Oui » se dit نَعَمْ."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e05', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.huna','ar.v.huwa','ar.v.hiya']::text[], 'mcq', 'lesson', 'Quel mot se lit hunâ (ici) ?', array['هُنَا']::text[], 'هُنَا = hu-nâ : ه avec damma, ن, puis ا qui allonge. Après le ه, regarde la lettre suivante : ن → hunâ, و → huwa, ي → hiya.', 2, '{"id": "ar.l22.e05", "unitIds": ["ar.g22.frequent_words", "ar.v.huna", "ar.v.huwa", "ar.v.hiya"], "type": "mcq", "difficulty": 2, "instruction": "Retrouve le mot qui correspond à la lecture.", "prompt": "Quel mot se lit hunâ (ici) ?", "promptLanguage": "fr", "options": ["هُنَا", "هُوَ", "هِيَ", "هٰذَا"], "answer": "هُنَا", "acceptedAnswers": ["هُنَا"], "explanation": "هُنَا = hu-nâ : ه avec damma, ن, puis ا qui allonge. Après le ه, regarde la lettre suivante : ن → hunâ, و → huwa, ي → hiya.", "tip": "Les trois mots en ه se lisent par leur 2e lettre : ن, و ou ي.", "extraExample": {"text": "الْمَطْعَمُ هُنَا", "translation": "Le restaurant est ici.", "transliteration": "al-maT3amu hunâ"}, "errorPatterns": [{"equals": "هُوَ", "category": "spelling", "feedback": "هُوَ se lit huwa : sa deuxième lettre est و, pas ن."}, {"equals": "هِيَ", "category": "spelling", "feedback": "هِيَ se lit hiya : kasra sous ه et ي à la fin."}, {"equals": "هٰذَا", "category": "spelling", "feedback": "هٰذَا se lit hâdhâ : il a un ذ et un petit alif sur le ه."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e06', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.hadha']::text[], 'mcq', 'lesson', 'Dans هٰذَا, que représente le petit trait vertical au-dessus du ه ?', array['un petit alif : le ه se lit hâ']::text[], 'C''est un alif en miniature : il allonge la voyelle, donc le ه se lit hâ. Dans quelques mots très fréquents comme هٰذَا, on ne l''écrit pas en grand.', 2, '{"id": "ar.l22.e06", "unitIds": ["ar.g22.frequent_words", "ar.v.hadha"], "type": "mcq", "difficulty": 2, "instruction": "Lis le signe.", "prompt": "Dans هٰذَا, que représente le petit trait vertical au-dessus du ه ?", "promptLanguage": "fr", "options": ["un petit alif : le ه se lit hâ", "une fatha : le ه se lit ha", "un soukoun", "une chadda"], "answer": "un petit alif : le ه se lit hâ", "acceptedAnswers": ["un petit alif : le ه se lit hâ"], "explanation": "C''est un alif en miniature : il allonge la voyelle, donc le ه se lit hâ. Dans quelques mots très fréquents comme هٰذَا, on ne l''écrit pas en grand.", "tip": "Trait vertical = alif ; trait penché = fatha.", "extraExample": {"text": "ذٰلِكَ", "translation": "cela (là-bas)", "transliteration": "dhâlika"}, "errorPatterns": [{"equals": "une fatha : le ه se lit ha", "category": "spelling", "feedback": "La fatha est un petit trait penché ; ici le trait est vertical : c''est un alif miniature."}, {"equals": "un soukoun", "category": "spelling", "feedback": "Le soukoun est un petit rond (ـْ), pas un trait vertical."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e07', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.hadha','ar.v.hadhihi','ar.v.maa_avec','ar.v.naam','ar.v.anta']::text[], 'match', 'lesson', 'Lis les petits mots d''un coup', '{}'::text[], 'هٰذَا / هٰذِهِ portent un petit alif sur le ه ; مَعَ et نَعَمْ contiennent ع (3) ; نَعَمْ finit par un soukoun sur م ; أَنْتَ a un soukoun sur ن.', 2, '{"id": "ar.l22.e07", "unitIds": ["ar.g22.frequent_words", "ar.v.hadha", "ar.v.hadhihi", "ar.v.maa_avec", "ar.v.naam", "ar.v.anta"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lis les petits mots d''un coup", "promptLanguage": "fr", "pairs": [{"left": "هٰذَا", "right": "hâdhâ"}, {"left": "هٰذِهِ", "right": "hâdhihi"}, {"left": "مَعَ", "right": "ma3a"}, {"left": "نَعَمْ", "right": "na3am"}, {"left": "أَنْتَ", "right": "''anta"}], "answer": "هٰذَا = hâdhâ ; هٰذِهِ = hâdhihi ; مَعَ = ma3a ; نَعَمْ = na3am ; أَنْتَ = ''anta", "acceptedAnswers": [], "explanation": "هٰذَا / هٰذِهِ portent un petit alif sur le ه ; مَعَ et نَعَمْ contiennent ع (3) ; نَعَمْ finit par un soukoun sur م ; أَنْتَ a un soukoun sur ن.", "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e08', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.hiya','ar.v.huwa','ar.v.ana','ar.v.anta']::text[], 'mcq', 'lesson', 'Quelle phrase veut dire « Elle est ici » ?', array['هِيَ هُنَا']::text[], 'Il n''y a pas de verbe « être » : هِيَ هُنَا = « elle (est) ici ». Seul le premier mot change : هِيَ elle, هُوَ il, أَنَا je, أَنْتَ tu.', 2, '{"id": "ar.l22.e08", "unitIds": ["ar.g22.frequent_words", "ar.v.hiya", "ar.v.huwa", "ar.v.ana", "ar.v.anta"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne phrase.", "prompt": "Quelle phrase veut dire « Elle est ici » ?", "promptLanguage": "fr", "options": ["هِيَ هُنَا", "هُوَ هُنَا", "أَنَا هُنَا", "أَنْتَ هُنَا"], "answer": "هِيَ هُنَا", "acceptedAnswers": ["هِيَ هُنَا"], "explanation": "Il n''y a pas de verbe « être » : هِيَ هُنَا = « elle (est) ici ». Seul le premier mot change : هِيَ elle, هُوَ il, أَنَا je, أَنْتَ tu.", "tip": "Repère d''abord le sujet : le verbe « être » n''est pas écrit.", "extraExample": {"text": "هُوَ هُنَا", "translation": "Il est ici.", "transliteration": "huwa hunâ"}, "errorPatterns": [{"equals": "هُوَ هُنَا", "category": "word_confusion", "feedback": "هُوَ = il. Pour « elle », il faut هِيَ."}, {"equals": "أَنَا هُنَا", "category": "word_confusion", "feedback": "أَنَا = je."}, {"equals": "أَنْتَ هُنَا", "category": "word_confusion", "feedback": "أَنْتَ = tu."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e09', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.anta']::text[], 'mcq', 'lesson', 'أَنْتَ', array['''anta']::text[], 'أَ = ''a, نْ = n (soukoun), تَ = ta : ''an-ta, « tu » (à un homme). Avec une kasra sous ت, on lirait ''anti, « tu » à une femme.', 2, '{"id": "ar.l22.e09", "unitIds": ["ar.g22.frequent_words", "ar.v.anta"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "أَنْتَ", "promptLanguage": "ar", "options": ["''anta", "''anâ", "''anti", "''antu"], "answer": "''anta", "acceptedAnswers": ["''anta"], "explanation": "أَ = ''a, نْ = n (soukoun), تَ = ta : ''an-ta, « tu » (à un homme). Avec une kasra sous ت, on lirait ''anti, « tu » à une femme.", "tip": "Fatha sur ت = on parle à un homme ; kasra = à une femme.", "extraExample": {"text": "أَنْتَ فِي الْبَيْتِ", "translation": "Tu es à la maison.", "transliteration": "''anta fî l-bayt"}, "errorPatterns": [{"equals": "''anâ", "category": "spelling", "feedback": "أَنَا (je) finit par ا ; ici le mot finit par ت."}, {"equals": "''anti", "category": "spelling", "feedback": "La voyelle sur ت est une fatha (a) : ''anta."}, {"equals": "''antu", "category": "spelling", "feedback": "Sur ت il y a une fatha, pas une damma."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e10', 'ar', 'ar.l22', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.hadha','ar.g22.frequent_words']::text[], 'mcq', 'lesson', 'En combien de blocs s''écrit هٰذَا ?', array['2']::text[], 'Révision des coupures : ه s''attache à ذ, mais ذ ne s''attache pas à la lettre suivante : هذ | ا. Deux blocs, un seul mot.', 2, '{"id": "ar.l22.e10", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.hadha", "ar.g22.frequent_words"], "type": "mcq", "difficulty": 2, "instruction": "Compte les blocs.", "prompt": "En combien de blocs s''écrit هٰذَا ?", "promptLanguage": "fr", "options": ["1", "2", "3"], "answer": "2", "acceptedAnswers": ["2"], "explanation": "Révision des coupures : ه s''attache à ذ, mais ذ ne s''attache pas à la lettre suivante : هذ | ا. Deux blocs, un seul mot.", "tip": "ذ coupe : cherche toujours ا د ذ ر ز و.", "extraExample": {"text": "هٰذِهِ", "translation": "ceci (féminin) : هذ | ه", "transliteration": "hâdhihi"}, "errorPatterns": [{"equals": "1", "category": "spelling", "feedback": "ذ ne s''attache pas à gauche : le ا qui suit est détaché."}, {"equals": "3", "category": "spelling", "feedback": "ه et ذ sont attachés ; il n''y a qu''une coupure, après ذ."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e11', 'ar', 'ar.l22', 'ar.v.fi', array['ar.v.fi','ar.v.min','ar.v.ala','ar.v.ila','ar.v.maa_avec','ar.g22.frequent_words']::text[], 'match', 'lesson', 'Les cinq petits mots de lieu et d''accompagnement', '{}'::text[], 'فِي et مِنْ sont courts ; عَلَى et إِلَى finissent par ى (qui se lit â) mais commencent par ع et إ ; مَعَ commence par م et finit par ع.', 2, '{"id": "ar.l22.e11", "unitIds": ["ar.v.fi", "ar.v.min", "ar.v.ala", "ar.v.ila", "ar.v.maa_avec", "ar.g22.frequent_words"], "type": "match", "difficulty": 2, "instruction": "Associe chaque petit mot à son sens.", "prompt": "Les cinq petits mots de lieu et d''accompagnement", "promptLanguage": "fr", "pairs": [{"left": "فِي", "right": "dans, à, en"}, {"left": "مِنْ", "right": "de, depuis"}, {"left": "عَلَى", "right": "sur"}, {"left": "إِلَى", "right": "vers, à"}, {"left": "مَعَ", "right": "avec"}], "answer": "فِي = dans, à, en ; مِنْ = de, depuis ; عَلَى = sur ; إِلَى = vers, à ; مَعَ = avec", "acceptedAnswers": [], "explanation": "فِي et مِنْ sont courts ; عَلَى et إِلَى finissent par ى (qui se lit â) mais commencent par ع et إ ; مَعَ commence par م et finit par ع.", "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e12', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.hadhihi','ar.v.madrasa']::text[], 'fill_blank', 'lesson', '___ مَدْرَسَةٌ', array['هٰذِهِ']::text[], 'مَدْرَسَة est féminin (finale ـة) : on emploie هٰذِهِ. هٰذَا s''utilise devant un nom masculin.', 2, '{"id": "ar.l22.e12", "unitIds": ["ar.g22.frequent_words", "ar.v.hadhihi", "ar.v.madrasa"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « C''est une école. »", "prompt": "___ مَدْرَسَةٌ", "promptLanguage": "ar", "options": ["هٰذِهِ", "هٰذَا", "هُوَ"], "answer": "هٰذِهِ", "acceptedAnswers": ["هٰذِهِ"], "explanation": "مَدْرَسَة est féminin (finale ـة) : on emploie هٰذِهِ. هٰذَا s''utilise devant un nom masculin.", "tip": "Nom en ـة → هٰذِهِ.", "extraExample": {"text": "هٰذِهِ سَيَّارَةٌ", "translation": "C''est une voiture.", "transliteration": "hâdhihi sayyâra"}, "errorPatterns": [{"equals": "هٰذَا", "category": "grammar", "feedback": "هٰذَا est masculin ; مَدْرَسَة est féminin (ـة)."}, {"equals": "هُوَ", "category": "word_confusion", "feedback": "هُوَ veut dire « il » ; pour montrer une chose, on emploie هٰذَا / هٰذِهِ."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e13', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.hadha','ar.v.kitab']::text[], 'fill_blank', 'lesson', '___ كِتَابٌ', array['هٰذَا']::text[], 'كِتَاب est masculin (pas de ـة) : on emploie هٰذَا.', 2, '{"id": "ar.l22.e13", "unitIds": ["ar.g22.frequent_words", "ar.v.hadha", "ar.v.kitab"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « C''est un livre. »", "prompt": "___ كِتَابٌ", "promptLanguage": "ar", "options": ["هٰذَا", "هٰذِهِ", "هِيَ"], "answer": "هٰذَا", "acceptedAnswers": ["هٰذَا"], "explanation": "كِتَاب est masculin (pas de ـة) : on emploie هٰذَا.", "tip": "Nom sans ـة → هٰذَا (le plus souvent).", "extraExample": {"text": "هٰذَا مَطْعَمٌ", "translation": "C''est un restaurant.", "transliteration": "hâdhâ maT3am"}, "errorPatterns": [{"equals": "هٰذِهِ", "category": "grammar", "feedback": "هٰذِهِ est féminin ; كِتَاب est masculin."}, {"equals": "هِيَ", "category": "word_confusion", "feedback": "هِيَ veut dire « elle »."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e14', 'ar', 'ar.l22', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.hadhihi','ar.g22.frequent_words']::text[], 'mcq', 'lesson', 'Combien de syllabes dans هٰذِهِ ?', array['3']::text[], 'Révision : hâ + dhi + hi. Chaque syllabe est ouverte et finit par une voyelle : le petit alif, la kasra sous ذ, la kasra sous ه final.', 3, '{"id": "ar.l22.e14", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.hadhihi", "ar.g22.frequent_words"], "type": "mcq", "difficulty": 3, "instruction": "Compte avec les voyelles.", "prompt": "Combien de syllabes dans هٰذِهِ ?", "promptLanguage": "fr", "options": ["2", "3", "4"], "answer": "3", "acceptedAnswers": ["3"], "explanation": "Révision : hâ + dhi + hi. Chaque syllabe est ouverte et finit par une voyelle : le petit alif, la kasra sous ذ, la kasra sous ه final.", "tip": "Une voyelle = une syllabe.", "extraExample": {"text": "هٰذَا", "translation": "ceci (masculin) : 2 syllabes, hâ-dhâ", "transliteration": "hâdhâ"}, "errorPatterns": [{"equals": "2", "category": "spelling", "feedback": "Compte les voyelles : â, i, i. Il y en a trois, donc trois syllabes."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e15', 'ar', 'ar.l22', 'ar.v.kataba', array['ar.v.kataba','ar.g22.frequent_words','ar.v.huwa','ar.v.kitab']::text[], 'fill_blank', 'lesson', '___ كَتَبَ الْكِتَابَ', array['هُوَ']::text[], 'Révision : كَتَبَ (il a écrit) est à la forme « il » : le pronom est هُوَ. هِيَ voudrait dire « elle ».', 3, '{"id": "ar.l22.e15", "unitIds": ["ar.v.kataba", "ar.g22.frequent_words", "ar.v.huwa", "ar.v.kitab"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Lui, il a écrit le livre. »", "prompt": "___ كَتَبَ الْكِتَابَ", "promptLanguage": "ar", "options": ["هُوَ", "هِيَ", "أَنَا"], "answer": "هُوَ", "acceptedAnswers": ["هُوَ"], "explanation": "Révision : كَتَبَ (il a écrit) est à la forme « il » : le pronom est هُوَ. هِيَ voudrait dire « elle ».", "tip": "Verbe de base en CaCaCa = « il » ; le pronom est هُوَ.", "extraExample": {"text": "هُوَ فِي الْمَدْرَسَةِ", "translation": "Il est à l''école.", "transliteration": "huwa fî l-madrasa"}, "errorPatterns": [{"equals": "هِيَ", "category": "word_confusion", "feedback": "هِيَ = elle. Le verbe كَتَبَ est à la forme « il »."}, {"equals": "أَنَا", "category": "word_confusion", "feedback": "أَنَا = je. Avec « je », le verbe aurait une autre terminaison."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e16', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.naam','ar.v.ana']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : oui / je suis / à l''école', array['نَعَمْ أَنَا فِي الْمَدْرَسَةِ']::text[], 'Le mot de réponse نَعَمْ vient en premier, puis le sujet أَنَا, puis le lieu فِي الْمَدْرَسَةِ. Pas de verbe « être » à écrire.', 2, '{"id": "ar.l22.e16", "unitIds": ["ar.g22.frequent_words", "ar.v.naam", "ar.v.ana"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre : « Oui, je suis à l''école. »", "prompt": "Remets dans l''ordre : oui / je suis / à l''école", "promptLanguage": "fr", "tokens": ["الْمَدْرَسَةِ", "نَعَمْ", "فِي", "أَنَا"], "answer": "نَعَمْ أَنَا فِي الْمَدْرَسَةِ", "acceptedAnswers": ["نَعَمْ أَنَا فِي الْمَدْرَسَةِ"], "explanation": "Le mot de réponse نَعَمْ vient en premier, puis le sujet أَنَا, puis le lieu فِي الْمَدْرَسَةِ. Pas de verbe « être » à écrire.", "tip": "Oui, sujet, lieu.", "extraExample": {"text": "نَعَمْ هُوَ فِي الْمَطْعَمِ", "translation": "Oui, il est au restaurant.", "transliteration": "na3am huwa fî l-maT3am"}, "pool": "lesson", "lessonId": "ar.l22", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e17', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.maa_avec','ar.v.ana','ar.v.radjul']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : je / avec l''homme / au restaurant', array['أَنَا مَعَ الرَّجُلِ فِي الْمَطْعَمِ','أَنَا فِي الْمَطْعَمِ مَعَ الرَّجُلِ']::text[], 'Sujet (أَنَا), puis مَعَ + le nom (الرَّجُلِ, finale en kasra), puis فِي + le lieu. Les deux compléments peuvent aussi s''échanger.', 3, '{"id": "ar.l22.e17", "unitIds": ["ar.g22.frequent_words", "ar.v.maa_avec", "ar.v.ana", "ar.v.radjul"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Je suis avec l''homme au restaurant. »", "prompt": "Remets dans l''ordre : je / avec l''homme / au restaurant", "promptLanguage": "fr", "tokens": ["فِي", "الْمَطْعَمِ", "أَنَا", "مَعَ", "الرَّجُلِ"], "answer": "أَنَا مَعَ الرَّجُلِ فِي الْمَطْعَمِ", "acceptedAnswers": ["أَنَا مَعَ الرَّجُلِ فِي الْمَطْعَمِ", "أَنَا فِي الْمَطْعَمِ مَعَ الرَّجُلِ"], "explanation": "Sujet (أَنَا), puis مَعَ + le nom (الرَّجُلِ, finale en kasra), puis فِي + le lieu. Les deux compléments peuvent aussi s''échanger.", "tip": "Sujet, puis les compléments introduits par مَعَ et فِي.", "extraExample": {"text": "أَنَا مَعَ سَامِي", "translation": "Je suis avec Sami.", "transliteration": "''anâ ma3a sâmî"}, "pool": "lesson", "lessonId": "ar.l22", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e18', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.naam','ar.v.ana','ar.v.huna']::text[], 'translation', 'lesson', 'نَعَمْ، أَنَا هُنَا', array['Oui, je suis ici.','Oui, moi, je suis ici.','Oui, je suis là.']::text[], 'نَعَمْ = oui ; أَنَا = je ; هُنَا = ici. Au présent, le verbe « être » n''est pas écrit.', 3, '{"id": "ar.l22.e18", "unitIds": ["ar.g22.frequent_words", "ar.v.naam", "ar.v.ana", "ar.v.huna"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "نَعَمْ، أَنَا هُنَا", "promptLanguage": "ar", "answer": "Oui, je suis ici.", "acceptedAnswers": ["Oui, je suis ici.", "Oui, moi, je suis ici.", "Oui, je suis là."], "explanation": "نَعَمْ = oui ; أَنَا = je ; هُنَا = ici. Au présent, le verbe « être » n''est pas écrit.", "tip": "Trois petits mots, une phrase : oui, je, ici.", "extraExample": {"text": "لَا، هُوَ هُنَا", "translation": "Non, il est ici.", "transliteration": "lâ, huwa hunâ"}, "errorPatterns": [{"contains": "non", "category": "word_confusion", "feedback": "نَعَمْ veut dire « oui » ; « non » se dit لَا."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e19', 'ar', 'ar.l22', 'ar.v.madrasa', array['ar.v.madrasa','ar.g22.frequent_words','ar.v.la','ar.v.hiya','ar.v.fi']::text[], 'translation', 'lesson', 'لَا، هِيَ فِي الْمَدْرَسَةِ', array['Non, elle est à l''école.','Non, elle est dans l''école.']::text[], 'لَا = non ; هِيَ = elle ; فِي الْمَدْرَسَةِ = à l''école (mot à mot : dans l''école).', 3, '{"id": "ar.l22.e19", "unitIds": ["ar.v.madrasa", "ar.g22.frequent_words", "ar.v.la", "ar.v.hiya", "ar.v.fi"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "لَا، هِيَ فِي الْمَدْرَسَةِ", "promptLanguage": "ar", "answer": "Non, elle est à l''école.", "acceptedAnswers": ["Non, elle est à l''école.", "Non, elle est dans l''école."], "explanation": "لَا = non ; هِيَ = elle ; فِي الْمَدْرَسَةِ = à l''école (mot à mot : dans l''école).", "tip": "لَا (non) ouvre la phrase ; le reste se lit mot à mot.", "extraExample": {"text": "لَا، هُوَ فِي الْمَطْعَمِ", "translation": "Non, il est au restaurant.", "transliteration": "lâ, huwa fî l-maT3am"}, "errorPatterns": [{"contains": "il est", "category": "word_confusion", "feedback": "هِيَ = elle (kasra sous ه, ي final). « Il » se dit هُوَ."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e20', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.naam']::text[], 'free_answer', 'lesson', 'Comment se lit نَعَمْ ?', array['na3am','naam','na''am']::text[], 'نَ = na, عَ = 3a, مْ = m (soukoun) : na-3am, « oui ». Deux syllabes : une ouverte, une fermée.', 3, '{"id": "ar.l22.e20", "unitIds": ["ar.g22.frequent_words", "ar.v.naam"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture de ce mot en lettres latines.", "prompt": "Comment se lit نَعَمْ ?", "promptLanguage": "fr", "answer": "na3am", "acceptedAnswers": ["na3am", "naam", "na''am"], "hint": "ع se transcrit 3.", "explanation": "نَ = na, عَ = 3a, مْ = m (soukoun) : na-3am, « oui ». Deux syllabes : une ouverte, une fermée.", "tip": "ع se note 3 : na3am.", "extraExample": {"text": "نَعَمْ، هُوَ هُنَا", "translation": "Oui, il est ici.", "transliteration": "na3am, huwa hunâ"}, "errorPatterns": [{"equals": "nam", "category": "spelling", "feedback": "Il manque le ع, qui se note 3 : na-3am, deux syllabes."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l22.e21', 'ar', 'ar.l22', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.hadha']::text[], 'free_answer', 'lesson', 'Comment se lit هٰذَا ?', array['hâdhâ','haadhaa','hadha']::text[], 'Le petit alif sur ه donne hâ, puis ذَا = dhâ : hâ-dhâ, « ceci ». On le note aussi hadha en transcription simplifiée.', 4, '{"id": "ar.l22.e21", "unitIds": ["ar.g22.frequent_words", "ar.v.hadha"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture de ce mot en lettres latines.", "prompt": "Comment se lit هٰذَا ?", "promptLanguage": "fr", "answer": "hâdhâ", "acceptedAnswers": ["hâdhâ", "haadhaa", "hadha"], "hint": "ذ se transcrit dh.", "explanation": "Le petit alif sur ه donne hâ, puis ذَا = dhâ : hâ-dhâ, « ceci ». On le note aussi hadha en transcription simplifiée.", "tip": "Petit alif sur ه = hâ ; ذ = dh.", "extraExample": {"text": "هٰذَا مَطْعَمٌ جَدِيدٌ", "translation": "C''est un nouveau restaurant.", "transliteration": "hâdhâ maT3amun djadîd"}, "errorPatterns": [{"equals": "hadhi", "category": "spelling", "feedback": "Le dernier signe est un ا précédé d''une fatha : dhâ, pas dhi."}, {"equals": "hazza", "category": "spelling", "feedback": "ذ a un point et se lit dh ; ce n''est pas ز."}], "pool": "lesson", "lessonId": "ar.l22", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e01', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.bahr']::text[], 'mcq', 'lesson', 'بَحْر', array['ba7r']::text[], 'بَ = ba, حْ = 7 (le soukoun supprime la voyelle), ر = r : ba7r, « la mer ». Une seule syllabe, sans voyelle entre ح et ر.', 1, '{"id": "ar.l23.e01", "unitIds": ["ar.g23.short_sentences", "ar.v.bahr"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "بَحْر", "promptLanguage": "ar", "options": ["ba7r", "bakhr", "ba7ar", "bi7r"], "answer": "ba7r", "acceptedAnswers": ["ba7r"], "explanation": "بَ = ba, حْ = 7 (le soukoun supprime la voyelle), ر = r : ba7r, « la mer ». Une seule syllabe, sans voyelle entre ح et ر.", "tip": "Le soukoun sur ح supprime la voyelle : ba7r, pas ba-7ar.", "extraExample": {"text": "الْبَحْرُ بَارِدٌ", "translation": "La mer est froide.", "transliteration": "al-ba7ru bârid"}, "errorPatterns": [{"equals": "bakhr", "category": "spelling", "feedback": "ح n''a aucun point ; il n''y a pas de point au-dessus : 7, pas kh."}, {"equals": "ba7ar", "category": "spelling", "feedback": "Le soukoun sur ح supprime la voyelle : ba7r."}, {"equals": "bi7r", "category": "spelling", "feedback": "Sur ب il y a une fatha (a), pas une kasra."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e02', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.kana','ar.v.alladhi','ar.v.al_yawm','ar.v.qahwa','ar.v.bahr']::text[], 'match', 'lesson', 'Cinq mots qu''on retrouve dans les phrases', '{}'::text[], 'كَانَ (il était) met la phrase au passé et الَّذِي (qui, que) relie un nom à ce qui le décrit. الْيَوْم (aujourd''hui), قَهْوَة (café) et بَحْر (mer) complètent les phrases.', 1, '{"id": "ar.l23.e02", "unitIds": ["ar.g23.short_sentences", "ar.v.kana", "ar.v.alladhi", "ar.v.al_yawm", "ar.v.qahwa", "ar.v.bahr"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à son sens.", "prompt": "Cinq mots qu''on retrouve dans les phrases", "promptLanguage": "fr", "pairs": [{"left": "كَانَ", "right": "il était"}, {"left": "الَّذِي", "right": "qui, que"}, {"left": "الْيَوْم", "right": "aujourd''hui"}, {"left": "قَهْوَة", "right": "le café"}, {"left": "بَحْر", "right": "la mer"}], "answer": "كَانَ = il était ; الَّذِي = qui, que ; الْيَوْم = aujourd''hui ; قَهْوَة = le café ; بَحْر = la mer", "acceptedAnswers": [], "explanation": "كَانَ (il était) met la phrase au passé et الَّذِي (qui, que) relie un nom à ce qui le décrit. الْيَوْم (aujourd''hui), قَهْوَة (café) et بَحْر (mer) complètent les phrases.", "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e03', 'ar', 'ar.l23', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.bayt','ar.v.bayd']::text[], 'mcq', 'lesson', 'Quel mot veut dire « la maison » (et non « les œufs ») ?', array['بَيْت']::text[], 'Révision des lettres jumelles : بَيْت finit par ت (deux points au-dessus). بَيْض finit par ض (un seul point), et بِنْت (la fille) a une kasra sous ب et un ن avant le ت.', 2, '{"id": "ar.l23.e03", "unitIds": ["ar.g21.lookalike_letters", "ar.v.bayt", "ar.v.bayd"], "type": "mcq", "difficulty": 2, "instruction": "Regarde la dernière lettre.", "prompt": "Quel mot veut dire « la maison » (et non « les œufs ») ?", "promptLanguage": "fr", "options": ["بَيْت", "بَيْض", "بِنْت"], "answer": "بَيْت", "acceptedAnswers": ["بَيْت"], "explanation": "Révision des lettres jumelles : بَيْت finit par ت (deux points au-dessus). بَيْض finit par ض (un seul point), et بِنْت (la fille) a une kasra sous ب et un ن avant le ت.", "tip": "ت = deux points ; ض = un point : compte-les.", "extraExample": {"text": "بَيْتٌ كَبِيرٌ", "translation": "une grande maison", "transliteration": "baytun kabîr"}, "errorPatterns": [{"equals": "بَيْض", "category": "word_confusion", "feedback": "بَيْض (bayD) finit par ض, avec un seul point : ce sont les œufs."}, {"equals": "بِنْت", "category": "word_confusion", "feedback": "بِنْت (bint) est la fille : kasra sous ب, puis ن avant le ت."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e04', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.bayt','ar.v.djamil']::text[], 'mcq', 'lesson', 'هٰذَا بَيْتٌ جَمِيلٌ', array['hâdhâ baytun djamîl']::text[], 'هٰذَا = hâdhâ (masculin), بَيْتٌ = baytun, جَمِيلٌ = djamîl (en fin de phrase, on ne prononce pas le -un). « C''est une belle maison » : pas de verbe, et l''adjectif suit le nom.', 2, '{"id": "ar.l23.e04", "unitIds": ["ar.g23.short_sentences", "ar.v.bayt", "ar.v.djamil"], "type": "mcq", "difficulty": 2, "instruction": "Lis la phrase d''un trait.", "prompt": "هٰذَا بَيْتٌ جَمِيلٌ", "promptLanguage": "ar", "options": ["hâdhâ baytun djamîl", "hâdhihi baytun djamîl", "hâdhâ baytan djamîl", "hâdhâ bint djamîl"], "answer": "hâdhâ baytun djamîl", "acceptedAnswers": ["hâdhâ baytun djamîl"], "explanation": "هٰذَا = hâdhâ (masculin), بَيْتٌ = baytun, جَمِيلٌ = djamîl (en fin de phrase, on ne prononce pas le -un). « C''est une belle maison » : pas de verbe, et l''adjectif suit le nom.", "tip": "Petit mot d''abord (هٰذَا), nom ensuite, terminaison en dernier.", "extraExample": {"text": "هٰذِهِ مَدِينَةٌ جَمِيلَةٌ", "translation": "C''est une belle ville.", "transliteration": "hâdhihi madînatun djamîla"}, "errorPatterns": [{"equals": "hâdhihi baytun djamîl", "category": "grammar", "feedback": "هٰذِهِ est le féminin, avec une kasra et un ه final. Ici le mot est هٰذَا, avec un ا final."}, {"equals": "hâdhâ baytan djamîl", "category": "spelling", "feedback": "Le signe sur ت est une damma doublée (ـٌ) : -un, pas -an."}, {"equals": "hâdhâ bint djamîl", "category": "spelling", "feedback": "Le mot est بَيْت (ي puis ت) : bayt, pas bint."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e05', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.bayt','ar.v.djamil','ar.v.djadid','ar.v.qahwa','ar.v.bahr']::text[], 'match', 'lesson', 'Lis cinq mots de la leçon d''un trait', '{}'::text[], 'جَمِيل (dja-mîl) et جَدِيد (dja-dîd) commencent pareil et finissent presque pareil : regarde la 2e lettre (م ou د) et la dernière (ل ou د).', 2, '{"id": "ar.l23.e05", "unitIds": ["ar.g23.short_sentences", "ar.v.bayt", "ar.v.djamil", "ar.v.djadid", "ar.v.qahwa", "ar.v.bahr"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lis cinq mots de la leçon d''un trait", "promptLanguage": "fr", "pairs": [{"left": "بَيْت", "right": "bayt"}, {"left": "جَمِيل", "right": "djamîl"}, {"left": "جَدِيد", "right": "djadîd"}, {"left": "قَهْوَة", "right": "qahwa"}, {"left": "بَحْر", "right": "ba7r"}], "answer": "بَيْت = bayt ; جَمِيل = djamîl ; جَدِيد = djadîd ; قَهْوَة = qahwa ; بَحْر = ba7r", "acceptedAnswers": [], "explanation": "جَمِيل (dja-mîl) et جَدِيد (dja-dîd) commencent pareil et finissent presque pareil : regarde la 2e lettre (م ou د) et la dernière (ل ou د).", "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e06', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.kana']::text[], 'mcq', 'lesson', 'كَانَ', array['il était']::text[], 'كَانَ (kâ-na) = il était, il a été : c''est le verbe « être » au passé. Au présent, on ne l''écrit pas.', 2, '{"id": "ar.l23.e06", "unitIds": ["ar.g23.short_sentences", "ar.v.kana"], "type": "mcq", "difficulty": 2, "instruction": "Que veut dire ce mot ?", "prompt": "كَانَ", "promptLanguage": "ar", "options": ["il était", "il est allé", "il a mangé", "il a écrit"], "answer": "il était", "acceptedAnswers": ["il était"], "explanation": "كَانَ (kâ-na) = il était, il a été : c''est le verbe « être » au passé. Au présent, on ne l''écrit pas.", "tip": "Pas de verbe « être » au présent, mais كَانَ au passé.", "extraExample": {"text": "كَانَ فِي الْمَدْرَسَةِ", "translation": "Il était à l''école.", "transliteration": "kâna fî l-madrasa"}, "errorPatterns": [{"equals": "il est allé", "category": "vocabulary", "feedback": "« Il est allé » se dit ذَهَبَ (dhahaba)."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e07', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.suq']::text[], 'mcq', 'lesson', 'Comment se lit السُّوقُ ?', array['as-sûqu']::text[], 'Devant س (une lettre solaire), le ل de l''article ne se prononce pas : la chadda sur س montre que la lettre est doublée, as-sûq.', 2, '{"id": "ar.l23.e07", "unitIds": ["ar.g23.short_sentences", "ar.v.suq"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Comment se lit السُّوقُ ?", "promptLanguage": "fr", "options": ["as-sûqu", "al-sûqu", "a-sûqu", "at-sûqu"], "answer": "as-sûqu", "acceptedAnswers": ["as-sûqu"], "explanation": "Devant س (une lettre solaire), le ل de l''article ne se prononce pas : la chadda sur س montre que la lettre est doublée, as-sûq.", "tip": "Chadda juste après ال : le ل est muet et la lettre se redouble.", "extraExample": {"text": "الشَّايُ حَارٌّ", "translation": "Le thé est chaud.", "transliteration": "ach-châyu 7ârr"}, "errorPatterns": [{"equals": "al-sûqu", "category": "spelling", "feedback": "Devant س, le ل ne se prononce pas : la chadda double le س, as-sûq."}, {"equals": "at-sûqu", "category": "spelling", "feedback": "La lettre doublée est س (as-), pas ت."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e08', 'ar', 'ar.l23', 'ar.v.hiya', array['ar.v.hiya','ar.g23.short_sentences','ar.v.bayt','ar.v.fi']::text[], 'mcq', 'lesson', 'هِيَ فِي الْبَيْتِ', array['Elle est à la maison.']::text[], 'Révision : هِيَ = elle (kasra sous ه, ي final). فِي الْبَيْتِ = à la maison, avec une kasra à la fin du nom après فِي.', 2, '{"id": "ar.l23.e08", "unitIds": ["ar.v.hiya", "ar.g23.short_sentences", "ar.v.bayt", "ar.v.fi"], "type": "mcq", "difficulty": 2, "instruction": "Lis la phrase d''un trait.", "prompt": "هِيَ فِي الْبَيْتِ", "promptLanguage": "ar", "options": ["Elle est à la maison.", "Il est à la maison.", "Je suis à la maison.", "Tu es à la maison."], "answer": "Elle est à la maison.", "acceptedAnswers": ["Elle est à la maison."], "explanation": "Révision : هِيَ = elle (kasra sous ه, ي final). فِي الْبَيْتِ = à la maison, avec une kasra à la fin du nom après فِي.", "tip": "Sujet d''abord (هِيَ), puis فِي + le nom en kasra.", "extraExample": {"text": "هُوَ فِي الْبَيْتِ", "translation": "Il est à la maison.", "transliteration": "huwa fî l-bayt"}, "errorPatterns": [{"equals": "Il est à la maison.", "category": "word_confusion", "feedback": "« Il » se dit هُوَ (damma, و). Ici : هِيَ, elle."}, {"equals": "Je suis à la maison.", "category": "word_confusion", "feedback": "« Je » se dit أَنَا."}, {"equals": "Tu es à la maison.", "category": "word_confusion", "feedback": "« Tu » se dit أَنْتَ."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e09', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.djamil','ar.v.djadid','ar.v.bayt']::text[], 'fill_blank', 'lesson', 'هٰذَا بَيْتٌ ___', array['جَمِيلٌ']::text[], '« Belle » = جَمِيل. بَيْت est masculin : l''adjectif n''a pas de ـة. جَدِيد (neuf) ressemble à جَمِيل mais ne veut pas dire « beau ».', 2, '{"id": "ar.l23.e09", "unitIds": ["ar.g23.short_sentences", "ar.v.djamil", "ar.v.djadid", "ar.v.bayt"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « C''est une belle maison. »", "prompt": "هٰذَا بَيْتٌ ___", "promptLanguage": "ar", "options": ["جَمِيلٌ", "جَمِيلَةٌ", "جَدِيدٌ"], "answer": "جَمِيلٌ", "acceptedAnswers": ["جَمِيلٌ"], "explanation": "« Belle » = جَمِيل. بَيْت est masculin : l''adjectif n''a pas de ـة. جَدِيد (neuf) ressemble à جَمِيل mais ne veut pas dire « beau ».", "tip": "جَمِيل a un م au milieu ; جَدِيد a un د.", "extraExample": {"text": "هٰذِهِ سَيَّارَةٌ جَمِيلَةٌ", "translation": "C''est une belle voiture.", "transliteration": "hâdhihi sayyâratun djamîla"}, "errorPatterns": [{"equals": "جَمِيلَةٌ", "category": "grammar", "feedback": "بَيْت est masculin : l''adjectif ne prend pas ـة."}, {"equals": "جَدِيدٌ", "category": "word_confusion", "feedback": "جَدِيد veut dire « neuf » ; « beau » se dit جَمِيل."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e10', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.bayt','ar.v.fi']::text[], 'fill_blank', 'lesson', 'أَنَا فِي ___', array['الْبَيْتِ']::text[], 'Après فِي, le nom prend une kasra (ـِ) à la fin : فِي الْبَيْتِ.', 2, '{"id": "ar.l23.e10", "unitIds": ["ar.g23.short_sentences", "ar.v.bayt", "ar.v.fi"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « Je suis à la maison. »", "prompt": "أَنَا فِي ___", "promptLanguage": "ar", "options": ["الْبَيْتِ", "الْبَيْتُ", "الْبَيْتَ"], "answer": "الْبَيْتِ", "acceptedAnswers": ["الْبَيْتِ"], "explanation": "Après فِي, le nom prend une kasra (ـِ) à la fin : فِي الْبَيْتِ.", "tip": "Après une préposition (فِي, مِنْ, عَلَى, إِلَى, مَعَ) : kasra à la fin du nom.", "extraExample": {"text": "الْقَهْوَةُ فِي الْبَيْتِ", "translation": "Le café est dans la maison.", "transliteration": "al-qahwatu fî l-bayt"}, "errorPatterns": [{"equals": "الْبَيْتُ", "category": "grammar", "feedback": "ـُ (damma) est la terminaison du sujet. Après فِي, il faut ـِ."}, {"equals": "الْبَيْتَ", "category": "grammar", "feedback": "ـَ (fatha) est la terminaison de l''objet. Après فِي, il faut ـِ."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e11', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.bayt','ar.v.djamil','ar.v.chay','ar.v.suq','ar.v.qahwa']::text[], 'match', 'lesson', 'Cinq phrases à lire d''un trait', '{}'::text[], 'Repère d''abord les petits mots (هٰذَا, فِي, إِلَى), puis le nom, puis la terminaison. Au présent, le verbe « être » n''est pas écrit.', 3, '{"id": "ar.l23.e11", "unitIds": ["ar.g23.short_sentences", "ar.v.bayt", "ar.v.djamil", "ar.v.chay", "ar.v.suq", "ar.v.qahwa"], "type": "match", "difficulty": 3, "instruction": "Associe chaque phrase à sa traduction.", "prompt": "Cinq phrases à lire d''un trait", "promptLanguage": "fr", "pairs": [{"left": "هٰذَا بَيْتٌ جَمِيلٌ", "right": "C''est une belle maison."}, {"left": "أَنَا فِي الْمَدْرَسَةِ", "right": "Je suis à l''école."}, {"left": "الشَّايُ حَارٌّ", "right": "Le thé est chaud."}, {"left": "ذَهَبَ إِلَى السُّوقِ", "right": "Il est allé au marché."}, {"left": "الْقَهْوَةُ بَارِدَةٌ", "right": "Le café est froid."}], "answer": "هٰذَا بَيْتٌ جَمِيلٌ = C''est une belle maison. ; أَنَا فِي الْمَدْرَسَةِ = Je suis à l''école. ; الشَّايُ حَارٌّ = Le thé est chaud. ; ذَهَبَ إِلَى السُّوقِ = Il est allé au marché. ; الْقَهْوَةُ بَارِدَةٌ = Le café est froid.", "acceptedAnswers": [], "explanation": "Repère d''abord les petits mots (هٰذَا, فِي, إِلَى), puis le nom, puis la terminaison. Au présent, le verbe « être » n''est pas écrit.", "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e12', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.bayt','ar.v.djamil']::text[], 'mcq', 'lesson', 'Comment se lit, en fin de phrase : الْبَيْتُ جَمِيلٌ ?', array['al-baytu djamîl']::text[], 'Au milieu de la phrase, on prononce la damma de الْبَيْتُ (-u). À la fin, on ne prononce pas la terminaison du dernier mot : djamîl, sans -un.', 3, '{"id": "ar.l23.e12", "unitIds": ["ar.g23.short_sentences", "ar.v.bayt", "ar.v.djamil"], "type": "mcq", "difficulty": 3, "instruction": "Lis la phrase comme à la pause.", "prompt": "Comment se lit, en fin de phrase : الْبَيْتُ جَمِيلٌ ?", "promptLanguage": "fr", "options": ["al-baytu djamîl", "al-baytu djamîlun", "al-bayt djamîl", "al-baytu djamîla"], "answer": "al-baytu djamîl", "acceptedAnswers": ["al-baytu djamîl"], "explanation": "Au milieu de la phrase, on prononce la damma de الْبَيْتُ (-u). À la fin, on ne prononce pas la terminaison du dernier mot : djamîl, sans -un.", "tip": "Dernier mot : on s''arrête sur la consonne.", "extraExample": {"text": "الْقَمَرُ جَمِيلٌ", "translation": "La lune est belle.", "transliteration": "al-qamaru djamîl"}, "errorPatterns": [{"equals": "al-baytu djamîlun", "category": "spelling", "feedback": "Le dernier mot se lit sans sa terminaison (-un) quand on s''arrête."}, {"equals": "al-bayt djamîl", "category": "spelling", "feedback": "La damma de الْبَيْتُ se prononce au milieu de la phrase : al-baytu."}, {"equals": "al-baytu djamîla", "category": "spelling", "feedback": "Le signe final est un tanwin en damma (-un), pas -a ; et on ne le prononce pas à la pause."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e13', 'ar', 'ar.l23', 'ar.v.dhahaba', array['ar.v.dhahaba','ar.g23.short_sentences','ar.v.bahr','ar.v.ila']::text[], 'fill_blank', 'lesson', 'ذَهَبَ إِلَى ___', array['الْبَحْرِ']::text[], 'Révision de ذَهَبَ إِلَى : après إِلَى, le nom prend une kasra à la fin, الْبَحْرِ (la mer).', 3, '{"id": "ar.l23.e13", "unitIds": ["ar.v.dhahaba", "ar.g23.short_sentences", "ar.v.bahr", "ar.v.ila"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Il est allé à la mer. »", "prompt": "ذَهَبَ إِلَى ___", "promptLanguage": "ar", "options": ["الْبَحْرِ", "الْبَحْرُ", "الْبَحْرَ"], "answer": "الْبَحْرِ", "acceptedAnswers": ["الْبَحْرِ"], "explanation": "Révision de ذَهَبَ إِلَى : après إِلَى, le nom prend une kasra à la fin, الْبَحْرِ (la mer).", "tip": "إِلَى → kasra à la fin du nom.", "extraExample": {"text": "ذَهَبَ إِلَى الْجَبَلِ", "translation": "Il est allé à la montagne.", "transliteration": "dhahaba ''ilâ l-djabal"}, "errorPatterns": [{"equals": "الْبَحْرُ", "category": "grammar", "feedback": "ـُ (damma) est la terminaison du sujet. Après إِلَى, il faut ـِ."}, {"equals": "الْبَحْرَ", "category": "grammar", "feedback": "ـَ (fatha) est la terminaison de l''objet. Après إِلَى, il faut ـِ."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e14', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.alladhi']::text[], 'mcq', 'lesson', 'Dans الْكِتَابُ الَّذِي عَلَى الْمَكْتَبِ جَدِيدٌ, que veut dire الَّذِي ?', array['qui, que']::text[], 'الَّذِي (alladhî) relie le nom à ce qui le décrit : « le livre QUI est sur le bureau est nouveau ». À lire d''un bloc.', 3, '{"id": "ar.l23.e14", "unitIds": ["ar.g23.short_sentences", "ar.v.alladhi"], "type": "mcq", "difficulty": 3, "instruction": "Que veut dire le petit mot ?", "prompt": "Dans الْكِتَابُ الَّذِي عَلَى الْمَكْتَبِ جَدِيدٌ, que veut dire الَّذِي ?", "promptLanguage": "fr", "options": ["qui, que", "dans", "et", "aujourd''hui"], "answer": "qui, que", "acceptedAnswers": ["qui, que"], "explanation": "الَّذِي (alladhî) relie le nom à ce qui le décrit : « le livre QUI est sur le bureau est nouveau ». À lire d''un bloc.", "tip": "الَّذِي = qui / que, à lire d''un seul bloc : alladhî.", "extraExample": {"text": "الشَّايُ الَّذِي هُنَا بَارِدٌ", "translation": "Le thé qui est ici est froid.", "transliteration": "ach-châyu lladhî hunâ bârid"}, "errorPatterns": [{"equals": "dans", "category": "word_confusion", "feedback": "« Dans » se dit فِي, un petit mot de deux lettres."}, {"equals": "et", "category": "word_confusion", "feedback": "« Et » se dit وَ, collé au mot suivant."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e15', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.bayt','ar.v.djadid']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : ceci / une maison / neuve', array['هٰذَا بَيْتٌ جَدِيدٌ']::text[], 'هٰذَا ouvre la phrase, puis le nom (بَيْتٌ), puis l''adjectif (جَدِيدٌ) : en arabe, l''adjectif suit le nom.', 2, '{"id": "ar.l23.e15", "unitIds": ["ar.g23.short_sentences", "ar.v.bayt", "ar.v.djadid"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre : « C''est une maison neuve. »", "prompt": "Remets dans l''ordre : ceci / une maison / neuve", "promptLanguage": "fr", "tokens": ["جَدِيدٌ", "بَيْتٌ", "هٰذَا"], "answer": "هٰذَا بَيْتٌ جَدِيدٌ", "acceptedAnswers": ["هٰذَا بَيْتٌ جَدِيدٌ"], "explanation": "هٰذَا ouvre la phrase, puis le nom (بَيْتٌ), puis l''adjectif (جَدِيدٌ) : en arabe, l''adjectif suit le nom.", "tip": "Petit mot, nom, adjectif.", "extraExample": {"text": "هٰذِهِ قَهْوَةٌ جَدِيدَةٌ", "translation": "C''est un nouveau café.", "transliteration": "hâdhihi qahwatun djadîda"}, "pool": "lesson", "lessonId": "ar.l23", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e16', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.chariba','ar.v.qahwa','ar.v.bayt','ar.v.al_yawm']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : il a bu / le café / à la maison / aujourd''hui', array['شَرِبَ الْقَهْوَةَ فِي الْبَيْتِ الْيَوْمَ','الْيَوْمَ شَرِبَ الْقَهْوَةَ فِي الْبَيْتِ']::text[], 'Verbe (شَرِبَ), ce qu''il a bu (الْقَهْوَةَ, fatha de l''objet), le lieu (فِي الْبَيْتِ, kasra après فِي), puis le moment (الْيَوْمَ). On peut aussi commencer par الْيَوْمَ.', 3, '{"id": "ar.l23.e16", "unitIds": ["ar.g23.short_sentences", "ar.v.chariba", "ar.v.qahwa", "ar.v.bayt", "ar.v.al_yawm"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Il a bu le café à la maison aujourd''hui. »", "prompt": "Remets dans l''ordre : il a bu / le café / à la maison / aujourd''hui", "promptLanguage": "fr", "tokens": ["الْيَوْمَ", "الْبَيْتِ", "فِي", "الْقَهْوَةَ", "شَرِبَ"], "answer": "شَرِبَ الْقَهْوَةَ فِي الْبَيْتِ الْيَوْمَ", "acceptedAnswers": ["شَرِبَ الْقَهْوَةَ فِي الْبَيْتِ الْيَوْمَ", "الْيَوْمَ شَرِبَ الْقَهْوَةَ فِي الْبَيْتِ"], "explanation": "Verbe (شَرِبَ), ce qu''il a bu (الْقَهْوَةَ, fatha de l''objet), le lieu (فِي الْبَيْتِ, kasra après فِي), puis le moment (الْيَوْمَ). On peut aussi commencer par الْيَوْمَ.", "tip": "Verbe, objet, lieu, moment.", "extraExample": {"text": "شَرِبَ الشَّايَ فِي الْمَدْرَسَةِ", "translation": "Il a bu le thé à l''école.", "transliteration": "chariba ch-châya fî l-madrasa"}, "pool": "lesson", "lessonId": "ar.l23", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e17', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.kana']::text[], 'fill_blank', 'lesson', 'كَانَ الشَّايُ ___', array['حَارًّا']::text[], 'Après كَانَ, l''adjectif prend la terminaison -an (ـًا) : حَارًّا. Au présent, sans كَانَ, on aurait الشَّايُ حَارٌّ.', 4, '{"id": "ar.l23.e17", "unitIds": ["ar.g23.short_sentences", "ar.v.kana"], "type": "fill_blank", "difficulty": 4, "instruction": "Complète : « Le thé était chaud. »", "prompt": "كَانَ الشَّايُ ___", "promptLanguage": "ar", "options": ["حَارًّا", "حَارٌّ", "بَارِدًا"], "answer": "حَارًّا", "acceptedAnswers": ["حَارًّا"], "explanation": "Après كَانَ, l''adjectif prend la terminaison -an (ـًا) : حَارًّا. Au présent, sans كَانَ, on aurait الشَّايُ حَارٌّ.", "tip": "كَانَ + adjectif en -an.", "extraExample": {"text": "كَانَ الْبَحْرُ بَارِدًا", "translation": "La mer était froide.", "transliteration": "kâna l-ba7ru bâridan"}, "errorPatterns": [{"equals": "حَارٌّ", "category": "grammar", "feedback": "Sans كَانَ, l''adjectif finit par -un (ـٌ). Après كَانَ, il prend -an (ـًا)."}, {"equals": "بَارِدًا", "category": "word_confusion", "feedback": "بَارِدًا veut dire « froid » ; ici le thé était chaud."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e18', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.kana','ar.v.bayt','ar.v.djadid']::text[], 'translation', 'lesson', 'كَانَ الْبَيْتُ جَدِيدًا', array['La maison était neuve.','La maison était nouvelle.','La maison était récente.']::text[], 'كَانَ = il était (le verbe « être » au passé) ; الْبَيْتُ = la maison ; جَدِيدًا = neuve (terminaison -an après كَانَ).', 3, '{"id": "ar.l23.e18", "unitIds": ["ar.g23.short_sentences", "ar.v.kana", "ar.v.bayt", "ar.v.djadid"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "كَانَ الْبَيْتُ جَدِيدًا", "promptLanguage": "ar", "answer": "La maison était neuve.", "acceptedAnswers": ["La maison était neuve.", "La maison était nouvelle.", "La maison était récente."], "explanation": "كَانَ = il était (le verbe « être » au passé) ; الْبَيْتُ = la maison ; جَدِيدًا = neuve (terminaison -an après كَانَ).", "tip": "كَانَ met la phrase au passé : « était ».", "extraExample": {"text": "كَانَ الْمَطَارُ كَبِيرًا", "translation": "L''aéroport était grand.", "transliteration": "kâna l-maTâru kabîran"}, "errorPatterns": [{"contains": "est neuve", "category": "verb_tense", "feedback": "كَانَ met la phrase au passé : « était », pas « est »."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e19', 'ar', 'ar.l23', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.matar_aeroport','ar.g23.short_sentences','ar.v.al_yawm']::text[], 'translation', 'lesson', 'ذَهَبَ إِلَى الْمَطَارِ الْيَوْمَ', array['Il est allé à l''aéroport aujourd''hui.','Aujourd''hui, il est allé à l''aéroport.','Il est allé aujourd''hui à l''aéroport.']::text[], 'Révision des mots longs : مَطَار se lit maTâr (voyelle longue), « l''aéroport ». الْيَوْمَ = aujourd''hui.', 3, '{"id": "ar.l23.e19", "unitIds": ["ar.g20.long_words_blocks", "ar.v.matar_aeroport", "ar.g23.short_sentences", "ar.v.al_yawm"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "ذَهَبَ إِلَى الْمَطَارِ الْيَوْمَ", "promptLanguage": "ar", "answer": "Il est allé à l''aéroport aujourd''hui.", "acceptedAnswers": ["Il est allé à l''aéroport aujourd''hui.", "Aujourd''hui, il est allé à l''aéroport.", "Il est allé aujourd''hui à l''aéroport."], "explanation": "Révision des mots longs : مَطَار se lit maTâr (voyelle longue), « l''aéroport ». الْيَوْمَ = aujourd''hui.", "tip": "Le ا de مَطَار fait la différence avec مَطَر (la pluie).", "extraExample": {"text": "هُوَ فِي الْمَطَارِ", "translation": "Il est à l''aéroport.", "transliteration": "huwa fî l-maTâr"}, "errorPatterns": [{"contains": "pluie", "category": "word_confusion", "feedback": "مَطَار (avec ا) est l''aéroport ; مَطَر (sans ا) est la pluie."}, {"contains": "hier", "category": "vocabulary", "feedback": "الْيَوْم veut dire « aujourd''hui »."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e20', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.alladhi','ar.v.bayt','ar.v.madina','ar.v.djadid']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : la maison / qui / est en ville / est neuve', array['الْبَيْتُ الَّذِي فِي الْمَدِينَةِ جَدِيدٌ']::text[], 'Le nom (الْبَيْتُ) est suivi de الَّذِي, puis de ce qui le décrit (فِي الْمَدِينَةِ), et l''adjectif جَدِيدٌ termine la phrase.', 4, '{"id": "ar.l23.e20", "unitIds": ["ar.g23.short_sentences", "ar.v.alladhi", "ar.v.bayt", "ar.v.madina", "ar.v.djadid"], "type": "reorder", "difficulty": 4, "instruction": "Remets les mots dans l''ordre : « La maison qui est en ville est neuve. »", "prompt": "Remets dans l''ordre : la maison / qui / est en ville / est neuve", "promptLanguage": "fr", "tokens": ["جَدِيدٌ", "الْمَدِينَةِ", "فِي", "الَّذِي", "الْبَيْتُ"], "answer": "الْبَيْتُ الَّذِي فِي الْمَدِينَةِ جَدِيدٌ", "acceptedAnswers": ["الْبَيْتُ الَّذِي فِي الْمَدِينَةِ جَدِيدٌ"], "explanation": "Le nom (الْبَيْتُ) est suivi de الَّذِي, puis de ce qui le décrit (فِي الْمَدِينَةِ), et l''adjectif جَدِيدٌ termine la phrase.", "tip": "Nom, الَّذِي, description, puis adjectif.", "extraExample": {"text": "السَّيَّارَةُ الَّتِي فِي الشَّارِعِ جَدِيدَةٌ", "translation": "La voiture qui est dans la rue est neuve.", "transliteration": "as-sayyâratu llatî fî ch-châri3i djadîda"}, "pool": "lesson", "lessonId": "ar.l23", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e21', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.qahwa']::text[], 'free_answer', 'lesson', 'Comment se lit قَهْوَة ?', array['qahwa']::text[], 'قَ = qa, هْ = h (soukoun), وَ = wa, ة = a final : qah-wa, « le café ». ق a deux points au-dessus (q).', 3, '{"id": "ar.l23.e21", "unitIds": ["ar.g23.short_sentences", "ar.v.qahwa"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture de ce mot en lettres latines.", "prompt": "Comment se lit قَهْوَة ?", "promptLanguage": "fr", "answer": "qahwa", "acceptedAnswers": ["qahwa"], "hint": "ق se transcrit q.", "explanation": "قَ = qa, هْ = h (soukoun), وَ = wa, ة = a final : qah-wa, « le café ». ق a deux points au-dessus (q).", "tip": "Soukoun sur ه : qah-wa, pas qa-ha-wa.", "extraExample": {"text": "الْقَهْوَةُ حَارَّةٌ", "translation": "Le café est chaud.", "transliteration": "al-qahwatu 7ârra"}, "errorPatterns": [{"equals": "qahawa", "category": "spelling", "feedback": "Le soukoun sur ه supprime la voyelle : qah-wa."}, {"equals": "fahwa", "category": "spelling", "feedback": "ف n''a qu''un point ; ici la lettre en a deux : ق, q."}, {"equals": "kahwa", "category": "spelling", "feedback": "ك (k) n''a pas de points ; ici il y en a deux : ق, q."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l23.e22', 'ar', 'ar.l23', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.djamil']::text[], 'free_answer', 'lesson', 'Comment se lit جَمِيل ?', array['djamîl','djamiil','djamil','jamiil','jamil','jamîl']::text[], 'جَ = dja, مِي = mî (kasra + ي = î long), ل = l : dja-mîl, « beau ». Ne le confonds pas avec جَدِيد (djadîd, neuf).', 4, '{"id": "ar.l23.e22", "unitIds": ["ar.g23.short_sentences", "ar.v.djamil"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture de ce mot en lettres latines.", "prompt": "Comment se lit جَمِيل ?", "promptLanguage": "fr", "answer": "djamîl", "acceptedAnswers": ["djamîl", "djamiil", "djamil", "jamiil", "jamil", "jamîl"], "hint": "ج se transcrit dj.", "explanation": "جَ = dja, مِي = mî (kasra + ي = î long), ل = l : dja-mîl, « beau ». Ne le confonds pas avec جَدِيد (djadîd, neuf).", "tip": "Kasra + ي = î : écris î, ou ii.", "extraExample": {"text": "الْبَحْرُ جَمِيلٌ", "translation": "La mer est belle.", "transliteration": "al-ba7ru djamîl"}, "errorPatterns": [{"equals": "djamal", "category": "word_confusion", "feedback": "djamal (جَمَل) est le chameau, sans ي. Ici le ي allonge le i : dja-mîl."}, {"equals": "djadid", "category": "word_confusion", "feedback": "djadîd est جَدِيد (neuf). Ici la 2e lettre est م : djamîl."}], "pool": "lesson", "lessonId": "ar.l23", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e01', 'ar', 'ar.l24', 'ar.g24.speed_reading', array['ar.g24.speed_reading','ar.v.nahar']::text[], 'mcq', 'lesson', 'نَهَار', array['nahâr']::text[], 'نَ = na, هَا = hâ (fatha + ا : a long), ر = r : na-hâr, « le jour ». Les 4 réflexes en une seconde : blocs (نها | ر), racine (ن ه ر), points (aucun), syllabes (na-hâr).', 1, '{"id": "ar.l24.e01", "unitIds": ["ar.g24.speed_reading", "ar.v.nahar"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "نَهَار", "promptLanguage": "ar", "options": ["nahâr", "nahr", "nahar", "nahâz"], "answer": "nahâr", "acceptedAnswers": ["nahâr"], "explanation": "نَ = na, هَا = hâ (fatha + ا : a long), ر = r : na-hâr, « le jour ». Les 4 réflexes en une seconde : blocs (نها | ر), racine (ن ه ر), points (aucun), syllabes (na-hâr).", "tip": "Blocs, racine, points, syllabes : quatre coups d''œil.", "extraExample": {"text": "نَهَارٌ جَمِيلٌ", "translation": "une belle journée", "transliteration": "nahârun djamîl"}, "errorPatterns": [{"equals": "nahr", "category": "spelling", "feedback": "Il y a un ا après ه : voyelle longue, na-hâr. Ne saute pas les voyelles longues en lisant vite."}, {"equals": "nahar", "category": "spelling", "feedback": "Le ا allonge le a : nahâr, avec un a long."}, {"equals": "nahâz", "category": "spelling", "feedback": "ر n''a pas de point ; ز en a un. Ici la dernière lettre est ر."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e02', 'ar', 'ar.l24', 'ar.g24.speed_reading', array['ar.g24.speed_reading','ar.v.layl','ar.v.nahar','ar.v.chita','ar.v.nadjm','ar.v.chams']::text[], 'match', 'lesson', 'Le ciel et les saisons : cinq mots', '{}'::text[], 'لَيْل et نَهَار sont des contraires. شَمْس (soleil) est féminin et نَجْم (étoile) masculin. شِتَاء (hiver) finit par une hamza seule, ء.', 1, '{"id": "ar.l24.e02", "unitIds": ["ar.g24.speed_reading", "ar.v.layl", "ar.v.nahar", "ar.v.chita", "ar.v.nadjm", "ar.v.chams"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à son sens.", "prompt": "Le ciel et les saisons : cinq mots", "promptLanguage": "fr", "pairs": [{"left": "لَيْل", "right": "la nuit"}, {"left": "نَهَار", "right": "le jour"}, {"left": "شِتَاء", "right": "l''hiver"}, {"left": "نَجْم", "right": "l''étoile"}, {"left": "شَمْس", "right": "le soleil"}], "answer": "لَيْل = la nuit ; نَهَار = le jour ; شِتَاء = l''hiver ; نَجْم = l''étoile ; شَمْس = le soleil", "acceptedAnswers": [], "explanation": "لَيْل et نَهَار sont des contraires. شَمْس (soleil) est féminin et نَجْم (étoile) masculin. شِتَاء (hiver) finit par une hamza seule, ء.", "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e03', 'ar', 'ar.l24', 'ar.g24.speed_reading', array['ar.g24.speed_reading','ar.v.chita']::text[], 'mcq', 'lesson', 'شِتَاء', array['chitâ''']::text[], 'شِ = chi (ش : trois points, kasra), تَا = tâ, ء = hamza finale : chi-tâ'', « l''hiver ». Deux blocs : شتا | ء, car le ا coupe le mot.', 2, '{"id": "ar.l24.e03", "unitIds": ["ar.g24.speed_reading", "ar.v.chita"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "شِتَاء", "promptLanguage": "ar", "options": ["chitâ''", "chitâ", "sitâ''", "chatâ''"], "answer": "chitâ''", "acceptedAnswers": ["chitâ''"], "explanation": "شِ = chi (ش : trois points, kasra), تَا = tâ, ء = hamza finale : chi-tâ'', « l''hiver ». Deux blocs : شتا | ء, car le ا coupe le mot.", "tip": "Une petite lettre seule à la fin : c''est la hamza, on marque un petit arrêt ('').", "extraExample": {"text": "الشِّتَاءُ بَارِدٌ", "translation": "L''hiver est froid.", "transliteration": "ach-chitâ''u bârid"}, "errorPatterns": [{"equals": "chitâ", "category": "spelling", "feedback": "N''oublie pas la hamza finale (ء) : chitâ''."}, {"equals": "sitâ''", "category": "spelling", "feedback": "ش a trois points : ch, pas s."}, {"equals": "chatâ''", "category": "spelling", "feedback": "Sous ش il y a une kasra (i) : chi-, pas cha-."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e04', 'ar', 'ar.l24', 'ar.g24.speed_reading', array['ar.g24.speed_reading','ar.v.maa_eau']::text[], 'mcq', 'lesson', 'مَاء', array['mâ''']::text[], 'مَا = mâ (fatha + ا), ء = hamza finale : mâ'', « l''eau ». La hamza ne s''attache à rien : ما | ء.', 2, '{"id": "ar.l24.e04", "unitIds": ["ar.g24.speed_reading", "ar.v.maa_eau"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "مَاء", "promptLanguage": "ar", "options": ["mâ''", "mâ", "ma''", "mâ3"], "answer": "mâ''", "acceptedAnswers": ["mâ''"], "explanation": "مَا = mâ (fatha + ا), ء = hamza finale : mâ'', « l''eau ». La hamza ne s''attache à rien : ما | ء.", "tip": "Une petite lettre seule à la fin : la hamza, on marque un arrêt ('').", "extraExample": {"text": "هٰذَا مَاءٌ حَارٌّ", "translation": "C''est de l''eau chaude.", "transliteration": "hâdhâ mâ''un 7ârr"}, "errorPatterns": [{"equals": "mâ", "category": "spelling", "feedback": "Sans la hamza finale, مَا veut dire « quoi » ou « ne… pas ». Ici il y a un ء : mâ''."}, {"equals": "ma''", "category": "spelling", "feedback": "Le ا allonge le a : mâ''."}, {"equals": "mâ3", "category": "spelling", "feedback": "ع est une lettre plus grande, avec une tête ; ici la fin est la petite hamza ء."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e05', 'ar', 'ar.l24', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.nadjm','ar.g24.speed_reading']::text[], 'mcq', 'lesson', 'Quel mot se lit nadjm (l''étoile) ?', array['نَجْم']::text[], 'L''étoile commence par نَ puis une lettre avec un point à l''intérieur de sa courbe : ج (dj). ح n''a pas de point, خ en a un au-dessus. Le mot finit par م, pas par ر.', 2, '{"id": "ar.l24.e05", "unitIds": ["ar.g21.lookalike_letters", "ar.v.nadjm", "ar.g24.speed_reading"], "type": "mcq", "difficulty": 2, "instruction": "Retrouve le mot qui correspond à la lecture.", "prompt": "Quel mot se lit nadjm (l''étoile) ?", "promptLanguage": "fr", "options": ["نَجْم", "نَحْم", "نَخْم", "نَجْر"], "answer": "نَجْم", "acceptedAnswers": ["نَجْم"], "explanation": "L''étoile commence par نَ puis une lettre avec un point à l''intérieur de sa courbe : ج (dj). ح n''a pas de point, خ en a un au-dessus. Le mot finit par م, pas par ر.", "tip": "Vérifie la lettre du milieu ET la dernière.", "extraExample": {"text": "هٰذَا نَجْمٌ كَبِيرٌ", "translation": "C''est une grande étoile.", "transliteration": "hâdhâ nadjmun kabîr"}, "errorPatterns": [{"equals": "نَحْم", "category": "spelling", "feedback": "ح n''a aucun point (7). L''étoile a un ج, avec un point à l''intérieur."}, {"equals": "نَخْم", "category": "spelling", "feedback": "خ a un point au-dessus (kh). Pour dj, le point est à l''intérieur de ج."}, {"equals": "نَجْر", "category": "spelling", "feedback": "La dernière lettre est م (une boucle), pas ر."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e06', 'ar', 'ar.l24', 'ar.g24.speed_reading', array['ar.g24.speed_reading','ar.v.rih','ar.v.ghayma','ar.v.maa_eau','ar.v.chita','ar.v.nadjm']::text[], 'match', 'lesson', 'Cinq mots, cinq lectures : le plus vite possible', '{}'::text[], 'Chaque mot demande un autre réflexe : رِيح se coupe après ر ; غَيْمَة a un غ (un point) ; مَاء et شِتَاء finissent par une hamza ; نَجْم a un ج (point à l''intérieur).', 2, '{"id": "ar.l24.e06", "unitIds": ["ar.g24.speed_reading", "ar.v.rih", "ar.v.ghayma", "ar.v.maa_eau", "ar.v.chita", "ar.v.nadjm"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Cinq mots, cinq lectures : le plus vite possible", "promptLanguage": "fr", "pairs": [{"left": "رِيح", "right": "rî7"}, {"left": "غَيْمَة", "right": "ghayma"}, {"left": "مَاء", "right": "mâ''"}, {"left": "شِتَاء", "right": "chitâ''"}, {"left": "نَجْم", "right": "nadjm"}], "answer": "رِيح = rî7 ; غَيْمَة = ghayma ; مَاء = mâ'' ; شِتَاء = chitâ'' ; نَجْم = nadjm", "acceptedAnswers": [], "explanation": "Chaque mot demande un autre réflexe : رِيح se coupe après ر ; غَيْمَة a un غ (un point) ; مَاء et شِتَاء finissent par une hamza ; نَجْم a un ج (point à l''intérieur).", "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e07', 'ar', 'ar.l24', 'ar.g19.non_connecting_letters', array['ar.g19.non_connecting_letters','ar.v.chams','ar.g24.speed_reading']::text[], 'mcq', 'lesson', 'Lequel de ces mots s''écrit d''un seul bloc, sans aucune coupure ?', array['شَمْس']::text[], 'Révision : شَمْس ne contient aucune des lettres ا د ذ ر ز و, donc un seul bloc. رِيح se coupe après ر (ر | يح), مَاء après ا (ما | ء) et نَهَار après ا puis ر (نها | ر).', 2, '{"id": "ar.l24.e07", "unitIds": ["ar.g19.non_connecting_letters", "ar.v.chams", "ar.g24.speed_reading"], "type": "mcq", "difficulty": 2, "instruction": "Compte les blocs.", "prompt": "Lequel de ces mots s''écrit d''un seul bloc, sans aucune coupure ?", "promptLanguage": "fr", "options": ["شَمْس", "رِيح", "مَاء", "نَهَار"], "answer": "شَمْس", "acceptedAnswers": ["شَمْس"], "explanation": "Révision : شَمْس ne contient aucune des lettres ا د ذ ر ز و, donc un seul bloc. رِيح se coupe après ر (ر | يح), مَاء après ا (ما | ء) et نَهَار après ا puis ر (نها | ر).", "tip": "Cherche les lettres qui coupent : ا د ذ ر ز و.", "extraExample": {"text": "غَيْمَة", "translation": "le nuage : un seul bloc aussi", "transliteration": "ghayma"}, "errorPatterns": [{"equals": "رِيح", "category": "spelling", "feedback": "رِيح commence par ر, qui ne s''attache pas à la suivante : ر | يح."}, {"equals": "مَاء", "category": "spelling", "feedback": "Le ا coupe le mot, et la hamza finale reste seule : ما | ء."}, {"equals": "نَهَار", "category": "spelling", "feedback": "Le ا et le ر coupent le mot : نها | ر."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e08', 'ar', 'ar.l24', 'ar.g17.open_closed_syllables', array['ar.g17.open_closed_syllables','ar.v.ghayma','ar.g24.speed_reading']::text[], 'mcq', 'lesson', 'Combien de syllabes dans غَيْمَة ?', array['2']::text[], 'Révision : غَيْ (ghay, fermée : le ي porte un soukoun) + مَة (ma) = ghay-ma. Le ي avec soukoun fait partie de la première syllabe.', 3, '{"id": "ar.l24.e08", "unitIds": ["ar.g17.open_closed_syllables", "ar.v.ghayma", "ar.g24.speed_reading"], "type": "mcq", "difficulty": 3, "instruction": "Compte avec les voyelles.", "prompt": "Combien de syllabes dans غَيْمَة ?", "promptLanguage": "fr", "options": ["2", "3", "4"], "answer": "2", "acceptedAnswers": ["2"], "explanation": "Révision : غَيْ (ghay, fermée : le ي porte un soukoun) + مَة (ma) = ghay-ma. Le ي avec soukoun fait partie de la première syllabe.", "tip": "Le soukoun ferme la syllabe : ghay-ma, pas gha-y-ma.", "extraExample": {"text": "قَهْوَة", "translation": "le café : qah-wa, 2 syllabes", "transliteration": "qahwa"}, "errorPatterns": [{"equals": "3", "category": "spelling", "feedback": "Le ي avec soukoun ferme la première syllabe (ghay) : il ne forme pas une syllabe à part."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e09', 'ar', 'ar.l24', 'ar.g21.lookalike_letters', array['ar.g21.lookalike_letters','ar.v.maa_eau','ar.g24.speed_reading']::text[], 'fill_blank', 'lesson', 'مَا___', array['ء']::text[], 'L''eau : مَاء, qui finit par une hamza ء, une petite lettre seule. ع et غ sont des lettres plus grandes (3 et gh), faites d''une tête et d''une boucle.', 2, '{"id": "ar.l24.e09", "unitIds": ["ar.g21.lookalike_letters", "ar.v.maa_eau", "ar.g24.speed_reading"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète le mot « l''eau ».", "prompt": "مَا___", "promptLanguage": "ar", "options": ["ء", "ع", "غ"], "answer": "ء", "acceptedAnswers": ["ء"], "explanation": "L''eau : مَاء, qui finit par une hamza ء, une petite lettre seule. ع et غ sont des lettres plus grandes (3 et gh), faites d''une tête et d''une boucle.", "tip": "Une toute petite lettre à la fin : c''est la hamza.", "extraExample": {"text": "شِتَاء", "translation": "l''hiver : finit aussi par ء", "transliteration": "chitâ''"}, "errorPatterns": [{"equals": "ع", "category": "spelling", "feedback": "ع a une grande tête (3) ; la fin de مَاء est une petite hamza."}, {"equals": "غ", "category": "spelling", "feedback": "غ est ع avec un point (gh). L''eau finit par la petite hamza ء."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e10', 'ar', 'ar.l24', 'ar.g18.three_letter_roots', array['ar.g18.three_letter_roots','ar.v.nahar','ar.g24.speed_reading']::text[], 'mcq', 'lesson', 'Quelle est la racine de نَهَار (le jour) ?', array['ن ه ر']::text[], 'Révision : le ا de نَهَار allonge la voyelle (hâ), il ne fait pas partie de la racine. Les 3 consonnes sont ن ه ر ; نَهْر (la rivière) a les mêmes trois consonnes.', 3, '{"id": "ar.l24.e10", "unitIds": ["ar.g18.three_letter_roots", "ar.v.nahar", "ar.g24.speed_reading"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la racine.", "prompt": "Quelle est la racine de نَهَار (le jour) ?", "promptLanguage": "fr", "options": ["ن ه ر", "ن ه ا", "ه ا ر"], "answer": "ن ه ر", "acceptedAnswers": ["ن ه ر"], "explanation": "Révision : le ا de نَهَار allonge la voyelle (hâ), il ne fait pas partie de la racine. Les 3 consonnes sont ن ه ر ; نَهْر (la rivière) a les mêmes trois consonnes.", "tip": "Enlève les ا و ي qui allongent : il reste 3 consonnes.", "extraExample": {"text": "نَهْر", "translation": "la rivière (mêmes consonnes ن ه ر)", "transliteration": "nahr"}, "errorPatterns": [{"equals": "ن ه ا", "category": "spelling", "feedback": "Le ا allonge la voyelle : ce n''est pas une consonne de la racine."}, {"equals": "ه ا ر", "category": "spelling", "feedback": "Le mot commence par ن : la racine est ن ه ر."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e11', 'ar', 'ar.l24', 'ar.g22.frequent_words', array['ar.g22.frequent_words','ar.v.huwa','ar.v.huna','ar.v.layl']::text[], 'mcq', 'lesson', 'هُوَ هُنَا فِي اللَّيْلِ', array['huwa hunâ fî l-layl']::text[], 'Petits mots d''abord : هُوَ (il), هُنَا (ici), فِي (dans). Puis le nom : اللَّيْلِ (la nuit), avec la kasra après فِي.', 3, '{"id": "ar.l24.e11", "unitIds": ["ar.g22.frequent_words", "ar.v.huwa", "ar.v.huna", "ar.v.layl"], "type": "mcq", "difficulty": 3, "instruction": "Lis la phrase d''un trait.", "prompt": "هُوَ هُنَا فِي اللَّيْلِ", "promptLanguage": "ar", "options": ["huwa hunâ fî l-layl", "hiya hunâ fî l-layl", "huwa hunâ fî n-nahâr", "''anâ hunâ fî l-layl"], "answer": "huwa hunâ fî l-layl", "acceptedAnswers": ["huwa hunâ fî l-layl"], "explanation": "Petits mots d''abord : هُوَ (il), هُنَا (ici), فِي (dans). Puis le nom : اللَّيْلِ (la nuit), avec la kasra après فِي.", "tip": "Pronom, lieu, puis nom : trois coups d''œil.", "extraExample": {"text": "هِيَ هُنَا", "translation": "Elle est ici.", "transliteration": "hiya hunâ"}, "errorPatterns": [{"equals": "hiya hunâ fî l-layl", "category": "word_confusion", "feedback": "هِيَ = elle (kasra sous ه, ي final) ; ici le premier mot est هُوَ (damma, و)."}, {"equals": "huwa hunâ fî n-nahâr", "category": "word_confusion", "feedback": "« La journée » se dit النَّهَار ; ici le mot est اللَّيْل, avec deux ل."}, {"equals": "''anâ hunâ fî l-layl", "category": "word_confusion", "feedback": "أَنَا = je ; ici le premier mot est هُوَ."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e12', 'ar', 'ar.l24', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.rih','ar.v.barid','ar.g24.speed_reading']::text[], 'fill_blank', 'lesson', 'الرِّيحُ ___', array['بَارِدَةٌ']::text[], 'رِيح est un mot féminin : l''adjectif prend ـة, بَارِدَةٌ. بَارِدٌ est le masculin, et حَارَّةٌ veut dire « chaude ».', 3, '{"id": "ar.l24.e12", "unitIds": ["ar.g23.short_sentences", "ar.v.rih", "ar.v.barid", "ar.g24.speed_reading"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Le vent est froid. »", "prompt": "الرِّيحُ ___", "promptLanguage": "ar", "options": ["بَارِدَةٌ", "بَارِدٌ", "حَارَّةٌ"], "answer": "بَارِدَةٌ", "acceptedAnswers": ["بَارِدَةٌ"], "explanation": "رِيح est un mot féminin : l''adjectif prend ـة, بَارِدَةٌ. بَارِدٌ est le masculin, et حَارَّةٌ veut dire « chaude ».", "tip": "Le vent (رِيح) et le soleil (شَمْس) sont des mots féminins.", "extraExample": {"text": "لَا رِيحَ الْيَوْمَ", "translation": "Il n''y a pas de vent aujourd''hui.", "transliteration": "lâ rî7a l-yawm"}, "errorPatterns": [{"equals": "بَارِدٌ", "category": "grammar", "feedback": "رِيح est féminin : l''adjectif doit avoir ـة aussi."}, {"equals": "حَارَّةٌ", "category": "word_confusion", "feedback": "حَارَّةٌ veut dire « chaude » ; ici le vent est froid."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e13', 'ar', 'ar.l24', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.layl','ar.v.barid']::text[], 'mcq', 'lesson', 'اللَّيْلُ بَارِدٌ', array['al-laylu bârid']::text[], 'Devant ل, l''article s''écrit avec deux ل (ال + لَّيْل) et se lit al-layl. On prononce la damma de اللَّيْلُ au milieu de la phrase (al-laylu), mais pas la terminaison du dernier mot : bârid.', 3, '{"id": "ar.l24.e13", "unitIds": ["ar.g23.short_sentences", "ar.v.layl", "ar.v.barid"], "type": "mcq", "difficulty": 3, "instruction": "Lis la phrase d''un trait.", "prompt": "اللَّيْلُ بَارِدٌ", "promptLanguage": "ar", "options": ["al-laylu bârid", "an-laylu bârid", "al-layl bârid", "al-laylu bârida"], "answer": "al-laylu bârid", "acceptedAnswers": ["al-laylu bârid"], "explanation": "Devant ل, l''article s''écrit avec deux ل (ال + لَّيْل) et se lit al-layl. On prononce la damma de اللَّيْلُ au milieu de la phrase (al-laylu), mais pas la terminaison du dernier mot : bârid.", "tip": "Article, nom, terminaison, puis adjectif sans terminaison à la pause.", "extraExample": {"text": "اللَّيْلُ جَمِيلٌ هُنَا", "translation": "La nuit est belle ici.", "transliteration": "al-laylu djamîlun hunâ"}, "errorPatterns": [{"equals": "an-laylu bârid", "category": "spelling", "feedback": "Devant ل, l''article se lit al- : le ل se prononce (al-layl)."}, {"equals": "al-layl bârid", "category": "spelling", "feedback": "La damma de اللَّيْلُ se prononce au milieu de la phrase : al-laylu."}, {"equals": "al-laylu bârida", "category": "spelling", "feedback": "À la pause, le dernier mot finit sur sa consonne : bârid."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e14', 'ar', 'ar.l24', 'ar.g24.speed_reading', array['ar.g24.speed_reading','ar.v.maa_eau','ar.v.chams','ar.v.chita','ar.v.nahar','ar.v.ghayma']::text[], 'match', 'lesson', 'Cinq phrases du ciel, lues d''un trait', '{}'::text[], 'Repère les petits mots (فِي, عَلَى), puis les noms, puis les terminaisons. Attention à l''accord : شَمْس est féminin (حَارَّةٌ), مَاء et نَهَار sont masculins (بَارِدٌ, حَارٌّ).', 3, '{"id": "ar.l24.e14", "unitIds": ["ar.g24.speed_reading", "ar.v.maa_eau", "ar.v.chams", "ar.v.chita", "ar.v.nahar", "ar.v.ghayma"], "type": "match", "difficulty": 3, "instruction": "Associe chaque phrase à sa traduction.", "prompt": "Cinq phrases du ciel, lues d''un trait", "promptLanguage": "fr", "pairs": [{"left": "الْمَاءُ بَارِدٌ", "right": "L''eau est froide."}, {"left": "الشَّمْسُ حَارَّةٌ", "right": "Le soleil est chaud."}, {"left": "الثَّلْجُ فِي الشِّتَاءِ", "right": "La neige est en hiver."}, {"left": "النَّهَارُ حَارٌّ فِي الصَّيْفِ", "right": "Le jour est chaud en été."}, {"left": "الْغَيْمَةُ عَلَى الْجَبَلِ", "right": "Le nuage est sur la montagne."}], "answer": "الْمَاءُ بَارِدٌ = L''eau est froide. ; الشَّمْسُ حَارَّةٌ = Le soleil est chaud. ; الثَّلْجُ فِي الشِّتَاءِ = La neige est en hiver. ; النَّهَارُ حَارٌّ فِي الصَّيْفِ = Le jour est chaud en été. ; الْغَيْمَةُ عَلَى الْجَبَلِ = Le nuage est sur la montagne.", "acceptedAnswers": [], "explanation": "Repère les petits mots (فِي, عَلَى), puis les noms, puis les terminaisons. Attention à l''accord : شَمْس est féminin (حَارَّةٌ), مَاء et نَهَار sont masculins (بَارِدٌ, حَارٌّ).", "pool": "lesson", "lessonId": "ar.l24", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e15', 'ar', 'ar.l24', 'ar.g20.long_words_blocks', array['ar.g20.long_words_blocks','ar.v.burtuqal','ar.g24.speed_reading']::text[], 'reorder', 'lesson', 'Reconstitue le mot « l''orange » à partir de ses syllabes', array['بُرْ تُ قَال']::text[], 'De droite à gauche : بُرْ (bur, fermée par le soukoun) + تُ (tu) + قَال (qâl, voyelle longue).', 3, '{"id": "ar.l24.e15", "unitIds": ["ar.g20.long_words_blocks", "ar.v.burtuqal", "ar.g24.speed_reading"], "type": "reorder", "difficulty": 3, "instruction": "Remets les syllabes dans l''ordre pour lire « l''orange ».", "prompt": "Reconstitue le mot « l''orange » à partir de ses syllabes", "promptLanguage": "fr", "tokens": ["قَال", "بُرْ", "تُ"], "answer": "بُرْ تُ قَال", "acceptedAnswers": ["بُرْ تُ قَال"], "explanation": "De droite à gauche : بُرْ (bur, fermée par le soukoun) + تُ (tu) + قَال (qâl, voyelle longue).", "tip": "Le soukoun ferme la syllabe : repère بُرْ.", "extraExample": {"text": "مُسْتَشْفَى", "translation": "l''hôpital : مُسْ + تَشْ + فَى", "transliteration": "mustachfâ"}, "pool": "lesson", "lessonId": "ar.l24", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e16', 'ar', 'ar.l24', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.nadjm','ar.v.layl','ar.v.fi']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : les étoiles / dans / la nuit', array['النُّجُومُ فِي اللَّيْلِ']::text[], 'Sujet (النُّجُومُ, le pluriel de نَجْم), puis فِي et le nom en kasra (اللَّيْلِ). Pas de verbe « être ».', 3, '{"id": "ar.l24.e16", "unitIds": ["ar.g23.short_sentences", "ar.v.nadjm", "ar.v.layl", "ar.v.fi"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Les étoiles sont dans la nuit. »", "prompt": "Remets dans l''ordre : les étoiles / dans / la nuit", "promptLanguage": "fr", "tokens": ["اللَّيْلِ", "فِي", "النُّجُومُ"], "answer": "النُّجُومُ فِي اللَّيْلِ", "acceptedAnswers": ["النُّجُومُ فِي اللَّيْلِ"], "explanation": "Sujet (النُّجُومُ, le pluriel de نَجْم), puis فِي et le nom en kasra (اللَّيْلِ). Pas de verbe « être ».", "tip": "Sujet, فِي, puis le moment ou le lieu.", "extraExample": {"text": "الْقَمَرُ فِي اللَّيْلِ", "translation": "La lune est dans la nuit.", "transliteration": "al-qamaru fî l-layl"}, "pool": "lesson", "lessonId": "ar.l24", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e17', 'ar', 'ar.l24', 'ar.g23.short_sentences', array['ar.g23.short_sentences','ar.v.layl','ar.v.nahar','ar.v.chams','ar.v.qamar']::text[], 'fill_blank', 'lesson', 'الشَّمْسُ فِي النَّهَارِ وَالْقَمَرُ فِي ___', array['اللَّيْلِ']::text[], 'Le soleil est dans le jour (النَّهَار), la lune dans la nuit (اللَّيْل). Après فِي, le nom prend une kasra : اللَّيْلِ.', 3, '{"id": "ar.l24.e17", "unitIds": ["ar.g23.short_sentences", "ar.v.layl", "ar.v.nahar", "ar.v.chams", "ar.v.qamar"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Le soleil le jour et la lune la nuit. »", "prompt": "الشَّمْسُ فِي النَّهَارِ وَالْقَمَرُ فِي ___", "promptLanguage": "ar", "options": ["اللَّيْلِ", "النَّهَارِ", "الشِّتَاءِ"], "answer": "اللَّيْلِ", "acceptedAnswers": ["اللَّيْلِ"], "explanation": "Le soleil est dans le jour (النَّهَار), la lune dans la nuit (اللَّيْل). Après فِي, le nom prend une kasra : اللَّيْلِ.", "tip": "Le contraire de نَهَار est لَيْل.", "extraExample": {"text": "شَرِبَ الشَّايَ فِي اللَّيْلِ", "translation": "Il a bu le thé la nuit.", "transliteration": "chariba ch-châya fî l-layl"}, "errorPatterns": [{"equals": "النَّهَارِ", "category": "word_confusion", "feedback": "Le soleil est déjà dans النَّهَار (le jour) ; la lune est dans la nuit."}, {"equals": "الشِّتَاءِ", "category": "word_confusion", "feedback": "الشِّتَاء est l''hiver, une saison, pas un moment de la journée."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e18', 'ar', 'ar.l24', 'ar.v.chariba', array['ar.v.chariba','ar.g24.speed_reading','ar.v.chay','ar.v.chita']::text[], 'translation', 'lesson', 'شَرِبَ الشَّايَ فِي الشِّتَاءِ', array['Il a bu du thé en hiver.','Il a bu le thé en hiver.','Il a bu le thé dans l''hiver.','Il a bu du thé pendant l''hiver.']::text[], 'شَرِبَ = il a bu ; الشَّايَ = le thé ; فِي الشِّتَاءِ = en hiver (mot à mot : dans l''hiver). Attention à la hamza finale de الشِّتَاء.', 3, '{"id": "ar.l24.e18", "unitIds": ["ar.v.chariba", "ar.g24.speed_reading", "ar.v.chay", "ar.v.chita"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "شَرِبَ الشَّايَ فِي الشِّتَاءِ", "promptLanguage": "ar", "answer": "Il a bu du thé en hiver.", "acceptedAnswers": ["Il a bu du thé en hiver.", "Il a bu le thé en hiver.", "Il a bu le thé dans l''hiver.", "Il a bu du thé pendant l''hiver."], "explanation": "شَرِبَ = il a bu ; الشَّايَ = le thé ; فِي الشِّتَاءِ = en hiver (mot à mot : dans l''hiver). Attention à la hamza finale de الشِّتَاء.", "tip": "Verbe, objet, moment : lis d''abord le petit mot فِي.", "extraExample": {"text": "شَرِبَ الْقَهْوَةَ فِي الصَّبَاحِ", "translation": "Il a bu le café le matin.", "transliteration": "chariba l-qahwata fî S-Sabâ7"}, "errorPatterns": [{"contains": "eau", "category": "vocabulary", "feedback": "L''eau se dit مَاء ; ici الشَّاي est le thé."}, {"contains": "été", "category": "word_confusion", "feedback": "الصَّيْف est l''été ; الشِّتَاء est l''hiver."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e19', 'ar', 'ar.l24', 'ar.g24.speed_reading', array['ar.g24.speed_reading','ar.v.chams']::text[], 'free_answer', 'lesson', 'Comment se lit شَمْس ?', array['chams','shams']::text[], 'شَ = cha (ش : trois points), مْ = m (soukoun), س = s : chams, « le soleil ». Le soukoun sur م ferme la syllabe : une seule syllabe.', 3, '{"id": "ar.l24.e19", "unitIds": ["ar.g24.speed_reading", "ar.v.chams"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture de ce mot en lettres latines.", "prompt": "Comment se lit شَمْس ?", "promptLanguage": "fr", "answer": "chams", "acceptedAnswers": ["chams", "shams"], "hint": "ش a trois points.", "explanation": "شَ = cha (ش : trois points), مْ = m (soukoun), س = s : chams, « le soleil ». Le soukoun sur م ferme la syllabe : une seule syllabe.", "tip": "ش = ch ; le soukoun sur م empêche d''ajouter un a : chams, pas chamas.", "extraExample": {"text": "الشَّمْسُ جَمِيلَةٌ فِي الصَّبَاحِ", "translation": "Le soleil est beau le matin.", "transliteration": "ach-chamsu djamîlatun fî S-Sabâ7"}, "errorPatterns": [{"equals": "chamas", "category": "spelling", "feedback": "Le soukoun sur م supprime la voyelle : chams, une seule syllabe."}, {"equals": "sams", "category": "spelling", "feedback": "ش a trois points : ch, pas s."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e20', 'ar', 'ar.l24', 'ar.g24.speed_reading', array['ar.g24.speed_reading','ar.v.kana','ar.v.maa_eau','ar.v.layl','ar.v.barid']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : était / l''eau / froide / la nuit', array['كَانَ الْمَاءُ بَارِدًا فِي اللَّيْلِ','فِي اللَّيْلِ كَانَ الْمَاءُ بَارِدًا']::text[], 'كَانَ ouvre la phrase, puis le sujet (الْمَاءُ), puis l''adjectif en -an (بَارِدًا), puis le moment (فِي اللَّيْلِ). On peut aussi commencer par فِي اللَّيْلِ.', 4, '{"id": "ar.l24.e20", "unitIds": ["ar.g24.speed_reading", "ar.v.kana", "ar.v.maa_eau", "ar.v.layl", "ar.v.barid"], "type": "reorder", "difficulty": 4, "instruction": "Remets les mots dans l''ordre : « L''eau était froide la nuit. »", "prompt": "Remets dans l''ordre : était / l''eau / froide / la nuit", "promptLanguage": "fr", "tokens": ["اللَّيْلِ", "فِي", "بَارِدًا", "الْمَاءُ", "كَانَ"], "answer": "كَانَ الْمَاءُ بَارِدًا فِي اللَّيْلِ", "acceptedAnswers": ["كَانَ الْمَاءُ بَارِدًا فِي اللَّيْلِ", "فِي اللَّيْلِ كَانَ الْمَاءُ بَارِدًا"], "explanation": "كَانَ ouvre la phrase, puis le sujet (الْمَاءُ), puis l''adjectif en -an (بَارِدًا), puis le moment (فِي اللَّيْلِ). On peut aussi commencer par فِي اللَّيْلِ.", "tip": "كَانَ, sujet, adjectif en -an, moment.", "extraExample": {"text": "كَانَ الشِّتَاءُ بَارِدًا", "translation": "L''hiver était froid.", "transliteration": "kâna ch-chitâ''u bâridan"}, "pool": "lesson", "lessonId": "ar.l24", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e21', 'ar', 'ar.l24', 'ar.g24.speed_reading', array['ar.g24.speed_reading','ar.v.ghayma','ar.v.hadhihi','ar.v.kabir','ar.v.ala']::text[], 'translation', 'lesson', 'هٰذِهِ غَيْمَةٌ كَبِيرَةٌ عَلَى الْجَبَلِ', array['C''est un gros nuage sur la montagne.','C''est un grand nuage sur la montagne.','Voici un gros nuage sur la montagne.','Voici un grand nuage sur la montagne.']::text[], 'هٰذِهِ = ceci (féminin) ; غَيْمَةٌ كَبِيرَةٌ = un gros nuage ; عَلَى الْجَبَلِ = sur la montagne. Lis d''abord les petits mots (هٰذِهِ, عَلَى), puis les noms.', 4, '{"id": "ar.l24.e21", "unitIds": ["ar.g24.speed_reading", "ar.v.ghayma", "ar.v.hadhihi", "ar.v.kabir", "ar.v.ala"], "type": "translation", "difficulty": 4, "instruction": "Traduis en français.", "prompt": "هٰذِهِ غَيْمَةٌ كَبِيرَةٌ عَلَى الْجَبَلِ", "promptLanguage": "ar", "answer": "C''est un gros nuage sur la montagne.", "acceptedAnswers": ["C''est un gros nuage sur la montagne.", "C''est un grand nuage sur la montagne.", "Voici un gros nuage sur la montagne.", "Voici un grand nuage sur la montagne."], "explanation": "هٰذِهِ = ceci (féminin) ; غَيْمَةٌ كَبِيرَةٌ = un gros nuage ; عَلَى الْجَبَلِ = sur la montagne. Lis d''abord les petits mots (هٰذِهِ, عَلَى), puis les noms.", "tip": "Petits mots, noms, terminaisons : la méthode de tout le module.", "extraExample": {"text": "هٰذَا جَبَلٌ كَبِيرٌ", "translation": "C''est une grande montagne.", "transliteration": "hâdhâ djabalun kabîr"}, "errorPatterns": [{"contains": "pluie", "category": "vocabulary", "feedback": "غَيْمَة est le nuage ; la pluie se dit مَطَر."}, {"contains": "mer", "category": "vocabulary", "feedback": "جَبَل est la montagne ; la mer se dit بَحْر."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l24.e22', 'ar', 'ar.l24', 'ar.g24.speed_reading', array['ar.g24.speed_reading','ar.v.ghayma']::text[], 'free_answer', 'lesson', 'Comment se lit غَيْمَة ?', array['ghayma','ghaima']::text[], 'غَيْ = ghay (غ : un point au-dessus ; ي avec soukoun = ay), مَة = ma : ghay-ma, « le nuage ». Vite, mais sans oublier le point.', 4, '{"id": "ar.l24.e22", "unitIds": ["ar.g24.speed_reading", "ar.v.ghayma"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la lecture de ce mot en lettres latines.", "prompt": "Comment se lit غَيْمَة ?", "promptLanguage": "fr", "answer": "ghayma", "acceptedAnswers": ["ghayma", "ghaima"], "hint": "Le point change la lettre : gh.", "explanation": "غَيْ = ghay (غ : un point au-dessus ; ي avec soukoun = ay), مَة = ma : ghay-ma, « le nuage ». Vite, mais sans oublier le point.", "tip": "Un point au-dessus de ع en fait un غ : gh.", "extraExample": {"text": "هٰذِهِ غَيْمَةٌ كَبِيرَةٌ", "translation": "C''est un gros nuage.", "transliteration": "hâdhihi ghaymatun kabîra"}, "errorPatterns": [{"equals": "3ayma", "category": "spelling", "feedback": "Le point au-dessus fait de ع un غ (gh). Aller vite ne veut pas dire oublier les points."}, {"equals": "ghayama", "category": "spelling", "feedback": "Le soukoun sur ي ferme la syllabe : ghay-ma, pas gha-ya-ma."}], "pool": "lesson", "lessonId": "ar.l24", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e01', 'ar', 'ar.l25', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.rabb']::text[], 'mcq', 'lesson', 'الرَّبّ', array['ar-rabb']::text[], 'ر est une lettre solaire : le ل ne se dit pas et le ر est doublé. Le ب porte lui aussi une chadda (rabb). On lit ar-rabb, « le Seigneur ».', 1, '{"id": "ar.l25.e01", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.rabb"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "الرَّبّ", "promptLanguage": "ar", "options": ["ar-rabb", "al-rabb", "ar-rab", "ad-rabb"], "answer": "ar-rabb", "acceptedAnswers": ["ar-rabb"], "hint": "Regarde la chadda juste après ال.", "explanation": "ر est une lettre solaire : le ل ne se dit pas et le ر est doublé. Le ب porte lui aussi une chadda (rabb). On lit ar-rabb, « le Seigneur ».", "tip": "Une chadda juste après ال : on ne dit pas le l.", "extraExample": {"text": "الرَّبُّ مَعَنَا", "translation": "Le Seigneur est avec nous.", "transliteration": "ar-rabbu ma3anâ"}, "errorPatterns": [{"equals": "al-rabb", "category": "grammar", "feedback": "ر est solaire : après ال, la chadda double le ر et le l disparaît. On dit ar-rabb."}, {"equals": "ar-rab", "category": "spelling", "feedback": "Le ب porte aussi une chadda : il est doublé, rabb et non rab."}, {"equals": "ad-rabb", "category": "spelling", "feedback": "Après ال, on double la lettre qui suit (ر), pas une autre."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e02', 'ar', 'ar.l25', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.masih']::text[], 'mcq', 'lesson', 'الْمَسِيح', array['al-masî7']::text[], 'م est une lettre lunaire : le ل porte un soukoun et on dit le l. La kasra suivie de ي donne un î long ; le ح (sans point) se note 7. On lit al-masî7, « le Christ ».', 1, '{"id": "ar.l25.e02", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.masih"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "الْمَسِيح", "promptLanguage": "ar", "options": ["al-masî7", "am-masî7", "al-masi7", "al-mâsî7"], "answer": "al-masî7", "acceptedAnswers": ["al-masî7"], "explanation": "م est une lettre lunaire : le ل porte un soukoun et on dit le l. La kasra suivie de ي donne un î long ; le ح (sans point) se note 7. On lit al-masî7, « le Christ ».", "tip": "Soukoun sur le ل : je dis le l.", "extraExample": {"text": "يَسُوعُ الْمَسِيحُ", "translation": "Jésus-Christ", "transliteration": "yasû3u l-masî7"}, "errorPatterns": [{"equals": "am-masî7", "category": "grammar", "feedback": "م est lunaire : le ل a un soukoun et se prononce. Le l ne s''assimile qu''aux lettres solaires."}, {"equals": "al-masi7", "category": "spelling", "feedback": "Kasra + ي = î long : masî7, pas masi7."}, {"equals": "al-mâsî7", "category": "spelling", "feedback": "Après م, il y a une fatha sans ا : le a est bref."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e03', 'ar', 'ar.l25', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.allah','ar.v.rabb','ar.v.yasu','ar.v.masih','ar.v.al_ab']::text[], 'match', 'lesson', 'Cinq noms du Credo', '{}'::text[], 'Ce sont les noms que tu entends au début du Credo. الرَّبّ est un titre (« le Seigneur »), الْمَسِيح aussi (« le Christ ») ; يَسُوع est le nom propre.', 1, '{"id": "ar.l25.e03", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.allah", "ar.v.rabb", "ar.v.yasu", "ar.v.masih", "ar.v.al_ab"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Cinq noms du Credo", "promptLanguage": "fr", "pairs": [{"left": "اللّٰه", "right": "Dieu"}, {"left": "الرَّبّ", "right": "le Seigneur"}, {"left": "يَسُوع", "right": "Jésus"}, {"left": "الْمَسِيح", "right": "le Christ"}, {"left": "الْآب", "right": "le Père"}], "answer": "اللّٰه = Dieu ; الرَّبّ = le Seigneur ; يَسُوع = Jésus ; الْمَسِيح = le Christ ; الْآب = le Père", "acceptedAnswers": [], "explanation": "Ce sont les noms que tu entends au début du Credo. الرَّبّ est un titre (« le Seigneur »), الْمَسِيح aussi (« le Christ ») ; يَسُوع est le nom propre.", "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e04', 'ar', 'ar.l25', 'ar.v.yasu', array['ar.v.yasu','ar.g25.al_solaire_lunaire']::text[], 'mcq', 'lesson', 'يَسُوع', array['Jésus']::text[], 'يَسُوع (ya-sû-3) est Jésus. Les autres noms s''écrivent autrement : يُوسُف (Joseph), يُوحَنَّا (Jean), يَعْقُوب (Jacques).', 1, '{"id": "ar.l25.e04", "unitIds": ["ar.v.yasu", "ar.g25.al_solaire_lunaire"], "type": "mcq", "difficulty": 1, "instruction": "Que veut dire ce mot ?", "prompt": "يَسُوع", "promptLanguage": "ar", "options": ["Jésus", "Joseph", "Jean", "Jacques"], "answer": "Jésus", "acceptedAnswers": ["Jésus"], "explanation": "يَسُوع (ya-sû-3) est Jésus. Les autres noms s''écrivent autrement : يُوسُف (Joseph), يُوحَنَّا (Jean), يَعْقُوب (Jacques).", "tip": "Le ع final de يَسُوع est la signature du mot.", "extraExample": {"text": "يَسُوعُ هُوَ الرَّبُّ", "translation": "Jésus est le Seigneur.", "transliteration": "yasû3u huwa r-rabb"}, "errorPatterns": [{"equals": "Joseph", "category": "vocabulary", "feedback": "Joseph s''écrit يُوسُف (yûsuf) : il finit par ف, pas par ع."}, {"equals": "Jean", "category": "vocabulary", "feedback": "Jean s''écrit يُوحَنَّا (yûhannâ) : il y a une chadda et un ا final."}, {"equals": "Jacques", "category": "vocabulary", "feedback": "Jacques s''écrit يَعْقُوب (ya3qûb) : il contient un ق et finit par ب."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e05', 'ar', 'ar.l25', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.al_ab','ar.v.rabb','ar.v.allah','ar.v.thaluth']::text[], 'mcq', 'lesson', 'Un seul de ces mots garde le l de l''article. Lequel ?', array['الْآب']::text[], 'Dans الْآب, le ل porte un soukoun (lunaire) : on dit al-âb. Dans les trois autres, une chadda suit ال (ر, ل, ث sont solaires) : le l ne se dit pas, on lit ar-rabb, Allâh, ath-thâlûth.', 2, '{"id": "ar.l25.e05", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.al_ab", "ar.v.rabb", "ar.v.allah", "ar.v.thaluth"], "type": "mcq", "difficulty": 2, "instruction": "Observe le signe qui suit ال.", "prompt": "Un seul de ces mots garde le l de l''article. Lequel ?", "promptLanguage": "fr", "options": ["الْآب", "الرَّبّ", "اللّٰه", "الثَّالُوث"], "answer": "الْآب", "acceptedAnswers": ["الْآب"], "explanation": "Dans الْآب, le ل porte un soukoun (lunaire) : on dit al-âb. Dans les trois autres, une chadda suit ال (ر, ل, ث sont solaires) : le l ne se dit pas, on lit ar-rabb, Allâh, ath-thâlûth.", "tip": "Soukoun : je dis le l. Chadda : je ne le dis pas.", "extraExample": {"text": "الْآبُ وَالاِبْنُ", "translation": "le Père et le Fils", "transliteration": "al-âbu wa-l-ibn"}, "errorPatterns": [{"equals": "الرَّبّ", "category": "grammar", "feedback": "ر est solaire : la chadda double le ر, on lit ar-rabb sans le l."}, {"equals": "اللّٰه", "category": "grammar", "feedback": "Le ل d''Allah est solaire : on lit Allâh, avec un l doublé."}, {"equals": "الثَّالُوث", "category": "grammar", "feedback": "ث est solaire : on lit ath-thâlûth, sans le l."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e06', 'ar', 'ar.l25', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.ruh_al_qudus']::text[], 'mcq', 'lesson', 'الرُّوح الْقُدُس', array['ar-rû7 al-qudus']::text[], 'Dans ce groupe, un mot est solaire et l''autre lunaire : ر est solaire (ar-rû7, le l tombe) et ق est lunaire (al-qudus, le l reste). La damma suivie de و donne un û long.', 2, '{"id": "ar.l25.e06", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.ruh_al_qudus"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quelle est la bonne lecture ?", "prompt": "الرُّوح الْقُدُس", "promptLanguage": "ar", "options": ["ar-rû7 al-qudus", "al-rû7 al-qudus", "ar-rû7 aq-qudus", "ar-ru7 al-qudus"], "answer": "ar-rû7 al-qudus", "acceptedAnswers": ["ar-rû7 al-qudus"], "explanation": "Dans ce groupe, un mot est solaire et l''autre lunaire : ر est solaire (ar-rû7, le l tombe) et ق est lunaire (al-qudus, le l reste). La damma suivie de و donne un û long.", "tip": "Lis chaque ال séparément : chadda ou soukoun ?", "extraExample": {"text": "بِاسْمِ الرُّوحِ الْقُدُسِ", "translation": "au nom du Saint-Esprit", "transliteration": "bismi r-rû7i l-qudus"}, "errorPatterns": [{"equals": "al-rû7 al-qudus", "category": "grammar", "feedback": "ر est solaire : on dit ar-rû7, sans le l."}, {"equals": "ar-rû7 aq-qudus", "category": "grammar", "feedback": "ق est lunaire : son ل porte un soukoun et se dit, al-qudus."}, {"equals": "ar-ru7 al-qudus", "category": "spelling", "feedback": "Damma + و = û long : rû7."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e07', 'ar', 'ar.l25', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.thaluth']::text[], 'mcq', 'lesson', 'الثَّالُوث', array['ath-thâlûth']::text[], 'ث est solaire : le l disparaît et le th est doublé. ثَا = thâ (fatha + ا) et لُو = lû (damma + و) : deux voyelles longues. On lit ath-thâlûth, « la Trinité ».', 2, '{"id": "ar.l25.e07", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.thaluth"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "الثَّالُوث", "promptLanguage": "ar", "options": ["ath-thâlûth", "al-thâlûth", "at-thâlûth", "ath-thalûth"], "answer": "ath-thâlûth", "acceptedAnswers": ["ath-thâlûth"], "explanation": "ث est solaire : le l disparaît et le th est doublé. ثَا = thâ (fatha + ا) et لُو = lû (damma + و) : deux voyelles longues. On lit ath-thâlûth, « la Trinité ».", "tip": "Trois voyelles à lire : a long, û long, puis la consonne finale.", "extraExample": {"text": "الثَّالُوثُ الْقُدُّوسُ", "translation": "la Sainte Trinité", "transliteration": "ath-thâlûthu l-quddûs"}, "errorPatterns": [{"equals": "al-thâlûth", "category": "grammar", "feedback": "ث est solaire : on double le th et on ne dit pas le l."}, {"equals": "at-thâlûth", "category": "spelling", "feedback": "ث (trois points) se note th, pas t."}, {"equals": "ath-thalûth", "category": "spelling", "feedback": "Après ثَ il y a un ا : le a est long, thâ."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e08', 'ar', 'ar.l25', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.rabb','ar.v.masih','ar.v.al_ab','ar.v.allah','ar.v.thaluth']::text[], 'match', 'lesson', 'Lis chaque mot d''un coup', '{}'::text[], 'Trois mots solaires (ar-rabb, Allâh, ath-thâlûth) et deux lunaires (al-masî7, al-âb). Le signe qui décide, c''est la chadda ou le soukoun.', 2, '{"id": "ar.l25.e08", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.rabb", "ar.v.masih", "ar.v.al_ab", "ar.v.allah", "ar.v.thaluth"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lis chaque mot d''un coup", "promptLanguage": "fr", "pairs": [{"left": "الرَّبّ", "right": "ar-rabb"}, {"left": "الْمَسِيح", "right": "al-masî7"}, {"left": "الْآب", "right": "al-âb"}, {"left": "اللّٰه", "right": "Allâh"}, {"left": "الثَّالُوث", "right": "ath-thâlûth"}], "answer": "الرَّبّ = ar-rabb ; الْمَسِيح = al-masî7 ; الْآب = al-âb ; اللّٰه = Allâh ; الثَّالُوث = ath-thâlûth", "acceptedAnswers": [], "explanation": "Trois mots solaires (ar-rabb, Allâh, ath-thâlûth) et deux lunaires (al-masî7, al-âb). Le signe qui décide, c''est la chadda ou le soukoun.", "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e09', 'ar', 'ar.l25', 'ar.g14.hamza_madda', array['ar.g14.hamza_madda','ar.g25.al_solaire_lunaire','ar.v.al_ab']::text[], 'mcq', 'lesson', 'الْآب', array['al-âb']::text[], 'Révision de la leçon 14 : آ est un alif madda, une hamza suivie d''un â long. Le ل porte un soukoun, on dit donc al-. Résultat : al-âb, « le Père ».', 3, '{"id": "ar.l25.e09", "unitIds": ["ar.g14.hamza_madda", "ar.g25.al_solaire_lunaire", "ar.v.al_ab"], "type": "mcq", "difficulty": 3, "instruction": "Comment lit-on ce mot ?", "prompt": "الْآب", "promptLanguage": "ar", "options": ["al-âb", "al-ab", "a-âb", "al-abb"], "answer": "al-âb", "acceptedAnswers": ["al-âb"], "explanation": "Révision de la leçon 14 : آ est un alif madda, une hamza suivie d''un â long. Le ل porte un soukoun, on dit donc al-. Résultat : al-âb, « le Père ».", "tip": "La madda (~) sur l''alif = â long.", "extraExample": {"text": "آبَاء", "translation": "pères", "transliteration": "âbâ''"}, "errorPatterns": [{"equals": "al-ab", "category": "spelling", "feedback": "Sans madda, أَب se lit ab (a bref). Ici la madda allonge : â."}, {"equals": "a-âb", "category": "grammar", "feedback": "Le ل a un soukoun : le l se prononce, al-âb."}, {"equals": "al-abb", "category": "spelling", "feedback": "Le ب ne porte pas de chadda : b simple."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e10', 'ar', 'ar.l25', 'ar.g12.shadda', array['ar.g12.shadda','ar.g25.al_solaire_lunaire','ar.v.rabb']::text[], 'mcq', 'lesson', 'Combien de consonnes doublées entends-tu dans الرَّبّ ?', array['Deux : rr et bb']::text[], 'Dans ar-rabb, la première chadda double le ر (article solaire) et la seconde double le ب (c''est le mot rabb lui-même). Chaque chadda se prononce.', 3, '{"id": "ar.l25.e10", "unitIds": ["ar.g12.shadda", "ar.g25.al_solaire_lunaire", "ar.v.rabb"], "type": "mcq", "difficulty": 3, "instruction": "Compte les chaddas.", "prompt": "Combien de consonnes doublées entends-tu dans الرَّبّ ?", "promptLanguage": "fr", "options": ["Deux : rr et bb", "Une seule : rr", "Une seule : bb", "Aucune"], "answer": "Deux : rr et bb", "acceptedAnswers": ["Deux : rr et bb"], "explanation": "Dans ar-rabb, la première chadda double le ر (article solaire) et la seconde double le ب (c''est le mot rabb lui-même). Chaque chadda se prononce.", "tip": "Une chadda = une consonne doublée.", "extraExample": {"text": "الشَّمْس", "translation": "le soleil : une seule chadda, ach-chams", "transliteration": "ach-chams"}, "errorPatterns": [{"equals": "Une seule : rr", "category": "grammar", "feedback": "Regarde la fin du mot : le ب porte aussi une chadda (rabb)."}, {"equals": "Une seule : bb", "category": "grammar", "feedback": "Le ر porte lui aussi une chadda : l''article solaire double sa lettre."}, {"equals": "Aucune", "category": "grammar", "feedback": "Les deux chaddas sont là : ر et ب sont doublés."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e11', 'ar', 'ar.l25', 'ar.v.ibn', array['ar.v.ibn','ar.g25.al_solaire_lunaire','ar.v.bismi']::text[], 'fill_blank', 'lesson', 'بِاسْمِ الْآبِ ___ وَالرُّوحِ الْقُدُسِ', array['وَالاِبْنِ']::text[], '« Et du Fils » se dit وَالاِبْنِ : وَ (et) + الاِبْن (le Fils). Tu connais اِبْن depuis la leçon 10. Le ا de اِبْن ne se dit pas : wa-l-ibni.', 2, '{"id": "ar.l25.e11", "unitIds": ["ar.v.ibn", "ar.g25.al_solaire_lunaire", "ar.v.bismi"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la formule : « Au nom du Père, du Fils et du Saint-Esprit ».", "prompt": "بِاسْمِ الْآبِ ___ وَالرُّوحِ الْقُدُسِ", "promptLanguage": "ar", "options": ["وَالاِبْنِ", "وَالرَّبِّ", "وَالثَّالُوثِ"], "answer": "وَالاِبْنِ", "acceptedAnswers": ["وَالاِبْنِ"], "explanation": "« Et du Fils » se dit وَالاِبْنِ : وَ (et) + الاِبْن (le Fils). Tu connais اِبْن depuis la leçon 10. Le ا de اِبْن ne se dit pas : wa-l-ibni.", "tip": "Père, Fils, Saint-Esprit : l''ordre ne change jamais.", "extraExample": {"text": "بِاسْمِ الْآبِ وَالاِبْنِ", "translation": "au nom du Père et du Fils", "transliteration": "bismi l-âbi wa-l-ibn"}, "errorPatterns": [{"equals": "وَالرَّبِّ", "category": "vocabulary", "feedback": "الرَّبّ est le Seigneur. La formule nomme le Fils : الاِبْن."}, {"equals": "وَالثَّالُوثِ", "category": "vocabulary", "feedback": "الثَّالُوث est la Trinité entière : on cite ici les personnes une par une."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e12', 'ar', 'ar.l25', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.yasu','ar.v.masih']::text[], 'fill_blank', 'lesson', 'يَسُوعُ ___', array['الْمَسِيحُ']::text[], '« Jésus-Christ » se dit يَسُوعُ الْمَسِيحُ : le titre « le Christ » suit le nom. م est lunaire, donc al-masî7.', 2, '{"id": "ar.l25.e12", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.yasu", "ar.v.masih"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « Jésus-Christ ».", "prompt": "يَسُوعُ ___", "promptLanguage": "ar", "options": ["الْمَسِيحُ", "الثَّالُوثُ", "الْآبُ"], "answer": "الْمَسِيحُ", "acceptedAnswers": ["الْمَسِيحُ"], "explanation": "« Jésus-Christ » se dit يَسُوعُ الْمَسِيحُ : le titre « le Christ » suit le nom. م est lunaire, donc al-masî7.", "tip": "Christ en arabe : masî7.", "extraExample": {"text": "يَسُوعُ الْمَسِيحُ هُوَ الرَّبُّ", "translation": "Jésus-Christ est le Seigneur.", "transliteration": "yasû3u l-masî7u huwa r-rabb"}, "errorPatterns": [{"equals": "الْآبُ", "category": "vocabulary", "feedback": "الْآب est le Père. Jésus-Christ est le Fils."}, {"equals": "الثَّالُوثُ", "category": "vocabulary", "feedback": "الثَّالُوث est la Trinité, pas un titre de Jésus."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e13', 'ar', 'ar.l25', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.rabb']::text[], 'fill_blank', 'lesson', 'الرَّبّ = ___-rabb', array['ar']::text[], 'ر est solaire : le ل de l''article ne se dit pas, il prend le son de la lettre qui suit. On lit donc ar-rabb.', 3, '{"id": "ar.l25.e13", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.rabb"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la lecture du mot الرَّبّ.", "prompt": "الرَّبّ = ___-rabb", "promptLanguage": "fr", "options": ["ar", "al", "ad"], "answer": "ar", "acceptedAnswers": ["ar"], "explanation": "ر est solaire : le ل de l''article ne se dit pas, il prend le son de la lettre qui suit. On lit donc ar-rabb.", "tip": "Lettre solaire : ال devient a + la lettre doublée.", "extraExample": {"text": "الرُّوح", "translation": "l''esprit", "transliteration": "ar-rû7"}, "errorPatterns": [{"equals": "al", "category": "grammar", "feedback": "Ce serait lunaire. Ici, la chadda sur ر montre qu''on ne dit pas le l."}, {"equals": "ad", "category": "spelling", "feedback": "Le son vient de la lettre suivante (ر), pas de د."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e14', 'ar', 'ar.l25', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.al_ab','ar.v.ibn','ar.v.ruh_al_qudus','ar.v.thaluth']::text[], 'match', 'lesson', 'Les trois Personnes et le tout', '{}'::text[], 'La Trinité (الثَّالُوث) est le nom des trois Personnes ensemble : le Père, le Fils et le Saint-Esprit. Remarque الاِبْن : c''est اِبْن (leçon 10) avec ال.', 3, '{"id": "ar.l25.e14", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.al_ab", "ar.v.ibn", "ar.v.ruh_al_qudus", "ar.v.thaluth"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à son sens.", "prompt": "Les trois Personnes et le tout", "promptLanguage": "fr", "pairs": [{"left": "الْآب", "right": "le Père"}, {"left": "الاِبْن", "right": "le Fils"}, {"left": "الرُّوح الْقُدُس", "right": "le Saint-Esprit"}, {"left": "الثَّالُوث", "right": "la Trinité"}], "answer": "الْآب = le Père ; الاِبْن = le Fils ; الرُّوح الْقُدُس = le Saint-Esprit ; الثَّالُوث = la Trinité", "acceptedAnswers": [], "explanation": "La Trinité (الثَّالُوث) est le nom des trois Personnes ensemble : le Père, le Fils et le Saint-Esprit. Remarque الاِبْن : c''est اِبْن (leçon 10) avec ال.", "pool": "lesson", "lessonId": "ar.l25", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e15', 'ar', 'ar.l25', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.bismi','ar.v.al_ab','ar.v.ibn','ar.v.ruh_al_qudus']::text[], 'reorder', 'lesson', 'Remets dans l''ordre la formule qui ouvre la prière', array['بِاسْمِ الْآبِ وَالاِبْنِ وَالرُّوحِ الْقُدُسِ']::text[], 'La formule commence par بِاسْمِ (au nom de), puis nomme le Père, le Fils et le Saint-Esprit, chacun relié par وَ. Chaque nom se termine par une kasra.', 3, '{"id": "ar.l25.e15", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.bismi", "ar.v.al_ab", "ar.v.ibn", "ar.v.ruh_al_qudus"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Au nom du Père, du Fils et du Saint-Esprit ».", "prompt": "Remets dans l''ordre la formule qui ouvre la prière", "promptLanguage": "fr", "tokens": ["وَالرُّوحِ", "بِاسْمِ", "الْقُدُسِ", "وَالاِبْنِ", "الْآبِ"], "answer": "بِاسْمِ الْآبِ وَالاِبْنِ وَالرُّوحِ الْقُدُسِ", "acceptedAnswers": ["بِاسْمِ الْآبِ وَالاِبْنِ وَالرُّوحِ الْقُدُسِ"], "explanation": "La formule commence par بِاسْمِ (au nom de), puis nomme le Père, le Fils et le Saint-Esprit, chacun relié par وَ. Chaque nom se termine par une kasra.", "tip": "Père, Fils, Esprit : récite-la dans l''ordre.", "extraExample": {"text": "بِاسْمِ الرَّبِّ يَسُوعَ الْمَسِيحِ", "translation": "au nom du Seigneur Jésus-Christ", "transliteration": "bismi r-rabbi yasû3a l-masî7i"}, "pool": "lesson", "lessonId": "ar.l25", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e16', 'ar', 'ar.l25', 'ar.v.ibn', array['ar.v.ibn','ar.g25.al_solaire_lunaire','ar.v.yasu','ar.v.masih','ar.v.allah']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : Jésus-Christ / Fils de / Dieu', array['يَسُوعُ الْمَسِيحُ ابْنُ اللّٰهِ']::text[], 'Le nom (يَسُوعُ الْمَسِيحُ) vient d''abord, puis ابْنُ (fils de) et اللّٰهِ (Dieu). Le a de al- tombe après la damma : ibnu llâhi.', 3, '{"id": "ar.l25.e16", "unitIds": ["ar.v.ibn", "ar.g25.al_solaire_lunaire", "ar.v.yasu", "ar.v.masih", "ar.v.allah"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Jésus-Christ, Fils de Dieu ».", "prompt": "Remets dans l''ordre : Jésus-Christ / Fils de / Dieu", "promptLanguage": "fr", "tokens": ["ابْنُ", "اللّٰهِ", "يَسُوعُ", "الْمَسِيحُ"], "answer": "يَسُوعُ الْمَسِيحُ ابْنُ اللّٰهِ", "acceptedAnswers": ["يَسُوعُ الْمَسِيحُ ابْنُ اللّٰهِ"], "explanation": "Le nom (يَسُوعُ الْمَسِيحُ) vient d''abord, puis ابْنُ (fils de) et اللّٰهِ (Dieu). Le a de al- tombe après la damma : ibnu llâhi.", "tip": "ابْنُ + nom = « fils de ».", "extraExample": {"text": "ابْنُ الْإِنْسَانِ", "translation": "le Fils de l''homme", "transliteration": "ibnu l-insân"}, "pool": "lesson", "lessonId": "ar.l25", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e17', 'ar', 'ar.l25', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.al_ab','ar.v.ibn']::text[], 'translation', 'lesson', 'الْآبُ وَالاِبْنُ', array['Le Père et le Fils','Père et Fils']::text[], 'الْآبُ = le Père ; وَ = et, collé au mot suivant ; الاِبْنُ = le Fils.', 2, '{"id": "ar.l25.e17", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.al_ab", "ar.v.ibn"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "الْآبُ وَالاِبْنُ", "promptLanguage": "ar", "answer": "Le Père et le Fils", "acceptedAnswers": ["Le Père et le Fils", "Père et Fils"], "explanation": "الْآبُ = le Père ; وَ = et, collé au mot suivant ; الاِبْنُ = le Fils.", "tip": "وَ se colle toujours au mot qui suit.", "extraExample": {"text": "الرَّبُّ وَالْمَسِيحُ", "translation": "le Seigneur et le Christ", "transliteration": "ar-rabbu wa-l-masî7"}, "errorPatterns": [{"contains": "esprit", "category": "vocabulary", "feedback": "Le Saint-Esprit se dit الرُّوح الْقُدُس. Ici le second mot est الاِبْن, le Fils."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e18', 'ar', 'ar.l25', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.yasu','ar.v.rabb','ar.v.huwa']::text[], 'translation', 'lesson', 'يَسُوعُ هُوَ الرَّبُّ', array['Jésus est le Seigneur.','Jésus, c''est le Seigneur.','C''est Jésus le Seigneur.','Jésus est Seigneur.']::text[], 'يَسُوعُ = Jésus ; هُوَ = il ; الرَّبُّ = le Seigneur. Au présent, l''arabe n''écrit pas « est » : هُوَ en tient lieu.', 3, '{"id": "ar.l25.e18", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.yasu", "ar.v.rabb", "ar.v.huwa"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "يَسُوعُ هُوَ الرَّبُّ", "promptLanguage": "ar", "answer": "Jésus est le Seigneur.", "acceptedAnswers": ["Jésus est le Seigneur.", "Jésus, c''est le Seigneur.", "C''est Jésus le Seigneur.", "Jésus est Seigneur."], "explanation": "يَسُوعُ = Jésus ; هُوَ = il ; الرَّبُّ = le Seigneur. Au présent, l''arabe n''écrit pas « est » : هُوَ en tient lieu.", "tip": "Pas de verbe « être » au présent : هُوَ fait le lien.", "extraExample": {"text": "الْمَسِيحُ هُوَ الرَّبُّ", "translation": "Le Christ est le Seigneur.", "transliteration": "al-masî7u huwa r-rabb"}, "errorPatterns": [{"contains": "dieu", "category": "vocabulary", "feedback": "Dieu se dit اللّٰه. Ici le dernier mot est الرَّبّ, le Seigneur."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e19', 'ar', 'ar.l25', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.ruh_al_qudus']::text[], 'free_answer', 'lesson', 'الرُّوحُ الْقُدُسُ', array['ar-rû7u l-qudus','arrû7u lqudus','ar rû7u l qudus','ar-ru7u l-qudus','arru7u lqudus','ar ru7u l qudus','ar-ruu7u l-qudus','arruu7u lqudus','ar ruu7u l qudus','ar-rû7 al-qudus','arrû7 alqudus','ar rû7 al qudus','ar-ru7 al-qudus','arru7 alqudus','ar ru7 al qudus','ar-ruu7 al-qudus','arruu7 alqudus','ar ruu7 al qudus','ar-rû7u al-qudus','arrû7u alqudus','ar rû7u al qudus','ar-ru7u al-qudus','arru7u alqudus','ar ru7u al qudus','ar-ruu7u al-qudus','arruu7u alqudus','ar ruu7u al qudus','ar-rû7 l-qudus','arrû7 lqudus','ar rû7 l qudus','ar-ru7 l-qudus','arru7 lqudus','ar ru7 l qudus','ar-ruu7 l-qudus','arruu7 lqudus','ar ruu7 l qudus','ar-ruh al-qudus','arruh alqudus','ar ruh al qudus','ar-ruhu l-qudus','arruhu lqudus','ar ruhu l qudus','ar-rûhu l-qudus','arrûhu lqudus','ar rûhu l qudus','ar-ruuhu l-qudus','arruuhu lqudus','ar ruuhu l qudus']::text[], 'الرُّوحُ : ر solaire, donc ar-rû7u (û long). الْقُدُسُ : ق lunaire, donc al-qudus ; après la damma, le a de al- tombe : l-qudus.', 3, '{"id": "ar.l25.e19", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.ruh_al_qudus"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ce groupe de mots en lettres latines.", "prompt": "الرُّوحُ الْقُدُسُ", "promptLanguage": "ar", "answer": "ar-rû7u l-qudus", "acceptedAnswers": ["ar-rû7u l-qudus", "arrû7u lqudus", "ar rû7u l qudus", "ar-ru7u l-qudus", "arru7u lqudus", "ar ru7u l qudus", "ar-ruu7u l-qudus", "arruu7u lqudus", "ar ruu7u l qudus", "ar-rû7 al-qudus", "arrû7 alqudus", "ar rû7 al qudus", "ar-ru7 al-qudus", "arru7 alqudus", "ar ru7 al qudus", "ar-ruu7 al-qudus", "arruu7 alqudus", "ar ruu7 al qudus", "ar-rû7u al-qudus", "arrû7u alqudus", "ar rû7u al qudus", "ar-ru7u al-qudus", "arru7u alqudus", "ar ru7u al qudus", "ar-ruu7u al-qudus", "arruu7u alqudus", "ar ruu7u al qudus", "ar-rû7 l-qudus", "arrû7 lqudus", "ar rû7 l qudus", "ar-ru7 l-qudus", "arru7 lqudus", "ar ru7 l qudus", "ar-ruu7 l-qudus", "arruu7 lqudus", "ar ruu7 l qudus", "ar-ruh al-qudus", "arruh alqudus", "ar ruh al qudus", "ar-ruhu l-qudus", "arruhu lqudus", "ar ruhu l qudus", "ar-rûhu l-qudus", "arrûhu lqudus", "ar rûhu l qudus", "ar-ruuhu l-qudus", "arruuhu lqudus", "ar ruuhu l qudus"], "hint": "Le ح sans point se note 7.", "explanation": "الرُّوحُ : ر solaire, donc ar-rû7u (û long). الْقُدُسُ : ق lunaire, donc al-qudus ; après la damma, le a de al- tombe : l-qudus.", "tip": "Un mot solaire, un mot lunaire : deux articles, deux règles.", "extraExample": {"text": "بِاسْمِ الرُّوحِ الْقُدُسِ", "translation": "au nom du Saint-Esprit", "transliteration": "bismi r-rû7i l-qudus"}, "errorPatterns": [{"equals": "al-rû7u l-qudus", "category": "grammar", "feedback": "ر est solaire : on dit ar-rû7u, sans le l."}, {"equals": "ar-rû7u q-qudus", "category": "grammar", "feedback": "ق est lunaire : le l de l-qudus se dit."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l25.e20', 'ar', 'ar.l25', 'ar.v.ism', array['ar.v.ism','ar.v.bismi','ar.g25.al_solaire_lunaire']::text[], 'free_answer', 'lesson', 'بِاسْمِ', array['au nom de','au nom du','au nom d''','au nom des','par le nom de']::text[], 'بِاسْمِ = بِ (au, par) + اسْم (nom) : « au nom de ». Le ا de اسْم ne se prononce pas : bismi.', 3, '{"id": "ar.l25.e20", "unitIds": ["ar.v.ism", "ar.v.bismi", "ar.g25.al_solaire_lunaire"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la traduction en français.", "prompt": "بِاسْمِ", "promptLanguage": "ar", "answer": "au nom de", "acceptedAnswers": ["au nom de", "au nom du", "au nom d''", "au nom des", "par le nom de"], "explanation": "بِاسْمِ = بِ (au, par) + اسْم (nom) : « au nom de ». Le ا de اسْم ne se prononce pas : bismi.", "tip": "بِاسْمِ + nom : c''est le début de la prière.", "extraExample": {"text": "بِاسْمِ الرَّبِّ", "translation": "au nom du Seigneur", "transliteration": "bismi r-rabbi"}, "errorPatterns": [{"contains": "père", "category": "vocabulary", "feedback": "« Père » se dit الْآب ; ici on te demande le sens de بِاسْمِ : « au nom de »."}], "pool": "lesson", "lessonId": "ar.l25", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e01', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.kanisa']::text[], 'mcq', 'lesson', 'كَنِيسَة', array['kanîsa']::text[], 'Le ة final d''un mot seul se lit a : ka-nî-sa. Le ي après la kasra donne un î long.', 1, '{"id": "ar.l26.e01", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.kanisa"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "كَنِيسَة", "promptLanguage": "ar", "options": ["kanîsa", "kanîsat", "kanîs", "kanasa"], "answer": "kanîsa", "acceptedAnswers": ["kanîsa"], "explanation": "Le ة final d''un mot seul se lit a : ka-nî-sa. Le ي après la kasra donne un î long.", "tip": "ة à la fin d''un mot seul : tu dis a.", "extraExample": {"text": "هٰذِهِ كَنِيسَةٌ", "translation": "C''est une église.", "transliteration": "hâdhihi kanîsa"}, "errorPatterns": [{"equals": "kanîsat", "category": "grammar", "feedback": "Le t de ة n''apparaît que si un autre mot suit. Seul, on dit simplement a."}, {"equals": "kanîs", "category": "spelling", "feedback": "N''oublie pas le ة : il ajoute un a final."}, {"equals": "kanasa", "category": "spelling", "feedback": "Sous le ن il y a une kasra suivie d''un ي : nî long, pas na."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e02', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.haykal']::text[], 'mcq', 'lesson', 'هَيْكَل', array['haykal']::text[], 'Le ي porte un soukoun après la fatha du ه : c''est la diphtongue ay, comme dans « paye ». On lit hay-kal, « le sanctuaire ».', 1, '{"id": "ar.l26.e02", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.haykal"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "هَيْكَل", "promptLanguage": "ar", "options": ["haykal", "hîkal", "hawkal", "hikal"], "answer": "haykal", "acceptedAnswers": ["haykal"], "explanation": "Le ي porte un soukoun après la fatha du ه : c''est la diphtongue ay, comme dans « paye ». On lit hay-kal, « le sanctuaire ».", "tip": "Fatha + ي avec soukoun = ay, pas î.", "extraExample": {"text": "الْمَذْبَحُ فِي الْهَيْكَلِ", "translation": "L''autel est dans le sanctuaire.", "transliteration": "al-madhba7u fî l-haykal"}, "errorPatterns": [{"equals": "hîkal", "category": "spelling", "feedback": "Un î long demande une kasra avant le ي. Ici la fatha et le soukoun donnent ay."}, {"equals": "hawkal", "category": "spelling", "feedback": "La lettre est ي (deux points dessous), pas و : ay et non aw."}, {"equals": "hikal", "category": "spelling", "feedback": "La voyelle du ه est une fatha (a) suivie de ي avec soukoun : hay."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e03', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.kanisa','ar.v.haykal','ar.v.madhbah','ar.v.ayquna','ar.v.salib']::text[], 'match', 'lesson', 'Dans l''église : cinq mots à connaître', '{}'::text[], 'Le sanctuaire (هَيْكَل) est la partie de l''église où se trouve l''autel (مَذْبَح) ; les icônes et la croix sont dans toute l''église.', 1, '{"id": "ar.l26.e03", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.kanisa", "ar.v.haykal", "ar.v.madhbah", "ar.v.ayquna", "ar.v.salib"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Dans l''église : cinq mots à connaître", "promptLanguage": "fr", "pairs": [{"left": "كَنِيسَة", "right": "église"}, {"left": "هَيْكَل", "right": "sanctuaire"}, {"left": "مَذْبَح", "right": "autel"}, {"left": "أَيْقُونَة", "right": "icône"}, {"left": "صَلِيب", "right": "croix"}], "answer": "كَنِيسَة = église ; هَيْكَل = sanctuaire ; مَذْبَح = autel ; أَيْقُونَة = icône ; صَلِيب = croix", "acceptedAnswers": [], "explanation": "Le sanctuaire (هَيْكَل) est la partie de l''église où se trouve l''autel (مَذْبَح) ; les icônes et la croix sont dans toute l''église.", "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e04', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.ayquna']::text[], 'mcq', 'lesson', 'أَيْقُونَة', array['ayqûna']::text[], 'Trois temps : أَيْ = ay (diphtongue), قُو = qû (damma + و = û long), نَة = na (ة final = a). On lit ay-qû-na.', 1, '{"id": "ar.l26.e04", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.ayquna"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "أَيْقُونَة", "promptLanguage": "ar", "options": ["ayqûna", "ayquna", "ayqûnat", "aqûna"], "answer": "ayqûna", "acceptedAnswers": ["ayqûna"], "explanation": "Trois temps : أَيْ = ay (diphtongue), قُو = qû (damma + و = û long), نَة = na (ة final = a). On lit ay-qû-na.", "tip": "Dans ce mot, un son long (û) et une diphtongue (ay).", "extraExample": {"text": "أَيْقُونَةٌ جَمِيلَةٌ", "translation": "une belle icône", "transliteration": "ayqûnatun djamîla"}, "errorPatterns": [{"equals": "ayquna", "category": "spelling", "feedback": "Après قُ, le و allonge la voyelle : qû et non qu."}, {"equals": "ayqûnat", "category": "grammar", "feedback": "En fin de mot seul, ة se lit a, pas at."}, {"equals": "aqûna", "category": "spelling", "feedback": "N''oublie pas le ي avec soukoun : il donne la diphtongue ay."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e05', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.mawiza']::text[], 'mcq', 'lesson', 'مَوْعِظَة', array['maw3iZa']::text[], 'مَوْ = maw : le و porte un soukoun après une fatha, c''est la diphtongue aw. Puis عِ = 3i, ظَ = Za (ظ = Z, la lettre emphatique avec un point) et le ة final se lit a.', 2, '{"id": "ar.l26.e05", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.mawiza"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "مَوْعِظَة", "promptLanguage": "ar", "options": ["maw3iZa", "mû3iZa", "maw3iDa", "mawa3iZa"], "answer": "maw3iZa", "acceptedAnswers": ["maw3iZa"], "explanation": "مَوْ = maw : le و porte un soukoun après une fatha, c''est la diphtongue aw. Puis عِ = 3i, ظَ = Za (ظ = Z, la lettre emphatique avec un point) et le ة final se lit a.", "tip": "و avec soukoun après fatha = aw (comme dans « miaou »).", "extraExample": {"text": "الْمَوْعِظَةُ عَلَى الْجَبَلِ", "translation": "le Sermon sur la montagne", "transliteration": "al-maw3iZatu 3alâ l-djabal"}, "errorPatterns": [{"equals": "mû3iZa", "category": "spelling", "feedback": "Un û long demande une damma avant le و. Ici, fatha + soukoun = aw."}, {"equals": "maw3iDa", "category": "spelling", "feedback": "ظ (un point sur ط) se note Z ; ض (point sur ص) se note D."}, {"equals": "mawa3iZa", "category": "spelling", "feedback": "Le و porte un soukoun : il n''y a pas de voyelle entre w et 3."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e06', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.haykal','ar.v.bakhur','ar.v.salib','ar.v.qurban']::text[], 'mcq', 'lesson', 'Dans lequel de ces mots y a-t-il une diphtongue (ay ou aw) ?', array['هَيْكَل']::text[], 'Dans هَيْكَل, le ي a un soukoun après une fatha : ay. Dans بَخُور le و suit une damma (û long), dans صَلِيب le ي suit une kasra (î long), dans قُرْبَان le ا suit une fatha (â long).', 2, '{"id": "ar.l26.e06", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.haykal", "ar.v.bakhur", "ar.v.salib", "ar.v.qurban"], "type": "mcq", "difficulty": 2, "instruction": "Observe la voyelle avant ي / و.", "prompt": "Dans lequel de ces mots y a-t-il une diphtongue (ay ou aw) ?", "promptLanguage": "fr", "options": ["هَيْكَل", "بَخُور", "صَلِيب", "قُرْبَان"], "answer": "هَيْكَل", "acceptedAnswers": ["هَيْكَل"], "explanation": "Dans هَيْكَل, le ي a un soukoun après une fatha : ay. Dans بَخُور le و suit une damma (û long), dans صَلِيب le ي suit une kasra (î long), dans قُرْبَان le ا suit une fatha (â long).", "tip": "Une diphtongue, c''est fatha + ي ou و avec soukoun.", "extraExample": {"text": "بَيْت", "translation": "maison (leçon 23) : bayt, ay aussi", "transliteration": "bayt"}, "errorPatterns": [{"equals": "بَخُور", "category": "spelling", "feedback": "Le و suit une damma et n''a pas de soukoun : c''est un û long."}, {"equals": "صَلِيب", "category": "spelling", "feedback": "Le ي suit une kasra : c''est un î long."}, {"equals": "قُرْبَان", "category": "spelling", "feedback": "Le ا suit une fatha : c''est un â long, pas une diphtongue."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e07', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.kanisa']::text[], 'mcq', 'lesson', 'Comment se lit le ة dans كَنِيسَة (mot seul) ?', array['a : kanîsa']::text[], 'Dans un mot lu seul, le ة se lit a. Le t n''apparaît que si un autre mot suit (kanîsatu r-rabb). On ne le note pas h dans notre système de transcription.', 2, '{"id": "ar.l26.e07", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.kanisa"], "type": "mcq", "difficulty": 2, "instruction": "Le ة final se prononce comment ?", "prompt": "Comment se lit le ة dans كَنِيسَة (mot seul) ?", "promptLanguage": "fr", "options": ["a : kanîsa", "t : kanîsat", "h : kanîsah", "ta : kanîsata"], "answer": "a : kanîsa", "acceptedAnswers": ["a : kanîsa"], "explanation": "Dans un mot lu seul, le ة se lit a. Le t n''apparaît que si un autre mot suit (kanîsatu r-rabb). On ne le note pas h dans notre système de transcription.", "tip": "ة = a, sauf devant un autre mot.", "extraExample": {"text": "هٰذِهِ شَمْعَةٌ", "translation": "C''est une bougie.", "transliteration": "hâdhihi cham3a"}, "errorPatterns": [{"equals": "t : kanîsat", "category": "grammar", "feedback": "Le t ne se dit que devant un autre mot (annexion), pas à la fin d''un mot seul."}, {"equals": "h : kanîsah", "category": "spelling", "feedback": "Certains livres notent un h, mais le son est un simple a. Ici, on écrit kanîsa."}, {"equals": "ta : kanîsata", "category": "grammar", "feedback": "La terminaison complète (-atu, -ati, -ata) ne se dit qu''à l''intérieur d''une phrase."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e08', 'ar', 'ar.l26', 'ar.v.masih', array['ar.v.masih','ar.g26.ta_marbuta_diphtongues','ar.v.ayquna']::text[], 'mcq', 'lesson', 'أَيْقُونَةُ الْمَسِيحِ', array['l''icône du Christ']::text[], 'أَيْقُونَة = icône ; الْمَسِيح = le Christ. Quand deux noms se suivent comme ici, le premier se lit avec un t devant le second : ayqûnatu l-masî7. Révision : الْمَسِيح est lunaire (al-).', 2, '{"id": "ar.l26.e08", "unitIds": ["ar.v.masih", "ar.g26.ta_marbuta_diphtongues", "ar.v.ayquna"], "type": "mcq", "difficulty": 2, "instruction": "Que veut dire ce groupe de mots ?", "prompt": "أَيْقُونَةُ الْمَسِيحِ", "promptLanguage": "ar", "options": ["l''icône du Christ", "l''église du Christ", "la croix du Christ", "l''autel du Christ"], "answer": "l''icône du Christ", "acceptedAnswers": ["l''icône du Christ"], "explanation": "أَيْقُونَة = icône ; الْمَسِيح = le Christ. Quand deux noms se suivent comme ici, le premier se lit avec un t devant le second : ayqûnatu l-masî7. Révision : الْمَسِيح est lunaire (al-).", "tip": "Le ة devient t devant le mot qui suit.", "extraExample": {"text": "أَيْقُونَةُ الْعَذْرَاءِ", "translation": "l''icône de la Vierge", "transliteration": "ayqûnatu l-3adhrâ''"}, "errorPatterns": [{"equals": "l''église du Christ", "category": "vocabulary", "feedback": "L''église se dit كَنِيسَة. Ici le premier mot commence par أَيْ : c''est أَيْقُونَة, l''icône."}, {"equals": "la croix du Christ", "category": "vocabulary", "feedback": "La croix se dit صَلِيب. Ici : أَيْقُونَة, l''icône."}, {"equals": "l''autel du Christ", "category": "vocabulary", "feedback": "L''autel se dit مَذْبَح. Ici : أَيْقُونَة, l''icône."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e09', 'ar', 'ar.l26', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.salib']::text[], 'mcq', 'lesson', 'الصَّلِيب', array['aS-Salîb']::text[], 'Révision de ال : ص est une lettre solaire, la chadda le montre. Le l tombe et le S est doublé : aS-Salîb. Le ـِي est un î long.', 3, '{"id": "ar.l26.e09", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.salib"], "type": "mcq", "difficulty": 3, "instruction": "Comment lit-on ce mot ?", "prompt": "الصَّلِيب", "promptLanguage": "ar", "options": ["aS-Salîb", "al-Salîb", "aS-Salib", "aS-Sulîb"], "answer": "aS-Salîb", "acceptedAnswers": ["aS-Salîb"], "explanation": "Révision de ال : ص est une lettre solaire, la chadda le montre. Le l tombe et le S est doublé : aS-Salîb. Le ـِي est un î long.", "tip": "Chadda après ال : le l ne se dit pas.", "extraExample": {"text": "الشَّمْعَة", "translation": "la bougie : ach-cham3a", "transliteration": "ach-cham3a"}, "errorPatterns": [{"equals": "al-Salîb", "category": "grammar", "feedback": "ص est solaire : la chadda double le S et le l ne se dit pas."}, {"equals": "aS-Sulîb", "category": "spelling", "feedback": "Sous le ل il y a une fatha : Sa-lîb, et non Su-lîb."}, {"equals": "aS-Salib", "category": "spelling", "feedback": "Kasra + ي = î long : Salîb."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e10', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.kanisa']::text[], 'fill_blank', 'lesson', '___ كَبِيرَةٌ', array['الْكَنِيسَةُ']::text[], 'كَبِيرَةٌ se termine par ة : c''est le féminin. Il faut un nom féminin, et seul الْكَنِيسَة (kanîsa) l''est. هَيْكَل et مَذْبَح sont masculins : ils demanderaient كَبِيرٌ.', 2, '{"id": "ar.l26.e10", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.kanisa"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « L''église est grande. »", "prompt": "___ كَبِيرَةٌ", "promptLanguage": "ar", "options": ["الْكَنِيسَةُ", "الْهَيْكَلُ", "الْمَذْبَحُ"], "answer": "الْكَنِيسَةُ", "acceptedAnswers": ["الْكَنِيسَةُ"], "explanation": "كَبِيرَةٌ se termine par ة : c''est le féminin. Il faut un nom féminin, et seul الْكَنِيسَة (kanîsa) l''est. هَيْكَل et مَذْبَح sont masculins : ils demanderaient كَبِيرٌ.", "tip": "ة final = souvent un mot féminin, et l''adjectif suit.", "extraExample": {"text": "الْأَيْقُونَةُ جَمِيلَةٌ", "translation": "L''icône est belle.", "transliteration": "al-ayqûnatu djamîla"}, "errorPatterns": [{"equals": "الْهَيْكَلُ", "category": "grammar", "feedback": "الْهَيْكَل est masculin (pas de ة) : l''adjectif serait كَبِيرٌ."}, {"equals": "الْمَذْبَحُ", "category": "grammar", "feedback": "الْمَذْبَح est masculin : l''adjectif serait كَبِيرٌ, sans ة."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e11', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.chamaa','ar.v.madhbah']::text[], 'fill_blank', 'lesson', 'عَلَى الْمَذْبَحِ ___', array['شَمْعَةٌ']::text[], 'Seule une bougie (شَمْعَة) peut se trouver sur l''autel. Une église ou un sanctuaire sont des lieux : on ne les pose pas sur un autel.', 3, '{"id": "ar.l26.e11", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.chamaa", "ar.v.madhbah"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Sur l''autel, il y a une bougie. »", "prompt": "عَلَى الْمَذْبَحِ ___", "promptLanguage": "ar", "options": ["شَمْعَةٌ", "كَنِيسَةٌ", "هَيْكَلٌ"], "answer": "شَمْعَةٌ", "acceptedAnswers": ["شَمْعَةٌ"], "explanation": "Seule une bougie (شَمْعَة) peut se trouver sur l''autel. Une église ou un sanctuaire sont des lieux : on ne les pose pas sur un autel.", "tip": "Lis la phrase en entier avant de choisir.", "extraExample": {"text": "عَلَى الْمَذْبَحِ صَلِيبٌ", "translation": "Sur l''autel, il y a une croix.", "transliteration": "3alâ l-madhba7i Salîb"}, "errorPatterns": [{"equals": "كَنِيسَةٌ", "category": "vocabulary", "feedback": "كَنِيسَة est l''église, un bâtiment : elle ne se trouve pas sur l''autel."}, {"equals": "هَيْكَلٌ", "category": "vocabulary", "feedback": "هَيْكَل est le sanctuaire : l''autel est dedans, pas l''inverse."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e12', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.mawiza']::text[], 'fill_blank', 'lesson', 'مَوْعِظَة = m___3iZa', array['aw']::text[], 'Le و porte un soukoun après la fatha du م : c''est la diphtongue aw. On lit maw3iZa.', 3, '{"id": "ar.l26.e12", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.mawiza"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la lecture du mot مَوْعِظَة.", "prompt": "مَوْعِظَة = m___3iZa", "promptLanguage": "fr", "options": ["aw", "û", "ay"], "answer": "aw", "acceptedAnswers": ["aw"], "explanation": "Le و porte un soukoun après la fatha du م : c''est la diphtongue aw. On lit maw3iZa.", "tip": "و + soukoun après fatha : aw.", "extraExample": {"text": "يَوْم", "translation": "jour : yawm", "transliteration": "yawm"}, "errorPatterns": [{"equals": "û", "category": "spelling", "feedback": "Un û long demande une damma avant le و sans soukoun."}, {"equals": "ay", "category": "spelling", "feedback": "La lettre est و, pas ي : aw et non ay."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e13', 'ar', 'ar.l26', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.chamaa','ar.v.madhbah']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : la bougie / sur / l''autel', array['الشَّمْعَةُ عَلَى الْمَذْبَحِ']::text[], 'On commence par le sujet (الشَّمْعَةُ), puis on dit où elle est (عَلَى الْمَذْبَحِ). Révision : ش est solaire (ach-cham3a) et م de مَذْبَح est lunaire (l-madhba7).', 3, '{"id": "ar.l26.e13", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.chamaa", "ar.v.madhbah"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « La bougie est sur l''autel. »", "prompt": "Remets dans l''ordre : la bougie / sur / l''autel", "promptLanguage": "fr", "tokens": ["عَلَى", "الْمَذْبَحِ", "الشَّمْعَةُ"], "answer": "الشَّمْعَةُ عَلَى الْمَذْبَحِ", "acceptedAnswers": ["الشَّمْعَةُ عَلَى الْمَذْبَحِ"], "explanation": "On commence par le sujet (الشَّمْعَةُ), puis on dit où elle est (عَلَى الْمَذْبَحِ). Révision : ش est solaire (ach-cham3a) et م de مَذْبَح est lunaire (l-madhba7).", "tip": "Sujet d''abord, lieu ensuite.", "extraExample": {"text": "الصَّلِيبُ عَلَى الْمَذْبَحِ", "translation": "La croix est sur l''autel.", "transliteration": "aS-Salîbu 3alâ l-madhba7"}, "pool": "lesson", "lessonId": "ar.l26", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e14', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.abouna','ar.v.kanisa']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : abouna / dans / l''église', array['أَبُونَا فِي الْكَنِيسَةِ']::text[], 'Le sujet أَبُونَا ouvre la phrase, puis فِي (dans) et الْكَنِيسَةِ. Le ة de الْكَنِيسَةِ garde sa lecture a en fin de phrase : fî l-kanîsa.', 3, '{"id": "ar.l26.e14", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.abouna", "ar.v.kanisa"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Abouna est dans l''église. »", "prompt": "Remets dans l''ordre : abouna / dans / l''église", "promptLanguage": "fr", "tokens": ["فِي", "الْكَنِيسَةِ", "أَبُونَا"], "answer": "أَبُونَا فِي الْكَنِيسَةِ", "acceptedAnswers": ["أَبُونَا فِي الْكَنِيسَةِ"], "explanation": "Le sujet أَبُونَا ouvre la phrase, puis فِي (dans) et الْكَنِيسَةِ. Le ة de الْكَنِيسَةِ garde sa lecture a en fin de phrase : fî l-kanîsa.", "tip": "Sujet, puis فِي + lieu.", "extraExample": {"text": "أَبُونَا فِي الْهَيْكَلِ", "translation": "Abouna est dans le sanctuaire.", "transliteration": "abûnâ fî l-haykal"}, "pool": "lesson", "lessonId": "ar.l26", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e15', 'ar', 'ar.l26', 'ar.v.rabb', array['ar.v.rabb','ar.g26.ta_marbuta_diphtongues','ar.v.kanisa']::text[], 'translation', 'lesson', 'هٰذِهِ كَنِيسَةُ الرَّبِّ', array['C''est l''église du Seigneur.','Ceci est l''église du Seigneur.','Voici l''église du Seigneur.','C''est une église du Seigneur.']::text[], 'هٰذِهِ = ceci, c''est (féminin) ; كَنِيسَةُ = l''église de ; الرَّبِّ = le Seigneur. Devant الرَّبِّ, le ة de كَنِيسَة se lit t : kanîsatu r-rabb.', 2, '{"id": "ar.l26.e15", "unitIds": ["ar.v.rabb", "ar.g26.ta_marbuta_diphtongues", "ar.v.kanisa"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "هٰذِهِ كَنِيسَةُ الرَّبِّ", "promptLanguage": "ar", "answer": "C''est l''église du Seigneur.", "acceptedAnswers": ["C''est l''église du Seigneur.", "Ceci est l''église du Seigneur.", "Voici l''église du Seigneur.", "C''est une église du Seigneur."], "explanation": "هٰذِهِ = ceci, c''est (féminin) ; كَنِيسَةُ = l''église de ; الرَّبِّ = le Seigneur. Devant الرَّبِّ, le ة de كَنِيسَة se lit t : kanîsatu r-rabb.", "tip": "كَنِيسَةُ + nom : le ة se lit t.", "extraExample": {"text": "كَنِيسَةُ الْمَسِيحِ", "translation": "l''église du Christ", "transliteration": "kanîsatu l-masî7"}, "errorPatterns": [{"contains": "maison", "category": "vocabulary", "feedback": "La maison se dit بَيْت. Ici, كَنِيسَة est l''église."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e16', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.haykal','ar.v.madhbah','ar.v.salib']::text[], 'translation', 'lesson', 'فِي الْهَيْكَلِ مَذْبَحٌ وَصَلِيبٌ', array['Dans le sanctuaire, il y a un autel et une croix.','Dans le sanctuaire il y a un autel et une croix.','Il y a un autel et une croix dans le sanctuaire.','Dans le sanctuaire, un autel et une croix.']::text[], 'فِي الْهَيْكَلِ = dans le sanctuaire ; مَذْبَحٌ = un autel ; وَصَلِيبٌ = et une croix (وَ se colle au mot suivant). Quand le lieu ouvre la phrase et que le nom n''a pas d''article, on traduit « il y a ».', 4, '{"id": "ar.l26.e16", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.haykal", "ar.v.madhbah", "ar.v.salib"], "type": "translation", "difficulty": 4, "instruction": "Traduis en français.", "prompt": "فِي الْهَيْكَلِ مَذْبَحٌ وَصَلِيبٌ", "promptLanguage": "ar", "answer": "Dans le sanctuaire, il y a un autel et une croix.", "acceptedAnswers": ["Dans le sanctuaire, il y a un autel et une croix.", "Dans le sanctuaire il y a un autel et une croix.", "Il y a un autel et une croix dans le sanctuaire.", "Dans le sanctuaire, un autel et une croix."], "explanation": "فِي الْهَيْكَلِ = dans le sanctuaire ; مَذْبَحٌ = un autel ; وَصَلِيبٌ = et une croix (وَ se colle au mot suivant). Quand le lieu ouvre la phrase et que le nom n''a pas d''article, on traduit « il y a ».", "tip": "Lieu + nom sans ال : « il y a… ».", "extraExample": {"text": "فِي الْكَنِيسَةِ أَيْقُونَةٌ وَشَمْعَةٌ", "translation": "Dans l''église, il y a une icône et une bougie.", "transliteration": "fî l-kanîsati ayqûnatun wa-cham3a"}, "errorPatterns": [{"contains": "église", "category": "vocabulary", "feedback": "Le premier lieu est الْهَيْكَل, le sanctuaire, pas l''église (كَنِيسَة)."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e17', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.bakhur','ar.v.chamaa','ar.v.qurban','ar.v.abouna','ar.v.mawiza']::text[], 'match', 'lesson', 'Cinq mots de plus', '{}'::text[], 'L''encens, la bougie et l''offrande sont posés ou brûlés à l''autel ; أَبُونَا est le prêtre qui célèbre ; la مَوْعِظَة est son sermon.', 2, '{"id": "ar.l26.e17", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.bakhur", "ar.v.chamaa", "ar.v.qurban", "ar.v.abouna", "ar.v.mawiza"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Cinq mots de plus", "promptLanguage": "fr", "pairs": [{"left": "بَخُور", "right": "encens"}, {"left": "شَمْعَة", "right": "bougie"}, {"left": "قُرْبَان", "right": "offrande"}, {"left": "أَبُونَا", "right": "notre père (le prêtre)"}, {"left": "مَوْعِظَة", "right": "sermon"}], "answer": "بَخُور = encens ; شَمْعَة = bougie ; قُرْبَان = offrande ; أَبُونَا = notre père (le prêtre) ; مَوْعِظَة = sermon", "acceptedAnswers": [], "explanation": "L''encens, la bougie et l''offrande sont posés ou brûlés à l''autel ; أَبُونَا est le prêtre qui célèbre ; la مَوْعِظَة est son sermon.", "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e18', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.kanisa','ar.v.haykal','ar.v.ayquna','ar.v.mawiza','ar.v.bakhur']::text[], 'match', 'lesson', 'Lecture éclair : cinq mots de l''église', '{}'::text[], 'ة final = a (kanîsa, ayqûna, maw3iZa) ; ـَيْ = ay (haykal, ayqûna) ; ـَوْ = aw (maw3iZa) ; ـُو = û (bakhûr).', 3, '{"id": "ar.l26.e18", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.kanisa", "ar.v.haykal", "ar.v.ayquna", "ar.v.mawiza", "ar.v.bakhur"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lecture éclair : cinq mots de l''église", "promptLanguage": "fr", "pairs": [{"left": "كَنِيسَة", "right": "kanîsa"}, {"left": "هَيْكَل", "right": "haykal"}, {"left": "أَيْقُونَة", "right": "ayqûna"}, {"left": "مَوْعِظَة", "right": "maw3iZa"}, {"left": "بَخُور", "right": "bakhûr"}], "answer": "كَنِيسَة = kanîsa ; هَيْكَل = haykal ; أَيْقُونَة = ayqûna ; مَوْعِظَة = maw3iZa ; بَخُور = bakhûr", "acceptedAnswers": [], "explanation": "ة final = a (kanîsa, ayqûna, maw3iZa) ; ـَيْ = ay (haykal, ayqûna) ; ـَوْ = aw (maw3iZa) ; ـُو = û (bakhûr).", "pool": "lesson", "lessonId": "ar.l26", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e19', 'ar', 'ar.l26', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.ayquna']::text[], 'free_answer', 'lesson', 'الْأَيْقُونَة', array['al-ayqûna','alayqûna','al ayqûna','al-ayquna','alayquna','al ayquna','al-ayquuna','alayquuna','al ayquuna','al-ayqunah','al-ayqûnah']::text[], 'الْ = al- (la hamza de أَيْقُونَة est lunaire), أَيْ = ay, قُو = qû (û long), نَة = na : al-ayqûna.', 3, '{"id": "ar.l26.e19", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.ayquna"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ce mot en lettres latines.", "prompt": "الْأَيْقُونَة", "promptLanguage": "ar", "answer": "al-ayqûna", "acceptedAnswers": ["al-ayqûna", "alayqûna", "al ayqûna", "al-ayquna", "alayquna", "al ayquna", "al-ayquuna", "alayquuna", "al ayquuna", "al-ayqunah", "al-ayqûnah"], "hint": "ay + qû + na.", "explanation": "الْ = al- (la hamza de أَيْقُونَة est lunaire), أَيْ = ay, قُو = qû (û long), نَة = na : al-ayqûna.", "tip": "Écris ay pour la diphtongue et û pour la voyelle longue.", "extraExample": {"text": "أَيْقُونَةٌ جَمِيلَةٌ", "translation": "une belle icône", "transliteration": "ayqûnatun djamîla"}, "errorPatterns": [{"equals": "al-ayqunat", "category": "grammar", "feedback": "À la fin d''un mot seul, le ة se lit a, pas at."}, {"equals": "ar-ayqûna", "category": "grammar", "feedback": "La hamza est lunaire : le ل porte un soukoun et se dit, al-ayqûna."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l26.e20', 'ar', 'ar.l26', 'ar.v.haykal', array['ar.v.haykal','ar.g26.ta_marbuta_diphtongues']::text[], 'free_answer', 'lesson', 'الْهَيْكَل', array['sanctuaire','le sanctuaire','chœur','le chœur','le sanctuaire (le chœur)','le sanctuaire de l''église']::text[], 'الْهَيْكَل est le sanctuaire d''une église copte : la partie où se trouve l''autel.', 3, '{"id": "ar.l26.e20", "unitIds": ["ar.v.haykal", "ar.g26.ta_marbuta_diphtongues"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la traduction en français.", "prompt": "الْهَيْكَل", "promptLanguage": "ar", "answer": "sanctuaire", "acceptedAnswers": ["sanctuaire", "le sanctuaire", "chœur", "le chœur", "le sanctuaire (le chœur)", "le sanctuaire de l''église"], "explanation": "الْهَيْكَل est le sanctuaire d''une église copte : la partie où se trouve l''autel.", "tip": "Haykal = là où est l''autel.", "extraExample": {"text": "حِجَابُ الْهَيْكَلِ", "translation": "la cloison du sanctuaire", "transliteration": "7idjâbu l-haykal"}, "errorPatterns": [{"contains": "autel", "category": "vocabulary", "feedback": "L''autel est مَذْبَح ; هَيْكَل est le sanctuaire qui le contient."}], "pool": "lesson", "lessonId": "ar.l26", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e01', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.quddas']::text[], 'mcq', 'lesson', 'الْقُدَّاس', array['al-quddâs']::text[], 'قُ = qu, دَّا = ddâ : le د porte une chadda (il est doublé) et le ا qui suit allonge le a. Le ق est lunaire : al-. On lit al-quddâs, « la messe ».', 1, '{"id": "ar.l27.e01", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.quddas"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "الْقُدَّاس", "promptLanguage": "ar", "options": ["al-quddâs", "al-qudâs", "al-qaddâs", "al-quddas"], "answer": "al-quddâs", "acceptedAnswers": ["al-quddâs"], "explanation": "قُ = qu, دَّا = ddâ : le د porte une chadda (il est doublé) et le ا qui suit allonge le a. Le ق est lunaire : al-. On lit al-quddâs, « la messe ».", "tip": "Chadda sur le د = deux d ; ا long = temps fort à la fin.", "extraExample": {"text": "الْقُدَّاسُ الْإِلٰهِيُّ", "translation": "la divine liturgie", "transliteration": "al-quddâsu l-ilâhiyy"}, "errorPatterns": [{"equals": "al-qudâs", "category": "spelling", "feedback": "Le د porte une chadda : il faut deux d, quddâs."}, {"equals": "al-qaddâs", "category": "spelling", "feedback": "Sous la première lettre après ال, c''est une damma (u), pas une fatha : qu."}, {"equals": "al-quddas", "category": "spelling", "feedback": "Le ا final allonge le a : quddâs."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e02', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.indjil']::text[], 'mcq', 'lesson', 'الْإِنْجِيل', array['al-indjîl']::text[], 'إِنْ = in (hamza sous l''alif + kasra, puis ن avec soukoun), جِي = djî (kasra + ي = î long), ل. On lit al-in-djîl, « l''Évangile ».', 1, '{"id": "ar.l27.e02", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.indjil"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "الْإِنْجِيل", "promptLanguage": "ar", "options": ["al-indjîl", "al-indjil", "al-andjîl", "al-indjâl"], "answer": "al-indjîl", "acceptedAnswers": ["al-indjîl"], "explanation": "إِنْ = in (hamza sous l''alif + kasra, puis ن avec soukoun), جِي = djî (kasra + ي = î long), ل. On lit al-in-djîl, « l''Évangile ».", "tip": "Hamza avec une kasra dessous : le mot commence par i.", "extraExample": {"text": "الْإِنْجِيلُ كِتَابٌ", "translation": "L''Évangile est un livre.", "transliteration": "al-indjîlu kitâb"}, "errorPatterns": [{"equals": "al-indjil", "category": "spelling", "feedback": "Kasra + ي = î long : djîl."}, {"equals": "al-andjîl", "category": "spelling", "feedback": "Le petit trait est sous l''alif : kasra, donc i et non a."}, {"equals": "al-indjâl", "category": "spelling", "feedback": "Après جِ, c''est un ي (î long), pas un ا."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e03', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.quddas','ar.v.indjil','ar.v.mazmur','ar.v.rasul','ar.v.tasbiha']::text[], 'match', 'lesson', 'Cinq mots de l''office', '{}'::text[], 'الْقُدَّاس est la liturgie de l''eucharistie ; الْإِنْجِيل et الْمَزْمُور en sont deux lectures ; التَّسْبِحَة est l''office de louange ; رَسُول est l''« envoyé ».', 1, '{"id": "ar.l27.e03", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.quddas", "ar.v.indjil", "ar.v.mazmur", "ar.v.rasul", "ar.v.tasbiha"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Cinq mots de l''office", "promptLanguage": "fr", "pairs": [{"left": "الْقُدَّاس", "right": "la messe (la liturgie)"}, {"left": "الْإِنْجِيل", "right": "l''Évangile"}, {"left": "الْمَزْمُور", "right": "le psaume"}, {"left": "رَسُول", "right": "apôtre"}, {"left": "التَّسْبِحَة", "right": "la louange (tasbiha)"}], "answer": "الْقُدَّاس = la messe (la liturgie) ; الْإِنْجِيل = l''Évangile ; الْمَزْمُور = le psaume ; رَسُول = apôtre ; التَّسْبِحَة = la louange (tasbiha)", "acceptedAnswers": [], "explanation": "الْقُدَّاس est la liturgie de l''eucharistie ; الْإِنْجِيل et الْمَزْمُور en sont deux lectures ; التَّسْبِحَة est l''office de louange ; رَسُول est l''« envoyé ».", "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e04', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.bulus']::text[], 'mcq', 'lesson', 'الْبُولُس', array['al-bûlus']::text[], 'بُو = bû (damma + و = û long), لُ = lu (damma seule : u bref), س. Le ب est lunaire : al-bûlus. Seul le premier u est long.', 2, '{"id": "ar.l27.e04", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.bulus"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "الْبُولُس", "promptLanguage": "ar", "options": ["al-bûlus", "al-bulus", "al-bûlûs", "al-bawlus"], "answer": "al-bûlus", "acceptedAnswers": ["al-bûlus"], "explanation": "بُو = bû (damma + و = û long), لُ = lu (damma seule : u bref), س. Le ب est lunaire : al-bûlus. Seul le premier u est long.", "tip": "Deux dammas, mais une seule est suivie d''un و : seule celle-là est longue.", "extraExample": {"text": "بُولُسُ الرَّسُولُ", "translation": "Paul l''apôtre", "transliteration": "bûlusu r-rasûl"}, "errorPatterns": [{"equals": "al-bulus", "category": "spelling", "feedback": "Il y a un و après la damma du ب : bû est long."}, {"equals": "al-bûlûs", "category": "spelling", "feedback": "Le deuxième u n''est pas suivi d''un و : il est bref, lus."}, {"equals": "al-bawlus", "category": "spelling", "feedback": "Le و n''a pas de soukoun et suit une damma : c''est un û, pas la diphtongue aw."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e05', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.katholikon']::text[], 'mcq', 'lesson', 'الْكَاثُولِيكُون', array['al-kâthûlîkûn']::text[], 'Découpe en blocs : كَا (kâ) · ثُو (thû) · لِي (lî) · كُو (kûn)… Quatre voyelles longues. ث se lit th, comme dans « thé » anglais.', 2, '{"id": "ar.l27.e05", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.katholikon"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "الْكَاثُولِيكُون", "promptLanguage": "ar", "options": ["al-kâthûlîkûn", "al-kâtûlîkûn", "al-kathûlikûn", "al-kâthûlîkun"], "answer": "al-kâthûlîkûn", "acceptedAnswers": ["al-kâthûlîkûn"], "explanation": "Découpe en blocs : كَا (kâ) · ثُو (thû) · لِي (lî) · كُو (kûn)… Quatre voyelles longues. ث se lit th, comme dans « thé » anglais.", "tip": "Quatre blocs, quatre voyelles longues : kâ-thû-lî-kûn.", "extraExample": {"text": "رِسَالَةُ يَعْقُوبَ", "translation": "l''épître de Jacques", "transliteration": "risâlatu ya3qûba"}, "errorPatterns": [{"equals": "al-kâtûlîkûn", "category": "spelling", "feedback": "ث (trois points) se note th, pas t."}, {"equals": "al-kathûlikûn", "category": "spelling", "feedback": "Après لِ, le ي allonge la voyelle : lî."}, {"equals": "al-kâthûlîkun", "category": "spelling", "feedback": "Le dernier ـُو est long aussi : kûn."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e06', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.ibraksis']::text[], 'mcq', 'lesson', 'الْإِبْرَكْسِيس', array['al-ibraksîs']::text[], 'إِبْ = ib, رَ = ra, كْ = k (soukoun), سِي = sîs (kasra + ي = î long), س. Un seul son long : l''avant-dernier.', 2, '{"id": "ar.l27.e06", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.ibraksis"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "الْإِبْرَكْسِيس", "promptLanguage": "ar", "options": ["al-ibraksîs", "al-ibraksis", "al-ibrâksîs", "al-abraksîs"], "answer": "al-ibraksîs", "acceptedAnswers": ["al-ibraksîs"], "explanation": "إِبْ = ib, رَ = ra, كْ = k (soukoun), سِي = sîs (kasra + ي = î long), س. Un seul son long : l''avant-dernier.", "tip": "Un seul î long, juste avant la dernière lettre.", "extraExample": {"text": "الْبُولُسُ وَالْإِبْرَكْسِيسُ", "translation": "le Paulus et l''Ibraksis", "transliteration": "al-bûlusu wa-l-ibraksîs"}, "errorPatterns": [{"equals": "al-ibraksis", "category": "spelling", "feedback": "Kasra + ي = î long : sîs."}, {"equals": "al-ibrâksîs", "category": "spelling", "feedback": "Après رَ il n''y a pas de ا : le a est bref."}, {"equals": "al-abraksîs", "category": "spelling", "feedback": "Sous le إ il y a une kasra : i, pas a."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e07', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.sinaksar']::text[], 'mcq', 'lesson', 'السِّنَكْسَار', array['as-sinaksâr']::text[], 'س est solaire : la chadda double le s et le l ne se dit pas, as-sinaksâr. Le ا final est long : â.', 2, '{"id": "ar.l27.e07", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.sinaksar"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "السِّنَكْسَار", "promptLanguage": "ar", "options": ["as-sinaksâr", "al-sinaksâr", "as-sinaksar", "as-sanaksâr"], "answer": "as-sinaksâr", "acceptedAnswers": ["as-sinaksâr"], "explanation": "س est solaire : la chadda double le s et le l ne se dit pas, as-sinaksâr. Le ا final est long : â.", "tip": "Chadda sous le س : on ne dit pas le l.", "extraExample": {"text": "هٰذَا كِتَابُ السِّنَكْسَارِ", "translation": "C''est le livre du Synaxaire.", "transliteration": "hâdhâ kitâbu s-sinaksâr"}, "errorPatterns": [{"equals": "al-sinaksâr", "category": "grammar", "feedback": "س est solaire : on dit as-sinaksâr, sans le l."}, {"equals": "as-sinaksar", "category": "spelling", "feedback": "Le ا final est une voyelle longue : sâr."}, {"equals": "as-sanaksâr", "category": "spelling", "feedback": "Sous le premier س il y a une kasra (si) accompagnée de la chadda."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e08', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.katholikon']::text[], 'mcq', 'lesson', 'Combien de voyelles longues compte الْكَاثُولِيكُون ?', array['4']::text[], 'Chaque voyelle longue = une voyelle brève + sa lettre de prolongement : كَا (â), ثُو (û), لِي (î), كُو (û). Cela fait 4.', 3, '{"id": "ar.l27.e08", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.katholikon"], "type": "mcq", "difficulty": 3, "instruction": "Compte les voyelles longues.", "prompt": "Combien de voyelles longues compte الْكَاثُولِيكُون ?", "promptLanguage": "fr", "options": ["4", "3", "2", "5"], "answer": "4", "acceptedAnswers": ["4"], "explanation": "Chaque voyelle longue = une voyelle brève + sa lettre de prolongement : كَا (â), ثُو (û), لِي (î), كُو (û). Cela fait 4.", "tip": "Compte les ا, و, ي qui allongent, pas ceux de la fin du mot.", "extraExample": {"text": "الْإِبْرَكْسِيس", "translation": "les Actes des Apôtres : une seule voyelle longue", "transliteration": "al-ibraksîs"}, "errorPatterns": [{"equals": "3", "category": "spelling", "feedback": "Il y en a une de plus : كَا, ثُو, لِي et كُو."}, {"equals": "2", "category": "spelling", "feedback": "Compte bien : â, û, î, û."}, {"equals": "5", "category": "spelling", "feedback": "Le ن final n''est pas une voyelle longue : il y en a 4."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e09', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.ibraksis','ar.v.katholikon','ar.v.bulus','ar.v.sinaksar']::text[], 'mcq', 'lesson', 'Quelle lecture est tirée des Actes des Apôtres ?', array['الْإِبْرَكْسِيس']::text[], 'L''Ibraksis (praxis = « actes ») est la lecture des Actes des Apôtres (أَعْمَال الرُّسُل). Le Paulus vient de Paul, le Catholicon des épîtres de Jacques, Pierre, Jean et Jude, le Synaxaire raconte la vie des saints.', 2, '{"id": "ar.l27.e09", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.ibraksis", "ar.v.katholikon", "ar.v.bulus", "ar.v.sinaksar"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lecture.", "prompt": "Quelle lecture est tirée des Actes des Apôtres ?", "promptLanguage": "fr", "options": ["الْإِبْرَكْسِيس", "الْبُولُس", "الْكَاثُولِيكُون", "السِّنَكْسَار"], "answer": "الْإِبْرَكْسِيس", "acceptedAnswers": ["الْإِبْرَكْسِيس"], "explanation": "L''Ibraksis (praxis = « actes ») est la lecture des Actes des Apôtres (أَعْمَال الرُّسُل). Le Paulus vient de Paul, le Catholicon des épîtres de Jacques, Pierre, Jean et Jude, le Synaxaire raconte la vie des saints.", "tip": "Ibraksis = Praxis = Actes.", "extraExample": {"text": "أَعْمَالُ الرُّسُلِ", "translation": "les Actes des Apôtres", "transliteration": "a3mâlu r-rusul"}, "errorPatterns": [{"equals": "الْبُولُس", "category": "vocabulary", "feedback": "Le Paulus est tiré des épîtres de saint Paul."}, {"equals": "الْكَاثُولِيكُون", "category": "vocabulary", "feedback": "Le Catholicon est tiré des épîtres de Jacques, Pierre, Jean et Jude."}, {"equals": "السِّنَكْسَار", "category": "vocabulary", "feedback": "Le Synaxaire raconte la vie des saints du jour."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e10', 'ar', 'ar.l27', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.tasbiha','ar.g25.al_solaire_lunaire']::text[], 'mcq', 'lesson', 'التَّسْبِحَة', array['at-tasbi7a']::text[], 'Révision : ت est solaire (chadda), donc at-tasbi7a, et le ة final d''un mot seul se lit a. Sous le ب il y a une kasra seule : bi bref. Le ح sans point se note 7.', 3, '{"id": "ar.l27.e10", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.tasbiha", "ar.g25.al_solaire_lunaire"], "type": "mcq", "difficulty": 3, "instruction": "Comment lit-on ce mot ?", "prompt": "التَّسْبِحَة", "promptLanguage": "ar", "options": ["at-tasbi7a", "al-tasbi7a", "at-tasbi7at", "at-tasbî7a"], "answer": "at-tasbi7a", "acceptedAnswers": ["at-tasbi7a"], "explanation": "Révision : ت est solaire (chadda), donc at-tasbi7a, et le ة final d''un mot seul se lit a. Sous le ب il y a une kasra seule : bi bref. Le ح sans point se note 7.", "tip": "Chadda après ال : pas de l. ة final : a.", "extraExample": {"text": "تَسْبِحَةُ نِصْفِ اللَّيْلِ", "translation": "la louange de minuit", "transliteration": "tasbi7atu niSfi l-layl"}, "errorPatterns": [{"equals": "al-tasbi7a", "category": "grammar", "feedback": "ت est solaire : la chadda double le t, on ne dit pas le l."}, {"equals": "at-tasbi7at", "category": "grammar", "feedback": "Le t de ة ne se dit que devant un autre mot ; seul, c''est a."}, {"equals": "at-tasbî7a", "category": "spelling", "feedback": "Sous le ب il n''y a pas de ي : la kasra est brève."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e11', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.bulus']::text[], 'fill_blank', 'lesson', 'الْبُولُس = al-b___lus', array['û']::text[], 'Le ب porte une damma suivie d''un و sans signe : c''est un û long. On lit al-bûlus.', 2, '{"id": "ar.l27.e11", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.bulus"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la lecture du mot الْبُولُس.", "prompt": "الْبُولُس = al-b___lus", "promptLanguage": "fr", "options": ["û", "u", "aw"], "answer": "û", "acceptedAnswers": ["û"], "explanation": "Le ب porte une damma suivie d''un و sans signe : c''est un û long. On lit al-bûlus.", "tip": "Damma + و = û.", "extraExample": {"text": "رَسُول", "translation": "apôtre : rasûl", "transliteration": "rasûl"}, "errorPatterns": [{"equals": "u", "category": "spelling", "feedback": "Un و suit la damma : la voyelle est longue."}, {"equals": "aw", "category": "spelling", "feedback": "Pour aw, il faudrait une fatha avant le و et un soukoun sur lui."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e12', 'ar', 'ar.l27', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.sinaksar']::text[], 'fill_blank', 'lesson', 'السِّنَكْسَار = ___-sinaksâr', array['as']::text[], 'Révision de ال : س est solaire (la chadda le montre). Le l tombe et le s est doublé : as-sinaksâr.', 2, '{"id": "ar.l27.e12", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.sinaksar"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la lecture du mot السِّنَكْسَار.", "prompt": "السِّنَكْسَار = ___-sinaksâr", "promptLanguage": "fr", "options": ["as", "al", "an"], "answer": "as", "acceptedAnswers": ["as"], "explanation": "Révision de ال : س est solaire (la chadda le montre). Le l tombe et le s est doublé : as-sinaksâr.", "tip": "Chadda = lettre solaire = pas de l.", "extraExample": {"text": "الشَّمْس", "translation": "le soleil : ach-chams", "transliteration": "ach-chams"}, "errorPatterns": [{"equals": "al", "category": "grammar", "feedback": "Ce serait une lettre lunaire. Ici la chadda sur le س montre qu''elle est solaire."}, {"equals": "an", "category": "spelling", "feedback": "Le son vient de la lettre qui suit : s, pas n."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e13', 'ar', 'ar.l27', 'ar.v.rasul', array['ar.v.rasul','ar.v.bulus','ar.g27.voyelles_longues_mots_grecs']::text[], 'fill_blank', 'lesson', 'بُولُسُ ___', array['الرَّسُولُ']::text[], '« Paul l''apôtre » se dit بُولُسُ الرَّسُولُ. ر est solaire : ar-rasûl. Un psaume ou la liturgie ne sont pas des titres de Paul.', 3, '{"id": "ar.l27.e13", "unitIds": ["ar.v.rasul", "ar.v.bulus", "ar.g27.voyelles_longues_mots_grecs"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Paul l''apôtre ».", "prompt": "بُولُسُ ___", "promptLanguage": "ar", "options": ["الرَّسُولُ", "الْمَزْمُورُ", "الْقُدَّاسُ"], "answer": "الرَّسُولُ", "acceptedAnswers": ["الرَّسُولُ"], "explanation": "« Paul l''apôtre » se dit بُولُسُ الرَّسُولُ. ر est solaire : ar-rasûl. Un psaume ou la liturgie ne sont pas des titres de Paul.", "tip": "رَسُول = l''envoyé, l''apôtre.", "extraExample": {"text": "بُطْرُسُ الرَّسُولُ", "translation": "Pierre l''apôtre", "transliteration": "buTrusu r-rasûl"}, "errorPatterns": [{"equals": "الْمَزْمُورُ", "category": "vocabulary", "feedback": "الْمَزْمُور est le psaume."}, {"equals": "الْقُدَّاسُ", "category": "vocabulary", "feedback": "الْقُدَّاس est la messe, pas un titre de Paul."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e14', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.bulus','ar.v.katholikon','ar.v.ibraksis','ar.v.indjil']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : Évangile / Paulus / Ibraksis / Catholicon', array['الْبُولُس الْكَاثُولِيكُون الْإِبْرَكْسِيس الْإِنْجِيل']::text[], 'On entend d''abord les épîtres : le Paulus (saint Paul), puis le Catholicon, puis l''Ibraksis (les Actes). L''Évangile, la lecture la plus solennelle, vient en dernier.', 3, '{"id": "ar.l27.e14", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.bulus", "ar.v.katholikon", "ar.v.ibraksis", "ar.v.indjil"], "type": "reorder", "difficulty": 3, "instruction": "Remets les lectures dans l''ordre où on les entend au qoddâs.", "prompt": "Remets dans l''ordre : Évangile / Paulus / Ibraksis / Catholicon", "promptLanguage": "fr", "tokens": ["الْإِنْجِيل", "الْإِبْرَكْسِيس", "الْبُولُس", "الْكَاثُولِيكُون"], "answer": "الْبُولُس الْكَاثُولِيكُون الْإِبْرَكْسِيس الْإِنْجِيل", "acceptedAnswers": ["الْبُولُس الْكَاثُولِيكُون الْإِبْرَكْسِيس الْإِنْجِيل"], "explanation": "On entend d''abord les épîtres : le Paulus (saint Paul), puis le Catholicon, puis l''Ibraksis (les Actes). L''Évangile, la lecture la plus solennelle, vient en dernier.", "tip": "Les épîtres d''abord, l''Évangile à la fin.", "extraExample": {"text": "السِّنَكْسَارُ وَالْإِنْجِيلُ", "translation": "le Synaxaire et l''Évangile", "transliteration": "as-sinaksâru wa-l-indjîl"}, "pool": "lesson", "lessonId": "ar.l27", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e15', 'ar', 'ar.l27', 'ar.v.madhbah', array['ar.v.madhbah','ar.g27.voyelles_longues_mots_grecs','ar.v.indjil']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : l''Évangile / sur / l''autel', array['الْإِنْجِيلُ عَلَى الْمَذْبَحِ']::text[], 'Le sujet الْإِنْجِيلُ ouvre la phrase, puis on dit où il est : عَلَى الْمَذْبَحِ. Révision de مَذْبَح (leçon 26).', 3, '{"id": "ar.l27.e15", "unitIds": ["ar.v.madhbah", "ar.g27.voyelles_longues_mots_grecs", "ar.v.indjil"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « L''Évangile est sur l''autel. »", "prompt": "Remets dans l''ordre : l''Évangile / sur / l''autel", "promptLanguage": "fr", "tokens": ["عَلَى", "الْمَذْبَحِ", "الْإِنْجِيلُ"], "answer": "الْإِنْجِيلُ عَلَى الْمَذْبَحِ", "acceptedAnswers": ["الْإِنْجِيلُ عَلَى الْمَذْبَحِ"], "explanation": "Le sujet الْإِنْجِيلُ ouvre la phrase, puis on dit où il est : عَلَى الْمَذْبَحِ. Révision de مَذْبَح (leçon 26).", "tip": "Sujet d''abord, lieu ensuite.", "extraExample": {"text": "الْقُرْبَانُ عَلَى الْمَذْبَحِ", "translation": "L''offrande est sur l''autel.", "transliteration": "al-qurbânu 3alâ l-madhba7"}, "pool": "lesson", "lessonId": "ar.l27", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e16', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.rasul','ar.v.bulus']::text[], 'translation', 'lesson', 'بُولُسُ الرَّسُولُ', array['Paul l''apôtre','Paul, l''apôtre','L''apôtre Paul','Saint Paul l''apôtre','Paul, l''envoyé']::text[], 'بُولُسُ = Paul ; الرَّسُولُ = l''apôtre (littéralement « l''envoyé »). Les deux mots sont côte à côte, sans verbe.', 2, '{"id": "ar.l27.e16", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.rasul", "ar.v.bulus"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "بُولُسُ الرَّسُولُ", "promptLanguage": "ar", "answer": "Paul l''apôtre", "acceptedAnswers": ["Paul l''apôtre", "Paul, l''apôtre", "L''apôtre Paul", "Saint Paul l''apôtre", "Paul, l''envoyé"], "explanation": "بُولُسُ = Paul ; الرَّسُولُ = l''apôtre (littéralement « l''envoyé »). Les deux mots sont côte à côte, sans verbe.", "tip": "Nom + titre avec ال : « Paul l''apôtre ».", "extraExample": {"text": "بُطْرُسُ الرَّسُولُ", "translation": "Pierre l''apôtre", "transliteration": "buTrusu r-rasûl"}, "errorPatterns": [{"contains": "pierre", "category": "vocabulary", "feedback": "Pierre se dit بُطْرُس. Ici le nom est بُولُس, Paul."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e17', 'ar', 'ar.l27', 'ar.v.kanisa', array['ar.v.kanisa','ar.v.quddas','ar.g27.voyelles_longues_mots_grecs']::text[], 'translation', 'lesson', 'الْقُدَّاسُ فِي الْكَنِيسَةِ', array['La messe est dans l''église.','La messe a lieu dans l''église.','La messe est à l''église.','La liturgie est dans l''église.','La liturgie est à l''église.','La liturgie a lieu à l''église.','La messe se célèbre dans l''église.']::text[], 'الْقُدَّاسُ = la messe ; فِي = dans ; الْكَنِيسَةِ = l''église (révision de la leçon 26). Pas de verbe « est » en arabe au présent.', 3, '{"id": "ar.l27.e17", "unitIds": ["ar.v.kanisa", "ar.v.quddas", "ar.g27.voyelles_longues_mots_grecs"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "الْقُدَّاسُ فِي الْكَنِيسَةِ", "promptLanguage": "ar", "answer": "La messe est dans l''église.", "acceptedAnswers": ["La messe est dans l''église.", "La messe a lieu dans l''église.", "La messe est à l''église.", "La liturgie est dans l''église.", "La liturgie est à l''église.", "La liturgie a lieu à l''église.", "La messe se célèbre dans l''église."], "explanation": "الْقُدَّاسُ = la messe ; فِي = dans ; الْكَنِيسَةِ = l''église (révision de la leçon 26). Pas de verbe « est » en arabe au présent.", "tip": "فِي + nom = « dans, à ».", "extraExample": {"text": "الْإِنْجِيلُ فِي الْكَنِيسَةِ", "translation": "L''Évangile est dans l''église.", "transliteration": "al-indjîlu fî l-kanîsa"}, "errorPatterns": [{"contains": "maison", "category": "vocabulary", "feedback": "La maison se dit بَيْت. Ici : الْكَنِيسَة, l''église."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e18', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.bulus','ar.v.katholikon','ar.v.ibraksis','ar.v.sinaksar','ar.v.indjil']::text[], 'match', 'lesson', 'Que lit-on dans chaque lecture ?', '{}'::text[], 'Chaque lecture a son livre : Paul pour le Paulus, les épîtres « universelles » pour le Catholicon, les Actes pour l''Ibraksis, le livre des saints pour le Synaxaire et les quatre Évangiles pour l''Évangile.', 2, '{"id": "ar.l27.e18", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.bulus", "ar.v.katholikon", "ar.v.ibraksis", "ar.v.sinaksar", "ar.v.indjil"], "type": "match", "difficulty": 2, "instruction": "Associe chaque lecture à son contenu.", "prompt": "Que lit-on dans chaque lecture ?", "promptLanguage": "fr", "pairs": [{"left": "الْبُولُس", "right": "les lettres de saint Paul"}, {"left": "الْكَاثُولِيكُون", "right": "les lettres de Jacques, Pierre, Jean et Jude"}, {"left": "الْإِبْرَكْسِيس", "right": "les Actes des Apôtres"}, {"left": "السِّنَكْسَار", "right": "la vie des saints du jour"}, {"left": "الْإِنْجِيل", "right": "le récit de la vie du Christ"}], "answer": "الْبُولُس = les lettres de saint Paul ; الْكَاثُولِيكُون = les lettres de Jacques, Pierre, Jean et Jude ; الْإِبْرَكْسِيس = les Actes des Apôtres ; السِّنَكْسَار = la vie des saints du jour ; الْإِنْجِيل = le récit de la vie du Christ", "acceptedAnswers": [], "explanation": "Chaque lecture a son livre : Paul pour le Paulus, les épîtres « universelles » pour le Catholicon, les Actes pour l''Ibraksis, le livre des saints pour le Synaxaire et les quatre Évangiles pour l''Évangile.", "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e19', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.bulus','ar.v.ibraksis','ar.v.sinaksar','ar.v.mazmur','ar.v.quddas']::text[], 'match', 'lesson', 'Lecture éclair : cinq mots de la messe', '{}'::text[], 'Chaque mot a ses voyelles longues : bû, sîs, sâr, zâ + mîr, dâs. Seul السِّنَكْسَار perd son l (solaire).', 3, '{"id": "ar.l27.e19", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.bulus", "ar.v.ibraksis", "ar.v.sinaksar", "ar.v.mazmur", "ar.v.quddas"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lecture éclair : cinq mots de la messe", "promptLanguage": "fr", "pairs": [{"left": "الْبُولُس", "right": "al-bûlus"}, {"left": "الْإِبْرَكْسِيس", "right": "al-ibraksîs"}, {"left": "السِّنَكْسَار", "right": "as-sinaksâr"}, {"left": "الْمَزَامِير", "right": "al-mazâmîr"}, {"left": "الْقُدَّاس", "right": "al-quddâs"}], "answer": "الْبُولُس = al-bûlus ; الْإِبْرَكْسِيس = al-ibraksîs ; السِّنَكْسَار = as-sinaksâr ; الْمَزَامِير = al-mazâmîr ; الْقُدَّاس = al-quddâs", "acceptedAnswers": [], "explanation": "Chaque mot a ses voyelles longues : bû, sîs, sâr, zâ + mîr, dâs. Seul السِّنَكْسَار perd son l (solaire).", "pool": "lesson", "lessonId": "ar.l27", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e20', 'ar', 'ar.l27', 'ar.g27.voyelles_longues_mots_grecs', array['ar.g27.voyelles_longues_mots_grecs','ar.v.bulus','ar.v.katholikon']::text[], 'free_answer', 'lesson', 'الْبُولُسُ وَالْكَاثُولِيكُونُ', array['al-bûlusu wa-l-kâthûlîkûn','albûlusu walkâthûlîkûn','al bûlusu wa l kâthûlîkûn','al-bulusu wa-l-kathulikun','albulusu walkathulikun','al bulusu wa l kathulikun','al-buulusu wa-l-kaathuuliikuun','albuulusu walkaathuuliikuun','al buulusu wa l kaathuuliikuun','al-bûlus wa-l-kâthûlîkûn','albûlus walkâthûlîkûn','al bûlus wa l kâthûlîkûn','al-bulus wa-l-kathulikun','albulus walkathulikun','al bulus wa l kathulikun','al-buulus wa-l-kaathuuliikuun','albuulus walkaathuuliikuun','al buulus wa l kaathuuliikuun','al-bûlusu wal-kâthûlîkûn','al bûlusu wal kâthûlîkûn','al-bulusu wal-kathulikun','al bulusu wal kathulikun','al-buulusu wal-kaathuuliikuun','al buulusu wal kaathuuliikuun','al-bûlus wal-kâthûlîkûn','al bûlus wal kâthûlîkûn','al-bulus wal-kathulikun','al bulus wal kathulikun','al-buulus wal-kaathuuliikuun','al buulus wal kaathuuliikuun','al-bûlusu wa al-kâthûlîkûn','albûlusu wa alkâthûlîkûn','al bûlusu wa al kâthûlîkûn','al-bulusu wa al-kathulikun','albulusu wa alkathulikun','al bulusu wa al kathulikun','al-buulusu wa al-kaathuuliikuun','albuulusu wa alkaathuuliikuun','al buulusu wa al kaathuuliikuun','al-bûlus wa al-kâthûlîkûn','albûlus wa alkâthûlîkûn','al bûlus wa al kâthûlîkûn','al-bulus wa al-kathulikun','albulus wa alkathulikun','al bulus wa al kathulikun','al-buulus wa al-kaathuuliikuun','albuulus wa alkaathuuliikuun','al buulus wa al kaathuuliikuun']::text[], 'الْبُولُسُ = al-bûlusu ; وَ = wa ; الْكَاثُولِيكُونُ = al-kâthûlîkûn (kâ, thû, lî, kûn). Après وَ, le a de al- tombe : wa-l-. Le dernier mot est lu sans sa voyelle finale.', 4, '{"id": "ar.l27.e20", "unitIds": ["ar.g27.voyelles_longues_mots_grecs", "ar.v.bulus", "ar.v.katholikon"], "type": "free_answer", "difficulty": 4, "instruction": "Écris ces deux lectures en lettres latines.", "prompt": "الْبُولُسُ وَالْكَاثُولِيكُونُ", "promptLanguage": "ar", "answer": "al-bûlusu wa-l-kâthûlîkûn", "acceptedAnswers": ["al-bûlusu wa-l-kâthûlîkûn", "albûlusu walkâthûlîkûn", "al bûlusu wa l kâthûlîkûn", "al-bulusu wa-l-kathulikun", "albulusu walkathulikun", "al bulusu wa l kathulikun", "al-buulusu wa-l-kaathuuliikuun", "albuulusu walkaathuuliikuun", "al buulusu wa l kaathuuliikuun", "al-bûlus wa-l-kâthûlîkûn", "albûlus walkâthûlîkûn", "al bûlus wa l kâthûlîkûn", "al-bulus wa-l-kathulikun", "albulus walkathulikun", "al bulus wa l kathulikun", "al-buulus wa-l-kaathuuliikuun", "albuulus walkaathuuliikuun", "al buulus wa l kaathuuliikuun", "al-bûlusu wal-kâthûlîkûn", "al bûlusu wal kâthûlîkûn", "al-bulusu wal-kathulikun", "al bulusu wal kathulikun", "al-buulusu wal-kaathuuliikuun", "al buulusu wal kaathuuliikuun", "al-bûlus wal-kâthûlîkûn", "al bûlus wal kâthûlîkûn", "al-bulus wal-kathulikun", "al bulus wal kathulikun", "al-buulus wal-kaathuuliikuun", "al buulus wal kaathuuliikuun", "al-bûlusu wa al-kâthûlîkûn", "albûlusu wa alkâthûlîkûn", "al bûlusu wa al kâthûlîkûn", "al-bulusu wa al-kathulikun", "albulusu wa alkathulikun", "al bulusu wa al kathulikun", "al-buulusu wa al-kaathuuliikuun", "albuulusu wa alkaathuuliikuun", "al buulusu wa al kaathuuliikuun", "al-bûlus wa al-kâthûlîkûn", "albûlus wa alkâthûlîkûn", "al bûlus wa al kâthûlîkûn", "al-bulus wa al-kathulikun", "albulus wa alkathulikun", "al bulus wa al kathulikun", "al-buulus wa al-kaathuuliikuun", "albuulus wa alkaathuuliikuun", "al buulus wa al kaathuuliikuun"], "hint": "Quatre voyelles longues dans le second mot : â, û, î, û.", "explanation": "الْبُولُسُ = al-bûlusu ; وَ = wa ; الْكَاثُولِيكُونُ = al-kâthûlîkûn (kâ, thû, lî, kûn). Après وَ, le a de al- tombe : wa-l-. Le dernier mot est lu sans sa voyelle finale.", "tip": "وَ + ال : wa-l-, le a disparaît.", "extraExample": {"text": "الْبُولُسُ وَالْإِبْرَكْسِيسُ", "translation": "le Paulus et l''Ibraksis", "transliteration": "al-bûlusu wa-l-ibraksîs"}, "errorPatterns": [{"contains": "katolikon", "category": "spelling", "feedback": "ث se note th et chaque voyelle longue doit être marquée : kâthûlîkûn."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l27.e21', 'ar', 'ar.l27', 'ar.v.quddas', array['ar.v.quddas','ar.g27.voyelles_longues_mots_grecs']::text[], 'free_answer', 'lesson', 'الْقُدَّاسُ الْإِلٰهِيُّ', array['la divine liturgie','la liturgie divine','divine liturgie','liturgie divine','la messe divine','la sainte liturgie']::text[], 'الْقُدَّاسُ = la messe, la liturgie ; الْإِلٰهِيُّ = divin. On dit « la divine liturgie ».', 2, '{"id": "ar.l27.e21", "unitIds": ["ar.v.quddas", "ar.g27.voyelles_longues_mots_grecs"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la traduction en français.", "prompt": "الْقُدَّاسُ الْإِلٰهِيُّ", "promptLanguage": "ar", "answer": "la divine liturgie", "acceptedAnswers": ["la divine liturgie", "la liturgie divine", "divine liturgie", "liturgie divine", "la messe divine", "la sainte liturgie"], "explanation": "الْقُدَّاسُ = la messe, la liturgie ; الْإِلٰهِيُّ = divin. On dit « la divine liturgie ».", "tip": "Le qoddâs est aussi appelé « la divine liturgie ».", "extraExample": {"text": "الْقُدَّاسُ فِي الْكَنِيسَةِ", "translation": "La messe est dans l''église.", "transliteration": "al-quddâsu fî l-kanîsa"}, "errorPatterns": [{"contains": "évangile", "category": "vocabulary", "feedback": "L''Évangile se dit الْإِنْجِيل. Ici, le premier mot est الْقُدَّاس, la liturgie."}], "pool": "lesson", "lessonId": "ar.l27", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e01', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.kitab_muqaddas']::text[], 'mcq', 'lesson', 'الْكِتَاب الْمُقَدَّس', array['al-kitâb al-muqaddas']::text[], 'كِتَاب = kitâb (livre). مُقَدَّس = muqaddas : la chadda double le د et la fatha qui suit donne « saint ». Les deux mots ont ال, tous deux lunaires : al- … al-. On lit al-kitâb al-muqaddas, « la Bible ».', 1, '{"id": "ar.l28.e01", "unitIds": ["ar.g28.nom_adjectif", "ar.v.kitab_muqaddas"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel groupe de mots est écrit ?", "prompt": "الْكِتَاب الْمُقَدَّس", "promptLanguage": "ar", "options": ["al-kitâb al-muqaddas", "al-kitâb al-muqadas", "al-kitâb al-muqaddis", "al-kutub al-muqaddas"], "answer": "al-kitâb al-muqaddas", "acceptedAnswers": ["al-kitâb al-muqaddas"], "explanation": "كِتَاب = kitâb (livre). مُقَدَّس = muqaddas : la chadda double le د et la fatha qui suit donne « saint ». Les deux mots ont ال, tous deux lunaires : al- … al-. On lit al-kitâb al-muqaddas, « la Bible ».", "tip": "Nom + adjectif, tous deux avec ال.", "extraExample": {"text": "الْإِنْجِيلُ فِي الْكِتَابِ الْمُقَدَّسِ", "translation": "L''Évangile est dans la Bible.", "transliteration": "al-indjîlu fî l-kitâbi l-muqaddas"}, "errorPatterns": [{"equals": "al-kitâb al-muqadas", "category": "spelling", "feedback": "Le د porte une chadda : muqaddas avec deux d."}, {"equals": "al-kitâb al-muqaddis", "category": "spelling", "feedback": "Sur le second د, c''est une fatha (a), pas une kasra : muqaddas, « rendu saint »."}, {"equals": "al-kutub al-muqaddas", "category": "spelling", "feedback": "كُتُب (kutub) est le pluriel « des livres ». Ici : كِتَاب avec un ا long."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e02', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.ahd_qadim']::text[], 'mcq', 'lesson', 'الْعَهْد الْقَدِيم', array['al-3ahd al-qadîm']::text[], 'ع et ق sont des lettres lunaires : on dit le l deux fois, al-3ahd al-qadîm. Le ـِي de قَدِيم est long. Mot à mot : « l''alliance l''ancienne », l''Ancien Testament.', 1, '{"id": "ar.l28.e02", "unitIds": ["ar.g28.nom_adjectif", "ar.v.ahd_qadim"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel groupe de mots est écrit ?", "prompt": "الْعَهْد الْقَدِيم", "promptLanguage": "ar", "options": ["al-3ahd al-qadîm", "al-3ahd aq-qadîm", "al-3ahd al-qadim", "al-3ahd al-djadîd"], "answer": "al-3ahd al-qadîm", "acceptedAnswers": ["al-3ahd al-qadîm"], "explanation": "ع et ق sont des lettres lunaires : on dit le l deux fois, al-3ahd al-qadîm. Le ـِي de قَدِيم est long. Mot à mot : « l''alliance l''ancienne », l''Ancien Testament.", "tip": "Deux ال avec soukoun : tu dis deux fois al-.", "extraExample": {"text": "الْمَزَامِيرُ فِي الْعَهْدِ الْقَدِيمِ", "translation": "Les Psaumes sont dans l''Ancien Testament.", "transliteration": "al-mazâmîru fî l-3ahdi l-qadîm"}, "errorPatterns": [{"equals": "al-3ahd aq-qadîm", "category": "grammar", "feedback": "ق est lunaire : le ل porte un soukoun et se dit, al-qadîm."}, {"equals": "al-3ahd al-qadim", "category": "spelling", "feedback": "Kasra + ي = î long : qadîm."}, {"equals": "al-3ahd al-djadîd", "category": "vocabulary", "feedback": "Le second mot commence par ق : c''est قَدِيم (ancien). جَدِيد (nouveau) commence par ج."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e03', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.nebowat']::text[], 'mcq', 'lesson', 'النُّبُوَّات', array['an-nubuwwât']::text[], 'ن est solaire : an-nu-… avec n doublé. Le و porte une chadda : nu-bu-wwât (deux w). La fin ـَات se lit â + t. On lit an-nubuwwât (en égyptien : « nebowat »).', 1, '{"id": "ar.l28.e03", "unitIds": ["ar.g28.nom_adjectif", "ar.v.nebowat"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "النُّبُوَّات", "promptLanguage": "ar", "options": ["an-nubuwwât", "al-nubuwwât", "an-nubuwat", "an-nubuwwat"], "answer": "an-nubuwwât", "acceptedAnswers": ["an-nubuwwât"], "explanation": "ن est solaire : an-nu-… avec n doublé. Le و porte une chadda : nu-bu-wwât (deux w). La fin ـَات se lit â + t. On lit an-nubuwwât (en égyptien : « nebowat »).", "tip": "Deux chaddas : une sur ن (article solaire), une sur و (deux w).", "extraExample": {"text": "النُّبُوَّاتُ كَثِيرَةٌ", "translation": "Les prophéties sont nombreuses.", "transliteration": "an-nubuwwâtu kathîra"}, "errorPatterns": [{"equals": "al-nubuwwât", "category": "grammar", "feedback": "ن est solaire : le l disparaît, an-nubuwwât."}, {"equals": "an-nubuwat", "category": "spelling", "feedback": "Le و est doublé (chadda) : nubuwwât."}, {"equals": "an-nubuwwat", "category": "spelling", "feedback": "Le ا avant le ت allonge : nubuwwât avec â."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e04', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.kitab_muqaddas','ar.v.ahd_qadim','ar.v.ahd_djadid','ar.v.nebowat','ar.v.nabi']::text[], 'match', 'lesson', 'La Bible et ses parties', '{}'::text[], 'La Bible (الْكِتَاب الْمُقَدَّس) se compose de l''Ancien et du Nouveau Testament. Les prophéties (النُّبُوَّات) sont lues dans l''Ancien Testament.', 1, '{"id": "ar.l28.e04", "unitIds": ["ar.g28.nom_adjectif", "ar.v.kitab_muqaddas", "ar.v.ahd_qadim", "ar.v.ahd_djadid", "ar.v.nebowat", "ar.v.nabi"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à sa traduction.", "prompt": "La Bible et ses parties", "promptLanguage": "fr", "pairs": [{"left": "الْكِتَاب الْمُقَدَّس", "right": "la Bible"}, {"left": "الْعَهْد الْقَدِيم", "right": "l''Ancien Testament"}, {"left": "الْعَهْد الْجَدِيد", "right": "le Nouveau Testament"}, {"left": "النُّبُوَّات", "right": "les prophéties"}, {"left": "نَبِيّ", "right": "prophète"}], "answer": "الْكِتَاب الْمُقَدَّس = la Bible ; الْعَهْد الْقَدِيم = l''Ancien Testament ; الْعَهْد الْجَدِيد = le Nouveau Testament ; النُّبُوَّات = les prophéties ; نَبِيّ = prophète", "acceptedAnswers": [], "explanation": "La Bible (الْكِتَاب الْمُقَدَّس) se compose de l''Ancien et du Nouveau Testament. Les prophéties (النُّبُوَّات) sont lues dans l''Ancien Testament.", "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e05', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.ahd_djadid']::text[], 'mcq', 'lesson', 'الْعَهْد الْجَدِيد', array['le Nouveau Testament']::text[], 'جَدِيد veut dire « nouveau » (leçon 23). Avec ال sur les deux mots, الْعَهْد الْجَدِيد est un nom : le Nouveau Testament.', 1, '{"id": "ar.l28.e05", "unitIds": ["ar.g28.nom_adjectif", "ar.v.ahd_djadid"], "type": "mcq", "difficulty": 1, "instruction": "Que veut dire ce groupe de mots ?", "prompt": "الْعَهْد الْجَدِيد", "promptLanguage": "ar", "options": ["le Nouveau Testament", "l''Ancien Testament", "la Bible", "l''Évangile"], "answer": "le Nouveau Testament", "acceptedAnswers": ["le Nouveau Testament"], "explanation": "جَدِيد veut dire « nouveau » (leçon 23). Avec ال sur les deux mots, الْعَهْد الْجَدِيد est un nom : le Nouveau Testament.", "tip": "جَدِيد = nouveau ; قَدِيم = ancien.", "extraExample": {"text": "بَيْتٌ جَدِيدٌ", "translation": "une maison neuve", "transliteration": "baytun djadîd"}, "errorPatterns": [{"equals": "l''Ancien Testament", "category": "vocabulary", "feedback": "L''Ancien Testament se dit الْعَهْد الْقَدِيم, avec ق."}, {"equals": "la Bible", "category": "vocabulary", "feedback": "La Bible entière se dit الْكِتَاب الْمُقَدَّس."}, {"equals": "l''Évangile", "category": "vocabulary", "feedback": "L''Évangile se dit الْإِنْجِيل ; il fait partie du Nouveau Testament."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e06', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.ahd_qadim']::text[], 'mcq', 'lesson', 'Quel groupe veut dire « l''Ancien Testament » ?', array['الْعَهْد الْقَدِيم']::text[], 'Le nom vient d''abord, puis l''adjectif, et les deux ont ال. Avec الْعَهْد قَدِيم, l''adjectif n''a pas ال : cela fait une phrase, « le testament est ancien ».', 2, '{"id": "ar.l28.e06", "unitIds": ["ar.g28.nom_adjectif", "ar.v.ahd_qadim"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne construction.", "prompt": "Quel groupe veut dire « l''Ancien Testament » ?", "promptLanguage": "fr", "options": ["الْعَهْد الْقَدِيم", "الْعَهْد قَدِيم", "عَهْد الْقَدِيم", "الْقَدِيم الْعَهْد"], "answer": "الْعَهْد الْقَدِيم", "acceptedAnswers": ["الْعَهْد الْقَدِيم"], "explanation": "Le nom vient d''abord, puis l''adjectif, et les deux ont ال. Avec الْعَهْد قَدِيم, l''adjectif n''a pas ال : cela fait une phrase, « le testament est ancien ».", "tip": "Nom défini → adjectif défini.", "extraExample": {"text": "الْكِتَاب الْمُقَدَّس", "translation": "la Bible", "transliteration": "al-kitâb al-muqaddas"}, "errorPatterns": [{"equals": "الْعَهْد قَدِيم", "category": "grammar", "feedback": "Sans ال sur l''adjectif, c''est une phrase : « le testament est ancien »."}, {"equals": "عَهْد الْقَدِيم", "category": "grammar", "feedback": "Le nom aussi doit avoir ال : الْعَهْد."}, {"equals": "الْقَدِيم الْعَهْد", "category": "word_order", "feedback": "En arabe, l''adjectif vient après le nom, jamais avant."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e07', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.kanisa']::text[], 'mcq', 'lesson', 'Comment dit-on « l''Église copte » ?', array['الْكَنِيسَة الْقِبْطِيَّة']::text[], 'كَنِيسَة est féminin (ة) : l''adjectif « copte » prend aussi la terminaison féminine, ـِيَّة (qibTiyya). Les deux mots ont ال. Lecture : al-kanîsa al-qibTiyya.', 2, '{"id": "ar.l28.e07", "unitIds": ["ar.g28.nom_adjectif", "ar.v.kanisa"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne construction.", "prompt": "Comment dit-on « l''Église copte » ?", "promptLanguage": "fr", "options": ["الْكَنِيسَة الْقِبْطِيَّة", "الْكَنِيسَة الْقِبْطِيّ", "الْكَنِيس الْقِبْطِيَّة", "الْقِبْطِيَّة كَنِيسَة"], "answer": "الْكَنِيسَة الْقِبْطِيَّة", "acceptedAnswers": ["الْكَنِيسَة الْقِبْطِيَّة"], "explanation": "كَنِيسَة est féminin (ة) : l''adjectif « copte » prend aussi la terminaison féminine, ـِيَّة (qibTiyya). Les deux mots ont ال. Lecture : al-kanîsa al-qibTiyya.", "tip": "Nom féminin → adjectif en ـَة.", "extraExample": {"text": "الْكَنِيسَة الْأُرْثُوذُكْسِيَّة", "translation": "l''Église orthodoxe", "transliteration": "al-kanîsa l-urthûdhuksiyya"}, "errorPatterns": [{"equals": "الْكَنِيسَة الْقِبْطِيّ", "category": "grammar", "feedback": "L''adjectif doit être féminin comme كَنِيسَة : الْقِبْطِيَّة."}, {"equals": "الْكَنِيس الْقِبْطِيَّة", "category": "vocabulary", "feedback": "الْكَنِيس (sans ة) est la synagogue ; l''église est الْكَنِيسَة."}, {"equals": "الْقِبْطِيَّة كَنِيسَة", "category": "word_order", "feedback": "Le nom vient d''abord, l''adjectif après."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e08', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.aya']::text[], 'mcq', 'lesson', 'Quel est le pluriel de آيَة (verset) ?', array['آيَات']::text[], 'Pour former ce pluriel, on retire le ة et on ajoute ـَات : آيَة → آيَات, comme أَيْقُونَة → أَيْقُونَات et نُبُوَّة → نُبُوَّات. Le آ (alif madda) reste.', 3, '{"id": "ar.l28.e08", "unitIds": ["ar.g28.nom_adjectif", "ar.v.aya"], "type": "mcq", "difficulty": 3, "instruction": "Forme le pluriel.", "prompt": "Quel est le pluriel de آيَة (verset) ?", "promptLanguage": "fr", "options": ["آيَات", "آيَتَات", "آيَاة", "أَيَات"], "answer": "آيَات", "acceptedAnswers": ["آيَات"], "explanation": "Pour former ce pluriel, on retire le ة et on ajoute ـَات : آيَة → آيَات, comme أَيْقُونَة → أَيْقُونَات et نُبُوَّة → نُبُوَّات. Le آ (alif madda) reste.", "tip": "Pluriel en -ât : on enlève ة, on ajoute ـَات.", "extraExample": {"text": "أَيْقُونَات", "translation": "des icônes", "transliteration": "ayqûnât"}, "errorPatterns": [{"equals": "آيَتَات", "category": "grammar", "feedback": "Il faut retirer le ة avant d''ajouter ـَات."}, {"equals": "آيَاة", "category": "spelling", "feedback": "La terminaison est ـَات (avec ت), pas ـَاة."}, {"equals": "أَيَات", "category": "spelling", "feedback": "Le début reste آ (alif madda) : â, pas a."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e09', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.ayquna','ar.g26.ta_marbuta_diphtongues']::text[], 'mcq', 'lesson', 'أَيْقُونَات', array['ayqûnât']::text[], 'Singulier أَيْقُونَة (ayqûna), pluriel أَيْقُونَات : ici le ت est une vraie lettre et se dit, après un â long : ayqûnât. أَيْ = ay, قُو = qû, نَا = nâ, ت.', 3, '{"id": "ar.l28.e09", "unitIds": ["ar.g28.nom_adjectif", "ar.v.ayquna", "ar.g26.ta_marbuta_diphtongues"], "type": "mcq", "difficulty": 3, "instruction": "Comment lit-on ce mot ?", "prompt": "أَيْقُونَات", "promptLanguage": "ar", "options": ["ayqûnât", "ayqûnat", "ayqunât", "ayqûna"], "answer": "ayqûnât", "acceptedAnswers": ["ayqûnât"], "explanation": "Singulier أَيْقُونَة (ayqûna), pluriel أَيْقُونَات : ici le ت est une vraie lettre et se dit, après un â long : ayqûnât. أَيْ = ay, قُو = qû, نَا = nâ, ت.", "tip": "ـَات : â long puis t.", "extraExample": {"text": "آيَات", "translation": "des versets", "transliteration": "âyât"}, "errorPatterns": [{"equals": "ayqûnat", "category": "spelling", "feedback": "Le fatha + ا donne un â long : nât, pas nat."}, {"equals": "ayqunât", "category": "spelling", "feedback": "Le و après la damma est long : qû."}, {"equals": "ayqûna", "category": "grammar", "feedback": "Le singulier se termine par ة. Ici il y a ـَات, avec un ت qui se dit."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e10', 'ar', 'ar.l28', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.nebowat','ar.g28.nom_adjectif']::text[], 'mcq', 'lesson', 'Pourquoi dit-on an-nubuwwât et non al-nubuwwât ?', array['Parce que ن est une lettre solaire']::text[], 'Révision de la leçon 25 : ن est solaire, donc le l de ال disparaît et le n est doublé. Le pluriel, le genre ou l''origine du mot n''y changent rien : c''est la première lettre après ال qui décide.', 3, '{"id": "ar.l28.e10", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.nebowat", "ar.g28.nom_adjectif"], "type": "mcq", "difficulty": 3, "instruction": "Pourquoi lit-on an-nubuwwât ?", "prompt": "Pourquoi dit-on an-nubuwwât et non al-nubuwwât ?", "promptLanguage": "fr", "options": ["Parce que ن est une lettre solaire", "Parce que le mot est au pluriel", "Parce que le mot est féminin", "Parce que le mot vient du grec"], "answer": "Parce que ن est une lettre solaire", "acceptedAnswers": ["Parce que ن est une lettre solaire"], "explanation": "Révision de la leçon 25 : ن est solaire, donc le l de ال disparaît et le n est doublé. Le pluriel, le genre ou l''origine du mot n''y changent rien : c''est la première lettre après ال qui décide.", "tip": "Première lettre après ال : solaire ou lunaire ?", "extraExample": {"text": "النَّبِيّ", "translation": "le prophète (ن solaire aussi)", "transliteration": "an-nabiyy"}, "errorPatterns": [{"equals": "Parce que le mot est au pluriel", "category": "grammar", "feedback": "Le nombre ne change pas la règle : seule la première lettre compte."}, {"equals": "Parce que le mot est féminin", "category": "grammar", "feedback": "Le genre ne change pas la règle : seule la première lettre compte."}, {"equals": "Parce que le mot vient du grec", "category": "grammar", "feedback": "نُبُوَّة n''est pas un mot grec ; et l''origine ne change pas la règle de ال."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e11', 'ar', 'ar.l28', 'ar.v.indjil', array['ar.v.indjil','ar.g28.nom_adjectif','ar.v.ahd_djadid']::text[], 'fill_blank', 'lesson', 'الْإِنْجِيلُ فِي ___', array['الْعَهْدِ الْجَدِيدِ']::text[], 'Les Évangiles font partie du Nouveau Testament : الْعَهْد الْجَدِيد. Nom et adjectif ont ال et se terminent tous deux par une kasra après فِي.', 3, '{"id": "ar.l28.e11", "unitIds": ["ar.v.indjil", "ar.g28.nom_adjectif", "ar.v.ahd_djadid"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « L''Évangile est dans le Nouveau Testament. »", "prompt": "الْإِنْجِيلُ فِي ___", "promptLanguage": "ar", "options": ["الْعَهْدِ الْجَدِيدِ", "الْعَهْدِ الْقَدِيمِ", "الْمَزَامِيرِ"], "answer": "الْعَهْدِ الْجَدِيدِ", "acceptedAnswers": ["الْعَهْدِ الْجَدِيدِ"], "explanation": "Les Évangiles font partie du Nouveau Testament : الْعَهْد الْجَدِيد. Nom et adjectif ont ال et se terminent tous deux par une kasra après فِي.", "tip": "Évangile = Nouveau Testament.", "extraExample": {"text": "الْإِنْجِيلُ فِي الْكِتَابِ الْمُقَدَّسِ", "translation": "L''Évangile est dans la Bible.", "transliteration": "al-indjîlu fî l-kitâbi l-muqaddas"}, "errorPatterns": [{"equals": "الْعَهْدِ الْقَدِيمِ", "category": "vocabulary", "feedback": "L''Ancien Testament précède la venue du Christ : les Évangiles sont dans le Nouveau."}, {"equals": "الْمَزَامِيرِ", "category": "vocabulary", "feedback": "Les Psaumes sont dans l''Ancien Testament ; l''Évangile n''y est pas."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e12', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.nebowat','ar.v.ahd_qadim']::text[], 'fill_blank', 'lesson', 'النُّبُوَّاتُ فِي ___', array['الْعَهْدِ الْقَدِيمِ']::text[], 'Les prophéties sont des lectures de l''Ancien Testament : الْعَهْد الْقَدِيم (« l''alliance l''ancienne »).', 3, '{"id": "ar.l28.e12", "unitIds": ["ar.g28.nom_adjectif", "ar.v.nebowat", "ar.v.ahd_qadim"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Les prophéties sont dans l''Ancien Testament. »", "prompt": "النُّبُوَّاتُ فِي ___", "promptLanguage": "ar", "options": ["الْعَهْدِ الْقَدِيمِ", "الْعَهْدِ الْجَدِيدِ", "الْإِنْجِيلِ"], "answer": "الْعَهْدِ الْقَدِيمِ", "acceptedAnswers": ["الْعَهْدِ الْقَدِيمِ"], "explanation": "Les prophéties sont des lectures de l''Ancien Testament : الْعَهْد الْقَدِيم (« l''alliance l''ancienne »).", "tip": "Prophéties = Ancien Testament.", "extraExample": {"text": "النَّبِيُّ دَاوُدُ فِي الْعَهْدِ الْقَدِيمِ", "translation": "Le prophète David est dans l''Ancien Testament.", "transliteration": "an-nabiyyu dâwudu fî l-3ahdi l-qadîm"}, "errorPatterns": [{"equals": "الْعَهْدِ الْجَدِيدِ", "category": "vocabulary", "feedback": "Les prophéties annoncent le Christ avant sa venue : elles sont dans l''Ancien Testament."}, {"equals": "الْإِنْجِيلِ", "category": "vocabulary", "feedback": "L''Évangile est un livre du Nouveau Testament, pas des prophéties."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e13', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.kitab_muqaddas']::text[], 'fill_blank', 'lesson', 'الْكِتَابُ ___', array['الْمُقَدَّسُ']::text[], '« La Bible » = nom + adjectif, tous deux avec ال et au masculin : الْكِتَابُ الْمُقَدَّسُ. Avec مُقَدَّسٌ (sans ال), on obtiendrait une phrase : « le livre est saint ».', 3, '{"id": "ar.l28.e13", "unitIds": ["ar.g28.nom_adjectif", "ar.v.kitab_muqaddas"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « la Bible » (nom + adjectif).", "prompt": "الْكِتَابُ ___", "promptLanguage": "ar", "options": ["الْمُقَدَّسُ", "مُقَدَّسٌ", "الْمُقَدَّسَةُ"], "answer": "الْمُقَدَّسُ", "acceptedAnswers": ["الْمُقَدَّسُ"], "explanation": "« La Bible » = nom + adjectif, tous deux avec ال et au masculin : الْكِتَابُ الْمُقَدَّسُ. Avec مُقَدَّسٌ (sans ال), on obtiendrait une phrase : « le livre est saint ».", "tip": "Même ال, même genre que le nom.", "extraExample": {"text": "الْعَهْدُ الْجَدِيدُ", "translation": "le Nouveau Testament", "transliteration": "al-3ahdu l-djadîd"}, "errorPatterns": [{"equals": "مُقَدَّسٌ", "category": "grammar", "feedback": "Sans ال, cela fait une phrase (« le livre est saint »), pas le nom « la Bible »."}, {"equals": "الْمُقَدَّسَةُ", "category": "grammar", "feedback": "كِتَاب est masculin : l''adjectif n''a pas de ة."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e14', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.ahd_qadim']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : les Psaumes / dans / l''Ancien Testament', array['الْمَزَامِيرُ فِي الْعَهْدِ الْقَدِيمِ']::text[], 'Le sujet vient d''abord (الْمَزَامِيرُ), puis فِي + le groupe nom + adjectif الْعَهْدِ الْقَدِيمِ : l''adjectif reste collé derrière son nom.', 3, '{"id": "ar.l28.e14", "unitIds": ["ar.g28.nom_adjectif", "ar.v.ahd_qadim"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Les Psaumes sont dans l''Ancien Testament. »", "prompt": "Remets dans l''ordre : les Psaumes / dans / l''Ancien Testament", "promptLanguage": "fr", "tokens": ["الْقَدِيمِ", "فِي", "الْمَزَامِيرُ", "الْعَهْدِ"], "answer": "الْمَزَامِيرُ فِي الْعَهْدِ الْقَدِيمِ", "acceptedAnswers": ["الْمَزَامِيرُ فِي الْعَهْدِ الْقَدِيمِ"], "explanation": "Le sujet vient d''abord (الْمَزَامِيرُ), puis فِي + le groupe nom + adjectif الْعَهْدِ الْقَدِيمِ : l''adjectif reste collé derrière son nom.", "tip": "L''adjectif suit toujours son nom.", "extraExample": {"text": "النُّبُوَّاتُ فِي الْعَهْدِ الْقَدِيمِ", "translation": "Les prophéties sont dans l''Ancien Testament.", "transliteration": "an-nubuwwâtu fî l-3ahdi l-qadîm"}, "pool": "lesson", "lessonId": "ar.l28", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e15', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.kitab_muqaddas','ar.v.indjil']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : l''Évangile / dans / la Bible', array['الْإِنْجِيلُ فِي الْكِتَابِ الْمُقَدَّسِ']::text[], 'Sujet (الْإِنْجِيلُ), puis فِي, puis le groupe nom + adjectif الْكِتَابِ الْمُقَدَّسِ, dans lequel l''adjectif suit son nom.', 3, '{"id": "ar.l28.e15", "unitIds": ["ar.g28.nom_adjectif", "ar.v.kitab_muqaddas", "ar.v.indjil"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « L''Évangile est dans la Bible. »", "prompt": "Remets dans l''ordre : l''Évangile / dans / la Bible", "promptLanguage": "fr", "tokens": ["الْمُقَدَّسِ", "الْإِنْجِيلُ", "الْكِتَابِ", "فِي"], "answer": "الْإِنْجِيلُ فِي الْكِتَابِ الْمُقَدَّسِ", "acceptedAnswers": ["الْإِنْجِيلُ فِي الْكِتَابِ الْمُقَدَّسِ"], "explanation": "Sujet (الْإِنْجِيلُ), puis فِي, puis le groupe nom + adjectif الْكِتَابِ الْمُقَدَّسِ, dans lequel l''adjectif suit son nom.", "tip": "Sujet, فِي, nom, adjectif.", "extraExample": {"text": "الْعَهْدُ الْجَدِيدُ فِي الْكِتَابِ الْمُقَدَّسِ", "translation": "Le Nouveau Testament est dans la Bible.", "transliteration": "al-3ahdu l-djadîdu fî l-kitâbi l-muqaddas"}, "pool": "lesson", "lessonId": "ar.l28", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e16', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.nabi']::text[], 'translation', 'lesson', 'النَّبِيُّ دَاوُدُ', array['Le prophète David','David le prophète','David, le prophète','Le prophète David.']::text[], 'النَّبِيُّ = le prophète ; دَاوُدُ = David. Ici le titre précède le nom, comme en français : « le prophète David ».', 2, '{"id": "ar.l28.e16", "unitIds": ["ar.g28.nom_adjectif", "ar.v.nabi"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "النَّبِيُّ دَاوُدُ", "promptLanguage": "ar", "answer": "Le prophète David", "acceptedAnswers": ["Le prophète David", "David le prophète", "David, le prophète", "Le prophète David."], "explanation": "النَّبِيُّ = le prophète ; دَاوُدُ = David. Ici le titre précède le nom, comme en français : « le prophète David ».", "tip": "Les titres comme نَبِيّ ou رَسُول se placent devant ou derrière le nom.", "extraExample": {"text": "النَّبِيُّ إِشَعْيَاءُ", "translation": "le prophète Isaïe", "transliteration": "an-nabiyyu icha3yâ''u"}, "errorPatterns": [{"contains": "apôtre", "category": "vocabulary", "feedback": "L''apôtre se dit رَسُول. Ici نَبِيّ est le prophète."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e17', 'ar', 'ar.l28', 'ar.v.indjil', array['ar.v.indjil','ar.g28.nom_adjectif','ar.v.aya']::text[], 'translation', 'lesson', 'هٰذِهِ آيَةٌ مِنَ الْإِنْجِيلِ', array['C''est un verset de l''Évangile.','Ceci est un verset de l''Évangile.','Voici un verset de l''Évangile.','C''est un verset tiré de l''Évangile.']::text[], 'هٰذِهِ = ceci, c''est (féminin, car آيَة est féminin) ; آيَةٌ = un verset ; مِنَ الْإِنْجِيلِ = de l''Évangile (مِنْ + ال : mina l-).', 3, '{"id": "ar.l28.e17", "unitIds": ["ar.v.indjil", "ar.g28.nom_adjectif", "ar.v.aya"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "هٰذِهِ آيَةٌ مِنَ الْإِنْجِيلِ", "promptLanguage": "ar", "answer": "C''est un verset de l''Évangile.", "acceptedAnswers": ["C''est un verset de l''Évangile.", "Ceci est un verset de l''Évangile.", "Voici un verset de l''Évangile.", "C''est un verset tiré de l''Évangile."], "explanation": "هٰذِهِ = ceci, c''est (féminin, car آيَة est féminin) ; آيَةٌ = un verset ; مِنَ الْإِنْجِيلِ = de l''Évangile (مِنْ + ال : mina l-).", "tip": "مِنْ = de, qui vient de.", "extraExample": {"text": "هٰذِهِ آيَةٌ جَمِيلَةٌ", "translation": "C''est un beau verset.", "transliteration": "hâdhihi âyatun djamîla"}, "errorPatterns": [{"contains": "chapitre", "category": "vocabulary", "feedback": "Le chapitre se dit أَصْحَاح. Ici آيَة est le verset."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e18', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.sifr','ar.v.aya','ar.v.ashah','ar.v.bichara']::text[], 'match', 'lesson', 'Les parties du texte biblique', '{}'::text[], 'Un livre de la Bible (سِفْر) se découpe en chapitres (أَصْحَاح), eux-mêmes en versets (آيَة). La بِشَارَة, c''est la « bonne nouvelle ».', 2, '{"id": "ar.l28.e18", "unitIds": ["ar.g28.nom_adjectif", "ar.v.sifr", "ar.v.aya", "ar.v.ashah", "ar.v.bichara"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Les parties du texte biblique", "promptLanguage": "fr", "pairs": [{"left": "سِفْر", "right": "livre (de la Bible)"}, {"left": "أَصْحَاح", "right": "chapitre"}, {"left": "آيَة", "right": "verset"}, {"left": "الْبِشَارَة", "right": "la bonne nouvelle (l''Annonciation)"}], "answer": "سِفْر = livre (de la Bible) ; أَصْحَاح = chapitre ; آيَة = verset ; الْبِشَارَة = la bonne nouvelle (l''Annonciation)", "acceptedAnswers": [], "explanation": "Un livre de la Bible (سِفْر) se découpe en chapitres (أَصْحَاح), eux-mêmes en versets (آيَة). La بِشَارَة, c''est la « bonne nouvelle ».", "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e19', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.nebowat','ar.v.ahd_djadid','ar.v.bichara','ar.v.ashah','ar.v.aya']::text[], 'match', 'lesson', 'Lecture éclair : cinq mots de la Bible', '{}'::text[], 'ـَات est un pluriel (nubuwwât, âyât) ; ال devant ن est solaire (an-) mais lunaire devant ع, ب (al-3ahd, al-bichâra).', 3, '{"id": "ar.l28.e19", "unitIds": ["ar.g28.nom_adjectif", "ar.v.nebowat", "ar.v.ahd_djadid", "ar.v.bichara", "ar.v.ashah", "ar.v.aya"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lecture éclair : cinq mots de la Bible", "promptLanguage": "fr", "pairs": [{"left": "النُّبُوَّات", "right": "an-nubuwwât"}, {"left": "الْعَهْد الْجَدِيد", "right": "al-3ahd al-djadîd"}, {"left": "الْبِشَارَة", "right": "al-bichâra"}, {"left": "أَصْحَاح", "right": "aS7â7"}, {"left": "آيَات", "right": "âyât"}], "answer": "النُّبُوَّات = an-nubuwwât ; الْعَهْد الْجَدِيد = al-3ahd al-djadîd ; الْبِشَارَة = al-bichâra ; أَصْحَاح = aS7â7 ; آيَات = âyât", "acceptedAnswers": [], "explanation": "ـَات est un pluriel (nubuwwât, âyât) ; ال devant ن est solaire (an-) mais lunaire devant ع, ب (al-3ahd, al-bichâra).", "pool": "lesson", "lessonId": "ar.l28", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e20', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.nebowat']::text[], 'free_answer', 'lesson', 'النُّبُوَّاتُ', array['an-nubuwwât','annubuwwât','an nubuwwât','an-nubuwwat','annubuwwat','an nubuwwat','an-nubuwwaat','annubuwwaat','an nubuwwaat','an-nubuwwâtu','annubuwwâtu','an nubuwwâtu','an-nubuwwatu','annubuwwatu','an nubuwwatu','an-nubuwwaatu','annubuwwaatu','an nubuwwaatu','an-nebowat','annebowat','an nebowat','nebowat','en-nebowat','ennebowat','en nebowat','el-nebowat','elnebowat','el nebowat']::text[], 'ن est solaire : an-nubuwwât. La chadda sur و double le w, et ـَات donne â + t. En Égypte, on prononce « nebowat ».', 3, '{"id": "ar.l28.e20", "unitIds": ["ar.g28.nom_adjectif", "ar.v.nebowat"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ce mot en lettres latines.", "prompt": "النُّبُوَّاتُ", "promptLanguage": "ar", "answer": "an-nubuwwât", "acceptedAnswers": ["an-nubuwwât", "annubuwwât", "an nubuwwât", "an-nubuwwat", "annubuwwat", "an nubuwwat", "an-nubuwwaat", "annubuwwaat", "an nubuwwaat", "an-nubuwwâtu", "annubuwwâtu", "an nubuwwâtu", "an-nubuwwatu", "annubuwwatu", "an nubuwwatu", "an-nubuwwaatu", "annubuwwaatu", "an nubuwwaatu", "an-nebowat", "annebowat", "an nebowat", "nebowat", "en-nebowat", "ennebowat", "en nebowat", "el-nebowat", "elnebowat", "el nebowat"], "hint": "La chadda sur le و double le w.", "explanation": "ن est solaire : an-nubuwwât. La chadda sur و double le w, et ـَات donne â + t. En Égypte, on prononce « nebowat ».", "tip": "Deux chaddas à repérer : n et w.", "extraExample": {"text": "نُبُوَّات", "translation": "des prophéties (sans l''article) : nubuwwât", "transliteration": "nubuwwât"}, "errorPatterns": [{"equals": "al-nubuwwât", "category": "grammar", "feedback": "ن est solaire : écris an-nubuwwât."}, {"equals": "an-nubuwat", "category": "spelling", "feedback": "Le و est doublé : nubuwwât."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l28.e21', 'ar', 'ar.l28', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.ahd_djadid']::text[], 'free_answer', 'lesson', 'عَهْدٌ جَدِيدٌ', array['une nouvelle alliance','une alliance nouvelle','un nouveau testament','un testament nouveau','nouvelle alliance','un nouveau pacte']::text[], 'Sans ال sur aucun des deux mots, عَهْدٌ جَدِيدٌ est un groupe indéfini : « une alliance nouvelle ». Avec ال sur les deux (الْعَهْد الْجَدِيد), il devient le nom du Nouveau Testament.', 4, '{"id": "ar.l28.e21", "unitIds": ["ar.g28.nom_adjectif", "ar.v.ahd_djadid"], "type": "free_answer", "difficulty": 4, "instruction": "Écris la traduction en français.", "prompt": "عَهْدٌ جَدِيدٌ", "promptLanguage": "ar", "answer": "une nouvelle alliance", "acceptedAnswers": ["une nouvelle alliance", "une alliance nouvelle", "un nouveau testament", "un testament nouveau", "nouvelle alliance", "un nouveau pacte"], "explanation": "Sans ال sur aucun des deux mots, عَهْدٌ جَدِيدٌ est un groupe indéfini : « une alliance nouvelle ». Avec ال sur les deux (الْعَهْد الْجَدِيد), il devient le nom du Nouveau Testament.", "tip": "Sans ال = « un/une… » ; avec ال sur les deux = nom précis.", "extraExample": {"text": "الْعَهْد الْجَدِيد", "translation": "le Nouveau Testament", "transliteration": "al-3ahd al-djadîd"}, "errorPatterns": [{"contains": "le nouveau testament", "category": "grammar", "feedback": "Sans ال, c''est un groupe indéfini : « une alliance nouvelle ». Le Nouveau Testament demande ال sur les deux mots."}], "pool": "lesson", "lessonId": "ar.l28", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e01', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.eid_al_milad','ar.v.eid']::text[], 'mcq', 'lesson', 'عِيد الْمِيلَاد', array['3îd al-mîlâd']::text[], 'عِيد = 3îd (kasra + ي = î long). الْمِيلَاد = al-mî-lâd, deux voyelles longues, م lunaire. Le premier mot n''a pas d''article : c''est une annexion, « la fête de la Nativité ».', 1, '{"id": "ar.l29.e01", "unitIds": ["ar.g29.idafa", "ar.v.eid_al_milad", "ar.v.eid"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel groupe de mots est écrit ?", "prompt": "عِيد الْمِيلَاد", "promptLanguage": "ar", "options": ["3îd al-mîlâd", "3îd al-milâd", "3ayd al-mîlâd", "al-3îd al-mîlâd"], "answer": "3îd al-mîlâd", "acceptedAnswers": ["3îd al-mîlâd"], "explanation": "عِيد = 3îd (kasra + ي = î long). الْمِيلَاد = al-mî-lâd, deux voyelles longues, م lunaire. Le premier mot n''a pas d''article : c''est une annexion, « la fête de la Nativité ».", "tip": "Annexion : le premier mot n''a pas ال.", "extraExample": {"text": "عِيدُ الْكَنِيسَةِ", "translation": "la fête de l''église", "transliteration": "3îdu l-kanîsa"}, "errorPatterns": [{"equals": "3îd al-milâd", "category": "spelling", "feedback": "Kasra + ي = î long : mîlâd."}, {"equals": "3ayd al-mîlâd", "category": "spelling", "feedback": "Le ي suit une kasra, il n''a pas de soukoun : c''est un î long, pas la diphtongue ay."}, {"equals": "al-3îd al-mîlâd", "category": "grammar", "feedback": "Dans une annexion, le premier nom n''a jamais ال : c''est 3îd."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e02', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.eid_al_qiyama']::text[], 'mcq', 'lesson', 'عِيد الْقِيَامَة', array['3îd al-qiyâma']::text[], 'قِيَامَة se coupe en trois : qi (kasra), yâ (fatha + ا = â long), ma + le ة final qui se lit a. Le ق est lunaire : al-qiyâma. En fin de groupe, ة = a.', 1, '{"id": "ar.l29.e02", "unitIds": ["ar.g29.idafa", "ar.v.eid_al_qiyama"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel groupe de mots est écrit ?", "prompt": "عِيد الْقِيَامَة", "promptLanguage": "ar", "options": ["3îd al-qiyâma", "3îd al-qiyama", "3îd aq-qiyâma", "3îd al-qiyâmat"], "answer": "3îd al-qiyâma", "acceptedAnswers": ["3îd al-qiyâma"], "explanation": "قِيَامَة se coupe en trois : qi (kasra), yâ (fatha + ا = â long), ma + le ة final qui se lit a. Le ق est lunaire : al-qiyâma. En fin de groupe, ة = a.", "tip": "ة à la fin du groupe : a.", "extraExample": {"text": "عِيدُ الْقِيَامَةِ الْمَجِيدُ", "translation": "la glorieuse fête de la Résurrection", "transliteration": "3îdu l-qiyâmati l-madjîd"}, "errorPatterns": [{"equals": "3îd al-qiyama", "category": "spelling", "feedback": "Le ا après يَ allonge la voyelle : yâ."}, {"equals": "3îd aq-qiyâma", "category": "grammar", "feedback": "ق est lunaire : on dit le l, al-qiyâma."}, {"equals": "3îd al-qiyâmat", "category": "grammar", "feedback": "Le t n''apparaît que si un mot suit directement. En fin de groupe, ة = a."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e03', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.eid','ar.v.eid_al_milad','ar.v.eid_al_qiyama','ar.v.ghitas','ar.v.ahad_al_chaanin']::text[], 'match', 'lesson', 'Les grandes fêtes', '{}'::text[], 'Presque tous les noms de fêtes commencent par عِيد. Le Baptême du Christ, الْغِطَاس, a un nom particulier ; les Rameaux se disent « dimanche des Hosannas ».', 1, '{"id": "ar.l29.e03", "unitIds": ["ar.g29.idafa", "ar.v.eid", "ar.v.eid_al_milad", "ar.v.eid_al_qiyama", "ar.v.ghitas", "ar.v.ahad_al_chaanin"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Les grandes fêtes", "promptLanguage": "fr", "pairs": [{"left": "عِيد", "right": "fête"}, {"left": "عِيد الْمِيلَاد", "right": "Noël (la Nativité)"}, {"left": "عِيد الْقِيَامَة", "right": "Pâques (la Résurrection)"}, {"left": "الْغِطَاس", "right": "l''Épiphanie (le Baptême du Christ)"}, {"left": "أَحَد الشَّعَانِين", "right": "le dimanche des Rameaux"}], "answer": "عِيد = fête ; عِيد الْمِيلَاد = Noël (la Nativité) ; عِيد الْقِيَامَة = Pâques (la Résurrection) ; الْغِطَاس = l''Épiphanie (le Baptême du Christ) ; أَحَد الشَّعَانِين = le dimanche des Rameaux", "acceptedAnswers": [], "explanation": "Presque tous les noms de fêtes commencent par عِيد. Le Baptême du Christ, الْغِطَاس, a un nom particulier ; les Rameaux se disent « dimanche des Hosannas ».", "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e04', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.sawm_kabir','ar.v.sawm']::text[], 'mcq', 'lesson', 'الصَّوْم الْكَبِير', array['aS-Sawm al-kabîr']::text[], 'ص est solaire : aS-S… (le l tombe, le S est doublé). ـَوْ est la diphtongue aw. Le second ال est lunaire (ك) : al-kabîr, avec un î long. On lit aS-Sawm al-kabîr, « le Grand Carême ».', 2, '{"id": "ar.l29.e04", "unitIds": ["ar.g29.idafa", "ar.v.sawm_kabir", "ar.v.sawm"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel groupe de mots est écrit ?", "prompt": "الصَّوْم الْكَبِير", "promptLanguage": "ar", "options": ["aS-Sawm al-kabîr", "al-Sawm al-kabîr", "aS-Sûm al-kabîr", "aS-Sawm al-kabir"], "answer": "aS-Sawm al-kabîr", "acceptedAnswers": ["aS-Sawm al-kabîr"], "explanation": "ص est solaire : aS-S… (le l tombe, le S est doublé). ـَوْ est la diphtongue aw. Le second ال est lunaire (ك) : al-kabîr, avec un î long. On lit aS-Sawm al-kabîr, « le Grand Carême ».", "tip": "Un article solaire (aS-), un article lunaire (al-).", "extraExample": {"text": "هٰذَا هُوَ الصَّوْمُ الْكَبِيرُ", "translation": "Voici le Grand Carême.", "transliteration": "hâdhâ huwa S-Sawmu l-kabîr"}, "errorPatterns": [{"equals": "al-Sawm al-kabîr", "category": "grammar", "feedback": "ص est solaire : la chadda double le S et le l ne se dit pas."}, {"equals": "aS-Sûm al-kabîr", "category": "spelling", "feedback": "Le و porte un soukoun après une fatha : c''est aw, pas û."}, {"equals": "aS-Sawm al-kabir", "category": "spelling", "feedback": "Kasra + ي = î long : kabîr."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e05', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.usbu_al_alam']::text[], 'mcq', 'lesson', 'أُسْبُوع الْآلَام', array['usbû3 al-âlâm']::text[], 'أُسْبُوع = us-bû-3 (damma + و = û long). الْآلَام : le آ (alif madda) vaut ''â, puis lâ (fatha + ا) et m : al-âlâm, « les souffrances ». Annexion : « semaine des souffrances ».', 2, '{"id": "ar.l29.e05", "unitIds": ["ar.g29.idafa", "ar.v.usbu_al_alam"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel groupe de mots est écrit ?", "prompt": "أُسْبُوع الْآلَام", "promptLanguage": "ar", "options": ["usbû3 al-âlâm", "usbu3 al-âlâm", "usbû3 al-alâm", "usbû3 al-âlam"], "answer": "usbû3 al-âlâm", "acceptedAnswers": ["usbû3 al-âlâm"], "explanation": "أُسْبُوع = us-bû-3 (damma + و = û long). الْآلَام : le آ (alif madda) vaut ''â, puis lâ (fatha + ا) et m : al-âlâm, « les souffrances ». Annexion : « semaine des souffrances ».", "tip": "Compte les voyelles longues : bû, puis â et lâ.", "extraExample": {"text": "أُسْبُوعُ الْآلَامِ قَبْلَ عِيدِ الْقِيَامَةِ", "translation": "La Semaine sainte précède Pâques.", "transliteration": "usbû3u l-âlâmi qabla 3îdi l-qiyâma"}, "errorPatterns": [{"equals": "usbu3 al-âlâm", "category": "spelling", "feedback": "Damma + و = û long : bû."}, {"equals": "usbû3 al-alâm", "category": "spelling", "feedback": "La madda de آ allonge : al-âlâm, avec un â."}, {"equals": "usbû3 al-âlam", "category": "spelling", "feedback": "Il y a un ا après لَ : lâm avec â long."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e06', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.g28.nom_adjectif']::text[], 'mcq', 'lesson', 'Dans lequel de ces groupes y a-t-il une annexion (iDâfa) ?', array['عِيد الْمِيلَاد']::text[], 'Dans une annexion, seul le second nom a ال : عِيد الْمِيلَاد. Les trois autres groupes ont ال sur les deux mots : ce sont des noms suivis d''un adjectif (الْكَبِير, الْجَدِيد, الْمُقَدَّس).', 2, '{"id": "ar.l29.e06", "unitIds": ["ar.g29.idafa", "ar.g28.nom_adjectif"], "type": "mcq", "difficulty": 2, "instruction": "Observe le premier mot de chaque groupe.", "prompt": "Dans lequel de ces groupes y a-t-il une annexion (iDâfa) ?", "promptLanguage": "fr", "options": ["عِيد الْمِيلَاد", "الصَّوْم الْكَبِير", "الْعَهْد الْجَدِيد", "الْكِتَاب الْمُقَدَّس"], "answer": "عِيد الْمِيلَاد", "acceptedAnswers": ["عِيد الْمِيلَاد"], "explanation": "Dans une annexion, seul le second nom a ال : عِيد الْمِيلَاد. Les trois autres groupes ont ال sur les deux mots : ce sont des noms suivis d''un adjectif (الْكَبِير, الْجَدِيد, الْمُقَدَّس).", "tip": "ال sur le seul 2e mot = annexion ; ال sur les deux = adjectif.", "extraExample": {"text": "أُسْبُوع الْآلَام", "translation": "une autre annexion : semaine de la Passion", "transliteration": "usbû3 al-âlâm"}, "errorPatterns": [{"equals": "الصَّوْم الْكَبِير", "category": "grammar", "feedback": "Ici ال est sur les deux mots, et الْكَبِير est un adjectif : « le Grand Carême »."}, {"equals": "الْعَهْد الْجَدِيد", "category": "grammar", "feedback": "ال sur les deux mots : nom + adjectif (جَدِيد = nouveau)."}, {"equals": "الْكِتَاب الْمُقَدَّس", "category": "grammar", "feedback": "ال sur les deux mots : nom + adjectif (مُقَدَّس = saint)."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e07', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.eid']::text[], 'mcq', 'lesson', 'Pourquoi عِيد n''a-t-il pas ال dans عِيد الْمِيلَاد ?', array['Dans une annexion, le premier nom n''a jamais ال']::text[], 'C''est le second nom (الْمِيلَاد) qui rend le groupe précis. Le premier reste « nu », sans ال ni tanwîn. Il n''est ni au pluriel ni solaire (ع est lunaire), et عِيد est un nom, pas un adjectif.', 3, '{"id": "ar.l29.e07", "unitIds": ["ar.g29.idafa", "ar.v.eid"], "type": "mcq", "difficulty": 3, "instruction": "Pourquoi cette forme ?", "prompt": "Pourquoi عِيد n''a-t-il pas ال dans عِيد الْمِيلَاد ?", "promptLanguage": "fr", "options": ["Dans une annexion, le premier nom n''a jamais ال", "Parce qu''il est au pluriel", "Parce que ع est une lettre solaire", "Parce que c''est un adjectif"], "answer": "Dans une annexion, le premier nom n''a jamais ال", "acceptedAnswers": ["Dans une annexion, le premier nom n''a jamais ال"], "explanation": "C''est le second nom (الْمِيلَاد) qui rend le groupe précis. Le premier reste « nu », sans ال ni tanwîn. Il n''est ni au pluriel ni solaire (ع est lunaire), et عِيد est un nom, pas un adjectif.", "tip": "Le premier nom est toujours nu.", "extraExample": {"text": "عِيدُ الْغِطَاسِ", "translation": "la fête de l''Épiphanie", "transliteration": "3îdu l-ghiTâs"}, "errorPatterns": [{"equals": "Parce qu''il est au pluriel", "category": "grammar", "feedback": "عِيد est au singulier ; le pluriel est أَعْيَاد."}, {"equals": "Parce que ع est une lettre solaire", "category": "grammar", "feedback": "ع est lunaire (al-3îd) ; le rôle de ال n''a rien à voir ici."}, {"equals": "Parce que c''est un adjectif", "category": "grammar", "feedback": "عِيد est un nom (« fête »), pas un adjectif."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e08', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.ghitas']::text[], 'mcq', 'lesson', 'الْغِطَاس', array['al-ghiTâs']::text[], 'غِ = ghi (kasra), طَا = Tâ (fatha + ا = â long), س. غ est lunaire : al-ghiTâs. Le ط (un rond avec une barre) est emphatique : T.', 2, '{"id": "ar.l29.e08", "unitIds": ["ar.g29.idafa", "ar.v.ghitas"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "الْغِطَاس", "promptLanguage": "ar", "options": ["al-ghiTâs", "al-ghiTas", "al-ghuTâs", "al-ghiDâs"], "answer": "al-ghiTâs", "acceptedAnswers": ["al-ghiTâs"], "explanation": "غِ = ghi (kasra), طَا = Tâ (fatha + ا = â long), س. غ est lunaire : al-ghiTâs. Le ط (un rond avec une barre) est emphatique : T.", "tip": "غ (un point) = gh ; ط (sans point) = T.", "extraExample": {"text": "عِيدُ الْغِطَاسِ", "translation": "la fête de l''Épiphanie", "transliteration": "3îdu l-ghiTâs"}, "errorPatterns": [{"equals": "al-ghiTas", "category": "spelling", "feedback": "Le ا après طَ allonge la voyelle : Tâs."}, {"equals": "al-ghuTâs", "category": "spelling", "feedback": "La voyelle sous le غ est une kasra : ghi."}, {"equals": "al-ghiDâs", "category": "spelling", "feedback": "ط (sans point) se note T ; ض (avec un point) se note D."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e09', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.ahad_al_chaanin','ar.v.usbu_al_alam']::text[], 'mcq', 'lesson', 'Quel dimanche ouvre la Semaine sainte ?', array['أَحَد الشَّعَانِين']::text[], 'Le dimanche des Rameaux (أَحَد الشَّعَانِين) rappelle l''entrée de Jésus à Jérusalem et ouvre la Semaine sainte (أُسْبُوع الْآلَام), qui mène à Pâques.', 3, '{"id": "ar.l29.e09", "unitIds": ["ar.g29.idafa", "ar.v.ahad_al_chaanin", "ar.v.usbu_al_alam"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne fête.", "prompt": "Quel dimanche ouvre la Semaine sainte ?", "promptLanguage": "fr", "options": ["أَحَد الشَّعَانِين", "عِيد الْمِيلَاد", "الْغِطَاس", "الْخَمَاسِين"], "answer": "أَحَد الشَّعَانِين", "acceptedAnswers": ["أَحَد الشَّعَانِين"], "explanation": "Le dimanche des Rameaux (أَحَد الشَّعَانِين) rappelle l''entrée de Jésus à Jérusalem et ouvre la Semaine sainte (أُسْبُوع الْآلَام), qui mène à Pâques.", "tip": "Rameaux → Semaine sainte → Pâques.", "extraExample": {"text": "أُسْبُوع الْآلَام", "translation": "la Semaine sainte", "transliteration": "usbû3 al-âlâm"}, "errorPatterns": [{"equals": "عِيد الْمِيلَاد", "category": "vocabulary", "feedback": "Noël est la fête de la Nativité, bien avant la Semaine sainte."}, {"equals": "الْغِطَاس", "category": "vocabulary", "feedback": "L''Épiphanie est le Baptême du Christ, en janvier."}, {"equals": "الْخَمَاسِين", "category": "vocabulary", "feedback": "Les Cinquante jours viennent après Pâques, pas avant."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e10', 'ar', 'ar.l29', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.ahad_al_chaanin']::text[], 'mcq', 'lesson', 'الشَّعَانِين', array['ach-cha3ânîn']::text[], 'Révision de ال : ش est solaire (chadda), donc ach-ch…, le l tombe. Puis ع (3), ânî : عَا (3â, long), نِي (nî, long), ن. On lit ach-cha3ânîn.', 3, '{"id": "ar.l29.e10", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.ahad_al_chaanin"], "type": "mcq", "difficulty": 3, "instruction": "Comment lit-on ce mot ?", "prompt": "الشَّعَانِين", "promptLanguage": "ar", "options": ["ach-cha3ânîn", "al-cha3ânîn", "ach-cha3anin", "as-sa3ânîn"], "answer": "ach-cha3ânîn", "acceptedAnswers": ["ach-cha3ânîn"], "explanation": "Révision de ال : ش est solaire (chadda), donc ach-ch…, le l tombe. Puis ع (3), ânî : عَا (3â, long), نِي (nî, long), ن. On lit ach-cha3ânîn.", "tip": "Chadda après ال : pas de l ; ش = ch.", "extraExample": {"text": "الشَّمْس", "translation": "le soleil : ach-chams", "transliteration": "ach-chams"}, "errorPatterns": [{"equals": "al-cha3ânîn", "category": "grammar", "feedback": "ش est solaire : la chadda double le ch, le l ne se dit pas."}, {"equals": "ach-cha3anin", "category": "spelling", "feedback": "Deux voyelles longues : 3â et nî."}, {"equals": "as-sa3ânîn", "category": "spelling", "feedback": "ش (trois points) se note ch, pas s."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e11', 'ar', 'ar.l29', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.sawm_kabir']::text[], 'fill_blank', 'lesson', 'الصَّوْم ___', array['الْكَبِير']::text[], 'Révision de la leçon 28 : nom défini + adjectif défini. صَوْم est masculin, donc l''adjectif aussi (pas de ة) et il reprend ال : الصَّوْم الْكَبِير.', 2, '{"id": "ar.l29.e11", "unitIds": ["ar.g28.nom_adjectif", "ar.v.sawm_kabir"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « le Grand Carême ».", "prompt": "الصَّوْم ___", "promptLanguage": "ar", "options": ["الْكَبِير", "كَبِيرٌ", "الْكَبِيرَة"], "answer": "الْكَبِير", "acceptedAnswers": ["الْكَبِير"], "explanation": "Révision de la leçon 28 : nom défini + adjectif défini. صَوْم est masculin, donc l''adjectif aussi (pas de ة) et il reprend ال : الصَّوْم الْكَبِير.", "tip": "Nom avec ال → adjectif avec ال, même genre.", "extraExample": {"text": "الْعَهْد الْجَدِيد", "translation": "le Nouveau Testament", "transliteration": "al-3ahd al-djadîd"}, "errorPatterns": [{"equals": "كَبِيرٌ", "category": "grammar", "feedback": "Sans ال, ce serait une phrase : « le jeûne est grand ». Pour le nom du Carême, il faut ال."}, {"equals": "الْكَبِيرَة", "category": "grammar", "feedback": "صَوْم est masculin : l''adjectif n''a pas de ة."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e12', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.eid','ar.v.eid_al_qiyama']::text[], 'fill_blank', 'lesson', '___ الْقِيَامَة', array['عِيد']::text[], 'Dans une annexion, le premier nom reste nu : pas de ال (الْعِيد) et pas de tanwîn (عِيدٌ). Le second nom, الْقِيَامَة, porte ال : عِيد الْقِيَامَة.', 3, '{"id": "ar.l29.e12", "unitIds": ["ar.g29.idafa", "ar.v.eid", "ar.v.eid_al_qiyama"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « la fête de la Résurrection ».", "prompt": "___ الْقِيَامَة", "promptLanguage": "ar", "options": ["عِيد", "الْعِيد", "عِيدٌ"], "answer": "عِيد", "acceptedAnswers": ["عِيد"], "explanation": "Dans une annexion, le premier nom reste nu : pas de ال (الْعِيد) et pas de tanwîn (عِيدٌ). Le second nom, الْقِيَامَة, porte ال : عِيد الْقِيَامَة.", "tip": "Premier nom d''une annexion : ni ال, ni tanwîn.", "extraExample": {"text": "عِيد الْمِيلَاد", "translation": "la fête de la Nativité", "transliteration": "3îd al-mîlâd"}, "errorPatterns": [{"equals": "الْعِيد", "category": "grammar", "feedback": "Le premier nom d''une annexion n''a jamais ال."}, {"equals": "عِيدٌ", "category": "grammar", "feedback": "Le tanwîn (ـٌ) ne se met pas sur le premier nom d''une annexion."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e13', 'ar', 'ar.l29', 'ar.v.khamasin', array['ar.v.khamasin','ar.g29.idafa','ar.v.eid_al_qiyama']::text[], 'fill_blank', 'lesson', 'الْخَمَاسِينُ بَعْدَ عِيدِ ___', array['الْقِيَامَةِ']::text[], 'Les Cinquante jours (الْخَمَاسِين) s''étendent de Pâques à la Pentecôte : ils viennent après عِيد الْقِيَامَة. Le second nom de l''annexion se termine par une kasra.', 3, '{"id": "ar.l29.e13", "unitIds": ["ar.v.khamasin", "ar.g29.idafa", "ar.v.eid_al_qiyama"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Les Cinquante jours viennent après Pâques. »", "prompt": "الْخَمَاسِينُ بَعْدَ عِيدِ ___", "promptLanguage": "ar", "options": ["الْقِيَامَةِ", "الْغِطَاسِ", "الْمِيلَادِ"], "answer": "الْقِيَامَةِ", "acceptedAnswers": ["الْقِيَامَةِ"], "explanation": "Les Cinquante jours (الْخَمَاسِين) s''étendent de Pâques à la Pentecôte : ils viennent après عِيد الْقِيَامَة. Le second nom de l''annexion se termine par une kasra.", "tip": "Khamasin = les 50 jours après Pâques.", "extraExample": {"text": "الْخَمَاسِينُ فَرَحٌ", "translation": "Les Cinquante jours sont une joie.", "transliteration": "al-khamâsînu fara7"}, "errorPatterns": [{"equals": "الْغِطَاسِ", "category": "vocabulary", "feedback": "L''Épiphanie est en janvier ; les Cinquante jours suivent Pâques."}, {"equals": "الْمِيلَادِ", "category": "vocabulary", "feedback": "Noël est en janvier ; les Cinquante jours suivent Pâques."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e14', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.eid_al_qiyama','ar.v.usbu_al_alam']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : Pâques / après / la Semaine sainte', array['عِيدُ الْقِيَامَةِ بَعْدَ أُسْبُوعِ الْآلَامِ','بَعْدَ أُسْبُوعِ الْآلَامِ عِيدُ الْقِيَامَةِ']::text[], 'Deux annexions séparées par بَعْدَ (après) : عِيدُ الْقِيَامَةِ puis أُسْبُوعِ الْآلَامِ. Chaque annexion forme un bloc : le premier nom reste collé au second.', 3, '{"id": "ar.l29.e14", "unitIds": ["ar.g29.idafa", "ar.v.eid_al_qiyama", "ar.v.usbu_al_alam"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Pâques vient après la Semaine sainte. »", "prompt": "Remets dans l''ordre : Pâques / après / la Semaine sainte", "promptLanguage": "fr", "tokens": ["بَعْدَ", "أُسْبُوعِ", "الْقِيَامَةِ", "عِيدُ", "الْآلَامِ"], "answer": "عِيدُ الْقِيَامَةِ بَعْدَ أُسْبُوعِ الْآلَامِ", "acceptedAnswers": ["عِيدُ الْقِيَامَةِ بَعْدَ أُسْبُوعِ الْآلَامِ", "بَعْدَ أُسْبُوعِ الْآلَامِ عِيدُ الْقِيَامَةِ"], "explanation": "Deux annexions séparées par بَعْدَ (après) : عِيدُ الْقِيَامَةِ puis أُسْبُوعِ الْآلَامِ. Chaque annexion forme un bloc : le premier nom reste collé au second.", "tip": "Une annexion ne se sépare jamais : les deux noms restent côte à côte.", "extraExample": {"text": "أُسْبُوعُ الْآلَامِ قَبْلَ عِيدِ الْقِيَامَةِ", "translation": "La Semaine sainte précède Pâques.", "transliteration": "usbû3u l-âlâmi qabla 3îdi l-qiyâma"}, "pool": "lesson", "lessonId": "ar.l29", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e15', 'ar', 'ar.l29', 'ar.v.nebowat', array['ar.v.nebowat','ar.g29.idafa','ar.v.usbu_al_alam']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : les prophéties / dans / la Semaine sainte', array['النُّبُوَّاتُ فِي أُسْبُوعِ الْآلَامِ']::text[], 'Révision : النُّبُوَّاتُ (an-nubuwwât) ouvre le groupe, puis فِي et l''annexion أُسْبُوعِ الْآلَامِ, dont les deux noms restent côte à côte.', 3, '{"id": "ar.l29.e15", "unitIds": ["ar.v.nebowat", "ar.g29.idafa", "ar.v.usbu_al_alam"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Les prophéties de la Semaine sainte. »", "prompt": "Remets dans l''ordre : les prophéties / dans / la Semaine sainte", "promptLanguage": "fr", "tokens": ["أُسْبُوعِ", "فِي", "الْآلَامِ", "النُّبُوَّاتُ"], "answer": "النُّبُوَّاتُ فِي أُسْبُوعِ الْآلَامِ", "acceptedAnswers": ["النُّبُوَّاتُ فِي أُسْبُوعِ الْآلَامِ"], "explanation": "Révision : النُّبُوَّاتُ (an-nubuwwât) ouvre le groupe, puis فِي et l''annexion أُسْبُوعِ الْآلَامِ, dont les deux noms restent côte à côte.", "tip": "Annexion = un bloc de deux noms.", "extraExample": {"text": "النُّبُوَّاتُ فِي الْعَهْدِ الْقَدِيمِ", "translation": "Les prophéties sont dans l''Ancien Testament.", "transliteration": "an-nubuwwâtu fî l-3ahdi l-qadîm"}, "pool": "lesson", "lessonId": "ar.l29", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e16', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.eid_al_milad']::text[], 'translation', 'lesson', 'عِيدُ الْمِيلَادِ الْمَجِيدُ', array['La glorieuse fête de la Nativité','La glorieuse fête de Noël','La fête glorieuse de la Nativité','La fête glorieuse de Noël','La fête de la Nativité glorieuse','La glorieuse Nativité']::text[], 'عِيدُ الْمِيلَادِ = la fête de la Nativité (annexion) ; الْمَجِيدُ = glorieux. L''adjectif qualifie « fête » (عِيد), le premier nom, et prend ال pour le reprendre : c''est la formule des vœux.', 2, '{"id": "ar.l29.e16", "unitIds": ["ar.g29.idafa", "ar.v.eid_al_milad"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "عِيدُ الْمِيلَادِ الْمَجِيدُ", "promptLanguage": "ar", "answer": "La glorieuse fête de la Nativité", "acceptedAnswers": ["La glorieuse fête de la Nativité", "La glorieuse fête de Noël", "La fête glorieuse de la Nativité", "La fête glorieuse de Noël", "La fête de la Nativité glorieuse", "La glorieuse Nativité"], "explanation": "عِيدُ الْمِيلَادِ = la fête de la Nativité (annexion) ; الْمَجِيدُ = glorieux. L''adjectif qualifie « fête » (عِيد), le premier nom, et prend ال pour le reprendre : c''est la formule des vœux.", "tip": "الْمَجِيد = glorieux, souvent dit pour Noël et Pâques.", "extraExample": {"text": "عِيدُ الْقِيَامَةِ الْمَجِيدُ", "translation": "la glorieuse fête de la Résurrection", "transliteration": "3îdu l-qiyâmati l-madjîd"}, "errorPatterns": [{"contains": "pâques", "category": "vocabulary", "feedback": "Pâques se dit عِيد الْقِيَامَة. Ici : الْمِيلَاد, la Nativité (Noël)."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e17', 'ar', 'ar.l29', 'ar.g26.ta_marbuta_diphtongues', array['ar.g26.ta_marbuta_diphtongues','ar.v.kanisa','ar.g29.idafa']::text[], 'translation', 'lesson', 'هٰذَا عِيدُ الْكَنِيسَةِ', array['C''est la fête de l''église.','Ceci est la fête de l''église.','Voici la fête de l''église.']::text[], 'هٰذَا = c''est ; عِيدُ الْكَنِيسَةِ = la fête de l''église (annexion). Révision de la leçon 26 : الْكَنِيسَة = l''église.', 3, '{"id": "ar.l29.e17", "unitIds": ["ar.g26.ta_marbuta_diphtongues", "ar.v.kanisa", "ar.g29.idafa"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "هٰذَا عِيدُ الْكَنِيسَةِ", "promptLanguage": "ar", "answer": "C''est la fête de l''église.", "acceptedAnswers": ["C''est la fête de l''église.", "Ceci est la fête de l''église.", "Voici la fête de l''église."], "explanation": "هٰذَا = c''est ; عِيدُ الْكَنِيسَةِ = la fête de l''église (annexion). Révision de la leçon 26 : الْكَنِيسَة = l''église.", "tip": "هٰذَا + annexion : « c''est la fête de… ».", "extraExample": {"text": "هٰذَا عِيدُ الْمِيلَادِ", "translation": "C''est la fête de la Nativité.", "transliteration": "hâdhâ 3îdu l-mîlâd"}, "errorPatterns": [{"contains": "maison", "category": "vocabulary", "feedback": "La maison se dit بَيْت. L''église est كَنِيسَة."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e18', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.sawm_kabir','ar.v.usbu_al_alam','ar.v.khamasin','ar.v.sawm']::text[], 'match', 'lesson', 'Les temps de l''année copte', '{}'::text[], 'Avant Pâques : le Grand Carême puis la Semaine sainte. Après Pâques : les Cinquante jours, sans jeûne. صَوْم est le mot général pour « jeûne ».', 2, '{"id": "ar.l29.e18", "unitIds": ["ar.g29.idafa", "ar.v.sawm_kabir", "ar.v.usbu_al_alam", "ar.v.khamasin", "ar.v.sawm"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Les temps de l''année copte", "promptLanguage": "fr", "pairs": [{"left": "الصَّوْم الْكَبِير", "right": "le Grand Carême"}, {"left": "أُسْبُوع الْآلَام", "right": "la Semaine sainte"}, {"left": "الْخَمَاسِين", "right": "les cinquante jours après Pâques"}, {"left": "صَوْم", "right": "jeûne"}], "answer": "الصَّوْم الْكَبِير = le Grand Carême ; أُسْبُوع الْآلَام = la Semaine sainte ; الْخَمَاسِين = les cinquante jours après Pâques ; صَوْم = jeûne", "acceptedAnswers": [], "explanation": "Avant Pâques : le Grand Carême puis la Semaine sainte. Après Pâques : les Cinquante jours, sans jeûne. صَوْم est le mot général pour « jeûne ».", "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e19', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.eid_al_milad','ar.v.ghitas','ar.v.ahad_al_chaanin','ar.v.khamasin','ar.v.sawm']::text[], 'match', 'lesson', 'Lecture éclair : cinq mots du calendrier', '{}'::text[], 'Lis chaque mot par blocs : mî-lâd, ghi-Tâs, cha-3â-nîn, kha-mâ-sîn. ـَوْ dans صَوْم est la diphtongue aw.', 3, '{"id": "ar.l29.e19", "unitIds": ["ar.g29.idafa", "ar.v.eid_al_milad", "ar.v.ghitas", "ar.v.ahad_al_chaanin", "ar.v.khamasin", "ar.v.sawm"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lecture éclair : cinq mots du calendrier", "promptLanguage": "fr", "pairs": [{"left": "عِيد الْمِيلَاد", "right": "3îd al-mîlâd"}, {"left": "الْغِطَاس", "right": "al-ghiTâs"}, {"left": "أَحَد الشَّعَانِين", "right": "a7ad ach-cha3ânîn"}, {"left": "الْخَمَاسِين", "right": "al-khamâsîn"}, {"left": "صَوْم", "right": "Sawm"}], "answer": "عِيد الْمِيلَاد = 3îd al-mîlâd ; الْغِطَاس = al-ghiTâs ; أَحَد الشَّعَانِين = a7ad ach-cha3ânîn ; الْخَمَاسِين = al-khamâsîn ; صَوْم = Sawm", "acceptedAnswers": [], "explanation": "Lis chaque mot par blocs : mî-lâd, ghi-Tâs, cha-3â-nîn, kha-mâ-sîn. ـَوْ dans صَوْم est la diphtongue aw.", "pool": "lesson", "lessonId": "ar.l29", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e20', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.ahad_al_chaanin']::text[], 'free_answer', 'lesson', 'أَحَد الشَّعَانِين', array['a7ad ach-cha3ânîn','a7ad achcha3ânîn','a7ad ach cha3ânîn','a7ad ach-cha3anin','a7ad achcha3anin','a7ad ach cha3anin','a7ad ach-cha3aaniin','a7ad achcha3aaniin','a7ad ach cha3aaniin','ahad ach-cha3ânîn','ahad achcha3ânîn','ahad ach cha3ânîn','ahad ach-cha3anin','ahad achcha3anin','ahad ach cha3anin','ahad ach-cha3aaniin','ahad achcha3aaniin','ahad ach cha3aaniin','a7ad ach-chaanin','a7ad achchaanin','a7ad ach chaanin','ahad ach-chaanin','ahad achchaanin','ahad ach chaanin','a7ad ash-sha3anin','a7ad ashsha3anin','a7ad ash sha3anin','ahad ash-shaanin','ahad ashshaanin','ahad ash shaanin']::text[], 'أَحَد = a7ad (ح = 7). الشَّعَانِين : ش solaire, donc ach-cha3ânîn, avec deux voyelles longues (3â et nî).', 4, '{"id": "ar.l29.e20", "unitIds": ["ar.g29.idafa", "ar.v.ahad_al_chaanin"], "type": "free_answer", "difficulty": 4, "instruction": "Écris ce groupe de mots en lettres latines.", "prompt": "أَحَد الشَّعَانِين", "promptLanguage": "ar", "answer": "a7ad ach-cha3ânîn", "acceptedAnswers": ["a7ad ach-cha3ânîn", "a7ad achcha3ânîn", "a7ad ach cha3ânîn", "a7ad ach-cha3anin", "a7ad achcha3anin", "a7ad ach cha3anin", "a7ad ach-cha3aaniin", "a7ad achcha3aaniin", "a7ad ach cha3aaniin", "ahad ach-cha3ânîn", "ahad achcha3ânîn", "ahad ach cha3ânîn", "ahad ach-cha3anin", "ahad achcha3anin", "ahad ach cha3anin", "ahad ach-cha3aaniin", "ahad achcha3aaniin", "ahad ach cha3aaniin", "a7ad ach-chaanin", "a7ad achchaanin", "a7ad ach chaanin", "ahad ach-chaanin", "ahad achchaanin", "ahad ach chaanin", "a7ad ash-sha3anin", "a7ad ashsha3anin", "a7ad ash sha3anin", "ahad ash-shaanin", "ahad ashshaanin", "ahad ash shaanin"], "hint": "ح se note 7 ; ش se note ch.", "explanation": "أَحَد = a7ad (ح = 7). الشَّعَانِين : ش solaire, donc ach-cha3ânîn, avec deux voyelles longues (3â et nî).", "tip": "Un article solaire : la chadda double le ch.", "extraExample": {"text": "هٰذَا أَحَدُ الشَّعَانِينِ", "translation": "C''est le dimanche des Rameaux.", "transliteration": "hâdhâ a7adu ch-cha3ânîn"}, "errorPatterns": [{"equals": "a7ad al-cha3ânîn", "category": "grammar", "feedback": "ش est solaire : écris ach-cha3ânîn."}, {"equals": "a7ad al-cha3anin", "category": "grammar", "feedback": "ش est solaire : le l ne se dit pas, ach-cha3ânîn."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l29.e21', 'ar', 'ar.l29', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.ghitas','ar.v.eid']::text[], 'free_answer', 'lesson', 'عِيدُ الْغِطَاسِ', array['la fête de l''Épiphanie','fête de l''Épiphanie','l''Épiphanie','la fête du Baptême','la fête du Baptême de Jésus','la fête du Baptême du Christ','la fête de la Théophanie','la Théophanie']::text[], 'عِيدُ = la fête de (annexion) ; الْغِطَاسِ = l''Épiphanie, le Baptême du Christ. Le nom vient de غَطَسَ, « plonger ».', 3, '{"id": "ar.l29.e21", "unitIds": ["ar.g29.idafa", "ar.v.ghitas", "ar.v.eid"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la traduction en français.", "prompt": "عِيدُ الْغِطَاسِ", "promptLanguage": "ar", "answer": "la fête de l''Épiphanie", "acceptedAnswers": ["la fête de l''Épiphanie", "fête de l''Épiphanie", "l''Épiphanie", "la fête du Baptême", "la fête du Baptême de Jésus", "la fête du Baptême du Christ", "la fête de la Théophanie", "la Théophanie"], "explanation": "عِيدُ = la fête de (annexion) ; الْغِطَاسِ = l''Épiphanie, le Baptême du Christ. Le nom vient de غَطَسَ, « plonger ».", "tip": "Ghitas = le Baptême (plongée dans l''eau).", "extraExample": {"text": "عِيدُ الْغِطَاسِ بَعْدَ عِيدِ الْمِيلَادِ", "translation": "L''Épiphanie vient après Noël.", "transliteration": "3îdu l-ghiTâsi ba3da 3îdi l-mîlâd"}, "errorPatterns": [{"contains": "noël", "category": "vocabulary", "feedback": "Noël est عِيد الْمِيلَاد. Ici le second mot est الْغِطَاس : l''Épiphanie, le Baptême."}], "pool": "lesson", "lessonId": "ar.l29", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e01', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.qiddis']::text[], 'mcq', 'lesson', 'قِدِّيس', array['qiddîs']::text[], 'قِ = qi, دِّي = ddî : le د porte une chadda (deux d) et le ي après la kasra est long. Puis س. On lit qid-dîs, « saint ».', 1, '{"id": "ar.l30.e01", "unitIds": ["ar.g30.chadda_hamza", "ar.v.qiddis"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "قِدِّيس", "promptLanguage": "ar", "options": ["qiddîs", "qidîs", "qaddîs", "qiddis"], "answer": "qiddîs", "acceptedAnswers": ["qiddîs"], "explanation": "قِ = qi, دِّي = ddî : le د porte une chadda (deux d) et le ي après la kasra est long. Puis س. On lit qid-dîs, « saint ».", "tip": "Chadda sur le د : deux d. Ensuite, î long.", "extraExample": {"text": "الْقِدِّيسُ مَرْقُسُ الرَّسُولُ", "translation": "saint Marc l''apôtre", "transliteration": "al-qiddîsu marqusu r-rasûl"}, "errorPatterns": [{"equals": "qidîs", "category": "spelling", "feedback": "La chadda double le د : qid-dîs, avec deux d."}, {"equals": "qaddîs", "category": "spelling", "feedback": "Sous le ق il y a une kasra : qi, pas qa."}, {"equals": "qiddis", "category": "spelling", "feedback": "Kasra + ي = î long : dîs."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e02', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.chammas']::text[], 'mcq', 'lesson', 'شَمَّاس', array['chammâs']::text[], 'شَ = cha, مَّا = mmâ : le م porte une chadda (deux m) et le ا qui suit est long. Puis س. On lit cham-mâs, « diacre ».', 1, '{"id": "ar.l30.e02", "unitIds": ["ar.g30.chadda_hamza", "ar.v.chammas"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "شَمَّاس", "promptLanguage": "ar", "options": ["chammâs", "chamâs", "chammas", "chimmâs"], "answer": "chammâs", "acceptedAnswers": ["chammâs"], "explanation": "شَ = cha, مَّا = mmâ : le م porte une chadda (deux m) et le ا qui suit est long. Puis س. On lit cham-mâs, « diacre ».", "tip": "Chadda sur le م : deux m ; ا : â long.", "extraExample": {"text": "الشَّمَّاسُ وَالْكَاهِنُ", "translation": "le diacre et le prêtre", "transliteration": "ach-chammâsu wa-l-kâhin"}, "errorPatterns": [{"equals": "chamâs", "category": "spelling", "feedback": "La chadda double le م : cham-mâs."}, {"equals": "chammas", "category": "spelling", "feedback": "Le ا final est long : mâs."}, {"equals": "chimmâs", "category": "spelling", "feedback": "Sous le ش il y a une fatha : cha."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e03', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.qiddis','ar.v.chahid','ar.v.adhra_maryam','ar.v.mar_marqus','ar.v.mar_girgis']::text[], 'match', 'lesson', 'Saints et saintes', '{}'::text[], 'قِدِّيس est le mot général pour « saint » ; شَهِيد est le martyr. مَار, devant un nom, signifie « saint » : مَار مَرْقُس, مَار جِرْجِس.', 1, '{"id": "ar.l30.e03", "unitIds": ["ar.g30.chadda_hamza", "ar.v.qiddis", "ar.v.chahid", "ar.v.adhra_maryam", "ar.v.mar_marqus", "ar.v.mar_girgis"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Saints et saintes", "promptLanguage": "fr", "pairs": [{"left": "قِدِّيس", "right": "saint"}, {"left": "شَهِيد", "right": "martyr"}, {"left": "الْعَذْرَاء مَرْيَم", "right": "la Vierge Marie"}, {"left": "مَار مَرْقُس", "right": "saint Marc"}, {"left": "مَار جِرْجِس", "right": "saint Georges"}], "answer": "قِدِّيس = saint ; شَهِيد = martyr ; الْعَذْرَاء مَرْيَم = la Vierge Marie ; مَار مَرْقُس = saint Marc ; مَار جِرْجِس = saint Georges", "acceptedAnswers": [], "explanation": "قِدِّيس est le mot général pour « saint » ; شَهِيد est le martyr. مَار, devant un nom, signifie « saint » : مَار مَرْقُس, مَار جِرْجِس.", "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e04', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.adhra_maryam','ar.g14.hamza_madda']::text[], 'mcq', 'lesson', 'الْعَذْرَاء', array['al-3adhrâ''']::text[], 'عَ = 3a, ذْ = dh (soukoun), رَا = râ (â long), puis le ء final : un petit coup de glotte, noté ''. Le ع est lunaire : al-3adhrâ''.', 2, '{"id": "ar.l30.e04", "unitIds": ["ar.g30.chadda_hamza", "ar.v.adhra_maryam", "ar.g14.hamza_madda"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "الْعَذْرَاء", "promptLanguage": "ar", "options": ["al-3adhrâ''", "al-3adhrâ", "al-3adrâ''", "al-3idhrâ''"], "answer": "al-3adhrâ''", "acceptedAnswers": ["al-3adhrâ''"], "explanation": "عَ = 3a, ذْ = dh (soukoun), رَا = râ (â long), puis le ء final : un petit coup de glotte, noté ''. Le ع est lunaire : al-3adhrâ''.", "tip": "ء seul à la fin = petit arrêt de la gorge.", "extraExample": {"text": "أَيْقُونَةُ الْعَذْرَاءِ مَرْيَمَ", "translation": "l''icône de la Vierge Marie", "transliteration": "ayqûnatu l-3adhrâ''i maryam"}, "errorPatterns": [{"equals": "al-3adhrâ", "category": "spelling", "feedback": "Il y a une hamza (ء) à la fin : on l''entend comme un petit arrêt, 3adhrâ''."}, {"equals": "al-3adrâ''", "category": "spelling", "feedback": "ذ (un point) se note dh, pas d."}, {"equals": "al-3idhrâ''", "category": "spelling", "feedback": "Sous le ع, c''est une fatha : 3a."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e05', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.chahid']::text[], 'mcq', 'lesson', 'الشُّهَدَاء', array['ach-chuhadâ''']::text[], 'C''est le pluriel de شَهِيد : « les martyrs ». ش est solaire (ach-), le ش porte la damma (chu), puis هَ, دَا (â long) et la hamza finale : ach-chuhadâ''.', 3, '{"id": "ar.l30.e05", "unitIds": ["ar.g30.chadda_hamza", "ar.v.chahid"], "type": "mcq", "difficulty": 3, "instruction": "Lis vite : quel mot est écrit ?", "prompt": "الشُّهَدَاء", "promptLanguage": "ar", "options": ["ach-chuhadâ''", "al-chuhadâ''", "ach-chuhada", "ach-chahidâ''"], "answer": "ach-chuhadâ''", "acceptedAnswers": ["ach-chuhadâ''"], "explanation": "C''est le pluriel de شَهِيد : « les martyrs ». ش est solaire (ach-), le ش porte la damma (chu), puis هَ, دَا (â long) et la hamza finale : ach-chuhadâ''.", "tip": "Pluriel en ـَاء : â long puis hamza.", "extraExample": {"text": "تَقْوِيمُ الشُّهَدَاءِ", "translation": "le calendrier des Martyrs", "transliteration": "taqwîmu ch-chuhadâ''"}, "errorPatterns": [{"equals": "al-chuhadâ''", "category": "grammar", "feedback": "ش est solaire : le l ne se dit pas, ach-chuhadâ''."}, {"equals": "ach-chuhada", "category": "spelling", "feedback": "Garde la hamza finale : un petit coup de glotte après le â long."}, {"equals": "ach-chahidâ''", "category": "spelling", "feedback": "Ce pluriel n''a pas de ي : شُهَدَاء se lit chuhadâ'' (u, a, â)."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e06', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.chammas','ar.v.usquf','ar.v.rahib','ar.v.baba']::text[], 'mcq', 'lesson', 'Qui assiste le prêtre à l''autel et conduit les réponses du peuple ?', array['شَمَّاس']::text[], 'Le شَمَّاس est le diacre : il sert à l''autel et dirige les réponses. L''évêque (أُسْقُف) est un chef de diocèse, le moine (رَاهِب) vit au monastère, le pape (الْبَابَا) est le patriarche.', 2, '{"id": "ar.l30.e06", "unitIds": ["ar.g30.chadda_hamza", "ar.v.chammas", "ar.v.usquf", "ar.v.rahib", "ar.v.baba"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Qui assiste le prêtre à l''autel et conduit les réponses du peuple ?", "promptLanguage": "fr", "options": ["شَمَّاس", "أُسْقُف", "رَاهِب", "الْبَابَا"], "answer": "شَمَّاس", "acceptedAnswers": ["شَمَّاس"], "explanation": "Le شَمَّاس est le diacre : il sert à l''autel et dirige les réponses. L''évêque (أُسْقُف) est un chef de diocèse, le moine (رَاهِب) vit au monastère, le pape (الْبَابَا) est le patriarche.", "tip": "Chammâs = diacre (celui qui sert).", "extraExample": {"text": "الشَّمَّاسُ فِي الْهَيْكَلِ", "translation": "Le diacre est dans le sanctuaire.", "transliteration": "ach-chammâsu fî l-haykal"}, "errorPatterns": [{"equals": "أُسْقُف", "category": "vocabulary", "feedback": "أُسْقُف est l''évêque, qui dirige un diocèse."}, {"equals": "رَاهِب", "category": "vocabulary", "feedback": "رَاهِب est le moine, qui vit au monastère."}, {"equals": "الْبَابَا", "category": "vocabulary", "feedback": "الْبَابَا est le pape, chef de l''Église copte."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e07', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.mar_girgis']::text[], 'mcq', 'lesson', 'مَار جِرْجِس', array['mâr djirdjis']::text[], 'مَار = mâr (fatha + ا long), جِرْجِس = djir-djis : deux kasras brèves, le ر avec soukoun. En Égypte, on prononce le ج comme un g : « Mari Girgis ».', 2, '{"id": "ar.l30.e07", "unitIds": ["ar.g30.chadda_hamza", "ar.v.mar_girgis"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quel groupe de mots est écrit ?", "prompt": "مَار جِرْجِس", "promptLanguage": "ar", "options": ["mâr djirdjis", "mâr djardjis", "mâr djirdjîs", "mâr djirdjas"], "answer": "mâr djirdjis", "acceptedAnswers": ["mâr djirdjis"], "explanation": "مَار = mâr (fatha + ا long), جِرْجِس = djir-djis : deux kasras brèves, le ر avec soukoun. En Égypte, on prononce le ج comme un g : « Mari Girgis ».", "tip": "Deux syllabes : djir-djis.", "extraExample": {"text": "كَنِيسَةُ مَارْ جِرْجِسَ", "translation": "l''église de saint Georges", "transliteration": "kanîsatu mâr djirdjisa"}, "errorPatterns": [{"equals": "mâr djardjis", "category": "spelling", "feedback": "Sous le ج il y a une kasra : dji."}, {"equals": "mâr djirdjîs", "category": "spelling", "feedback": "Le dernier ي manque : la kasra est brève, djis."}, {"equals": "mâr djirdjas", "category": "spelling", "feedback": "Sous le س il y a une kasra : djis."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e08', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.chammas']::text[], 'mcq', 'lesson', 'Combien de chaddas y a-t-il dans الشَّمَّاس ?', array['2']::text[], 'Une chadda sur le ش (article solaire : ach-) et une sur le م (le mot lui-même, cham-mâs). Cela fait deux consonnes doublées : ach-chammâs.', 3, '{"id": "ar.l30.e08", "unitIds": ["ar.g30.chadda_hamza", "ar.v.chammas"], "type": "mcq", "difficulty": 3, "instruction": "Compte les chaddas.", "prompt": "Combien de chaddas y a-t-il dans الشَّمَّاس ?", "promptLanguage": "fr", "options": ["2", "1", "3", "0"], "answer": "2", "acceptedAnswers": ["2"], "explanation": "Une chadda sur le ش (article solaire : ach-) et une sur le م (le mot lui-même, cham-mâs). Cela fait deux consonnes doublées : ach-chammâs.", "tip": "ال solaire ajoute une chadda à celle du mot.", "extraExample": {"text": "الشَّمْس", "translation": "le soleil : une seule chadda, ach-chams", "transliteration": "ach-chams"}, "errorPatterns": [{"equals": "1", "category": "grammar", "feedback": "Regarde aussi le م : il porte une chadda lui aussi."}, {"equals": "3", "category": "grammar", "feedback": "Il y en a deux : sur ش et sur م."}, {"equals": "0", "category": "grammar", "feedback": "Les chaddas sont bien là : sur ش et sur م."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e09', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.adhra_maryam','ar.g14.hamza_madda']::text[], 'mcq', 'lesson', 'Quelle est la dernière lettre de الْعَذْرَاء ?', array['ء (une hamza seule)']::text[], 'Après le ا long, le mot se termine par ء, une hamza écrite seule sur la ligne. Elle se prononce comme un petit coup de glotte : al-3adhrâ''.', 2, '{"id": "ar.l30.e09", "unitIds": ["ar.g30.chadda_hamza", "ar.v.adhra_maryam", "ar.g14.hamza_madda"], "type": "mcq", "difficulty": 2, "instruction": "Observe la fin du mot.", "prompt": "Quelle est la dernière lettre de الْعَذْرَاء ?", "promptLanguage": "fr", "options": ["ء (une hamza seule)", "ا (un alif)", "ة (un tâ marbûta)", "ي (un yâ'')"], "answer": "ء (une hamza seule)", "acceptedAnswers": ["ء (une hamza seule)"], "explanation": "Après le ا long, le mot se termine par ء, une hamza écrite seule sur la ligne. Elle se prononce comme un petit coup de glotte : al-3adhrâ''.", "tip": "ء = hamza ; elle ne dépend d''aucun support.", "extraExample": {"text": "نِسَاء", "translation": "femmes : nisâ''", "transliteration": "nisâ''"}, "errorPatterns": [{"equals": "ا (un alif)", "category": "spelling", "feedback": "Le ا est l''avant-dernière lettre (qui allonge le â). La dernière est la hamza."}, {"equals": "ة (un tâ marbûta)", "category": "spelling", "feedback": "Le ة porte deux points sur un rond : il n''y en a pas ici."}, {"equals": "ي (un yâ'')", "category": "spelling", "feedback": "Il n''y a pas de ي dans ce mot."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e10', 'ar', 'ar.l30', 'ar.g29.idafa', array['ar.g29.idafa','ar.g26.ta_marbuta_diphtongues','ar.v.mar_girgis']::text[], 'mcq', 'lesson', 'Dans l''annexion كَنِيسَةُ مَارْ جِرْجِسَ, comment se lit le ة de كَنِيسَة ?', array['t : kanîsatu mâr djirdjisa']::text[], 'Révision : dans une annexion, le premier nom est suivi directement du second, et son ة se lit t : kanîsatu mâr djirdjisa. Le a seul ne vaut qu''à la fin d''un groupe.', 3, '{"id": "ar.l30.e10", "unitIds": ["ar.g29.idafa", "ar.g26.ta_marbuta_diphtongues", "ar.v.mar_girgis"], "type": "mcq", "difficulty": 3, "instruction": "Observe l''annexion.", "prompt": "Dans l''annexion كَنِيسَةُ مَارْ جِرْجِسَ, comment se lit le ة de كَنِيسَة ?", "promptLanguage": "fr", "options": ["t : kanîsatu mâr djirdjisa", "a : kanîsa mâr djirdjisa", "h : kanîsah mâr djirdjisa", "n : kanîsan mâr djirdjisa"], "answer": "t : kanîsatu mâr djirdjisa", "acceptedAnswers": ["t : kanîsatu mâr djirdjisa"], "explanation": "Révision : dans une annexion, le premier nom est suivi directement du second, et son ة se lit t : kanîsatu mâr djirdjisa. Le a seul ne vaut qu''à la fin d''un groupe.", "tip": "ة devant un autre mot = t.", "extraExample": {"text": "كَنِيسَةُ مَارْ مَرْقُسَ", "translation": "l''église de saint Marc", "transliteration": "kanîsatu mâr marqusa"}, "errorPatterns": [{"equals": "a : kanîsa mâr djirdjisa", "category": "grammar", "feedback": "Le ة se dit a seulement à la fin d''un groupe. Ici, un autre mot suit : t."}, {"equals": "h : kanîsah mâr djirdjisa", "category": "grammar", "feedback": "On ne note pas de h : devant un mot, le ة se dit t."}, {"equals": "n : kanîsan mâr djirdjisa", "category": "grammar", "feedback": "Le n appartiendrait à un tanwîn (ـٌ) ; dans une annexion, il n''y a pas de tanwîn."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e11', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.qiddis','ar.v.mar_girgis']::text[], 'fill_blank', 'lesson', 'الْقِدِّيسُ ___', array['جِرْجِسُ']::text[], '« Saint Georges » = الْقِدِّيسُ جِرْجِسُ (ou مَارْ جِرْجِسُ). مَرْيَم est une femme : on dirait الْقِدِّيسَةُ مَرْيَمُ.', 2, '{"id": "ar.l30.e11", "unitIds": ["ar.g30.chadda_hamza", "ar.v.qiddis", "ar.v.mar_girgis"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « saint Georges ».", "prompt": "الْقِدِّيسُ ___", "promptLanguage": "ar", "options": ["جِرْجِسُ", "مَرْيَمُ", "الْبَابَا"], "answer": "جِرْجِسُ", "acceptedAnswers": ["جِرْجِسُ"], "explanation": "« Saint Georges » = الْقِدِّيسُ جِرْجِسُ (ou مَارْ جِرْجِسُ). مَرْيَم est une femme : on dirait الْقِدِّيسَةُ مَرْيَمُ.", "tip": "قِدِّيس + nom = « saint ... ».", "extraExample": {"text": "الْقِدِّيسُ مَرْقُسُ", "translation": "saint Marc", "transliteration": "al-qiddîsu marqusu"}, "errorPatterns": [{"equals": "مَرْيَمُ", "category": "grammar", "feedback": "Marie est une femme : le titre serait féminin, الْقِدِّيسَة."}, {"equals": "الْبَابَا", "category": "vocabulary", "feedback": "الْبَابَا est le pape, un titre, pas le nom d''un saint."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e12', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.chammas']::text[], 'fill_blank', 'lesson', '___ فِي الْهَيْكَلِ', array['الشَّمَّاسُ']::text[], 'Seul un diacre (الشَّمَّاس) peut être « dans le sanctuaire ». L''église contient le sanctuaire, pas l''inverse, et le sanctuaire ne peut pas être dans lui-même.', 3, '{"id": "ar.l30.e12", "unitIds": ["ar.g30.chadda_hamza", "ar.v.chammas"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Le diacre est dans le sanctuaire. »", "prompt": "___ فِي الْهَيْكَلِ", "promptLanguage": "ar", "options": ["الشَّمَّاسُ", "الْكَنِيسَةُ", "الْهَيْكَلُ"], "answer": "الشَّمَّاسُ", "acceptedAnswers": ["الشَّمَّاسُ"], "explanation": "Seul un diacre (الشَّمَّاس) peut être « dans le sanctuaire ». L''église contient le sanctuaire, pas l''inverse, et le sanctuaire ne peut pas être dans lui-même.", "tip": "Lis la phrase en entier avant de choisir.", "extraExample": {"text": "الْكَاهِنُ فِي الْهَيْكَلِ", "translation": "Le prêtre est dans le sanctuaire.", "transliteration": "al-kâhinu fî l-haykal"}, "errorPatterns": [{"equals": "الْكَنِيسَةُ", "category": "vocabulary", "feedback": "L''église contient le sanctuaire : elle n''est pas « dans » le sanctuaire."}, {"equals": "الْهَيْكَلُ", "category": "vocabulary", "feedback": "Le sanctuaire ne peut pas être dans lui-même."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e13', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.adhra_maryam']::text[], 'fill_blank', 'lesson', 'الْعَذْرَاء = al-3adhrâ___', array['''']::text[], 'Le dernier signe, ء, est une hamza : on la note '' (petit coup de glotte). Elle suit le â long : al-3adhrâ''.', 3, '{"id": "ar.l30.e13", "unitIds": ["ar.g30.chadda_hamza", "ar.v.adhra_maryam"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la lecture du mot الْعَذْرَاء.", "prompt": "الْعَذْرَاء = al-3adhrâ___", "promptLanguage": "fr", "options": ["''", "a", "t"], "answer": "''", "acceptedAnswers": ["''"], "explanation": "Le dernier signe, ء, est une hamza : on la note '' (petit coup de glotte). Elle suit le â long : al-3adhrâ''.", "tip": "Hamza = '' (apostrophe).", "extraExample": {"text": "نِسَاء", "translation": "femmes : nisâ''", "transliteration": "nisâ''"}, "errorPatterns": [{"equals": "a", "category": "spelling", "feedback": "Il y a déjà un â long ; la hamza finale n''est pas un a mais un coup de glotte ('')."}, {"equals": "t", "category": "spelling", "feedback": "Le ت ne figure pas dans ce mot : la lettre finale est ء."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e14', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.usquf','ar.v.kahin','ar.v.kanisa']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : l''évêque / et le prêtre / dans l''église', array['الْأُسْقُفُ وَالْكَاهِنُ فِي الْكَنِيسَةِ']::text[], 'Les deux sujets (الْأُسْقُفُ وَالْكَاهِنُ) viennent d''abord, reliés par وَ collé au second, puis فِي الْكَنِيسَةِ pour dire où ils sont.', 3, '{"id": "ar.l30.e14", "unitIds": ["ar.g30.chadda_hamza", "ar.v.usquf", "ar.v.kahin", "ar.v.kanisa"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « L''évêque et le prêtre sont dans l''église. »", "prompt": "Remets dans l''ordre : l''évêque / et le prêtre / dans l''église", "promptLanguage": "fr", "tokens": ["فِي", "الْأُسْقُفُ", "الْكَنِيسَةِ", "وَالْكَاهِنُ"], "answer": "الْأُسْقُفُ وَالْكَاهِنُ فِي الْكَنِيسَةِ", "acceptedAnswers": ["الْأُسْقُفُ وَالْكَاهِنُ فِي الْكَنِيسَةِ"], "explanation": "Les deux sujets (الْأُسْقُفُ وَالْكَاهِنُ) viennent d''abord, reliés par وَ collé au second, puis فِي الْكَنِيسَةِ pour dire où ils sont.", "tip": "Sujets d''abord, lieu ensuite.", "extraExample": {"text": "الْأُسْقُفُ فِي الْهَيْكَلِ", "translation": "L''évêque est dans le sanctuaire.", "transliteration": "al-usqufu fî l-haykal"}, "pool": "lesson", "lessonId": "ar.l30", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e15', 'ar', 'ar.l30', 'ar.g29.idafa', array['ar.g29.idafa','ar.v.adhra_maryam','ar.v.ayquna']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : l''icône / de la Vierge / Marie', array['أَيْقُونَةُ الْعَذْرَاءِ مَرْيَمَ']::text[], 'Révision de l''annexion : le premier nom (أَيْقُونَةُ) n''a pas ال et son ة se lit t ; puis le second (الْعَذْرَاءِ), puis le nom propre مَرْيَمَ qui précise.', 3, '{"id": "ar.l30.e15", "unitIds": ["ar.g29.idafa", "ar.v.adhra_maryam", "ar.v.ayquna"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « L''icône de la Vierge Marie. »", "prompt": "Remets dans l''ordre : l''icône / de la Vierge / Marie", "promptLanguage": "fr", "tokens": ["مَرْيَمَ", "أَيْقُونَةُ", "الْعَذْرَاءِ"], "answer": "أَيْقُونَةُ الْعَذْرَاءِ مَرْيَمَ", "acceptedAnswers": ["أَيْقُونَةُ الْعَذْرَاءِ مَرْيَمَ"], "explanation": "Révision de l''annexion : le premier nom (أَيْقُونَةُ) n''a pas ال et son ة se lit t ; puis le second (الْعَذْرَاءِ), puis le nom propre مَرْيَمَ qui précise.", "tip": "Premier nom nu, puis le nom précis.", "extraExample": {"text": "أَيْقُونَةُ الْمَسِيحِ", "translation": "l''icône du Christ", "transliteration": "ayqûnatu l-masî7"}, "pool": "lesson", "lessonId": "ar.l30", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e16', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.mar_girgis','ar.v.chahid']::text[], 'translation', 'lesson', 'مَارْ جِرْجِسُ شَهِيدٌ', array['Saint Georges est un martyr.','Saint Georges est martyr.','Mar Girgis est un martyr.','Mar Guirguis est un martyr.','Saint Georges, c''est un martyr.']::text[], 'مَارْ جِرْجِسُ = saint Georges ; شَهِيدٌ = un martyr (tanwîn : « un »). Pas de verbe « être » en arabe au présent.', 2, '{"id": "ar.l30.e16", "unitIds": ["ar.g30.chadda_hamza", "ar.v.mar_girgis", "ar.v.chahid"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "مَارْ جِرْجِسُ شَهِيدٌ", "promptLanguage": "ar", "answer": "Saint Georges est un martyr.", "acceptedAnswers": ["Saint Georges est un martyr.", "Saint Georges est martyr.", "Mar Girgis est un martyr.", "Mar Guirguis est un martyr.", "Saint Georges, c''est un martyr."], "explanation": "مَارْ جِرْجِسُ = saint Georges ; شَهِيدٌ = un martyr (tanwîn : « un »). Pas de verbe « être » en arabe au présent.", "tip": "مَار devant un nom = « saint ».", "extraExample": {"text": "مَارْ مَرْقُسُ قِدِّيسٌ", "translation": "Saint Marc est un saint.", "transliteration": "mâr marqusu qiddîs"}, "errorPatterns": [{"contains": "marc", "category": "vocabulary", "feedback": "Marc se dit مَرْقُس. Ici, le nom est جِرْجِس : Georges."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e17', 'ar', 'ar.l30', 'ar.v.abouna', array['ar.v.abouna','ar.v.huwa','ar.v.kahin','ar.g30.chadda_hamza']::text[], 'translation', 'lesson', 'أَبُونَا هُوَ الْكَاهِنُ', array['Abouna est le prêtre.','Notre père est le prêtre.','Abouna, c''est le prêtre.','Notre père, c''est le prêtre.']::text[], 'أَبُونَا = « notre père », la façon d''appeler le prêtre ; هُوَ = il est ; الْكَاهِنُ = le prêtre. Les deux mots désignent la même personne.', 3, '{"id": "ar.l30.e17", "unitIds": ["ar.v.abouna", "ar.v.huwa", "ar.v.kahin", "ar.g30.chadda_hamza"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "أَبُونَا هُوَ الْكَاهِنُ", "promptLanguage": "ar", "answer": "Abouna est le prêtre.", "acceptedAnswers": ["Abouna est le prêtre.", "Notre père est le prêtre.", "Abouna, c''est le prêtre.", "Notre père, c''est le prêtre."], "explanation": "أَبُونَا = « notre père », la façon d''appeler le prêtre ; هُوَ = il est ; الْكَاهِنُ = le prêtre. Les deux mots désignent la même personne.", "tip": "أَبُونَا dans la vie courante ; الْكَاهِن dans les livres.", "extraExample": {"text": "أَبُونَا بُطْرُس", "translation": "Abouna Boutros", "transliteration": "abûnâ buTrus"}, "errorPatterns": [{"contains": "diacre", "category": "vocabulary", "feedback": "Le diacre se dit شَمَّاس. Ici : الْكَاهِن, le prêtre."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e18', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.baba','ar.v.usquf','ar.v.rahib','ar.v.chammas','ar.v.kahin']::text[], 'match', 'lesson', 'Le clergé de l''Église copte', '{}'::text[], 'Du pape (الْبَابَا) au diacre (شَمَّاس) : le pape et les évêques dirigent l''Église, les prêtres célèbrent, les diacres servent, les moines vivent au monastère.', 2, '{"id": "ar.l30.e18", "unitIds": ["ar.g30.chadda_hamza", "ar.v.baba", "ar.v.usquf", "ar.v.rahib", "ar.v.chammas", "ar.v.kahin"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Le clergé de l''Église copte", "promptLanguage": "fr", "pairs": [{"left": "الْبَابَا", "right": "le pape"}, {"left": "أُسْقُف", "right": "évêque"}, {"left": "رَاهِب", "right": "moine"}, {"left": "شَمَّاس", "right": "diacre"}, {"left": "كَاهِن", "right": "prêtre"}], "answer": "الْبَابَا = le pape ; أُسْقُف = évêque ; رَاهِب = moine ; شَمَّاس = diacre ; كَاهِن = prêtre", "acceptedAnswers": [], "explanation": "Du pape (الْبَابَا) au diacre (شَمَّاس) : le pape et les évêques dirigent l''Église, les prêtres célèbrent, les diacres servent, les moines vivent au monastère.", "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e19', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.qiddis','ar.v.chammas','ar.v.adhra_maryam','ar.v.rahib','ar.v.usquf']::text[], 'match', 'lesson', 'Lecture éclair : cinq mots d''Église', '{}'::text[], 'Les chaddas (qid-dîs, cham-mâs) doublent la consonne ; la hamza finale (3adhrâ'') se garde ; râhib a un â long, usquf trois voyelles brèves.', 3, '{"id": "ar.l30.e19", "unitIds": ["ar.g30.chadda_hamza", "ar.v.qiddis", "ar.v.chammas", "ar.v.adhra_maryam", "ar.v.rahib", "ar.v.usquf"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lecture éclair : cinq mots d''Église", "promptLanguage": "fr", "pairs": [{"left": "قِدِّيس", "right": "qiddîs"}, {"left": "شَمَّاس", "right": "chammâs"}, {"left": "الْعَذْرَاء", "right": "al-3adhrâ''"}, {"left": "رَاهِب", "right": "râhib"}, {"left": "أُسْقُف", "right": "usquf"}], "answer": "قِدِّيس = qiddîs ; شَمَّاس = chammâs ; الْعَذْرَاء = al-3adhrâ'' ; رَاهِب = râhib ; أُسْقُف = usquf", "acceptedAnswers": [], "explanation": "Les chaddas (qid-dîs, cham-mâs) doublent la consonne ; la hamza finale (3adhrâ'') se garde ; râhib a un â long, usquf trois voyelles brèves.", "pool": "lesson", "lessonId": "ar.l30", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e20', 'ar', 'ar.l30', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.chammas','ar.g30.chadda_hamza']::text[], 'free_answer', 'lesson', 'الشَّمَّاس', array['ach-chammâs','achchammâs','ach chammâs','ach-chammas','achchammas','ach chammas','ach-chammaas','achchammaas','ach chammaas','ash-shammas','ashshammas','ash shammas','ash-shammâs','ashshammâs','ash shammâs','ash-shammaas','ashshammaas','ash shammaas']::text[], 'ش est solaire : le l tombe et le ch est doublé (ach-). Le م porte sa propre chadda (mm) et le ا final est long : ach-chammâs.', 3, '{"id": "ar.l30.e20", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.chammas", "ar.g30.chadda_hamza"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ce mot en lettres latines.", "prompt": "الشَّمَّاس", "promptLanguage": "ar", "answer": "ach-chammâs", "acceptedAnswers": ["ach-chammâs", "achchammâs", "ach chammâs", "ach-chammas", "achchammas", "ach chammas", "ach-chammaas", "achchammaas", "ach chammaas", "ash-shammas", "ashshammas", "ash shammas", "ash-shammâs", "ashshammâs", "ash shammâs", "ash-shammaas", "ashshammaas", "ash shammaas"], "hint": "ach- + cham + mâs.", "explanation": "ش est solaire : le l tombe et le ch est doublé (ach-). Le م porte sa propre chadda (mm) et le ا final est long : ach-chammâs.", "tip": "Deux chaddas = deux consonnes doublées : ch et m.", "extraExample": {"text": "الشَّمَّاسُ فِي الْهَيْكَلِ", "translation": "Le diacre est dans le sanctuaire.", "transliteration": "ach-chammâsu fî l-haykal"}, "errorPatterns": [{"equals": "al-chammâs", "category": "grammar", "feedback": "ش est solaire : écris ach-chammâs, sans le l."}, {"equals": "ach-chamâs", "category": "spelling", "feedback": "Le م porte aussi une chadda : chammâs avec deux m."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l30.e21', 'ar', 'ar.l30', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.baba']::text[], 'free_answer', 'lesson', 'الْبَابَا', array['le pape','pape','le pape d''Alexandrie','le patriarche','le pape copte']::text[], 'الْبَابَا est le pape, chef de l''Église copte orthodoxe. Écrit sans ال, بَابَا est aussi le mot familier pour « papa ».', 3, '{"id": "ar.l30.e21", "unitIds": ["ar.g30.chadda_hamza", "ar.v.baba"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la traduction en français.", "prompt": "الْبَابَا", "promptLanguage": "ar", "answer": "le pape", "acceptedAnswers": ["le pape", "pape", "le pape d''Alexandrie", "le patriarche", "le pape copte"], "explanation": "الْبَابَا est le pape, chef de l''Église copte orthodoxe. Écrit sans ال, بَابَا est aussi le mot familier pour « papa ».", "tip": "Al-bâbâ = le pape d''Alexandrie.", "extraExample": {"text": "قَدَاسَةُ الْبَابَا", "translation": "Sa Sainteté le pape", "transliteration": "qadâsatu l-bâbâ"}, "errorPatterns": [{"contains": "porte", "category": "vocabulary", "feedback": "La porte se dit بَاب (un seul ب). Ici il y a deux ب et deux ا : الْبَابَا, le pape."}], "pool": "lesson", "lessonId": "ar.l30", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e01', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.ya_rabb_irham']::text[], 'mcq', 'lesson', 'يَا رَبُّ ارْحَمْ', array['yâ rabbu r-7am']::text[], 'يَا = yâ (le ا est long). رَبُّ garde sa damma finale (rabbu) puisque le mot suivant l''enchaîne. Dans ارْحَمْ, le ا tombe après la damma : on dit r-7am. Le ح sans point est le 7 de la gorge.', 1, '{"id": "ar.l31.e01", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.ya_rabb_irham"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quelle lecture est la bonne ?", "prompt": "يَا رَبُّ ارْحَمْ", "promptLanguage": "ar", "options": ["yâ rabbu r-7am", "yâ rabbu ârham", "yâ rabbi r-7am", "ya rabbu r-7am"], "answer": "yâ rabbu r-7am", "acceptedAnswers": ["yâ rabbu r-7am"], "explanation": "يَا = yâ (le ا est long). رَبُّ garde sa damma finale (rabbu) puisque le mot suivant l''enchaîne. Dans ارْحَمْ, le ا tombe après la damma : on dit r-7am. Le ح sans point est le 7 de la gorge.", "tip": "Après يَا, le nom finit par une damma : yâ rabbu.", "extraExample": {"text": "يَا رَبُّ", "translation": "ô Seigneur", "transliteration": "yâ rabb"}, "errorPatterns": [{"equals": "yâ rabbu ârham", "category": "spelling", "feedback": "Le ا de ارْحَمْ n''est pas un â long : il est muet quand il suit رَبُّ. On enchaîne r-7am."}, {"equals": "yâ rabbi r-7am", "category": "grammar", "feedback": "Après يَا, le nom prend une damma (rabbu), pas une kasra."}, {"equals": "ya rabbu r-7am", "category": "spelling", "feedback": "Le ا de يَا est long : yâ."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e02', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.amin']::text[], 'mcq', 'lesson', 'آمِين', array['âmîn']::text[], 'آ est un alif madda (hamza + â long, leçon 14). Puis م, et ـِين : la kasra suivie de ي donne un î long. On lit â-mîn, le mot qui clôt chaque prière.', 1, '{"id": "ar.l31.e02", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.amin"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quelle lecture est la bonne ?", "prompt": "آمِين", "promptLanguage": "ar", "options": ["âmîn", "amîn", "âmin", "âmn"], "answer": "âmîn", "acceptedAnswers": ["âmîn"], "explanation": "آ est un alif madda (hamza + â long, leçon 14). Puis م, et ـِين : la kasra suivie de ي donne un î long. On lit â-mîn, le mot qui clôt chaque prière.", "tip": "آ = â ; ـِين = îne.", "extraExample": {"text": "آمِين يَا رَبُّ", "translation": "Amen, Seigneur.", "transliteration": "âmîn yâ rabb"}, "errorPatterns": [{"equals": "amîn", "category": "spelling", "feedback": "Le آ (alif madda) donne un â long : âmîn."}, {"equals": "âmin", "category": "spelling", "feedback": "Le ي après la kasra est long : mîn."}, {"equals": "âmn", "category": "spelling", "feedback": "Il y a une voyelle entre le m et le n : mîn."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e03', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.ya_rabb_irham','ar.v.amin','ar.v.al_madjd_lak','ar.v.as_salam_lil_kull','ar.v.wa_li_ruhika']::text[], 'match', 'lesson', 'Les réponses de la liturgie', '{}'::text[], 'Le prêtre dit السَّلَامُ لِلْكُلِّ et le peuple répond وَلِرُوحِكَ أَيْضًا. يَا رَبُّ ارْحَمْ est la supplication, آمِين clôt la prière et الْمَجْدُ لَكَ يَا رَبُّ est une louange.', 1, '{"id": "ar.l31.e03", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.ya_rabb_irham", "ar.v.amin", "ar.v.al_madjd_lak", "ar.v.as_salam_lil_kull", "ar.v.wa_li_ruhika"], "type": "match", "difficulty": 1, "instruction": "Associe chaque formule à sa traduction.", "prompt": "Les réponses de la liturgie", "promptLanguage": "fr", "pairs": [{"left": "يَا رَبُّ ارْحَمْ", "right": "Seigneur, aie pitié"}, {"left": "آمِين", "right": "amen"}, {"left": "الْمَجْدُ لَكَ يَا رَبُّ", "right": "Gloire à toi, Seigneur"}, {"left": "السَّلَامُ لِلْكُلِّ", "right": "La paix soit à tous"}, {"left": "وَلِرُوحِكَ أَيْضًا", "right": "Et à ton esprit aussi"}], "answer": "يَا رَبُّ ارْحَمْ = Seigneur, aie pitié ; آمِين = amen ; الْمَجْدُ لَكَ يَا رَبُّ = Gloire à toi, Seigneur ; السَّلَامُ لِلْكُلِّ = La paix soit à tous ; وَلِرُوحِكَ أَيْضًا = Et à ton esprit aussi", "acceptedAnswers": [], "explanation": "Le prêtre dit السَّلَامُ لِلْكُلِّ et le peuple répond وَلِرُوحِكَ أَيْضًا. يَا رَبُّ ارْحَمْ est la supplication, آمِين clôt la prière et الْمَجْدُ لَكَ يَا رَبُّ est une louange.", "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e04', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.al_madjd_lak']::text[], 'mcq', 'lesson', 'Que veut dire لَكَ dans الْمَجْدُ لَكَ يَا رَبُّ ?', array['à toi']::text[], 'لَكَ = لِ (à) + ـكَ (toi). Le suffixe ـكَ se colle au mot et veut dire « toi, ton ». ـنَا serait « nous », ـهُ « lui ».', 2, '{"id": "ar.l31.e04", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.al_madjd_lak"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne traduction.", "prompt": "Que veut dire لَكَ dans الْمَجْدُ لَكَ يَا رَبُّ ?", "promptLanguage": "fr", "options": ["à toi", "à nous", "à lui", "à moi"], "answer": "à toi", "acceptedAnswers": ["à toi"], "explanation": "لَكَ = لِ (à) + ـكَ (toi). Le suffixe ـكَ se colle au mot et veut dire « toi, ton ». ـنَا serait « nous », ـهُ « lui ».", "tip": "ـكَ = toi, ton.", "extraExample": {"text": "لَكَ الْمَجْدُ", "translation": "À toi la gloire.", "transliteration": "laka l-madjd"}, "errorPatterns": [{"equals": "à nous", "category": "grammar", "feedback": "« À nous » s''écrit لَنَا, avec le suffixe ـنَا. Ici, c''est ـكَ."}, {"equals": "à lui", "category": "grammar", "feedback": "« À lui » s''écrit لَهُ, avec le suffixe ـهُ. Ici, c''est ـكَ."}, {"equals": "à moi", "category": "grammar", "feedback": "« À moi » s''écrit لِي. Ici, le suffixe est ـكَ : à toi."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e05', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.ya_rabb_irham']::text[], 'mcq', 'lesson', 'Dans يَا رَبُّ ارْحَمْ, que devient le ا de ارْحَمْ ?', array['Il tombe : rabbu r-7am']::text[], 'Ce ا ne sert qu''à commencer le mot. Quand le mot précédent finit par une voyelle (la damma de رَبُّ), il disparaît et on enchaîne r-7am. Si tu fais un petit silence entre les deux mots, comme à l''église, tu entends « irham » : c''est la même formule en deux temps.', 2, '{"id": "ar.l31.e05", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.ya_rabb_irham"], "type": "mcq", "difficulty": 2, "instruction": "Observe l''enchaînement.", "prompt": "Dans يَا رَبُّ ارْحَمْ, que devient le ا de ارْحَمْ ?", "promptLanguage": "fr", "options": ["Il tombe : rabbu r-7am", "Il s''allonge : rabbu ârham", "Il devient ع : rabbu 3arham", "Il se lit y : rabbu yarham"], "answer": "Il tombe : rabbu r-7am", "acceptedAnswers": ["Il tombe : rabbu r-7am"], "explanation": "Ce ا ne sert qu''à commencer le mot. Quand le mot précédent finit par une voyelle (la damma de رَبُّ), il disparaît et on enchaîne r-7am. Si tu fais un petit silence entre les deux mots, comme à l''église, tu entends « irham » : c''est la même formule en deux temps.", "tip": "Un ا de liaison se tait après une voyelle.", "extraExample": {"text": "بِاسْمِ الرَّبِّ", "translation": "au nom du Seigneur", "transliteration": "bismi r-rabb"}, "errorPatterns": [{"equals": "Il s''allonge : rabbu ârham", "category": "spelling", "feedback": "Un ا long porte une marque de voyelle (آ) ou se voit entre deux consonnes ; ici, c''est un ا de liaison qui tombe."}, {"equals": "Il devient ع : rabbu 3arham", "category": "spelling", "feedback": "ع est une autre lettre ; ici le ا tombe tout simplement."}, {"equals": "Il se lit y : rabbu yarham", "category": "spelling", "feedback": "Le y est la lettre ي. Le ا de ارْحَمْ ne se lit pas y."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e06', 'ar', 'ar.l31', 'ar.g25.al_solaire_lunaire', array['ar.g25.al_solaire_lunaire','ar.v.as_salam_lil_kull']::text[], 'mcq', 'lesson', 'السَّلَامُ لِلْكُلِّ', array['as-salâmu li-l-kull']::text[], 'ال devant س (lettre solaire) : le l tombe et le s est doublé, as-salâm. Dans لِلْكُلِّ, ل + الْكُلّ font deux l de suite (li-l-kull) et la chadda double le k.', 2, '{"id": "ar.l31.e06", "unitIds": ["ar.g25.al_solaire_lunaire", "ar.v.as_salam_lil_kull"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quelle lecture est la bonne ?", "prompt": "السَّلَامُ لِلْكُلِّ", "promptLanguage": "ar", "options": ["as-salâmu li-l-kull", "al-salâmu li-l-kull", "as-salâmu li-kull", "as-salamu li-l-kull"], "answer": "as-salâmu li-l-kull", "acceptedAnswers": ["as-salâmu li-l-kull"], "explanation": "ال devant س (lettre solaire) : le l tombe et le s est doublé, as-salâm. Dans لِلْكُلِّ, ل + الْكُلّ font deux l de suite (li-l-kull) et la chadda double le k.", "tip": "ال + س = as-.", "extraExample": {"text": "السَّلَامُ عَلَيْكُمْ", "translation": "La paix sur vous.", "transliteration": "as-salâmu 3alaykum"}, "errorPatterns": [{"equals": "al-salâmu li-l-kull", "category": "grammar", "feedback": "س est une lettre solaire : le l de ال ne se dit pas, as-salâm."}, {"equals": "as-salâmu li-kull", "category": "spelling", "feedback": "Il y a deux ل de suite dans لِلْكُلِّ : li-l-kull."}, {"equals": "as-salamu li-l-kull", "category": "spelling", "feedback": "Le ا après le ل est long : salâm."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e07', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.wa_li_ruhika','ar.v.as_salam_lil_kull']::text[], 'mcq', 'lesson', 'Le prêtre dit : السَّلَامُ لِلْكُلِّ. Que répond le peuple ?', array['وَلِرُوحِكَ أَيْضًا']::text[], 'Au salut du prêtre, le peuple répond وَلِرُوحِكَ أَيْضًا : « et à ton esprit aussi », c''est-à-dire que la paix soit aussi sur lui.', 2, '{"id": "ar.l31.e07", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.wa_li_ruhika", "ar.v.as_salam_lil_kull"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la réponse du peuple.", "prompt": "Le prêtre dit : السَّلَامُ لِلْكُلِّ. Que répond le peuple ?", "promptLanguage": "fr", "options": ["وَلِرُوحِكَ أَيْضًا", "الْمَجْدُ لَكَ يَا رَبُّ", "يَا رَبُّ ارْحَمْ", "هَلِّلُويَا"], "answer": "وَلِرُوحِكَ أَيْضًا", "acceptedAnswers": ["وَلِرُوحِكَ أَيْضًا"], "explanation": "Au salut du prêtre, le peuple répond وَلِرُوحِكَ أَيْضًا : « et à ton esprit aussi », c''est-à-dire que la paix soit aussi sur lui.", "tip": "Salut du prêtre, vœu en retour.", "extraExample": {"text": "وَلَكَ أَيْضًا", "translation": "Et à toi aussi.", "transliteration": "wa-laka ayDan"}, "errorPatterns": [{"equals": "الْمَجْدُ لَكَ يَا رَبُّ", "category": "vocabulary", "feedback": "C''est une louange adressée au Seigneur, pas la réponse au salut du prêtre."}, {"equals": "يَا رَبُّ ارْحَمْ", "category": "vocabulary", "feedback": "C''est la réponse à l''appel du diacre صَلُّوا, pas au salut du prêtre."}, {"equals": "هَلِّلُويَا", "category": "vocabulary", "feedback": "L''alléluia est un cri de joie, pas la réponse au salut du prêtre."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e08', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.wa_li_ruhika']::text[], 'mcq', 'lesson', 'وَلِرُوحِكَ أَيْضًا', array['wa-li-rû7ika ayDan']::text[], 'وَ = wa (et) ; لِ = li (à) ; رُوحِ = rû7i (esprit : ر damma, و long, ح = 7) ; ـكَ = ka (ton) ; أَيْضًا = ayDan (ay est une diphtongue, ض = D emphatique, le tanwîn en fatha s''entend -an).', 3, '{"id": "ar.l31.e08", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.wa_li_ruhika"], "type": "mcq", "difficulty": 3, "instruction": "Lis vite : quelle lecture est la bonne ?", "prompt": "وَلِرُوحِكَ أَيْضًا", "promptLanguage": "ar", "options": ["wa-li-rû7ika ayDan", "wa-li-ru7ika ayDan", "wa-la-rû7ika ayDan", "wa-li-rû7i ayDan"], "answer": "wa-li-rû7ika ayDan", "acceptedAnswers": ["wa-li-rû7ika ayDan"], "explanation": "وَ = wa (et) ; لِ = li (à) ; رُوحِ = rû7i (esprit : ر damma, و long, ح = 7) ; ـكَ = ka (ton) ; أَيْضًا = ayDan (ay est une diphtongue, ض = D emphatique, le tanwîn en fatha s''entend -an).", "tip": "wa + li + rû7 + ika + ayDan.", "extraExample": {"text": "وَلِلْكَنِيسَةِ أَيْضًا", "translation": "Et à l''église aussi.", "transliteration": "wa-li-l-kanîsati ayDan"}, "errorPatterns": [{"equals": "wa-li-ru7ika ayDan", "category": "spelling", "feedback": "Il y a un و après le ر : rû7 avec un û long."}, {"equals": "wa-la-rû7ika ayDan", "category": "spelling", "feedback": "Sous le ل il y a une kasra : li (« à »)."}, {"equals": "wa-li-rû7i ayDan", "category": "grammar", "feedback": "Le suffixe ـكَ (ton) se lit aussi : rû7ika."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e09', 'ar', 'ar.l31', 'ar.g30.chadda_hamza', array['ar.g30.chadda_hamza','ar.v.quddus']::text[], 'mcq', 'lesson', 'قُدُّوس', array['quddûs']::text[], 'قُ = qu ; دُّ = le د avec chadda et damma, donc ddu ; و = û long ; س. La chadda double le d : qud-dûs, comme qid-dîs dans la leçon 30.', 2, '{"id": "ar.l31.e09", "unitIds": ["ar.g30.chadda_hamza", "ar.v.quddus"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quelle lecture est la bonne ?", "prompt": "قُدُّوس", "promptLanguage": "ar", "options": ["quddûs", "qudûs", "qaddûs", "quddus"], "answer": "quddûs", "acceptedAnswers": ["quddûs"], "explanation": "قُ = qu ; دُّ = le د avec chadda et damma, donc ddu ; و = û long ; س. La chadda double le d : qud-dûs, comme qid-dîs dans la leçon 30.", "tip": "Chadda sur le د : deux d.", "extraExample": {"text": "اللّٰهُ قُدُّوسٌ", "translation": "Dieu est saint.", "transliteration": "Allâhu quddûs"}, "errorPatterns": [{"equals": "qudûs", "category": "spelling", "feedback": "La chadda sur le د double la lettre : qud-dûs."}, {"equals": "qaddûs", "category": "spelling", "feedback": "Le ق porte une damma : qu."}, {"equals": "quddus", "category": "spelling", "feedback": "Le و est long : dûs."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e10', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.sallu']::text[], 'mcq', 'lesson', 'صَلُّوا', array['Sallû']::text[], 'ص = S (emphatique) avec une fatha ; لُّ = ل avec chadda et damma, donc llu ; ـُوا : le و est long (û) et le ا qui le suit est muet. On lit Sal-lû.', 2, '{"id": "ar.l31.e10", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.sallu"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quelle lecture est la bonne ?", "prompt": "صَلُّوا", "promptLanguage": "ar", "options": ["Sallû", "Sallûa", "Sallâ", "Sillû"], "answer": "Sallû", "acceptedAnswers": ["Sallû"], "explanation": "ص = S (emphatique) avec une fatha ; لُّ = ل avec chadda et damma, donc llu ; ـُوا : le و est long (û) et le ا qui le suit est muet. On lit Sal-lû.", "tip": "ـُوا à la fin d''un verbe : le ا se tait.", "extraExample": {"text": "صَلُّوا فِي الْكَنِيسَةِ", "translation": "Priez dans l''église !", "transliteration": "Sallû fî l-kanîsa"}, "errorPatterns": [{"equals": "Sallûa", "category": "grammar", "feedback": "Le ا écrit après و à la fin du verbe est muet : Sallû."}, {"equals": "Sallâ", "category": "spelling", "feedback": "Le ل porte une chadda avec une damma, puis un و long : llû."}, {"equals": "Sillû", "category": "spelling", "feedback": "Sous le ص il y a une fatha : Sa."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e11', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.sallu','ar.v.quddus','ar.v.halleluia','ar.v.ajbiyya','ar.v.abana']::text[], 'match', 'lesson', 'Les mots de la prière', '{}'::text[], 'صَلُّوا est l''appel du diacre ; قُدُّوس est le « Saint » ; هَلِّلُويَا est le cri de joie ; الْأَجْبِيَّة est le livre des sept prières ; أَبَانَا ouvre le Notre Père.', 2, '{"id": "ar.l31.e11", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.sallu", "ar.v.quddus", "ar.v.halleluia", "ar.v.ajbiyya", "ar.v.abana"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Les mots de la prière", "promptLanguage": "fr", "pairs": [{"left": "صَلُّوا", "right": "priez !"}, {"left": "قُدُّوس", "right": "saint (dit de Dieu)"}, {"left": "هَلِّلُويَا", "right": "alléluia"}, {"left": "الْأَجْبِيَّة", "right": "l''Agpeya, le livre des heures"}, {"left": "أَبَانَا", "right": "notre Père"}], "answer": "صَلُّوا = priez ! ; قُدُّوس = saint (dit de Dieu) ; هَلِّلُويَا = alléluia ; الْأَجْبِيَّة = l''Agpeya, le livre des heures ; أَبَانَا = notre Père", "acceptedAnswers": [], "explanation": "صَلُّوا est l''appel du diacre ; قُدُّوس est le « Saint » ; هَلِّلُويَا est le cri de joie ; الْأَجْبِيَّة est le livre des sept prières ; أَبَانَا ouvre le Notre Père.", "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e12', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.amin','ar.v.quddus','ar.v.sallu','ar.v.halleluia','ar.v.ajbiyya']::text[], 'match', 'lesson', 'Lecture éclair : cinq mots de la prière', '{}'::text[], 'Les chaddas doublent le d de quddûs, le l de Sallû et de hallilûyâ, le y de adjbiyya ; le ا de صَلُّوا ne se prononce pas.', 3, '{"id": "ar.l31.e12", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.amin", "ar.v.quddus", "ar.v.sallu", "ar.v.halleluia", "ar.v.ajbiyya"], "type": "match", "difficulty": 3, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lecture éclair : cinq mots de la prière", "promptLanguage": "fr", "pairs": [{"left": "آمِين", "right": "âmîn"}, {"left": "قُدُّوس", "right": "quddûs"}, {"left": "صَلُّوا", "right": "Sallû"}, {"left": "هَلِّلُويَا", "right": "hallilûyâ"}, {"left": "الْأَجْبِيَّة", "right": "al-adjbiyya"}], "answer": "آمِين = âmîn ; قُدُّوس = quddûs ; صَلُّوا = Sallû ; هَلِّلُويَا = hallilûyâ ; الْأَجْبِيَّة = al-adjbiyya", "acceptedAnswers": [], "explanation": "Les chaddas doublent le d de quddûs, le l de Sallû et de hallilûyâ, le y de adjbiyya ; le ا de صَلُّوا ne se prononce pas.", "pool": "lesson", "lessonId": "ar.l31", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e13', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.abana']::text[], 'fill_blank', 'lesson', 'أَبَا___ الَّذِي فِي السَّمَاوَاتِ', array['نَا']::text[], '« Notre » se dit ـنَا : أَبَا + نَا = أَبَانَا. ـكَ donnerait « ton père » (أَبَاكَ) et ـهُ « son père » (أَبَاهُ).', 2, '{"id": "ar.l31.e13", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.abana"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « Notre Père qui es aux cieux. »", "prompt": "أَبَا___ الَّذِي فِي السَّمَاوَاتِ", "promptLanguage": "ar", "options": ["هُ", "كَ", "نَا"], "answer": "نَا", "acceptedAnswers": ["نَا"], "explanation": "« Notre » se dit ـنَا : أَبَا + نَا = أَبَانَا. ـكَ donnerait « ton père » (أَبَاكَ) et ـهُ « son père » (أَبَاهُ).", "tip": "نَا = notre, nous.", "extraExample": {"text": "رَبُّنَا", "translation": "notre Seigneur", "transliteration": "rabbunâ"}, "errorPatterns": [{"equals": "كَ", "category": "grammar", "feedback": "ـكَ veut dire « ton » : on dirait « ton père ». Ici, c''est « notre »."}, {"equals": "هُ", "category": "grammar", "feedback": "ـهُ veut dire « son » : on dirait « son père ». Ici, c''est « notre »."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e14', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.wa_li_ruhika']::text[], 'fill_blank', 'lesson', 'وَلِرُوحِ___ أَيْضًا', array['كَ']::text[], '« Ton » se dit ـكَ : رُوحِ + كَ = رُوحِكَ. ـنَا donnerait « notre esprit » et ـهُ « son esprit ».', 2, '{"id": "ar.l31.e14", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.wa_li_ruhika"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la réponse : « Et à ton esprit aussi. »", "prompt": "وَلِرُوحِ___ أَيْضًا", "promptLanguage": "ar", "options": ["نَا", "هُ", "كَ"], "answer": "كَ", "acceptedAnswers": ["كَ"], "explanation": "« Ton » se dit ـكَ : رُوحِ + كَ = رُوحِكَ. ـنَا donnerait « notre esprit » et ـهُ « son esprit ».", "tip": "ـكَ = ton, toi.", "extraExample": {"text": "رُوحُنَا", "translation": "notre esprit", "transliteration": "rû7unâ"}, "errorPatterns": [{"equals": "نَا", "category": "grammar", "feedback": "ـنَا veut dire « notre ». Le peuple s''adresse au prêtre : ton esprit."}, {"equals": "هُ", "category": "grammar", "feedback": "ـهُ veut dire « son ». Le peuple s''adresse au prêtre : ton esprit."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e15', 'ar', 'ar.l31', 'ar.v.bismi', array['ar.v.bismi','ar.g31.ya_pronoms_attaches','ar.v.amin']::text[], 'fill_blank', 'lesson', 'بِاسْمِ الْآبِ وَالاِبْنِ وَالرُّوحِ الْقُدُسِ. ___', array['آمِين']::text[], 'La formule se ferme par آمِين. Rappelle-toi que dans بِاسْمِ le ا s''écrit mais ne se dit pas (bismi) : c''est le même ا muet que dans ارْحَمْ.', 3, '{"id": "ar.l31.e15", "unitIds": ["ar.v.bismi", "ar.g31.ya_pronoms_attaches", "ar.v.amin"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la fin du signe de la croix : « Au nom du Père, du Fils et du Saint-Esprit. Amen. »", "prompt": "بِاسْمِ الْآبِ وَالاِبْنِ وَالرُّوحِ الْقُدُسِ. ___", "promptLanguage": "ar", "options": ["هَلِّلُويَا", "آمِين", "يَا رَبُّ"], "answer": "آمِين", "acceptedAnswers": ["آمِين"], "explanation": "La formule se ferme par آمِين. Rappelle-toi que dans بِاسْمِ le ا s''écrit mais ne se dit pas (bismi) : c''est le même ا muet que dans ارْحَمْ.", "tip": "Prière finie : آمِين.", "extraExample": {"text": "بِاسْمِ الرَّبِّ. آمِين", "translation": "Au nom du Seigneur. Amen.", "transliteration": "bismi r-rabb. âmîn"}, "errorPatterns": [{"equals": "هَلِّلُويَا", "category": "vocabulary", "feedback": "L''alléluia est une louange joyeuse, pas la fin du signe de la croix."}, {"equals": "يَا رَبُّ", "category": "vocabulary", "feedback": "يَا رَبُّ appelle le Seigneur ; la formule se ferme par آمِين."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e16', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.ya_rabb_irham']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : aie pitié / ô / Seigneur', array['يَا رَبُّ ارْحَمْ']::text[], 'On appelle d''abord (يَا رَبُّ), puis on demande (ارْحَمْ).', 2, '{"id": "ar.l31.e16", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.ya_rabb_irham"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre : « Seigneur, aie pitié. »", "prompt": "Remets dans l''ordre : aie pitié / ô / Seigneur", "promptLanguage": "fr", "tokens": ["ارْحَمْ", "يَا", "رَبُّ"], "answer": "يَا رَبُّ ارْحَمْ", "acceptedAnswers": ["يَا رَبُّ ارْحَمْ"], "explanation": "On appelle d''abord (يَا رَبُّ), puis on demande (ارْحَمْ).", "tip": "Appeler, puis demander.", "extraExample": {"text": "يَا رَبُّ", "translation": "ô Seigneur", "transliteration": "yâ rabb"}, "pool": "lesson", "lessonId": "ar.l31", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e17', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.abana']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : dans / Notre Père / les cieux / qui', array['أَبَانَا الَّذِي فِي السَّمَاوَاتِ']::text[], 'Le nom أَبَانَا vient d''abord, puis الَّذِي (qui) introduit ce qui le décrit : فِي السَّمَاوَاتِ, « dans les cieux ».', 3, '{"id": "ar.l31.e17", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.abana"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Notre Père qui es aux cieux. »", "prompt": "Remets dans l''ordre : dans / Notre Père / les cieux / qui", "promptLanguage": "fr", "tokens": ["فِي", "أَبَانَا", "السَّمَاوَاتِ", "الَّذِي"], "answer": "أَبَانَا الَّذِي فِي السَّمَاوَاتِ", "acceptedAnswers": ["أَبَانَا الَّذِي فِي السَّمَاوَاتِ"], "explanation": "Le nom أَبَانَا vient d''abord, puis الَّذِي (qui) introduit ce qui le décrit : فِي السَّمَاوَاتِ, « dans les cieux ».", "tip": "Nom d''abord, puis « qui … ».", "extraExample": {"text": "رَبُّنَا فِي السَّمَاءِ", "translation": "Notre Seigneur est au ciel.", "transliteration": "rabbunâ fî s-samâ''"}, "pool": "lesson", "lessonId": "ar.l31", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e18', 'ar', 'ar.l31', 'ar.v.alladhi', array['ar.v.alladhi','ar.g31.ya_pronoms_attaches','ar.v.chammas']::text[], 'translation', 'lesson', 'الشَّمَّاسُ هُوَ الَّذِي فِي الْهَيْكَلِ', array['Le diacre est celui qui est dans le sanctuaire.','Le diacre est celui qui est dans le chœur.','Le diacre, c''est celui qui est dans le sanctuaire.','Le diacre est celui qui est au sanctuaire.','Le diacre est celui qui se trouve dans le sanctuaire.']::text[], 'الَّذِي = « celui qui » (leçon 23) ; هُوَ = il est ; فِي الْهَيْكَلِ = dans le sanctuaire. Le verbe « être » ne s''écrit pas.', 3, '{"id": "ar.l31.e18", "unitIds": ["ar.v.alladhi", "ar.g31.ya_pronoms_attaches", "ar.v.chammas"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "الشَّمَّاسُ هُوَ الَّذِي فِي الْهَيْكَلِ", "promptLanguage": "ar", "answer": "Le diacre est celui qui est dans le sanctuaire.", "acceptedAnswers": ["Le diacre est celui qui est dans le sanctuaire.", "Le diacre est celui qui est dans le chœur.", "Le diacre, c''est celui qui est dans le sanctuaire.", "Le diacre est celui qui est au sanctuaire.", "Le diacre est celui qui se trouve dans le sanctuaire."], "explanation": "الَّذِي = « celui qui » (leçon 23) ; هُوَ = il est ; فِي الْهَيْكَلِ = dans le sanctuaire. Le verbe « être » ne s''écrit pas.", "tip": "هُوَ الَّذِي = c''est celui qui.", "extraExample": {"text": "الْكَاهِنُ هُوَ الَّذِي فِي الْكَنِيسَةِ", "translation": "Le prêtre est celui qui est dans l''église.", "transliteration": "al-kâhinu huwa lladhî fî l-kanîsa"}, "errorPatterns": [{"contains": "prêtre", "category": "vocabulary", "feedback": "Le prêtre se dit كَاهِن. Ici, le mot est الشَّمَّاس : le diacre."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e19', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.al_madjd_lak']::text[], 'translation', 'lesson', 'الْمَجْدُ لَكَ يَا رَبُّ', array['Gloire à toi, Seigneur.','Gloire à toi, ô Seigneur.','Gloire à toi, Seigneur !','La gloire est à toi, Seigneur.']::text[], 'الْمَجْدُ = la gloire ; لَكَ = à toi ; يَا رَبُّ = ô Seigneur. Il n''y a pas de verbe.', 3, '{"id": "ar.l31.e19", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.al_madjd_lak"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "الْمَجْدُ لَكَ يَا رَبُّ", "promptLanguage": "ar", "answer": "Gloire à toi, Seigneur.", "acceptedAnswers": ["Gloire à toi, Seigneur.", "Gloire à toi, ô Seigneur.", "Gloire à toi, Seigneur !", "La gloire est à toi, Seigneur."], "explanation": "الْمَجْدُ = la gloire ; لَكَ = à toi ; يَا رَبُّ = ô Seigneur. Il n''y a pas de verbe.", "tip": "لَكَ = à toi.", "extraExample": {"text": "الْمَجْدُ لِلّٰهِ", "translation": "Gloire à Dieu.", "transliteration": "al-madjdu li-llâh"}, "errorPatterns": [{"contains": "nous", "category": "grammar", "feedback": "« À nous » s''écrit لَنَا. Ici, le suffixe est ـكَ : à toi."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e20', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.halleluia']::text[], 'free_answer', 'lesson', 'هَلِّلُويَا', array['hallilûyâ','halliluya','halliluuyaa','hallelûyâ','halleluya','halleluuyaa']::text[], 'La chadda double le ل : hal-li-lû-yâ. ـُو est un û long, puis يَا : yâ.', 3, '{"id": "ar.l31.e20", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.halleluia"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ce mot en lettres latines.", "prompt": "هَلِّلُويَا", "promptLanguage": "ar", "answer": "hallilûyâ", "acceptedAnswers": ["hallilûyâ", "halliluya", "halliluuyaa", "hallelûyâ", "halleluya", "halleluuyaa"], "hint": "hal + li + lû + yâ.", "explanation": "La chadda double le ل : hal-li-lû-yâ. ـُو est un û long, puis يَا : yâ.", "tip": "Quatre syllabes : hal · li · lû · yâ.", "extraExample": {"text": "هَلِّلُويَا لِلرَّبِّ", "translation": "Alléluia au Seigneur.", "transliteration": "hallilûyâ li-r-rabb"}, "errorPatterns": [{"equals": "halilûyâ", "category": "spelling", "feedback": "Le ل porte une chadda : deux l (hal-li-lû-yâ)."}, {"equals": "hallilûya", "category": "spelling", "feedback": "Le ا final est long : yâ."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l31.e21', 'ar', 'ar.l31', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.v.ajbiyya']::text[], 'free_answer', 'lesson', 'الْأَجْبِيَّة', array['l''Agpeya','Agpeya','l''Agbeya','Agbeya','le livre des heures','livre des heures','le livre des sept prières','les sept prières']::text[], 'الْأَجْبِيَّة (écrit aussi Agbeya) est le livre des heures des Coptes, avec les sept prières du jour et de la nuit. On l''appelle aussi كِتَاب السَّبْع صَلَوَات, « le livre des sept prières ».', 3, '{"id": "ar.l31.e21", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.v.ajbiyya"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la traduction en français.", "prompt": "الْأَجْبِيَّة", "promptLanguage": "ar", "answer": "l''Agpeya", "acceptedAnswers": ["l''Agpeya", "Agpeya", "l''Agbeya", "Agbeya", "le livre des heures", "livre des heures", "le livre des sept prières", "les sept prières"], "explanation": "الْأَجْبِيَّة (écrit aussi Agbeya) est le livre des heures des Coptes, avec les sept prières du jour et de la nuit. On l''appelle aussi كِتَاب السَّبْع صَلَوَات, « le livre des sept prières ».", "tip": "Agpeya = le livre des heures.", "extraExample": {"text": "الْأَجْبِيَّةُ فِي الْبَيْتِ", "translation": "L''Agpeya est dans la maison.", "transliteration": "al-adjbiyyatu fî l-bayt"}, "errorPatterns": [{"contains": "bible", "category": "vocabulary", "feedback": "La Bible se dit الْكِتَاب الْمُقَدَّس. L''Agpeya est le livre des heures."}], "pool": "lesson", "lessonId": "ar.l31", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e01', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.mahabba']::text[], 'mcq', 'lesson', 'اللّٰهُ مَحَبَّةٌ', array['Allâhu ma7abba']::text[], 'اللّٰهُ se lit Allâhu (damma). مَحَبَّةٌ = ma-7ab-ba : ح = 7 et la chadda double le ب. C''est la fin du verset : on s''arrête, le tanwîn et le t du ة tombent.', 1, '{"id": "ar.l32.e01", "unitIds": ["ar.g32.tanwin_pause", "ar.v.mahabba"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quelle lecture est la bonne en fin de verset ?", "prompt": "اللّٰهُ مَحَبَّةٌ", "promptLanguage": "ar", "options": ["Allâhu ma7abba", "Allâhu ma7abbatun", "Allâhu mahabba", "Allâhi ma7abba"], "answer": "Allâhu ma7abba", "acceptedAnswers": ["Allâhu ma7abba"], "explanation": "اللّٰهُ se lit Allâhu (damma). مَحَبَّةٌ = ma-7ab-ba : ح = 7 et la chadda double le ب. C''est la fin du verset : on s''arrête, le tanwîn et le t du ة tombent.", "tip": "Fin de phrase : le tanwîn tombe.", "extraExample": {"text": "اللّٰهُ نُورٌ", "translation": "Dieu est lumière.", "transliteration": "Allâhu nûr"}, "errorPatterns": [{"equals": "Allâhu ma7abbatun", "category": "grammar", "feedback": "À la fin du verset, le tanwîn tombe : on dit ma7abba."}, {"equals": "Allâhu mahabba", "category": "spelling", "feedback": "Le ح sans point se note 7 : ma7abba."}, {"equals": "Allâhi ma7abba", "category": "grammar", "feedback": "Le sujet اللّٰهُ porte une damma : Allâhu."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e02', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.nur']::text[], 'mcq', 'lesson', 'نُور', array['nûr']::text[], 'ن avec une damma (nu), puis و : le و après une damma est long, û. Puis ر. On lit nûr.', 1, '{"id": "ar.l32.e02", "unitIds": ["ar.g32.tanwin_pause", "ar.v.nur"], "type": "mcq", "difficulty": 1, "instruction": "Lis vite : quelle lecture est la bonne ?", "prompt": "نُور", "promptLanguage": "ar", "options": ["nûr", "nur", "nâr", "nîr"], "answer": "nûr", "acceptedAnswers": ["nûr"], "explanation": "ن avec une damma (nu), puis و : le و après une damma est long, û. Puis ر. On lit nûr.", "tip": "Damma + و = û long.", "extraExample": {"text": "نُورُ الْعَالَمِ", "translation": "la lumière du monde", "transliteration": "nûru l-3âlam"}, "errorPatterns": [{"equals": "nur", "category": "spelling", "feedback": "Le و après la damma est long : nûr."}, {"equals": "nâr", "category": "spelling", "feedback": "C''est un و, pas un ا : û."}, {"equals": "nîr", "category": "spelling", "feedback": "La damma donne u, pas i."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e03', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.mahabba','ar.v.rai','ar.v.salih','ar.v.nur','ar.v.tariq']::text[], 'match', 'lesson', 'Les mots des versets (1)', '{}'::text[], 'Ces cinq mots viennent de versets très connus : « Dieu est amour », « Je suis le bon berger », « Dieu est lumière », « Je suis le chemin ».', 1, '{"id": "ar.l32.e03", "unitIds": ["ar.g32.tanwin_pause", "ar.v.mahabba", "ar.v.rai", "ar.v.salih", "ar.v.nur", "ar.v.tariq"], "type": "match", "difficulty": 1, "instruction": "Associe chaque mot à sa traduction.", "prompt": "Les mots des versets (1)", "promptLanguage": "fr", "pairs": [{"left": "مَحَبَّة", "right": "amour"}, {"left": "الرَّاعِي", "right": "le berger"}, {"left": "صَالِح", "right": "bon"}, {"left": "نُور", "right": "lumière"}, {"left": "طَرِيق", "right": "chemin"}], "answer": "مَحَبَّة = amour ; الرَّاعِي = le berger ; صَالِح = bon ; نُور = lumière ; طَرِيق = chemin", "acceptedAnswers": [], "explanation": "Ces cinq mots viennent de versets très connus : « Dieu est amour », « Je suis le bon berger », « Dieu est lumière », « Je suis le chemin ».", "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e04', 'ar', 'ar.l32', 'ar.g13.tanwin', array['ar.g13.tanwin','ar.v.mahabba']::text[], 'mcq', 'lesson', 'Quel signe y a-t-il à la fin de مَحَبَّةٌ ?', array['Un tanwîn en damma (-un)']::text[], 'Révision : la damma doublée (ـٌ) donne le tanwîn -un, « un/une », sur un nom sans ال. Avec ال, il ne resterait qu''une seule damma (الْمَحَبَّةُ).', 2, '{"id": "ar.l32.e04", "unitIds": ["ar.g13.tanwin", "ar.v.mahabba"], "type": "mcq", "difficulty": 2, "instruction": "Observe le tanwîn.", "prompt": "Quel signe y a-t-il à la fin de مَحَبَّةٌ ?", "promptLanguage": "fr", "options": ["Un tanwîn en damma (-un)", "Un tanwîn en fatha (-an)", "Un tanwîn en kasra (-in)", "Une simple damma (-u)"], "answer": "Un tanwîn en damma (-un)", "acceptedAnswers": ["Un tanwîn en damma (-un)"], "explanation": "Révision : la damma doublée (ـٌ) donne le tanwîn -un, « un/une », sur un nom sans ال. Avec ال, il ne resterait qu''une seule damma (الْمَحَبَّةُ).", "tip": "Deux dammas = -un.", "extraExample": {"text": "كَلِمَةٌ", "translation": "une parole", "transliteration": "kalimatun"}, "errorPatterns": [{"equals": "Un tanwîn en fatha (-an)", "category": "grammar", "feedback": "Le tanwîn -an s''écrit ـً avec un ا. Ici, le signe est une damma doublée."}, {"equals": "Un tanwîn en kasra (-in)", "category": "grammar", "feedback": "Le tanwîn -in s''écrit sous la lettre. Ici, le signe est au-dessus : c''est une damma."}, {"equals": "Une simple damma (-u)", "category": "grammar", "feedback": "Il y a deux marques de damma, pas une : c''est un tanwîn, -un."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e05', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.mahabba']::text[], 'mcq', 'lesson', 'Dans مَحَبَّةٌ وَنُورٌ, comment lit-on le premier mot, مَحَبَّةٌ ?', array['ma7abbatun']::text[], 'Au milieu d''une phrase, on lit le tanwîn : ma7abbatun wa-nûr. C''est seulement à la fin qu''il tombe.', 2, '{"id": "ar.l32.e05", "unitIds": ["ar.g32.tanwin_pause", "ar.v.mahabba"], "type": "mcq", "difficulty": 2, "instruction": "Observe la pause.", "prompt": "Dans مَحَبَّةٌ وَنُورٌ, comment lit-on le premier mot, مَحَبَّةٌ ?", "promptLanguage": "fr", "options": ["ma7abbatun", "ma7abba", "ma7abbatan", "ma7abbat"], "answer": "ma7abbatun", "acceptedAnswers": ["ma7abbatun"], "explanation": "Au milieu d''une phrase, on lit le tanwîn : ma7abbatun wa-nûr. C''est seulement à la fin qu''il tombe.", "tip": "Milieu : tout se lit ; fin : la voyelle tombe.", "extraExample": {"text": "نُورٌ وَحَيَاةٌ", "translation": "lumière et vie", "transliteration": "nûrun wa-7ayâ"}, "errorPatterns": [{"equals": "ma7abba", "category": "grammar", "feedback": "C''est la lecture à la fin d''une phrase. Ici, un autre mot suit : on lit le tanwîn."}, {"equals": "ma7abbatan", "category": "spelling", "feedback": "Le signe est une damma doublée : -un, pas -an."}, {"equals": "ma7abbat", "category": "spelling", "feedback": "Le tanwîn ajoute le son -un : ma7abbatun."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e06', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.nur']::text[], 'mcq', 'lesson', 'À la fin du verset اللّٰهُ نُورٌ, comment lit-on نُورٌ ?', array['nûr']::text[], 'À la fin d''une phrase, le tanwîn -un tombe : on s''arrête sur nûr, sans voyelle.', 2, '{"id": "ar.l32.e06", "unitIds": ["ar.g32.tanwin_pause", "ar.v.nur"], "type": "mcq", "difficulty": 2, "instruction": "Observe la pause.", "prompt": "À la fin du verset اللّٰهُ نُورٌ, comment lit-on نُورٌ ?", "promptLanguage": "fr", "options": ["nûr", "nûrun", "nûran", "nûrâ"], "answer": "nûr", "acceptedAnswers": ["nûr"], "explanation": "À la fin d''une phrase, le tanwîn -un tombe : on s''arrête sur nûr, sans voyelle.", "tip": "Dernier mot : on s''arrête net.", "extraExample": {"text": "اللّٰهُ مَحَبَّةٌ", "translation": "Dieu est amour.", "transliteration": "Allâhu ma7abba"}, "errorPatterns": [{"equals": "nûrun", "category": "grammar", "feedback": "Le tanwîn se lit au milieu d''une phrase. À la fin, il tombe : nûr."}, {"equals": "nûran", "category": "grammar", "feedback": "Le signe est une damma doublée, jamais -an."}, {"equals": "nûrâ", "category": "grammar", "feedback": "Le signe est une damma doublée : -un au milieu, rien à la fin."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e07', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.hayat']::text[], 'mcq', 'lesson', 'الْحَيَاة', array['al-7ayâ']::text[], 'ح = 7 (lunaire : al-), يَ = ya, ا = â long. Le ة final ne s''entend plus à la pause. Au milieu d''une phrase, on dirait al-7ayâtu.', 2, '{"id": "ar.l32.e07", "unitIds": ["ar.g32.tanwin_pause", "ar.v.hayat"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quelle lecture est la bonne en fin de phrase ?", "prompt": "الْحَيَاة", "promptLanguage": "ar", "options": ["al-7ayâ", "al-7ayâtu", "al-hayâ", "al-7iyâ"], "answer": "al-7ayâ", "acceptedAnswers": ["al-7ayâ"], "explanation": "ح = 7 (lunaire : al-), يَ = ya, ا = â long. Le ة final ne s''entend plus à la pause. Au milieu d''une phrase, on dirait al-7ayâtu.", "tip": "ة après ا long : muet à la pause.", "extraExample": {"text": "حَيَاةُ الْكَنِيسَةِ", "translation": "la vie de l''église", "transliteration": "7ayâtu l-kanîsa"}, "errorPatterns": [{"equals": "al-7ayâtu", "category": "grammar", "feedback": "C''est la lecture au milieu d''une phrase. À la fin, la damma et le t tombent : al-7ayâ."}, {"equals": "al-hayâ", "category": "spelling", "feedback": "Le ح sans point est un 7, pas un h."}, {"equals": "al-7iyâ", "category": "spelling", "feedback": "Sous le ح il y a une fatha : 7a."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e08', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.rai']::text[], 'mcq', 'lesson', 'الرَّاعِي', array['ar-râ3î']::text[], 'ر est une lettre solaire : le l de ال ne se dit pas et le ر est doublé (chadda), ar-. Puis ا long, ع = 3 et ـِي = î long : râ3î.', 2, '{"id": "ar.l32.e08", "unitIds": ["ar.g32.tanwin_pause", "ar.v.rai"], "type": "mcq", "difficulty": 2, "instruction": "Lis vite : quelle lecture est la bonne ?", "prompt": "الرَّاعِي", "promptLanguage": "ar", "options": ["ar-râ3î", "al-râ3î", "ar-ra3î", "ar-râ''î"], "answer": "ar-râ3î", "acceptedAnswers": ["ar-râ3î"], "explanation": "ر est une lettre solaire : le l de ال ne se dit pas et le ر est doublé (chadda), ar-. Puis ا long, ع = 3 et ـِي = î long : râ3î.", "tip": "ال + ر = ar-.", "extraExample": {"text": "الرَّاعِي الصَّالِحُ", "translation": "le bon berger", "transliteration": "ar-râ3î S-Sâli7u"}, "errorPatterns": [{"equals": "al-râ3î", "category": "grammar", "feedback": "ر est solaire : le l tombe, ar-râ3î."}, {"equals": "ar-ra3î", "category": "spelling", "feedback": "Le ا est long : râ."}, {"equals": "ar-râ''î", "category": "spelling", "feedback": "C''est un ع (3), pas une hamza."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e09', 'ar', 'ar.l32', 'ar.g28.nom_adjectif', array['ar.g28.nom_adjectif','ar.v.rai','ar.v.salih']::text[], 'mcq', 'lesson', 'Comment dit-on « le bon berger » ?', array['الرَّاعِي الصَّالِح']::text[], 'Révision de la leçon 28 : l''adjectif suit le nom et reprend ال quand le nom l''a. Sans ال sur l''adjectif, ce serait une phrase : « le berger est bon ».', 2, '{"id": "ar.l32.e09", "unitIds": ["ar.g28.nom_adjectif", "ar.v.rai", "ar.v.salih"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne forme.", "prompt": "Comment dit-on « le bon berger » ?", "promptLanguage": "fr", "options": ["الرَّاعِي الصَّالِح", "الرَّاعِي صَالِح", "رَاعِي الصَّالِح", "الصَّالِح الرَّاعِي"], "answer": "الرَّاعِي الصَّالِح", "acceptedAnswers": ["الرَّاعِي الصَّالِح"], "explanation": "Révision de la leçon 28 : l''adjectif suit le nom et reprend ال quand le nom l''a. Sans ال sur l''adjectif, ce serait une phrase : « le berger est bon ».", "tip": "Nom + adjectif : ال sur les deux.", "extraExample": {"text": "الْكِتَاب الْمُقَدَّس", "translation": "la Bible", "transliteration": "al-kitâb al-muqaddas"}, "errorPatterns": [{"equals": "الرَّاعِي صَالِح", "category": "grammar", "feedback": "Sans ال sur l''adjectif, c''est une phrase : « le berger est bon »."}, {"equals": "رَاعِي الصَّالِح", "category": "grammar", "feedback": "Sans ال sur le premier mot, c''est une annexion : « le berger du bon »."}, {"equals": "الصَّالِح الرَّاعِي", "category": "grammar", "feedback": "L''adjectif se place après le nom, pas avant."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e10', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.kalima']::text[], 'mcq', 'lesson', 'Au début de l''Évangile de Jean : « Au commencement était الْكَلِمَة ». Qui est الْكَلِمَة ?', array['Le Verbe, c''est-à-dire Jésus-Christ']::text[], 'Dans le prologue de saint Jean, الْكَلِمَة est le Verbe (la Parole) : le Christ, qui est auprès de Dieu. Dans la vie courante, كَلِمَة veut simplement dire « un mot ».', 3, '{"id": "ar.l32.e10", "unitIds": ["ar.g32.tanwin_pause", "ar.v.kalima"], "type": "mcq", "difficulty": 3, "instruction": "Réponds à la question.", "prompt": "Au début de l''Évangile de Jean : « Au commencement était الْكَلِمَة ». Qui est الْكَلِمَة ?", "promptLanguage": "fr", "options": ["Le Verbe, c''est-à-dire Jésus-Christ", "Un livre de la Bible", "Un prophète", "Un chant de l''église"], "answer": "Le Verbe, c''est-à-dire Jésus-Christ", "acceptedAnswers": ["Le Verbe, c''est-à-dire Jésus-Christ"], "explanation": "Dans le prologue de saint Jean, الْكَلِمَة est le Verbe (la Parole) : le Christ, qui est auprès de Dieu. Dans la vie courante, كَلِمَة veut simplement dire « un mot ».", "tip": "الْكَلِمَة avec ال = le Verbe.", "extraExample": {"text": "كَلِمَةُ اللّٰهِ", "translation": "la parole de Dieu, le Verbe de Dieu", "transliteration": "kalimatu llâh"}, "errorPatterns": [{"equals": "Un livre de la Bible", "category": "vocabulary", "feedback": "Un livre se dit كِتَاب ou سِفْر. الْكَلِمَة est le Verbe."}, {"equals": "Un prophète", "category": "vocabulary", "feedback": "Un prophète se dit نَبِيّ. الْكَلِمَة est le Verbe."}, {"equals": "Un chant de l''église", "category": "vocabulary", "feedback": "Un chant n''est pas une كَلِمَة au sens de Jean : c''est le Verbe, le Christ."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e11', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.hayat','ar.v.kalima','ar.v.alam','ar.v.haqq','ar.v.nur']::text[], 'match', 'lesson', 'Lecture éclair : les mots des versets (2)', '{}'::text[], 'Le ح sans point se lit 7, le ع se lit 3. La chadda double le ق de 7aqq. Le ة final se lit a à la pause (kalima) ou se tait après un â long (7ayâ).', 2, '{"id": "ar.l32.e11", "unitIds": ["ar.g32.tanwin_pause", "ar.v.hayat", "ar.v.kalima", "ar.v.alam", "ar.v.haqq", "ar.v.nur"], "type": "match", "difficulty": 2, "instruction": "Associe chaque mot à sa lecture.", "prompt": "Lecture éclair : les mots des versets (2)", "promptLanguage": "fr", "pairs": [{"left": "حَقّ", "right": "7aqq"}, {"left": "حَيَاة", "right": "7ayâ"}, {"left": "كَلِمَة", "right": "kalima"}, {"left": "عَالَم", "right": "3âlam"}, {"left": "نُور", "right": "nûr"}], "answer": "حَقّ = 7aqq ; حَيَاة = 7ayâ ; كَلِمَة = kalima ; عَالَم = 3âlam ; نُور = nûr", "acceptedAnswers": [], "explanation": "Le ح sans point se lit 7, le ع se lit 3. La chadda double le ق de 7aqq. Le ة final se lit a à la pause (kalima) ou se tait après un â long (7ayâ).", "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e12', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.mahabba','ar.v.nur','ar.v.tariq','ar.v.haqq','ar.v.hayat']::text[], 'match', 'lesson', 'Cinq versets très courts', '{}'::text[], 'Les deux premiers sont de la première lettre de saint Jean (1 Jean 4:8 et 1:5) ; les trois suivants forment le verset de Jean 14:6.', 3, '{"id": "ar.l32.e12", "unitIds": ["ar.g32.tanwin_pause", "ar.v.mahabba", "ar.v.nur", "ar.v.tariq", "ar.v.haqq", "ar.v.hayat"], "type": "match", "difficulty": 3, "instruction": "Associe chaque verset à sa traduction.", "prompt": "Cinq versets très courts", "promptLanguage": "fr", "pairs": [{"left": "اللّٰهُ مَحَبَّةٌ", "right": "Dieu est amour"}, {"left": "اللّٰهُ نُورٌ", "right": "Dieu est lumière"}, {"left": "أَنَا هُوَ الطَّرِيقُ", "right": "Je suis le chemin"}, {"left": "أَنَا هُوَ الْحَقُّ", "right": "Je suis la vérité"}, {"left": "أَنَا هُوَ الْحَيَاةُ", "right": "Je suis la vie"}], "answer": "اللّٰهُ مَحَبَّةٌ = Dieu est amour ; اللّٰهُ نُورٌ = Dieu est lumière ; أَنَا هُوَ الطَّرِيقُ = Je suis le chemin ; أَنَا هُوَ الْحَقُّ = Je suis la vérité ; أَنَا هُوَ الْحَيَاةُ = Je suis la vie", "acceptedAnswers": [], "explanation": "Les deux premiers sont de la première lettre de saint Jean (1 Jean 4:8 et 1:5) ; les trois suivants forment le verset de Jean 14:6.", "pool": "lesson", "lessonId": "ar.l32", "skill": "recognition"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e13', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.mahabba']::text[], 'fill_blank', 'lesson', 'اللّٰهُ ___', array['مَحَبَّةٌ']::text[], '« Dieu est amour » = اللّٰهُ مَحَبَّةٌ (1 Jean 4:8). Le tanwîn est la marque de l''attribut sans ال.', 2, '{"id": "ar.l32.e13", "unitIds": ["ar.g32.tanwin_pause", "ar.v.mahabba"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète : « Dieu est amour. »", "prompt": "اللّٰهُ ___", "promptLanguage": "ar", "options": ["نُورٌ", "مَحَبَّةٌ", "عَالَمٌ"], "answer": "مَحَبَّةٌ", "acceptedAnswers": ["مَحَبَّةٌ"], "explanation": "« Dieu est amour » = اللّٰهُ مَحَبَّةٌ (1 Jean 4:8). Le tanwîn est la marque de l''attribut sans ال.", "tip": "Amour = مَحَبَّة.", "extraExample": {"text": "اللّٰهُ نُورٌ", "translation": "Dieu est lumière.", "transliteration": "Allâhu nûr"}, "errorPatterns": [{"equals": "نُورٌ", "category": "vocabulary", "feedback": "اللّٰهُ نُورٌ est aussi un verset, mais il veut dire « Dieu est lumière »."}, {"equals": "عَالَمٌ", "category": "vocabulary", "feedback": "عَالَم est le monde : « Dieu est monde » n''a pas de sens."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e14', 'ar', 'ar.l32', 'ar.g31.ya_pronoms_attaches', array['ar.g31.ya_pronoms_attaches','ar.g32.tanwin_pause','ar.v.nur']::text[], 'fill_blank', 'lesson', 'الرَّبُّ نُورُ___', array['نَا']::text[], 'Révision de la leçon 31 : « notre » se dit ـنَا. نُورُ + نَا = نُورُنَا. ـكَ donnerait « ta lumière » et ـهُ « sa lumière ».', 3, '{"id": "ar.l32.e14", "unitIds": ["ar.g31.ya_pronoms_attaches", "ar.g32.tanwin_pause", "ar.v.nur"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Le Seigneur est notre lumière. »", "prompt": "الرَّبُّ نُورُ___", "promptLanguage": "ar", "options": ["كَ", "نَا", "هُ"], "answer": "نَا", "acceptedAnswers": ["نَا"], "explanation": "Révision de la leçon 31 : « notre » se dit ـنَا. نُورُ + نَا = نُورُنَا. ـكَ donnerait « ta lumière » et ـهُ « sa lumière ».", "tip": "نَا = notre.", "extraExample": {"text": "رَبُّنَا", "translation": "notre Seigneur", "transliteration": "rabbunâ"}, "errorPatterns": [{"equals": "كَ", "category": "grammar", "feedback": "ـكَ veut dire « ton, ta » : « ta lumière ». Ici, c''est « notre »."}, {"equals": "هُ", "category": "grammar", "feedback": "ـهُ veut dire « son, sa » : « sa lumière ». Ici, c''est « notre »."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e15', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.haqq','ar.v.tariq','ar.v.hayat']::text[], 'fill_blank', 'lesson', 'أَنَا هُوَ الطَّرِيقُ وَالْحَقُّ وَ___', array['الْحَيَاةُ']::text[], 'Les trois noms sont définis (ils ont ال) : ils gardent une simple damma, sans tanwîn. À la fin du verset, on les lit al-7ayâ, sans la damma ni le t.', 3, '{"id": "ar.l32.e15", "unitIds": ["ar.g32.tanwin_pause", "ar.v.haqq", "ar.v.tariq", "ar.v.hayat"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète : « Je suis le chemin, la vérité et la vie. »", "prompt": "أَنَا هُوَ الطَّرِيقُ وَالْحَقُّ وَ___", "promptLanguage": "ar", "options": ["حَيَاةٌ", "الْحَيَاةِ", "الْحَيَاةُ"], "answer": "الْحَيَاةُ", "acceptedAnswers": ["الْحَيَاةُ"], "explanation": "Les trois noms sont définis (ils ont ال) : ils gardent une simple damma, sans tanwîn. À la fin du verset, on les lit al-7ayâ, sans la damma ni le t.", "tip": "Avec ال : une seule damma.", "extraExample": {"text": "الْحَقُّ جَمِيلٌ", "translation": "La vérité est belle.", "transliteration": "al-7aqqu djamîl"}, "errorPatterns": [{"equals": "حَيَاةٌ", "category": "grammar", "feedback": "Avec un tanwîn, ce serait « une vie ». Ici, les trois mots ont ال."}, {"equals": "الْحَيَاةِ", "category": "grammar", "feedback": "Une kasra suit فِي ou مِنْ. Ici, le mot est un attribut, avec une damma."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e16', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.nur','ar.v.alam']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : Je suis (2 mots) / la lumière de / le monde', array['أَنَا هُوَ نُورُ الْعَالَمِ']::text[], 'أَنَا هُوَ = « moi, je suis ». Puis une annexion : نُورُ (sans ال) + الْعَالَمِ (avec ال et une kasra), comme عِيدُ الْمِيلَادِ dans la leçon 29.', 2, '{"id": "ar.l32.e16", "unitIds": ["ar.g32.tanwin_pause", "ar.v.nur", "ar.v.alam"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre : « Je suis la lumière du monde. »", "prompt": "Remets dans l''ordre : Je suis (2 mots) / la lumière de / le monde", "promptLanguage": "fr", "tokens": ["هُوَ", "الْعَالَمِ", "أَنَا", "نُورُ"], "answer": "أَنَا هُوَ نُورُ الْعَالَمِ", "acceptedAnswers": ["أَنَا هُوَ نُورُ الْعَالَمِ"], "explanation": "أَنَا هُوَ = « moi, je suis ». Puis une annexion : نُورُ (sans ال) + الْعَالَمِ (avec ال et une kasra), comme عِيدُ الْمِيلَادِ dans la leçon 29.", "tip": "Premier nom nu, puis le nom précis.", "extraExample": {"text": "نُورُ الْكَنِيسَةِ", "translation": "la lumière de l''église", "transliteration": "nûru l-kanîsa"}, "pool": "lesson", "lessonId": "ar.l32", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e17', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.rai','ar.v.salih']::text[], 'reorder', 'lesson', 'Remets dans l''ordre : Je suis (2 mots) / le berger / le bon', array['أَنَا هُوَ الرَّاعِي الصَّالِحُ']::text[], 'أَنَا هُوَ vient d''abord, puis le nom (الرَّاعِي) et son adjectif (الصَّالِحُ), qui reprend ال.', 3, '{"id": "ar.l32.e17", "unitIds": ["ar.g32.tanwin_pause", "ar.v.rai", "ar.v.salih"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre : « Je suis le bon berger. »", "prompt": "Remets dans l''ordre : Je suis (2 mots) / le berger / le bon", "promptLanguage": "fr", "tokens": ["الصَّالِحُ", "أَنَا", "الرَّاعِي", "هُوَ"], "answer": "أَنَا هُوَ الرَّاعِي الصَّالِحُ", "acceptedAnswers": ["أَنَا هُوَ الرَّاعِي الصَّالِحُ"], "explanation": "أَنَا هُوَ vient d''abord, puis le nom (الرَّاعِي) et son adjectif (الصَّالِحُ), qui reprend ال.", "tip": "Nom d''abord, adjectif ensuite.", "extraExample": {"text": "الْعَهْد الْجَدِيد", "translation": "le Nouveau Testament", "transliteration": "al-3ahd al-djadîd"}, "pool": "lesson", "lessonId": "ar.l32", "skill": "recall"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e18', 'ar', 'ar.l32', 'ar.v.ana', array['ar.v.ana','ar.v.huwa','ar.g32.tanwin_pause','ar.v.tariq']::text[], 'translation', 'lesson', 'أَنَا هُوَ الطَّرِيقُ', array['Je suis le chemin.','Moi, je suis le chemin.','C''est moi, le chemin.','Je suis la route.']::text[], 'أَنَا = je (leçon 22) ; هُوَ ajoute l''insistance, « c''est moi qui suis » ; الطَّرِيقُ = le chemin. Le verbe « être » ne s''écrit pas.', 2, '{"id": "ar.l32.e18", "unitIds": ["ar.v.ana", "ar.v.huwa", "ar.g32.tanwin_pause", "ar.v.tariq"], "type": "translation", "difficulty": 2, "instruction": "Traduis en français.", "prompt": "أَنَا هُوَ الطَّرِيقُ", "promptLanguage": "ar", "answer": "Je suis le chemin.", "acceptedAnswers": ["Je suis le chemin.", "Moi, je suis le chemin.", "C''est moi, le chemin.", "Je suis la route."], "explanation": "أَنَا = je (leçon 22) ; هُوَ ajoute l''insistance, « c''est moi qui suis » ; الطَّرِيقُ = le chemin. Le verbe « être » ne s''écrit pas.", "tip": "أَنَا هُوَ = « Je suis ».", "extraExample": {"text": "هُوَ الطَّرِيقُ", "translation": "Il est le chemin.", "transliteration": "huwa T-Tarîq"}, "errorPatterns": [{"contains": "vérité", "category": "vocabulary", "feedback": "La vérité se dit حَقّ. Ici, le mot est الطَّرِيق : le chemin."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e19', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.mahabba','ar.v.nur']::text[], 'translation', 'lesson', 'اللّٰهُ نُورٌ وَمَحَبَّةٌ', array['Dieu est lumière et amour.','Dieu est la lumière et l''amour.','Dieu est lumière et Dieu est amour.']::text[], 'Deux attributs sans ال, reliés par وَ : نُورٌ وَمَحَبَّةٌ. Au milieu de la phrase, on lit le tanwîn de نُورٌ : Allâhu nûrun wa-ma7abba.', 3, '{"id": "ar.l32.e19", "unitIds": ["ar.g32.tanwin_pause", "ar.v.mahabba", "ar.v.nur"], "type": "translation", "difficulty": 3, "instruction": "Traduis en français.", "prompt": "اللّٰهُ نُورٌ وَمَحَبَّةٌ", "promptLanguage": "ar", "answer": "Dieu est lumière et amour.", "acceptedAnswers": ["Dieu est lumière et amour.", "Dieu est la lumière et l''amour.", "Dieu est lumière et Dieu est amour."], "explanation": "Deux attributs sans ال, reliés par وَ : نُورٌ وَمَحَبَّةٌ. Au milieu de la phrase, on lit le tanwîn de نُورٌ : Allâhu nûrun wa-ma7abba.", "tip": "Sans ال : on ne traduit pas « un ».", "extraExample": {"text": "الْكَلِمَةُ نُورٌ", "translation": "La parole est lumière.", "transliteration": "al-kalimatu nûr"}, "errorPatterns": [{"contains": "monde", "category": "vocabulary", "feedback": "Le monde se dit عَالَم. Ici, le mot est نُور : la lumière."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e20', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.nur']::text[], 'free_answer', 'lesson', 'اللّٰهُ نُورٌ', array['Allâhu nûr','Allahu nur','Allaahu nuur']::text[], 'Sujet avec damma (Allâhu), puis l''attribut nûr. À la fin du verset, le tanwîn tombe : on s''arrête sur nûr (1 Jean 1:5).', 3, '{"id": "ar.l32.e20", "unitIds": ["ar.g32.tanwin_pause", "ar.v.nur"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la lecture en lettres latines, comme à la fin d''un verset.", "prompt": "اللّٰهُ نُورٌ", "promptLanguage": "ar", "answer": "Allâhu nûr", "acceptedAnswers": ["Allâhu nûr", "Allahu nur", "Allaahu nuur"], "hint": "Le dernier mot s''arrête sans -un.", "explanation": "Sujet avec damma (Allâhu), puis l''attribut nûr. À la fin du verset, le tanwîn tombe : on s''arrête sur nûr (1 Jean 1:5).", "tip": "Allâhu + nûr.", "extraExample": {"text": "اللّٰهُ مَحَبَّةٌ", "translation": "Dieu est amour.", "transliteration": "Allâhu ma7abba"}, "errorPatterns": [{"equals": "Allâhu nûrun", "category": "grammar", "feedback": "À la fin du verset, le tanwîn tombe : nûr."}, {"equals": "Allahu nûrun", "category": "grammar", "feedback": "À la fin du verset, le tanwîn tombe : nûr."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l32.e21', 'ar', 'ar.l32', 'ar.g32.tanwin_pause', array['ar.g32.tanwin_pause','ar.v.kalima']::text[], 'free_answer', 'lesson', 'كَلِمَةٌ', array['une parole','un mot','parole','mot','une parole, un mot']::text[], 'كَلِمَة est un mot, une parole. Le tanwîn dit « un, une ». Avec ال, الْكَلِمَة est le Verbe, le Christ (Jean 1).', 3, '{"id": "ar.l32.e21", "unitIds": ["ar.g32.tanwin_pause", "ar.v.kalima"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la traduction en français.", "prompt": "كَلِمَةٌ", "promptLanguage": "ar", "answer": "une parole", "acceptedAnswers": ["une parole", "un mot", "parole", "mot", "une parole, un mot"], "explanation": "كَلِمَة est un mot, une parole. Le tanwîn dit « un, une ». Avec ال, الْكَلِمَة est le Verbe, le Christ (Jean 1).", "tip": "كَلِمَة : mot, parole, Verbe.", "extraExample": {"text": "كَلِمَةُ اللّٰهِ", "translation": "la parole de Dieu, le Verbe de Dieu", "transliteration": "kalimatu llâh"}, "errorPatterns": [{"contains": "livre", "category": "vocabulary", "feedback": "Un livre se dit كِتَاب. Ici, le mot est كَلِمَة : un mot, une parole."}], "pool": "lesson", "lessonId": "ar.l32", "skill": "production"}'::jsonb, '2026.10.22', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.alif', 'ar', 'ا', 'la lettre alif, qui allonge le son a (â)', 'Alif est un simple trait vertical. Après une lettre portant a, il l''allonge : بَاب se lit bâb, avec un a long. Au début d''un mot, il porte presque toujours une hamza (أ ou إ) et se lit a, i ou u. Il s''attache à la lettre d''avant (ـا) mais jamais à la suivante : il n''a donc que deux formes, ا et ـا.', '[{"text": "بَاب", "translation": "la porte (ا au milieu, attaché à ب)", "transliteration": "bâb"}, {"text": "أَثَاث", "translation": "les meubles (ا au début, avec une hamza)", "transliteration": "athâth"}]'::jsonb, null, '{"id": "ar.d.alif", "word": "ا", "translation": "la lettre alif, qui allonge le son a (â)", "partOfSpeech": "letter", "transliteration": "alif", "explanation": "Alif est un simple trait vertical. Après une lettre portant a, il l''allonge : بَاب se lit bâb, avec un a long. Au début d''un mot, il porte presque toujours une hamza (أ ou إ) et se lit a, i ou u. Il s''attache à la lettre d''avant (ـا) mais jamais à la suivante : il n''a donc que deux formes, ا et ـا.", "examples": [{"text": "بَاب", "translation": "la porte (ا au milieu, attaché à ب)", "transliteration": "bâb"}, {"text": "أَثَاث", "translation": "les meubles (ا au début, avec une hamza)", "transliteration": "athâth"}], "confusions": [{"word": "لـ", "note": "lâm au début d''un mot est aussi un trait vertical, mais il est relié à la lettre suivante ; alif ne l''est jamais."}], "forms": {"isolated": "ا", "initial": "ا", "medial": "ـا", "final": "ـا"}, "unitId": "ar.v.alif"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ba', 'ar', 'ب', 'la lettre bâ'', le son b', 'ب se prononce b, comme dans « bol ». Son corps est une cuvette quand il est isolé ou à la fin (ب, ـب) et une petite dent au début ou au milieu (بـ, ـبـ). Son signe distinctif : un seul point, en dessous.', '[{"text": "بَيْت", "translation": "la maison (ب au début)", "transliteration": "bayt"}, {"text": "كُتُب", "translation": "des livres (ب à la fin, attaché)", "transliteration": "kutub"}]'::jsonb, null, '{"id": "ar.d.ba", "word": "ب", "translation": "la lettre bâ'', le son b", "partOfSpeech": "letter", "transliteration": "bâ''", "explanation": "ب se prononce b, comme dans « bol ». Son corps est une cuvette quand il est isolé ou à la fin (ب, ـب) et une petite dent au début ou au milieu (بـ, ـبـ). Son signe distinctif : un seul point, en dessous.", "examples": [{"text": "بَيْت", "translation": "la maison (ب au début)", "transliteration": "bayt"}, {"text": "كُتُب", "translation": "des livres (ب à la fin, attaché)", "transliteration": "kutub"}], "confusions": [{"word": "ت", "note": "même corps, mais deux points au-dessus : t."}, {"word": "ن", "note": "un seul point aussi, mais au-dessus : n."}, {"word": "ي", "note": "deux points en dessous : y ou î."}], "forms": {"isolated": "ب", "initial": "بـ", "medial": "ـبـ", "final": "ـب"}, "unitId": "ar.v.ba"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ta', 'ar', 'ت', 'la lettre tâ'', le son t', 'ت se prononce t, comme en français. Même corps que ب (cuvette isolée ou finale, dent au début ou au milieu), mais avec deux points au-dessus.', '[{"text": "تِين", "translation": "les figues (ت au début)", "transliteration": "tîn"}, {"text": "بَيْت", "translation": "la maison (ت à la fin, attaché)", "transliteration": "bayt"}]'::jsonb, null, '{"id": "ar.d.ta", "word": "ت", "translation": "la lettre tâ'', le son t", "partOfSpeech": "letter", "transliteration": "tâ''", "explanation": "ت se prononce t, comme en français. Même corps que ب (cuvette isolée ou finale, dent au début ou au milieu), mais avec deux points au-dessus.", "examples": [{"text": "تِين", "translation": "les figues (ت au début)", "transliteration": "tîn"}, {"text": "بَيْت", "translation": "la maison (ت à la fin, attaché)", "transliteration": "bayt"}], "confusions": [{"word": "ث", "note": "trois points au-dessus : th anglais."}, {"word": "ب", "note": "un point en dessous : b."}, {"word": "ة", "note": "tâ'' marbûTa : deux points sur une petite boucle, toujours à la fin d''un mot."}], "forms": {"isolated": "ت", "initial": "تـ", "medial": "ـتـ", "final": "ـت"}, "unitId": "ar.v.ta"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.tha', 'ar', 'ث', 'la lettre thâ'', le son th de « think »', 'ث se prononce comme le th anglais de « think » : le bout de la langue entre les dents, sans faire vibrer la voix. Ce n''est ni un s ni un t. Même corps que ب et ت, avec trois points au-dessus.', '[{"text": "ثَوْب", "translation": "le vêtement (ث au début)", "transliteration": "thawb"}, {"text": "أَثَاث", "translation": "les meubles (le dernier ث est isolé, après ا)", "transliteration": "athâth"}]'::jsonb, null, '{"id": "ar.d.tha", "word": "ث", "translation": "la lettre thâ'', le son th de « think »", "partOfSpeech": "letter", "transliteration": "thâ''", "explanation": "ث se prononce comme le th anglais de « think » : le bout de la langue entre les dents, sans faire vibrer la voix. Ce n''est ni un s ni un t. Même corps que ب et ت, avec trois points au-dessus.", "examples": [{"text": "ثَوْب", "translation": "le vêtement (ث au début)", "transliteration": "thawb"}, {"text": "أَثَاث", "translation": "les meubles (le dernier ث est isolé, après ا)", "transliteration": "athâth"}], "confusions": [{"word": "ت", "note": "deux points seulement : t."}, {"word": "ش", "note": "trois points aussi, mais posés sur trois dents : ch."}, {"word": "ذ", "note": "dh, le th « sonore » de l''anglais « this »."}], "forms": {"isolated": "ث", "initial": "ثـ", "medial": "ـثـ", "final": "ـث"}, "unitId": "ar.v.tha"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bab', 'ar', 'بَاب', 'la porte', 'Un mot à lire d''un seul coup d''œil : ب au début, ا qui allonge le a, puis un ب isolé, car ا ne s''attache pas à la lettre suivante.', '[{"text": "أَبْوَاب", "translation": "des portes", "transliteration": "abwâb"}, {"text": "بَابِي", "translation": "ma porte", "transliteration": "bâbî"}]'::jsonb, null, '{"id": "ar.d.bab", "word": "بَاب", "translation": "la porte", "partOfSpeech": "noun", "transliteration": "bâb", "explanation": "Un mot à lire d''un seul coup d''œil : ب au début, ا qui allonge le a, puis un ب isolé, car ا ne s''attache pas à la lettre suivante.", "examples": [{"text": "أَبْوَاب", "translation": "des portes", "transliteration": "abwâb"}, {"text": "بَابِي", "translation": "ma porte", "transliteration": "bâbî"}], "forms": {"plural": "أَبْوَاب"}, "unitId": "ar.v.bab"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kitab', 'ar', 'كِتَاب', 'le livre', 'ك au début, ت au milieu (deux points au-dessus), ا qui allonge le a, puis ب isolé après ا.', '[{"text": "كُتُب", "translation": "des livres", "transliteration": "kutub"}, {"text": "كِتَابِي", "translation": "mon livre", "transliteration": "kitâbî"}]'::jsonb, null, '{"id": "ar.d.kitab", "word": "كِتَاب", "translation": "le livre", "partOfSpeech": "noun", "transliteration": "kitâb", "explanation": "ك au début, ت au milieu (deux points au-dessus), ا qui allonge le a, puis ب isolé après ا.", "examples": [{"text": "كُتُب", "translation": "des livres", "transliteration": "kutub"}, {"text": "كِتَابِي", "translation": "mon livre", "transliteration": "kitâbî"}], "confusions": [{"word": "كُتُب", "note": "kutub : le pluriel, des livres."}], "forms": {"plural": "كُتُب"}, "unitId": "ar.v.kitab"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.thawb', 'ar', 'ثَوْب', 'le vêtement', 'Désigne un vêtement, et en particulier la longue robe portée au Moyen-Orient. ث au début (trois points), و qui ne s''attache pas à la suite, puis ب isolé.', '[{"text": "ثِيَاب", "translation": "des vêtements", "transliteration": "thiyâb"}, {"text": "ثَوْبِي", "translation": "mon vêtement", "transliteration": "thawbî"}]'::jsonb, null, '{"id": "ar.d.thawb", "word": "ثَوْب", "translation": "le vêtement", "otherTranslations": ["la robe longue, la tunique"], "partOfSpeech": "noun", "transliteration": "thawb", "explanation": "Désigne un vêtement, et en particulier la longue robe portée au Moyen-Orient. ث au début (trois points), و qui ne s''attache pas à la suite, puis ب isolé.", "examples": [{"text": "ثِيَاب", "translation": "des vêtements", "transliteration": "thiyâb"}, {"text": "ثَوْبِي", "translation": "mon vêtement", "transliteration": "thawbî"}], "forms": {"plural": "ثِيَاب"}, "unitId": "ar.v.thawb"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.athath', 'ar', 'أَثَاث', 'les meubles', 'Nom collectif : il désigne l''ensemble des meubles d''une maison. Il commence par un alif avec hamza (أ, son a), puis ث, ا, et un ث isolé à la fin.', '[{"text": "أَثَاثِي", "translation": "mes meubles", "transliteration": "athâthî"}, {"text": "قِطْعَةُ أَثَاث", "translation": "un meuble (une pièce de mobilier)", "transliteration": "qiT3atu athâth"}]'::jsonb, null, '{"id": "ar.d.athath", "word": "أَثَاث", "translation": "les meubles", "otherTranslations": ["le mobilier"], "partOfSpeech": "noun", "transliteration": "athâth", "explanation": "Nom collectif : il désigne l''ensemble des meubles d''une maison. Il commence par un alif avec hamza (أ, son a), puis ث, ا, et un ث isolé à la fin.", "examples": [{"text": "أَثَاثِي", "translation": "mes meubles", "transliteration": "athâthî"}, {"text": "قِطْعَةُ أَثَاث", "translation": "un meuble (une pièce de mobilier)", "transliteration": "qiT3atu athâth"}], "unitId": "ar.v.athath"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.nun', 'ar', 'ن', 'la lettre nûn, le son n', 'ن se prononce n, comme dans « nuit ». Au début et au milieu, c''est la même petite dent que ب ت ث ; à la fin ou isolée, c''est une cuvette. Son signe distinctif : un seul point, au-dessus.', '[{"text": "نَبَات", "translation": "la plante (ن au début)", "transliteration": "nabât"}, {"text": "تِين", "translation": "les figues (ن à la fin, attaché)", "transliteration": "tîn"}]'::jsonb, null, '{"id": "ar.d.nun", "word": "ن", "translation": "la lettre nûn, le son n", "partOfSpeech": "letter", "transliteration": "nûn", "explanation": "ن se prononce n, comme dans « nuit ». Au début et au milieu, c''est la même petite dent que ب ت ث ; à la fin ou isolée, c''est une cuvette. Son signe distinctif : un seul point, au-dessus.", "examples": [{"text": "نَبَات", "translation": "la plante (ن au début)", "transliteration": "nabât"}, {"text": "تِين", "translation": "les figues (ن à la fin, attaché)", "transliteration": "tîn"}], "confusions": [{"word": "ب", "note": "même corps, mais le point est en dessous : b."}, {"word": "ت", "note": "deux points au-dessus : t."}, {"word": "ث", "note": "trois points au-dessus : th."}, {"word": "ي", "note": "deux points en dessous : y ou î."}], "forms": {"isolated": "ن", "initial": "نـ", "medial": "ـنـ", "final": "ـن"}, "unitId": "ar.v.nun"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ya', 'ar', 'ي', 'la lettre yâ'', le son y ou î', 'ي est tantôt la consonne y (comme dans « yaourt »), tantôt la voyelle longue î (comme dans تِين, tîn). Son signe distinctif : deux points en dessous. À la fin ou isolée, elle s''étire en une longue queue qui revient vers la gauche.', '[{"text": "بَيْنَ", "translation": "entre (ي au milieu, consonne y)", "transliteration": "bayna"}, {"text": "تِين", "translation": "les figues (ي au milieu, î long)", "transliteration": "tîn"}]'::jsonb, null, '{"id": "ar.d.ya", "word": "ي", "translation": "la lettre yâ'', le son y ou î", "partOfSpeech": "letter", "transliteration": "yâ''", "explanation": "ي est tantôt la consonne y (comme dans « yaourt »), tantôt la voyelle longue î (comme dans تِين, tîn). Son signe distinctif : deux points en dessous. À la fin ou isolée, elle s''étire en une longue queue qui revient vers la gauche.", "examples": [{"text": "بَيْنَ", "translation": "entre (ي au milieu, consonne y)", "transliteration": "bayna"}, {"text": "تِين", "translation": "les figues (ي au milieu, î long)", "transliteration": "tîn"}], "confusions": [{"word": "ت", "note": "deux points aussi, mais au-dessus : t."}, {"word": "ب", "note": "un seul point, en dessous : b."}, {"word": "ى", "note": "alif maqsûra : même queue, mais sans aucun point, à la fin de certains mots."}], "forms": {"isolated": "ي", "initial": "يـ", "medial": "ـيـ", "final": "ـي"}, "unitId": "ar.v.ya"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.tin', 'ar', 'تِين', 'les figues', 'Nom collectif : تِين désigne les figues en général (une seule figue se dit تِينَة). Lecture : ت (deux points dessus), ي qui note le î long (deux points dessous), puis ن final (un point dessus).', '[{"text": "تِينَة", "translation": "une figue", "transliteration": "tîna"}, {"text": "شَجَرَةُ تِين", "translation": "un figuier", "transliteration": "chadjaratu tîn"}]'::jsonb, null, '{"id": "ar.d.tin", "word": "تِين", "translation": "les figues", "partOfSpeech": "noun", "transliteration": "tîn", "explanation": "Nom collectif : تِين désigne les figues en général (une seule figue se dit تِينَة). Lecture : ت (deux points dessus), ي qui note le î long (deux points dessous), puis ن final (un point dessus).", "examples": [{"text": "تِينَة", "translation": "une figue", "transliteration": "tîna"}, {"text": "شَجَرَةُ تِين", "translation": "un figuier", "transliteration": "chadjaratu tîn"}], "forms": {"unité": "تِينَة"}, "unitId": "ar.v.tin"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.banat', 'ar', 'بَنَات', 'les filles', 'Pluriel de بِنْت (une fille). ب au début, ن au milieu (un point dessus), ا qui allonge le a, puis ت isolé (deux points dessus) car ا ne s''attache pas à la suite.', '[{"text": "بِنْت", "translation": "une fille (singulier)", "transliteration": "bint"}, {"text": "بَنَاتِي", "translation": "mes filles", "transliteration": "banâtî"}]'::jsonb, null, '{"id": "ar.d.banat", "word": "بَنَات", "translation": "les filles", "otherTranslations": ["les jeunes filles"], "partOfSpeech": "noun", "transliteration": "banât", "explanation": "Pluriel de بِنْت (une fille). ب au début, ن au milieu (un point dessus), ا qui allonge le a, puis ت isolé (deux points dessus) car ا ne s''attache pas à la suite.", "examples": [{"text": "بِنْت", "translation": "une fille (singulier)", "transliteration": "bint"}, {"text": "بَنَاتِي", "translation": "mes filles", "transliteration": "banâtî"}], "forms": {"singulier": "بِنْت"}, "unitId": "ar.v.banat"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.nabat', 'ar', 'نَبَات', 'la plante', 'Nom collectif : la végétation, la plante en général. ن au début (un point dessus), ب au milieu (un point dessous), ا qui allonge le a, puis ت isolé (deux points dessus).', '[{"text": "نَبَاتَات", "translation": "des plantes", "transliteration": "nabâtât"}, {"text": "نَبَاتِيّ", "translation": "végétal, végétarien", "transliteration": "nabâtî"}]'::jsonb, null, '{"id": "ar.d.nabat", "word": "نَبَات", "translation": "la plante", "otherTranslations": ["la végétation"], "partOfSpeech": "noun", "transliteration": "nabât", "explanation": "Nom collectif : la végétation, la plante en général. ن au début (un point dessus), ب au milieu (un point dessous), ا qui allonge le a, puis ت isolé (deux points dessus).", "examples": [{"text": "نَبَاتَات", "translation": "des plantes", "transliteration": "nabâtât"}, {"text": "نَبَاتِيّ", "translation": "végétal, végétarien", "transliteration": "nabâtî"}], "confusions": [{"word": "بَنَات", "note": "banât : les filles. Mêmes lettres, ordre différent : regarde la première lettre."}], "forms": {"plural": "نَبَاتَات"}, "unitId": "ar.v.nabat"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bayna', 'ar', 'بَيْنَ', 'entre', 'Petit mot très fréquent qui indique ce qui se trouve au milieu de deux choses. ب (un point dessous), ي (deux points dessous) puis ن final (un point dessus).', '[{"text": "بَيْنَ الْبَيْتِ وَالْبَابِ", "translation": "entre la maison et la porte", "transliteration": "bayna l-bayti wa-l-bâbi"}, {"text": "بَيْنِي وَبَيْنَكَ", "translation": "entre moi et toi", "transliteration": "baynî wa-baynaka"}]'::jsonb, null, '{"id": "ar.d.bayna", "word": "بَيْنَ", "translation": "entre", "otherTranslations": ["parmi"], "partOfSpeech": "preposition", "transliteration": "bayna", "explanation": "Petit mot très fréquent qui indique ce qui se trouve au milieu de deux choses. ب (un point dessous), ي (deux points dessous) puis ن final (un point dessus).", "examples": [{"text": "بَيْنَ الْبَيْتِ وَالْبَابِ", "translation": "entre la maison et la porte", "transliteration": "bayna l-bayti wa-l-bâbi"}, {"text": "بَيْنِي وَبَيْنَكَ", "translation": "entre moi et toi", "transliteration": "baynî wa-baynaka"}], "confusions": [{"word": "بَيْت", "note": "bayt : la maison. Mêmes premières lettres, mais ت à la fin."}], "unitId": "ar.v.bayna"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.djim', 'ar', 'ج', 'la lettre djîm, le son dj', 'ج se prononce dj en arabe standard, comme dans « jazz » (en Égypte, on dit plutôt g, comme dans « gare »). Son signe distinctif : un point à l''intérieur de la courbe, sous la tête.', '[{"text": "جَزَر", "translation": "les carottes (ج au début)", "transliteration": "djazar"}, {"text": "تَاج", "translation": "la couronne (ج isolé, après ا)", "transliteration": "tâdj"}]'::jsonb, null, '{"id": "ar.d.djim", "word": "ج", "translation": "la lettre djîm, le son dj", "partOfSpeech": "letter", "transliteration": "djîm", "explanation": "ج se prononce dj en arabe standard, comme dans « jazz » (en Égypte, on dit plutôt g, comme dans « gare »). Son signe distinctif : un point à l''intérieur de la courbe, sous la tête.", "examples": [{"text": "جَزَر", "translation": "les carottes (ج au début)", "transliteration": "djazar"}, {"text": "تَاج", "translation": "la couronne (ج isolé, après ا)", "transliteration": "tâdj"}], "confusions": [{"word": "ح", "note": "même silhouette, sans aucun point : 7."}, {"word": "خ", "note": "même silhouette, point au-dessus : kh."}, {"word": "ث", "note": "ne pas confondre avec les dents à points : ج est un crochet."}], "forms": {"isolated": "ج", "initial": "جـ", "medial": "ـجـ", "final": "ـج"}, "unitId": "ar.v.djim"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.hha', 'ar', 'ح', 'la lettre 7â'', un h soufflé du fond de la gorge', 'ح est un h expiré fort, du fond de la gorge, comme quand on souffle sur une vitre pour l''embuer. On le note 7. Son signe distinctif : aucun point.', '[{"text": "حَبِيب", "translation": "le chéri (ح au début)", "transliteration": "7abîb"}, {"text": "تَحْتَ", "translation": "sous (ح au milieu)", "transliteration": "ta7ta"}]'::jsonb, null, '{"id": "ar.d.hha", "word": "ح", "translation": "la lettre 7â'', un h soufflé du fond de la gorge", "partOfSpeech": "letter", "transliteration": "7â''", "explanation": "ح est un h expiré fort, du fond de la gorge, comme quand on souffle sur une vitre pour l''embuer. On le note 7. Son signe distinctif : aucun point.", "examples": [{"text": "حَبِيب", "translation": "le chéri (ح au début)", "transliteration": "7abîb"}, {"text": "تَحْتَ", "translation": "sous (ح au milieu)", "transliteration": "ta7ta"}], "confusions": [{"word": "ج", "note": "même silhouette, avec un point dans la courbe : dj."}, {"word": "خ", "note": "même silhouette, avec un point au-dessus : kh."}, {"word": "ه", "note": "le h léger de « hop » (leçon 7) : ح est beaucoup plus rauque."}], "forms": {"isolated": "ح", "initial": "حـ", "medial": "ـحـ", "final": "ـح"}, "unitId": "ar.v.hha"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kha', 'ar', 'خ', 'la lettre khâ'', le son kh', 'خ se prononce comme le j de l''espagnol « jota » ou le ch de l''allemand « Bach » : un souffle frotté au fond de la gorge. Son signe distinctif : un point au-dessus.', '[{"text": "خَاتَم", "translation": "la bague (خ au début)", "transliteration": "khâtam"}, {"text": "مَطْبَخ", "translation": "la cuisine (خ à la fin, attaché)", "transliteration": "maTbakh"}]'::jsonb, null, '{"id": "ar.d.kha", "word": "خ", "translation": "la lettre khâ'', le son kh", "partOfSpeech": "letter", "transliteration": "khâ''", "explanation": "خ se prononce comme le j de l''espagnol « jota » ou le ch de l''allemand « Bach » : un souffle frotté au fond de la gorge. Son signe distinctif : un point au-dessus.", "examples": [{"text": "خَاتَم", "translation": "la bague (خ au début)", "transliteration": "khâtam"}, {"text": "مَطْبَخ", "translation": "la cuisine (خ à la fin, attaché)", "transliteration": "maTbakh"}], "confusions": [{"word": "ح", "note": "même silhouette, sans point : 7."}, {"word": "ج", "note": "même silhouette, point dans la courbe : dj."}], "forms": {"isolated": "خ", "initial": "خـ", "medial": "ـخـ", "final": "ـخ"}, "unitId": "ar.v.kha"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.habib', 'ar', 'حَبِيب', 'le chéri, l''ami cher', 'Mot d''affection très courant : on l''emploie pour un proche, un ami, un enfant (« mon chéri »). ح au début (aucun point), ب au milieu (un point dessous), ي qui note le î long, puis ب final.', '[{"text": "حَبِيبِي", "translation": "mon chéri", "transliteration": "7abîbî"}, {"text": "حَبِيبَتِي", "translation": "ma chérie", "transliteration": "7abîbatî"}]'::jsonb, null, '{"id": "ar.d.habib", "word": "حَبِيب", "translation": "le chéri, l''ami cher", "partOfSpeech": "noun", "transliteration": "7abîb", "explanation": "Mot d''affection très courant : on l''emploie pour un proche, un ami, un enfant (« mon chéri »). ح au début (aucun point), ب au milieu (un point dessous), ي qui note le î long, puis ب final.", "examples": [{"text": "حَبِيبِي", "translation": "mon chéri", "transliteration": "7abîbî"}, {"text": "حَبِيبَتِي", "translation": "ma chérie", "transliteration": "7abîbatî"}], "forms": {"féminin": "حَبِيبَة"}, "unitId": "ar.v.habib"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.tahta', 'ar', 'تَحْتَ', 'sous, en dessous de', 'Petit mot de lieu très fréquent. ت au début (deux points dessus), ح au milieu (aucun point), ت final (deux points dessus).', '[{"text": "تَحْتَ الْبَابِ", "translation": "sous la porte", "transliteration": "ta7ta l-bâbi"}, {"text": "تَحْتَ الْكِتَابِ", "translation": "sous le livre", "transliteration": "ta7ta l-kitâbi"}]'::jsonb, null, '{"id": "ar.d.tahta", "word": "تَحْتَ", "translation": "sous, en dessous de", "otherTranslations": ["au-dessous de"], "partOfSpeech": "preposition", "transliteration": "ta7ta", "explanation": "Petit mot de lieu très fréquent. ت au début (deux points dessus), ح au milieu (aucun point), ت final (deux points dessus).", "examples": [{"text": "تَحْتَ الْبَابِ", "translation": "sous la porte", "transliteration": "ta7ta l-bâbi"}, {"text": "تَحْتَ الْكِتَابِ", "translation": "sous le livre", "transliteration": "ta7ta l-kitâbi"}], "unitId": "ar.v.tahta"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.nahnu', 'ar', 'نَحْنُ', 'nous', 'Le pronom « nous ». ن au début (un point dessus), ح au milieu (aucun point), ن final (un point dessus).', '[{"text": "نَحْنُ هُنَا", "translation": "nous sommes ici", "transliteration": "na7nu hunâ"}, {"text": "نَحْنُ فِي الْبَيْتِ", "translation": "nous sommes à la maison", "transliteration": "na7nu fî l-bayti"}]'::jsonb, null, '{"id": "ar.d.nahnu", "word": "نَحْنُ", "translation": "nous", "partOfSpeech": "pronoun", "transliteration": "na7nu", "explanation": "Le pronom « nous ». ن au début (un point dessus), ح au milieu (aucun point), ن final (un point dessus).", "examples": [{"text": "نَحْنُ هُنَا", "translation": "nous sommes ici", "transliteration": "na7nu hunâ"}, {"text": "نَحْنُ فِي الْبَيْتِ", "translation": "nous sommes à la maison", "transliteration": "na7nu fî l-bayti"}], "unitId": "ar.v.nahnu"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.taj', 'ar', 'تَاج', 'la couronne', 'ت au début (deux points dessus), ا qui allonge le a, puis ج isolé : ا ne s''attache pas à la lettre suivante.', '[{"text": "تَاجُ الْمَلِكِ", "translation": "la couronne du roi", "transliteration": "tâdju l-maliki"}, {"text": "تِيجَان", "translation": "des couronnes", "transliteration": "tîdjân"}]'::jsonb, null, '{"id": "ar.d.taj", "word": "تَاج", "translation": "la couronne", "partOfSpeech": "noun", "transliteration": "tâdj", "explanation": "ت au début (deux points dessus), ا qui allonge le a, puis ج isolé : ا ne s''attache pas à la lettre suivante.", "examples": [{"text": "تَاجُ الْمَلِكِ", "translation": "la couronne du roi", "transliteration": "tâdju l-maliki"}, {"text": "تِيجَان", "translation": "des couronnes", "transliteration": "tîdjân"}], "forms": {"plural": "تِيجَان"}, "unitId": "ar.v.taj"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.khatam', 'ar', 'خَاتَم', 'la bague', 'Désigne la bague, et aussi le sceau. خ au début (point dessus), ا qui allonge le a, puis ت (deux points dessus) et م final.', '[{"text": "خَاتَمِي", "translation": "ma bague", "transliteration": "khâtamî"}, {"text": "خَوَاتِم", "translation": "des bagues", "transliteration": "khawâtim"}]'::jsonb, null, '{"id": "ar.d.khatam", "word": "خَاتَم", "translation": "la bague", "otherTranslations": ["le sceau"], "partOfSpeech": "noun", "transliteration": "khâtam", "explanation": "Désigne la bague, et aussi le sceau. خ au début (point dessus), ا qui allonge le a, puis ت (deux points dessus) et م final.", "examples": [{"text": "خَاتَمِي", "translation": "ma bague", "transliteration": "khâtamî"}, {"text": "خَوَاتِم", "translation": "des bagues", "transliteration": "khawâtim"}], "forms": {"plural": "خَوَاتِم"}, "unitId": "ar.v.khatam"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.djazar', 'ar', 'جَزَر', 'les carottes', 'Nom collectif : les carottes en général (une seule carotte se dit جَزَرَة). ج au début (point dans la courbe), puis ز et ر, deux lettres qui ne s''attachent pas à la suivante.', '[{"text": "جَزَرَة", "translation": "une carotte", "transliteration": "djazara"}, {"text": "عَصِيرُ جَزَر", "translation": "du jus de carotte", "transliteration": "3aSîru djazar"}]'::jsonb, null, '{"id": "ar.d.djazar", "word": "جَزَر", "translation": "les carottes", "partOfSpeech": "noun", "transliteration": "djazar", "explanation": "Nom collectif : les carottes en général (une seule carotte se dit جَزَرَة). ج au début (point dans la courbe), puis ز et ر, deux lettres qui ne s''attachent pas à la suivante.", "examples": [{"text": "جَزَرَة", "translation": "une carotte", "transliteration": "djazara"}, {"text": "عَصِيرُ جَزَر", "translation": "du jus de carotte", "transliteration": "3aSîru djazar"}], "forms": {"unité": "جَزَرَة"}, "unitId": "ar.v.djazar"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.dal', 'ar', 'د', 'la lettre dâl, le son d', 'د se prononce d, comme dans « dé ». C''est un petit angle sans aucun point. Comme ا, elle ne s''attache pas à la lettre suivante : elle n''a que deux formes, د (isolée) et ـد (finale).', '[{"text": "دَار", "translation": "la demeure (د isolée, au début)", "transliteration": "dâr"}, {"text": "وَلَد", "translation": "un garçon (ـد attaché à ل)", "transliteration": "walad"}]'::jsonb, null, '{"id": "ar.d.dal", "word": "د", "translation": "la lettre dâl, le son d", "partOfSpeech": "letter", "transliteration": "dâl", "explanation": "د se prononce d, comme dans « dé ». C''est un petit angle sans aucun point. Comme ا, elle ne s''attache pas à la lettre suivante : elle n''a que deux formes, د (isolée) et ـد (finale).", "examples": [{"text": "دَار", "translation": "la demeure (د isolée, au début)", "transliteration": "dâr"}, {"text": "وَلَد", "translation": "un garçon (ـد attaché à ل)", "transliteration": "walad"}], "confusions": [{"word": "ذ", "note": "même forme avec un point au-dessus : dh."}, {"word": "ر", "note": "forme voisine : r, une petite virgule qui descend sous la ligne."}], "forms": {"isolated": "د", "initial": "د", "medial": "ـد", "final": "ـد"}, "unitId": "ar.v.dal"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.dhal', 'ar', 'ذ', 'la lettre dhâl, le son dh de « this »', 'ذ se prononce comme le th anglais de « this », avec la voix (en Égypte, on dit souvent z ou d). C''est د avec un point au-dessus. Comme د, elle ne s''attache pas à la suivante : deux formes seulement, ذ et ـذ.', '[{"text": "ذِرَاع", "translation": "le bras (ذ au début)", "transliteration": "dhirâ3"}, {"text": "لَذِيذ", "translation": "délicieux (ـذ attaché, deux fois)", "transliteration": "ladhîdh"}]'::jsonb, null, '{"id": "ar.d.dhal", "word": "ذ", "translation": "la lettre dhâl, le son dh de « this »", "partOfSpeech": "letter", "transliteration": "dhâl", "explanation": "ذ se prononce comme le th anglais de « this », avec la voix (en Égypte, on dit souvent z ou d). C''est د avec un point au-dessus. Comme د, elle ne s''attache pas à la suivante : deux formes seulement, ذ et ـذ.", "examples": [{"text": "ذِرَاع", "translation": "le bras (ذ au début)", "transliteration": "dhirâ3"}, {"text": "لَذِيذ", "translation": "délicieux (ـذ attaché, deux fois)", "transliteration": "ladhîdh"}], "confusions": [{"word": "د", "note": "même forme sans point : d."}, {"word": "ز", "note": "forme de ر avec un point : z."}, {"word": "ث", "note": "le th « sourd » de « think », trois points sur une dent."}], "forms": {"isolated": "ذ", "initial": "ذ", "medial": "ـذ", "final": "ـذ"}, "unitId": "ar.v.dhal"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ra', 'ar', 'ر', 'la lettre râ'', le son r', 'ر est le r roulé de l''arabe (comme en espagnol ou en italien), un peu plus appuyé que le r français. C''est une petite virgule qui descend sous la ligne, sans point. Elle ne s''attache pas à la suivante : ر et ـر seulement.', '[{"text": "رَجُل", "translation": "un homme (ر au début)", "transliteration": "radjul"}, {"text": "دَار", "translation": "la demeure (ر isolée, après ا)", "transliteration": "dâr"}]'::jsonb, null, '{"id": "ar.d.ra", "word": "ر", "translation": "la lettre râ'', le son r", "partOfSpeech": "letter", "transliteration": "râ''", "explanation": "ر est le r roulé de l''arabe (comme en espagnol ou en italien), un peu plus appuyé que le r français. C''est une petite virgule qui descend sous la ligne, sans point. Elle ne s''attache pas à la suivante : ر et ـر seulement.", "examples": [{"text": "رَجُل", "translation": "un homme (ر au début)", "transliteration": "radjul"}, {"text": "دَار", "translation": "la demeure (ر isolée, après ا)", "transliteration": "dâr"}], "confusions": [{"word": "ز", "note": "même forme avec un point au-dessus : z."}, {"word": "د", "note": "forme voisine, en angle : d."}, {"word": "و", "note": "boucle fermée avec une queue : w."}], "forms": {"isolated": "ر", "initial": "ر", "medial": "ـر", "final": "ـر"}, "unitId": "ar.v.ra"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.zay', 'ar', 'ز', 'la lettre zây, le son z', 'ز se prononce z, comme dans « zèbre ». C''est ر avec un point au-dessus. Elle ne s''attache pas à la lettre suivante : ز et ـز seulement.', '[{"text": "زَيْت", "translation": "l''huile (ز au début)", "transliteration": "zayt"}, {"text": "جَزَر", "translation": "les carottes (ـز attaché à ج)", "transliteration": "djazar"}]'::jsonb, null, '{"id": "ar.d.zay", "word": "ز", "translation": "la lettre zây, le son z", "partOfSpeech": "letter", "transliteration": "zây", "explanation": "ز se prononce z, comme dans « zèbre ». C''est ر avec un point au-dessus. Elle ne s''attache pas à la lettre suivante : ز et ـز seulement.", "examples": [{"text": "زَيْت", "translation": "l''huile (ز au début)", "transliteration": "zayt"}, {"text": "جَزَر", "translation": "les carottes (ـز attaché à ج)", "transliteration": "djazar"}], "confusions": [{"word": "ر", "note": "même forme sans point : r."}, {"word": "ذ", "note": "dh : c''est د avec un point, pas ر."}], "forms": {"isolated": "ز", "initial": "ز", "medial": "ـز", "final": "ـز"}, "unitId": "ar.v.zay"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.waw', 'ar', 'و', 'la lettre wâw, le son w ou û', 'و est le w de « week-end », mais aussi la voyelle longue û (nûr, la lumière) et la moitié de la diphtongue aw (ثَوْب, thawb). C''est une boucle fermée prolongée par une queue qui descend, sans point. Elle ne s''attache pas à la suivante : و et ـو seulement.', '[{"text": "وَرَق", "translation": "du papier, des feuilles (و au début)", "transliteration": "waraq"}, {"text": "ثَوْب", "translation": "le vêtement (ـو attaché à ث)", "transliteration": "thawb"}]'::jsonb, null, '{"id": "ar.d.waw", "word": "و", "translation": "la lettre wâw, le son w ou û", "partOfSpeech": "letter", "transliteration": "wâw", "explanation": "و est le w de « week-end », mais aussi la voyelle longue û (nûr, la lumière) et la moitié de la diphtongue aw (ثَوْب, thawb). C''est une boucle fermée prolongée par une queue qui descend, sans point. Elle ne s''attache pas à la suivante : و et ـو seulement.", "examples": [{"text": "وَرَق", "translation": "du papier, des feuilles (و au début)", "transliteration": "waraq"}, {"text": "ثَوْب", "translation": "le vêtement (ـو attaché à ث)", "transliteration": "thawb"}], "confusions": [{"word": "ر", "note": "sans boucle : r."}, {"word": "ف", "note": "boucle surmontée d''un point, qui s''attache à la suivante : f (leçon 7)."}], "forms": {"isolated": "و", "initial": "و", "medial": "ـو", "final": "ـو"}, "unitId": "ar.v.waw"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.dar', 'ar', 'دَار', 'la demeure, la maison', 'Mot pour « la demeure, la maison », plus soutenu que بَيْت (bayt), le mot courant pour un logement. Trois lettres séparées : د ne s''attache pas à ا, et ا ne s''attache pas à ر.', '[{"text": "دَارِي", "translation": "ma demeure", "transliteration": "dârî"}, {"text": "دُور", "translation": "des maisons", "transliteration": "dûr"}]'::jsonb, null, '{"id": "ar.d.dar", "word": "دَار", "translation": "la demeure, la maison", "otherTranslations": ["le foyer"], "partOfSpeech": "noun", "transliteration": "dâr", "explanation": "Mot pour « la demeure, la maison », plus soutenu que بَيْت (bayt), le mot courant pour un logement. Trois lettres séparées : د ne s''attache pas à ا, et ا ne s''attache pas à ر.", "examples": [{"text": "دَارِي", "translation": "ma demeure", "transliteration": "dârî"}, {"text": "دُور", "translation": "des maisons", "transliteration": "dûr"}], "confusions": [{"word": "بَيْت", "note": "bayt : la maison, le mot courant pour un logement."}], "forms": {"plural": "دُور"}, "unitId": "ar.v.dar"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.zayt', 'ar', 'زَيْت', 'l''huile', 'Désigne l''huile. Deux blocs : ز seul (il ne s''attache pas à la suite), puis يت, où ي repart en forme de début.', '[{"text": "زَيْتُون", "translation": "des olives", "transliteration": "zaytûn"}, {"text": "زَيْتُونَة", "translation": "une olive", "transliteration": "zaytûna"}]'::jsonb, null, '{"id": "ar.d.zayt", "word": "زَيْت", "translation": "l''huile", "partOfSpeech": "noun", "transliteration": "zayt", "explanation": "Désigne l''huile. Deux blocs : ز seul (il ne s''attache pas à la suite), puis يت, où ي repart en forme de début.", "examples": [{"text": "زَيْتُون", "translation": "des olives", "transliteration": "zaytûn"}, {"text": "زَيْتُونَة", "translation": "une olive", "transliteration": "zaytûna"}], "unitId": "ar.v.zayt"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.dadjadj', 'ar', 'دَجَاج', 'le poulet', 'Nom collectif : le poulet, la volaille. Trois blocs : د seul, puis جا (ج en forme de début, attaché à ا), puis ج isolé après ا.', '[{"text": "دَجَاجَة", "translation": "une poule, un poulet", "transliteration": "dadjâdja"}, {"text": "أَرُزّ وَدَجَاج", "translation": "du riz et du poulet", "transliteration": "aruzz wa-dadjâdj"}]'::jsonb, null, '{"id": "ar.d.dadjadj", "word": "دَجَاج", "translation": "le poulet", "partOfSpeech": "noun", "transliteration": "dadjâdj", "explanation": "Nom collectif : le poulet, la volaille. Trois blocs : د seul, puis جا (ج en forme de début, attaché à ا), puis ج isolé après ا.", "examples": [{"text": "دَجَاجَة", "translation": "une poule, un poulet", "transliteration": "dadjâdja"}, {"text": "أَرُزّ وَدَجَاج", "translation": "du riz et du poulet", "transliteration": "aruzz wa-dadjâdj"}], "forms": {"unité": "دَجَاجَة"}, "unitId": "ar.v.dadjadj"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ladhidh', 'ar', 'لَذِيذ', 'délicieux', 'Adjectif très courant pour parler de nourriture : « bon, savoureux ». Deux blocs : لذ (ل attaché à ذ) puis يذ (ي repart en forme de début, attaché à ذ).', '[{"text": "طَعَام لَذِيذ", "translation": "un repas délicieux", "transliteration": "Ta3âm ladhîdh"}, {"text": "خُبْز لَذِيذ", "translation": "du pain délicieux", "transliteration": "khubz ladhîdh"}]'::jsonb, null, '{"id": "ar.d.ladhidh", "word": "لَذِيذ", "translation": "délicieux", "otherTranslations": ["savoureux"], "partOfSpeech": "adjective", "transliteration": "ladhîdh", "explanation": "Adjectif très courant pour parler de nourriture : « bon, savoureux ». Deux blocs : لذ (ل attaché à ذ) puis يذ (ي repart en forme de début, attaché à ذ).", "examples": [{"text": "طَعَام لَذِيذ", "translation": "un repas délicieux", "transliteration": "Ta3âm ladhîdh"}, {"text": "خُبْز لَذِيذ", "translation": "du pain délicieux", "transliteration": "khubz ladhîdh"}], "forms": {"féminin": "لَذِيذَة"}, "unitId": "ar.v.ladhidh"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sin', 'ar', 'س', 'la lettre sîn, le son s', 'س se prononce s, comme dans « sac » (toujours dur, jamais z). Au début et au milieu, ce sont trois petites dents en scie ; isolée ou à la fin, une grande courbe avec une queue. Aucun point.', '[{"text": "سَرِير", "translation": "le lit (س au début)", "transliteration": "sarîr"}, {"text": "مَسَاء", "translation": "le soir (س au milieu)", "transliteration": "masâ''"}]'::jsonb, null, '{"id": "ar.d.sin", "word": "س", "translation": "la lettre sîn, le son s", "partOfSpeech": "letter", "transliteration": "sîn", "explanation": "س se prononce s, comme dans « sac » (toujours dur, jamais z). Au début et au milieu, ce sont trois petites dents en scie ; isolée ou à la fin, une grande courbe avec une queue. Aucun point.", "examples": [{"text": "سَرِير", "translation": "le lit (س au début)", "transliteration": "sarîr"}, {"text": "مَسَاء", "translation": "le soir (س au milieu)", "transliteration": "masâ''"}], "confusions": [{"word": "ش", "note": "même scie, mais avec trois points au-dessus : ch."}, {"word": "ص", "note": "le s « lourd » : boucle ronde au lieu d''une scie."}], "forms": {"isolated": "س", "initial": "سـ", "medial": "ـسـ", "final": "ـس"}, "unitId": "ar.v.sin"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.chin', 'ar', 'ش', 'la lettre chîn, le son ch', 'ش se prononce ch, comme dans « chat ». C''est س avec trois points au-dessus. Les trois points sont posés sur trois petites dents.', '[{"text": "شَوْكَة", "translation": "la fourchette (ش au début)", "transliteration": "chawka"}, {"text": "عَشَاء", "translation": "le dîner (ش au milieu)", "transliteration": "3achâ''"}]'::jsonb, null, '{"id": "ar.d.chin", "word": "ش", "translation": "la lettre chîn, le son ch", "partOfSpeech": "letter", "transliteration": "chîn", "explanation": "ش se prononce ch, comme dans « chat ». C''est س avec trois points au-dessus. Les trois points sont posés sur trois petites dents.", "examples": [{"text": "شَوْكَة", "translation": "la fourchette (ش au début)", "transliteration": "chawka"}, {"text": "عَشَاء", "translation": "le dîner (ش au milieu)", "transliteration": "3achâ''"}], "confusions": [{"word": "س", "note": "même scie sans point : s."}, {"word": "ث", "note": "trois points aussi, mais sur une seule dent : th."}], "forms": {"isolated": "ش", "initial": "شـ", "medial": "ـشـ", "final": "ـش"}, "unitId": "ar.v.chin"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sad', 'ar', 'ص', 'la lettre Sâd, le s « lourd »', 'ص est un s « lourd » (emphatique) : la langue est plaquée contre le palais et la voyelle voisine devient plus grave. On le note S majuscule. Au début et au milieu, c''est une boucle ronde ; à la fin ou isolée, la boucle se prolonge par une queue. Aucun point.', '[{"text": "صَحْن", "translation": "l''assiette (ص au début)", "transliteration": "Sa7n"}, {"text": "قَمِيص", "translation": "la chemise (ـص à la fin, attaché)", "transliteration": "qamîS"}]'::jsonb, null, '{"id": "ar.d.sad", "word": "ص", "translation": "la lettre Sâd, le s « lourd »", "partOfSpeech": "letter", "transliteration": "Sâd", "explanation": "ص est un s « lourd » (emphatique) : la langue est plaquée contre le palais et la voyelle voisine devient plus grave. On le note S majuscule. Au début et au milieu, c''est une boucle ronde ; à la fin ou isolée, la boucle se prolonge par une queue. Aucun point.", "examples": [{"text": "صَحْن", "translation": "l''assiette (ص au début)", "transliteration": "Sa7n"}, {"text": "قَمِيص", "translation": "la chemise (ـص à la fin, attaché)", "transliteration": "qamîS"}], "confusions": [{"word": "ض", "note": "même boucle avec un point au-dessus : D."}, {"word": "س", "note": "le s léger : trois dents en scie."}], "forms": {"isolated": "ص", "initial": "صـ", "medial": "ـصـ", "final": "ـص"}, "unitId": "ar.v.sad"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.dad', 'ar', 'ض', 'la lettre Dâd, le d « lourd »', 'ض est un d « lourd » (emphatique), plus profond que د. On le note D majuscule. C''est ص avec un point au-dessus. C''est une lettre si caractéristique que l''arabe est appelé « la langue du ض » (لُغَة الضَّاد).', '[{"text": "ضَيْف", "translation": "l''invité (ض au début)", "transliteration": "Dayf"}, {"text": "مَرِيض", "translation": "malade (ـض à la fin, attaché)", "transliteration": "marîD"}]'::jsonb, null, '{"id": "ar.d.dad", "word": "ض", "translation": "la lettre Dâd, le d « lourd »", "partOfSpeech": "letter", "transliteration": "Dâd", "explanation": "ض est un d « lourd » (emphatique), plus profond que د. On le note D majuscule. C''est ص avec un point au-dessus. C''est une lettre si caractéristique que l''arabe est appelé « la langue du ض » (لُغَة الضَّاد).", "examples": [{"text": "ضَيْف", "translation": "l''invité (ض au début)", "transliteration": "Dayf"}, {"text": "مَرِيض", "translation": "malade (ـض à la fin, attaché)", "transliteration": "marîD"}], "confusions": [{"word": "ص", "note": "même boucle sans point : S."}, {"word": "د", "note": "le d léger : un petit angle qui ne s''attache pas à la suite."}], "forms": {"isolated": "ض", "initial": "ضـ", "medial": "ـضـ", "final": "ـض"}, "unitId": "ar.v.dad"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sarir', 'ar', 'سَرِير', 'le lit', 'Le meuble où l''on dort. Deux blocs : س attaché à ر (qui coupe), puis ي attaché au dernier ر.', '[{"text": "سَرِيرِي", "translation": "mon lit", "transliteration": "sarîrî"}, {"text": "أَسِرَّة", "translation": "des lits", "transliteration": "asirra"}]'::jsonb, null, '{"id": "ar.d.sarir", "word": "سَرِير", "translation": "le lit", "partOfSpeech": "noun", "transliteration": "sarîr", "explanation": "Le meuble où l''on dort. Deux blocs : س attaché à ر (qui coupe), puis ي attaché au dernier ر.", "examples": [{"text": "سَرِيرِي", "translation": "mon lit", "transliteration": "sarîrî"}, {"text": "أَسِرَّة", "translation": "des lits", "transliteration": "asirra"}], "forms": {"plural": "أَسِرَّة"}, "unitId": "ar.v.sarir"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.chawka', 'ar', 'شَوْكَة', 'la fourchette', 'Désigne la fourchette de table, et aussi l''épine d''une plante. ش (scie, trois points) attaché à و, puis ك et ة dans un second bloc.', '[{"text": "شَوْكَتِي", "translation": "ma fourchette", "transliteration": "chawkatî"}, {"text": "شَوْكَة وَسِكِّين", "translation": "une fourchette et un couteau", "transliteration": "chawka wa-sikkîn"}]'::jsonb, null, '{"id": "ar.d.chawka", "word": "شَوْكَة", "translation": "la fourchette", "otherTranslations": ["l''épine"], "partOfSpeech": "noun", "transliteration": "chawka", "explanation": "Désigne la fourchette de table, et aussi l''épine d''une plante. ش (scie, trois points) attaché à و, puis ك et ة dans un second bloc.", "examples": [{"text": "شَوْكَتِي", "translation": "ma fourchette", "transliteration": "chawkatî"}, {"text": "شَوْكَة وَسِكِّين", "translation": "une fourchette et un couteau", "transliteration": "chawka wa-sikkîn"}], "unitId": "ar.v.chawka"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sahn', 'ar', 'صَحْن', 'l''assiette', 'Une assiette ou un plat creux. Un seul bloc : ص (boucle) attaché à ح (aucun point) puis à ن (un point dessus).', '[{"text": "صَحْنِي", "translation": "mon assiette", "transliteration": "Sa7nî"}, {"text": "صُحُون", "translation": "des assiettes", "transliteration": "Su7ûn"}]'::jsonb, null, '{"id": "ar.d.sahn", "word": "صَحْن", "translation": "l''assiette", "partOfSpeech": "noun", "transliteration": "Sa7n", "explanation": "Une assiette ou un plat creux. Un seul bloc : ص (boucle) attaché à ح (aucun point) puis à ن (un point dessus).", "examples": [{"text": "صَحْنِي", "translation": "mon assiette", "transliteration": "Sa7nî"}, {"text": "صُحُون", "translation": "des assiettes", "transliteration": "Su7ûn"}], "forms": {"plural": "صُحُون"}, "unitId": "ar.v.sahn"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.misbah', 'ar', 'مِصْبَاح', 'la lampe', 'La lampe, l''ampoule ou le luminaire. م attaché à ص (forme du milieu) puis à ب, avec ا et ح isolé à la fin.', '[{"text": "مِصْبَاحِي", "translation": "ma lampe", "transliteration": "miSbâ7î"}, {"text": "مَصَابِيح", "translation": "des lampes", "transliteration": "maSâbî7"}]'::jsonb, null, '{"id": "ar.d.misbah", "word": "مِصْبَاح", "translation": "la lampe", "otherTranslations": ["l''ampoule"], "partOfSpeech": "noun", "transliteration": "miSbâ7", "explanation": "La lampe, l''ampoule ou le luminaire. م attaché à ص (forme du milieu) puis à ب, avec ا et ح isolé à la fin.", "examples": [{"text": "مِصْبَاحِي", "translation": "ma lampe", "transliteration": "miSbâ7î"}, {"text": "مَصَابِيح", "translation": "des lampes", "transliteration": "maSâbî7"}], "forms": {"plural": "مَصَابِيح"}, "unitId": "ar.v.misbah"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.dayf', 'ar', 'ضَيْف', 'l''invité', 'La personne que l''on reçoit chez soi. Un seul bloc : ض (boucle, un point dessus), ي (deux points dessous), ف.', '[{"text": "ضَيْفِي", "translation": "mon invité", "transliteration": "Dayfî"}, {"text": "ضُيُوف", "translation": "des invités", "transliteration": "Duyûf"}]'::jsonb, null, '{"id": "ar.d.dayf", "word": "ضَيْف", "translation": "l''invité", "otherTranslations": ["l''hôte (celui qu''on reçoit)"], "partOfSpeech": "noun", "transliteration": "Dayf", "explanation": "La personne que l''on reçoit chez soi. Un seul bloc : ض (boucle, un point dessus), ي (deux points dessous), ف.", "examples": [{"text": "ضَيْفِي", "translation": "mon invité", "transliteration": "Dayfî"}, {"text": "ضُيُوف", "translation": "des invités", "transliteration": "Duyûf"}], "confusions": [{"word": "صَيْف", "note": "Sayf : l''été. Même forme, mais sans le point sur la boucle."}], "forms": {"plural": "ضُيُوف"}, "unitId": "ar.v.dayf"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.qamis', 'ar', 'قَمِيص', 'la chemise', 'Un vêtement du haut. Un seul bloc : ق, م, ي puis ص final, dont la boucle est suivie d''une queue.', '[{"text": "قَمِيصِي", "translation": "ma chemise", "transliteration": "qamîSî"}, {"text": "قُمْصَان", "translation": "des chemises", "transliteration": "qumSân"}]'::jsonb, null, '{"id": "ar.d.qamis", "word": "قَمِيص", "translation": "la chemise", "partOfSpeech": "noun", "transliteration": "qamîS", "explanation": "Un vêtement du haut. Un seul bloc : ق, م, ي puis ص final, dont la boucle est suivie d''une queue.", "examples": [{"text": "قَمِيصِي", "translation": "ma chemise", "transliteration": "qamîSî"}, {"text": "قُمْصَان", "translation": "des chemises", "transliteration": "qumSân"}], "forms": {"plural": "قُمْصَان"}, "unitId": "ar.v.qamis"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.tah', 'ar', 'ط', 'la lettre Tâ'', le t « lourd »', 'ط est un t « lourd » (emphatique) : la langue est plaquée contre le palais et la voyelle voisine devient plus grave. On le note T majuscule. C''est une boucle fermée surmontée d''un bâton vertical, sans point.', '[{"text": "طَعَام", "translation": "la nourriture (ط au début)", "transliteration": "Ta3âm"}, {"text": "بَسِيط", "translation": "simple (ـط à la fin, attaché)", "transliteration": "basîT"}]'::jsonb, null, '{"id": "ar.d.tah", "word": "ط", "translation": "la lettre Tâ'', le t « lourd »", "partOfSpeech": "letter", "transliteration": "Tâ''", "explanation": "ط est un t « lourd » (emphatique) : la langue est plaquée contre le palais et la voyelle voisine devient plus grave. On le note T majuscule. C''est une boucle fermée surmontée d''un bâton vertical, sans point.", "examples": [{"text": "طَعَام", "translation": "la nourriture (ط au début)", "transliteration": "Ta3âm"}, {"text": "بَسِيط", "translation": "simple (ـط à la fin, attaché)", "transliteration": "basîT"}], "confusions": [{"word": "ظ", "note": "même forme avec un point au-dessus : Z."}, {"word": "ت", "note": "le t léger : une dent à deux points, sans bâton."}, {"word": "ص", "note": "une boucle sans bâton : S."}], "forms": {"isolated": "ط", "initial": "طـ", "medial": "ـطـ", "final": "ـط"}, "unitId": "ar.v.tah"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.zah', 'ar', 'ظ', 'la lettre Zâ'', le dh « lourd »', 'ظ est un dh « lourd » (emphatique), voisin de ذ mais plus profond ; en Égypte on entend plutôt un z lourd. On le note Z majuscule. C''est ط avec un point au-dessus.', '[{"text": "نَظِيف", "translation": "propre (ظ au milieu)", "transliteration": "naZîf"}, {"text": "ظَهْر", "translation": "le dos (ظ au début)", "transliteration": "Zahr"}]'::jsonb, null, '{"id": "ar.d.zah", "word": "ظ", "translation": "la lettre Zâ'', le dh « lourd »", "partOfSpeech": "letter", "transliteration": "Zâ''", "explanation": "ظ est un dh « lourd » (emphatique), voisin de ذ mais plus profond ; en Égypte on entend plutôt un z lourd. On le note Z majuscule. C''est ط avec un point au-dessus.", "examples": [{"text": "نَظِيف", "translation": "propre (ظ au milieu)", "transliteration": "naZîf"}, {"text": "ظَهْر", "translation": "le dos (ظ au début)", "transliteration": "Zahr"}], "confusions": [{"word": "ط", "note": "même forme sans point : T."}, {"word": "ض", "note": "une boucle sans bâton, avec un point : D."}, {"word": "ذ", "note": "le dh léger : un petit angle avec un point."}], "forms": {"isolated": "ظ", "initial": "ظـ", "medial": "ـظـ", "final": "ـظ"}, "unitId": "ar.v.zah"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ayn', 'ar', 'ع', 'la lettre 3ayn, un son guttural propre à l''arabe', 'ع n''existe pas en français : c''est un son créé en serrant la gorge, comme un « a » poussé du fond du larynx. On le note 3. Au début et au milieu, c''est une petite tête triangulaire ; à la fin ou isolée, une tête avec une queue. Aucun point.', '[{"text": "عَسَل", "translation": "le miel (ع au début)", "transliteration": "3asal"}, {"text": "سَرِيع", "translation": "rapide (ـع à la fin, attaché)", "transliteration": "sarî3"}]'::jsonb, null, '{"id": "ar.d.ayn", "word": "ع", "translation": "la lettre 3ayn, un son guttural propre à l''arabe", "partOfSpeech": "letter", "transliteration": "3ayn", "explanation": "ع n''existe pas en français : c''est un son créé en serrant la gorge, comme un « a » poussé du fond du larynx. On le note 3. Au début et au milieu, c''est une petite tête triangulaire ; à la fin ou isolée, une tête avec une queue. Aucun point.", "examples": [{"text": "عَسَل", "translation": "le miel (ع au début)", "transliteration": "3asal"}, {"text": "سَرِيع", "translation": "rapide (ـع à la fin, attaché)", "transliteration": "sarî3"}], "confusions": [{"word": "غ", "note": "même tête avec un point au-dessus : gh."}, {"word": "ح", "note": "un crochet sans point : 7, un h soufflé, bien moins profond que 3."}], "forms": {"isolated": "ع", "initial": "عـ", "medial": "ـعـ", "final": "ـع"}, "unitId": "ar.v.ayn"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ghayn', 'ar', 'غ', 'la lettre ghayn, le son gh', 'غ se prononce au fond de la gorge, comme le r grasseyé français de « rue ». C''est ع avec un point au-dessus.', '[{"text": "غُرْفَة", "translation": "la chambre (غ au début)", "transliteration": "ghurfa"}, {"text": "صَغِير", "translation": "petit (غ au milieu)", "transliteration": "Saghîr"}]'::jsonb, null, '{"id": "ar.d.ghayn", "word": "غ", "translation": "la lettre ghayn, le son gh", "partOfSpeech": "letter", "transliteration": "ghayn", "explanation": "غ se prononce au fond de la gorge, comme le r grasseyé français de « rue ». C''est ع avec un point au-dessus.", "examples": [{"text": "غُرْفَة", "translation": "la chambre (غ au début)", "transliteration": "ghurfa"}, {"text": "صَغِير", "translation": "petit (غ au milieu)", "transliteration": "Saghîr"}], "confusions": [{"word": "ع", "note": "même tête sans point : 3."}, {"word": "خ", "note": "kh : un crochet avec un point au-dessus, plus rauque que gh."}], "forms": {"isolated": "غ", "initial": "غـ", "medial": "ـغـ", "final": "ـغ"}, "unitId": "ar.v.ghayn"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.taam', 'ar', 'طَعَام', 'la nourriture, le repas', 'Mot très courant pour la nourriture en général, ou un repas. ط et ع s''attachent à ا ; م reste isolé car ا ne s''attache pas à la lettre suivante.', '[{"text": "طَعَام لَذِيذ", "translation": "un repas délicieux", "transliteration": "Ta3âm ladhîdh"}, {"text": "أَطْعِمَة", "translation": "des aliments", "transliteration": "aT3ima"}]'::jsonb, null, '{"id": "ar.d.taam", "word": "طَعَام", "translation": "la nourriture, le repas", "otherTranslations": ["le plat"], "partOfSpeech": "noun", "transliteration": "Ta3âm", "explanation": "Mot très courant pour la nourriture en général, ou un repas. ط et ع s''attachent à ا ; م reste isolé car ا ne s''attache pas à la lettre suivante.", "examples": [{"text": "طَعَام لَذِيذ", "translation": "un repas délicieux", "transliteration": "Ta3âm ladhîdh"}, {"text": "أَطْعِمَة", "translation": "des aliments", "transliteration": "aT3ima"}], "forms": {"plural": "أَطْعِمَة"}, "unitId": "ar.v.taam"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.tawila', 'ar', 'طَاوِلَة', 'la table', 'La table, le meuble. Trois blocs : طا (ط attaché à ا), و seul (il coupe le mot), puis لة (ل attaché à ة).', '[{"text": "طَاوِلَتِي", "translation": "ma table", "transliteration": "Tâwilatî"}, {"text": "طَاوِلَات", "translation": "des tables", "transliteration": "Tâwilât"}]'::jsonb, null, '{"id": "ar.d.tawila", "word": "طَاوِلَة", "translation": "la table", "partOfSpeech": "noun", "transliteration": "Tâwila", "explanation": "La table, le meuble. Trois blocs : طا (ط attaché à ا), و seul (il coupe le mot), puis لة (ل attaché à ة).", "examples": [{"text": "طَاوِلَتِي", "translation": "ma table", "transliteration": "Tâwilatî"}, {"text": "طَاوِلَات", "translation": "des tables", "transliteration": "Tâwilât"}], "forms": {"plural": "طَاوِلَات"}, "unitId": "ar.v.tawila"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.asal', 'ar', 'عَسَل', 'le miel', 'Le miel. ع (tête sans point) au début, attaché à س (scie sans point) puis à ل.', '[{"text": "عَسَلِي", "translation": "mon miel", "transliteration": "3asalî"}, {"text": "خُبْز وَعَسَل", "translation": "du pain et du miel", "transliteration": "khubz wa-3asal"}]'::jsonb, null, '{"id": "ar.d.asal", "word": "عَسَل", "translation": "le miel", "partOfSpeech": "noun", "transliteration": "3asal", "explanation": "Le miel. ع (tête sans point) au début, attaché à س (scie sans point) puis à ل.", "examples": [{"text": "عَسَلِي", "translation": "mon miel", "transliteration": "3asalî"}, {"text": "خُبْز وَعَسَل", "translation": "du pain et du miel", "transliteration": "khubz wa-3asal"}], "unitId": "ar.v.asal"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.asir', 'ar', 'عَصِير', 'le jus', 'Un jus de fruit. ع au début, ص au milieu (boucle sans point), ي puis ر final.', '[{"text": "عَصِيرُ جَزَر", "translation": "du jus de carotte", "transliteration": "3aSîru djazar"}, {"text": "عَصَائِر", "translation": "des jus", "transliteration": "3aSâ''ir"}]'::jsonb, null, '{"id": "ar.d.asir", "word": "عَصِير", "translation": "le jus", "partOfSpeech": "noun", "transliteration": "3aSîr", "explanation": "Un jus de fruit. ع au début, ص au milieu (boucle sans point), ي puis ر final.", "examples": [{"text": "عَصِيرُ جَزَر", "translation": "du jus de carotte", "transliteration": "3aSîru djazar"}, {"text": "عَصَائِر", "translation": "des jus", "transliteration": "3aSâ''ir"}], "forms": {"plural": "عَصَائِر"}, "unitId": "ar.v.asir"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ghurfa', 'ar', 'غُرْفَة', 'la chambre, la pièce', 'Une pièce de la maison, en particulier la chambre. غ au début (tête avec un point), attaché à ر qui coupe le mot ; puis فة dans un second bloc.', '[{"text": "غُرْفَتِي", "translation": "ma chambre", "transliteration": "ghurfatî"}, {"text": "غُرَف", "translation": "des chambres", "transliteration": "ghuraf"}]'::jsonb, null, '{"id": "ar.d.ghurfa", "word": "غُرْفَة", "translation": "la chambre, la pièce", "otherTranslations": ["la pièce"], "partOfSpeech": "noun", "transliteration": "ghurfa", "explanation": "Une pièce de la maison, en particulier la chambre. غ au début (tête avec un point), attaché à ر qui coupe le mot ; puis فة dans un second bloc.", "examples": [{"text": "غُرْفَتِي", "translation": "ma chambre", "transliteration": "ghurfatî"}, {"text": "غُرَف", "translation": "des chambres", "transliteration": "ghuraf"}], "forms": {"plural": "غُرَف"}, "unitId": "ar.v.ghurfa"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.nazif', 'ar', 'نَظِيف', 'propre', 'Adjectif qui s''emploie pour un lieu, un vêtement, une personne. ن au début, ظ au milieu (boucle, bâton, point dessus), ي puis ف.', '[{"text": "بَيْت نَظِيف", "translation": "une maison propre", "transliteration": "bayt naZîf"}, {"text": "قَمِيص نَظِيف", "translation": "une chemise propre", "transliteration": "qamîS naZîf"}]'::jsonb, null, '{"id": "ar.d.nazif", "word": "نَظِيف", "translation": "propre", "partOfSpeech": "adjective", "transliteration": "naZîf", "explanation": "Adjectif qui s''emploie pour un lieu, un vêtement, une personne. ن au début, ظ au milieu (boucle, bâton, point dessus), ي puis ف.", "examples": [{"text": "بَيْت نَظِيف", "translation": "une maison propre", "transliteration": "bayt naZîf"}, {"text": "قَمِيص نَظِيف", "translation": "une chemise propre", "transliteration": "qamîS naZîf"}], "forms": {"féminin": "نَظِيفَة"}, "unitId": "ar.v.nazif"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.fa', 'ar', 'ف', 'la lettre fâ'', le son f', 'ف se prononce f, comme dans « feu ». Au début et au milieu, c''est une petite tête ronde ; à la fin ou isolée, la tête est suivie d''une courte queue. Son signe distinctif : un seul point, au-dessus.', '[{"text": "مِفْتَاح", "translation": "la clé (ف au milieu)", "transliteration": "miftâ7"}, {"text": "هَاتِف", "translation": "le téléphone (ف à la fin, attaché)", "transliteration": "hâtif"}]'::jsonb, null, '{"id": "ar.d.fa", "word": "ف", "translation": "la lettre fâ'', le son f", "partOfSpeech": "letter", "transliteration": "fâ''", "explanation": "ف se prononce f, comme dans « feu ». Au début et au milieu, c''est une petite tête ronde ; à la fin ou isolée, la tête est suivie d''une courte queue. Son signe distinctif : un seul point, au-dessus.", "examples": [{"text": "مِفْتَاح", "translation": "la clé (ف au milieu)", "transliteration": "miftâ7"}, {"text": "هَاتِف", "translation": "le téléphone (ف à la fin, attaché)", "transliteration": "hâtif"}], "confusions": [{"word": "ق", "note": "même tête avec deux points : q."}, {"word": "و", "note": "boucle sans point, qui ne s''attache pas à la suite : w."}], "forms": {"isolated": "ف", "initial": "فـ", "medial": "ـفـ", "final": "ـف"}, "unitId": "ar.v.fa"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.qaf', 'ar', 'ق', 'la lettre qâf, un k du fond de la gorge', 'ق est un k prononcé tout au fond de la gorge ; on le note q. En Égypte, on l''entend souvent comme une petite coupure de gorge (comme une hamza). Même tête que ف, mais avec deux points au-dessus ; à la fin ou isolée, la queue plonge sous la ligne.', '[{"text": "قَلَم", "translation": "le stylo (ق au début)", "transliteration": "qalam"}, {"text": "بَقَرَة", "translation": "la vache (ق au milieu)", "transliteration": "baqara"}]'::jsonb, null, '{"id": "ar.d.qaf", "word": "ق", "translation": "la lettre qâf, un k du fond de la gorge", "partOfSpeech": "letter", "transliteration": "qâf", "explanation": "ق est un k prononcé tout au fond de la gorge ; on le note q. En Égypte, on l''entend souvent comme une petite coupure de gorge (comme une hamza). Même tête que ف, mais avec deux points au-dessus ; à la fin ou isolée, la queue plonge sous la ligne.", "examples": [{"text": "قَلَم", "translation": "le stylo (ق au début)", "transliteration": "qalam"}, {"text": "بَقَرَة", "translation": "la vache (ق au milieu)", "transliteration": "baqara"}], "confusions": [{"word": "ف", "note": "même tête avec un seul point : f."}, {"word": "ك", "note": "le k léger : un zigzag dans un trait haut."}], "forms": {"isolated": "ق", "initial": "قـ", "medial": "ـقـ", "final": "ـق"}, "unitId": "ar.v.qaf"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kaf', 'ar', 'ك', 'la lettre kâf, le son k', 'ك se prononce k, comme dans « kilo ». On la reconnaît à son petit zigzag à l''intérieur d''un trait haut. Ne la confonds pas avec ل, qui est un trait vertical tout simple.', '[{"text": "كُوب", "translation": "le verre (ك au début)", "transliteration": "kûb"}, {"text": "سَمَك", "translation": "le poisson (ك à la fin, attaché)", "transliteration": "samak"}]'::jsonb, null, '{"id": "ar.d.kaf", "word": "ك", "translation": "la lettre kâf, le son k", "partOfSpeech": "letter", "transliteration": "kâf", "explanation": "ك se prononce k, comme dans « kilo ». On la reconnaît à son petit zigzag à l''intérieur d''un trait haut. Ne la confonds pas avec ل, qui est un trait vertical tout simple.", "examples": [{"text": "كُوب", "translation": "le verre (ك au début)", "transliteration": "kûb"}, {"text": "سَمَك", "translation": "le poisson (ك à la fin, attaché)", "transliteration": "samak"}], "confusions": [{"word": "ل", "note": "trait vertical simple, sans zigzag : l."}, {"word": "ق", "note": "le k du fond de la gorge : une tête ronde à deux points."}], "forms": {"isolated": "ك", "initial": "كـ", "medial": "ـكـ", "final": "ـك"}, "unitId": "ar.v.kaf"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.lam', 'ar', 'ل', 'la lettre lâm, le son l', 'ل se prononce l, comme dans « lac ». C''est un grand trait vertical, qui s''attache à la lettre suivante : c''est ce qui le distingue de ا. À la fin ou isolé, le trait se termine par une base arrondie.', '[{"text": "قَلَم", "translation": "le stylo (ل au milieu)", "transliteration": "qalam"}, {"text": "عَسَل", "translation": "le miel (ل à la fin, attaché)", "transliteration": "3asal"}]'::jsonb, null, '{"id": "ar.d.lam", "word": "ل", "translation": "la lettre lâm, le son l", "partOfSpeech": "letter", "transliteration": "lâm", "explanation": "ل se prononce l, comme dans « lac ». C''est un grand trait vertical, qui s''attache à la lettre suivante : c''est ce qui le distingue de ا. À la fin ou isolé, le trait se termine par une base arrondie.", "examples": [{"text": "قَلَم", "translation": "le stylo (ل au milieu)", "transliteration": "qalam"}, {"text": "عَسَل", "translation": "le miel (ل à la fin, attaché)", "transliteration": "3asal"}], "confusions": [{"word": "ا", "note": "alif, trait vertical aussi, mais qui ne s''attache jamais à la lettre suivante."}, {"word": "ك", "note": "avec un zigzag à l''intérieur : k."}], "forms": {"isolated": "ل", "initial": "لـ", "medial": "ـلـ", "final": "ـل"}, "unitId": "ar.v.lam"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.mim', 'ar', 'م', 'la lettre mîm, le son m', 'م se prononce m, comme dans « maman ». Au début, c''est une petite boule ; au milieu, une petite bosse sur la ligne ; à la fin ou isolée, la boule se prolonge par une queue qui descend. Aucun point.', '[{"text": "مِفْتَاح", "translation": "la clé (م au début)", "transliteration": "miftâ7"}, {"text": "قَلَم", "translation": "le stylo (م à la fin, attaché)", "transliteration": "qalam"}]'::jsonb, null, '{"id": "ar.d.mim", "word": "م", "translation": "la lettre mîm, le son m", "partOfSpeech": "letter", "transliteration": "mîm", "explanation": "م se prononce m, comme dans « maman ». Au début, c''est une petite boule ; au milieu, une petite bosse sur la ligne ; à la fin ou isolée, la boule se prolonge par une queue qui descend. Aucun point.", "examples": [{"text": "مِفْتَاح", "translation": "la clé (م au début)", "transliteration": "miftâ7"}, {"text": "قَلَم", "translation": "le stylo (م à la fin, attaché)", "transliteration": "qalam"}], "confusions": [{"word": "و", "note": "boucle avec une queue, qui ne s''attache pas à la suite : w."}, {"word": "ف", "note": "tête ronde avec un point au-dessus : f."}], "forms": {"isolated": "م", "initial": "مـ", "medial": "ـمـ", "final": "ـم"}, "unitId": "ar.v.mim"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ha', 'ar', 'ه', 'la lettre hâ'', un h léger', 'ه se prononce h, un simple souffle comme dans l''anglais « hello » (ne le confonds pas avec le ح, beaucoup plus rauque). C''est la lettre qui change le plus de forme : ه isolée, هـ au début, ـهـ au milieu, ـه à la fin. Aucun point.', '[{"text": "هَاتِف", "translation": "le téléphone (هـ au début)", "transliteration": "hâtif"}, {"text": "وَجْه", "translation": "le visage (ـه à la fin, attaché)", "transliteration": "wadjh"}]'::jsonb, null, '{"id": "ar.d.ha", "word": "ه", "translation": "la lettre hâ'', un h léger", "partOfSpeech": "letter", "transliteration": "hâ''", "explanation": "ه se prononce h, un simple souffle comme dans l''anglais « hello » (ne le confonds pas avec le ح, beaucoup plus rauque). C''est la lettre qui change le plus de forme : ه isolée, هـ au début, ـهـ au milieu, ـه à la fin. Aucun point.", "examples": [{"text": "هَاتِف", "translation": "le téléphone (هـ au début)", "transliteration": "hâtif"}, {"text": "وَجْه", "translation": "le visage (ـه à la fin, attaché)", "transliteration": "wadjh"}], "confusions": [{"word": "ح", "note": "le h rauque (7), un crochet sans point."}, {"word": "ة", "note": "tâ'' marbûTa : même allure que ـه à la fin d''un mot, mais avec deux points (leçon 8)."}], "forms": {"isolated": "ه", "initial": "هـ", "medial": "ـهـ", "final": "ـه"}, "unitId": "ar.v.ha"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.qalam', 'ar', 'قَلَم', 'le stylo', 'Le stylo, le crayon : l''objet avec lequel on écrit. ق (deux points) au début, ل au milieu (trait simple), م final.', '[{"text": "قَلَمِي", "translation": "mon stylo", "transliteration": "qalamî"}, {"text": "أَقْلَام", "translation": "des stylos", "transliteration": "aqlâm"}]'::jsonb, null, '{"id": "ar.d.qalam", "word": "قَلَم", "translation": "le stylo", "otherTranslations": ["le crayon"], "partOfSpeech": "noun", "transliteration": "qalam", "explanation": "Le stylo, le crayon : l''objet avec lequel on écrit. ق (deux points) au début, ل au milieu (trait simple), م final.", "examples": [{"text": "قَلَمِي", "translation": "mon stylo", "transliteration": "qalamî"}, {"text": "أَقْلَام", "translation": "des stylos", "transliteration": "aqlâm"}], "forms": {"plural": "أَقْلَام"}, "unitId": "ar.v.qalam"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kub', 'ar', 'كُوب', 'le verre, le gobelet', 'Un verre ou un gobelet, pour boire. ك (avec son zigzag) au début, attaché à و, qui coupe le mot ; puis ب isolé.', '[{"text": "كُوبِي", "translation": "mon verre", "transliteration": "kûbî"}, {"text": "أَكْوَاب", "translation": "des verres", "transliteration": "akwâb"}]'::jsonb, null, '{"id": "ar.d.kub", "word": "كُوب", "translation": "le verre, le gobelet", "otherTranslations": ["la tasse"], "partOfSpeech": "noun", "transliteration": "kûb", "explanation": "Un verre ou un gobelet, pour boire. ك (avec son zigzag) au début, attaché à و, qui coupe le mot ; puis ب isolé.", "examples": [{"text": "كُوبِي", "translation": "mon verre", "transliteration": "kûbî"}, {"text": "أَكْوَاب", "translation": "des verres", "transliteration": "akwâb"}], "forms": {"plural": "أَكْوَاب"}, "unitId": "ar.v.kub"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.hatif', 'ar', 'هَاتِف', 'le téléphone', 'Le téléphone. ه au début, ا qui coupe le mot, puis ت et ف attachés ensemble (ف en forme finale).', '[{"text": "هَاتِفِي", "translation": "mon téléphone", "transliteration": "hâtifî"}, {"text": "هَوَاتِف", "translation": "des téléphones", "transliteration": "hawâtif"}]'::jsonb, null, '{"id": "ar.d.hatif", "word": "هَاتِف", "translation": "le téléphone", "partOfSpeech": "noun", "transliteration": "hâtif", "explanation": "Le téléphone. ه au début, ا qui coupe le mot, puis ت et ف attachés ensemble (ف en forme finale).", "examples": [{"text": "هَاتِفِي", "translation": "mon téléphone", "transliteration": "hâtifî"}, {"text": "هَوَاتِف", "translation": "des téléphones", "transliteration": "hawâtif"}], "forms": {"plural": "هَوَاتِف"}, "unitId": "ar.v.hatif"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.miftah', 'ar', 'مِفْتَاح', 'la clé', 'La clé. م, ف (forme du milieu) et ت s''attachent à ا ; le dernier ح reste isolé après ا.', '[{"text": "مِفْتَاحِي", "translation": "ma clé", "transliteration": "miftâ7î"}, {"text": "مَفَاتِيح", "translation": "des clés", "transliteration": "mafâtî7"}]'::jsonb, null, '{"id": "ar.d.miftah", "word": "مِفْتَاح", "translation": "la clé", "partOfSpeech": "noun", "transliteration": "miftâ7", "explanation": "La clé. م, ف (forme du milieu) et ت s''attachent à ا ; le dernier ح reste isolé après ا.", "examples": [{"text": "مِفْتَاحِي", "translation": "ma clé", "transliteration": "miftâ7î"}, {"text": "مَفَاتِيح", "translation": "des clés", "transliteration": "mafâtî7"}], "forms": {"plural": "مَفَاتِيح"}, "unitId": "ar.v.miftah"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ta_marbuta', 'ar', 'ة', 'la lettre tâ'' marbûTa, le a final des mots féminins', 'ة est un ه surmonté de deux points. On ne la trouve qu''à la fin d''un mot, le plus souvent un féminin, et elle se lit a (مَكْتَبَة, maktaba). Elle n''a que deux formes : ـة (attachée) et ة (isolée, après ا د ذ ر ز و).', '[{"text": "مَكْتَبَة", "translation": "la bibliothèque (ـة attaché à ب)", "transliteration": "maktaba"}, {"text": "شَجَرَة", "translation": "l''arbre (ة isolé, après ر)", "transliteration": "chadjara"}]'::jsonb, null, '{"id": "ar.d.ta_marbuta", "word": "ة", "translation": "la lettre tâ'' marbûTa, le a final des mots féminins", "partOfSpeech": "letter", "transliteration": "tâ'' marbûTa", "explanation": "ة est un ه surmonté de deux points. On ne la trouve qu''à la fin d''un mot, le plus souvent un féminin, et elle se lit a (مَكْتَبَة, maktaba). Elle n''a que deux formes : ـة (attachée) et ة (isolée, après ا د ذ ر ز و).", "examples": [{"text": "مَكْتَبَة", "translation": "la bibliothèque (ـة attaché à ب)", "transliteration": "maktaba"}, {"text": "شَجَرَة", "translation": "l''arbre (ة isolé, après ر)", "transliteration": "chadjara"}], "confusions": [{"word": "ه", "note": "même boucle à la fin d''un mot, mais sans points : h."}, {"word": "ت", "note": "tâ'' ordinaire : une dent (ou une cuvette) à deux points, qui peut être au début ou au milieu."}], "forms": {"isolated": "ة", "initial": "ة", "medial": "ـة", "final": "ـة"}, "unitId": "ar.v.ta_marbuta"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.alif_maqsura', 'ar', 'ى', 'la lettre alif maqSûra, un â en fin de mot', 'ى ressemble à un ي sans aucun point. On ne la trouve qu''à la fin de certains mots, où elle se lit â (مَقْهَى, maqhâ). Elle n''a que deux formes : ى (isolée) et ـى (attachée).', '[{"text": "مَقْهَى", "translation": "le café (ـى attaché à ه)", "transliteration": "maqhâ"}, {"text": "مُسْتَشْفَى", "translation": "l''hôpital (ـى attaché à ف)", "transliteration": "mustachfâ"}]'::jsonb, null, '{"id": "ar.d.alif_maqsura", "word": "ى", "translation": "la lettre alif maqSûra, un â en fin de mot", "partOfSpeech": "letter", "transliteration": "alif maqSûra", "explanation": "ى ressemble à un ي sans aucun point. On ne la trouve qu''à la fin de certains mots, où elle se lit â (مَقْهَى, maqhâ). Elle n''a que deux formes : ى (isolée) et ـى (attachée).", "examples": [{"text": "مَقْهَى", "translation": "le café (ـى attaché à ه)", "transliteration": "maqhâ"}, {"text": "مُسْتَشْفَى", "translation": "l''hôpital (ـى attaché à ف)", "transliteration": "mustachfâ"}], "confusions": [{"word": "ي", "note": "même queue, avec deux points dessous : y ou î."}, {"word": "ا", "note": "alif : un trait vertical, qui s''écrit à la fin d''un mot au lieu de ى."}], "forms": {"isolated": "ى", "initial": "ى", "medial": "ـى", "final": "ـى"}, "unitId": "ar.v.alif_maqsura"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.hamza', 'ar', 'ء', 'la hamza, une brève coupure de gorge', 'ء est la hamza : une brève fermeture de la gorge, comme le petit arrêt dans « sa-a » (on la note ''). Elle peut se tenir seule sur la ligne (سَمَاء) ou être posée sur un support : أ إ ؤ ئ (détaillé au module 2). Elle n''a qu''une forme.', '[{"text": "سَمَاء", "translation": "le ciel (ء seule, après ا)", "transliteration": "samâ''"}, {"text": "مَاء", "translation": "l''eau (ء seule, après ا)", "transliteration": "mâ''"}]'::jsonb, null, '{"id": "ar.d.hamza", "word": "ء", "translation": "la hamza, une brève coupure de gorge", "partOfSpeech": "letter", "transliteration": "hamza", "explanation": "ء est la hamza : une brève fermeture de la gorge, comme le petit arrêt dans « sa-a » (on la note ''). Elle peut se tenir seule sur la ligne (سَمَاء) ou être posée sur un support : أ إ ؤ ئ (détaillé au module 2). Elle n''a qu''une forme.", "examples": [{"text": "سَمَاء", "translation": "le ciel (ء seule, après ا)", "transliteration": "samâ''"}, {"text": "مَاء", "translation": "l''eau (ء seule, après ا)", "transliteration": "mâ''"}], "confusions": [{"word": "ع", "note": "3ayn : une tête d''œil plus grande, un son de gorge serrée, pas une simple coupure."}, {"word": "أ", "note": "alif portant une hamza : le a du début de mot."}], "forms": {"isolated": "ء", "initial": "ء", "medial": "ء", "final": "ء"}, "unitId": "ar.v.hamza"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.lam_alif', 'ar', 'لا', 'la ligature lâm-alif, ل suivi de ا', 'Quand ل est suivi de ا, on ne les écrit jamais séparément : ils forment une ligature obligatoire, deux traits qui se croisent (لا, ـلا). Elle se lit lâ. Comme ا, elle ne s''attache pas à la lettre suivante.', '[{"text": "سَلَام", "translation": "la paix (ـلا attaché à س)", "transliteration": "salâm"}, {"text": "صَلَاة", "translation": "la prière (ـلا attaché à ص)", "transliteration": "Salâ"}]'::jsonb, null, '{"id": "ar.d.lam_alif", "word": "لا", "translation": "la ligature lâm-alif, ل suivi de ا", "partOfSpeech": "letter", "transliteration": "lâm-alif", "explanation": "Quand ل est suivi de ا, on ne les écrit jamais séparément : ils forment une ligature obligatoire, deux traits qui se croisent (لا, ـلا). Elle se lit lâ. Comme ا, elle ne s''attache pas à la lettre suivante.", "examples": [{"text": "سَلَام", "translation": "la paix (ـلا attaché à س)", "transliteration": "salâm"}, {"text": "صَلَاة", "translation": "la prière (ـلا attaché à ص)", "transliteration": "Salâ"}], "confusions": [{"word": "ال", "note": "alif puis lâm : l''article « le », autre ordre, autre sens (module 2)."}, {"word": "ك", "note": "kâf : un seul trait avec un zigzag."}], "forms": {"isolated": "لا", "initial": "لا", "medial": "ـلا", "final": "ـلا"}, "unitId": "ar.v.lam_alif"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.maktaba', 'ar', 'مَكْتَبَة', 'la bibliothèque, la librairie', 'Le lieu où l''on trouve des livres : bibliothèque ou librairie. Même racine que كِتَاب (le livre) et مَكْتَب (le bureau). Le ة final se lit a.', '[{"text": "مَكْتَبَتِي", "translation": "ma bibliothèque", "transliteration": "maktabatî"}, {"text": "مَكْتَبَات", "translation": "des bibliothèques", "transliteration": "maktabât"}]'::jsonb, null, '{"id": "ar.d.maktaba", "word": "مَكْتَبَة", "translation": "la bibliothèque, la librairie", "otherTranslations": ["la librairie"], "partOfSpeech": "noun", "transliteration": "maktaba", "explanation": "Le lieu où l''on trouve des livres : bibliothèque ou librairie. Même racine que كِتَاب (le livre) et مَكْتَب (le bureau). Le ة final se lit a.", "examples": [{"text": "مَكْتَبَتِي", "translation": "ma bibliothèque", "transliteration": "maktabatî"}, {"text": "مَكْتَبَات", "translation": "des bibliothèques", "transliteration": "maktabât"}], "confusions": [{"word": "مَكْتَب", "note": "maktab : le bureau, sans ة final."}], "forms": {"plural": "مَكْتَبَات"}, "unitId": "ar.v.maktaba"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.fakiha', 'ar', 'فَاكِهَة', 'le fruit', 'Un fruit (au singulier) ; le pluriel فَوَاكِه désigne les fruits en général. ف, ا, ك, ه, puis ة final.', '[{"text": "عَصِيرُ فَاكِهَة", "translation": "un jus de fruit", "transliteration": "3aSîru fâkiha"}, {"text": "فَوَاكِه", "translation": "des fruits", "transliteration": "fawâkih"}]'::jsonb, null, '{"id": "ar.d.fakiha", "word": "فَاكِهَة", "translation": "le fruit", "partOfSpeech": "noun", "transliteration": "fâkiha", "explanation": "Un fruit (au singulier) ; le pluriel فَوَاكِه désigne les fruits en général. ف, ا, ك, ه, puis ة final.", "examples": [{"text": "عَصِيرُ فَاكِهَة", "translation": "un jus de fruit", "transliteration": "3aSîru fâkiha"}, {"text": "فَوَاكِه", "translation": "des fruits", "transliteration": "fawâkih"}], "forms": {"plural": "فَوَاكِه"}, "unitId": "ar.v.fakiha"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.maqha', 'ar', 'مَقْهَى', 'le café (le lieu)', 'Le lieu où l''on boit du café et du thé. Il finit par ى (alif maqSûra), sans point, qui se lit â. Ne le confonds pas avec قَهْوَة (qahwa), la boisson.', '[{"text": "فِي الْمَقْهَى", "translation": "au café", "transliteration": "fî l-maqhâ"}, {"text": "قَهْوَة فِي الْمَقْهَى", "translation": "un café au café", "transliteration": "qahwa fî l-maqhâ"}]'::jsonb, null, '{"id": "ar.d.maqha", "word": "مَقْهَى", "translation": "le café (le lieu)", "partOfSpeech": "noun", "transliteration": "maqhâ", "explanation": "Le lieu où l''on boit du café et du thé. Il finit par ى (alif maqSûra), sans point, qui se lit â. Ne le confonds pas avec قَهْوَة (qahwa), la boisson.", "examples": [{"text": "فِي الْمَقْهَى", "translation": "au café", "transliteration": "fî l-maqhâ"}, {"text": "قَهْوَة فِي الْمَقْهَى", "translation": "un café au café", "transliteration": "qahwa fî l-maqhâ"}], "confusions": [{"word": "قَهْوَة", "note": "qahwa : la boisson, le café qu''on boit."}], "unitId": "ar.v.maqha"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sama', 'ar', 'سَمَاء', 'le ciel', 'Le ciel. Il finit par une hamza (ء) seule sur la ligne, après ا : une brève coupure de gorge.', '[{"text": "فِي السَّمَاء", "translation": "dans le ciel", "transliteration": "fî s-samâ''"}, {"text": "سَمَاوَات", "translation": "des cieux", "transliteration": "samâwât"}]'::jsonb, null, '{"id": "ar.d.sama", "word": "سَمَاء", "translation": "le ciel", "partOfSpeech": "noun", "transliteration": "samâ''", "explanation": "Le ciel. Il finit par une hamza (ء) seule sur la ligne, après ا : une brève coupure de gorge.", "examples": [{"text": "فِي السَّمَاء", "translation": "dans le ciel", "transliteration": "fî s-samâ''"}, {"text": "سَمَاوَات", "translation": "des cieux", "transliteration": "samâwât"}], "forms": {"plural": "سَمَاوَات"}, "unitId": "ar.v.sama"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.salam', 'ar', 'سَلَام', 'la paix, le salut', 'La paix, et aussi le « salut » de la salutation السَّلَامُ عَلَيْكُمْ. Le ل et le ا s''écrivent en ligature لا.', '[{"text": "السَّلَامُ عَلَيْكُمْ", "translation": "que la paix soit sur vous", "transliteration": "as-salâmu 3alaykum"}, {"text": "سَلَامٌ لَكَ", "translation": "paix à toi", "transliteration": "salâmun laka"}]'::jsonb, null, '{"id": "ar.d.salam", "word": "سَلَام", "translation": "la paix, le salut", "otherTranslations": ["la salutation"], "partOfSpeech": "noun", "transliteration": "salâm", "explanation": "La paix, et aussi le « salut » de la salutation السَّلَامُ عَلَيْكُمْ. Le ل et le ا s''écrivent en ligature لا.", "examples": [{"text": "السَّلَامُ عَلَيْكُمْ", "translation": "que la paix soit sur vous", "transliteration": "as-salâmu 3alaykum"}, {"text": "سَلَامٌ لَكَ", "translation": "paix à toi", "transliteration": "salâmun laka"}], "unitId": "ar.v.salam"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.fatha', 'ar', 'فَتْحَة', 'fatha : le signe de la voyelle a', 'Petit trait oblique posé au-dessus de la lettre : il donne le son a bref (بَ = ba).', '[{"text": "كَتَبَ", "translation": "il a écrit", "transliteration": "kataba"}, {"text": "وَلَد", "translation": "garçon", "transliteration": "walad"}]'::jsonb, null, '{"id": "ar.d.fatha", "word": "فَتْحَة", "translation": "fatha : le signe de la voyelle a", "otherTranslations": ["ouverture"], "partOfSpeech": "letter", "transliteration": "fat7a", "explanation": "Petit trait oblique posé au-dessus de la lettre : il donne le son a bref (بَ = ba).", "examples": [{"text": "كَتَبَ", "translation": "il a écrit", "transliteration": "kataba"}, {"text": "وَلَد", "translation": "garçon", "transliteration": "walad"}], "confusions": [{"word": "كَسْرَة (kasra)", "note": "le même trait, mais sous la lettre : son i."}], "forms": {"signe": "ـَ"}, "unitId": "ar.v.fatha"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kasra', 'ar', 'كَسْرَة', 'kasra : le signe de la voyelle i', 'Petit trait oblique placé sous la lettre : il donne le son i bref (بِ = bi).', '[{"text": "كَتِف", "translation": "épaule", "transliteration": "katif"}, {"text": "فَهِمَ", "translation": "il a compris", "transliteration": "fahima"}]'::jsonb, null, '{"id": "ar.d.kasra", "word": "كَسْرَة", "translation": "kasra : le signe de la voyelle i", "otherTranslations": ["brisure"], "partOfSpeech": "letter", "transliteration": "kasra", "explanation": "Petit trait oblique placé sous la lettre : il donne le son i bref (بِ = bi).", "examples": [{"text": "كَتِف", "translation": "épaule", "transliteration": "katif"}, {"text": "فَهِمَ", "translation": "il a compris", "transliteration": "fahima"}], "confusions": [{"word": "فَتْحَة (fatha)", "note": "le même trait, mais au-dessus de la lettre : son a."}], "forms": {"signe": "ـِ"}, "unitId": "ar.v.kasra"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.damma', 'ar', 'ضَمَّة', 'damma : le signe de la voyelle u (« ou »)', 'Petite boucle en forme de و posée au-dessus de la lettre : elle donne le son u, prononcé « ou » (بُ = bu).', '[{"text": "عُنُق", "translation": "cou", "transliteration": "3unuq"}, {"text": "رَجُل", "translation": "homme", "transliteration": "radjul"}]'::jsonb, null, '{"id": "ar.d.damma", "word": "ضَمَّة", "translation": "damma : le signe de la voyelle u (« ou »)", "partOfSpeech": "letter", "transliteration": "Damma", "explanation": "Petite boucle en forme de و posée au-dessus de la lettre : elle donne le son u, prononcé « ou » (بُ = bu).", "examples": [{"text": "عُنُق", "translation": "cou", "transliteration": "3unuq"}, {"text": "رَجُل", "translation": "homme", "transliteration": "radjul"}], "confusions": [{"word": "سُكُون (sukun)", "note": "petit rond sans queue : la lettre n''a pas de voyelle."}], "forms": {"signe": "ـُ"}, "unitId": "ar.v.damma"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.walad', 'ar', 'وَلَد', 'garçon', 'Un garçon ou, plus largement, un enfant ; au pluriel أَوْلَاد (awlâd), « les enfants ».', '[{"text": "هٰذَا وَلَدٌ صَغِيرٌ.", "translation": "C''est un petit garçon.", "transliteration": "hâdhâ waladun Saghîrun"}, {"text": "وَلَدِي فِي الْبَيْتِ.", "translation": "Mon fils est à la maison.", "transliteration": "waladî fî l-bayti"}]'::jsonb, null, '{"id": "ar.d.walad", "word": "وَلَد", "translation": "garçon", "otherTranslations": ["enfant", "fils"], "partOfSpeech": "noun", "transliteration": "walad", "explanation": "Un garçon ou, plus largement, un enfant ; au pluriel أَوْلَاد (awlâd), « les enfants ».", "examples": [{"text": "هٰذَا وَلَدٌ صَغِيرٌ.", "translation": "C''est un petit garçon.", "transliteration": "hâdhâ waladun Saghîrun"}, {"text": "وَلَدِي فِي الْبَيْتِ.", "translation": "Mon fils est à la maison.", "transliteration": "waladî fî l-bayti"}], "confusions": [{"word": "بِنْت (bint)", "note": "la fille."}], "forms": {"plural": "أَوْلَاد"}, "unitId": "ar.v.walad"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.radjul', 'ar', 'رَجُل', 'homme', 'Un homme adulte ; le pluriel est رِجَال (ridjâl).', '[{"text": "الرَّجُلُ طَوِيلٌ.", "translation": "L''homme est grand.", "transliteration": "ar-radjulu Tawîlun"}, {"text": "جَلَسَ رَجُلٌ.", "translation": "Un homme s''est assis.", "transliteration": "djalasa radjulun"}]'::jsonb, null, '{"id": "ar.d.radjul", "word": "رَجُل", "translation": "homme", "partOfSpeech": "noun", "transliteration": "radjul", "explanation": "Un homme adulte ; le pluriel est رِجَال (ridjâl).", "examples": [{"text": "الرَّجُلُ طَوِيلٌ.", "translation": "L''homme est grand.", "transliteration": "ar-radjulu Tawîlun"}, {"text": "جَلَسَ رَجُلٌ.", "translation": "Un homme s''est assis.", "transliteration": "djalasa radjulun"}], "confusions": [{"word": "رِجْل (ridjl)", "note": "la jambe, le pied : mêmes lettres, autres signes !"}], "forms": {"plural": "رِجَال"}, "unitId": "ar.v.radjul"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.yad', 'ar', 'يَد', 'main', 'La main ; c''est un mot féminin.', '[{"text": "يَدِي", "translation": "ma main", "transliteration": "yadî"}, {"text": "يَدُ الْوَلَدِ صَغِيرَةٌ.", "translation": "La main du garçon est petite.", "transliteration": "yadu l-waladi Saghîratun"}]'::jsonb, null, '{"id": "ar.d.yad", "word": "يَد", "translation": "main", "partOfSpeech": "noun", "transliteration": "yad", "explanation": "La main ; c''est un mot féminin.", "examples": [{"text": "يَدِي", "translation": "ma main", "transliteration": "yadî"}, {"text": "يَدُ الْوَلَدِ صَغِيرَةٌ.", "translation": "La main du garçon est petite.", "transliteration": "yadu l-waladi Saghîratun"}], "confusions": [], "forms": {"plural": "أَيْدٍ"}, "unitId": "ar.v.yad"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.fam', 'ar', 'فَم', 'bouche', 'La bouche ; un mot très court : fa-m.', '[{"text": "فَمُ الطِّفْلِ صَغِيرٌ.", "translation": "La bouche de l''enfant est petite.", "transliteration": "famu T-Tifli Saghîrun"}, {"text": "فَتَحَ فَمَهُ.", "translation": "Il a ouvert la bouche.", "transliteration": "fata7a famahu"}]'::jsonb, null, '{"id": "ar.d.fam", "word": "فَم", "translation": "bouche", "partOfSpeech": "noun", "transliteration": "fam", "explanation": "La bouche ; un mot très court : fa-m.", "examples": [{"text": "فَمُ الطِّفْلِ صَغِيرٌ.", "translation": "La bouche de l''enfant est petite.", "transliteration": "famu T-Tifli Saghîrun"}, {"text": "فَتَحَ فَمَهُ.", "translation": "Il a ouvert la bouche.", "transliteration": "fata7a famahu"}], "confusions": [], "forms": {"plural": "أَفْوَاه"}, "unitId": "ar.v.fam"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
