insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.chaar', 'ar', 'شَعْر', 'cheveux', 'Les cheveux (et les poils) ; le mot est au singulier en arabe. Avec l''article : الشَّعْر (ach-cha3r).', '[{"text": "شَعْرُهَا طَوِيلٌ.", "translation": "Elle a les cheveux longs.", "transliteration": "cha3ruhâ Tawîlun"}, {"text": "الشَّعْرُ الْأَسْوَدُ", "translation": "les cheveux noirs", "transliteration": "ach-cha3ru l-aswadu"}]'::jsonb, null, '{"id": "ar.d.chaar", "word": "شَعْر", "translation": "cheveux", "otherTranslations": ["poils"], "partOfSpeech": "noun", "transliteration": "cha3r", "explanation": "Les cheveux (et les poils) ; le mot est au singulier en arabe. Avec l''article : الشَّعْر (ach-cha3r).", "examples": [{"text": "شَعْرُهَا طَوِيلٌ.", "translation": "Elle a les cheveux longs.", "transliteration": "cha3ruhâ Tawîlun"}, {"text": "الشَّعْرُ الْأَسْوَدُ", "translation": "les cheveux noirs", "transliteration": "ach-cha3ru l-aswadu"}], "confusions": [{"word": "شِعْر (chi3r)", "note": "la poésie : kasra au lieu de fatha."}], "unitId": "ar.v.chaar"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
