insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.fatat', 'ar', 'فَتَاة', 'jeune fille', 'Une jeune fille, une adolescente ; pluriel فَتَيَات (fatayât). Isolé, le mot se lit fatâ ; le t revient devant une terminaison : fatâtun.', '[{"text": "فَتَاةٌ ذَكِيَّةٌ", "translation": "une jeune fille intelligente", "transliteration": "fatâtun dhakiyyatun"}, {"text": "الْفَتَاةُ تَقْرَأُ.", "translation": "La jeune fille lit.", "transliteration": "al-fatâtu taqra''u"}]'::jsonb, null, '{"id": "ar.d.fatat", "word": "فَتَاة", "translation": "jeune fille", "partOfSpeech": "noun", "transliteration": "fatâ", "explanation": "Une jeune fille, une adolescente ; pluriel فَتَيَات (fatayât). Isolé, le mot se lit fatâ ; le t revient devant une terminaison : fatâtun.", "examples": [{"text": "فَتَاةٌ ذَكِيَّةٌ", "translation": "une jeune fille intelligente", "transliteration": "fatâtun dhakiyyatun"}, {"text": "الْفَتَاةُ تَقْرَأُ.", "translation": "La jeune fille lit.", "transliteration": "al-fatâtu taqra''u"}], "confusions": [{"word": "بِنْت (bint)", "note": "la fille (enfant), ou la fille de quelqu''un."}], "forms": {"plural": "فَتَيَات"}, "unitId": "ar.v.fatat"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
