insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.qamar', 'ar', 'قَمَر', 'la lune', 'قَمَر est la lune ; le mot est masculin : الْقَمَرُ (al-qamar). Il se lit en 2 syllabes : qa-mar.', '[{"text": "الْقَمَرُ جَمِيلٌ", "translation": "La lune est belle.", "transliteration": "al-qamaru djamîl"}, {"text": "الْقَمَرُ كَبِيرٌ", "translation": "La lune est grande.", "transliteration": "al-qamaru kabîr"}]'::jsonb, null, '{"id": "ar.d.qamar", "word": "قَمَر", "transliteration": "qamar", "translation": "la lune", "partOfSpeech": "noun", "explanation": "قَمَر est la lune ; le mot est masculin : الْقَمَرُ (al-qamar). Il se lit en 2 syllabes : qa-mar.", "examples": [{"text": "الْقَمَرُ جَمِيلٌ", "translation": "La lune est belle.", "transliteration": "al-qamaru djamîl"}, {"text": "الْقَمَرُ كَبِيرٌ", "translation": "La lune est grande.", "transliteration": "al-qamaru kabîr"}], "confusions": [{"word": "شَمْس", "note": "chams, le soleil (féminin), l''autre astre du ciel."}], "forms": {"plural": "أَقْمَار"}, "unitId": "ar.v.qamar"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.djabal', 'ar', 'جَبَل', 'la montagne', 'جَبَل veut dire « la montagne ». Masculin, 2 syllabes : dja-bal.', '[{"text": "الْجَبَلُ كَبِيرٌ", "translation": "La montagne est grande.", "transliteration": "al-djabalu kabîr"}, {"text": "الثَّلْجُ عَلَى الْجَبَلِ", "translation": "La neige est sur la montagne.", "transliteration": "ath-thaldju 3alâ l-djabal"}]'::jsonb, null, '{"id": "ar.d.djabal", "word": "جَبَل", "transliteration": "djabal", "translation": "la montagne", "partOfSpeech": "noun", "explanation": "جَبَل veut dire « la montagne ». Masculin, 2 syllabes : dja-bal.", "examples": [{"text": "الْجَبَلُ كَبِيرٌ", "translation": "La montagne est grande.", "transliteration": "al-djabalu kabîr"}, {"text": "الثَّلْجُ عَلَى الْجَبَلِ", "translation": "La neige est sur la montagne.", "transliteration": "ath-thaldju 3alâ l-djabal"}], "confusions": [{"word": "حَبْل", "note": "7abl, la corde : ح n''a pas de point et le ب porte un soukoun."}], "forms": {"plural": "جِبَال"}, "unitId": "ar.v.djabal"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.matar', 'ar', 'مَطَر', 'la pluie', 'مَطَر est la pluie. Trois lettres, trois voyelles brèves : ma-Tar.', '[{"text": "الْمَطَرُ بَارِدٌ", "translation": "La pluie est froide.", "transliteration": "al-maTaru bârid"}, {"text": "لَا مَطَرَ الْيَوْمَ", "translation": "Il n''y a pas de pluie aujourd''hui.", "transliteration": "lâ maTara l-yawm"}]'::jsonb, null, '{"id": "ar.d.matar", "word": "مَطَر", "transliteration": "maTar", "translation": "la pluie", "partOfSpeech": "noun", "explanation": "مَطَر est la pluie. Trois lettres, trois voyelles brèves : ma-Tar.", "examples": [{"text": "الْمَطَرُ بَارِدٌ", "translation": "La pluie est froide.", "transliteration": "al-maTaru bârid"}, {"text": "لَا مَطَرَ الْيَوْمَ", "translation": "Il n''y a pas de pluie aujourd''hui.", "transliteration": "lâ maTara l-yawm"}], "confusions": [{"word": "مَطَار", "note": "maTâr, l''aéroport : un ا en plus, donc une voyelle longue."}], "forms": {"plural": "أَمْطَار"}, "unitId": "ar.v.matar"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.chadjara', 'ar', 'شَجَرَة', 'l''arbre', 'شَجَرَة est un arbre. Le mot est féminin (finale ـة) : on dit هٰذِهِ شَجَرَةٌ. Trois syllabes ouvertes : cha-dja-ra.', '[{"text": "هٰذِهِ شَجَرَةٌ كَبِيرَةٌ", "translation": "C''est un grand arbre.", "transliteration": "hâdhihi chadjaratun kabîra"}, {"text": "الشَّجَرَةُ فِي الشَّارِعِ", "translation": "L''arbre est dans la rue.", "transliteration": "ach-chadjaratu fî ch-châri3"}]'::jsonb, null, '{"id": "ar.d.chadjara", "word": "شَجَرَة", "transliteration": "chadjara", "translation": "l''arbre", "partOfSpeech": "noun", "explanation": "شَجَرَة est un arbre. Le mot est féminin (finale ـة) : on dit هٰذِهِ شَجَرَةٌ. Trois syllabes ouvertes : cha-dja-ra.", "examples": [{"text": "هٰذِهِ شَجَرَةٌ كَبِيرَةٌ", "translation": "C''est un grand arbre.", "transliteration": "hâdhihi chadjaratun kabîra"}, {"text": "الشَّجَرَةُ فِي الشَّارِعِ", "translation": "L''arbre est dans la rue.", "transliteration": "ach-chadjaratu fî ch-châri3"}], "forms": {"plural": "أَشْجَار", "collective": "شَجَر"}, "unitId": "ar.v.chadjara"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.samak', 'ar', 'سَمَك', 'le poisson', 'سَمَك désigne le poisson en général (comme aliment ou animal). Pour « un poisson », on dit سَمَكَة.', '[{"text": "أَكَلَ السَّمَكَ", "translation": "Il a mangé le poisson.", "transliteration": "''akala s-samak"}, {"text": "السَّمَكُ فِي الْبَحْرِ", "translation": "Le poisson est dans la mer.", "transliteration": "as-samaku fî l-ba7r"}]'::jsonb, null, '{"id": "ar.d.samak", "word": "سَمَك", "transliteration": "samak", "translation": "le poisson", "partOfSpeech": "noun", "explanation": "سَمَك désigne le poisson en général (comme aliment ou animal). Pour « un poisson », on dit سَمَكَة.", "examples": [{"text": "أَكَلَ السَّمَكَ", "translation": "Il a mangé le poisson.", "transliteration": "''akala s-samak"}, {"text": "السَّمَكُ فِي الْبَحْرِ", "translation": "Le poisson est dans la mer.", "transliteration": "as-samaku fî l-ba7r"}], "forms": {"singular": "سَمَكَة", "plural": "أَسْمَاك"}, "unitId": "ar.v.samak"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.madrasa', 'ar', 'مَدْرَسَة', 'l''école', 'مَدْرَسَة est le lieu où l''on étudie : مَـ (lieu) + d-r-s, la racine de دَرَسَ (étudier). Trois syllabes : mad-ra-sa.', '[{"text": "أَنَا فِي الْمَدْرَسَةِ", "translation": "Je suis à l''école.", "transliteration": "''anâ fî l-madrasa"}, {"text": "هٰذِهِ مَدْرَسَةٌ جَدِيدَةٌ", "translation": "C''est une nouvelle école.", "transliteration": "hâdhihi madrasatun djadîda"}]'::jsonb, null, '{"id": "ar.d.madrasa", "word": "مَدْرَسَة", "transliteration": "madrasa", "translation": "l''école", "partOfSpeech": "noun", "explanation": "مَدْرَسَة est le lieu où l''on étudie : مَـ (lieu) + d-r-s, la racine de دَرَسَ (étudier). Trois syllabes : mad-ra-sa.", "examples": [{"text": "أَنَا فِي الْمَدْرَسَةِ", "translation": "Je suis à l''école.", "transliteration": "''anâ fî l-madrasa"}, {"text": "هٰذِهِ مَدْرَسَةٌ جَدِيدَةٌ", "translation": "C''est une nouvelle école.", "transliteration": "hâdhihi madrasatun djadîda"}], "forms": {"plural": "مَدَارِس"}, "unitId": "ar.v.madrasa"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.min', 'ar', 'مِنْ', 'de, depuis (provenance)', 'مِنْ indique d''où l''on vient ou d''où vient une chose. Devant l''article الـ, il devient مِنَ (mina) pour enchaîner.', '[{"text": "هُوَ مِنْ مِصْرَ", "translation": "Il est d''Égypte.", "transliteration": "huwa min miSr"}, {"text": "الْخُبْزُ مِنَ السُّوقِ", "translation": "Le pain vient du marché.", "transliteration": "al-khubzu mina s-sûq"}]'::jsonb, null, '{"id": "ar.d.min", "word": "مِنْ", "transliteration": "min", "translation": "de, depuis (provenance)", "partOfSpeech": "preposition", "explanation": "مِنْ indique d''où l''on vient ou d''où vient une chose. Devant l''article الـ, il devient مِنَ (mina) pour enchaîner.", "examples": [{"text": "هُوَ مِنْ مِصْرَ", "translation": "Il est d''Égypte.", "transliteration": "huwa min miSr"}, {"text": "الْخُبْزُ مِنَ السُّوقِ", "translation": "Le pain vient du marché.", "transliteration": "al-khubzu mina s-sûq"}], "confusions": [{"word": "مَنْ", "note": "man, « qui ? » : mêmes lettres, mais une fatha sur م au lieu d''une kasra."}], "unitId": "ar.v.min"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.fi', 'ar', 'فِي', 'dans, à, en', 'فِي est la préposition la plus fréquente : le lieu (dans, à) et le moment (en). Le nom qui suit finit par une kasra : فِي الْبَيْتِ.', '[{"text": "هُوَ فِي الْمَدْرَسَةِ", "translation": "Il est à l''école.", "transliteration": "huwa fî l-madrasa"}, {"text": "السَّمَكُ فِي الْمَاءِ", "translation": "Le poisson est dans l''eau.", "transliteration": "as-samaku fî l-mâ''"}]'::jsonb, null, '{"id": "ar.d.fi", "word": "فِي", "transliteration": "fî", "translation": "dans, à, en", "partOfSpeech": "preposition", "explanation": "فِي est la préposition la plus fréquente : le lieu (dans, à) et le moment (en). Le nom qui suit finit par une kasra : فِي الْبَيْتِ.", "examples": [{"text": "هُوَ فِي الْمَدْرَسَةِ", "translation": "Il est à l''école.", "transliteration": "huwa fî l-madrasa"}, {"text": "السَّمَكُ فِي الْمَاءِ", "translation": "Le poisson est dans l''eau.", "transliteration": "as-samaku fî l-mâ''"}], "unitId": "ar.v.fi"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kataba', 'ar', 'كَتَبَ', 'écrire (il a écrit)', 'كَتَبَ est la forme du dictionnaire : « il a écrit ». Racine k-t-b, que l''on retrouve dans كِتَاب (livre) et مَكْتَب (bureau).', '[{"text": "كَتَبَ كِتَابًا", "translation": "Il a écrit un livre.", "transliteration": "kataba kitâban"}, {"text": "كَتَبَ فِي الْمَكْتَبِ", "translation": "Il a écrit au bureau.", "transliteration": "kataba fî l-maktab"}]'::jsonb, null, '{"id": "ar.d.kataba", "word": "كَتَبَ", "transliteration": "kataba", "translation": "écrire (il a écrit)", "partOfSpeech": "verb", "explanation": "كَتَبَ est la forme du dictionnaire : « il a écrit ». Racine k-t-b, que l''on retrouve dans كِتَاب (livre) et مَكْتَب (bureau).", "examples": [{"text": "كَتَبَ كِتَابًا", "translation": "Il a écrit un livre.", "transliteration": "kataba kitâban"}, {"text": "كَتَبَ فِي الْمَكْتَبِ", "translation": "Il a écrit au bureau.", "transliteration": "kataba fî l-maktab"}], "forms": {"present": "يَكْتُبُ"}, "unitId": "ar.v.kataba"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.darasa', 'ar', 'دَرَسَ', 'étudier (il a étudié)', 'دَرَسَ veut dire « il a étudié ». Racine d-r-s, comme مَدْرَسَة (école). Attention : 3 lettres qui ne s''attachent pas, donc 3 blocs.', '[{"text": "دَرَسَ فِي الْمَدْرَسَةِ", "translation": "Il a étudié à l''école.", "transliteration": "darasa fî l-madrasa"}, {"text": "دَرَسَ الْكِتَابَ", "translation": "Il a étudié le livre.", "transliteration": "darasa l-kitâb"}]'::jsonb, null, '{"id": "ar.d.darasa", "word": "دَرَسَ", "transliteration": "darasa", "translation": "étudier (il a étudié)", "partOfSpeech": "verb", "explanation": "دَرَسَ veut dire « il a étudié ». Racine d-r-s, comme مَدْرَسَة (école). Attention : 3 lettres qui ne s''attachent pas, donc 3 blocs.", "examples": [{"text": "دَرَسَ فِي الْمَدْرَسَةِ", "translation": "Il a étudié à l''école.", "transliteration": "darasa fî l-madrasa"}, {"text": "دَرَسَ الْكِتَابَ", "translation": "Il a étudié le livre.", "transliteration": "darasa l-kitâb"}], "confusions": [{"word": "دَرْس", "note": "dars, la leçon : même racine, avec un soukoun sur ر."}], "forms": {"present": "يَدْرُسُ"}, "unitId": "ar.v.darasa"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.dhahaba', 'ar', 'ذَهَبَ', 'aller (il est allé)', 'ذَهَبَ veut dire « il est allé ». On l''emploie avec إِلَى (vers) : ذَهَبَ إِلَى… = il est allé à…', '[{"text": "ذَهَبَ إِلَى الْمَدْرَسَةِ", "translation": "Il est allé à l''école.", "transliteration": "dhahaba ''ilâ l-madrasa"}, {"text": "ذَهَبَ إِلَى السُّوقِ", "translation": "Il est allé au marché.", "transliteration": "dhahaba ''ilâ s-sûq"}]'::jsonb, null, '{"id": "ar.d.dhahaba", "word": "ذَهَبَ", "transliteration": "dhahaba", "translation": "aller (il est allé)", "partOfSpeech": "verb", "explanation": "ذَهَبَ veut dire « il est allé ». On l''emploie avec إِلَى (vers) : ذَهَبَ إِلَى… = il est allé à…", "examples": [{"text": "ذَهَبَ إِلَى الْمَدْرَسَةِ", "translation": "Il est allé à l''école.", "transliteration": "dhahaba ''ilâ l-madrasa"}, {"text": "ذَهَبَ إِلَى السُّوقِ", "translation": "Il est allé au marché.", "transliteration": "dhahaba ''ilâ s-sûq"}], "confusions": [{"word": "ذَهَب", "note": "dhahab, l''or : mêmes lettres, sans voyelle sur la dernière."}], "forms": {"present": "يَذْهَبُ"}, "unitId": "ar.v.dhahaba"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.akala', 'ar', 'أَكَلَ', 'manger (il a mangé)', 'أَكَلَ veut dire « il a mangé ». Le أ du début porte une hamza : on attaque le mot par un petit coup de gorge, ''a-ka-la.', '[{"text": "أَكَلَ الْخُبْزَ", "translation": "Il a mangé le pain.", "transliteration": "''akala l-khubz"}, {"text": "أَكَلَ فِي الْمَطْعَمِ", "translation": "Il a mangé au restaurant.", "transliteration": "''akala fî l-maT3am"}]'::jsonb, null, '{"id": "ar.d.akala", "word": "أَكَلَ", "transliteration": "''akala", "translation": "manger (il a mangé)", "partOfSpeech": "verb", "explanation": "أَكَلَ veut dire « il a mangé ». Le أ du début porte une hamza : on attaque le mot par un petit coup de gorge, ''a-ka-la.", "examples": [{"text": "أَكَلَ الْخُبْزَ", "translation": "Il a mangé le pain.", "transliteration": "''akala l-khubz"}, {"text": "أَكَلَ فِي الْمَطْعَمِ", "translation": "Il a mangé au restaurant.", "transliteration": "''akala fî l-maT3am"}], "forms": {"present": "يَأْكُلُ"}, "unitId": "ar.v.akala"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.chariba', 'ar', 'شَرِبَ', 'boire (il a bu)', 'شَرِبَ veut dire « il a bu ». Attention au rythme : une kasra sous ر, cha-ri-ba.', '[{"text": "شَرِبَ الْمَاءَ", "translation": "Il a bu l''eau.", "transliteration": "chariba l-mâ''"}, {"text": "شَرِبَ الشَّايَ", "translation": "Il a bu le thé.", "transliteration": "chariba ch-chây"}]'::jsonb, null, '{"id": "ar.d.chariba", "word": "شَرِبَ", "transliteration": "chariba", "translation": "boire (il a bu)", "partOfSpeech": "verb", "explanation": "شَرِبَ veut dire « il a bu ». Attention au rythme : une kasra sous ر, cha-ri-ba.", "examples": [{"text": "شَرِبَ الْمَاءَ", "translation": "Il a bu l''eau.", "transliteration": "chariba l-mâ''"}, {"text": "شَرِبَ الشَّايَ", "translation": "Il a bu le thé.", "transliteration": "chariba ch-chây"}], "forms": {"present": "يَشْرَبُ"}, "unitId": "ar.v.chariba"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.fataha', 'ar', 'فَتَحَ', 'ouvrir (il a ouvert)', 'فَتَحَ veut dire « il a ouvert ». Trois lettres attachées en un seul bloc : fa-ta-7a.', '[{"text": "فَتَحَ الْكِتَابَ", "translation": "Il a ouvert le livre.", "transliteration": "fata7a l-kitâb"}, {"text": "فَتَحَ الْبَابَ", "translation": "Il a ouvert la porte.", "transliteration": "fata7a l-bâb"}]'::jsonb, null, '{"id": "ar.d.fataha", "word": "فَتَحَ", "transliteration": "fata7a", "translation": "ouvrir (il a ouvert)", "partOfSpeech": "verb", "explanation": "فَتَحَ veut dire « il a ouvert ». Trois lettres attachées en un seul bloc : fa-ta-7a.", "examples": [{"text": "فَتَحَ الْكِتَابَ", "translation": "Il a ouvert le livre.", "transliteration": "fata7a l-kitâb"}, {"text": "فَتَحَ الْبَابَ", "translation": "Il a ouvert la porte.", "transliteration": "fata7a l-bâb"}], "forms": {"present": "يَفْتَحُ"}, "unitId": "ar.v.fataha"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.djalasa', 'ar', 'جَلَسَ', 's''asseoir (il s''est assis)', 'جَلَسَ veut dire « il s''est assis ». Un seul bloc, rythme CaCaCa : dja-la-sa.', '[{"text": "جَلَسَ هُنَا", "translation": "Il s''est assis ici.", "transliteration": "djalasa hunâ"}, {"text": "جَلَسَ فِي الْمَطْعَمِ", "translation": "Il s''est assis au restaurant.", "transliteration": "djalasa fî l-maT3am"}]'::jsonb, null, '{"id": "ar.d.djalasa", "word": "جَلَسَ", "transliteration": "djalasa", "translation": "s''asseoir (il s''est assis)", "partOfSpeech": "verb", "explanation": "جَلَسَ veut dire « il s''est assis ». Un seul bloc, rythme CaCaCa : dja-la-sa.", "examples": [{"text": "جَلَسَ هُنَا", "translation": "Il s''est assis ici.", "transliteration": "djalasa hunâ"}, {"text": "جَلَسَ فِي الْمَطْعَمِ", "translation": "Il s''est assis au restaurant.", "transliteration": "djalasa fî l-maT3am"}], "forms": {"present": "يَجْلِسُ"}, "unitId": "ar.v.djalasa"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.maktab', 'ar', 'مَكْتَب', 'le bureau', 'مَكْتَب est le bureau (la table ou la pièce) : مَـ (lieu) + k-t-b (écrire), « le lieu où l''on écrit ».', '[{"text": "الْمَكْتَبُ كَبِيرٌ", "translation": "Le bureau est grand.", "transliteration": "al-maktabu kabîr"}, {"text": "أَنَا فِي الْمَكْتَبِ", "translation": "Je suis au bureau.", "transliteration": "''anâ fî l-maktab"}]'::jsonb, null, '{"id": "ar.d.maktab", "word": "مَكْتَب", "transliteration": "maktab", "translation": "le bureau", "partOfSpeech": "noun", "explanation": "مَكْتَب est le bureau (la table ou la pièce) : مَـ (lieu) + k-t-b (écrire), « le lieu où l''on écrit ».", "examples": [{"text": "الْمَكْتَبُ كَبِيرٌ", "translation": "Le bureau est grand.", "transliteration": "al-maktabu kabîr"}, {"text": "أَنَا فِي الْمَكْتَبِ", "translation": "Je suis au bureau.", "transliteration": "''anâ fî l-maktab"}], "confusions": [{"word": "مَكْتَبَة", "note": "maktaba, la bibliothèque ou la librairie : un ة en plus."}], "forms": {"plural": "مَكَاتِب"}, "unitId": "ar.v.maktab"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.warda', 'ar', 'وَرْدَة', 'la rose, la fleur', 'وَرْدَة est une rose, et plus largement une fleur. Le mot est fait de 4 lettres qui ne s''attachent pas à gauche : 4 blocs, و | ر | د | ة.', '[{"text": "هٰذِهِ وَرْدَةٌ جَمِيلَةٌ", "translation": "C''est une belle rose.", "transliteration": "hâdhihi wardatun djamîla"}, {"text": "الْوَرْدَةُ فِي الْبَيْتِ", "translation": "La rose est dans la maison.", "transliteration": "al-wardatu fî l-bayt"}]'::jsonb, null, '{"id": "ar.d.warda", "word": "وَرْدَة", "transliteration": "warda", "translation": "la rose, la fleur", "partOfSpeech": "noun", "explanation": "وَرْدَة est une rose, et plus largement une fleur. Le mot est fait de 4 lettres qui ne s''attachent pas à gauche : 4 blocs, و | ر | د | ة.", "examples": [{"text": "هٰذِهِ وَرْدَةٌ جَمِيلَةٌ", "translation": "C''est une belle rose.", "transliteration": "hâdhihi wardatun djamîla"}, {"text": "الْوَرْدَةُ فِي الْبَيْتِ", "translation": "La rose est dans la maison.", "transliteration": "al-wardatu fî l-bayt"}], "confusions": [{"word": "وَرَق", "note": "waraq, les feuilles, le papier."}], "forms": {"plural": "وُرُود"}, "unitId": "ar.v.warda"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.aruzz', 'ar', 'أَرُزّ', 'le riz', 'أَرُزّ est le riz. La chadda sur ز double la lettre : ''a-ruzz. Trois blocs : أ | ر | ز. En Égypte, on dit رُزّ (ruzz).', '[{"text": "أَكَلَ الْأَرُزَّ", "translation": "Il a mangé le riz.", "transliteration": "''akala l-''aruzz"}, {"text": "الْأَرُزُّ حَارٌّ", "translation": "Le riz est chaud.", "transliteration": "al-''aruzzu 7ârr"}]'::jsonb, null, '{"id": "ar.d.aruzz", "word": "أَرُزّ", "transliteration": "''aruzz", "translation": "le riz", "partOfSpeech": "noun", "explanation": "أَرُزّ est le riz. La chadda sur ز double la lettre : ''a-ruzz. Trois blocs : أ | ر | ز. En Égypte, on dit رُزّ (ruzz).", "examples": [{"text": "أَكَلَ الْأَرُزَّ", "translation": "Il a mangé le riz.", "transliteration": "''akala l-''aruzz"}, {"text": "الْأَرُزُّ حَارٌّ", "translation": "Le riz est chaud.", "transliteration": "al-''aruzzu 7ârr"}], "unitId": "ar.v.aruzz"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.barid', 'ar', 'بَارِد', 'froid', 'بَارِد veut dire « froid » (eau, temps, boisson). Au féminin : بَارِدَة. Trois blocs : با | ر | د.', '[{"text": "الْمَاءُ بَارِدٌ", "translation": "L''eau est froide.", "transliteration": "al-mâ''u bârid"}, {"text": "هٰذَا شَايٌ بَارِدٌ", "translation": "C''est un thé froid.", "transliteration": "hâdhâ châyun bârid"}]'::jsonb, null, '{"id": "ar.d.barid", "word": "بَارِد", "transliteration": "bârid", "translation": "froid", "partOfSpeech": "adjective", "explanation": "بَارِد veut dire « froid » (eau, temps, boisson). Au féminin : بَارِدَة. Trois blocs : با | ر | د.", "examples": [{"text": "الْمَاءُ بَارِدٌ", "translation": "L''eau est froide.", "transliteration": "al-mâ''u bârid"}, {"text": "هٰذَا شَايٌ بَارِدٌ", "translation": "C''est un thé froid.", "transliteration": "hâdhâ châyun bârid"}], "confusions": [{"word": "بَرْد", "note": "bard, le froid (le nom) : pas de ا après ب."}], "forms": {"feminine": "بَارِدَة"}, "unitId": "ar.v.barid"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.harr', 'ar', 'حَارّ', 'chaud', 'حَارّ veut dire « chaud » (temps, boisson, plat) ; pour un plat, aussi « piquant ». Au féminin : حَارَّة. La chadda sur ر allonge le r : 7ârr.', '[{"text": "الشَّايُ حَارٌّ", "translation": "Le thé est chaud.", "transliteration": "ach-châyu 7ârr"}, {"text": "الصَّيْفُ حَارٌّ", "translation": "L''été est chaud.", "transliteration": "aS-Sayfu 7ârr"}]'::jsonb, null, '{"id": "ar.d.harr", "word": "حَارّ", "transliteration": "7ârr", "translation": "chaud", "otherTranslations": ["piquant (plat)"], "partOfSpeech": "adjective", "explanation": "حَارّ veut dire « chaud » (temps, boisson, plat) ; pour un plat, aussi « piquant ». Au féminin : حَارَّة. La chadda sur ر allonge le r : 7ârr.", "examples": [{"text": "الشَّايُ حَارٌّ", "translation": "Le thé est chaud.", "transliteration": "ach-châyu 7ârr"}, {"text": "الصَّيْفُ حَارٌّ", "translation": "L''été est chaud.", "transliteration": "aS-Sayfu 7ârr"}], "confusions": [{"word": "جَار", "note": "djâr, le voisin : ج a un point dedans et il n''y a pas de chadda."}], "forms": {"feminine": "حَارَّة"}, "unitId": "ar.v.harr"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.madina', 'ar', 'مَدِينَة', 'la ville', 'مَدِينَة est la ville. Deux blocs : مد | ينة, car د ne s''attache pas à la lettre suivante.', '[{"text": "هٰذِهِ مَدِينَةٌ كَبِيرَةٌ", "translation": "C''est une grande ville.", "transliteration": "hâdhihi madînatun kabîra"}, {"text": "أَنَا فِي الْمَدِينَةِ", "translation": "Je suis en ville.", "transliteration": "''anâ fî l-madîna"}]'::jsonb, null, '{"id": "ar.d.madina", "word": "مَدِينَة", "transliteration": "madîna", "translation": "la ville", "partOfSpeech": "noun", "explanation": "مَدِينَة est la ville. Deux blocs : مد | ينة, car د ne s''attache pas à la lettre suivante.", "examples": [{"text": "هٰذِهِ مَدِينَةٌ كَبِيرَةٌ", "translation": "C''est une grande ville.", "transliteration": "hâdhihi madînatun kabîra"}, {"text": "أَنَا فِي الْمَدِينَةِ", "translation": "Je suis en ville.", "transliteration": "''anâ fî l-madîna"}], "forms": {"plural": "مُدُن"}, "unitId": "ar.v.madina"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.chari', 'ar', 'شَارِع', 'la rue', 'شَارِع est la rue. Trois blocs : شا | ر | ع. Le ع final se prononce du fond de la gorge.', '[{"text": "الشَّارِعُ كَبِيرٌ", "translation": "La rue est grande.", "transliteration": "ach-châri3u kabîr"}, {"text": "السُّوقُ فِي هٰذَا الشَّارِعِ", "translation": "Le marché est dans cette rue.", "transliteration": "as-sûqu fî hâdhâ ch-châri3"}]'::jsonb, null, '{"id": "ar.d.chari", "word": "شَارِع", "transliteration": "châri3", "translation": "la rue", "partOfSpeech": "noun", "explanation": "شَارِع est la rue. Trois blocs : شا | ر | ع. Le ع final se prononce du fond de la gorge.", "examples": [{"text": "الشَّارِعُ كَبِيرٌ", "translation": "La rue est grande.", "transliteration": "ach-châri3u kabîr"}, {"text": "السُّوقُ فِي هٰذَا الشَّارِعِ", "translation": "Le marché est dans cette rue.", "transliteration": "as-sûqu fî hâdhâ ch-châri3"}], "forms": {"plural": "شَوَارِع"}, "unitId": "ar.v.chari"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ila', 'ar', 'إِلَى', 'vers, à (direction)', 'إِلَى indique la direction : on va vers un lieu. Le ى final se lit â. Deux blocs : إ | لى.', '[{"text": "ذَهَبَ إِلَى الْمَدِينَةِ", "translation": "Il est allé en ville.", "transliteration": "dhahaba ''ilâ l-madîna"}, {"text": "مِنَ الْبَيْتِ إِلَى الْمَدْرَسَةِ", "translation": "De la maison à l''école.", "transliteration": "mina l-bayti ''ilâ l-madrasa"}]'::jsonb, null, '{"id": "ar.d.ila", "word": "إِلَى", "transliteration": "''ilâ", "translation": "vers, à (direction)", "partOfSpeech": "preposition", "explanation": "إِلَى indique la direction : on va vers un lieu. Le ى final se lit â. Deux blocs : إ | لى.", "examples": [{"text": "ذَهَبَ إِلَى الْمَدِينَةِ", "translation": "Il est allé en ville.", "transliteration": "dhahaba ''ilâ l-madîna"}, {"text": "مِنَ الْبَيْتِ إِلَى الْمَدْرَسَةِ", "translation": "De la maison à l''école.", "transliteration": "mina l-bayti ''ilâ l-madrasa"}], "confusions": [{"word": "عَلَى", "note": "3alâ, sur : même finale ى, mais commence par ع."}], "unitId": "ar.v.ila"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.wa', 'ar', 'وَ', 'et', 'وَ ne s''écrit jamais seul : il se colle au mot qui suit, sans espace (وَالْجُبْنُ). Comme و ne s''attache pas à gauche, il forme un petit bloc à part.', '[{"text": "الْخُبْزُ وَالْجُبْنُ", "translation": "Le pain et le fromage.", "transliteration": "al-khubzu wa-l-djubn"}, {"text": "أَنَا وَأَنْتَ", "translation": "Moi et toi.", "transliteration": "''anâ wa-''anta"}]'::jsonb, null, '{"id": "ar.d.wa", "word": "وَ", "transliteration": "wa", "translation": "et", "partOfSpeech": "conjunction", "explanation": "وَ ne s''écrit jamais seul : il se colle au mot qui suit, sans espace (وَالْجُبْنُ). Comme و ne s''attache pas à gauche, il forme un petit bloc à part.", "examples": [{"text": "الْخُبْزُ وَالْجُبْنُ", "translation": "Le pain et le fromage.", "transliteration": "al-khubzu wa-l-djubn"}, {"text": "أَنَا وَأَنْتَ", "translation": "Moi et toi.", "transliteration": "''anâ wa-''anta"}], "unitId": "ar.v.wa"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.mustachfa', 'ar', 'مُسْتَشْفَى', 'l''hôpital', 'مُسْتَشْفَى est l''hôpital : مُسْتَـ au début et la racine ch-f-y (guérir), « le lieu où l''on se soigne ». Un seul bloc de 6 lettres : mus-tach-fâ ; le ى final se lit â.', '[{"text": "ذَهَبَ إِلَى الْمُسْتَشْفَى", "translation": "Il est allé à l''hôpital.", "transliteration": "dhahaba ''ilâ l-mustachfâ"}, {"text": "الْمُسْتَشْفَى فِي الْمَدِينَةِ", "translation": "L''hôpital est en ville.", "transliteration": "al-mustachfâ fî l-madîna"}]'::jsonb, null, '{"id": "ar.d.mustachfa", "word": "مُسْتَشْفَى", "transliteration": "mustachfâ", "translation": "l''hôpital", "partOfSpeech": "noun", "explanation": "مُسْتَشْفَى est l''hôpital : مُسْتَـ au début et la racine ch-f-y (guérir), « le lieu où l''on se soigne ». Un seul bloc de 6 lettres : mus-tach-fâ ; le ى final se lit â.", "examples": [{"text": "ذَهَبَ إِلَى الْمُسْتَشْفَى", "translation": "Il est allé à l''hôpital.", "transliteration": "dhahaba ''ilâ l-mustachfâ"}, {"text": "الْمُسْتَشْفَى فِي الْمَدِينَةِ", "translation": "L''hôpital est en ville.", "transliteration": "al-mustachfâ fî l-madîna"}], "forms": {"plural": "مُسْتَشْفَيَات"}, "unitId": "ar.v.mustachfa"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.matam', 'ar', 'مَطْعَم', 'le restaurant', 'مَطْعَم est le restaurant : مَـ (lieu) + ط ع م (la racine de « manger, goûter »). Deux syllabes fermées : maT-3am.', '[{"text": "الْمَطْعَمُ جَدِيدٌ", "translation": "Le restaurant est nouveau.", "transliteration": "al-maT3amu djadîd"}, {"text": "هُوَ فِي الْمَطْعَمِ", "translation": "Il est au restaurant.", "transliteration": "huwa fî l-maT3am"}]'::jsonb, null, '{"id": "ar.d.matam", "word": "مَطْعَم", "transliteration": "maT3am", "translation": "le restaurant", "partOfSpeech": "noun", "explanation": "مَطْعَم est le restaurant : مَـ (lieu) + ط ع م (la racine de « manger, goûter »). Deux syllabes fermées : maT-3am.", "examples": [{"text": "الْمَطْعَمُ جَدِيدٌ", "translation": "Le restaurant est nouveau.", "transliteration": "al-maT3amu djadîd"}, {"text": "هُوَ فِي الْمَطْعَمِ", "translation": "Il est au restaurant.", "transliteration": "huwa fî l-maT3am"}], "confusions": [{"word": "طَعَام", "note": "Ta3âm, la nourriture : même racine ط ع م."}], "forms": {"plural": "مَطَاعِم"}, "unitId": "ar.v.matam"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sayyara', 'ar', 'سَيَّارَة', 'la voiture', 'سَيَّارَة est la voiture. La chadda sur ي la double : say-yâ-ra. Trois blocs : سيا | ر | ة.', '[{"text": "هٰذِهِ سَيَّارَةٌ جَدِيدَةٌ", "translation": "C''est une voiture neuve.", "transliteration": "hâdhihi sayyâratun djadîda"}, {"text": "السَّيَّارَةُ فِي الشَّارِعِ", "translation": "La voiture est dans la rue.", "transliteration": "as-sayyâratu fî ch-châri3"}]'::jsonb, null, '{"id": "ar.d.sayyara", "word": "سَيَّارَة", "transliteration": "sayyâra", "translation": "la voiture", "partOfSpeech": "noun", "explanation": "سَيَّارَة est la voiture. La chadda sur ي la double : say-yâ-ra. Trois blocs : سيا | ر | ة.", "examples": [{"text": "هٰذِهِ سَيَّارَةٌ جَدِيدَةٌ", "translation": "C''est une voiture neuve.", "transliteration": "hâdhihi sayyâratun djadîda"}, {"text": "السَّيَّارَةُ فِي الشَّارِعِ", "translation": "La voiture est dans la rue.", "transliteration": "as-sayyâratu fî ch-châri3"}], "forms": {"plural": "سَيَّارَات"}, "unitId": "ar.v.sayyara"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.matar_aeroport', 'ar', 'مَطَار', 'l''aéroport', 'مَطَار est l''aéroport (de la racine « voler »). Le ا du milieu allonge la voyelle : ma-Târ. Deux blocs : مطا | ر.', '[{"text": "هٰذَا مَطَارٌ كَبِيرٌ", "translation": "C''est un grand aéroport.", "transliteration": "hâdhâ maTârun kabîr"}, {"text": "ذَهَبَ إِلَى الْمَطَارِ", "translation": "Il est allé à l''aéroport.", "transliteration": "dhahaba ''ilâ l-maTâr"}]'::jsonb, null, '{"id": "ar.d.matar_aeroport", "word": "مَطَار", "transliteration": "maTâr", "translation": "l''aéroport", "partOfSpeech": "noun", "explanation": "مَطَار est l''aéroport (de la racine « voler »). Le ا du milieu allonge la voyelle : ma-Târ. Deux blocs : مطا | ر.", "examples": [{"text": "هٰذَا مَطَارٌ كَبِيرٌ", "translation": "C''est un grand aéroport.", "transliteration": "hâdhâ maTârun kabîr"}, {"text": "ذَهَبَ إِلَى الْمَطَارِ", "translation": "Il est allé à l''aéroport.", "transliteration": "dhahaba ''ilâ l-maTâr"}], "confusions": [{"word": "مَطَر", "note": "maTar, la pluie : pas de ا, voyelle brève."}], "forms": {"plural": "مَطَارَات"}, "unitId": "ar.v.matar_aeroport"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.burtuqal', 'ar', 'بُرْتُقَال', 'l''orange (le fruit)', 'بُرْتُقَال désigne les oranges, le fruit en général ; une seule orange se dit بُرْتُقَالَة. Trois blocs : بر | تقا | ل.', '[{"text": "أَكَلَ الْبُرْتُقَالَ", "translation": "Il a mangé les oranges.", "transliteration": "''akala l-burtuqâl"}, {"text": "الْبُرْتُقَالُ مِنَ السُّوقِ", "translation": "Les oranges viennent du marché.", "transliteration": "al-burtuqâlu mina s-sûq"}]'::jsonb, null, '{"id": "ar.d.burtuqal", "word": "بُرْتُقَال", "transliteration": "burtuqâl", "translation": "l''orange (le fruit)", "partOfSpeech": "noun", "explanation": "بُرْتُقَال désigne les oranges, le fruit en général ; une seule orange se dit بُرْتُقَالَة. Trois blocs : بر | تقا | ل.", "examples": [{"text": "أَكَلَ الْبُرْتُقَالَ", "translation": "Il a mangé les oranges.", "transliteration": "''akala l-burtuqâl"}, {"text": "الْبُرْتُقَالُ مِنَ السُّوقِ", "translation": "Les oranges viennent du marché.", "transliteration": "al-burtuqâlu mina s-sûq"}], "forms": {"singular": "بُرْتُقَالَة"}, "unitId": "ar.v.burtuqal"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.tuffaha', 'ar', 'تُفَّاحَة', 'la pomme', 'تُفَّاحَة est une pomme ; les pommes en général se disent تُفَّاح. Deux blocs : تفا | حة. La chadda double le f : tuf-fâ-7a.', '[{"text": "هٰذِهِ تُفَّاحَةٌ كَبِيرَةٌ", "translation": "C''est une grosse pomme.", "transliteration": "hâdhihi tuffâ7atun kabîra"}, {"text": "أَكَلَ تُفَّاحَةً", "translation": "Il a mangé une pomme.", "transliteration": "''akala tuffâ7a"}]'::jsonb, null, '{"id": "ar.d.tuffaha", "word": "تُفَّاحَة", "transliteration": "tuffâ7a", "translation": "la pomme", "partOfSpeech": "noun", "explanation": "تُفَّاحَة est une pomme ; les pommes en général se disent تُفَّاح. Deux blocs : تفا | حة. La chadda double le f : tuf-fâ-7a.", "examples": [{"text": "هٰذِهِ تُفَّاحَةٌ كَبِيرَةٌ", "translation": "C''est une grosse pomme.", "transliteration": "hâdhihi tuffâ7atun kabîra"}, {"text": "أَكَلَ تُفَّاحَةً", "translation": "Il a mangé une pomme.", "transliteration": "''akala tuffâ7a"}], "forms": {"collective": "تُفَّاح"}, "unitId": "ar.v.tuffaha"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sabah', 'ar', 'صَبَاح', 'le matin', 'صَبَاح est le matin. On l''entend dans la salutation صَبَاحُ الْخَيْرِ (bonjour, le matin). Deux blocs : صبا | ح.', '[{"text": "صَبَاحُ الْخَيْرِ", "translation": "Bonjour (le matin).", "transliteration": "Sabâ7u l-khayr"}, {"text": "شَرِبَ الْقَهْوَةَ فِي الصَّبَاحِ", "translation": "Il a bu le café le matin.", "transliteration": "chariba l-qahwata fî S-Sabâ7"}]'::jsonb, null, '{"id": "ar.d.sabah", "word": "صَبَاح", "transliteration": "Sabâ7", "translation": "le matin", "partOfSpeech": "noun", "explanation": "صَبَاح est le matin. On l''entend dans la salutation صَبَاحُ الْخَيْرِ (bonjour, le matin). Deux blocs : صبا | ح.", "examples": [{"text": "صَبَاحُ الْخَيْرِ", "translation": "Bonjour (le matin).", "transliteration": "Sabâ7u l-khayr"}, {"text": "شَرِبَ الْقَهْوَةَ فِي الصَّبَاحِ", "translation": "Il a bu le café le matin.", "transliteration": "chariba l-qahwata fî S-Sabâ7"}], "unitId": "ar.v.sabah"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.masa', 'ar', 'مَسَاء', 'le soir', 'مَسَاء est le soir : مَسَاءُ الْخَيْرِ veut dire « bonsoir ». La hamza finale ء, seule sur la ligne, ne s''attache à rien : مسا | ء.', '[{"text": "مَسَاءُ الْخَيْرِ", "translation": "Bonsoir.", "transliteration": "masâ''u l-khayr"}, {"text": "الْمَسَاءُ بَارِدٌ", "translation": "La soirée est froide.", "transliteration": "al-masâ''u bârid"}]'::jsonb, null, '{"id": "ar.d.masa", "word": "مَسَاء", "transliteration": "masâ''", "translation": "le soir", "partOfSpeech": "noun", "explanation": "مَسَاء est le soir : مَسَاءُ الْخَيْرِ veut dire « bonsoir ». La hamza finale ء, seule sur la ligne, ne s''attache à rien : مسا | ء.", "examples": [{"text": "مَسَاءُ الْخَيْرِ", "translation": "Bonsoir.", "transliteration": "masâ''u l-khayr"}, {"text": "الْمَسَاءُ بَارِدٌ", "translation": "La soirée est froide.", "transliteration": "al-masâ''u bârid"}], "unitId": "ar.v.masa"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ala', 'ar', 'عَلَى', 'sur', 'عَلَى veut dire « sur ». Un seul bloc ; le ى final se lit â, comme un alif.', '[{"text": "الشَّايُ عَلَى الْمَكْتَبِ", "translation": "Le thé est sur le bureau.", "transliteration": "ach-châyu 3alâ l-maktab"}, {"text": "جَلَسَ عَلَى الْأَرْضِ", "translation": "Il s''est assis par terre.", "transliteration": "djalasa 3alâ l-''arD"}]'::jsonb, null, '{"id": "ar.d.ala", "word": "عَلَى", "transliteration": "3alâ", "translation": "sur", "partOfSpeech": "preposition", "explanation": "عَلَى veut dire « sur ». Un seul bloc ; le ى final se lit â, comme un alif.", "examples": [{"text": "الشَّايُ عَلَى الْمَكْتَبِ", "translation": "Le thé est sur le bureau.", "transliteration": "ach-châyu 3alâ l-maktab"}, {"text": "جَلَسَ عَلَى الْأَرْضِ", "translation": "Il s''est assis par terre.", "transliteration": "djalasa 3alâ l-''arD"}], "confusions": [{"word": "إِلَى", "note": "''ilâ, vers : même finale ى, mais commence par إ."}], "unitId": "ar.v.ala"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kabir', 'ar', 'كَبِير', 'grand', 'كَبِير veut dire « grand » (taille, âge, importance). Au féminin : كَبِيرَة. Un seul bloc : ka-bîr.', '[{"text": "الْبَيْتُ كَبِيرٌ", "translation": "La maison est grande.", "transliteration": "al-baytu kabîr"}, {"text": "هٰذَا جَبَلٌ كَبِيرٌ", "translation": "C''est une grande montagne.", "transliteration": "hâdhâ djabalun kabîr"}]'::jsonb, null, '{"id": "ar.d.kabir", "word": "كَبِير", "transliteration": "kabîr", "translation": "grand", "otherTranslations": ["gros", "âgé"], "partOfSpeech": "adjective", "explanation": "كَبِير veut dire « grand » (taille, âge, importance). Au féminin : كَبِيرَة. Un seul bloc : ka-bîr.", "examples": [{"text": "الْبَيْتُ كَبِيرٌ", "translation": "La maison est grande.", "transliteration": "al-baytu kabîr"}, {"text": "هٰذَا جَبَلٌ كَبِيرٌ", "translation": "C''est une grande montagne.", "transliteration": "hâdhâ djabalun kabîr"}], "confusions": [{"word": "صَغِير", "note": "Saghîr, petit : le contraire."}], "forms": {"feminine": "كَبِيرَة", "plural": "كِبَار"}, "unitId": "ar.v.kabir"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.khubz', 'ar', 'خُبْز', 'le pain', 'خُبْز est le pain. خ a un point au-dessus (kh) ; une seule syllabe fermée : khubz.', '[{"text": "الْخُبْزُ حَارٌّ", "translation": "Le pain est chaud.", "transliteration": "al-khubzu 7ârr"}, {"text": "أَكَلَ الْخُبْزَ وَالْجُبْنَ", "translation": "Il a mangé le pain et le fromage.", "transliteration": "''akala l-khubza wa-l-djubn"}]'::jsonb, null, '{"id": "ar.d.khubz", "word": "خُبْز", "transliteration": "khubz", "translation": "le pain", "partOfSpeech": "noun", "explanation": "خُبْز est le pain. خ a un point au-dessus (kh) ; une seule syllabe fermée : khubz.", "examples": [{"text": "الْخُبْزُ حَارٌّ", "translation": "Le pain est chaud.", "transliteration": "al-khubzu 7ârr"}, {"text": "أَكَلَ الْخُبْزَ وَالْجُبْنَ", "translation": "Il a mangé le pain et le fromage.", "transliteration": "''akala l-khubza wa-l-djubn"}], "confusions": [{"word": "جُبْن", "note": "djubn, le fromage : ج (point dedans) au début et ن à la fin."}], "unitId": "ar.v.khubz"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.djubn', 'ar', 'جُبْن', 'le fromage', 'جُبْن est le fromage. En Égypte, on dit جِبْنَة (gibna). Ne le confonds pas avec خُبْز : la silhouette est proche.', '[{"text": "الْجُبْنُ مِنَ السُّوقِ", "translation": "Le fromage vient du marché.", "transliteration": "al-djubnu mina s-sûq"}, {"text": "أَكَلَ الْجُبْنَ فِي الصَّبَاحِ", "translation": "Il a mangé le fromage le matin.", "transliteration": "''akala l-djubna fî S-Sabâ7"}]'::jsonb, null, '{"id": "ar.d.djubn", "word": "جُبْن", "transliteration": "djubn", "translation": "le fromage", "partOfSpeech": "noun", "explanation": "جُبْن est le fromage. En Égypte, on dit جِبْنَة (gibna). Ne le confonds pas avec خُبْز : la silhouette est proche.", "examples": [{"text": "الْجُبْنُ مِنَ السُّوقِ", "translation": "Le fromage vient du marché.", "transliteration": "al-djubnu mina s-sûq"}, {"text": "أَكَلَ الْجُبْنَ فِي الصَّبَاحِ", "translation": "Il a mangé le fromage le matin.", "transliteration": "''akala l-djubna fî S-Sabâ7"}], "confusions": [{"word": "خُبْز", "note": "khubz, le pain : خ (point dessus) au début et ز à la fin."}], "unitId": "ar.v.djubn"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.halib', 'ar', 'حَلِيب', 'le lait', 'حَلِيب est le lait. Le ح n''a aucun point : 7a-lîb. En Égypte, on dit plutôt لَبَن (laban).', '[{"text": "شَرِبَ الْحَلِيبَ", "translation": "Il a bu le lait.", "transliteration": "chariba l-7alîb"}, {"text": "الْحَلِيبُ بَارِدٌ", "translation": "Le lait est froid.", "transliteration": "al-7alîbu bârid"}]'::jsonb, null, '{"id": "ar.d.halib", "word": "حَلِيب", "transliteration": "7alîb", "translation": "le lait", "partOfSpeech": "noun", "explanation": "حَلِيب est le lait. Le ح n''a aucun point : 7a-lîb. En Égypte, on dit plutôt لَبَن (laban).", "examples": [{"text": "شَرِبَ الْحَلِيبَ", "translation": "Il a bu le lait.", "transliteration": "chariba l-7alîb"}, {"text": "الْحَلِيبُ بَارِدٌ", "translation": "Le lait est froid.", "transliteration": "al-7alîbu bârid"}], "confusions": [{"word": "خَلِيج", "note": "khalîdj, le golfe : خ a un point au-dessus."}], "unitId": "ar.v.halib"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sayf', 'ar', 'صَيْف', 'l''été', 'صَيْف est l''été. ص n''a pas de point ; avec un point (ض), le mot devient ضَيْف, l''invité.', '[{"text": "الْبَحْرُ جَمِيلٌ فِي الصَّيْفِ", "translation": "La mer est belle en été.", "transliteration": "al-ba7ru djamîlun fî S-Sayf"}, {"text": "الشَّمْسُ حَارَّةٌ فِي الصَّيْفِ", "translation": "Le soleil est chaud en été.", "transliteration": "ach-chamsu 7ârratun fî S-Sayf"}]'::jsonb, null, '{"id": "ar.d.sayf", "word": "صَيْف", "transliteration": "Sayf", "translation": "l''été", "partOfSpeech": "noun", "explanation": "صَيْف est l''été. ص n''a pas de point ; avec un point (ض), le mot devient ضَيْف, l''invité.", "examples": [{"text": "الْبَحْرُ جَمِيلٌ فِي الصَّيْفِ", "translation": "La mer est belle en été.", "transliteration": "al-ba7ru djamîlun fî S-Sayf"}, {"text": "الشَّمْسُ حَارَّةٌ فِي الصَّيْفِ", "translation": "Le soleil est chaud en été.", "transliteration": "ach-chamsu 7ârratun fî S-Sayf"}], "confusions": [{"word": "ضَيْف", "note": "Dayf, l''invité : un seul point sur ض change tout le mot."}], "unitId": "ar.v.sayf"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.thaldj', 'ar', 'ثَلْج', 'la neige', 'ثَلْج est la neige, et aussi la glace (les glaçons). ث porte 3 points : th, comme dans l''anglais « think ».', '[{"text": "الثَّلْجُ بَارِدٌ", "translation": "La neige est froide.", "transliteration": "ath-thaldju bârid"}, {"text": "لَا ثَلْجَ فِي الْمَدِينَةِ", "translation": "Il n''y a pas de neige en ville.", "transliteration": "lâ thaldja fî l-madîna"}]'::jsonb, null, '{"id": "ar.d.thaldj", "word": "ثَلْج", "transliteration": "thaldj", "translation": "la neige", "otherTranslations": ["la glace (glaçons)"], "partOfSpeech": "noun", "explanation": "ثَلْج est la neige, et aussi la glace (les glaçons). ث porte 3 points : th, comme dans l''anglais « think ».", "examples": [{"text": "الثَّلْجُ بَارِدٌ", "translation": "La neige est froide.", "transliteration": "ath-thaldju bârid"}, {"text": "لَا ثَلْجَ فِي الْمَدِينَةِ", "translation": "Il n''y a pas de neige en ville.", "transliteration": "lâ thaldja fî l-madîna"}], "unitId": "ar.v.thaldj"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.chay', 'ar', 'شَاي', 'le thé', 'شَاي est le thé. ش a 3 points (ch) ; deux blocs : شا | ي.', '[{"text": "هٰذَا شَايٌ حَارٌّ", "translation": "C''est un thé chaud.", "transliteration": "hâdhâ châyun 7ârr"}, {"text": "الشَّايُ مَعَ الْحَلِيبِ", "translation": "Le thé au lait.", "transliteration": "ach-châyu ma3a l-7alîb"}]'::jsonb, null, '{"id": "ar.d.chay", "word": "شَاي", "transliteration": "chây", "translation": "le thé", "partOfSpeech": "noun", "explanation": "شَاي est le thé. ش a 3 points (ch) ; deux blocs : شا | ي.", "examples": [{"text": "هٰذَا شَايٌ حَارٌّ", "translation": "C''est un thé chaud.", "transliteration": "hâdhâ châyun 7ârr"}, {"text": "الشَّايُ مَعَ الْحَلِيبِ", "translation": "Le thé au lait.", "transliteration": "ach-châyu ma3a l-7alîb"}], "confusions": [{"word": "سَاعَة", "note": "sâ3a, l''heure, la montre : س n''a pas de points."}], "unitId": "ar.v.chay"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bayd', 'ar', 'بَيْض', 'les œufs', 'بَيْض désigne les œufs en général ; un œuf se dit بَيْضَة. La dernière lettre est ض (D emphatique).', '[{"text": "أَكَلَ الْبَيْضَ", "translation": "Il a mangé les œufs.", "transliteration": "''akala l-bayD"}, {"text": "الْبَيْضُ مِنَ السُّوقِ", "translation": "Les œufs viennent du marché.", "transliteration": "al-bayDu mina s-sûq"}]'::jsonb, null, '{"id": "ar.d.bayd", "word": "بَيْض", "transliteration": "bayD", "translation": "les œufs", "partOfSpeech": "noun", "explanation": "بَيْض désigne les œufs en général ; un œuf se dit بَيْضَة. La dernière lettre est ض (D emphatique).", "examples": [{"text": "أَكَلَ الْبَيْضَ", "translation": "Il a mangé les œufs.", "transliteration": "''akala l-bayD"}, {"text": "الْبَيْضُ مِنَ السُّوقِ", "translation": "Les œufs viennent du marché.", "transliteration": "al-bayDu mina s-sûq"}], "confusions": [{"word": "بَيْت", "note": "bayt, la maison : ت (2 points) à la fin au lieu de ض."}], "forms": {"singular": "بَيْضَة"}, "unitId": "ar.v.bayd"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.suq', 'ar', 'سُوق', 'le marché', 'سُوق est le marché. Avec l''article, le ل ne se prononce pas devant س : السُّوق = as-sûq. Deux blocs : سو | ق.', '[{"text": "أَنَا فِي السُّوقِ", "translation": "Je suis au marché.", "transliteration": "''anâ fî s-sûq"}, {"text": "السُّوقُ فِي الْمَدِينَةِ", "translation": "Le marché est en ville.", "transliteration": "as-sûqu fî l-madîna"}]'::jsonb, null, '{"id": "ar.d.suq", "word": "سُوق", "transliteration": "sûq", "translation": "le marché", "partOfSpeech": "noun", "explanation": "سُوق est le marché. Avec l''article, le ل ne se prononce pas devant س : السُّوق = as-sûq. Deux blocs : سو | ق.", "examples": [{"text": "أَنَا فِي السُّوقِ", "translation": "Je suis au marché.", "transliteration": "''anâ fî s-sûq"}, {"text": "السُّوقُ فِي الْمَدِينَةِ", "translation": "Le marché est en ville.", "transliteration": "as-sûqu fî l-madîna"}], "forms": {"plural": "أَسْوَاق"}, "unitId": "ar.v.suq"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.saghir', 'ar', 'صَغِير', 'petit', 'صَغِير veut dire « petit ». Au féminin : صَغِيرَة. Attention au غ (point dessus, gh) : Sa-ghîr.', '[{"text": "هٰذِهِ وَرْدَةٌ صَغِيرَةٌ", "translation": "C''est une petite rose.", "transliteration": "hâdhihi wardatun Saghîra"}, {"text": "الْمَطْعَمُ صَغِيرٌ", "translation": "Le restaurant est petit.", "transliteration": "al-maT3amu Saghîr"}]'::jsonb, null, '{"id": "ar.d.saghir", "word": "صَغِير", "transliteration": "Saghîr", "translation": "petit", "partOfSpeech": "adjective", "explanation": "صَغِير veut dire « petit ». Au féminin : صَغِيرَة. Attention au غ (point dessus, gh) : Sa-ghîr.", "examples": [{"text": "هٰذِهِ وَرْدَةٌ صَغِيرَةٌ", "translation": "C''est une petite rose.", "transliteration": "hâdhihi wardatun Saghîra"}, {"text": "الْمَطْعَمُ صَغِيرٌ", "translation": "Le restaurant est petit.", "transliteration": "al-maT3amu Saghîr"}], "confusions": [{"word": "كَبِير", "note": "kabîr, grand : le contraire."}], "forms": {"feminine": "صَغِيرَة", "plural": "صِغَار"}, "unitId": "ar.v.saghir"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.hadha', 'ar', 'هٰذَا', 'ceci, celui-ci (masculin)', 'هٰذَا montre une chose ou une personne au masculin : « ceci, c''est, ce… ». Le petit alif vertical sur ه se lit â : hâ-dhâ.', '[{"text": "هٰذَا مَطْعَمٌ جَدِيدٌ", "translation": "C''est un nouveau restaurant.", "transliteration": "hâdhâ maT3amun djadîd"}, {"text": "هٰذَا الشَّارِعُ كَبِيرٌ", "translation": "Cette rue est grande.", "transliteration": "hâdhâ ch-châri3u kabîr"}]'::jsonb, null, '{"id": "ar.d.hadha", "word": "هٰذَا", "transliteration": "hâdhâ", "translation": "ceci, celui-ci (masculin)", "otherTranslations": ["c''est", "ce, cet"], "partOfSpeech": "pronoun", "explanation": "هٰذَا montre une chose ou une personne au masculin : « ceci, c''est, ce… ». Le petit alif vertical sur ه se lit â : hâ-dhâ.", "examples": [{"text": "هٰذَا مَطْعَمٌ جَدِيدٌ", "translation": "C''est un nouveau restaurant.", "transliteration": "hâdhâ maT3amun djadîd"}, {"text": "هٰذَا الشَّارِعُ كَبِيرٌ", "translation": "Cette rue est grande.", "transliteration": "hâdhâ ch-châri3u kabîr"}], "confusions": [{"word": "هٰذِهِ", "note": "hâdhihi, la forme féminine."}], "forms": {"feminine": "هٰذِهِ"}, "unitId": "ar.v.hadha"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.hadhihi', 'ar', 'هٰذِهِ', 'ceci, celle-ci (féminin)', 'هٰذِهِ est le féminin de هٰذَا : on l''emploie devant les noms féminins, souvent terminés par ـة.', '[{"text": "هٰذِهِ سَيَّارَةٌ", "translation": "C''est une voiture.", "transliteration": "hâdhihi sayyâra"}, {"text": "هٰذِهِ الْمَدِينَةُ جَمِيلَةٌ", "translation": "Cette ville est belle.", "transliteration": "hâdhihi l-madînatu djamîla"}]'::jsonb, null, '{"id": "ar.d.hadhihi", "word": "هٰذِهِ", "transliteration": "hâdhihi", "translation": "ceci, celle-ci (féminin)", "otherTranslations": ["c''est", "cette"], "partOfSpeech": "pronoun", "explanation": "هٰذِهِ est le féminin de هٰذَا : on l''emploie devant les noms féminins, souvent terminés par ـة.", "examples": [{"text": "هٰذِهِ سَيَّارَةٌ", "translation": "C''est une voiture.", "transliteration": "hâdhihi sayyâra"}, {"text": "هٰذِهِ الْمَدِينَةُ جَمِيلَةٌ", "translation": "Cette ville est belle.", "transliteration": "hâdhihi l-madînatu djamîla"}], "confusions": [{"word": "هٰذَا", "note": "hâdhâ, la forme masculine."}], "unitId": "ar.v.hadhihi"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.huwa', 'ar', 'هُوَ', 'il, lui', 'هُوَ veut dire « il, lui » ; il remplace aussi une chose masculine (le livre → هُوَ). Le و porte une fatha : hu-wa.', '[{"text": "هُوَ فِي الْمَطَارِ", "translation": "Il est à l''aéroport.", "transliteration": "huwa fî l-maTâr"}, {"text": "هُوَ مِنَ الْمَدِينَةِ", "translation": "Il est de la ville.", "transliteration": "huwa mina l-madîna"}]'::jsonb, null, '{"id": "ar.d.huwa", "word": "هُوَ", "transliteration": "huwa", "translation": "il, lui", "partOfSpeech": "pronoun", "explanation": "هُوَ veut dire « il, lui » ; il remplace aussi une chose masculine (le livre → هُوَ). Le و porte une fatha : hu-wa.", "examples": [{"text": "هُوَ فِي الْمَطَارِ", "translation": "Il est à l''aéroport.", "transliteration": "huwa fî l-maTâr"}, {"text": "هُوَ مِنَ الْمَدِينَةِ", "translation": "Il est de la ville.", "transliteration": "huwa mina l-madîna"}], "confusions": [{"word": "هِيَ", "note": "hiya, elle : kasra sous ه et ي au lieu de و."}], "unitId": "ar.v.huwa"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.hiya', 'ar', 'هِيَ', 'elle', 'هِيَ veut dire « elle » ; elle remplace aussi une chose féminine (la voiture → هِيَ). Kasra sous ه, fatha sur ي : hi-ya.', '[{"text": "هِيَ فِي الْمَدْرَسَةِ", "translation": "Elle est à l''école.", "transliteration": "hiya fî l-madrasa"}, {"text": "هِيَ مِنْ مِصْرَ", "translation": "Elle est d''Égypte.", "transliteration": "hiya min miSr"}]'::jsonb, null, '{"id": "ar.d.hiya", "word": "هِيَ", "transliteration": "hiya", "translation": "elle", "partOfSpeech": "pronoun", "explanation": "هِيَ veut dire « elle » ; elle remplace aussi une chose féminine (la voiture → هِيَ). Kasra sous ه, fatha sur ي : hi-ya.", "examples": [{"text": "هِيَ فِي الْمَدْرَسَةِ", "translation": "Elle est à l''école.", "transliteration": "hiya fî l-madrasa"}, {"text": "هِيَ مِنْ مِصْرَ", "translation": "Elle est d''Égypte.", "transliteration": "hiya min miSr"}], "confusions": [{"word": "هُوَ", "note": "huwa, il : damma sur ه et و au lieu de ي."}], "unitId": "ar.v.hiya"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ana', 'ar', 'أَنَا', 'je, moi', 'أَنَا veut dire « je, moi ». Le ا final s''écrit, mais on le prononce souvent bref : ''ana. Deux blocs : أ | نا.', '[{"text": "أَنَا هُنَا", "translation": "Je suis ici.", "transliteration": "''anâ hunâ"}, {"text": "أَنَا مِنْ مِصْرَ", "translation": "Je suis d''Égypte.", "transliteration": "''anâ min miSr"}]'::jsonb, null, '{"id": "ar.d.ana", "word": "أَنَا", "transliteration": "''anâ", "translation": "je, moi", "partOfSpeech": "pronoun", "explanation": "أَنَا veut dire « je, moi ». Le ا final s''écrit, mais on le prononce souvent bref : ''ana. Deux blocs : أ | نا.", "examples": [{"text": "أَنَا هُنَا", "translation": "Je suis ici.", "transliteration": "''anâ hunâ"}, {"text": "أَنَا مِنْ مِصْرَ", "translation": "Je suis d''Égypte.", "transliteration": "''anâ min miSr"}], "confusions": [{"word": "أَنْتَ", "note": "''anta, tu : un ت en plus."}], "unitId": "ar.v.ana"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.anta', 'ar', 'أَنْتَ', 'tu, toi (masculin)', 'أَنْتَ veut dire « tu, toi » quand on parle à un homme. À une femme, on dit أَنْتِ (''anti), avec une kasra.', '[{"text": "أَنْتَ فِي الْبَيْتِ", "translation": "Tu es à la maison.", "transliteration": "''anta fî l-bayt"}, {"text": "أَنْتَ فِي الْمَطْعَمِ", "translation": "Tu es au restaurant.", "transliteration": "''anta fî l-maT3am"}]'::jsonb, null, '{"id": "ar.d.anta", "word": "أَنْتَ", "transliteration": "''anta", "translation": "tu, toi (masculin)", "partOfSpeech": "pronoun", "explanation": "أَنْتَ veut dire « tu, toi » quand on parle à un homme. À une femme, on dit أَنْتِ (''anti), avec une kasra.", "examples": [{"text": "أَنْتَ فِي الْبَيْتِ", "translation": "Tu es à la maison.", "transliteration": "''anta fî l-bayt"}, {"text": "أَنْتَ فِي الْمَطْعَمِ", "translation": "Tu es au restaurant.", "transliteration": "''anta fî l-maT3am"}], "confusions": [{"word": "أَنَا", "note": "''anâ, je : pas de ت."}], "forms": {"feminine": "أَنْتِ"}, "unitId": "ar.v.anta"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.la', 'ar', 'لَا', 'non ; ne… pas', 'لَا veut dire « non », et aussi « ne… pas » ou « il n''y a pas de ». Il s''écrit avec une ligature : ل et ا collés en un seul signe.', '[{"text": "لَا، أَنَا فِي الْبَيْتِ", "translation": "Non, je suis à la maison.", "transliteration": "lâ, ''anâ fî l-bayt"}, {"text": "لَا ثَلْجَ الْيَوْمَ", "translation": "Il n''y a pas de neige aujourd''hui.", "transliteration": "lâ thaldja l-yawm"}]'::jsonb, null, '{"id": "ar.d.la", "word": "لَا", "transliteration": "lâ", "translation": "non ; ne… pas", "otherTranslations": ["ne… pas", "il n''y a pas de"], "partOfSpeech": "particle", "explanation": "لَا veut dire « non », et aussi « ne… pas » ou « il n''y a pas de ». Il s''écrit avec une ligature : ل et ا collés en un seul signe.", "examples": [{"text": "لَا، أَنَا فِي الْبَيْتِ", "translation": "Non, je suis à la maison.", "transliteration": "lâ, ''anâ fî l-bayt"}, {"text": "لَا ثَلْجَ الْيَوْمَ", "translation": "Il n''y a pas de neige aujourd''hui.", "transliteration": "lâ thaldja l-yawm"}], "unitId": "ar.v.la"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.naam', 'ar', 'نَعَمْ', 'oui', 'نَعَمْ veut dire « oui ». Une syllabe ouverte puis une fermée : na-3am. En Égypte, on dit souvent أَيْوَه (aywa).', '[{"text": "نَعَمْ، هُوَ هُنَا", "translation": "Oui, il est ici.", "transliteration": "na3am, huwa hunâ"}, {"text": "نَعَمْ، أَنَا مِنْ مِصْرَ", "translation": "Oui, je suis d''Égypte.", "transliteration": "na3am, ''anâ min miSr"}]'::jsonb, null, '{"id": "ar.d.naam", "word": "نَعَمْ", "transliteration": "na3am", "translation": "oui", "partOfSpeech": "particle", "explanation": "نَعَمْ veut dire « oui ». Une syllabe ouverte puis une fermée : na-3am. En Égypte, on dit souvent أَيْوَه (aywa).", "examples": [{"text": "نَعَمْ، هُوَ هُنَا", "translation": "Oui, il est ici.", "transliteration": "na3am, huwa hunâ"}, {"text": "نَعَمْ، أَنَا مِنْ مِصْرَ", "translation": "Oui, je suis d''Égypte.", "transliteration": "na3am, ''anâ min miSr"}], "unitId": "ar.v.naam"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.maa_avec', 'ar', 'مَعَ', 'avec', 'مَعَ veut dire « avec ». Le nom qui suit finit par une kasra : مَعَ الْحَلِيبِ.', '[{"text": "أَنَا مَعَ سَامِي", "translation": "Je suis avec Sami.", "transliteration": "''anâ ma3a sâmî"}, {"text": "أَكَلَ الْخُبْزَ مَعَ الْجُبْنِ", "translation": "Il a mangé le pain avec le fromage.", "transliteration": "''akala l-khubza ma3a l-djubn"}]'::jsonb, null, '{"id": "ar.d.maa_avec", "word": "مَعَ", "transliteration": "ma3a", "translation": "avec", "partOfSpeech": "preposition", "explanation": "مَعَ veut dire « avec ». Le nom qui suit finit par une kasra : مَعَ الْحَلِيبِ.", "examples": [{"text": "أَنَا مَعَ سَامِي", "translation": "Je suis avec Sami.", "transliteration": "''anâ ma3a sâmî"}, {"text": "أَكَلَ الْخُبْزَ مَعَ الْجُبْنِ", "translation": "Il a mangé le pain avec le fromage.", "transliteration": "''akala l-khubza ma3a l-djubn"}], "unitId": "ar.v.maa_avec"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.huna', 'ar', 'هُنَا', 'ici', 'هُنَا veut dire « ici ». Un seul bloc, deux syllabes ouvertes : hu-nâ.', '[{"text": "الْمَطْعَمُ هُنَا", "translation": "Le restaurant est ici.", "transliteration": "al-maT3amu hunâ"}, {"text": "السُّوقُ هُنَا", "translation": "Le marché est ici.", "transliteration": "as-sûqu hunâ"}]'::jsonb, null, '{"id": "ar.d.huna", "word": "هُنَا", "transliteration": "hunâ", "translation": "ici", "partOfSpeech": "adverb", "explanation": "هُنَا veut dire « ici ». Un seul bloc, deux syllabes ouvertes : hu-nâ.", "examples": [{"text": "الْمَطْعَمُ هُنَا", "translation": "Le restaurant est ici.", "transliteration": "al-maT3amu hunâ"}, {"text": "السُّوقُ هُنَا", "translation": "Le marché est ici.", "transliteration": "as-sûqu hunâ"}], "confusions": [{"word": "هُنَاكَ", "note": "hunâka, là-bas : avec ك à la fin."}], "unitId": "ar.v.huna"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kana', 'ar', 'كَانَ', 'être (il était)', 'كَانَ veut dire « il était, il a été » : c''est le verbe « être » au passé (au présent, on ne l''écrit pas). L''adjectif qui suit prend souvent ـًا (-an) : كَانَ حَارًّا. Deux blocs : كا | ن.', '[{"text": "كَانَ الشَّايُ حَارًّا", "translation": "Le thé était chaud.", "transliteration": "kâna ch-châyu 7ârrâ"}, {"text": "كَانَ فِي الْمَدْرَسَةِ", "translation": "Il était à l''école.", "transliteration": "kâna fî l-madrasa"}]'::jsonb, null, '{"id": "ar.d.kana", "word": "كَانَ", "transliteration": "kâna", "translation": "être (il était)", "partOfSpeech": "verb", "explanation": "كَانَ veut dire « il était, il a été » : c''est le verbe « être » au passé (au présent, on ne l''écrit pas). L''adjectif qui suit prend souvent ـًا (-an) : كَانَ حَارًّا. Deux blocs : كا | ن.", "examples": [{"text": "كَانَ الشَّايُ حَارًّا", "translation": "Le thé était chaud.", "transliteration": "kâna ch-châyu 7ârrâ"}, {"text": "كَانَ فِي الْمَدْرَسَةِ", "translation": "Il était à l''école.", "transliteration": "kâna fî l-madrasa"}], "forms": {"present": "يَكُونُ"}, "unitId": "ar.v.kana"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.alladhi', 'ar', 'الَّذِي', 'qui, que (masculin)', 'الَّذِي relie un nom masculin à la suite de la phrase : « qui, que ». Au féminin : الَّتِي. On l''écrit avec un seul ل portant une chadda : (a)l-ladhî.', '[{"text": "الْكِتَابُ الَّذِي عَلَى الْمَكْتَبِ جَدِيدٌ", "translation": "Le livre qui est sur le bureau est nouveau.", "transliteration": "al-kitâbu lladhî 3alâ l-maktabi djadîd"}, {"text": "الشَّايُ الَّذِي هُنَا بَارِدٌ", "translation": "Le thé qui est ici est froid.", "transliteration": "ach-châyu lladhî hunâ bârid"}]'::jsonb, null, '{"id": "ar.d.alladhi", "word": "الَّذِي", "transliteration": "alladhî", "translation": "qui, que (masculin)", "partOfSpeech": "pronoun", "explanation": "الَّذِي relie un nom masculin à la suite de la phrase : « qui, que ». Au féminin : الَّتِي. On l''écrit avec un seul ل portant une chadda : (a)l-ladhî.", "examples": [{"text": "الْكِتَابُ الَّذِي عَلَى الْمَكْتَبِ جَدِيدٌ", "translation": "Le livre qui est sur le bureau est nouveau.", "transliteration": "al-kitâbu lladhî 3alâ l-maktabi djadîd"}, {"text": "الشَّايُ الَّذِي هُنَا بَارِدٌ", "translation": "Le thé qui est ici est froid.", "transliteration": "ach-châyu lladhî hunâ bârid"}], "forms": {"feminine": "الَّتِي"}, "unitId": "ar.v.alladhi"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.al_yawm', 'ar', 'الْيَوْم', 'aujourd''hui', 'الْيَوْمَ (avec une fatha finale dans la phrase) veut dire « aujourd''hui » ; mot à mot « le jour ». Trois blocs : ا | ليو | م.', '[{"text": "الْيَوْمَ أَنَا فِي الْبَيْتِ", "translation": "Aujourd''hui, je suis à la maison.", "transliteration": "al-yawma ''anâ fî l-bayt"}, {"text": "ذَهَبَ إِلَى الْمَدِينَةِ الْيَوْمَ", "translation": "Il est allé en ville aujourd''hui.", "transliteration": "dhahaba ''ilâ l-madînati l-yawm"}]'::jsonb, null, '{"id": "ar.d.al_yawm", "word": "الْيَوْم", "transliteration": "al-yawm", "translation": "aujourd''hui", "otherTranslations": ["le jour"], "partOfSpeech": "adverb", "explanation": "الْيَوْمَ (avec une fatha finale dans la phrase) veut dire « aujourd''hui » ; mot à mot « le jour ». Trois blocs : ا | ليو | م.", "examples": [{"text": "الْيَوْمَ أَنَا فِي الْبَيْتِ", "translation": "Aujourd''hui, je suis à la maison.", "transliteration": "al-yawma ''anâ fî l-bayt"}, {"text": "ذَهَبَ إِلَى الْمَدِينَةِ الْيَوْمَ", "translation": "Il est allé en ville aujourd''hui.", "transliteration": "dhahaba ''ilâ l-madînati l-yawm"}], "confusions": [{"word": "يَوْم", "note": "yawm, un jour (sans l''article)."}], "unitId": "ar.v.al_yawm"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.djamil', 'ar', 'جَمِيل', 'beau, joli', 'جَمِيل veut dire « beau, joli ». Au féminin : جَمِيلَة. Un seul bloc : dja-mîl.', '[{"text": "الْبَحْرُ جَمِيلٌ", "translation": "La mer est belle.", "transliteration": "al-ba7ru djamîl"}, {"text": "هٰذِهِ مَدِينَةٌ جَمِيلَةٌ", "translation": "C''est une belle ville.", "transliteration": "hâdhihi madînatun djamîla"}]'::jsonb, null, '{"id": "ar.d.djamil", "word": "جَمِيل", "transliteration": "djamîl", "translation": "beau, joli", "partOfSpeech": "adjective", "explanation": "جَمِيل veut dire « beau, joli ». Au féminin : جَمِيلَة. Un seul bloc : dja-mîl.", "examples": [{"text": "الْبَحْرُ جَمِيلٌ", "translation": "La mer est belle.", "transliteration": "al-ba7ru djamîl"}, {"text": "هٰذِهِ مَدِينَةٌ جَمِيلَةٌ", "translation": "C''est une belle ville.", "transliteration": "hâdhihi madînatun djamîla"}], "confusions": [{"word": "جَمَل", "note": "djamal, le chameau : pas de ي, voyelle brève."}], "forms": {"feminine": "جَمِيلَة"}, "unitId": "ar.v.djamil"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bayt', 'ar', 'بَيْت', 'la maison', 'بَيْت est la maison, le foyer. Une seule syllabe fermée : bayt.', '[{"text": "هٰذَا بَيْتٌ صَغِيرٌ", "translation": "C''est une petite maison.", "transliteration": "hâdhâ baytun Saghîr"}, {"text": "أَنَا فِي الْبَيْتِ", "translation": "Je suis à la maison.", "transliteration": "''anâ fî l-bayt"}]'::jsonb, null, '{"id": "ar.d.bayt", "word": "بَيْت", "transliteration": "bayt", "translation": "la maison", "partOfSpeech": "noun", "explanation": "بَيْت est la maison, le foyer. Une seule syllabe fermée : bayt.", "examples": [{"text": "هٰذَا بَيْتٌ صَغِيرٌ", "translation": "C''est une petite maison.", "transliteration": "hâdhâ baytun Saghîr"}, {"text": "أَنَا فِي الْبَيْتِ", "translation": "Je suis à la maison.", "transliteration": "''anâ fî l-bayt"}], "confusions": [{"word": "بَيْض", "note": "bayD, les œufs : ض à la fin au lieu de ت."}], "forms": {"plural": "بُيُوت"}, "unitId": "ar.v.bayt"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bahr', 'ar', 'بَحْر', 'la mer', 'بَحْر est la mer. Une seule syllabe fermée : ba7r ; le ح se souffle du fond de la gorge.', '[{"text": "الْبَحْرُ بَارِدٌ", "translation": "La mer est froide.", "transliteration": "al-ba7ru bârid"}, {"text": "ذَهَبَ إِلَى الْبَحْرِ", "translation": "Il est allé à la mer.", "transliteration": "dhahaba ''ilâ l-ba7r"}]'::jsonb, null, '{"id": "ar.d.bahr", "word": "بَحْر", "transliteration": "ba7r", "translation": "la mer", "partOfSpeech": "noun", "explanation": "بَحْر est la mer. Une seule syllabe fermée : ba7r ; le ح se souffle du fond de la gorge.", "examples": [{"text": "الْبَحْرُ بَارِدٌ", "translation": "La mer est froide.", "transliteration": "al-ba7ru bârid"}, {"text": "ذَهَبَ إِلَى الْبَحْرِ", "translation": "Il est allé à la mer.", "transliteration": "dhahaba ''ilâ l-ba7r"}], "confusions": [{"word": "نَهْر", "note": "nahr, la rivière, le fleuve."}], "forms": {"plural": "بِحَار"}, "unitId": "ar.v.bahr"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.djadid', 'ar', 'جَدِيد', 'nouveau, neuf', 'جَدِيد veut dire « nouveau, neuf ». Au féminin : جَدِيدَة. Deux blocs : جد | يد.', '[{"text": "الْمَطَارُ جَدِيدٌ", "translation": "L''aéroport est neuf.", "transliteration": "al-maTâru djadîd"}, {"text": "هٰذَا شَارِعٌ جَدِيدٌ", "translation": "C''est une nouvelle rue.", "transliteration": "hâdhâ châri3un djadîd"}]'::jsonb, null, '{"id": "ar.d.djadid", "word": "جَدِيد", "transliteration": "djadîd", "translation": "nouveau, neuf", "partOfSpeech": "adjective", "explanation": "جَدِيد veut dire « nouveau, neuf ». Au féminin : جَدِيدَة. Deux blocs : جد | يد.", "examples": [{"text": "الْمَطَارُ جَدِيدٌ", "translation": "L''aéroport est neuf.", "transliteration": "al-maTâru djadîd"}, {"text": "هٰذَا شَارِعٌ جَدِيدٌ", "translation": "C''est une nouvelle rue.", "transliteration": "hâdhâ châri3un djadîd"}], "forms": {"feminine": "جَدِيدَة", "plural": "جُدُد"}, "unitId": "ar.v.djadid"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.qahwa', 'ar', 'قَهْوَة', 'le café', 'قَهْوَة est le café (la boisson). En Égypte, le mot se prononce ahwa et désigne aussi le café où l''on s''assoit.', '[{"text": "الْقَهْوَةُ حَارَّةٌ", "translation": "Le café est chaud.", "transliteration": "al-qahwatu 7ârra"}, {"text": "الْقَهْوَةُ مَعَ الْحَلِيبِ", "translation": "Le café au lait.", "transliteration": "al-qahwatu ma3a l-7alîb"}]'::jsonb, null, '{"id": "ar.d.qahwa", "word": "قَهْوَة", "transliteration": "qahwa", "translation": "le café", "partOfSpeech": "noun", "explanation": "قَهْوَة est le café (la boisson). En Égypte, le mot se prononce ahwa et désigne aussi le café où l''on s''assoit.", "examples": [{"text": "الْقَهْوَةُ حَارَّةٌ", "translation": "Le café est chaud.", "transliteration": "al-qahwatu 7ârra"}, {"text": "الْقَهْوَةُ مَعَ الْحَلِيبِ", "translation": "Le café au lait.", "transliteration": "al-qahwatu ma3a l-7alîb"}], "unitId": "ar.v.qahwa"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.layl', 'ar', 'لَيْل', 'la nuit', 'لَيْل est la nuit. Avec l''article, on écrit deux ل : اللَّيْل (al-layl).', '[{"text": "شَرِبَ الشَّايَ فِي اللَّيْلِ", "translation": "Il a bu le thé la nuit.", "transliteration": "chariba ch-châya fî l-layl"}, {"text": "اللَّيْلُ جَمِيلٌ هُنَا", "translation": "La nuit est belle ici.", "transliteration": "al-laylu djamîlun hunâ"}]'::jsonb, null, '{"id": "ar.d.layl", "word": "لَيْل", "transliteration": "layl", "translation": "la nuit", "partOfSpeech": "noun", "explanation": "لَيْل est la nuit. Avec l''article, on écrit deux ل : اللَّيْل (al-layl).", "examples": [{"text": "شَرِبَ الشَّايَ فِي اللَّيْلِ", "translation": "Il a bu le thé la nuit.", "transliteration": "chariba ch-châya fî l-layl"}, {"text": "اللَّيْلُ جَمِيلٌ هُنَا", "translation": "La nuit est belle ici.", "transliteration": "al-laylu djamîlun hunâ"}], "confusions": [{"word": "لَيْلَة", "note": "layla, une nuit (une seule) : avec ـة."}], "unitId": "ar.v.layl"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.nahar', 'ar', 'نَهَار', 'le jour (la journée)', 'نَهَار est le jour, le temps où il fait clair (le contraire de لَيْل). Deux blocs : نها | ر.', '[{"text": "النَّهَارُ حَارٌّ فِي الصَّيْفِ", "translation": "Le jour, il fait chaud en été.", "transliteration": "an-nahâru 7ârrun fî S-Sayf"}, {"text": "الشَّمْسُ فِي النَّهَارِ وَالْقَمَرُ فِي اللَّيْلِ", "translation": "Le soleil le jour, la lune la nuit.", "transliteration": "ach-chamsu fî n-nahâri wa-l-qamaru fî l-layl"}]'::jsonb, null, '{"id": "ar.d.nahar", "word": "نَهَار", "transliteration": "nahâr", "translation": "le jour (la journée)", "partOfSpeech": "noun", "explanation": "نَهَار est le jour, le temps où il fait clair (le contraire de لَيْل). Deux blocs : نها | ر.", "examples": [{"text": "النَّهَارُ حَارٌّ فِي الصَّيْفِ", "translation": "Le jour, il fait chaud en été.", "transliteration": "an-nahâru 7ârrun fî S-Sayf"}, {"text": "الشَّمْسُ فِي النَّهَارِ وَالْقَمَرُ فِي اللَّيْلِ", "translation": "Le soleil le jour, la lune la nuit.", "transliteration": "ach-chamsu fî n-nahâri wa-l-qamaru fî l-layl"}], "confusions": [{"word": "نَهْر", "note": "nahr, la rivière : pas de ا, une seule syllabe."}], "unitId": "ar.v.nahar"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.chita', 'ar', 'شِتَاء', 'l''hiver', 'شِتَاء est l''hiver. La hamza finale ء ne s''attache à rien : شتا | ء, chi-tâ''.', '[{"text": "الشِّتَاءُ بَارِدٌ", "translation": "L''hiver est froid.", "transliteration": "ach-chitâ''u bârid"}, {"text": "الثَّلْجُ فِي الشِّتَاءِ", "translation": "La neige en hiver.", "transliteration": "ath-thaldju fî ch-chitâ''"}]'::jsonb, null, '{"id": "ar.d.chita", "word": "شِتَاء", "transliteration": "chitâ''", "translation": "l''hiver", "partOfSpeech": "noun", "explanation": "شِتَاء est l''hiver. La hamza finale ء ne s''attache à rien : شتا | ء, chi-tâ''.", "examples": [{"text": "الشِّتَاءُ بَارِدٌ", "translation": "L''hiver est froid.", "transliteration": "ach-chitâ''u bârid"}, {"text": "الثَّلْجُ فِي الشِّتَاءِ", "translation": "La neige en hiver.", "transliteration": "ath-thaldju fî ch-chitâ''"}], "confusions": [{"word": "صَيْف", "note": "Sayf, l''été : le contraire."}], "unitId": "ar.v.chita"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.nadjm', 'ar', 'نَجْم', 'l''étoile', 'نَجْم est l''étoile (et aussi une vedette, une star). Une seule syllabe fermée : nadjm.', '[{"text": "هٰذَا نَجْمٌ كَبِيرٌ", "translation": "C''est une grande étoile.", "transliteration": "hâdhâ nadjmun kabîr"}, {"text": "النُّجُومُ فِي اللَّيْلِ", "translation": "Les étoiles, la nuit.", "transliteration": "an-nudjûmu fî l-layl"}]'::jsonb, null, '{"id": "ar.d.nadjm", "word": "نَجْم", "transliteration": "nadjm", "translation": "l''étoile", "otherTranslations": ["une vedette"], "partOfSpeech": "noun", "explanation": "نَجْم est l''étoile (et aussi une vedette, une star). Une seule syllabe fermée : nadjm.", "examples": [{"text": "هٰذَا نَجْمٌ كَبِيرٌ", "translation": "C''est une grande étoile.", "transliteration": "hâdhâ nadjmun kabîr"}, {"text": "النُّجُومُ فِي اللَّيْلِ", "translation": "Les étoiles, la nuit.", "transliteration": "an-nudjûmu fî l-layl"}], "forms": {"plural": "نُجُوم"}, "unitId": "ar.v.nadjm"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.maa_eau', 'ar', 'مَاء', 'l''eau', 'مَاء est l''eau. Deux blocs : ما | ء ; on entend un petit arrêt à la fin, mâ''. En Égypte, on dit مَيَّة (mayya).', '[{"text": "هٰذَا مَاءٌ حَارٌّ", "translation": "C''est de l''eau chaude.", "transliteration": "hâdhâ mâ''un 7ârr"}, {"text": "الْمَاءُ عَلَى الْمَكْتَبِ", "translation": "L''eau est sur le bureau.", "transliteration": "al-mâ''u 3alâ l-maktab"}]'::jsonb, null, '{"id": "ar.d.maa_eau", "word": "مَاء", "transliteration": "mâ''", "translation": "l''eau", "partOfSpeech": "noun", "explanation": "مَاء est l''eau. Deux blocs : ما | ء ; on entend un petit arrêt à la fin, mâ''. En Égypte, on dit مَيَّة (mayya).", "examples": [{"text": "هٰذَا مَاءٌ حَارٌّ", "translation": "C''est de l''eau chaude.", "transliteration": "hâdhâ mâ''un 7ârr"}, {"text": "الْمَاءُ عَلَى الْمَكْتَبِ", "translation": "L''eau est sur le bureau.", "transliteration": "al-mâ''u 3alâ l-maktab"}], "confusions": [{"word": "مَا", "note": "mâ, « quoi ? » ou « ne… pas » : sans le ء final."}], "unitId": "ar.v.maa_eau"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.chams', 'ar', 'شَمْس', 'le soleil', 'شَمْس est le soleil. Le mot est féminin : الشَّمْسُ حَارَّةٌ. Une seule syllabe fermée : chams.', '[{"text": "الشَّمْسُ جَمِيلَةٌ فِي الصَّبَاحِ", "translation": "Le soleil est beau le matin.", "transliteration": "ach-chamsu djamîlatun fî S-Sabâ7"}, {"text": "لَا شَمْسَ الْيَوْمَ", "translation": "Il n''y a pas de soleil aujourd''hui.", "transliteration": "lâ chamsa l-yawm"}]'::jsonb, null, '{"id": "ar.d.chams", "word": "شَمْس", "transliteration": "chams", "translation": "le soleil", "partOfSpeech": "noun", "explanation": "شَمْس est le soleil. Le mot est féminin : الشَّمْسُ حَارَّةٌ. Une seule syllabe fermée : chams.", "examples": [{"text": "الشَّمْسُ جَمِيلَةٌ فِي الصَّبَاحِ", "translation": "Le soleil est beau le matin.", "transliteration": "ach-chamsu djamîlatun fî S-Sabâ7"}, {"text": "لَا شَمْسَ الْيَوْمَ", "translation": "Il n''y a pas de soleil aujourd''hui.", "transliteration": "lâ chamsa l-yawm"}], "confusions": [{"word": "قَمَر", "note": "qamar, la lune (masculin)."}], "unitId": "ar.v.chams"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.rih', 'ar', 'رِيح', 'le vent', 'رِيح est le vent. Le mot est féminin : الرِّيحُ بَارِدَةٌ. Deux blocs : ر | يح.', '[{"text": "الرِّيحُ بَارِدَةٌ", "translation": "Le vent est froid.", "transliteration": "ar-rî7u bârida"}, {"text": "لَا رِيحَ الْيَوْمَ", "translation": "Il n''y a pas de vent aujourd''hui.", "transliteration": "lâ rî7a l-yawm"}]'::jsonb, null, '{"id": "ar.d.rih", "word": "رِيح", "transliteration": "rî7", "translation": "le vent", "partOfSpeech": "noun", "explanation": "رِيح est le vent. Le mot est féminin : الرِّيحُ بَارِدَةٌ. Deux blocs : ر | يح.", "examples": [{"text": "الرِّيحُ بَارِدَةٌ", "translation": "Le vent est froid.", "transliteration": "ar-rî7u bârida"}, {"text": "لَا رِيحَ الْيَوْمَ", "translation": "Il n''y a pas de vent aujourd''hui.", "transliteration": "lâ rî7a l-yawm"}], "forms": {"plural": "رِيَاح"}, "unitId": "ar.v.rih"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ghayma', 'ar', 'غَيْمَة', 'le nuage', 'غَيْمَة est un nuage. Le point sur غ (gh) le distingue de ع. Un seul bloc : ghay-ma.', '[{"text": "هٰذِهِ غَيْمَةٌ كَبِيرَةٌ", "translation": "C''est un gros nuage.", "transliteration": "hâdhihi ghaymatun kabîra"}, {"text": "الْغَيْمَةُ عَلَى الْجَبَلِ", "translation": "Le nuage est sur la montagne.", "transliteration": "al-ghaymatu 3alâ l-djabal"}]'::jsonb, null, '{"id": "ar.d.ghayma", "word": "غَيْمَة", "transliteration": "ghayma", "translation": "le nuage", "partOfSpeech": "noun", "explanation": "غَيْمَة est un nuage. Le point sur غ (gh) le distingue de ع. Un seul bloc : ghay-ma.", "examples": [{"text": "هٰذِهِ غَيْمَةٌ كَبِيرَةٌ", "translation": "C''est un gros nuage.", "transliteration": "hâdhihi ghaymatun kabîra"}, {"text": "الْغَيْمَةُ عَلَى الْجَبَلِ", "translation": "Le nuage est sur la montagne.", "transliteration": "al-ghaymatu 3alâ l-djabal"}], "forms": {"plural": "غُيُوم"}, "unitId": "ar.v.ghayma"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.allah', 'ar', 'اللّٰه', 'Dieu', 'اللّٰه est le mot arabe pour « Dieu » : les chrétiens arabophones l''emploient depuis toujours, dans la Bible et dans la liturgie. Le ل est solaire, on lit donc Allâh (l doublé). Le petit trait vertical au-dessus de la chadda est un alif qui se lit â.', '[{"text": "اللّٰهُ مَعَنَا", "translation": "Dieu est avec nous.", "transliteration": "Allâhu ma3anâ"}, {"text": "بَيْتُ اللّٰهِ", "translation": "la maison de Dieu", "transliteration": "baytu llâhi"}]'::jsonb, null, '{"id": "ar.d.allah", "word": "اللّٰه", "transliteration": "Allâh", "translation": "Dieu", "partOfSpeech": "noun", "explanation": "اللّٰه est le mot arabe pour « Dieu » : les chrétiens arabophones l''emploient depuis toujours, dans la Bible et dans la liturgie. Le ل est solaire, on lit donc Allâh (l doublé). Le petit trait vertical au-dessus de la chadda est un alif qui se lit â.", "examples": [{"text": "اللّٰهُ مَعَنَا", "translation": "Dieu est avec nous.", "transliteration": "Allâhu ma3anâ"}, {"text": "بَيْتُ اللّٰهِ", "translation": "la maison de Dieu", "transliteration": "baytu llâhi"}], "confusions": [{"word": "الرَّبّ", "note": "ar-rabb, « le Seigneur » : un autre titre de Dieu, avec un mot différent."}], "unitId": "ar.v.allah"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.rabb', 'ar', 'الرَّبّ', 'le Seigneur', 'الرَّبّ est le titre de Dieu et du Christ : « le Seigneur ». Il a deux chaddas : la première vient de ال solaire (ar-), la seconde fait partie du mot (rabb, avec un b doublé).', '[{"text": "رَبُّنَا يَسُوعُ الْمَسِيحُ", "translation": "notre Seigneur Jésus-Christ", "transliteration": "rabbunâ yasû3u l-masî7"}, {"text": "الرَّبُّ مَعَنَا", "translation": "Le Seigneur est avec nous.", "transliteration": "ar-rabbu ma3anâ"}]'::jsonb, null, '{"id": "ar.d.rabb", "word": "الرَّبّ", "transliteration": "ar-rabb", "translation": "le Seigneur", "partOfSpeech": "noun", "explanation": "الرَّبّ est le titre de Dieu et du Christ : « le Seigneur ». Il a deux chaddas : la première vient de ال solaire (ar-), la seconde fait partie du mot (rabb, avec un b doublé).", "examples": [{"text": "رَبُّنَا يَسُوعُ الْمَسِيحُ", "translation": "notre Seigneur Jésus-Christ", "transliteration": "rabbunâ yasû3u l-masî7"}, {"text": "الرَّبُّ مَعَنَا", "translation": "Le Seigneur est avec nous.", "transliteration": "ar-rabbu ma3anâ"}], "confusions": [{"word": "الْآب", "note": "al-âb, « le Père » : une des personnes de la Trinité, alors que الرَّبّ est un titre."}], "forms": {"avec « notre »": "رَبُّنَا"}, "unitId": "ar.v.rabb"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.yasu', 'ar', 'يَسُوع', 'Jésus', 'يَسُوع est le nom de Jésus en arabe chrétien. Il se termine par ع (3), une consonne de la gorge qu''on prononce bien à la fin : yasû3. Le و après la damma est long (û).', '[{"text": "يَسُوعُ الْمَسِيحُ", "translation": "Jésus-Christ", "transliteration": "yasû3u l-masî7"}, {"text": "يَسُوعُ ابْنُ اللّٰهِ", "translation": "Jésus, Fils de Dieu", "transliteration": "yasû3u bnu llâh"}]'::jsonb, null, '{"id": "ar.d.yasu", "word": "يَسُوع", "transliteration": "yasû3", "translation": "Jésus", "partOfSpeech": "noun", "explanation": "يَسُوع est le nom de Jésus en arabe chrétien. Il se termine par ع (3), une consonne de la gorge qu''on prononce bien à la fin : yasû3. Le و après la damma est long (û).", "examples": [{"text": "يَسُوعُ الْمَسِيحُ", "translation": "Jésus-Christ", "transliteration": "yasû3u l-masî7"}, {"text": "يَسُوعُ ابْنُ اللّٰهِ", "translation": "Jésus, Fils de Dieu", "transliteration": "yasû3u bnu llâh"}], "confusions": [{"word": "عِيسَى", "note": "3îsâ : c''est le nom de Jésus dans le Coran ; les chrétiens arabes disent يَسُوع."}], "unitId": "ar.v.yasu"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.masih', 'ar', 'الْمَسِيح', 'le Christ', 'الْمَسِيح est le Christ, « le Messie », celui qui a reçu l''onction. م est une lettre lunaire : le ل porte un soukoun et on dit al-. Le ي après la kasra allonge : masî7. Le ح (sans point) se note 7.', '[{"text": "يَسُوعُ الْمَسِيحُ هُوَ الرَّبُّ", "translation": "Jésus-Christ est le Seigneur.", "transliteration": "yasû3u l-masî7u huwa r-rabb"}, {"text": "بِاسْمِ الْمَسِيحِ", "translation": "au nom du Christ", "transliteration": "bismi l-masî7i"}]'::jsonb, null, '{"id": "ar.d.masih", "word": "الْمَسِيح", "transliteration": "al-masî7", "translation": "le Christ", "partOfSpeech": "noun", "explanation": "الْمَسِيح est le Christ, « le Messie », celui qui a reçu l''onction. م est une lettre lunaire : le ل porte un soukoun et on dit al-. Le ي après la kasra allonge : masî7. Le ح (sans point) se note 7.", "examples": [{"text": "يَسُوعُ الْمَسِيحُ هُوَ الرَّبُّ", "translation": "Jésus-Christ est le Seigneur.", "transliteration": "yasû3u l-masî7u huwa r-rabb"}, {"text": "بِاسْمِ الْمَسِيحِ", "translation": "au nom du Christ", "transliteration": "bismi l-masî7i"}], "confusions": [{"word": "مَسَاء", "note": "masâ'', le soir (leçon 20) : il commence de la même façon, mais sans ي ni ح."}], "unitId": "ar.v.masih"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.al_ab', 'ar', 'الْآب', 'le Père (Dieu le Père)', 'Dans la Trinité, الْآب est Dieu le Père. Le آ (alif madda) vaut une hamza suivie d''un â long : al-âb. Pour dire « père » dans la vie courante, on écrit أَب (ab) : أَبِي = mon père.', '[{"text": "بِاسْمِ الْآبِ", "translation": "au nom du Père", "transliteration": "bismi l-âbi"}, {"text": "الْآبُ وَالاِبْنُ", "translation": "le Père et le Fils", "transliteration": "al-âbu wa-l-ibn"}]'::jsonb, null, '{"id": "ar.d.al_ab", "word": "الْآب", "transliteration": "al-âb", "translation": "le Père (Dieu le Père)", "partOfSpeech": "noun", "explanation": "Dans la Trinité, الْآب est Dieu le Père. Le آ (alif madda) vaut une hamza suivie d''un â long : al-âb. Pour dire « père » dans la vie courante, on écrit أَب (ab) : أَبِي = mon père.", "examples": [{"text": "بِاسْمِ الْآبِ", "translation": "au nom du Père", "transliteration": "bismi l-âbi"}, {"text": "الْآبُ وَالاِبْنُ", "translation": "le Père et le Fils", "transliteration": "al-âbu wa-l-ibn"}], "confusions": [{"word": "أَب", "note": "ab, un père, mon père (sens courant) : un a bref, pas de madda."}], "forms": {"plural": "آبَاء"}, "unitId": "ar.v.al_ab"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ruh_al_qudus', 'ar', 'الرُّوح الْقُدُس', 'le Saint-Esprit', 'Deux mots : الرُّوح (l''esprit, solaire : ar-rû7) et الْقُدُس (la sainteté, lunaire : al-qudus). Ensemble : « l''Esprit de sainteté », le Saint-Esprit. Dans une phrase, on lit ar-rû7u l-qudus.', '[{"text": "بِاسْمِ الْآبِ وَالاِبْنِ وَالرُّوحِ الْقُدُسِ", "translation": "au nom du Père, du Fils et du Saint-Esprit", "transliteration": "bismi l-âbi wa-l-ibni wa-r-rû7i l-qudus"}, {"text": "الرُّوحُ الْقُدُسُ هُوَ الرَّبُّ", "translation": "Le Saint-Esprit est le Seigneur.", "transliteration": "ar-rû7u l-qudusu huwa r-rabb"}]'::jsonb, null, '{"id": "ar.d.ruh_al_qudus", "word": "الرُّوح الْقُدُس", "transliteration": "ar-rû7 al-qudus", "translation": "le Saint-Esprit", "partOfSpeech": "expression", "explanation": "Deux mots : الرُّوح (l''esprit, solaire : ar-rû7) et الْقُدُس (la sainteté, lunaire : al-qudus). Ensemble : « l''Esprit de sainteté », le Saint-Esprit. Dans une phrase, on lit ar-rû7u l-qudus.", "examples": [{"text": "بِاسْمِ الْآبِ وَالاِبْنِ وَالرُّوحِ الْقُدُسِ", "translation": "au nom du Père, du Fils et du Saint-Esprit", "transliteration": "bismi l-âbi wa-l-ibni wa-r-rû7i l-qudus"}, {"text": "الرُّوحُ الْقُدُسُ هُوَ الرَّبُّ", "translation": "Le Saint-Esprit est le Seigneur.", "transliteration": "ar-rû7u l-qudusu huwa r-rabb"}], "confusions": [{"word": "الْقُدُّوس", "note": "al-quddûs, « le Saint » (adjectif) : une chadda sur le د et un û long."}], "unitId": "ar.v.ruh_al_qudus"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.thaluth', 'ar', 'الثَّالُوث', 'la Trinité', 'الثَّالُوث est la Trinité : un seul Dieu en trois personnes, le Père, le Fils et le Saint-Esprit. ث est solaire : on lit ath-thâlûth, avec un th doublé. Le ا et le و sont des voyelles longues : â et û.', '[{"text": "الثَّالُوثُ: الْآبُ وَالاِبْنُ وَالرُّوحُ الْقُدُسُ", "translation": "La Trinité : le Père, le Fils et le Saint-Esprit.", "transliteration": "ath-thâlûthu: al-âbu wa-l-ibnu wa-r-rû7u l-qudus"}, {"text": "الثَّالُوثُ الْقُدُّوسُ", "translation": "la Sainte Trinité", "transliteration": "ath-thâlûthu l-quddûs"}]'::jsonb, null, '{"id": "ar.d.thaluth", "word": "الثَّالُوث", "transliteration": "ath-thâlûth", "translation": "la Trinité", "partOfSpeech": "noun", "explanation": "الثَّالُوث est la Trinité : un seul Dieu en trois personnes, le Père, le Fils et le Saint-Esprit. ث est solaire : on lit ath-thâlûth, avec un th doublé. Le ا et le و sont des voyelles longues : â et û.", "examples": [{"text": "الثَّالُوثُ: الْآبُ وَالاِبْنُ وَالرُّوحُ الْقُدُسُ", "translation": "La Trinité : le Père, le Fils et le Saint-Esprit.", "transliteration": "ath-thâlûthu: al-âbu wa-l-ibnu wa-r-rû7u l-qudus"}, {"text": "الثَّالُوثُ الْقُدُّوسُ", "translation": "la Sainte Trinité", "transliteration": "ath-thâlûthu l-quddûs"}], "confusions": [{"word": "ثَلَاثَة", "note": "thalâtha, « trois » : même racine ث ل ث, mais ce n''est pas le mot de la Trinité."}], "unitId": "ar.v.thaluth"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bismi', 'ar', 'بِاسْمِ', 'au nom de', 'بِاسْمِ = بِ (au, par) + اسْم (nom). Le ا s''écrit mais ne se prononce pas : on lit bismi d''un seul souffle. Le mot suivant prend une kasra : بِاسْمِ الْآبِ. C''est la formule qui ouvre la prière : « Au nom du Père… ».', '[{"text": "بِاسْمِ يَسُوعَ الْمَسِيحِ", "translation": "au nom de Jésus-Christ", "transliteration": "bismi yasû3a l-masî7i"}, {"text": "بِاسْمِ الرَّبِّ", "translation": "au nom du Seigneur", "transliteration": "bismi r-rabbi"}]'::jsonb, null, '{"id": "ar.d.bismi", "word": "بِاسْمِ", "transliteration": "bismi", "translation": "au nom de", "partOfSpeech": "expression", "explanation": "بِاسْمِ = بِ (au, par) + اسْم (nom). Le ا s''écrit mais ne se prononce pas : on lit bismi d''un seul souffle. Le mot suivant prend une kasra : بِاسْمِ الْآبِ. C''est la formule qui ouvre la prière : « Au nom du Père… ».", "examples": [{"text": "بِاسْمِ يَسُوعَ الْمَسِيحِ", "translation": "au nom de Jésus-Christ", "transliteration": "bismi yasû3a l-masî7i"}, {"text": "بِاسْمِ الرَّبِّ", "translation": "au nom du Seigneur", "transliteration": "bismi r-rabbi"}], "confusions": [{"word": "اِسْم", "note": "ism, un nom (leçon 16) : seul, il se lit avec un i au début ; après بِ, le ا disparaît."}], "unitId": "ar.v.bismi"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kanisa', 'ar', 'كَنِيسَة', 'église', 'كَنِيسَة est l''église, le bâtiment comme la communauté des fidèles. C''est un nom féminin : le ة final se lit a (kanîsa). Le ي après la kasra allonge : nî.', '[{"text": "الْكَنِيسَةُ كَبِيرَةٌ", "translation": "L''église est grande.", "transliteration": "al-kanîsatu kabîra"}, {"text": "ذَهَبَ إِلَى الْكَنِيسَةِ", "translation": "Il est allé à l''église.", "transliteration": "dhahaba ''ilâ l-kanîsa"}]'::jsonb, null, '{"id": "ar.d.kanisa", "word": "كَنِيسَة", "transliteration": "kanîsa", "translation": "église", "partOfSpeech": "noun", "explanation": "كَنِيسَة est l''église, le bâtiment comme la communauté des fidèles. C''est un nom féminin : le ة final se lit a (kanîsa). Le ي après la kasra allonge : nî.", "examples": [{"text": "الْكَنِيسَةُ كَبِيرَةٌ", "translation": "L''église est grande.", "transliteration": "al-kanîsatu kabîra"}, {"text": "ذَهَبَ إِلَى الْكَنِيسَةِ", "translation": "Il est allé à l''église.", "transliteration": "dhahaba ''ilâ l-kanîsa"}], "confusions": [{"word": "كَنِيس", "note": "kanîs, la synagogue : sans ة."}], "forms": {"plural": "كَنَائِس"}, "unitId": "ar.v.kanisa"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.haykal', 'ar', 'هَيْكَل', 'sanctuaire (le chœur où est l''autel)', 'Dans une église copte, الْهَيْكَل est le sanctuaire : la partie la plus sacrée, derrière la cloison des icônes, où se tient l''autel. هَيْ se lit hay (diphtongue), pas hî.', '[{"text": "الْمَذْبَحُ فِي الْهَيْكَلِ", "translation": "L''autel est dans le sanctuaire.", "transliteration": "al-madhba7u fî l-haykal"}, {"text": "حِجَابُ الْهَيْكَلِ", "translation": "la cloison du sanctuaire (l''iconostase)", "transliteration": "7idjâbu l-haykal"}]'::jsonb, null, '{"id": "ar.d.haykal", "word": "هَيْكَل", "transliteration": "haykal", "translation": "sanctuaire (le chœur où est l''autel)", "partOfSpeech": "noun", "explanation": "Dans une église copte, الْهَيْكَل est le sanctuaire : la partie la plus sacrée, derrière la cloison des icônes, où se tient l''autel. هَيْ se lit hay (diphtongue), pas hî.", "examples": [{"text": "الْمَذْبَحُ فِي الْهَيْكَلِ", "translation": "L''autel est dans le sanctuaire.", "transliteration": "al-madhba7u fî l-haykal"}, {"text": "حِجَابُ الْهَيْكَلِ", "translation": "la cloison du sanctuaire (l''iconostase)", "transliteration": "7idjâbu l-haykal"}], "confusions": [{"word": "هِيَ", "note": "hiya, « elle » : ici le ي porte une kasra avant lui, c''est un î."}], "forms": {"plural": "هَيَاكِل"}, "unitId": "ar.v.haykal"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.madhbah', 'ar', 'مَذْبَح', 'autel', 'مَذْبَح est l''autel : la table sacrée, au centre du sanctuaire, où l''on célèbre le qoddâs. Le mot vient de la racine ذ ب ح (offrir en sacrifice). Il se lit en deux syllabes : madh-ba7.', '[{"text": "عَلَى الْمَذْبَحِ شَمْعَةٌ", "translation": "Sur l''autel, il y a une bougie.", "transliteration": "3alâ l-madhba7i cham3a"}, {"text": "هٰذَا الْمَذْبَحُ كَبِيرٌ", "translation": "Cet autel est grand.", "transliteration": "hâdhâ l-madhba7u kabîr"}]'::jsonb, null, '{"id": "ar.d.madhbah", "word": "مَذْبَح", "transliteration": "madhba7", "translation": "autel", "partOfSpeech": "noun", "explanation": "مَذْبَح est l''autel : la table sacrée, au centre du sanctuaire, où l''on célèbre le qoddâs. Le mot vient de la racine ذ ب ح (offrir en sacrifice). Il se lit en deux syllabes : madh-ba7.", "examples": [{"text": "عَلَى الْمَذْبَحِ شَمْعَةٌ", "translation": "Sur l''autel, il y a une bougie.", "transliteration": "3alâ l-madhba7i cham3a"}, {"text": "هٰذَا الْمَذْبَحُ كَبِيرٌ", "translation": "Cet autel est grand.", "transliteration": "hâdhâ l-madhba7u kabîr"}], "forms": {"plural": "مَذَابِح"}, "unitId": "ar.v.madhbah"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ayquna', 'ar', 'أَيْقُونَة', 'icône', 'أَيْقُونَة (du grec eikôn) est une icône. Le début أَيْ se lit ay (diphtongue), le ـُو est un û long, et le ة final se lit a : ay-qû-na.', '[{"text": "أَيْقُونَةٌ جَمِيلَةٌ", "translation": "une belle icône", "transliteration": "ayqûnatun djamîla"}, {"text": "فِي الْكَنِيسَةِ أَيْقُونَةٌ", "translation": "Dans l''église, il y a une icône.", "transliteration": "fî l-kanîsati ayqûna"}]'::jsonb, null, '{"id": "ar.d.ayquna", "word": "أَيْقُونَة", "transliteration": "ayqûna", "translation": "icône", "partOfSpeech": "noun", "explanation": "أَيْقُونَة (du grec eikôn) est une icône. Le début أَيْ se lit ay (diphtongue), le ـُو est un û long, et le ة final se lit a : ay-qû-na.", "examples": [{"text": "أَيْقُونَةٌ جَمِيلَةٌ", "translation": "une belle icône", "transliteration": "ayqûnatun djamîla"}, {"text": "فِي الْكَنِيسَةِ أَيْقُونَةٌ", "translation": "Dans l''église, il y a une icône.", "transliteration": "fî l-kanîsati ayqûna"}], "forms": {"plural": "أَيْقُونَات"}, "unitId": "ar.v.ayquna"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bakhur', 'ar', 'بَخُور', 'encens', 'بَخُور est l''encens, brûlé dans l''encensoir pendant le qoddâs et aux offices d''« élévation de l''encens » du matin et du soir (رَفْع الْبَخُور). Le ـُو est un û long : ba-khûr.', '[{"text": "هٰذَا بَخُورٌ جَدِيدٌ", "translation": "C''est un nouvel encens.", "transliteration": "hâdhâ bakhûrun djadîd"}, {"text": "الْبَخُورُ فِي الْكَنِيسَةِ", "translation": "L''encens est dans l''église.", "transliteration": "al-bakhûru fî l-kanîsa"}]'::jsonb, null, '{"id": "ar.d.bakhur", "word": "بَخُور", "transliteration": "bakhûr", "translation": "encens", "partOfSpeech": "noun", "explanation": "بَخُور est l''encens, brûlé dans l''encensoir pendant le qoddâs et aux offices d''« élévation de l''encens » du matin et du soir (رَفْع الْبَخُور). Le ـُو est un û long : ba-khûr.", "examples": [{"text": "هٰذَا بَخُورٌ جَدِيدٌ", "translation": "C''est un nouvel encens.", "transliteration": "hâdhâ bakhûrun djadîd"}, {"text": "الْبَخُورُ فِي الْكَنِيسَةِ", "translation": "L''encens est dans l''église.", "transliteration": "al-bakhûru fî l-kanîsa"}], "confusions": [{"word": "بَحْر", "note": "ba7r, la mer : ح sans point à la place du خ, et un soukoun au lieu du û long."}], "unitId": "ar.v.bakhur"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.chamaa', 'ar', 'شَمْعَة', 'bougie, cierge', 'شَمْعَة est la bougie ou le cierge qu''on allume devant une icône ou sur l''autel. Le ة final se lit a. Le ع (3) se prononce au fond de la gorge : cham-3a.', '[{"text": "أَشْعَلَ شَمْعَةً", "translation": "Il a allumé une bougie.", "transliteration": "ach3ala cham3a"}, {"text": "شَمْعَةٌ أَمَامَ الْأَيْقُونَةِ", "translation": "une bougie devant l''icône", "transliteration": "cham3atun amâma l-ayqûna"}]'::jsonb, null, '{"id": "ar.d.chamaa", "word": "شَمْعَة", "transliteration": "cham3a", "translation": "bougie, cierge", "partOfSpeech": "noun", "explanation": "شَمْعَة est la bougie ou le cierge qu''on allume devant une icône ou sur l''autel. Le ة final se lit a. Le ع (3) se prononce au fond de la gorge : cham-3a.", "examples": [{"text": "أَشْعَلَ شَمْعَةً", "translation": "Il a allumé une bougie.", "transliteration": "ach3ala cham3a"}, {"text": "شَمْعَةٌ أَمَامَ الْأَيْقُونَةِ", "translation": "une bougie devant l''icône", "transliteration": "cham3atun amâma l-ayqûna"}], "confusions": [{"word": "شَمْس", "note": "chams, le soleil (leçon 24) : même début, mais finit par س."}], "forms": {"plural": "شُمُوع"}, "unitId": "ar.v.chamaa"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.qurban', 'ar', 'قُرْبَان', 'offrande, pain d''offrande (l''oblation)', 'قُرْبَان est ce qu''on offre à Dieu pour s''approcher de lui : l''offrande, le pain d''oblation. Dans l''usage copte, on parle aussi du « saint qorbân » (الْقُرْبَان الْمُقَدَّس) pour la communion. Le ا est un â long : qur-bân.', '[{"text": "الْقُرْبَانُ عَلَى الْمَذْبَحِ", "translation": "L''offrande est sur l''autel.", "transliteration": "al-qurbânu 3alâ l-madhba7"}, {"text": "قُرْبَانٌ لِلرَّبِّ", "translation": "une offrande pour le Seigneur", "transliteration": "qurbânun li-r-rabb"}]'::jsonb, null, '{"id": "ar.d.qurban", "word": "قُرْبَان", "transliteration": "qurbân", "translation": "offrande, pain d''offrande (l''oblation)", "partOfSpeech": "noun", "explanation": "قُرْبَان est ce qu''on offre à Dieu pour s''approcher de lui : l''offrande, le pain d''oblation. Dans l''usage copte, on parle aussi du « saint qorbân » (الْقُرْبَان الْمُقَدَّس) pour la communion. Le ا est un â long : qur-bân.", "examples": [{"text": "الْقُرْبَانُ عَلَى الْمَذْبَحِ", "translation": "L''offrande est sur l''autel.", "transliteration": "al-qurbânu 3alâ l-madhba7"}, {"text": "قُرْبَانٌ لِلرَّبِّ", "translation": "une offrande pour le Seigneur", "transliteration": "qurbânun li-r-rabb"}], "confusions": [{"word": "قَرِيب", "note": "qarîb, proche : même racine ق ر ب (s''approcher), mais autre mot."}], "unitId": "ar.v.qurban"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.abouna', 'ar', 'أَبُونَا', '« notre père » : le prêtre', 'أَبُونَا veut dire « notre père » (أَبُو + نَا). C''est ainsi que les fidèles appellent leur prêtre, souvent suivi de son nom. Quand on s''adresse à Dieu, on écrit أَبَانَا (abânâ), « Notre Père » (leçon 31).', '[{"text": "أَبُونَا فِي الْهَيْكَلِ", "translation": "Abouna est dans le sanctuaire.", "transliteration": "abûnâ fî l-haykal"}, {"text": "أَبُونَا بُطْرُس", "translation": "Abouna Boutros (le père Pierre)", "transliteration": "abûnâ buTrus"}]'::jsonb, null, '{"id": "ar.d.abouna", "word": "أَبُونَا", "transliteration": "abûnâ", "translation": "« notre père » : le prêtre", "partOfSpeech": "noun", "explanation": "أَبُونَا veut dire « notre père » (أَبُو + نَا). C''est ainsi que les fidèles appellent leur prêtre, souvent suivi de son nom. Quand on s''adresse à Dieu, on écrit أَبَانَا (abânâ), « Notre Père » (leçon 31).", "examples": [{"text": "أَبُونَا فِي الْهَيْكَلِ", "translation": "Abouna est dans le sanctuaire.", "transliteration": "abûnâ fî l-haykal"}, {"text": "أَبُونَا بُطْرُس", "translation": "Abouna Boutros (le père Pierre)", "transliteration": "abûnâ buTrus"}], "confusions": [{"word": "أَب", "note": "ab, un père (leçon 14) : sans le suffixe نَا, c''est « père » tout court."}], "unitId": "ar.v.abouna"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.salib', 'ar', 'صَلِيب', 'croix', 'صَلِيب est la croix. Le ص (S) est une lettre emphatique : on le prononce avec la gorge un peu serrée. Le ـِي est un î long : Sa-lîb. Avec l''article, ص est solaire : aS-Salîb.', '[{"text": "الصَّلِيبُ عَلَى الْمَذْبَحِ", "translation": "La croix est sur l''autel.", "transliteration": "aS-Salîbu 3alâ l-madhba7"}, {"text": "صَلِيبٌ كَبِيرٌ", "translation": "une grande croix", "transliteration": "Salîbun kabîr"}]'::jsonb, null, '{"id": "ar.d.salib", "word": "صَلِيب", "transliteration": "Salîb", "translation": "croix", "partOfSpeech": "noun", "explanation": "صَلِيب est la croix. Le ص (S) est une lettre emphatique : on le prononce avec la gorge un peu serrée. Le ـِي est un î long : Sa-lîb. Avec l''article, ص est solaire : aS-Salîb.", "examples": [{"text": "الصَّلِيبُ عَلَى الْمَذْبَحِ", "translation": "La croix est sur l''autel.", "transliteration": "aS-Salîbu 3alâ l-madhba7"}, {"text": "صَلِيبٌ كَبِيرٌ", "translation": "une grande croix", "transliteration": "Salîbun kabîr"}], "confusions": [{"word": "صَلَاة", "note": "Salât, la prière : même début صَل, mais un ا long et un ة à la fin."}], "forms": {"plural": "صُلْبَان"}, "unitId": "ar.v.salib"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.mawiza', 'ar', 'مَوْعِظَة', 'sermon, homélie', 'مَوْعِظَة est le sermon que le prêtre prononce après l''Évangile. En Égypte, on dit aussi عِظَة (3iZa). Le début مَوْ se lit maw (diphtongue), et le ظ (Z) est une lettre emphatique.', '[{"text": "هٰذِهِ مَوْعِظَةٌ جَمِيلَةٌ", "translation": "C''est un beau sermon.", "transliteration": "hâdhihi maw3iZatun djamîla"}, {"text": "الْمَوْعِظَةُ عَلَى الْجَبَلِ", "translation": "le Sermon sur la montagne", "transliteration": "al-maw3iZatu 3alâ l-djabal"}]'::jsonb, null, '{"id": "ar.d.mawiza", "word": "مَوْعِظَة", "transliteration": "maw3iZa", "translation": "sermon, homélie", "partOfSpeech": "noun", "explanation": "مَوْعِظَة est le sermon que le prêtre prononce après l''Évangile. En Égypte, on dit aussi عِظَة (3iZa). Le début مَوْ se lit maw (diphtongue), et le ظ (Z) est une lettre emphatique.", "examples": [{"text": "هٰذِهِ مَوْعِظَةٌ جَمِيلَةٌ", "translation": "C''est un beau sermon.", "transliteration": "hâdhihi maw3iZatun djamîla"}, {"text": "الْمَوْعِظَةُ عَلَى الْجَبَلِ", "translation": "le Sermon sur la montagne", "transliteration": "al-maw3iZatu 3alâ l-djabal"}], "confusions": [{"word": "عَظْم", "note": "3aZm, l''os (leçon 16) : mêmes lettres ع ظ, mais sans مَوْ ni ة."}], "forms": {"plural": "مَوَاعِظ"}, "unitId": "ar.v.mawiza"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.quddas', 'ar', 'الْقُدَّاس', 'la messe (la divine liturgie)', 'الْقُدَّاس est la divine liturgie, la messe copte, dont le nom vient de la racine ق د س (sainteté). Le د porte une chadda (quddâs) et le ا est long. En arabe, on dit aussi الْقُدَّاس الْإِلٰهِيّ, « la divine liturgie ».', '[{"text": "الْقُدَّاسُ الْإِلٰهِيُّ", "translation": "la divine liturgie", "transliteration": "al-quddâsu l-ilâhiyy"}, {"text": "ذَهَبَ إِلَى الْقُدَّاسِ", "translation": "Il est allé à la messe.", "transliteration": "dhahaba ''ilâ l-quddâs"}]'::jsonb, null, '{"id": "ar.d.quddas", "word": "الْقُدَّاس", "transliteration": "al-quddâs", "translation": "la messe (la divine liturgie)", "partOfSpeech": "noun", "explanation": "الْقُدَّاس est la divine liturgie, la messe copte, dont le nom vient de la racine ق د س (sainteté). Le د porte une chadda (quddâs) et le ا est long. En arabe, on dit aussi الْقُدَّاس الْإِلٰهِيّ, « la divine liturgie ».", "examples": [{"text": "الْقُدَّاسُ الْإِلٰهِيُّ", "translation": "la divine liturgie", "transliteration": "al-quddâsu l-ilâhiyy"}, {"text": "ذَهَبَ إِلَى الْقُدَّاسِ", "translation": "Il est allé à la messe.", "transliteration": "dhahaba ''ilâ l-quddâs"}], "confusions": [{"word": "قُدُّوس", "note": "quddûs, saint (adjectif) : même racine, mais un û long à la fin ; le qoddâs a un â long."}], "forms": {"plural": "قَدَادِيس"}, "unitId": "ar.v.quddas"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.indjil', 'ar', 'الْإِنْجِيل', 'l''Évangile', 'الْإِنْجِيل est l''Évangile, la lecture la plus solennelle du qoddâs, écoutée debout. Le إ (hamza sous l''alif) se lit i, le ج se note dj, et le ي après la kasra est long : in-djîl.', '[{"text": "الْإِنْجِيلُ كِتَابٌ", "translation": "L''Évangile est un livre.", "transliteration": "al-indjîlu kitâb"}, {"text": "الْإِنْجِيلُ عَلَى الْمَذْبَحِ", "translation": "L''Évangile est sur l''autel.", "transliteration": "al-indjîlu 3alâ l-madhba7"}]'::jsonb, null, '{"id": "ar.d.indjil", "word": "الْإِنْجِيل", "transliteration": "al-indjîl", "translation": "l''Évangile", "partOfSpeech": "noun", "explanation": "الْإِنْجِيل est l''Évangile, la lecture la plus solennelle du qoddâs, écoutée debout. Le إ (hamza sous l''alif) se lit i, le ج se note dj, et le ي après la kasra est long : in-djîl.", "examples": [{"text": "الْإِنْجِيلُ كِتَابٌ", "translation": "L''Évangile est un livre.", "transliteration": "al-indjîlu kitâb"}, {"text": "الْإِنْجِيلُ عَلَى الْمَذْبَحِ", "translation": "L''Évangile est sur l''autel.", "transliteration": "al-indjîlu 3alâ l-madhba7"}], "forms": {"plural": "أَنَاجِيل"}, "unitId": "ar.v.indjil"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bulus', 'ar', 'الْبُولُس', 'l''épître de saint Paul (lecture)', 'الْبُولُس est la première lecture du qoddâs : un passage des épîtres de saint Paul (بُولُس). Le ب est lunaire (al-), le ـُو est un û long, et le deuxième u est bref : bû-lus.', '[{"text": "بُولُسُ الرَّسُولُ", "translation": "Paul l''apôtre", "transliteration": "bûlusu r-rasûl"}, {"text": "رِسَالَةُ بُولُسَ", "translation": "l''épître de Paul", "transliteration": "risâlatu bûlusa"}]'::jsonb, null, '{"id": "ar.d.bulus", "word": "الْبُولُس", "transliteration": "al-bûlus", "translation": "l''épître de saint Paul (lecture)", "partOfSpeech": "noun", "explanation": "الْبُولُس est la première lecture du qoddâs : un passage des épîtres de saint Paul (بُولُس). Le ب est lunaire (al-), le ـُو est un û long, et le deuxième u est bref : bû-lus.", "examples": [{"text": "بُولُسُ الرَّسُولُ", "translation": "Paul l''apôtre", "transliteration": "bûlusu r-rasûl"}, {"text": "رِسَالَةُ بُولُسَ", "translation": "l''épître de Paul", "transliteration": "risâlatu bûlusa"}], "confusions": [{"word": "بُطْرُس", "note": "buTrus, Pierre : un autre apôtre, dont les épîtres sont lues dans le كَاثُولِيكُون."}], "unitId": "ar.v.bulus"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.katholikon', 'ar', 'الْكَاثُولِيكُون', 'les épîtres catholiques (lecture)', 'Le كَاثُولِيكُون (du grec « catholique », universel) est la lecture tirée des épîtres catholiques : Jacques, Pierre, Jean et Jude. Il suit le Paulus. Le mot a quatre voyelles longues : kâ-thû-lî-kûn.', '[{"text": "رِسَالَةُ يَعْقُوبَ", "translation": "l''épître de Jacques", "transliteration": "risâlatu ya3qûba"}, {"text": "الْبُولُسُ وَالْكَاثُولِيكُونُ", "translation": "le Paulus et le Catholicon", "transliteration": "al-bûlusu wa-l-kâthûlîkûn"}]'::jsonb, null, '{"id": "ar.d.katholikon", "word": "الْكَاثُولِيكُون", "transliteration": "al-kâthûlîkûn", "translation": "les épîtres catholiques (lecture)", "partOfSpeech": "noun", "explanation": "Le كَاثُولِيكُون (du grec « catholique », universel) est la lecture tirée des épîtres catholiques : Jacques, Pierre, Jean et Jude. Il suit le Paulus. Le mot a quatre voyelles longues : kâ-thû-lî-kûn.", "examples": [{"text": "رِسَالَةُ يَعْقُوبَ", "translation": "l''épître de Jacques", "transliteration": "risâlatu ya3qûba"}, {"text": "الْبُولُسُ وَالْكَاثُولِيكُونُ", "translation": "le Paulus et le Catholicon", "transliteration": "al-bûlusu wa-l-kâthûlîkûn"}], "confusions": [{"word": "كَاثُولِيك", "note": "kâthûlîk, « catholique » (l''Église de Rome) : sans ن final ; le Catholicon, lui, est une lecture de la liturgie copte."}], "unitId": "ar.v.katholikon"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ibraksis', 'ar', 'الْإِبْرَكْسِيس', 'les Actes des Apôtres (lecture)', 'L''Ibraksis (du grec praxis, « actes ») est la lecture tirée des Actes des Apôtres (أَعْمَال الرُّسُل). Un seul son long, à l''avant-dernière syllabe : ib-rak-sîs.', '[{"text": "الْبُولُسُ وَالْإِبْرَكْسِيسُ", "translation": "le Paulus et l''Ibraksis", "transliteration": "al-bûlusu wa-l-ibraksîs"}, {"text": "الْإِبْرَكْسِيسُ مِنْ أَعْمَالِ الرُّسُلِ", "translation": "L''Ibraksis est tiré des Actes des Apôtres.", "transliteration": "al-ibraksîsu min a3mâli r-rusul"}]'::jsonb, null, '{"id": "ar.d.ibraksis", "word": "الْإِبْرَكْسِيس", "transliteration": "al-ibraksîs", "translation": "les Actes des Apôtres (lecture)", "partOfSpeech": "noun", "explanation": "L''Ibraksis (du grec praxis, « actes ») est la lecture tirée des Actes des Apôtres (أَعْمَال الرُّسُل). Un seul son long, à l''avant-dernière syllabe : ib-rak-sîs.", "examples": [{"text": "الْبُولُسُ وَالْإِبْرَكْسِيسُ", "translation": "le Paulus et l''Ibraksis", "transliteration": "al-bûlusu wa-l-ibraksîs"}, {"text": "الْإِبْرَكْسِيسُ مِنْ أَعْمَالِ الرُّسُلِ", "translation": "L''Ibraksis est tiré des Actes des Apôtres.", "transliteration": "al-ibraksîsu min a3mâli r-rusul"}], "unitId": "ar.v.ibraksis"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sinaksar', 'ar', 'السِّنَكْسَار', 'le Synaxaire (la vie des saints du jour)', 'Le سِنَكْسَار (du grec synaxarion) est le livre qui raconte la vie des saints de chaque jour ; on le lit pendant le qoddâs, après l''Ibraksis. س est solaire : as-sinaksâr.', '[{"text": "هٰذَا كِتَابُ السِّنَكْسَارِ", "translation": "C''est le livre du Synaxaire.", "transliteration": "hâdhâ kitâbu s-sinaksâr"}, {"text": "السِّنَكْسَارُ وَالْإِنْجِيلُ", "translation": "le Synaxaire et l''Évangile", "transliteration": "as-sinaksâru wa-l-indjîl"}]'::jsonb, null, '{"id": "ar.d.sinaksar", "word": "السِّنَكْسَار", "transliteration": "as-sinaksâr", "translation": "le Synaxaire (la vie des saints du jour)", "partOfSpeech": "noun", "explanation": "Le سِنَكْسَار (du grec synaxarion) est le livre qui raconte la vie des saints de chaque jour ; on le lit pendant le qoddâs, après l''Ibraksis. س est solaire : as-sinaksâr.", "examples": [{"text": "هٰذَا كِتَابُ السِّنَكْسَارِ", "translation": "C''est le livre du Synaxaire.", "transliteration": "hâdhâ kitâbu s-sinaksâr"}, {"text": "السِّنَكْسَارُ وَالْإِنْجِيلُ", "translation": "le Synaxaire et l''Évangile", "transliteration": "as-sinaksâru wa-l-indjîl"}], "unitId": "ar.v.sinaksar"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.mazmur', 'ar', 'الْمَزْمُور', 'le psaume', 'الْمَزْمُور est un psaume ; le livre entier s''appelle سِفْر الْمَزَامِير, le livre des Psaumes. Au qoddâs, on chante un psaume avant l''Évangile. Le ـُو est un û long : maz-mûr. Le pluriel الْمَزَامِير se lit al-mazâmîr.', '[{"text": "مَزْمُورٌ لِدَاوُدَ", "translation": "un psaume de David", "transliteration": "mazmûrun li-dâwud"}, {"text": "الْمَزَامِيرُ كِتَابٌ", "translation": "Les Psaumes sont un livre.", "transliteration": "al-mazâmîru kitâb"}]'::jsonb, null, '{"id": "ar.d.mazmur", "word": "الْمَزْمُور", "transliteration": "al-mazmûr", "translation": "le psaume", "partOfSpeech": "noun", "explanation": "الْمَزْمُور est un psaume ; le livre entier s''appelle سِفْر الْمَزَامِير, le livre des Psaumes. Au qoddâs, on chante un psaume avant l''Évangile. Le ـُو est un û long : maz-mûr. Le pluriel الْمَزَامِير se lit al-mazâmîr.", "examples": [{"text": "مَزْمُورٌ لِدَاوُدَ", "translation": "un psaume de David", "transliteration": "mazmûrun li-dâwud"}, {"text": "الْمَزَامِيرُ كِتَابٌ", "translation": "Les Psaumes sont un livre.", "transliteration": "al-mazâmîru kitâb"}], "confusions": [{"word": "مِزْمَار", "note": "mizmâr, une flûte : même racine ز م ر, mais un autre mot."}], "forms": {"plural": "مَزَامِير"}, "unitId": "ar.v.mazmur"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.rasul', 'ar', 'رَسُول', 'apôtre', 'رَسُول veut dire « apôtre » (et plus largement « envoyé, messager »). Le pluriel est رُسُل (rusul) : أَعْمَال الرُّسُل = les Actes des Apôtres. Le ـُو est un û long : ra-sûl.', '[{"text": "بُطْرُسُ الرَّسُولُ", "translation": "Pierre l''apôtre", "transliteration": "buTrusu r-rasûl"}, {"text": "أَعْمَالُ الرُّسُلِ", "translation": "les Actes des Apôtres", "transliteration": "a3mâlu r-rusul"}]'::jsonb, null, '{"id": "ar.d.rasul", "word": "رَسُول", "transliteration": "rasûl", "translation": "apôtre", "partOfSpeech": "noun", "explanation": "رَسُول veut dire « apôtre » (et plus largement « envoyé, messager »). Le pluriel est رُسُل (rusul) : أَعْمَال الرُّسُل = les Actes des Apôtres. Le ـُو est un û long : ra-sûl.", "examples": [{"text": "بُطْرُسُ الرَّسُولُ", "translation": "Pierre l''apôtre", "transliteration": "buTrusu r-rasûl"}, {"text": "أَعْمَالُ الرُّسُلِ", "translation": "les Actes des Apôtres", "transliteration": "a3mâlu r-rusul"}], "forms": {"plural": "رُسُل"}, "unitId": "ar.v.rasul"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.tasbiha', 'ar', 'التَّسْبِحَة', 'la tasbiha (office de louange, psalmodie de la nuit)', 'التَّسْبِحَة est la louange chantée à l''église, surtout la tasbiha de nuit (تَسْبِحَة نِصْف اللَّيْل, « la louange de minuit »). ت est solaire : at-tasbi7a ; le ح se note 7 et le ة final se lit a.', '[{"text": "التَّسْبِحَةُ فِي اللَّيْلِ", "translation": "La tasbiha a lieu la nuit.", "transliteration": "at-tasbi7atu fî l-layl"}, {"text": "تَسْبِحَةُ نِصْفِ اللَّيْلِ", "translation": "la louange de minuit", "transliteration": "tasbi7atu niSfi l-layl"}]'::jsonb, null, '{"id": "ar.d.tasbiha", "word": "التَّسْبِحَة", "transliteration": "at-tasbi7a", "translation": "la tasbiha (office de louange, psalmodie de la nuit)", "partOfSpeech": "noun", "explanation": "التَّسْبِحَة est la louange chantée à l''église, surtout la tasbiha de nuit (تَسْبِحَة نِصْف اللَّيْل, « la louange de minuit »). ت est solaire : at-tasbi7a ; le ح se note 7 et le ة final se lit a.", "examples": [{"text": "التَّسْبِحَةُ فِي اللَّيْلِ", "translation": "La tasbiha a lieu la nuit.", "transliteration": "at-tasbi7atu fî l-layl"}, {"text": "تَسْبِحَةُ نِصْفِ اللَّيْلِ", "translation": "la louange de minuit", "transliteration": "tasbi7atu niSfi l-layl"}], "confusions": [{"word": "تَسْبِيحَة", "note": "tasbîha : la forme de l''arabe standard (avec ي) ; dans les livres coptes on lit le plus souvent تَسْبِحَة."}], "forms": {"plural": "تَسَابِيح"}, "unitId": "ar.v.tasbiha"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kitab_muqaddas', 'ar', 'الْكِتَاب الْمُقَدَّس', 'la Bible (le Livre saint)', 'Mot à mot : « le livre le saint ». Le nom (الْكِتَاب, que tu connais depuis la leçon 1) et l''adjectif (الْمُقَدَّس) ont tous deux ال. Le د de مُقَدَّس porte une chadda : mu-qad-das.', '[{"text": "الْكِتَابُ الْمُقَدَّسُ كَبِيرٌ", "translation": "La Bible est grande.", "transliteration": "al-kitâbu l-muqaddasu kabîr"}, {"text": "الْإِنْجِيلُ فِي الْكِتَابِ الْمُقَدَّسِ", "translation": "L''Évangile est dans la Bible.", "transliteration": "al-indjîlu fî l-kitâbi l-muqaddas"}]'::jsonb, null, '{"id": "ar.d.kitab_muqaddas", "word": "الْكِتَاب الْمُقَدَّس", "transliteration": "al-kitâb al-muqaddas", "translation": "la Bible (le Livre saint)", "partOfSpeech": "expression", "explanation": "Mot à mot : « le livre le saint ». Le nom (الْكِتَاب, que tu connais depuis la leçon 1) et l''adjectif (الْمُقَدَّس) ont tous deux ال. Le د de مُقَدَّس porte une chadda : mu-qad-das.", "examples": [{"text": "الْكِتَابُ الْمُقَدَّسُ كَبِيرٌ", "translation": "La Bible est grande.", "transliteration": "al-kitâbu l-muqaddasu kabîr"}, {"text": "الْإِنْجِيلُ فِي الْكِتَابِ الْمُقَدَّسِ", "translation": "L''Évangile est dans la Bible.", "transliteration": "al-indjîlu fî l-kitâbi l-muqaddas"}], "confusions": [{"word": "كِتَابٌ مُقَدَّسٌ", "note": "kitâbun muqaddas, « un livre saint » : sans ال, c''est un groupe indéfini."}], "unitId": "ar.v.kitab_muqaddas"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ahd_qadim', 'ar', 'الْعَهْد الْقَدِيم', 'l''Ancien Testament', 'عَهْد veut dire « alliance, testament ». L''Ancien Testament, c''est « l''alliance l''ancienne » : nom + adjectif, tous deux avec ال. Les deux mots sont lunaires : al-3ahd, al-qadîm.', '[{"text": "النُّبُوَّاتُ فِي الْعَهْدِ الْقَدِيمِ", "translation": "Les prophéties sont dans l''Ancien Testament.", "transliteration": "an-nubuwwâtu fî l-3ahdi l-qadîm"}, {"text": "الْمَزَامِيرُ فِي الْعَهْدِ الْقَدِيمِ", "translation": "Les Psaumes sont dans l''Ancien Testament.", "transliteration": "al-mazâmîru fî l-3ahdi l-qadîm"}]'::jsonb, null, '{"id": "ar.d.ahd_qadim", "word": "الْعَهْد الْقَدِيم", "transliteration": "al-3ahd al-qadîm", "translation": "l''Ancien Testament", "partOfSpeech": "expression", "explanation": "عَهْد veut dire « alliance, testament ». L''Ancien Testament, c''est « l''alliance l''ancienne » : nom + adjectif, tous deux avec ال. Les deux mots sont lunaires : al-3ahd, al-qadîm.", "examples": [{"text": "النُّبُوَّاتُ فِي الْعَهْدِ الْقَدِيمِ", "translation": "Les prophéties sont dans l''Ancien Testament.", "transliteration": "an-nubuwwâtu fî l-3ahdi l-qadîm"}, {"text": "الْمَزَامِيرُ فِي الْعَهْدِ الْقَدِيمِ", "translation": "Les Psaumes sont dans l''Ancien Testament.", "transliteration": "al-mazâmîru fî l-3ahdi l-qadîm"}], "confusions": [{"word": "الْعَهْد الْجَدِيد", "note": "al-3ahd al-djadîd, le Nouveau Testament : l''adjectif contraire."}], "unitId": "ar.v.ahd_qadim"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ahd_djadid', 'ar', 'الْعَهْد الْجَدِيد', 'le Nouveau Testament', '« L''alliance la nouvelle » : même construction que l''Ancien Testament, avec جَدِيد (nouveau, leçon 23). Le Nouveau Testament contient les Évangiles, les Actes et les épîtres.', '[{"text": "الْإِنْجِيلُ فِي الْعَهْدِ الْجَدِيدِ", "translation": "L''Évangile est dans le Nouveau Testament.", "transliteration": "al-indjîlu fî l-3ahdi l-djadîd"}, {"text": "رِسَالَةُ بُولُسَ فِي الْعَهْدِ الْجَدِيدِ", "translation": "L''épître de Paul est dans le Nouveau Testament.", "transliteration": "risâlatu bûlusa fî l-3ahdi l-djadîd"}]'::jsonb, null, '{"id": "ar.d.ahd_djadid", "word": "الْعَهْد الْجَدِيد", "transliteration": "al-3ahd al-djadîd", "translation": "le Nouveau Testament", "partOfSpeech": "expression", "explanation": "« L''alliance la nouvelle » : même construction que l''Ancien Testament, avec جَدِيد (nouveau, leçon 23). Le Nouveau Testament contient les Évangiles, les Actes et les épîtres.", "examples": [{"text": "الْإِنْجِيلُ فِي الْعَهْدِ الْجَدِيدِ", "translation": "L''Évangile est dans le Nouveau Testament.", "transliteration": "al-indjîlu fî l-3ahdi l-djadîd"}, {"text": "رِسَالَةُ بُولُسَ فِي الْعَهْدِ الْجَدِيدِ", "translation": "L''épître de Paul est dans le Nouveau Testament.", "transliteration": "risâlatu bûlusa fî l-3ahdi l-djadîd"}], "confusions": [{"word": "الْعَهْد الْقَدِيم", "note": "al-3ahd al-qadîm, l''Ancien Testament : le contraire."}], "unitId": "ar.v.ahd_djadid"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.nebowat', 'ar', 'النُّبُوَّات', 'les prophéties (lectures de l''Ancien Testament)', 'النُّبُوَّات (« nebowat » en prononciation égyptienne) sont les prophéties : des lectures de l''Ancien Testament, surtout pendant la Semaine sainte et à la veille des grandes fêtes. C''est le pluriel en ـَات de نُبُوَّة. ن est solaire (an-) et le و est doublé : nu-bu-wwât.', '[{"text": "هٰذِهِ نُبُوَّةٌ", "translation": "C''est une prophétie.", "transliteration": "hâdhihi nubuwwa"}, {"text": "النُّبُوَّاتُ كَثِيرَةٌ", "translation": "Les prophéties sont nombreuses.", "transliteration": "an-nubuwwâtu kathîra"}]'::jsonb, null, '{"id": "ar.d.nebowat", "word": "النُّبُوَّات", "transliteration": "an-nubuwwât", "translation": "les prophéties (lectures de l''Ancien Testament)", "partOfSpeech": "noun", "explanation": "النُّبُوَّات (« nebowat » en prononciation égyptienne) sont les prophéties : des lectures de l''Ancien Testament, surtout pendant la Semaine sainte et à la veille des grandes fêtes. C''est le pluriel en ـَات de نُبُوَّة. ن est solaire (an-) et le و est doublé : nu-bu-wwât.", "examples": [{"text": "هٰذِهِ نُبُوَّةٌ", "translation": "C''est une prophétie.", "transliteration": "hâdhihi nubuwwa"}, {"text": "النُّبُوَّاتُ كَثِيرَةٌ", "translation": "Les prophéties sont nombreuses.", "transliteration": "an-nubuwwâtu kathîra"}], "confusions": [{"word": "نَبِيّ", "note": "nabiyy, le prophète : de la même famille."}], "forms": {"singulier": "نُبُوَّة"}, "unitId": "ar.v.nebowat"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.nabi', 'ar', 'نَبِيّ', 'prophète', 'نَبِيّ est un prophète (David, Isaïe, Daniel…). Le ي final porte une chadda : nabiyy. Le pluriel est أَنْبِيَاء (anbiyâ''), avec une hamza finale.', '[{"text": "النَّبِيُّ دَاوُدُ", "translation": "le prophète David", "transliteration": "an-nabiyyu dâwud"}, {"text": "أَنْبِيَاءُ الْعَهْدِ الْقَدِيمِ", "translation": "les prophètes de l''Ancien Testament", "transliteration": "anbiyâ''u l-3ahdi l-qadîm"}]'::jsonb, null, '{"id": "ar.d.nabi", "word": "نَبِيّ", "transliteration": "nabiyy", "translation": "prophète", "partOfSpeech": "noun", "explanation": "نَبِيّ est un prophète (David, Isaïe, Daniel…). Le ي final porte une chadda : nabiyy. Le pluriel est أَنْبِيَاء (anbiyâ''), avec une hamza finale.", "examples": [{"text": "النَّبِيُّ دَاوُدُ", "translation": "le prophète David", "transliteration": "an-nabiyyu dâwud"}, {"text": "أَنْبِيَاءُ الْعَهْدِ الْقَدِيمِ", "translation": "les prophètes de l''Ancien Testament", "transliteration": "anbiyâ''u l-3ahdi l-qadîm"}], "confusions": [{"word": "نُبُوَّة", "note": "nubuwwa, la prophétie : de la même famille."}], "forms": {"plural": "أَنْبِيَاء"}, "unitId": "ar.v.nabi"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sifr', 'ar', 'سِفْر', 'livre (de la Bible)', 'سِفْر est un des livres qui composent la Bible : سِفْر التَّكْوِين (la Genèse), سِفْر الْمَزَامِير (le livre des Psaumes). Pour un livre ordinaire, on dit كِتَاب. Le pluriel est أَسْفَار.', '[{"text": "سِفْرُ التَّكْوِينِ", "translation": "le livre de la Genèse", "transliteration": "sifru t-takwîn"}, {"text": "سِفْرُ الْمَزَامِيرِ", "translation": "le livre des Psaumes", "transliteration": "sifru l-mazâmîr"}]'::jsonb, null, '{"id": "ar.d.sifr", "word": "سِفْر", "transliteration": "sifr", "translation": "livre (de la Bible)", "partOfSpeech": "noun", "explanation": "سِفْر est un des livres qui composent la Bible : سِفْر التَّكْوِين (la Genèse), سِفْر الْمَزَامِير (le livre des Psaumes). Pour un livre ordinaire, on dit كِتَاب. Le pluriel est أَسْفَار.", "examples": [{"text": "سِفْرُ التَّكْوِينِ", "translation": "le livre de la Genèse", "transliteration": "sifru t-takwîn"}, {"text": "سِفْرُ الْمَزَامِيرِ", "translation": "le livre des Psaumes", "transliteration": "sifru l-mazâmîr"}], "confusions": [{"word": "سَفَر", "note": "safar, le voyage : mêmes lettres س ف ر, mais deux fathas."}, {"word": "كِتَاب", "note": "kitâb, un livre en général (leçon 1)."}], "forms": {"plural": "أَسْفَار"}, "unitId": "ar.v.sifr"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bichara', 'ar', 'الْبِشَارَة', 'l''Annonciation, la Bonne Nouvelle', 'بِشَارَة veut dire « bonne nouvelle ». Avec ال, الْبِشَارَة est l''Annonciation : عِيد الْبِشَارَة est la fête où l''ange annonce à la Vierge la naissance de Jésus. Le ا est long (bi-châ-ra) et le ة final se lit a.', '[{"text": "هٰذِهِ بِشَارَةٌ", "translation": "C''est une bonne nouvelle.", "transliteration": "hâdhihi bichâra"}, {"text": "عِيدُ الْبِشَارَةِ", "translation": "la fête de l''Annonciation", "transliteration": "3îdu l-bichâra"}]'::jsonb, null, '{"id": "ar.d.bichara", "word": "الْبِشَارَة", "transliteration": "al-bichâra", "translation": "l''Annonciation, la Bonne Nouvelle", "partOfSpeech": "noun", "explanation": "بِشَارَة veut dire « bonne nouvelle ». Avec ال, الْبِشَارَة est l''Annonciation : عِيد الْبِشَارَة est la fête où l''ange annonce à la Vierge la naissance de Jésus. Le ا est long (bi-châ-ra) et le ة final se lit a.", "examples": [{"text": "هٰذِهِ بِشَارَةٌ", "translation": "C''est une bonne nouvelle.", "transliteration": "hâdhihi bichâra"}, {"text": "عِيدُ الْبِشَارَةِ", "translation": "la fête de l''Annonciation", "transliteration": "3îdu l-bichâra"}], "confusions": [{"word": "بَشَر", "note": "bachar, les êtres humains : même début, autre mot."}], "unitId": "ar.v.bichara"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.aya', 'ar', 'آيَة', 'verset', 'آيَة est un verset de la Bible : on la cite avec son chapitre et son numéro. Le آ (alif madda) vaut hamza + â long. Le ة final se lit a ; au pluriel on dit آيَات (âyât).', '[{"text": "هٰذِهِ آيَةٌ جَمِيلَةٌ", "translation": "C''est un beau verset.", "transliteration": "hâdhihi âyatun djamîla"}, {"text": "آيَاتٌ مِنَ الْإِنْجِيلِ", "translation": "des versets de l''Évangile", "transliteration": "âyâtun mina l-indjîl"}]'::jsonb, null, '{"id": "ar.d.aya", "word": "آيَة", "transliteration": "âya", "translation": "verset", "partOfSpeech": "noun", "explanation": "آيَة est un verset de la Bible : on la cite avec son chapitre et son numéro. Le آ (alif madda) vaut hamza + â long. Le ة final se lit a ; au pluriel on dit آيَات (âyât).", "examples": [{"text": "هٰذِهِ آيَةٌ جَمِيلَةٌ", "translation": "C''est un beau verset.", "transliteration": "hâdhihi âyatun djamîla"}, {"text": "آيَاتٌ مِنَ الْإِنْجِيلِ", "translation": "des versets de l''Évangile", "transliteration": "âyâtun mina l-indjîl"}], "forms": {"plural": "آيَات"}, "unitId": "ar.v.aya"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ashah', 'ar', 'أَصْحَاح', 'chapitre (de la Bible)', 'أَصْحَاح est un chapitre de la Bible ; on écrit aussi إِصْحَاح, avec une kasra au début. Les chapitres se comptent : الْأَصْحَاح الْأَوَّل = le premier chapitre. Le ص est emphatique (S) et les ح sont sans point (7).', '[{"text": "الْأَصْحَاحُ الْأَوَّلُ", "translation": "le premier chapitre", "transliteration": "al-aS7â7u l-awwal"}, {"text": "أَصْحَاحٌ مِنَ الْإِنْجِيلِ", "translation": "un chapitre de l''Évangile", "transliteration": "aS7â7un mina l-indjîl"}]'::jsonb, null, '{"id": "ar.d.ashah", "word": "أَصْحَاح", "transliteration": "aS7â7", "translation": "chapitre (de la Bible)", "partOfSpeech": "noun", "explanation": "أَصْحَاح est un chapitre de la Bible ; on écrit aussi إِصْحَاح, avec une kasra au début. Les chapitres se comptent : الْأَصْحَاح الْأَوَّل = le premier chapitre. Le ص est emphatique (S) et les ح sont sans point (7).", "examples": [{"text": "الْأَصْحَاحُ الْأَوَّلُ", "translation": "le premier chapitre", "transliteration": "al-aS7â7u l-awwal"}, {"text": "أَصْحَاحٌ مِنَ الْإِنْجِيلِ", "translation": "un chapitre de l''Évangile", "transliteration": "aS7â7un mina l-indjîl"}], "confusions": [{"word": "صَحِيح", "note": "Sa7î7, correct, exact : mêmes consonnes ص ح ح, mais d''autres voyelles."}], "unitId": "ar.v.ashah"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.eid', 'ar', 'عِيد', 'fête', 'عِيد est une fête (un jour de fête de l''Église). C''est le premier mot de presque tous les noms de fêtes : عِيد الْمِيلَاد, عِيد الْقِيَامَة… Dans une annexion, il n''a jamais ال. Le ع (3) vient du fond de la gorge ; le ي après la kasra est un î long. Pluriel : أَعْيَاد.', '[{"text": "عِيدُ الْكَنِيسَةِ", "translation": "la fête de l''église", "transliteration": "3îdu l-kanîsa"}, {"text": "الْعِيدُ جَمِيلٌ", "translation": "La fête est belle.", "transliteration": "al-3îdu djamîl"}]'::jsonb, null, '{"id": "ar.d.eid", "word": "عِيد", "transliteration": "3îd", "translation": "fête", "partOfSpeech": "noun", "explanation": "عِيد est une fête (un jour de fête de l''Église). C''est le premier mot de presque tous les noms de fêtes : عِيد الْمِيلَاد, عِيد الْقِيَامَة… Dans une annexion, il n''a jamais ال. Le ع (3) vient du fond de la gorge ; le ي après la kasra est un î long. Pluriel : أَعْيَاد.", "examples": [{"text": "عِيدُ الْكَنِيسَةِ", "translation": "la fête de l''église", "transliteration": "3îdu l-kanîsa"}, {"text": "الْعِيدُ جَمِيلٌ", "translation": "La fête est belle.", "transliteration": "al-3îdu djamîl"}], "forms": {"plural": "أَعْيَاد"}, "unitId": "ar.v.eid"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.eid_al_milad', 'ar', 'عِيد الْمِيلَاد', 'Noël (la fête de la Nativité)', 'Annexion : « fête de la Nativité ». الْمِيلَاد (la naissance) est lunaire : al-mîlâd. Dans l''Église copte, Noël se fête le 7 janvier. On dit souvent عِيد الْمِيلَاد الْمَجِيد, « la glorieuse fête de la Nativité ».', '[{"text": "عِيدُ الْمِيلَادِ الْمَجِيدُ", "translation": "la glorieuse fête de la Nativité", "transliteration": "3îdu l-mîlâdi l-madjîd"}, {"text": "هٰذَا عِيدُ الْمِيلَادِ", "translation": "C''est la fête de la Nativité.", "transliteration": "hâdhâ 3îdu l-mîlâd"}]'::jsonb, null, '{"id": "ar.d.eid_al_milad", "word": "عِيد الْمِيلَاد", "transliteration": "3îd al-mîlâd", "translation": "Noël (la fête de la Nativité)", "partOfSpeech": "expression", "explanation": "Annexion : « fête de la Nativité ». الْمِيلَاد (la naissance) est lunaire : al-mîlâd. Dans l''Église copte, Noël se fête le 7 janvier. On dit souvent عِيد الْمِيلَاد الْمَجِيد, « la glorieuse fête de la Nativité ».", "examples": [{"text": "عِيدُ الْمِيلَادِ الْمَجِيدُ", "translation": "la glorieuse fête de la Nativité", "transliteration": "3îdu l-mîlâdi l-madjîd"}, {"text": "هٰذَا عِيدُ الْمِيلَادِ", "translation": "C''est la fête de la Nativité.", "transliteration": "hâdhâ 3îdu l-mîlâd"}], "confusions": [{"word": "عِيد مِيلَاد", "note": "3îd mîlâd, un anniversaire : sans ال sur le second mot, c''est « une fête de naissance »."}], "unitId": "ar.v.eid_al_milad"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.eid_al_qiyama', 'ar', 'عِيد الْقِيَامَة', 'Pâques (la fête de la Résurrection)', 'Annexion : « fête de la Résurrection ». C''est la plus grande fête de l''Église copte. الْقِيَامَة (de la racine ق و م, « se lever ») est lunaire ; le ة final se lit a. Le salut de Pâques est الْمَسِيحُ قَامَ, « le Christ est ressuscité ».', '[{"text": "عِيدُ الْقِيَامَةِ الْمَجِيدُ", "translation": "la glorieuse fête de la Résurrection", "transliteration": "3îdu l-qiyâmati l-madjîd"}, {"text": "الْمَسِيحُ قَامَ", "translation": "Le Christ est ressuscité.", "transliteration": "al-masî7u qâm"}]'::jsonb, null, '{"id": "ar.d.eid_al_qiyama", "word": "عِيد الْقِيَامَة", "transliteration": "3îd al-qiyâma", "translation": "Pâques (la fête de la Résurrection)", "partOfSpeech": "expression", "explanation": "Annexion : « fête de la Résurrection ». C''est la plus grande fête de l''Église copte. الْقِيَامَة (de la racine ق و م, « se lever ») est lunaire ; le ة final se lit a. Le salut de Pâques est الْمَسِيحُ قَامَ, « le Christ est ressuscité ».", "examples": [{"text": "عِيدُ الْقِيَامَةِ الْمَجِيدُ", "translation": "la glorieuse fête de la Résurrection", "transliteration": "3îdu l-qiyâmati l-madjîd"}, {"text": "الْمَسِيحُ قَامَ", "translation": "Le Christ est ressuscité.", "transliteration": "al-masî7u qâm"}], "confusions": [{"word": "قِيَام", "note": "qiyâm, le fait de se lever, de se tenir debout : sans ة, le même début."}], "unitId": "ar.v.eid_al_qiyama"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ghitas', 'ar', 'الْغِطَاس', 'l''Épiphanie (fête du Baptême du Christ)', 'الْغِطَاس est la fête du Baptême de Jésus dans le Jourdain, l''Épiphanie, célébrée le 19 janvier dans l''Église copte. Le mot vient de غَطَسَ (plonger, s''immerger). Le غ (gh) est une lettre de la gorge, le ط (T) est emphatique et le ا est long. On dit aussi عِيد الْغِطَاس.', '[{"text": "عِيدُ الْغِطَاسِ", "translation": "la fête de l''Épiphanie", "transliteration": "3îdu l-ghiTâs"}, {"text": "عِيدُ الْغِطَاسِ بَعْدَ عِيدِ الْمِيلَادِ", "translation": "L''Épiphanie vient après Noël.", "transliteration": "3îdu l-ghiTâsi ba3da 3îdi l-mîlâd"}]'::jsonb, null, '{"id": "ar.d.ghitas", "word": "الْغِطَاس", "transliteration": "al-ghiTâs", "translation": "l''Épiphanie (fête du Baptême du Christ)", "partOfSpeech": "noun", "explanation": "الْغِطَاس est la fête du Baptême de Jésus dans le Jourdain, l''Épiphanie, célébrée le 19 janvier dans l''Église copte. Le mot vient de غَطَسَ (plonger, s''immerger). Le غ (gh) est une lettre de la gorge, le ط (T) est emphatique et le ا est long. On dit aussi عِيد الْغِطَاس.", "examples": [{"text": "عِيدُ الْغِطَاسِ", "translation": "la fête de l''Épiphanie", "transliteration": "3îdu l-ghiTâs"}, {"text": "عِيدُ الْغِطَاسِ بَعْدَ عِيدِ الْمِيلَادِ", "translation": "L''Épiphanie vient après Noël.", "transliteration": "3îdu l-ghiTâsi ba3da 3îdi l-mîlâd"}], "confusions": [{"word": "عِيد الْمِيلَاد", "note": "3îd al-mîlâd, Noël : la fête qui précède."}], "unitId": "ar.v.ghitas"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ahad_al_chaanin', 'ar', 'أَحَد الشَّعَانِين', 'le dimanche des Rameaux', 'Annexion : « dimanche des Rameaux ». أَحَد est le dimanche (et aussi « un »). الشَّعَانِين vient de « hosanna » : ش est solaire, ach-cha3ânîn. Ce dimanche ouvre la Semaine sainte.', '[{"text": "هٰذَا أَحَدُ الشَّعَانِينِ", "translation": "C''est le dimanche des Rameaux.", "transliteration": "hâdhâ a7adu ch-cha3ânîn"}, {"text": "أَحَدُ الشَّعَانِينِ قَبْلَ عِيدِ الْقِيَامَةِ", "translation": "Le dimanche des Rameaux vient avant Pâques.", "transliteration": "a7adu ch-cha3ânîni qabla 3îdi l-qiyâma"}]'::jsonb, null, '{"id": "ar.d.ahad_al_chaanin", "word": "أَحَد الشَّعَانِين", "transliteration": "a7ad ach-cha3ânîn", "translation": "le dimanche des Rameaux", "partOfSpeech": "expression", "explanation": "Annexion : « dimanche des Rameaux ». أَحَد est le dimanche (et aussi « un »). الشَّعَانِين vient de « hosanna » : ش est solaire, ach-cha3ânîn. Ce dimanche ouvre la Semaine sainte.", "examples": [{"text": "هٰذَا أَحَدُ الشَّعَانِينِ", "translation": "C''est le dimanche des Rameaux.", "transliteration": "hâdhâ a7adu ch-cha3ânîn"}, {"text": "أَحَدُ الشَّعَانِينِ قَبْلَ عِيدِ الْقِيَامَةِ", "translation": "Le dimanche des Rameaux vient avant Pâques.", "transliteration": "a7adu ch-cha3ânîni qabla 3îdi l-qiyâma"}], "confusions": [{"word": "أَحَد", "note": "a7ad, « un » (quelqu''un) ; avec ال, الْأَحَد est le dimanche."}], "unitId": "ar.v.ahad_al_chaanin"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sawm_kabir', 'ar', 'الصَّوْم الْكَبِير', 'le Grand Carême', 'Attention : ce n''est pas une annexion mais un nom + un adjectif, donc ال sur les deux mots. الصَّوْم (le jeûne) commence par ص solaire et ـَوْ est la diphtongue aw ; الْكَبِير veut dire « grand ». Le Grand Carême précède Pâques.', '[{"text": "هٰذَا هُوَ الصَّوْمُ الْكَبِيرُ", "translation": "Voici le Grand Carême.", "transliteration": "hâdhâ huwa S-Sawmu l-kabîr"}, {"text": "الصَّوْمُ الْكَبِيرُ قَبْلَ عِيدِ الْقِيَامَةِ", "translation": "Le Grand Carême vient avant Pâques.", "transliteration": "aS-Sawmu l-kabîru qabla 3îdi l-qiyâma"}]'::jsonb, null, '{"id": "ar.d.sawm_kabir", "word": "الصَّوْم الْكَبِير", "transliteration": "aS-Sawm al-kabîr", "translation": "le Grand Carême", "partOfSpeech": "expression", "explanation": "Attention : ce n''est pas une annexion mais un nom + un adjectif, donc ال sur les deux mots. الصَّوْم (le jeûne) commence par ص solaire et ـَوْ est la diphtongue aw ; الْكَبِير veut dire « grand ». Le Grand Carême précède Pâques.", "examples": [{"text": "هٰذَا هُوَ الصَّوْمُ الْكَبِيرُ", "translation": "Voici le Grand Carême.", "transliteration": "hâdhâ huwa S-Sawmu l-kabîr"}, {"text": "الصَّوْمُ الْكَبِيرُ قَبْلَ عِيدِ الْقِيَامَةِ", "translation": "Le Grand Carême vient avant Pâques.", "transliteration": "aS-Sawmu l-kabîru qabla 3îdi l-qiyâma"}], "confusions": [{"word": "صَوْم الْمِيلَاد", "note": "Sawm al-mîlâd, le jeûne de la Nativité : ici c''est une annexion (le premier nom n''a pas ال)."}], "unitId": "ar.v.sawm_kabir"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.usbu_al_alam', 'ar', 'أُسْبُوع الْآلَام', 'la Semaine sainte (semaine de la Passion)', 'Annexion : « semaine des souffrances ». أُسْبُوع = semaine ; الْآلَام = les souffrances, la Passion (آ = alif madda, al-âlâm). On dit aussi الْبَصْخَة (al-baSkha) pour la Semaine sainte.', '[{"text": "النُّبُوَّاتُ فِي أُسْبُوعِ الْآلَامِ", "translation": "les prophéties de la Semaine sainte", "transliteration": "an-nubuwwâtu fî usbû3i l-âlâm"}, {"text": "أُسْبُوعُ الْآلَامِ قَبْلَ عِيدِ الْقِيَامَةِ", "translation": "La Semaine sainte précède Pâques.", "transliteration": "usbû3u l-âlâmi qabla 3îdi l-qiyâma"}]'::jsonb, null, '{"id": "ar.d.usbu_al_alam", "word": "أُسْبُوع الْآلَام", "transliteration": "usbû3 al-âlâm", "translation": "la Semaine sainte (semaine de la Passion)", "partOfSpeech": "expression", "explanation": "Annexion : « semaine des souffrances ». أُسْبُوع = semaine ; الْآلَام = les souffrances, la Passion (آ = alif madda, al-âlâm). On dit aussi الْبَصْخَة (al-baSkha) pour la Semaine sainte.", "examples": [{"text": "النُّبُوَّاتُ فِي أُسْبُوعِ الْآلَامِ", "translation": "les prophéties de la Semaine sainte", "transliteration": "an-nubuwwâtu fî usbû3i l-âlâm"}, {"text": "أُسْبُوعُ الْآلَامِ قَبْلَ عِيدِ الْقِيَامَةِ", "translation": "La Semaine sainte précède Pâques.", "transliteration": "usbû3u l-âlâmi qabla 3îdi l-qiyâma"}], "confusions": [{"word": "أَلَم", "note": "alam, une douleur : le singulier de الْآلَام (« les douleurs »)."}], "forms": {"plural": "أَسَابِيع"}, "unitId": "ar.v.usbu_al_alam"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.khamasin', 'ar', 'الْخَمَاسِين', 'les cinquante jours après Pâques', 'الْخَمَاسِين vient de خَمْسُون (cinquante) : ce sont les cinquante jours de joie entre Pâques et la Pentecôte, sans jeûne. En Égypte, le même mot désigne aussi un vent chaud et sec du printemps.', '[{"text": "الْخَمَاسِينُ بَعْدَ عِيدِ الْقِيَامَةِ", "translation": "Les Cinquante jours viennent après Pâques.", "transliteration": "al-khamâsînu ba3da 3îdi l-qiyâma"}, {"text": "أَيَّامُ الْخَمَاسِينِ", "translation": "les jours des Cinquante jours", "transliteration": "ayyâmu l-khamâsîn"}]'::jsonb, null, '{"id": "ar.d.khamasin", "word": "الْخَمَاسِين", "transliteration": "al-khamâsîn", "translation": "les cinquante jours après Pâques", "partOfSpeech": "noun", "explanation": "الْخَمَاسِين vient de خَمْسُون (cinquante) : ce sont les cinquante jours de joie entre Pâques et la Pentecôte, sans jeûne. En Égypte, le même mot désigne aussi un vent chaud et sec du printemps.", "examples": [{"text": "الْخَمَاسِينُ بَعْدَ عِيدِ الْقِيَامَةِ", "translation": "Les Cinquante jours viennent après Pâques.", "transliteration": "al-khamâsînu ba3da 3îdi l-qiyâma"}, {"text": "أَيَّامُ الْخَمَاسِينِ", "translation": "les jours des Cinquante jours", "transliteration": "ayyâmu l-khamâsîn"}], "confusions": [{"word": "خَمْسُون", "note": "khamsûn, cinquante : le nombre, avec un soukoun sur le م."}], "unitId": "ar.v.khamasin"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sawm', 'ar', 'صَوْم', 'jeûne', 'صَوْم est le jeûne, une période d''abstinence. On dit aussi صِيَام (Siyâm). Premier mot d''annexion : صَوْم الْمِيلَاد (le jeûne de la Nativité), صَوْم الرُّسُل (le jeûne des Apôtres). Le ص est emphatique (S) et ـَوْ est la diphtongue aw.', '[{"text": "صَوْمُ الْمِيلَادِ", "translation": "le jeûne de la Nativité", "transliteration": "Sawmu l-mîlâd"}, {"text": "صَوْمُ الرُّسُلِ", "translation": "le jeûne des Apôtres", "transliteration": "Sawmu r-rusul"}]'::jsonb, null, '{"id": "ar.d.sawm", "word": "صَوْم", "transliteration": "Sawm", "translation": "jeûne", "partOfSpeech": "noun", "explanation": "صَوْم est le jeûne, une période d''abstinence. On dit aussi صِيَام (Siyâm). Premier mot d''annexion : صَوْم الْمِيلَاد (le jeûne de la Nativité), صَوْم الرُّسُل (le jeûne des Apôtres). Le ص est emphatique (S) et ـَوْ est la diphtongue aw.", "examples": [{"text": "صَوْمُ الْمِيلَادِ", "translation": "le jeûne de la Nativité", "transliteration": "Sawmu l-mîlâd"}, {"text": "صَوْمُ الرُّسُلِ", "translation": "le jeûne des Apôtres", "transliteration": "Sawmu r-rusul"}], "confusions": [{"word": "صَوْت", "note": "Sawt, la voix : même début صَوْ, mais finit par ت."}], "unitId": "ar.v.sawm"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.qiddis', 'ar', 'قِدِّيس', 'saint', 'قِدِّيس désigne une personne sainte, un saint : le د porte une chadda, on lit qid-dîs. Le féminin est قِدِّيسَة (qiddîsa). Pour Dieu, on dit plutôt قُدُّوس (leçon 31).', '[{"text": "الْقِدِّيسُ مَرْقُسُ الرَّسُولُ", "translation": "saint Marc l''apôtre", "transliteration": "al-qiddîsu marqusu r-rasûl"}, {"text": "قِدِّيسٌ وَشَهِيدٌ", "translation": "un saint et martyr", "transliteration": "qiddîsun wa-chahîd"}]'::jsonb, null, '{"id": "ar.d.qiddis", "word": "قِدِّيس", "transliteration": "qiddîs", "translation": "saint", "partOfSpeech": "noun", "explanation": "قِدِّيس désigne une personne sainte, un saint : le د porte une chadda, on lit qid-dîs. Le féminin est قِدِّيسَة (qiddîsa). Pour Dieu, on dit plutôt قُدُّوس (leçon 31).", "examples": [{"text": "الْقِدِّيسُ مَرْقُسُ الرَّسُولُ", "translation": "saint Marc l''apôtre", "transliteration": "al-qiddîsu marqusu r-rasûl"}, {"text": "قِدِّيسٌ وَشَهِيدٌ", "translation": "un saint et martyr", "transliteration": "qiddîsun wa-chahîd"}], "confusions": [{"word": "قُدُّوس", "note": "quddûs, saint (dit de Dieu) : une damma et un û long ; qiddîs désigne un saint."}], "forms": {"féminin": "قِدِّيسَة", "plural": "قِدِّيسُون"}, "unitId": "ar.v.qiddis"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.chahid', 'ar', 'شَهِيد', 'martyr', 'شَهِيد est le martyr, celui qui a donné sa vie pour le Christ ; le mot veut aussi dire « témoin ». Le pluriel est شُهَدَاء (chuhadâ''), avec une hamza finale. Le calendrier copte est aussi appelé « calendrier des Martyrs ».', '[{"text": "مَارْ جِرْجِسُ شَهِيدٌ", "translation": "Saint Georges est un martyr.", "transliteration": "mâr djirdjisu chahîd"}, {"text": "تَقْوِيمُ الشُّهَدَاءِ", "translation": "le calendrier des Martyrs (le calendrier copte)", "transliteration": "taqwîmu ch-chuhadâ''"}]'::jsonb, null, '{"id": "ar.d.chahid", "word": "شَهِيد", "transliteration": "chahîd", "translation": "martyr", "partOfSpeech": "noun", "explanation": "شَهِيد est le martyr, celui qui a donné sa vie pour le Christ ; le mot veut aussi dire « témoin ». Le pluriel est شُهَدَاء (chuhadâ''), avec une hamza finale. Le calendrier copte est aussi appelé « calendrier des Martyrs ».", "examples": [{"text": "مَارْ جِرْجِسُ شَهِيدٌ", "translation": "Saint Georges est un martyr.", "transliteration": "mâr djirdjisu chahîd"}, {"text": "تَقْوِيمُ الشُّهَدَاءِ", "translation": "le calendrier des Martyrs (le calendrier copte)", "transliteration": "taqwîmu ch-chuhadâ''"}], "confusions": [{"word": "شَاهِد", "note": "châhid, un témoin : même racine ش ه د, mais un â long au lieu du î."}], "forms": {"plural": "شُهَدَاء"}, "unitId": "ar.v.chahid"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.adhra_maryam', 'ar', 'الْعَذْرَاء مَرْيَم', 'la Vierge Marie', 'الْعَذْرَاء (la vierge) accompagne le nom de Marie, مَرْيَم. La hamza finale se prononce : al-3adhrâ''. Les Coptes disent aussi السَّيِّدَة الْعَذْرَاء (Notre-Dame la Vierge) ou وَالِدَة الْإِلٰه (la Mère de Dieu).', '[{"text": "أَيْقُونَةُ الْعَذْرَاءِ مَرْيَمَ", "translation": "l''icône de la Vierge Marie", "transliteration": "ayqûnatu l-3adhrâ''i maryam"}, {"text": "وَالِدَةُ الْإِلٰهِ", "translation": "la Mère de Dieu", "transliteration": "wâlidatu l-ilâh"}]'::jsonb, null, '{"id": "ar.d.adhra_maryam", "word": "الْعَذْرَاء مَرْيَم", "transliteration": "al-3adhrâ'' maryam", "translation": "la Vierge Marie", "partOfSpeech": "expression", "explanation": "الْعَذْرَاء (la vierge) accompagne le nom de Marie, مَرْيَم. La hamza finale se prononce : al-3adhrâ''. Les Coptes disent aussi السَّيِّدَة الْعَذْرَاء (Notre-Dame la Vierge) ou وَالِدَة الْإِلٰه (la Mère de Dieu).", "examples": [{"text": "أَيْقُونَةُ الْعَذْرَاءِ مَرْيَمَ", "translation": "l''icône de la Vierge Marie", "transliteration": "ayqûnatu l-3adhrâ''i maryam"}, {"text": "وَالِدَةُ الْإِلٰهِ", "translation": "la Mère de Dieu", "transliteration": "wâlidatu l-ilâh"}], "confusions": [{"word": "عَذَاب", "note": "3adhâb, le tourment : début semblable, mais pas de ء et un autre sens."}], "unitId": "ar.v.adhra_maryam"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.mar_marqus', 'ar', 'مَار مَرْقُس', 'saint Marc (l''évangéliste)', 'مَار est un titre de respect devant le nom d''un saint (« saint, seigneur »). مَرْقُس est Marc, l''évangéliste, fondateur de l''Église d''Alexandrie selon la tradition. Le ق se prononce au fond de la gorge ; en Égypte on entend « Mari Morqos ».', '[{"text": "كَنِيسَةُ مَارْ مَرْقُسَ", "translation": "l''église de saint Marc", "transliteration": "kanîsatu mâr marqusa"}, {"text": "مَارْ مَرْقُسُ كَاتِبُ الْإِنْجِيلِ", "translation": "saint Marc, auteur de l''Évangile", "transliteration": "mâr marqusu kâtibu l-indjîl"}]'::jsonb, null, '{"id": "ar.d.mar_marqus", "word": "مَار مَرْقُس", "transliteration": "mâr marqus", "translation": "saint Marc (l''évangéliste)", "partOfSpeech": "noun", "explanation": "مَار est un titre de respect devant le nom d''un saint (« saint, seigneur »). مَرْقُس est Marc, l''évangéliste, fondateur de l''Église d''Alexandrie selon la tradition. Le ق se prononce au fond de la gorge ; en Égypte on entend « Mari Morqos ».", "examples": [{"text": "كَنِيسَةُ مَارْ مَرْقُسَ", "translation": "l''église de saint Marc", "transliteration": "kanîsatu mâr marqusa"}, {"text": "مَارْ مَرْقُسُ كَاتِبُ الْإِنْجِيلِ", "translation": "saint Marc, auteur de l''Évangile", "transliteration": "mâr marqusu kâtibu l-indjîl"}], "unitId": "ar.v.mar_marqus"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.mar_girgis', 'ar', 'مَار جِرْجِس', 'saint Georges', 'مَار جِرْجِس est saint Georges, l''un des martyrs les plus aimés d''Égypte. Le ج se lit dj en arabe standard, mais g en Égypte : « Mari Girgis ». Deux syllabes à lire : djir-djis.', '[{"text": "كَنِيسَةُ مَارْ جِرْجِسَ", "translation": "l''église de saint Georges", "transliteration": "kanîsatu mâr djirdjisa"}, {"text": "مَارْ جِرْجِسُ قِدِّيسٌ", "translation": "Saint Georges est un saint.", "transliteration": "mâr djirdjisu qiddîs"}]'::jsonb, null, '{"id": "ar.d.mar_girgis", "word": "مَار جِرْجِس", "transliteration": "mâr djirdjis", "translation": "saint Georges", "partOfSpeech": "noun", "explanation": "مَار جِرْجِس est saint Georges, l''un des martyrs les plus aimés d''Égypte. Le ج se lit dj en arabe standard, mais g en Égypte : « Mari Girgis ». Deux syllabes à lire : djir-djis.", "examples": [{"text": "كَنِيسَةُ مَارْ جِرْجِسَ", "translation": "l''église de saint Georges", "transliteration": "kanîsatu mâr djirdjisa"}, {"text": "مَارْ جِرْجِسُ قِدِّيسٌ", "translation": "Saint Georges est un saint.", "transliteration": "mâr djirdjisu qiddîs"}], "confusions": [{"word": "مَار مَرْقُس", "note": "mâr marqus, saint Marc : un autre saint, avec le même titre مَار."}], "unitId": "ar.v.mar_girgis"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.baba', 'ar', 'الْبَابَا', 'le pape (patriarche d''Alexandrie)', 'الْبَابَا est le titre du chef de l''Église copte orthodoxe, le pape d''Alexandrie. Deux ا longs : bâ-bâ. On dit قَدَاسَة الْبَابَا, « Sa Sainteté le pape ».', '[{"text": "قَدَاسَةُ الْبَابَا", "translation": "Sa Sainteté le pape", "transliteration": "qadâsatu l-bâbâ"}, {"text": "الْبَابَا فِي الْكَنِيسَةِ", "translation": "Le pape est dans l''église.", "transliteration": "al-bâbâ fî l-kanîsa"}]'::jsonb, null, '{"id": "ar.d.baba", "word": "الْبَابَا", "transliteration": "al-bâbâ", "translation": "le pape (patriarche d''Alexandrie)", "partOfSpeech": "noun", "explanation": "الْبَابَا est le titre du chef de l''Église copte orthodoxe, le pape d''Alexandrie. Deux ا longs : bâ-bâ. On dit قَدَاسَة الْبَابَا, « Sa Sainteté le pape ».", "examples": [{"text": "قَدَاسَةُ الْبَابَا", "translation": "Sa Sainteté le pape", "transliteration": "qadâsatu l-bâbâ"}, {"text": "الْبَابَا فِي الْكَنِيسَةِ", "translation": "Le pape est dans l''église.", "transliteration": "al-bâbâ fî l-kanîsa"}], "confusions": [{"word": "بَابَا", "note": "bâbâ, « papa » en arabe familier : écrit pareil, mais sans ال, c''est le père de famille."}, {"word": "بَاب", "note": "bâb, la porte (leçon 1) : un seul ب et pas de ا final."}], "unitId": "ar.v.baba"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.usquf', 'ar', 'أُسْقُف', 'évêque', 'أُسْقُف est l''évêque. Devant son nom, on dit souvent الْأَنْبَا (al-anbâ), comme pour les moines. Le pluriel est أَسَاقِفَة (asâqifa).', '[{"text": "الْأُسْقُفُ وَالْكَاهِنُ", "translation": "l''évêque et le prêtre", "transliteration": "al-usqufu wa-l-kâhin"}, {"text": "الْأُسْقُفُ فِي الْهَيْكَلِ", "translation": "L''évêque est dans le sanctuaire.", "transliteration": "al-usqufu fî l-haykal"}]'::jsonb, null, '{"id": "ar.d.usquf", "word": "أُسْقُف", "transliteration": "usquf", "translation": "évêque", "partOfSpeech": "noun", "explanation": "أُسْقُف est l''évêque. Devant son nom, on dit souvent الْأَنْبَا (al-anbâ), comme pour les moines. Le pluriel est أَسَاقِفَة (asâqifa).", "examples": [{"text": "الْأُسْقُفُ وَالْكَاهِنُ", "translation": "l''évêque et le prêtre", "transliteration": "al-usqufu wa-l-kâhin"}, {"text": "الْأُسْقُفُ فِي الْهَيْكَلِ", "translation": "L''évêque est dans le sanctuaire.", "transliteration": "al-usqufu fî l-haykal"}], "forms": {"plural": "أَسَاقِفَة"}, "unitId": "ar.v.usquf"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.rahib', 'ar', 'رَاهِب', 'moine', 'رَاهِب est le moine, qui vit au monastère (دَيْر). Le ا est long : râ-hib. Le pluriel est رُهْبَان (ruhbân).', '[{"text": "الرَّاهِبُ فِي الدَّيْرِ", "translation": "Le moine est au monastère.", "transliteration": "ar-râhibu fî d-dayr"}, {"text": "رَاهِبٌ وَكَاهِنٌ", "translation": "un moine et un prêtre", "transliteration": "râhibun wa-kâhin"}]'::jsonb, null, '{"id": "ar.d.rahib", "word": "رَاهِب", "transliteration": "râhib", "translation": "moine", "partOfSpeech": "noun", "explanation": "رَاهِب est le moine, qui vit au monastère (دَيْر). Le ا est long : râ-hib. Le pluriel est رُهْبَان (ruhbân).", "examples": [{"text": "الرَّاهِبُ فِي الدَّيْرِ", "translation": "Le moine est au monastère.", "transliteration": "ar-râhibu fî d-dayr"}, {"text": "رَاهِبٌ وَكَاهِنٌ", "translation": "un moine et un prêtre", "transliteration": "râhibun wa-kâhin"}], "confusions": [{"word": "رَاعِي", "note": "râ3î, le berger (leçon 32) : un 3 à la place du h."}], "forms": {"plural": "رُهْبَان"}, "unitId": "ar.v.rahib"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.chammas', 'ar', 'شَمَّاس', 'diacre', 'شَمَّاس est le diacre : il assiste le prêtre à l''autel et conduit les réponses du peuple. Le م porte une chadda : cham-mâs. Avec ال, ش est solaire et le mot a deux chaddas : ach-chammâs. Pluriel : شَمَامِسَة.', '[{"text": "الشَّمَّاسُ فِي الْهَيْكَلِ", "translation": "Le diacre est dans le sanctuaire.", "transliteration": "ach-chammâsu fî l-haykal"}, {"text": "الشَّمَّاسُ وَالْكَاهِنُ", "translation": "le diacre et le prêtre", "transliteration": "ach-chammâsu wa-l-kâhin"}]'::jsonb, null, '{"id": "ar.d.chammas", "word": "شَمَّاس", "transliteration": "chammâs", "translation": "diacre", "partOfSpeech": "noun", "explanation": "شَمَّاس est le diacre : il assiste le prêtre à l''autel et conduit les réponses du peuple. Le م porte une chadda : cham-mâs. Avec ال, ش est solaire et le mot a deux chaddas : ach-chammâs. Pluriel : شَمَامِسَة.", "examples": [{"text": "الشَّمَّاسُ فِي الْهَيْكَلِ", "translation": "Le diacre est dans le sanctuaire.", "transliteration": "ach-chammâsu fî l-haykal"}, {"text": "الشَّمَّاسُ وَالْكَاهِنُ", "translation": "le diacre et le prêtre", "transliteration": "ach-chammâsu wa-l-kâhin"}], "confusions": [{"word": "شَمْس", "note": "chams, le soleil : pas de chadda sur le م et pas de ا."}], "forms": {"plural": "شَمَامِسَة"}, "unitId": "ar.v.chammas"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kahin', 'ar', 'كَاهِن', 'prêtre', 'كَاهِن est le prêtre ; c''est le mot des livres liturgiques (« الْكَاهِنُ : … » devant ce qu''il dit). Dans la vie courante, on dit أَبُونَا. Devant le nom, on trouve aussi الْقَسّ ou الْقُمُّص. Le ا est long : kâ-hin. Pluriel : كَهَنَة.', '[{"text": "أَبُونَا هُوَ الْكَاهِنُ", "translation": "Abouna est le prêtre.", "transliteration": "abûnâ huwa l-kâhin"}, {"text": "كَاهِنُ الْكَنِيسَةِ", "translation": "le prêtre de l''église", "transliteration": "kâhinu l-kanîsa"}]'::jsonb, null, '{"id": "ar.d.kahin", "word": "كَاهِن", "transliteration": "kâhin", "translation": "prêtre", "partOfSpeech": "noun", "explanation": "كَاهِن est le prêtre ; c''est le mot des livres liturgiques (« الْكَاهِنُ : … » devant ce qu''il dit). Dans la vie courante, on dit أَبُونَا. Devant le nom, on trouve aussi الْقَسّ ou الْقُمُّص. Le ا est long : kâ-hin. Pluriel : كَهَنَة.", "examples": [{"text": "أَبُونَا هُوَ الْكَاهِنُ", "translation": "Abouna est le prêtre.", "transliteration": "abûnâ huwa l-kâhin"}, {"text": "كَاهِنُ الْكَنِيسَةِ", "translation": "le prêtre de l''église", "transliteration": "kâhinu l-kanîsa"}], "confusions": [{"word": "كَاتِب", "note": "kâtib, l''écrivain, le scribe : kâ- au début aussi, mais autre racine."}], "forms": {"plural": "كَهَنَة"}, "unitId": "ar.v.kahin"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ya_rabb_irham', 'ar', 'يَا رَبُّ ارْحَمْ', 'Seigneur, aie pitié (Kyrie eleison)', 'C''est la réponse la plus fréquente de la liturgie, la traduction du grec Κύριε ἐλέησον (Kyrie eleison). يَا appelle (« ô »), رَبُّ est le Seigneur sans ال, et ارْحَمْ est un ordre : « aie pitié ! ». Après رَبُّ, le ا de ارْحَمْ ne se prononce pas : yâ rabbu r-7am. Le ح sans point est le 7 de la gorge. L''Église la répète de nombreuses fois, par exemple quand le diacre dit صَلُّوا.', '[{"text": "يَا رَبُّ ارْحَمْ", "translation": "Seigneur, aie pitié.", "transliteration": "yâ rabbu r-7am"}, {"text": "يَا رَبُّ ارْحَمْ، يَا رَبُّ ارْحَمْ", "translation": "Seigneur, aie pitié ; Seigneur, aie pitié.", "transliteration": "yâ rabbu r-7am, yâ rabbu r-7am"}]'::jsonb, null, '{"id": "ar.d.ya_rabb_irham", "word": "يَا رَبُّ ارْحَمْ", "transliteration": "yâ rabbu r-7am", "translation": "Seigneur, aie pitié (Kyrie eleison)", "partOfSpeech": "expression", "explanation": "C''est la réponse la plus fréquente de la liturgie, la traduction du grec Κύριε ἐλέησον (Kyrie eleison). يَا appelle (« ô »), رَبُّ est le Seigneur sans ال, et ارْحَمْ est un ordre : « aie pitié ! ». Après رَبُّ, le ا de ارْحَمْ ne se prononce pas : yâ rabbu r-7am. Le ح sans point est le 7 de la gorge. L''Église la répète de nombreuses fois, par exemple quand le diacre dit صَلُّوا.", "examples": [{"text": "يَا رَبُّ ارْحَمْ", "translation": "Seigneur, aie pitié.", "transliteration": "yâ rabbu r-7am"}, {"text": "يَا رَبُّ ارْحَمْ، يَا رَبُّ ارْحَمْ", "translation": "Seigneur, aie pitié ; Seigneur, aie pitié.", "transliteration": "yâ rabbu r-7am, yâ rabbu r-7am"}], "confusions": [{"word": "رَحْمَة", "note": "ra7ma, la miséricorde : même racine ر ح م, mais c''est un nom (« la pitié »), pas l''ordre ارْحَمْ."}], "unitId": "ar.v.ya_rabb_irham"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.amin', 'ar', 'آمِين', 'amen', 'آمِين (« ainsi soit-il ») ferme les prières : le prêtre la dit à la fin de ses oraisons et le peuple la reprend. Le آ est un alif madda (hamza + â long, leçon 14), puis م et ـِين : îne. On la trouve aussi à la fin du signe de la croix.', '[{"text": "بِاسْمِ الْآبِ وَالاِبْنِ وَالرُّوحِ الْقُدُسِ. آمِين", "translation": "Au nom du Père, du Fils et du Saint-Esprit. Amen.", "transliteration": "bismi l-âbi wa-l-ibni wa-r-rû7i l-qudus. âmîn"}, {"text": "آمِين يَا رَبُّ", "translation": "Amen, Seigneur.", "transliteration": "âmîn yâ rabb"}]'::jsonb, null, '{"id": "ar.d.amin", "word": "آمِين", "transliteration": "âmîn", "translation": "amen", "partOfSpeech": "interjection", "explanation": "آمِين (« ainsi soit-il ») ferme les prières : le prêtre la dit à la fin de ses oraisons et le peuple la reprend. Le آ est un alif madda (hamza + â long, leçon 14), puis م et ـِين : îne. On la trouve aussi à la fin du signe de la croix.", "examples": [{"text": "بِاسْمِ الْآبِ وَالاِبْنِ وَالرُّوحِ الْقُدُسِ. آمِين", "translation": "Au nom du Père, du Fils et du Saint-Esprit. Amen.", "transliteration": "bismi l-âbi wa-l-ibni wa-r-rû7i l-qudus. âmîn"}, {"text": "آمِين يَا رَبُّ", "translation": "Amen, Seigneur.", "transliteration": "âmîn yâ rabb"}], "confusions": [{"word": "أَمِين", "note": "amîn, digne de confiance (dit d''une personne) : un a bref au début, sans madda."}], "unitId": "ar.v.amin"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.al_madjd_lak', 'ar', 'الْمَجْدُ لَكَ يَا رَبُّ', 'Gloire à toi, Seigneur', 'Louange simple adressée au Seigneur. الْمَجْد = la gloire (م lunaire : al-madjd) ; لَكَ = لِ (à) + ـكَ (toi) ; يَا رَبُّ = ô Seigneur. Il n''y a pas de verbe : « Gloire à toi ». Lis le ك avec une fatha : laka.', '[{"text": "الْمَجْدُ لَكَ", "translation": "Gloire à toi.", "transliteration": "al-madjdu laka"}, {"text": "الْمَجْدُ لِلّٰهِ", "translation": "Gloire à Dieu.", "transliteration": "al-madjdu li-llâh"}]'::jsonb, null, '{"id": "ar.d.al_madjd_lak", "word": "الْمَجْدُ لَكَ يَا رَبُّ", "transliteration": "al-madjdu laka yâ rabb", "translation": "Gloire à toi, Seigneur", "partOfSpeech": "expression", "explanation": "Louange simple adressée au Seigneur. الْمَجْد = la gloire (م lunaire : al-madjd) ; لَكَ = لِ (à) + ـكَ (toi) ; يَا رَبُّ = ô Seigneur. Il n''y a pas de verbe : « Gloire à toi ». Lis le ك avec une fatha : laka.", "examples": [{"text": "الْمَجْدُ لَكَ", "translation": "Gloire à toi.", "transliteration": "al-madjdu laka"}, {"text": "الْمَجْدُ لِلّٰهِ", "translation": "Gloire à Dieu.", "transliteration": "al-madjdu li-llâh"}], "confusions": [{"word": "الْمَجِيد", "note": "al-madjîd, « le glorieux » (leçon 29) : même racine م ج د, avec un î long."}], "unitId": "ar.v.al_madjd_lak"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.as_salam_lil_kull', 'ar', 'السَّلَامُ لِلْكُلِّ', 'La paix soit à tous (salut du prêtre)', 'Salut du prêtre à l''assemblée, avant certaines prières. Le peuple répond وَلِرُوحِكَ أَيْضًا. السَّلَام (la paix, leçon 8) a un س solaire : as-salâm. لِلْكُلِّ = لِ (à) + الْكُلّ (tous, le tout) : le ا de ال tombe à l''écrit, d''où deux ل de suite (li-l-kull). Le ك porte une chadda : kull.', '[{"text": "الْكَاهِنُ: السَّلَامُ لِلْكُلِّ", "translation": "Le prêtre : La paix soit à tous.", "transliteration": "al-kâhinu: as-salâmu li-l-kull"}, {"text": "السَّلَامُ لِلْكَنِيسَةِ", "translation": "La paix à l''église.", "transliteration": "as-salâmu li-l-kanîsa"}]'::jsonb, null, '{"id": "ar.d.as_salam_lil_kull", "word": "السَّلَامُ لِلْكُلِّ", "transliteration": "as-salâmu li-l-kull", "translation": "La paix soit à tous (salut du prêtre)", "partOfSpeech": "expression", "explanation": "Salut du prêtre à l''assemblée, avant certaines prières. Le peuple répond وَلِرُوحِكَ أَيْضًا. السَّلَام (la paix, leçon 8) a un س solaire : as-salâm. لِلْكُلِّ = لِ (à) + الْكُلّ (tous, le tout) : le ا de ال tombe à l''écrit, d''où deux ل de suite (li-l-kull). Le ك porte une chadda : kull.", "examples": [{"text": "الْكَاهِنُ: السَّلَامُ لِلْكُلِّ", "translation": "Le prêtre : La paix soit à tous.", "transliteration": "al-kâhinu: as-salâmu li-l-kull"}, {"text": "السَّلَامُ لِلْكَنِيسَةِ", "translation": "La paix à l''église.", "transliteration": "as-salâmu li-l-kanîsa"}], "confusions": [{"word": "السَّلَامُ عَلَيْكُمْ", "note": "as-salâmu 3alaykum, « la paix sur vous » : salutation de tous les jours ; dans la liturgie, le prêtre dit لِلْكُلِّ, « à tous »."}], "unitId": "ar.v.as_salam_lil_kull"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.wa_li_ruhika', 'ar', 'وَلِرُوحِكَ أَيْضًا', 'Et à ton esprit aussi (réponse du peuple)', 'Réponse du peuple au salut السَّلَامُ لِلْكُلِّ. وَ (et) + لِ (à) + رُوحِ (esprit : ر damma, و long, ح = 7) + ـكَ (ton) + أَيْضًا (aussi : ay est une diphtongue, ض = D). Le tanwîn de أَيْضًا s''entend -an dans la phrase ; à la fin d''une phrase lue à la lettre, on entend plutôt -â (leçon 32). On entend aussi وَمَعَ رُوحِكَ (« et avec ton esprit ») dans d''autres traditions.', '[{"text": "السَّلَامُ لِلْكُلِّ. وَلِرُوحِكَ أَيْضًا", "translation": "La paix soit à tous. Et à ton esprit aussi.", "transliteration": "as-salâmu li-l-kull. wa-li-rû7ika ayDan"}, {"text": "وَلَكَ أَيْضًا", "translation": "Et à toi aussi.", "transliteration": "wa-laka ayDan"}]'::jsonb, null, '{"id": "ar.d.wa_li_ruhika", "word": "وَلِرُوحِكَ أَيْضًا", "transliteration": "wa-li-rû7ika ayDan", "translation": "Et à ton esprit aussi (réponse du peuple)", "partOfSpeech": "expression", "explanation": "Réponse du peuple au salut السَّلَامُ لِلْكُلِّ. وَ (et) + لِ (à) + رُوحِ (esprit : ر damma, و long, ح = 7) + ـكَ (ton) + أَيْضًا (aussi : ay est une diphtongue, ض = D). Le tanwîn de أَيْضًا s''entend -an dans la phrase ; à la fin d''une phrase lue à la lettre, on entend plutôt -â (leçon 32). On entend aussi وَمَعَ رُوحِكَ (« et avec ton esprit ») dans d''autres traditions.", "examples": [{"text": "السَّلَامُ لِلْكُلِّ. وَلِرُوحِكَ أَيْضًا", "translation": "La paix soit à tous. Et à ton esprit aussi.", "transliteration": "as-salâmu li-l-kull. wa-li-rû7ika ayDan"}, {"text": "وَلَكَ أَيْضًا", "translation": "Et à toi aussi.", "transliteration": "wa-laka ayDan"}], "confusions": [{"word": "وَمَعَ رُوحِكَ", "note": "wa-ma3a rû7ika, « et avec ton esprit » : variante de la même réponse, avec مَعَ (avec, leçon 22)."}], "unitId": "ar.v.wa_li_ruhika"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.abana', 'ar', 'أَبَانَا الَّذِي فِي السَّمَاوَاتِ', 'Notre Père qui es aux cieux', 'Début du Notre Père, la prière que l''Église récite à chaque office. أَبَانَا = أَب (père) + ـنَا (notre) : c''est la forme qu''on emploie en s''adressant à lui. الَّذِي = qui (leçon 23) ; فِي = dans ; السَّمَاوَات = les cieux (pluriel de سَمَاء), avec un س solaire : as-samâwât. Le a de ال tombe après الَّذِي et après فِي : lladhî fî s-samâwât.', '[{"text": "أَبَانَا الَّذِي فِي السَّمَاوَاتِ", "translation": "Notre Père qui es aux cieux.", "transliteration": "abâna lladhî fî s-samâwât"}, {"text": "رَبُّنَا فِي السَّمَاءِ", "translation": "Notre Seigneur est au ciel.", "transliteration": "rabbunâ fî s-samâ''"}]'::jsonb, null, '{"id": "ar.d.abana", "word": "أَبَانَا الَّذِي فِي السَّمَاوَاتِ", "transliteration": "abâna lladhî fî s-samâwât", "translation": "Notre Père qui es aux cieux", "partOfSpeech": "expression", "explanation": "Début du Notre Père, la prière que l''Église récite à chaque office. أَبَانَا = أَب (père) + ـنَا (notre) : c''est la forme qu''on emploie en s''adressant à lui. الَّذِي = qui (leçon 23) ; فِي = dans ; السَّمَاوَات = les cieux (pluriel de سَمَاء), avec un س solaire : as-samâwât. Le a de ال tombe après الَّذِي et après فِي : lladhî fî s-samâwât.", "examples": [{"text": "أَبَانَا الَّذِي فِي السَّمَاوَاتِ", "translation": "Notre Père qui es aux cieux.", "transliteration": "abâna lladhî fî s-samâwât"}, {"text": "رَبُّنَا فِي السَّمَاءِ", "translation": "Notre Seigneur est au ciel.", "transliteration": "rabbunâ fî s-samâ''"}], "confusions": [{"word": "أَبُونَا", "note": "abûnâ, « notre père » (leçon 26) : le mot qu''on emploie pour le prêtre ; ici la fin du mot change (û devient â) parce qu''on s''adresse à lui."}], "unitId": "ar.v.abana"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.quddus', 'ar', 'قُدُّوس', 'saint (dit de Dieu), « Agios »', 'قُدُّوس est le « Saint » : un titre réservé à Dieu, qu''on chante dans le Trisagion (« Agios ») et dans le triple « Saint, saint, saint » d''Ésaïe 6. La chadda double le د (qud-dûs) et le و est long. Ne le confonds pas avec قِدِّيس (qiddîs), un saint.', '[{"text": "اللّٰهُ قُدُّوسٌ", "translation": "Dieu est saint.", "transliteration": "Allâhu quddûs"}, {"text": "قُدُّوسٌ قُدُّوسٌ قُدُّوسٌ", "translation": "Saint, saint, saint.", "transliteration": "quddûsun quddûsun quddûs"}]'::jsonb, null, '{"id": "ar.d.quddus", "word": "قُدُّوس", "transliteration": "quddûs", "translation": "saint (dit de Dieu), « Agios »", "partOfSpeech": "adjective", "explanation": "قُدُّوس est le « Saint » : un titre réservé à Dieu, qu''on chante dans le Trisagion (« Agios ») et dans le triple « Saint, saint, saint » d''Ésaïe 6. La chadda double le د (qud-dûs) et le و est long. Ne le confonds pas avec قِدِّيس (qiddîs), un saint.", "examples": [{"text": "اللّٰهُ قُدُّوسٌ", "translation": "Dieu est saint.", "transliteration": "Allâhu quddûs"}, {"text": "قُدُّوسٌ قُدُّوسٌ قُدُّوسٌ", "translation": "Saint, saint, saint.", "transliteration": "quddûsun quddûsun quddûs"}], "confusions": [{"word": "قِدِّيس", "note": "qiddîs, un saint (leçon 30) : on le dit des saints ; قُدُّوس est réservé à Dieu."}], "unitId": "ar.v.quddus"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sallu', 'ar', 'صَلُّوا', 'priez !', 'Appel que le diacre lance à l''assemblée : « Priez ! ». C''est un verbe à l''impératif, au pluriel. Le ص est emphatique (S), le ل porte une chadda (Sal-lû) et le ا écrit après و est muet : Sallû, et non « Sallûâ ». Le nom de la prière est صَلَاة (Salâ).', '[{"text": "الشَّمَّاسُ: صَلُّوا", "translation": "Le diacre : Priez !", "transliteration": "ach-chammâsu: Sallû"}, {"text": "صَلُّوا فِي الْكَنِيسَةِ", "translation": "Priez dans l''église !", "transliteration": "Sallû fî l-kanîsa"}]'::jsonb, null, '{"id": "ar.d.sallu", "word": "صَلُّوا", "transliteration": "Sallû", "translation": "priez !", "partOfSpeech": "verb", "explanation": "Appel que le diacre lance à l''assemblée : « Priez ! ». C''est un verbe à l''impératif, au pluriel. Le ص est emphatique (S), le ل porte une chadda (Sal-lû) et le ا écrit après و est muet : Sallû, et non « Sallûâ ». Le nom de la prière est صَلَاة (Salâ).", "examples": [{"text": "الشَّمَّاسُ: صَلُّوا", "translation": "Le diacre : Priez !", "transliteration": "ach-chammâsu: Sallû"}, {"text": "صَلُّوا فِي الْكَنِيسَةِ", "translation": "Priez dans l''église !", "transliteration": "Sallû fî l-kanîsa"}], "confusions": [{"word": "صَلَاة", "note": "Salâ, la prière (nom) : même racine ص ل و, avec un â long au milieu et un ة à la fin."}], "forms": {"nom (la prière)": "صَلَاة"}, "unitId": "ar.v.sallu"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.halleluia', 'ar', 'هَلِّلُويَا', 'alléluia', 'L''alléluia vient de l''hébreu : « louez le Seigneur ». C''est le cri de joie de l''Église, très présent dans les chants de Pâques. L''orthographe varie selon les livres (هَلِّلُويَا, هَلِّيلُويَا) mais la lecture reste la même : hal-li-lû-yâ. La chadda double le ل ; ـُو est un û long et يَا est yâ.', '[{"text": "هَلِّلُويَا! الْمَسِيحُ قَامَ", "translation": "Alléluia ! Le Christ est ressuscité.", "transliteration": "hallilûyâ! al-masî7u qâm"}, {"text": "هَلِّلُويَا لِلرَّبِّ", "translation": "Alléluia au Seigneur.", "transliteration": "hallilûyâ li-r-rabb"}]'::jsonb, null, '{"id": "ar.d.halleluia", "word": "هَلِّلُويَا", "transliteration": "hallilûyâ", "translation": "alléluia", "partOfSpeech": "interjection", "explanation": "L''alléluia vient de l''hébreu : « louez le Seigneur ». C''est le cri de joie de l''Église, très présent dans les chants de Pâques. L''orthographe varie selon les livres (هَلِّلُويَا, هَلِّيلُويَا) mais la lecture reste la même : hal-li-lû-yâ. La chadda double le ل ; ـُو est un û long et يَا est yâ.", "examples": [{"text": "هَلِّلُويَا! الْمَسِيحُ قَامَ", "translation": "Alléluia ! Le Christ est ressuscité.", "transliteration": "hallilûyâ! al-masî7u qâm"}, {"text": "هَلِّلُويَا لِلرَّبِّ", "translation": "Alléluia au Seigneur.", "transliteration": "hallilûyâ li-r-rabb"}], "confusions": [{"word": "آمِين", "note": "âmîn, amen : l''autre mot que le peuple reprend souvent ; il ferme la prière, l''alléluia la célèbre."}], "unitId": "ar.v.halleluia"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ajbiyya', 'ar', 'الْأَجْبِيَّة', 'l''Agpeya, le livre des heures (les sept prières)', 'الْأَجْبِيَّة (écrit aussi Agbeya) est le livre des heures des Coptes : les sept prières du jour et de la nuit. On l''appelle aussi كِتَاب السَّبْع صَلَوَات, « le livre des sept prières ». La chadda double le ي : adj-biy-ya. En Égypte, le ج se dit g : « el-agbeya ».', '[{"text": "الْأَجْبِيَّةُ كِتَابُ الصَّلَاةِ", "translation": "L''Agpeya est le livre de la prière.", "transliteration": "al-adjbiyyatu kitâbu S-Salâ"}, {"text": "الْأَجْبِيَّةُ فِي الْكَنِيسَةِ وَفِي الْبَيْتِ", "translation": "L''Agpeya est dans l''église et dans la maison.", "transliteration": "al-adjbiyyatu fî l-kanîsa wa-fî l-bayt"}]'::jsonb, null, '{"id": "ar.d.ajbiyya", "word": "الْأَجْبِيَّة", "transliteration": "al-adjbiyya", "translation": "l''Agpeya, le livre des heures (les sept prières)", "partOfSpeech": "noun", "explanation": "الْأَجْبِيَّة (écrit aussi Agbeya) est le livre des heures des Coptes : les sept prières du jour et de la nuit. On l''appelle aussi كِتَاب السَّبْع صَلَوَات, « le livre des sept prières ». La chadda double le ي : adj-biy-ya. En Égypte, le ج se dit g : « el-agbeya ».", "examples": [{"text": "الْأَجْبِيَّةُ كِتَابُ الصَّلَاةِ", "translation": "L''Agpeya est le livre de la prière.", "transliteration": "al-adjbiyyatu kitâbu S-Salâ"}, {"text": "الْأَجْبِيَّةُ فِي الْكَنِيسَةِ وَفِي الْبَيْتِ", "translation": "L''Agpeya est dans l''église et dans la maison.", "transliteration": "al-adjbiyyatu fî l-kanîsa wa-fî l-bayt"}], "confusions": [{"word": "كِتَاب", "note": "kitâb, un livre (leçon 1) : l''Agpeya est un livre précis, le livre des heures."}], "unitId": "ar.v.ajbiyya"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.mahabba', 'ar', 'مَحَبَّة', 'amour (l''amour de Dieu, la charité)', 'مَحَبَّة est l''amour, surtout celui de Dieu pour les hommes et celui des chrétiens entre eux : « Dieu est amour » (1 Jean 4:8). Elle vient de la racine ح ب ب, comme حَبِيب (leçon 3). Le ب porte une chadda : ma-7ab-ba. Le ة se lit a en fin de phrase et at(un) au milieu.', '[{"text": "اللّٰهُ مَحَبَّةٌ", "translation": "Dieu est amour.", "transliteration": "Allâhu ma7abba"}, {"text": "مَحَبَّةُ اللّٰهِ", "translation": "l''amour de Dieu", "transliteration": "ma7abbatu llâh"}]'::jsonb, null, '{"id": "ar.d.mahabba", "word": "مَحَبَّة", "transliteration": "ma7abba", "translation": "amour (l''amour de Dieu, la charité)", "partOfSpeech": "noun", "explanation": "مَحَبَّة est l''amour, surtout celui de Dieu pour les hommes et celui des chrétiens entre eux : « Dieu est amour » (1 Jean 4:8). Elle vient de la racine ح ب ب, comme حَبِيب (leçon 3). Le ب porte une chadda : ma-7ab-ba. Le ة se lit a en fin de phrase et at(un) au milieu.", "examples": [{"text": "اللّٰهُ مَحَبَّةٌ", "translation": "Dieu est amour.", "transliteration": "Allâhu ma7abba"}, {"text": "مَحَبَّةُ اللّٰهِ", "translation": "l''amour de Dieu", "transliteration": "ma7abbatu llâh"}], "confusions": [{"word": "حَبِيب", "note": "7abîb, le chéri (leçon 3) : même racine ح ب ب, mais c''est une personne aimée, pas le nom de l''amour."}], "unitId": "ar.v.mahabba"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.rai', 'ar', 'الرَّاعِي', 'le berger', 'الرَّاعِي est le berger, image du Christ, « le bon berger » (Jean 10). ر est solaire : l''article donne ar-, avec une chadda sur le ر. Puis ا long, ع (3) et ـِي : î long. L''Église donne aussi ce nom à ceux qui prennent soin du peuple : le prêtre, l''évêque.', '[{"text": "الرَّاعِي فِي الْجَبَلِ", "translation": "Le berger est dans la montagne.", "transliteration": "ar-râ3î fî l-djabal"}, {"text": "يَسُوعُ هُوَ الرَّاعِي", "translation": "Jésus est le berger.", "transliteration": "yasû3u huwa r-râ3î"}]'::jsonb, null, '{"id": "ar.d.rai", "word": "الرَّاعِي", "transliteration": "ar-râ3î", "translation": "le berger", "partOfSpeech": "noun", "explanation": "الرَّاعِي est le berger, image du Christ, « le bon berger » (Jean 10). ر est solaire : l''article donne ar-, avec une chadda sur le ر. Puis ا long, ع (3) et ـِي : î long. L''Église donne aussi ce nom à ceux qui prennent soin du peuple : le prêtre, l''évêque.", "examples": [{"text": "الرَّاعِي فِي الْجَبَلِ", "translation": "Le berger est dans la montagne.", "transliteration": "ar-râ3î fî l-djabal"}, {"text": "يَسُوعُ هُوَ الرَّاعِي", "translation": "Jésus est le berger.", "transliteration": "yasû3u huwa r-râ3î"}], "confusions": [{"word": "رَاهِب", "note": "râhib, le moine (leçon 30) : même début رَا, mais ce mot finit par ب."}], "unitId": "ar.v.rai"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.salih', 'ar', 'صَالِح', 'bon (le bon berger)', 'صَالِح veut dire « bon, juste, pieux ». Comme tout adjectif (leçon 28), il se place après le nom : الرَّاعِي الصَّالِح, « le bon berger ». Avec ال, ص est solaire : aS-Sâli7. Le ص est emphatique (S) et le ح sans point se note 7.', '[{"text": "أَنَا هُوَ الرَّاعِي الصَّالِحُ", "translation": "Je suis le bon berger (Jean 10:11).", "transliteration": "ana huwa r-râ3î S-Sâli7u"}, {"text": "رَجُلٌ صَالِحٌ", "translation": "un homme bon", "transliteration": "radjulun Sâli7"}]'::jsonb, null, '{"id": "ar.d.salih", "word": "صَالِح", "transliteration": "Sâli7", "translation": "bon (le bon berger)", "partOfSpeech": "adjective", "explanation": "صَالِح veut dire « bon, juste, pieux ». Comme tout adjectif (leçon 28), il se place après le nom : الرَّاعِي الصَّالِح, « le bon berger ». Avec ال, ص est solaire : aS-Sâli7. Le ص est emphatique (S) et le ح sans point se note 7.", "examples": [{"text": "أَنَا هُوَ الرَّاعِي الصَّالِحُ", "translation": "Je suis le bon berger (Jean 10:11).", "transliteration": "ana huwa r-râ3î S-Sâli7u"}, {"text": "رَجُلٌ صَالِحٌ", "translation": "un homme bon", "transliteration": "radjulun Sâli7"}], "confusions": [{"word": "صَبَاح", "note": "Sabâ7, le matin (leçon 20) : même début صَ, mais la deuxième lettre est ب."}], "unitId": "ar.v.salih"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.nur', 'ar', 'نُور', 'lumière', 'نُور est la lumière. Dans l''Évangile, le Christ dit : « Je suis la lumière du monde » (Jean 8:12), et saint Jean écrit : « Dieu est lumière » (1 Jean 1:5). Le و après la damma est long : nûr. En annexion, il garde sa damma : نُورُ الْعَالَمِ.', '[{"text": "اللّٰهُ نُورٌ", "translation": "Dieu est lumière.", "transliteration": "Allâhu nûr"}, {"text": "أَنَا هُوَ نُورُ الْعَالَمِ", "translation": "Je suis la lumière du monde.", "transliteration": "ana huwa nûru l-3âlam"}]'::jsonb, null, '{"id": "ar.d.nur", "word": "نُور", "transliteration": "nûr", "translation": "lumière", "partOfSpeech": "noun", "explanation": "نُور est la lumière. Dans l''Évangile, le Christ dit : « Je suis la lumière du monde » (Jean 8:12), et saint Jean écrit : « Dieu est lumière » (1 Jean 1:5). Le و après la damma est long : nûr. En annexion, il garde sa damma : نُورُ الْعَالَمِ.", "examples": [{"text": "اللّٰهُ نُورٌ", "translation": "Dieu est lumière.", "transliteration": "Allâhu nûr"}, {"text": "أَنَا هُوَ نُورُ الْعَالَمِ", "translation": "Je suis la lumière du monde.", "transliteration": "ana huwa nûru l-3âlam"}], "confusions": [{"word": "نَار", "note": "nâr, le feu : mêmes consonnes ن et ر, mais un ا long à la place du و."}], "unitId": "ar.v.nur"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.tariq', 'ar', 'طَرِيق', 'chemin', 'طَرِيق est le chemin, la route. Le Christ dit : « Je suis le chemin » (Jean 14:6). Le ط est emphatique (T) ; avec l''article, c''est une lettre solaire : aT-Tarîq. Le ي après la kasra est long : Ta-rîq.', '[{"text": "أَنَا هُوَ الطَّرِيقُ", "translation": "Je suis le chemin.", "transliteration": "ana huwa T-Tarîq"}, {"text": "طَرِيقٌ جَدِيدٌ", "translation": "un chemin nouveau", "transliteration": "Tarîqun djadîd"}]'::jsonb, null, '{"id": "ar.d.tariq", "word": "طَرِيق", "transliteration": "Tarîq", "translation": "chemin", "partOfSpeech": "noun", "explanation": "طَرِيق est le chemin, la route. Le Christ dit : « Je suis le chemin » (Jean 14:6). Le ط est emphatique (T) ; avec l''article, c''est une lettre solaire : aT-Tarîq. Le ي après la kasra est long : Ta-rîq.", "examples": [{"text": "أَنَا هُوَ الطَّرِيقُ", "translation": "Je suis le chemin.", "transliteration": "ana huwa T-Tarîq"}, {"text": "طَرِيقٌ جَدِيدٌ", "translation": "un chemin nouveau", "transliteration": "Tarîqun djadîd"}], "confusions": [{"word": "طَرِيقَة", "note": "Tarîqa, la manière de faire : le même mot avec un ة et un autre sens."}], "unitId": "ar.v.tariq"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.haqq', 'ar', 'حَقّ', 'vérité', 'حَقّ veut dire « vérité », mais aussi « droit, juste ». Le ح sans point est le 7 de la gorge et la chadda double le ق : 7aqq. Avec ال, c''est un nom lunaire : الْحَقّ, al-7aqq, « la Vérité », un des noms que le Christ se donne (Jean 14:6).', '[{"text": "أَنَا هُوَ الْحَقُّ", "translation": "Je suis la vérité.", "transliteration": "ana huwa l-7aqq"}, {"text": "الْحَقُّ جَمِيلٌ", "translation": "La vérité est belle.", "transliteration": "al-7aqqu djamîl"}]'::jsonb, null, '{"id": "ar.d.haqq", "word": "حَقّ", "transliteration": "7aqq", "translation": "vérité", "partOfSpeech": "noun", "explanation": "حَقّ veut dire « vérité », mais aussi « droit, juste ». Le ح sans point est le 7 de la gorge et la chadda double le ق : 7aqq. Avec ال, c''est un nom lunaire : الْحَقّ, al-7aqq, « la Vérité », un des noms que le Christ se donne (Jean 14:6).", "examples": [{"text": "أَنَا هُوَ الْحَقُّ", "translation": "Je suis la vérité.", "transliteration": "ana huwa l-7aqq"}, {"text": "الْحَقُّ جَمِيلٌ", "translation": "La vérité est belle.", "transliteration": "al-7aqqu djamîl"}], "confusions": [{"word": "حَارّ", "note": "7ârr, chaud (leçon 19) : commence aussi par ح et finit par une lettre doublée, mais avec un ا long."}], "unitId": "ar.v.haqq"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.hayat', 'ar', 'حَيَاة', 'vie', 'حَيَاة est la vie. Le Christ dit : « Je suis… la vie » (Jean 14:6). La vie éternelle se dit حَيَاة أَبَدِيَّة. Le ة se lit t si un autre mot suit (7ayâtu l-kanîsa) ; à la pause, il ne s''entend plus : 7ayâ.', '[{"text": "أَنَا هُوَ الْحَيَاةُ", "translation": "Je suis la vie.", "transliteration": "ana huwa l-7ayâ"}, {"text": "حَيَاةُ الْكَنِيسَةِ", "translation": "la vie de l''église", "transliteration": "7ayâtu l-kanîsa"}]'::jsonb, null, '{"id": "ar.d.hayat", "word": "حَيَاة", "transliteration": "7ayâ", "translation": "vie", "partOfSpeech": "noun", "explanation": "حَيَاة est la vie. Le Christ dit : « Je suis… la vie » (Jean 14:6). La vie éternelle se dit حَيَاة أَبَدِيَّة. Le ة se lit t si un autre mot suit (7ayâtu l-kanîsa) ; à la pause, il ne s''entend plus : 7ayâ.", "examples": [{"text": "أَنَا هُوَ الْحَيَاةُ", "translation": "Je suis la vie.", "transliteration": "ana huwa l-7ayâ"}, {"text": "حَيَاةُ الْكَنِيسَةِ", "translation": "la vie de l''église", "transliteration": "7ayâtu l-kanîsa"}], "confusions": [{"word": "حَيّ", "note": "7ayy, vivant : même racine ح ي ي, avec une chadda sur le ي et sans ا long."}], "unitId": "ar.v.hayat"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kalima', 'ar', 'كَلِمَة', 'parole ; le Verbe (Jean 1)', 'كَلِمَة est un mot, une parole. Avec ال et une majuscule en français, الْكَلِمَة est le Verbe, le Christ : « Au commencement était le Verbe » (Jean 1:1). Le pluriel est كَلِمَات. Le ة se lit a en fin de phrase.', '[{"text": "كَلِمَةُ اللّٰهِ", "translation": "la parole de Dieu, le Verbe de Dieu", "transliteration": "kalimatu llâh"}, {"text": "كَلِمَةٌ جَمِيلَةٌ", "translation": "une belle parole", "transliteration": "kalimatun djamîla"}]'::jsonb, null, '{"id": "ar.d.kalima", "word": "كَلِمَة", "transliteration": "kalima", "translation": "parole ; le Verbe (Jean 1)", "partOfSpeech": "noun", "explanation": "كَلِمَة est un mot, une parole. Avec ال et une majuscule en français, الْكَلِمَة est le Verbe, le Christ : « Au commencement était le Verbe » (Jean 1:1). Le pluriel est كَلِمَات. Le ة se lit a en fin de phrase.", "examples": [{"text": "كَلِمَةُ اللّٰهِ", "translation": "la parole de Dieu, le Verbe de Dieu", "transliteration": "kalimatu llâh"}, {"text": "كَلِمَةٌ جَمِيلَةٌ", "translation": "une belle parole", "transliteration": "kalimatun djamîla"}], "confusions": [{"word": "كَلَام", "note": "kalâm, le discours, la parole en général : même racine ك ل م, avec un ا long au milieu."}], "forms": {"plural": "كَلِمَات"}, "unitId": "ar.v.kalima"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.alam', 'ar', 'عَالَم', 'monde', 'عَالَم est le monde, l''univers. Le Christ est « la lumière du monde » : نُورُ الْعَالَمِ. Le ع (3) est suivi d''un ا long : 3â-lam. Fais attention aux mots proches, comme عِلْم (science) et عَلَم (drapeau).', '[{"text": "نُورُ الْعَالَمِ", "translation": "la lumière du monde", "transliteration": "nûru l-3âlam"}, {"text": "الْكَنِيسَةُ فِي الْعَالَمِ", "translation": "L''Église est dans le monde.", "transliteration": "al-kanîsatu fî l-3âlam"}]'::jsonb, null, '{"id": "ar.d.alam", "word": "عَالَم", "transliteration": "3âlam", "translation": "monde", "partOfSpeech": "noun", "explanation": "عَالَم est le monde, l''univers. Le Christ est « la lumière du monde » : نُورُ الْعَالَمِ. Le ع (3) est suivi d''un ا long : 3â-lam. Fais attention aux mots proches, comme عِلْم (science) et عَلَم (drapeau).", "examples": [{"text": "نُورُ الْعَالَمِ", "translation": "la lumière du monde", "transliteration": "nûru l-3âlam"}, {"text": "الْكَنِيسَةُ فِي الْعَالَمِ", "translation": "L''Église est dans le monde.", "transliteration": "al-kanîsatu fî l-3âlam"}], "confusions": [{"word": "عِلْم", "note": "3ilm, la science : mêmes consonnes ع ل م, mais voyelles brèves et pas de ا."}], "unitId": "ar.v.alam"}'::jsonb, '2026.10.22') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
